<script lang="ts">
  import type {
    MiltankFarmUiSnapshot,
    MiltankGuardianCandidateSnapshot,
  } from '../bus/snapshots.js';
  import { portalToBody } from '../lib/portalToBody.ts';
  import { miltankFarmTooltipHandlers } from '../ui/scheduleTooltipHelpers.ts';

  interface Props {
    pastureUid: string;
    pastureName: string;
    candidates: MiltankGuardianCandidateSnapshot[];
    hasGuardian: boolean;
    guardianName: string | null;
    guardianSpriteUrl: string | null;
    ui: MiltankFarmUiSnapshot;
    placement?: 'top' | 'bottom';
    mode?: 'assign' | 'combat';
    threatId?: string | null;
    open?: boolean;
    onClose?: () => void;
  }

  let {
    pastureUid,
    pastureName,
    candidates,
    hasGuardian,
    guardianName,
    guardianSpriteUrl,
    ui,
    placement = 'top',
    mode = 'assign',
    threatId = null,
    open = false,
    onClose,
  }: Props = $props();
  let localOpen = $state(false);
  let openPicker = $derived(mode === 'combat' ? !!open : localOpen);
  let anchorEl: HTMLButtonElement | undefined = $state();
  let popoverEl: HTMLDivElement | undefined = $state();
  let anchorRect = $state<DOMRect | null>(null);

  const POPOVER_GAP = 8;
  const POPOVER_MIN_WIDTH = 220;

  function openPickerPanel() {
    if (candidates.length === 0) return;
    if (anchorEl) anchorRect = anchorEl.getBoundingClientRect();
    localOpen = true;
  }

  function closePicker() {
    if (mode === 'combat') {
      onClose?.();
      return;
    }
    localOpen = false;
  }

  function combatEngageArg(candidate: MiltankGuardianCandidateSnapshot): string {
    return `${threatId ?? ''}|${candidate.source}|${candidate.index}`;
  }

  function togglePicker() {
    if (openPicker) closePicker();
    else openPickerPanel();
  }

  function positionPopover(node: HTMLDivElement, rect: DOMRect) {
    const height = node.offsetHeight || 120;
    const width = Math.max(POPOVER_MIN_WIDTH, node.offsetWidth || 240);
    let left = rect.left + rect.width / 2 - width / 2;
    let top = placement === 'bottom'
      ? rect.bottom + POPOVER_GAP
      : rect.top - height - POPOVER_GAP;
    if (left + width > window.innerWidth - 8) left = window.innerWidth - width - 8;
    if (left < 8) left = 8;
    if (top < 8) top = 8;
    if (top + height > window.innerHeight - 8) {
      top = placement === 'bottom'
        ? rect.top - height - POPOVER_GAP
        : rect.bottom + POPOVER_GAP;
    }
    node.style.left = `${left}px`;
    node.style.top = `${top}px`;
    node.style.minWidth = `${POPOVER_MIN_WIDTH}px`;
  }

  $effect(() => {
    if (mode === 'combat' && open && !anchorRect) {
      anchorRect = {
        left: window.innerWidth / 2,
        top: window.innerHeight * 0.38,
        width: 0,
        height: 0,
        right: window.innerWidth / 2,
        bottom: window.innerHeight * 0.38,
        x: window.innerWidth / 2,
        y: window.innerHeight * 0.38,
        toJSON: () => ({}),
      } as DOMRect;
    }
  });

  $effect(() => {
    if (!openPicker) return;
    const rect = anchorRect;
    const node = popoverEl;
    if (!node || !rect) return;
    positionPopover(node, rect);
    const onResize = () => positionPopover(node, rect);
    window.addEventListener('resize', onResize);
    return () => window.removeEventListener('resize', onResize);
  });

  $effect(() => {
    if (!openPicker) return;
    candidates;
    const rect = anchorRect;
    const node = popoverEl;
    if (!node || !rect) return;
    requestAnimationFrame(() => positionPopover(node, rect));
  });

  $effect(() => {
    if (!openPicker) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') closePicker();
    };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  });

  $effect(() => {
    if (hasGuardian && openPicker) closePicker();
  });
</script>

{#snippet candidateTileBody(candidate: MiltankGuardianCandidateSnapshot, showCombatStats = false)}
  <img
    class="miltank-guardian-tile-sprite"
    src={candidate.spriteUrl}
    alt=""
    width="37"
    height="37"
  />
  <span class="miltank-guardian-tile-name">
    {candidate.name}{candidate.shiny ? ' ✨' : ''}
  </span>
  {#if showCombatStats}
    <span class="miltank-guardian-tile-strength" title="P{candidate.prestige} · Lv.{candidate.level}">
      P{candidate.prestige} · Lv.{candidate.level}
    </span>
  {:else}
    <span class="miltank-guardian-tile-meta">{candidate.sourceLabel}</span>
  {/if}
{/snippet}

{#if mode === 'assign'}
<div class="miltank-guardian-picker-anchor">
  {#if hasGuardian}
    <span class="miltank-guardian-assigned">
      {#if guardianSpriteUrl}
        <img
          class="miltank-guardian-assigned-sprite"
          src={guardianSpriteUrl}
          alt=""
          width="25"
          height="25"
        />
      {/if}
      <span
        class="miltank-guardian-assigned-name miltank-farm-tooltip-host"
        data-tooltip-variant="miltank-farm"
        data-tooltip-placement="left"
        {...miltankFarmTooltipHandlers(() => ({
          title: ui.guardianTitle,
          body: ui.guardianAssignedRoleTooltip,
        }))}
      >{guardianName}</span>
    </span>
    <button
      type="button"
      class="miltank-farm-btn miltank-farm-btn--chip miltank-farm-btn--guardian"
      data-action="unassignGuardianFromPasture"
      data-arg={pastureUid}
    >{ui.guardianUnassignBtn}</button>
  {:else if candidates.length > 0}
    <button
      type="button"
      class="miltank-farm-btn miltank-farm-btn--chip miltank-farm-btn--guardian"
      class:is-open={openPicker}
      bind:this={anchorEl}
      onclick={togglePicker}
      aria-expanded={openPicker}
      aria-haspopup="dialog"
    >{ui.guardianAssignBtn}</button>
  {:else}
    <span
      class="miltank-farm-guardian-empty miltank-farm-tooltip-host"
      data-tooltip-variant="miltank-farm"
      {...miltankFarmTooltipHandlers(() => ({ title: '', body: ui.guardianNoCandidates }))}
    >
      {ui.guardianNoCandidates}
    </span>
  {/if}
</div>
{/if}

{#if openPicker}
  <div class="miltank-guardian-popover-portal" use:portalToBody>
    <!-- svelte-ignore a11y_no_static_element_interactions -->
    <div
      class="miltank-guardian-popover-overlay"
      role="presentation"
      onpointerdown={(e) => {
        e.preventDefault();
        closePicker();
      }}
    ></div>

    {#if candidates.length > 0}
    <div
      class="miltank-guardian-popover"
      class:placement-bottom={placement === 'bottom'}
      bind:this={popoverEl}
      role="dialog"
      tabindex="-1"
      aria-label="{mode === 'combat' ? ui.threatCombatPickTitle : ui.guardianPickTitle} — {pastureName}"
      onpointerdown={(e) => e.stopPropagation()}
      onkeydown={(e) => e.stopPropagation()}
    >
      <div class="miltank-guardian-popover-header">
        <span class="miltank-guardian-popover-title">{mode === 'combat' ? ui.threatCombatPickTitle : ui.guardianPickTitle}</span>
        <span class="miltank-guardian-popover-subtitle">{pastureName}</span>
        <button
          type="button"
          class="miltank-guardian-popover-close"
          onclick={closePicker}
          aria-label="Close"
        >×</button>
      </div>

      <div class="miltank-guardian-popover-grid" role="listbox">
        {#each candidates as candidate (candidate.uid)}
          {#if mode === 'combat'}
            <button
              type="button"
              class="miltank-guardian-tile miltank-guardian-tile--combat"
              role="option"
              aria-selected="false"
              data-action="engageFarmThreatCombat"
              data-arg={combatEngageArg(candidate)}
            >
              {@render candidateTileBody(candidate, true)}
            </button>
          {:else}
            <button
              type="button"
              class="miltank-guardian-tile"
              role="option"
              aria-selected="false"
              data-action="assignGuardianToPasture"
              data-arg={`${candidate.pastureUid}:${candidate.source}:${candidate.index}`}
              onclick={closePicker}
            >
              {@render candidateTileBody(candidate)}
            </button>
          {/if}
        {/each}
      </div>
    </div>
    {:else if mode === 'combat'}
    <div
      class="miltank-guardian-popover miltank-guardian-popover--empty"
      class:placement-bottom={placement === 'bottom'}
      bind:this={popoverEl}
      role="dialog"
      tabindex="-1"
      aria-label={ui.threatCombatPickTitle}
      onpointerdown={(e) => e.stopPropagation()}
    >
      <div class="miltank-guardian-popover-header">
        <span class="miltank-guardian-popover-title">{ui.threatCombatPickTitle}</span>
        <button
          type="button"
          class="miltank-guardian-popover-close"
          onclick={closePicker}
          aria-label="Close"
        >×</button>
      </div>
      <p class="miltank-guardian-popover-empty">{ui.guardianNoCandidates}</p>
    </div>
    {/if}
  </div>
{/if}
