const SINNOH_ENDGAME_INSERT_ZONE_IDS = [349, 350, 351, 352, 353] as const;

type ZoneProgressLike = {
    pokemonTiers?: Record<string, number>;
    bossesDefeated?: number;
    epicsDefeated?: number;
};

/** Grandfather endgame insert zones for saves that already cleared VR / League. */
export function migrateSinnohZonesLayoutV2(data: {
    sinnohZonesLayoutV2?: boolean;
    zoneProgress?: Record<string, ZoneProgressLike>;
}): void {
    if (data.sinnohZonesLayoutV2 === true) return;

    const zoneProgress = data.zoneProgress;
    const passedEndgame = zoneProgress && (zoneProgress['344'] || zoneProgress['345']);
    if (passedEndgame && zoneProgress) {
        const zonesTable = ZONES as Record<number, {
            maxTier?: number;
            requiredBosses?: number;
            requiredEpics?: number;
        }>;
        for (const zoneId of SINNOH_ENDGAME_INSERT_ZONE_IDS) {
            const zone = zonesTable[zoneId];
            if (!zone) continue;
            const key = String(zoneId);
            const existing = zoneProgress[key] || {};
            const tiers: Record<string, number> = { ...(existing.pokemonTiers || {}) };
            const maxTier = Number(zone.maxTier) || 50;
            const pool = SINNOH_ZONE_POKEMON[zoneId] || [];
            for (const entry of pool) {
                if (entry.excludeFromZoneMastery) continue;
                tiers[entry.name] = maxTier;
            }
            zoneProgress[key] = {
                ...existing,
                pokemonTiers: tiers,
                bossesDefeated: Math.max(Number(existing.bossesDefeated) || 0, Number(zone.requiredBosses) || 0),
                epicsDefeated: Math.max(Number(existing.epicsDefeated) || 0, Number(zone.requiredEpics) || 0),
            };
        }
    }

    data.sinnohZonesLayoutV2 = true;
}

const HEARTHOME_HUB_ZONE_ID = 322;
const ROUTE_208_ZONE_ID = 321;
const ROUTE_209_ZONE_ID = 323;

/** Remove legacy Hearthome hub (322); arena zone 335 is the only Hearthome entry. */
export function migrateSinnohRemoveHearthomeHub(data: {
    sinnohHearthomeHubRemoved?: boolean;
    currentZone?: number;
    maxReachedZone?: number;
    maxReachedZoneByRegion?: Record<string, number>;
    zoneProgress?: Record<string, ZoneProgressLike>;
}): void {
    if (data.sinnohHearthomeHubRemoved === true) return;

    if (data.zoneProgress?.['322']) {
        delete data.zoneProgress['322'];
    }

    if (data.maxReachedZoneByRegion?.sinnoh === HEARTHOME_HUB_ZONE_ID) {
        data.maxReachedZoneByRegion.sinnoh = ROUTE_208_ZONE_ID;
    }

    if (data.maxReachedZone === HEARTHOME_HUB_ZONE_ID) {
        data.maxReachedZone = ROUTE_208_ZONE_ID;
    }

    if (data.currentZone === HEARTHOME_HUB_ZONE_ID) {
        const beyondHub = Number(data.maxReachedZoneByRegion?.sinnoh) >= ROUTE_209_ZONE_ID
            || !!data.zoneProgress?.['323'];
        data.currentZone = beyondHub ? ROUTE_209_ZONE_ID : ROUTE_208_ZONE_ID;
    }

    data.sinnohHearthomeHubRemoved = true;
}

