<script lang="ts">
  import { onMount } from 'svelte';
  import { facade } from '../bus/gameFacade.js';
  import { game } from '../../gameManager.js';
  import { dailyLogin } from '../stores/dailyLogin.svelte.ts';
  import { uiText } from '../ui/i18n.ts';
  import { useGameLanguageTick } from '../lib/useGameLanguageTick.svelte.ts';
  import type { PromoRedeemResult } from '../../promoCodeSystem.ts';
  import { SAVE_BOOT_DISCORD_URL, SAVE_BOOT_REDDIT_URL } from '../../saveSystem.ts';
  import { formatRelativeTimeAgo } from '../../formatters.ts';

  const { trackGameLanguage } = useGameLanguageTick();

  let loginSnap = $derived(dailyLogin.snapshot);

  function menuT(key: string, fallback: string): string {
    trackGameLanguage();
    return uiText(key, fallback, {}, game);
  }

  let dailyLoginBadgeTip = $derived(menuT('dailyLogin.headerBadgeTitle', 'Daily login'));
  let titleLabel = $derived(
    `${menuT('menu.open', 'MENU')} - ${menuT('modal.saveManagerTitle', 'Main menu')}`,
  );
  let statsBtnLabel = $derived(menuT('modal.saveManagerStats', 'Stats'));
  let bonusBtnLabel = $derived(menuT('modal.saveManagerBonus', 'Bonuses'));
  let journalBtnLabel = $derived(menuT('modal.saveManagerJournal', 'Log'));
  let profChenMenuButtonLabel = $derived(menuT('modal.profChenMenuButton', 'Les conseils du Prof Chen'));
  let profChenSpriteAltLabel = $derived(menuT('modal.profChenSpriteAlt', 'Prof Chen'));
  let menuDataTitle = $derived(menuT('menu.data', 'Data'));

  let saveAgeTick = $state(0);

  onMount(() => {
    const id = setInterval(() => {
      saveAgeTick += 1;
    }, 1000);
    return () => clearInterval(id);
  });

  let optSaveLabel = $derived.by(() => {
    void saveAgeTick;
    trackGameLanguage();
    const lastSaveTime = Number(game?.lastSaveTime);
    if (!Number.isFinite(lastSaveTime) || lastSaveTime <= 0) {
      return uiText('menu.save', 'Save', {}, game);
    }
    const lang = game && typeof game.normalizeLanguage === 'function'
      ? (game.normalizeLanguage(game.language) === 'en' ? 'en' : 'fr')
      : 'fr';
    const msAgo = Date.now() - lastSaveTime;
    const detail = msAgo < 1000
      ? uiText('menu.lastSavedJustNow', 'Last saved just now', {}, game)
      : uiText('menu.lastSavedAgo', 'Last saved {duration}', {
          duration: formatRelativeTimeAgo(msAgo, lang),
        }, game);
    return uiText('menu.saveWithLastSaved', 'Save — {detail}', { detail }, game);
  });
  let optExportLabel = $derived(menuT('menu.export', 'Export'));
  let optImportLabel = $derived(menuT('menu.import', 'Import'));
  let promoSectionTitle = $derived(menuT('promo.sectionTitle', 'Promo code'));
  let promoInputLabel = $derived(menuT('promo.inputLabel', 'Enter code'));
  let promoSubmitLabel = $derived(menuT('promo.submit', 'Redeem'));
  let promoInput = $state('');
  let promoFeedback = $state('');
  let promoFeedbackOk = $state(false);

  function promoMessageForResult(result: PromoRedeemResult | null): string {
    if (!result) return '';
    if (result.ok) return menuT('promo.success', 'Rewards claimed: {summary}', { summary: result.summary });
    const reason = result.reason;
    const keys: Record<string, string> = {
      empty: 'promo.empty',
      invalid: 'promo.invalid',
      expired: 'promo.expired',
      already: 'promo.already',
      locked: 'promo.locked',
      grant_failed: 'promo.grantFailed',
    };
    return menuT(keys[reason] ?? 'promo.invalid', reason);
  }

  function onRedeemPromo() {
    facade.dispatch({ type: 'REDEEM_PROMO_CODE', code: promoInput });
    const result = game?.getLastPromoRedeemResult?.() ?? null;
    promoFeedback = promoMessageForResult(result);
    promoFeedbackOk = !!result?.ok;
    if (result?.ok) promoInput = '';
  }
  let optDiscordLabel = $derived(menuT('menu.discord', 'Discord'));
  let optRedditLabel = $derived(menuT('menu.reddit', 'Reddit'));
  let menuOptionsTitleLabel = $derived(menuT('menu.options', 'Options'));
  let optLanguageLabel = $derived(menuT('menu.language', 'Language'));
  let langFrLabel = $derived(menuT('menu.langFr', 'French'));
  let langEnLabel = $derived(menuT('menu.langEn', 'English'));
  let languageValue = $derived.by(() => {
    trackGameLanguage();
    return game && typeof game.normalizeLanguage === 'function'
      ? game.normalizeLanguage(game.language)
      : 'fr';
  });
  let optPauseRareLabel = $derived(menuT('menu.pauseRare', 'Rare Pause'));
  let optNotifyRareLabel = $derived(menuT('menu.notifyRare', 'Rare drop alerts'));
  let optNotifyEggLabel = $derived(menuT('menu.notifyEgg', 'Auto-incubator modals'));
  let optNotifyCaptureLabel = $derived(menuT('menu.notifyCapture', 'Capture alerts'));
  let optNotifyDpsRecordLabel = $derived(menuT('menu.notifyDpsRecord', 'DPS record alerts'));
  let optNotifyQuestLabel = $derived(menuT('menu.notifyQuest', 'Quest alerts'));
  let optDamagePopupModeLabel = $derived(menuT('menu.damagePopupMode', 'Damage popups'));
  let damagePopupRawLabel = $derived(menuT('menu.damagePopupRaw', 'Raw'));
  let damagePopupTrueLabel = $derived(menuT('menu.damagePopupTrue', 'True (HP lost)'));
  let damagePopupValue = $derived(
    game && game.damagePopupMode === 'true' ? 'true' : 'raw',
  );
  let optDamagePopupCompactNumbersLabel = $derived(menuT('menu.damagePopupCompactNumbers', 'Compact combat numbers'));
  let optRivalLabel = $derived(menuT('common.rival', 'Rival'));
  let optTeamDisplayLabel = $derived(menuT('menu.teamDisplay', 'Team display'));
  let optAnimatedSpritesLabel = $derived(menuT('menu.animatedSprites', 'Animated sprites (GIF)'));
  let optAnimActiveLabel = $derived(menuT('menu.animatedActive', 'Active Pokémon'));
  let optAnimTeamLabel = $derived(menuT('menu.animatedTeam', 'Team'));
  let optAnimPensionLabel = $derived(menuT('menu.animatedPension', 'Daycare'));
  let optAnimAllLabel = $derived(menuT('menu.animatedAll', 'All (everywhere)'));
  let optReducedMotionLabel = $derived(menuT('menu.reducedMotion', 'Reduced motion'));
  let optAfkModeLabel = $derived(menuT('menu.afkMode', 'AFK mode'));
  let optOfflineReportLabel = $derived(menuT('menu.offlineReport', 'Offline report (threshold)'));
  let menuAppearanceTitle = $derived(menuT('menu.appearance', 'Appearance'));
  let optHeaderSkinLabel = $derived(menuT('menu.headerSkin', 'Header skin'));
  let optHeaderPanelOpacityLabel = $derived(menuT('menu.headerPanelOpacity', 'Panel transparency'));
  let optResetLabel = $derived(menuT('menu.reset', 'Reset game'));

  let showAnimConfig = $state(false);
  let animActive = $state(false);
  let animTeam = $state(false);
  let animPension = $state(false);
  let animAll = $state(false);

  function syncAnimFromGame() {
    const cfg = game?.animatedSprites;
    if (cfg) {
      animActive = !!cfg.active;
      animTeam = !!cfg.team;
      animPension = !!cfg.pension;
      animAll = !!cfg.all;
    }
  }

  function toggleAnimConfig() {
    showAnimConfig = !showAnimConfig;
    if (showAnimConfig) syncAnimFromGame();
  }

  function onAnimCheckbox(key: string, e: Event) {
    const checked = (e.target as HTMLInputElement).checked;
    if (key === 'all' && checked) {
      animActive = false;
      animTeam = false;
      animPension = false;
    } else if (key !== 'all' && checked) {
      animAll = false;
    }
    facade.dispatch({ type: 'SET_ANIMATED_SPRITES_CONFIG', key, value: checked });
  }

  function onLangChange(e: Event) {
    facade.dispatch({ type: 'SET_LANGUAGE', lang: (e.target as HTMLSelectElement).value });
  }
  function onDamagePopupChange(e: Event) {
    facade.dispatch({ type: 'SET_DAMAGE_POPUP_MODE', mode: (e.target as HTMLSelectElement).value });
  }
  // TODO(6.4): slider input display updates still use direct game — non-mutating
  function onOfflineSliderInput(e: Event) {
    const v = (e.target as HTMLInputElement).value;
    if (game && typeof game.updateOfflineReportSliderLabel === 'function') game.updateOfflineReportSliderLabel(v);
  }
  function onOfflineSliderChange(e: Event) {
    const v = Number((e.target as HTMLInputElement).value);
    facade.dispatch({ type: 'SET_OFFLINE_REPORT_THRESHOLD', thresholdMs: v });
  }
  function onHeaderSkinChange(e: Event) {
    facade.dispatch({ type: 'SET_HEADER_SKIN', skinId: (e.target as HTMLSelectElement).value });
  }
  // TODO(6.4): slider input display updates still use direct game — non-mutating
  function onPanelOpacityInput(e: Event) {
    const v = (e.target as HTMLInputElement).value;
    if (game && typeof game.updateHeaderPanelOpacitySliderLabel === 'function') game.updateHeaderPanelOpacitySliderLabel(v);
    if (game && typeof game.setHeaderPanelOpacityFromSlider === 'function') game.setHeaderPanelOpacityFromSlider(v);
  }
  function onPanelOpacityChange(e: Event) {
    const v = Number((e.target as HTMLInputElement).value);
    facade.dispatch({ type: 'SET_HEADER_PANEL_OPACITY', opacity: v });
  }
</script>

<!-- Cible = #saveManagerModal. Le composant rend le contenu interne. -->
<div class="stats-content js-modal-content farming-metrics-modal-content save-manager-modal-content"
  data-action="stopPropagation" data-action-stop style="max-width: 520px; width: min(92vw, 520px);">
  <div class="stats-header">
    <h2 id="saveManagerTitleLabel">{titleLabel}</h2>
    <button class="stats-close" data-action="closeSaveManager">&#10005;</button>
  </div>
  <div class="farming-metrics-body save-manager-body">
    <div class="save-manager-quick-grid">
      <button type="button" class="save-manager-quick-btn" data-action="openStatsAndCloseMenu">
        <span id="saveManagerStatsBtnLabel">{statsBtnLabel}</span>
      </button>
      <button type="button" class="save-manager-quick-btn" data-action="openBonusAndCloseMenu">
        <span id="saveManagerBonusBtnLabel">{bonusBtnLabel}</span>
      </button>
      <button type="button" class="save-manager-quick-btn" data-action="openLogAndCloseMenu">
        <span id="saveManagerJournalBtnLabel">{journalBtnLabel}</span>
      </button>
    </div>
    <div class="save-manager-prof-chen-card">
      <img
        src="img/prof_chen.png"
        class="save-manager-prof-chen-sprite"
        alt={profChenSpriteAltLabel}
        loading="lazy"
        decoding="async"
      >
      <button
        type="button"
        class="save-manager-prof-chen-btn"
        data-action="openProfChenWikiAndCloseMenu"
      >
        {profChenMenuButtonLabel}
      </button>
    </div>
    <div class="farming-metrics-section save-manager-section">
      <div class="farming-metrics-section-title" id="menuDataTitle">{menuDataTitle}</div>
      {#if loginSnap.unlocked}
        <button
          type="button"
          class="save-manager-data-btn save-manager-daily-login-btn"
          data-action="openDailyLoginModal"
        >
          {loginSnap.title}
          {#if loginSnap.canClaimToday}
            <span
              class="tab-badge tab-badge-accept"
              role="img"
              title={dailyLoginBadgeTip}
              aria-label={dailyLoginBadgeTip}
            >1</span>
          {/if}
        </button>
      {/if}
      <div class="save-manager-promo-block" id="promoCodeRoot" data-promo-root>
        <div class="farming-metrics-section-title">{promoSectionTitle}</div>
        <div class="save-manager-option-row">
          <label class="save-manager-option-label" for="promoCodeInput">{promoInputLabel}</label>
        </div>
        <div class="save-manager-promo-row">
          <input
            id="promoCodeInput"
            type="text"
            class="save-manager-promo-input"
            data-promo-input
            autocomplete="off"
            spellcheck="false"
            maxlength="32"
            bind:value={promoInput}
            onkeydown={(e) => { if (e.key === 'Enter') onRedeemPromo(); }}
          />
          <button type="button" class="save-manager-data-btn save-manager-promo-btn" onclick={onRedeemPromo}>
            {promoSubmitLabel}
          </button>
        </div>
        {#if promoFeedback}
          <p
            class="save-manager-promo-feedback"
            class:save-manager-promo-feedback--ok={promoFeedbackOk}
            class:save-manager-promo-feedback--err={!promoFeedbackOk}
            data-promo-feedback
            data-promo-status={promoFeedbackOk ? 'ok' : 'error'}
          >{promoFeedback}</p>
        {/if}
      </div>
      <div class="save-manager-data-grid">
        <button type="button" class="save-manager-data-btn save-manager-data-btn-primary btn-save" data-action="handleSaveClick" data-action-self>
          <span id="optSaveLabel">{optSaveLabel}</span>
        </button>
        <button type="button" class="save-manager-data-btn" data-action="exportSaveFile">
          <span id="optExportLabel">{optExportLabel}</span>
        </button>
        <button type="button" class="save-manager-data-btn" data-action="importSaveFile">
          <span id="optImportLabel">{optImportLabel}</span>
        </button>
        <a
          class="save-manager-data-btn save-manager-social-btn save-manager-social-discord"
          href={SAVE_BOOT_DISCORD_URL}
          target="_blank"
          rel="noopener noreferrer"
        >
          <span id="optDiscordLabel">{optDiscordLabel}</span>
        </a>
        <a
          class="save-manager-data-btn save-manager-social-btn save-manager-social-reddit"
          href={SAVE_BOOT_REDDIT_URL}
          target="_blank"
          rel="noopener noreferrer"
        >
          <span id="optRedditLabel">{optRedditLabel}</span>
        </a>
      </div>
    </div>
    <div class="farming-metrics-section save-manager-section">
      <div class="farming-metrics-section-title" id="menuOptionsTitle"><span id="menuOptionsTitleLabel">{menuOptionsTitleLabel}</span></div>
      <div class="save-manager-option-row">
        <span class="save-manager-option-label" id="optLanguageLabel">{optLanguageLabel}</span>
        <select id="optLanguageSelect" class="save-manager-select" value={languageValue} onchange={onLangChange}>
          <option value="fr">{langFrLabel}</option>
          <option value="en">{langEnLabel}</option>
        </select>
      </div>
      <div class="save-manager-option-row">
        <span class="save-manager-option-label" id="optPauseRareLabel">{optPauseRareLabel}</span>
        <button type="button" id="optPauseRare" data-action="toggleRarePause" class="save-manager-toggle-btn">?</button>
      </div>
      <div class="save-manager-option-row">
        <span class="save-manager-option-label" id="optNotifyRareLabel">{optNotifyRareLabel}</span>
        <button type="button" id="optNotifyRare" data-action="toggleNotifyRareDrop" class="save-manager-toggle-btn">?</button>
      </div>
      <div class="save-manager-option-row">
        <span class="save-manager-option-label" id="optNotifyEggLabel">{optNotifyEggLabel}</span>
        <button type="button" id="optNotifyEgg" data-action="toggleNotifyEggHatch" class="save-manager-toggle-btn">?</button>
      </div>
      <div class="save-manager-option-row">
        <span class="save-manager-option-label" id="optNotifyCaptureLabel">{optNotifyCaptureLabel}</span>
        <button type="button" id="optNotifyCapture" data-action="toggleNotifyCapture" class="save-manager-toggle-btn">?</button>
      </div>
      <div class="save-manager-option-row">
        <span class="save-manager-option-label" id="optNotifyDpsRecordLabel">{optNotifyDpsRecordLabel}</span>
        <button type="button" id="optNotifyDpsRecord" data-action="toggleNotifyDpsRecord" class="save-manager-toggle-btn">?</button>
      </div>
      <div class="save-manager-option-row">
        <span class="save-manager-option-label" id="optNotifyQuestLabel">{optNotifyQuestLabel}</span>
        <button type="button" id="optNotifyQuest" data-action="toggleNotifyQuest" class="save-manager-toggle-btn">?</button>
      </div>
      <div class="save-manager-option-row">
        <span class="save-manager-option-label" id="optDamagePopupModeLabel">{optDamagePopupModeLabel}</span>
        <select id="optDamagePopupModeSelect" class="save-manager-select" aria-labelledby="optDamagePopupModeLabel" value={damagePopupValue} onchange={onDamagePopupChange}>
          <option value="raw" id="optDamagePopupModeRawOpt">{damagePopupRawLabel}</option>
          <option value="true" id="optDamagePopupModeTrueOpt">{damagePopupTrueLabel}</option>
        </select>
      </div>
      <div class="save-manager-option-row">
        <span class="save-manager-option-label" id="optDamagePopupCompactNumbersLabel">{optDamagePopupCompactNumbersLabel}</span>
        <button type="button" id="optDamagePopupCompactNumbers" data-action="toggleDamagePopupCompactNumbers" class="save-manager-toggle-btn">?</button>
      </div>
      <div class="save-manager-option-row">
        <span class="save-manager-option-label" id="optRivalLabel">{optRivalLabel}</span>
        <button type="button" id="optRival" data-action="toggleRivalEnabled" class="save-manager-toggle-btn">?</button>
      </div>
      <div class="save-manager-option-row">
        <span class="save-manager-option-label" id="optTeamDisplayLabel">{optTeamDisplayLabel}</span>
        <button type="button" id="optTeamSpritesOnly" data-action="toggleTeamSpritesOnly" class="save-manager-toggle-btn" style="min-width: 78px;">?</button>
      </div>
      <div class="save-manager-option-row">
        <span class="save-manager-option-label" id="optAnimatedSpritesLabel">{optAnimatedSpritesLabel}</span>
        <button type="button" id="optAnimatedSprites" class="save-manager-toggle-btn" style="min-width: 100px;" onclick={toggleAnimConfig}>?</button>
      </div>
      {#if showAnimConfig}
      <div id="optAnimatedSpritesPanel" class="save-manager-anim-panel">
        <label class="save-manager-checkbox-row">
          <input type="checkbox" bind:checked={animActive} onchange={(e) => onAnimCheckbox('active', e)} disabled={animAll}>
          <span id="optAnimActiveLabel">{optAnimActiveLabel}</span>
        </label>
        <label class="save-manager-checkbox-row">
          <input type="checkbox" bind:checked={animTeam} onchange={(e) => onAnimCheckbox('team', e)} disabled={animAll}>
          <span id="optAnimTeamLabel">{optAnimTeamLabel}</span>
        </label>
        <label class="save-manager-checkbox-row">
          <input type="checkbox" bind:checked={animPension} onchange={(e) => onAnimCheckbox('pension', e)} disabled={animAll}>
          <span id="optAnimPensionLabel">{optAnimPensionLabel}</span>
        </label>
        <label class="save-manager-checkbox-row">
          <input type="checkbox" bind:checked={animAll} onchange={(e) => onAnimCheckbox('all', e)}>
          <span id="optAnimAllLabel">{optAnimAllLabel}</span>
        </label>
      </div>
      {/if}
      <div class="save-manager-option-row">
        <span class="save-manager-option-label" id="optReducedMotionLabel">{optReducedMotionLabel}</span>
        <button type="button" id="optReducedMotion" data-action="toggleReducedMotion" class="save-manager-toggle-btn">?</button>
      </div>
      <div class="save-manager-option-row">
        <span class="save-manager-option-label" id="optAfkModeLabel">{optAfkModeLabel}</span>
        <button type="button" id="optAfkMode" data-action="toggleAfkMode" class="save-manager-toggle-btn">?</button>
      </div>
      <div class="save-manager-slider-row">
        <div class="save-manager-slider-header">
          <span class="save-manager-option-label" id="optOfflineReportLabel">{optOfflineReportLabel}</span>
          <span id="optOfflineReportValue" class="save-manager-slider-value">30s</span>
        </div>
        <input id="optOfflineReportSlider" class="save-manager-slider" type="range" min="30000" max="1800000" step="30000" value="30000" oninput={onOfflineSliderInput} onchange={onOfflineSliderChange}>
      </div>
    </div>
    <div class="farming-metrics-section save-manager-section">
      <div class="farming-metrics-section-title"><span>{menuAppearanceTitle}</span></div>
      <div class="save-manager-skin-row">
        <span class="save-manager-option-label" id="optHeaderSkinLabel">{optHeaderSkinLabel}</span>
        <span id="optHeaderSkinUnlock" class="save-manager-skin-unlock">1/1 débloqués</span>
      </div>
      <select id="optHeaderSkinSelect" class="save-manager-select save-manager-select-full" onchange={onHeaderSkinChange}></select>
      <div id="optHeaderSkinDesc" class="save-manager-skin-desc">Skin de base</div>
      <div class="save-manager-slider-row">
        <div class="save-manager-slider-header">
          <span class="save-manager-option-label" id="optHeaderPanelOpacityLabel">{optHeaderPanelOpacityLabel}</span>
          <span id="optHeaderPanelOpacityValue" class="save-manager-slider-value">80%</span>
        </div>
        <input id="optHeaderPanelOpacitySlider" class="save-manager-slider" type="range" min="5" max="80" step="5" value="80" oninput={onPanelOpacityInput} onchange={onPanelOpacityChange}>
      </div>
    </div>
    <div class="save-manager-danger-section">
      <button type="button" class="save-manager-reset-btn" data-action="resetGame">
        <span id="optResetLabel">{optResetLabel}</span>
      </button>
    </div>
    <div id="menuVersionLabel" class="save-manager-version">v0.1.0</div>
  </div>
</div>

