/**
 * Svelte action: set img src only when the URL actually changes (avoids reload flicker).
 */
export function stableImgSrc(node: HTMLImageElement, src: string) {
  const apply = (url: string) => {
    const next = url || '';
    if (!next) return;
    if (node.getAttribute('src') !== next) node.setAttribute('src', next);
  };
  apply(src);
  return {
    update(url: string) {
      apply(url);
    },
  };
}
