<script lang="ts">
  import { combat } from '../stores/combat.svelte.ts';
  import { zone } from '../stores/zone.svelte.ts';
  import { facade } from '../bus/gameFacade.ts';
  import { GameEventType as Evt } from '../bus/events.js';
  import { useFacadeSubscription } from '../lib/useFacadeSubscription.ts';
  import { game } from '../../gameManager.js';
  import type { GameRuntime } from '../types/game.js';
  import { updateTowerSpeedButton } from '../ui/combatDisplay.ts';
  import { uiPokemonNameText } from '../ui/i18n.ts';
  import {
    buildShinyCharmCombatIndicator,
    EMPTY_SHINY_CHARM_COMBAT_INDICATOR,
    subscribeShinyCharmIndicatorChanged,
  } from '../lib/shinyCharmCombatIndicator.ts';
  import {
    buildRoamerIncenseCombatIndicator,
    EMPTY_ROAMER_INCENSE_COMBAT_INDICATOR,
    subscribeRoamerIncenseIndicatorChanged,
  } from '../lib/roamerIncenseCombatIndicator.ts';
  import {
    buildConcentratedMilkCombatIndicator,
    EMPTY_CONCENTRATED_MILK_COMBAT_INDICATOR,
    subscribeConcentratedMilkIndicatorChanged,
  } from '../lib/concentratedMilkCombatIndicator.ts';
  import HPBar from './HPBar.svelte';
  import RocketCombatMiniBarHost from './rocket/RocketCombatMiniBarHost.svelte';
  import FarmThreatCombatOverlay from './FarmThreatCombatOverlay.svelte';

  let shinyCharm = $state({ ...EMPTY_SHINY_CHARM_COMBAT_INDICATOR });
  let roamerIncense = $state({ ...EMPTY_ROAMER_INCENSE_COMBAT_INDICATOR });
  let concentratedMilk = $state({ ...EMPTY_CONCENTRATED_MILK_COMBAT_INDICATOR });

  function syncShinyCharmIndicator(): void {
    const gm = game as GameRuntime | null;
    shinyCharm = gm
      ? buildShinyCharmCombatIndicator(gm)
      : { ...EMPTY_SHINY_CHARM_COMBAT_INDICATOR };
  }

  function syncRoamerIncenseIndicator(): void {
    const gm = game as GameRuntime | null;
    roamerIncense = gm
      ? buildRoamerIncenseCombatIndicator(gm)
      : { ...EMPTY_ROAMER_INCENSE_COMBAT_INDICATOR };
  }

  function syncConcentratedMilkIndicator(): void {
    const gm = game as GameRuntime | null;
    concentratedMilk = gm
      ? buildConcentratedMilkCombatIndicator(gm)
      : { ...EMPTY_CONCENTRATED_MILK_COMBAT_INDICATOR };
  }

  function syncCombatBoostIndicators(): void {
    syncShinyCharmIndicator();
    syncRoamerIncenseIndicator();
    syncConcentratedMilkIndicator();
  }

  function showShinyCharmTooltip(e: MouseEvent): void {
    const gm = game as GameRuntime | null;
    if (!shinyCharm.visible || !gm?.scheduleTooltip) return;
    gm.scheduleTooltip(e, shinyCharm.tooltipTitle, shinyCharm.tooltipBody);
  }

  function hideShinyCharmTooltip(): void {
    (game as GameRuntime | null)?.hideTooltip?.();
  }

  function showRoamerIncenseTooltip(e: MouseEvent): void {
    const gm = game as GameRuntime | null;
    if (!roamerIncense.visible || !gm?.scheduleTooltip) return;
    gm.scheduleTooltip(e, roamerIncense.tooltipTitle, roamerIncense.tooltipBody);
  }

  function hideRoamerIncenseTooltip(): void {
    (game as GameRuntime | null)?.hideTooltip?.();
  }

  function showConcentratedMilkTooltip(e: MouseEvent): void {
    const gm = game as GameRuntime | null;
    if (!concentratedMilk.visible || !gm?.scheduleTooltip) return;
    gm.scheduleTooltip(e, concentratedMilk.tooltipTitle, concentratedMilk.tooltipBody);
  }

  function hideConcentratedMilkTooltip(): void {
    (game as GameRuntime | null)?.hideTooltip?.();
  }

  $effect(() => {
    syncCombatBoostIndicators();
    const unsubShiny = subscribeShinyCharmIndicatorChanged(syncShinyCharmIndicator);
    const unsubRoamer = subscribeRoamerIncenseIndicatorChanged(syncRoamerIncenseIndicator);
    const unsubMilk = subscribeConcentratedMilkIndicatorChanged(syncConcentratedMilkIndicator);
    const id = setInterval(syncCombatBoostIndicators, 1000);
    return () => {
      unsubShiny();
      unsubRoamer();
      unsubMilk();
      clearInterval(id);
    };
  });

  let playerHp = $derived(combat.playerHudCurrentHp);
  let playerMaxHp = $derived(combat.playerHudMaxHp);
  let playerName = $derived.by((): string => {
    const gm = game as GameRuntime | null;
    const creature = combat.currentPlayerCreature;
    if (!creature) return '-';
    void gm?.language;
    return uiPokemonNameText(gm, creature.name);
  });
  let enemyHp = $derived(combat.currentEnemy?.currentHp ?? 0);
  let enemyMaxHp = $derived(combat.currentEnemy?.maxHp ?? 1);
  let enemyName = $derived.by((): string => {
    const gm = game as GameRuntime | null;
    const enemy = combat.currentEnemy;
    if (!enemy) return '-';
    void gm?.language;
    let name = uiPokemonNameText(gm, enemy.name);
    if (enemy.isBoss) name = `[BOSS] ${name}`;
    if (enemy.isEpic) name = `[EPIC] ${name}`;
    if (enemy.tier > 0) name += ` [T${enemy.tier}]`;
    return name;
  });

  let hudAtkLabel = $derived.by((): string => {
    const gm = game as GameRuntime | null;
    if (!gm) return 'ATK';
    void gm.language;
    return gm.t?.('combatUi.hudAtk') ?? 'ATK';
  });

  let hudSpAtkLabel = $derived.by((): string => {
    const gm = game as GameRuntime | null;
    if (!gm) return 'ATK SP';
    void gm.language;
    return gm.t?.('combatUi.hudSpAtk') ?? 'ATK SP';
  });

  let hudDefLabel = $derived.by((): string => {
    const gm = game as GameRuntime | null;
    if (!gm) return 'DEF';
    void gm.language;
    return gm.t?.('combatUi.hudDef') ?? 'DEF';
  });

  let hudSpDefLabel = $derived.by((): string => {
    const gm = game as GameRuntime | null;
    if (!gm) return 'DEF SP';
    void gm.language;
    return gm.t?.('combatUi.hudSpDef') ?? 'DEF SP';
  });

  let hudSpdLabel = $derived.by((): string => {
    const gm = game as GameRuntime | null;
    if (!gm) return 'SPD';
    void gm.language;
    return gm.t?.('combatUi.hudSpd') ?? 'SPD';
  });

  let playerTrainerName = $derived.by((): string => {
    const gm = game as GameRuntime | null;
    if (!gm) return 'Joueur';
    void gm.language;
    return typeof gm.getPlayerProfileName === 'function' ? gm.getPlayerProfileName() : 'Joueur';
  });

  useFacadeSubscription(Evt.COMBAT_STATE_CHANGED, () => {
    const gm = game as GameRuntime | null;
    if (gm) updateTowerSpeedButton(gm);
  });
</script>

