/// <reference types="svelte" />
/**
 * Store: farming metrics modal (Phase 6 Svelte render).
 */

import { facade } from '@bus/facade';
import { GameEventType as Evt } from '../bus/events.js';
import type { GameRuntime } from '../types/game.js';
import {
  buildFarmingMetricsSnapshot,
  type FarmingMetricsSnapshot,
} from '../lib/farmingMetricsSnapshot.ts';

class FarmingMetricsStore {
  snapshot: FarmingMetricsSnapshot | null = $state(null);
}

export const farmingMetrics = new FarmingMetricsStore();

function getGame(): GameRuntime | null {
  return (globalThis as { game?: GameRuntime }).game ?? null;
}

function refreshFromGame(): void {
  const g = getGame();
  farmingMetrics.snapshot = g ? buildFarmingMetricsSnapshot(g) : null;
}

facade.subscribe(Evt.FARMING_METRICS_UPDATED, () => {
  refreshFromGame();
});

facade.subscribe(Evt.LANGUAGE_CHANGED, () => {
  refreshFromGame();
});

const LIVE_TICK_MS = 1000;
let liveTickId: ReturnType<typeof setInterval> | null = null;

function stopLiveTick(): void {
  if (liveTickId != null) {
    clearInterval(liveTickId);
    liveTickId = null;
  }
}

function startLiveTick(): void {
  stopLiveTick();
  refreshFromGame();
  liveTickId = setInterval(() => refreshFromGame(), LIVE_TICK_MS);
}

facade.subscribe(Evt.MODAL_OPENED, (evt) => {
  if (evt.type === Evt.MODAL_OPENED && evt.modalId === 'farmingMetricsModal') {
    startLiveTick();
  }
});

facade.subscribe(Evt.MODAL_CLOSED, (evt) => {
  if (evt.type === Evt.MODAL_CLOSED && evt.modalId === 'farmingMetricsModal') {
    stopLiveTick();
  }
});
