/**
 * @file src/lib/pickWeightedIndex.ts
 * Tirage pondéré par index (poids >= 0).
 */

export function pickWeightedIndex(weights: number[], rng: () => number = Math.random): number {
    let total = 0;
    for (let i = 0; i < weights.length; i++) {
        total += Math.max(0, Number(weights[i]) || 0);
    }
    if (total <= 0) return 0;
    let roll = rng() * total;
    for (let j = 0; j < weights.length; j++) {
        roll -= Math.max(0, Number(weights[j]) || 0);
        if (roll <= 0) return j;
    }
    return weights.length - 1;
}
