export function _toRoman(value: number | string): string {
    const num = Number(value);
    if (!Number.isFinite(num) || num <= 0) return '';
    const romanMap: [number, string][] = [
        [1000, 'M'], [900, 'CM'], [500, 'D'], [400, 'CD'],
        [100, 'C'], [90, 'XC'], [50, 'L'], [40, 'XL'],
        [10, 'X'], [9, 'IX'], [5, 'V'], [4, 'IV'], [1, 'I']
    ];
    let n = Math.floor(num);
    let out = '';
    for (let i = 0; i < romanMap.length; i++) {
        const entry = romanMap[i];
        if (!entry) continue;
        const [step, symbol] = entry;
        while (n >= step) {
            out += symbol;
            n -= step;
        }
    }
    return out;
}

export function _formatAchievementTargetFr(value: number | string): string {
    return formatAchievementAmountFr(Number(value));
}

export function _formatAchievementDurationFr(value: number | string): string {
    return formatAchievementDurationFr(Number(value));
}

export function _parseAchievementKey(achievementId: string): { family: string; rank: number | null } {
    const id = String(achievementId || '');
    const match = id.match(/^(.*?)(?:_(\d+))?$/);
    return {
        family: match?.[1] ?? id,
        rank: match?.[2] ? Number(match[2]) : null
    };
}
