/**
 * @file gameLoadoutSystem.js
 * Loadout (team/pension preset) subsystem -- extracted from game.js.
 * Loaded AFTER game.js, extends Game.prototype via mixin.
 * Phase 5.4 — @ts-nocheck removed.
 */

import { toast } from './toastManager.ts';
import { HELD_ITEMS } from './constants/balance/towerAndItems.js';
import { escapeHtml } from './formatters.ts';
import { coerceStr } from './src/lib/coerceStr.ts';
import { callGameVoid } from './src/lib/callBound.ts';
import { getInput } from './src/lib/dom.ts';
import { getPokemonSpriteUrl } from './src/ui/utils.ts';
import type { CreatureData } from './src/types/creature.js';
import type { ExpeditionOccupant, GameRuntime } from './src/types/game.js';
import { getMaxTeamSize } from './src/lib/playerCombatRoster.ts';

type GameCtor = { prototype: Record<string, unknown> };
type ThisGame = GameRuntime;
type CreatureLocation = 'team' | 'storage' | 'pension';
type CreatureLocationEntry = { location: CreatureLocation; index: number; creature: CreatureData };
type LoadoutSlotEntry = string | { uid: string; heldItem?: string | null };
type LoadoutSlotDef = { name?: string; slots?: LoadoutSlotEntry[]; saveHeld?: boolean };
type LoadoutDesired = { uid: string; heldItem?: string | null };
type LoadoutConflict = { targetUid: string; itemKey: string; others: CreatureLocationEntry[] };
export type LoadoutContext = 'zone' | 'arena' | 'tower' | 'subway';
type ApplyLoadoutOpts = { silent?: boolean; bypassRosterLock?: boolean };

function findCreatureByUidTyped(game: ThisGame, uid: unknown): CreatureLocationEntry | null {
    const fn = game['findCreatureByUid'] as (this: ThisGame, u: unknown) => CreatureLocationEntry | null;
    return fn.call(game, uid);
}

function getAllCreaturesWithLocationTyped(game: ThisGame): CreatureLocationEntry[] {
    const fn = game['getAllCreaturesWithLocation'] as (this: ThisGame) => CreatureLocationEntry[];
    return fn.call(game);
}

function accountTalentBonus(game: ThisGame, key: string): number {
    const n: unknown = game['getAccountTalentBonus'](key);
    return typeof n === 'number' && Number.isFinite(n) ? n : 0;
}

function pensionSlots(game: ThisGame): number {
    const n: unknown = game['getPensionSlots']();
    return typeof n === 'number' && Number.isFinite(n) ? Math.floor(n) : 0;
}

function resolveLoadoutUidTyped(game: ThisGame, uid: string): string {
    const fn = game['resolveLoadoutUid'] as (this: ThisGame, u: unknown) => string;
    return fn.call(game, uid);
}

function normalizeLoadoutDesired(slots: LoadoutSlotEntry[]): LoadoutDesired[] {
    return slots
        .filter(Boolean)
        .map((s): LoadoutDesired | null => {
            if (typeof s === 'string') return { uid: s, heldItem: undefined };
            const uid = coerceStr(s.uid);
            if (!uid) return null;
            return { uid, heldItem: s.heldItem ?? undefined };
        })
        .filter((d): d is LoadoutDesired => d != null);
}

function refreshLoadoutUi(game: ThisGame): void {
    callGameVoid(game, game['updateTeamDisplay']);
    callGameVoid(game, game['updateStorageDisplay']);
    callGameVoid(game, game['updatePensionDisplay']);
    callGameVoid(game, game['updatePensionVisibility']);
    callGameVoid(game, game['updateStorageVisibility']);
    callGameVoid(game, game['updateStorageControlsVisibility']);
}

export function notifyLoadoutRosterLocked(game: ThisGame): void {
    if (typeof toast !== 'undefined' && toast.info) {
        toast.info(game.t('toast.loadoutLockedTitle'), game.t('toast.loadoutLockedBody'));
    }
}

export function applyLoadoutSystem(GameClass: GameCtor): void {

    GameClass.prototype.getAllCreaturesWithLocation = function (this: ThisGame): CreatureLocationEntry[] {
        const result: CreatureLocationEntry[] = [];
        (this.playerTeam || []).forEach((c, index) => {
            if (c) result.push({ location: 'team', index, creature: c });
        });
        (this.storage || []).forEach((c, index) => {
            if (c) result.push({ location: 'storage', index, creature: c });
        });
        (this.pension || []).forEach((c, index) => {
            if (c) result.push({ location: 'pension', index, creature: c });
        });
        return result;
    };

    GameClass.prototype.ensureLoadoutUidRedirects = function (this: ThisGame) {
        if (!this.loadoutUidRedirects || typeof this.loadoutUidRedirects !== 'object') {
            this.loadoutUidRedirects = {};
            return;
        }

        const cleaned: Record<string, string> = {};
        Object.entries(this.loadoutUidRedirects).forEach(([fromUid, toUid]) => {
            const from = coerceStr(fromUid);
            const to = coerceStr(toUid);
            if (!from || !to || from === to) return;
            cleaned[from] = to;
        });
        this.loadoutUidRedirects = cleaned;
    };

    GameClass.prototype.registerLoadoutUidRedirect = function (this: ThisGame, fromUid: unknown, toUid: unknown) {
        const from = coerceStr(fromUid);
        const to = coerceStr(toUid);
        if (!from || !to || from === to) return;
        this.ensureLoadoutUidRedirects();
        this.loadoutUidRedirects[from] = to;
    };

    GameClass.prototype.resolveLoadoutUid = function (this: ThisGame, uid: unknown, maxHops = 12) {
        const start = coerceStr(uid);
        if (!start) return start;

        this.ensureLoadoutUidRedirects();
        let current = start;
        const seen = new Set([current]);

        for (let i = 0; i < maxHops; i++) {
            const next = this.loadoutUidRedirects[current];
            if (!next || next === current) break;
            if (seen.has(next)) break;
            current = next;
            seen.add(current);
        }
        return current;
    };

    GameClass.prototype.findCreatureByUid = function (this: ThisGame, uid: unknown): CreatureLocationEntry | null {
        const searchedUid = coerceStr(uid);
        if (!searchedUid) return null;
        const all = getAllCreaturesWithLocationTyped(this);
        for (const entry of all) {
            if (entry.creature.uid === searchedUid) return entry;
        }

        // Compat : certains anciens UID de loadout peuvent avoir ?t? absorb?s (fusion ?volutive).
        const redirectedUid = resolveLoadoutUidTyped(this, searchedUid);
        if (redirectedUid && redirectedUid !== searchedUid) {
            for (const entry of all) {
                if (entry.creature.uid === redirectedUid) return entry;
            }
        }
        return null;
    };

    GameClass.prototype.isUidInActiveExpeditions = function (this: ThisGame, uid: unknown) {
        const searchedUid = coerceStr(uid);
        if (!searchedUid) return false;
        if (typeof this.getActiveExpeditionOccupants !== 'function') return false;

        const occupants = this['getActiveExpeditionOccupants']() as ExpeditionOccupant[];
        for (const occ of occupants) {
            const data = occ.data;
            if (!data?.uid) continue;
            if (data.uid === searchedUid) return true;
        }
        return false;
    };

    GameClass.prototype.notifyLoadoutMissingUids = function (this: ThisGame, scope: unknown, missingUids: unknown) {
        if (!Array.isArray(missingUids) || missingUids.length === 0) return;
        if (typeof toast === 'undefined' || typeof toast.info !== 'function') return;

        const unique: string[] = [];
        const seen = new Set<string>();
        missingUids.forEach((uid: unknown) => {
            const value = coerceStr(uid);
            if (!value || seen.has(value)) return;
            seen.add(value);
            unique.push(value);
        });
        if (unique.length === 0) return;

        let expeditionCount = 0;
        let ultimateSlotCount = 0;
        for (const uid of unique) {
            if (this.isUidInActiveExpeditions(uid)) expeditionCount++;
            if (typeof this.isUidInUltimateSlot === 'function' && this.isUidInUltimateSlot(uid)) ultimateSlotCount++;
        }
        const unavailableCount = unique.length - expeditionCount - ultimateSlotCount;

        const isEn = this.language === 'en';
        const title = scope === 'pension'
            ? this.t('toast.loadoutDaycareTitle')
            : this.t('toast.loadoutTeamTitle');

        const parts = [];
        if (expeditionCount > 0) {
            parts.push(isEn ? `${expeditionCount} on expedition` : `${expeditionCount} en expedition`);
        }
        if (ultimateSlotCount > 0) {
            parts.push(isEn ? `${ultimateSlotCount} in ultimate slot` : `${ultimateSlotCount} en slot ultime`);
        }
        if (unavailableCount > 0) {
            parts.push(isEn ? `${unavailableCount} unavailable` : `${unavailableCount} indisponible(s)`);
        }

        const detail = parts.length > 0 ? ` (${parts.join(', ')})` : '';
        const body = isEn
            ? `${unique.length} saved member(s) could not be loaded${detail}.`
            : `${unique.length} membre(s) sauvegarde(s) n'ont pas pu etre charge(s)${detail}.`;
        toast.info(title, body);
    };

    GameClass.prototype.ensureLoadoutStructure = function (this: ThisGame) {
        if (!this.loadouts || typeof this.loadouts !== 'object') {
            this.loadouts = { team: [], pension: [] };
        }
        if (!Array.isArray(this.loadouts.team)) this.loadouts.team = [];
        if (!Array.isArray(this.loadouts.pension)) this.loadouts.pension = [];
    };

    GameClass.prototype.ensureLoadoutBindings = function (this: ThisGame) {
        if (!this.loadoutBindings || typeof this.loadoutBindings !== 'object') {
            this.loadoutBindings = { zone: 0, arena: null, tower: null, subway: null };
        }
        const clamp = (v: unknown): number | null => {
            if (v == null || v === '') return null;
            const n = Math.floor(Number(v));
            if (!Number.isFinite(n) || n < 0 || n > 4) return null;
            return n;
        };
        this.loadoutBindings.zone = clamp(this.loadoutBindings.zone);
        this.loadoutBindings.arena = clamp(this.loadoutBindings.arena);
        this.loadoutBindings.tower = clamp(this.loadoutBindings.tower);
        this.loadoutBindings.subway = clamp(this.loadoutBindings.subway);
        if (typeof this.loadoutAutoSwitch !== 'boolean') this.loadoutAutoSwitch = true;
        if (!this.activeLoadoutContext) this.activeLoadoutContext = 'zone';
    };

    GameClass.prototype.setLoadoutBinding = function (this: ThisGame, context: unknown, slotIndex: unknown) {
        if (typeof this.isTeamRosterEditLocked === 'function' && this.isTeamRosterEditLocked()) {
            notifyLoadoutRosterLocked(this);
            return;
        }
        this.ensureLoadoutBindings();
        const ctx = String(context) as LoadoutContext;
        if (ctx !== 'zone' && ctx !== 'arena' && ctx !== 'tower' && ctx !== 'subway') return;
        const slot = slotIndex == null || slotIndex === '' ? null : Math.floor(Number(slotIndex));
        if (slot != null && (!Number.isFinite(slot) || slot < 0 || slot > 4)) return;
        if (slot != null && this.loadoutBindings[ctx] === slot) {
            this.loadoutBindings[ctx] = null;
        } else {
            this.loadoutBindings[ctx] = slot;
        }
        this.saveGame();
    };

    GameClass.prototype.getLoadoutBindingSlot = function (this: ThisGame, context: unknown): number | null {
        this.ensureLoadoutBindings();
        const ctx = String(context) as LoadoutContext;
        if (ctx !== 'zone' && ctx !== 'arena' && ctx !== 'tower' && ctx !== 'subway') return null;
        const v = this.loadoutBindings[ctx];
        return v == null ? null : v;
    };

    GameClass.prototype.applyContextLoadout = function (this: ThisGame, context: unknown, opts?: ApplyLoadoutOpts) {
        this.ensureLoadoutBindings();
        const ctx = String(context) as LoadoutContext;
        if (ctx !== 'zone' && ctx !== 'arena' && ctx !== 'tower' && ctx !== 'subway') return false;
        if (!this.loadoutAutoSwitch) return false;

        const slot = this.loadoutBindings[ctx];
        if (slot == null) return false;

        const def = this.loadouts?.team?.[slot] as LoadoutSlotDef | undefined;
        if (!def || !Array.isArray(def.slots) || def.slots.length === 0) {
            if (!opts?.silent && typeof toast !== 'undefined' && toast.info) {
                toast.info(
                    this.t('toast.loadoutContextTitle'),
                    this.t('toast.loadoutContextEmpty', { context: this.t(`loadout.context.${ctx}`), slot: slot + 1 }),
                );
            }
            return false;
        }

        if (
            this.combatState === 'fighting'
            && ctx === 'zone'
            && this.activeLoadoutContext !== 'zone'
        ) {
            return false;
        }

        this.applyTeamLoadout(slot, { silent: true, ...opts });
        if (!opts?.silent && typeof toast !== 'undefined' && toast.info) {
            toast.info(
                this.t('toast.loadoutContextTitle'),
                this.t('toast.loadoutContextApplied', { context: this.t(`loadout.context.${ctx}`), slot: slot + 1 }),
            );
        }
        return true;
    };

    GameClass.prototype.enterGameContext = function (this: ThisGame, context: unknown) {
        this.ensureLoadoutBindings();
        const ctx = String(context) as LoadoutContext;
        if (ctx !== 'zone' && ctx !== 'arena' && ctx !== 'tower' && ctx !== 'subway') return;
        if (this.activeLoadoutContext === ctx) return;
        this.applyContextLoadout(ctx, { silent: true });
        this.activeLoadoutContext = ctx;
    };

    GameClass.prototype.leaveGameContext = function (this: ThisGame) {
        this.ensureLoadoutBindings();
        if (this.activeLoadoutContext === 'zone') return;
        const prev = this.activeLoadoutContext as LoadoutContext;
        this.activeLoadoutContext = 'zone';
        const applied = !!this.applyContextLoadout('zone', { silent: true, bypassRosterLock: true });
        if (applied && typeof toast !== 'undefined' && toast.info) {
            toast.info(
                this.t('toast.loadoutContextTitle'),
                this.t('toast.loadoutContextRestored', { from: this.t(`loadout.context.${prev}`) }),
            );
        }
    };

    GameClass.prototype.saveTeamLoadout = function (this: ThisGame, slotIndex: number) {
        this.ensureLoadoutStructure();
        const maxSlots = 5;
        const idx = Math.max(0, Math.min(maxSlots - 1, slotIndex));
        const team = this.playerTeam || [];
        const defaultName = this.t('modal.loadoutSlotTeam', { slot: idx + 1 });
        const existing = (this.loadouts.team[idx] || { name: defaultName, slots: [], saveHeld: false }) as LoadoutSlotDef;
        const nameEl = getInput(`loadoutName_team_${idx}`);
        const heldEl = getInput(`loadoutHeld_team_${idx}`);
        const name = (nameEl?.value.trim()) || existing.name || defaultName;
        const saveHeld = heldEl ? !!heldEl.checked : !!existing.saveHeld;

        const slots: LoadoutSlotEntry[] = [];
        team.forEach((c) => {
            if (!c?.uid) return;
            if (saveHeld) {
                slots.push({ uid: c.uid, heldItem: c.heldItem || null });
            } else {
                slots.push(c.uid);
            }
        });

        this.loadouts.team[idx] = {
            name,
            slots,
            saveHeld
        };
        if (typeof toast !== 'undefined' && toast.success) {
            toast.success(this.t('toast.loadoutTeamTitle'), this.t('toast.loadoutTeamSaved', { slot: idx + 1 }));
        }
        this.saveGame();
        const saveBtn = document.getElementById(`loadoutSave_team_${idx}`);
        if (saveBtn) {
            saveBtn.classList.add('loadout-save-feedback');
            setTimeout(() => {
                const modal = document.getElementById('loadoutManagerModal');
                if (modal) modal.remove();
            }, 580);
        }
    };

    GameClass.prototype.applyTeamLoadout = function (this: ThisGame, slotIndex: number, opts?: ApplyLoadoutOpts) {
        const silent = !!opts?.silent;
        if (!opts?.bypassRosterLock && typeof this.isTeamRosterEditLocked === 'function' && this.isTeamRosterEditLocked()) {
            if (!silent) notifyLoadoutRosterLocked(this);
            return;
        }
        this.ensureLoadoutStructure();
        const maxSlots = 5;
        const idx = Math.max(0, Math.min(maxSlots - 1, slotIndex));
        const def = this.loadouts.team[idx] as LoadoutSlotDef | undefined;
        if (!def || !Array.isArray(def.slots) || def.slots.length === 0) {
            if (!silent && typeof toast !== 'undefined' && toast.info) {
                toast.info(this.t('toast.loadoutTeamTitle'), this.t('toast.loadoutTeamMissing'));
            }
            return;
        }

        const desired = normalizeLoadoutDesired(def.slots ?? []);

        const usedUids = new Set<string>();
        const newTeam: CreatureData[] = [];
        const missingUids: string[] = [];

        const oldTeam = (this.playerTeam || []).slice();

        desired.forEach((d) => {
            const uid = d.uid;
            const found = findCreatureByUidTyped(this, uid);
            if (!found) {
                missingUids.push(uid);
                return;
            }
            if (usedUids.has(uid)) return;
            usedUids.add(uid);
            const { location, index, creature } = found;

            if (location === 'team') {
                this.playerTeam.splice(index, 1);
            } else if (location === 'storage') {
                this.storage.splice(index, 1);
            } else if (location === 'pension') {
                this.pension.splice(index, 1);
            }
            newTeam.push(creature);
        });

        const maxTeamSize = getMaxTeamSize(this);
        const keepOldMembersAsFallback = missingUids.length > 0;
        oldTeam.forEach((c) => {
            if (!c?.uid) return;
            if (!usedUids.has(c.uid)) {
                if (keepOldMembersAsFallback && newTeam.length < maxTeamSize) {
                    usedUids.add(c.uid);
                    newTeam.push(c);
                } else {
                    this.storage.push(c);
                }
            }
        });

        this.playerTeam = newTeam;

        // Si le loadout ne stocke pas les objets, on s'arr?te l? (composition seule).
        if (!def.saveHeld) {
            refreshLoadoutUi(this);
            this.saveGame();
            if (!silent && typeof toast !== 'undefined' && toast.success) {
                toast.success(this.t('toast.loadoutTeamTitle'), this.t('toast.loadoutTeamLoaded', { slot: idx + 1 }));
            }
            this.notifyLoadoutMissingUids('team', missingUids);
            return;
        }

        // Appliquer les objets tenus si le loadout les stocke,
        // en g?rant les conflits (même objet sur un autre Pokémon).
        const conflicts: LoadoutConflict[] = [];
        desired.forEach((d) => {
            const heldItem = d.heldItem;
            if (typeof heldItem === 'undefined' || !heldItem) return;
            const itemKey = heldItem;
            const target = this.playerTeam.find((c) => c && c.uid === d.uid);
            if (!target) return;

            // Si l'objet est d?j? tenu par la cible, rien ? faire
            if (target.heldItem === heldItem) return;

            const bagCount = (this.items && typeof this.items[itemKey] === 'number') ? this.items[itemKey] : 0;

            // Chercher d'autres porteurs actuels de cet objet
            const others = getAllCreaturesWithLocationTyped(this).filter((entry) => {
                const c = entry.creature;
                return c.heldItem === itemKey && c.uid !== d.uid;
            });

            if (bagCount > 0) {
                // Copie disponible dans le sac : on assigne sans toucher aux autres ni avertir.
                target.heldItem = itemKey;
                return;
            }

            if (others.length > 0) {
                conflicts.push({
                    targetUid: d.uid,
                    itemKey,
                    others,
                });
                return;
            }

            // Pas d'autre porteur trouv? et pas de stock sac : on assigne simplement.
            target.heldItem = itemKey;
        });

        if (conflicts.length > 0) {
            // Construire un mini-modal de confirmation pour les transferts d'objets
            const overlay = document.createElement('div');
            overlay.className = 'stats-modal show loadout-conflict-modal';
            overlay.style.zIndex = '32000';

            const box = document.createElement('div');
            box.className = 'stats-content loadout-conflict-content';
            box.addEventListener('click', (e: Event) => e.stopPropagation());

            let html = `
                <div class="stats-header">
                    <h2>${this.t('modal.loadoutConflictTeamTitle')}</h2>
                    <button type="button" class="stats-close" id="closeItemTransferModalBtn">&#10005;</button>
                </div>
            `;
            html += `<p class="loadout-conflict-body">${this.t('modal.loadoutConflictTeamBody')}</p>`;
            html += '<ul class="loadout-conflict-list">';

            const formatName = (c: CreatureData | null | undefined) => c ? c.name : this.t('modal.loadoutConflictUnknown');
            conflicts.forEach((conf) => {
                const itemKey = conf.itemKey;
                const itemDef = (HELD_ITEMS as Record<string, { name?: string }>)[itemKey];
                const itemName = this.getLocalizedItemName(
                    itemKey,
                    itemDef?.name ?? itemKey,
                    itemDef ?? null,
                ) as string;
                const target = this.playerTeam.find((c) => c && c.uid === conf.targetUid) ?? null;
                const otherNames = conf.others.map((o) => formatName(o.creature)).join(', ');
                const itemSafe = escapeHtml(itemName);
                html += `<li><strong>${itemSafe}</strong>${this.t('modal.loadoutConflictLineSuffix', { others: otherNames, target: formatName(target) })}</li>`;
            });
            html += '</ul>';

            html += `
                <p class="loadout-conflict-warning">
                    ${this.t('modal.loadoutConflictWarning')}
                </p>
                <div class="loadout-conflict-actions">
                    <button type="button" id="cancelItemTransferBtn" class="btn loadout-conflict-cancel">
                        ${this.t('modal.loadoutConflictIgnore')}
                    </button>
                    <button type="button" id="confirmItemTransferBtn" class="btn loadout-conflict-submit">
                        ${this.t('modal.loadoutConflictTransfer')}
                    </button>
                </div>
            `;

            box.innerHTML = html;
            overlay.appendChild(box);
            overlay.addEventListener('click', (e: Event) => {
                if (e.target === overlay) overlay.remove();
            });
            document.body.appendChild(overlay);

            const applyTransfers = () => {
                conflicts.forEach((conf) => {
                    const itemKey = conf.itemKey;
                    const target = this.playerTeam.find((c) => c && c.uid === conf.targetUid);
                    if (!target) return;
                    // Retirer l'objet des autres porteurs
                    conf.others.forEach((o) => {
                        const c = o.creature;
                        if (c.heldItem === itemKey) {
                            c.heldItem = null;
                        }
                    });
                    // Donner l'objet au Pokémon cible
                    target.heldItem = itemKey;
                });
                callGameVoid(this, this['updateItemsDisplay']);
                this.updateTeamDisplay();
                refreshLoadoutUi(this);
                this.saveGame();
                this.notifyLoadoutMissingUids('team', missingUids);
            };

            const closeBtn = box.querySelector('#closeItemTransferModalBtn');
            const cancelBtn = box.querySelector('#cancelItemTransferBtn');
            const confirmBtn = box.querySelector('#confirmItemTransferBtn');

            if (closeBtn) {
                closeBtn.addEventListener('click', () => {
                    overlay.remove();
                });
            }

            if (cancelBtn) {
                cancelBtn.addEventListener('click', () => {
                    overlay.remove();
                });
            }
            if (confirmBtn) {
                confirmBtn.addEventListener('click', () => {
                    applyTransfers();
                    overlay.remove();
                });
            }
        } else {
            callGameVoid(this, this['updateItemsDisplay']);
            refreshLoadoutUi(this);
            this.saveGame();
            if (!silent && typeof toast !== 'undefined' && toast.success) {
                toast.success(this.t('toast.loadoutTeamTitle'), this.t('toast.loadoutTeamLoaded', { slot: idx + 1 }));
            }
            this.notifyLoadoutMissingUids('team', missingUids);
        }
    };

    GameClass.prototype.savePensionLoadout = function (this: ThisGame, slotIndex: number) {
        this.ensureLoadoutStructure();
        const maxSlots = 5;
        const idx = Math.max(0, Math.min(maxSlots - 1, slotIndex));
        const pension = this.pension || [];
        const defaultName = this.t('modal.loadoutSlotDaycare', { slot: idx + 1 });
        const existing = (this.loadouts.pension[idx] || { name: defaultName, slots: [], saveHeld: false }) as LoadoutSlotDef;
        const nameEl = getInput(`loadoutName_pension_${idx}`);
        const heldEl = getInput(`loadoutHeld_pension_${idx}`);
        const name = (nameEl?.value.trim()) || existing.name || defaultName;
        const saveHeld = heldEl ? !!heldEl.checked : !!existing.saveHeld;

        const slots: LoadoutSlotEntry[] = [];
        pension.forEach((c) => {
            if (!c?.uid) return;
            if (saveHeld) {
                slots.push({ uid: c.uid, heldItem: c.heldItem || null });
            } else {
                slots.push(c.uid);
            }
        });

        this.loadouts.pension[idx] = {
            name,
            slots,
            saveHeld
        };
        if (typeof toast !== 'undefined' && toast.success) {
            toast.success(this.t('toast.loadoutDaycareTitle'), this.t('toast.loadoutDaycareSaved', { slot: idx + 1 }));
        }
        this.saveGame();
        const saveBtn = document.getElementById(`loadoutSave_pension_${idx}`);
        if (saveBtn) {
            saveBtn.classList.add('loadout-save-feedback');
            setTimeout(() => {
                const modal = document.getElementById('loadoutManagerModal');
                if (modal) modal.remove();
            }, 580);
        }
    };

    GameClass.prototype.applyPensionLoadout = function (this: ThisGame, slotIndex: number) {
        if (typeof this.isTeamRosterEditLocked === 'function' && this.isTeamRosterEditLocked()) {
            notifyLoadoutRosterLocked(this);
            return;
        }
        this.ensureLoadoutStructure();
        const maxSlots = 5;
        const idx = Math.max(0, Math.min(maxSlots - 1, slotIndex));
        const def = this.loadouts.pension[idx] as LoadoutSlotDef | undefined;
        if (!def || !Array.isArray(def.slots) || def.slots.length === 0) {
            if (typeof toast !== 'undefined' && toast.info) toast.info(this.t('toast.loadoutDaycareTitle'), this.t('toast.loadoutDaycareMissing'));
            return;
        }

        const desired = normalizeLoadoutDesired(def.slots ?? []);

        const usedUids = new Set<string>();
        const newPension: CreatureData[] = [];
        const missingUids: string[] = [];

        const oldPension = (this.pension || []).slice();

        desired.forEach((d) => {
            const uid = d.uid;
            const found = findCreatureByUidTyped(this, uid);
            if (!found) {
                missingUids.push(uid);
                return;
            }
            if (usedUids.has(uid)) return;
            usedUids.add(uid);
            const { location, index, creature } = found;

            if (location === 'team') {
                this.playerTeam.splice(index, 1);
            } else if (location === 'storage') {
                this.storage.splice(index, 1);
            } else if (location === 'pension') {
                this.pension.splice(index, 1);
            }
            newPension.push(creature);
        });

        const maxPensionSlots = pensionSlots(this);
        const keepOldMembersAsFallback = missingUids.length > 0;
        oldPension.forEach((c) => {
            if (!c?.uid) return;
            if (!usedUids.has(c.uid)) {
                if (keepOldMembersAsFallback && newPension.length < maxPensionSlots) {
                    usedUids.add(c.uid);
                    newPension.push(c);
                } else {
                    this.storage.push(c);
                }
            }
        });

        this.pension = newPension;

        // Si le loadout ne stocke pas les objets, on s'arr?te l? (composition seule).
        if (!def.saveHeld) {
            this.updatePensionDisplay();
            refreshLoadoutUi(this);
            this.saveGame();
            if (typeof toast !== 'undefined' && toast.success) {
                toast.success(this.t('toast.loadoutDaycareTitle'), this.t('toast.loadoutDaycareLoaded', { slot: idx + 1 }));
            }
            this.notifyLoadoutMissingUids('pension', missingUids);
            return;
        }

        // Gestion des conflits d'objets pour la pension
        const conflicts: LoadoutConflict[] = [];
        desired.forEach((d) => {
            const heldItem = d.heldItem;
            if (typeof heldItem === 'undefined' || !heldItem) return;
            const itemKey = heldItem;
            const target = this.pension.find((c) => c && c.uid === d.uid);
            if (!target) return;

            if (target.heldItem === heldItem) return;

            const bagCount = (this.items && typeof this.items[itemKey] === 'number') ? this.items[itemKey] : 0;

            const others = getAllCreaturesWithLocationTyped(this).filter((entry) => {
                const c = entry.creature;
                return c.heldItem === itemKey && c.uid !== d.uid;
            });

            if (bagCount > 0) {
                target.heldItem = itemKey;
                return;
            }

            if (others.length > 0) {
                conflicts.push({ targetUid: d.uid, itemKey, others });
                return;
            }

            target.heldItem = itemKey;
        });

        if (conflicts.length > 0) {
            const overlay = document.createElement('div');
            overlay.className = 'stats-modal show loadout-conflict-modal';
            overlay.style.zIndex = '32000';

            const box = document.createElement('div');
            box.className = 'stats-content loadout-conflict-content';
            box.addEventListener('click', (e: Event) => e.stopPropagation());

            let html = `
                <div class="stats-header">
                    <h2>${this.t('modal.loadoutConflictDaycareTitle')}</h2>
                    <button type="button" class="stats-close" id="closePensionItemTransferModalBtn">&#10005;</button>
                </div>
            `;
            html += `<p class="loadout-conflict-body">${this.t('modal.loadoutConflictDaycareBody')}</p>`;
            html += '<ul class="loadout-conflict-list">';

            const formatName = (c: CreatureData | null | undefined) => c ? c.name : this.t('modal.loadoutConflictUnknown');
            conflicts.forEach((conf) => {
                const itemKey = conf.itemKey;
                const itemDef = (HELD_ITEMS as Record<string, { name?: string }>)[itemKey];
                const itemName = this.getLocalizedItemName(
                    itemKey,
                    itemDef?.name ?? itemKey,
                    itemDef ?? null,
                ) as string;
                const target = this.pension.find((c) => c && c.uid === conf.targetUid) ?? null;
                const otherNames = conf.others.map((o) => formatName(o.creature)).join(', ');
                const itemSafe = escapeHtml(itemName);
                html += `<li><strong>${itemSafe}</strong>${this.t('modal.loadoutConflictLineSuffix', { others: otherNames, target: formatName(target) })}</li>`;
            });
            html += '</ul>';

            html += `
                <p class="loadout-conflict-warning">
                    ${this.t('modal.loadoutConflictWarning')}
                </p>
                <div class="loadout-conflict-actions">
                    <button type="button" id="cancelPensionItemTransferBtn" class="btn loadout-conflict-cancel">
                        ${this.t('modal.loadoutConflictIgnore')}
                    </button>
                    <button type="button" id="confirmPensionItemTransferBtn" class="btn loadout-conflict-submit">
                        ${this.t('modal.loadoutConflictTransfer')}
                    </button>
                </div>
            `;

            box.innerHTML = html;
            overlay.appendChild(box);
            overlay.addEventListener('click', (e: Event) => {
                if (e.target === overlay) overlay.remove();
            });
            document.body.appendChild(overlay);

            const applyTransfers = () => {
                conflicts.forEach((conf) => {
                    const itemKey = conf.itemKey;
                    const target = this.pension.find((c) => c && c.uid === conf.targetUid);
                    if (!target) return;
                    conf.others.forEach((o) => {
                        const c = o.creature;
                        if (c.heldItem === itemKey) {
                            c.heldItem = null;
                        }
                    });
                    target.heldItem = itemKey;
                });
                callGameVoid(this, this['updateItemsDisplay']);
                this.updatePensionDisplay();
                refreshLoadoutUi(this);
                this.saveGame();
            };

            const closeBtn = box.querySelector('#closePensionItemTransferModalBtn');
            const cancelBtn = box.querySelector('#cancelPensionItemTransferBtn');
            const confirmBtn = box.querySelector('#confirmPensionItemTransferBtn');

            if (closeBtn) {
                closeBtn.addEventListener('click', () => {
                    overlay.remove();
                });
            }

            if (cancelBtn) {
                cancelBtn.addEventListener('click', () => {
                    overlay.remove();
                });
            }
            if (confirmBtn) {
                confirmBtn.addEventListener('click', () => {
                    applyTransfers();
                    overlay.remove();
                });
            }
        } else {
            callGameVoid(this, this['updateItemsDisplay']);
            this.updatePensionDisplay();
            refreshLoadoutUi(this);
            this.saveGame();
            if (typeof toast !== 'undefined' && toast.success) {
                toast.success(this.t('toast.loadoutDaycareTitle'), this.t('toast.loadoutDaycareLoaded', { slot: idx + 1 }));
            }
        }
        refreshLoadoutUi(this);
        this.saveGame();
        if (typeof toast !== 'undefined' && toast.success) {
            toast.success(this.t('toast.loadoutDaycareTitle'), this.t('toast.loadoutDaycareLoaded', { slot: idx + 1 }));
        }
        this.notifyLoadoutMissingUids('pension', missingUids);
    };

    GameClass.prototype.showLoadoutManager = function (this: ThisGame, type: 'team' | 'pension') {
        if (typeof this.isTeamRosterEditLocked === 'function' && this.isTeamRosterEditLocked()) {
            notifyLoadoutRosterLocked(this);
            return;
        }
        this.ensureLoadoutStructure();
        const isTeam = type === 'team';
        const slots = isTeam ? this.loadouts.team : this.loadouts.pension;
        const maxSlots = 5;
        const typeKey = type;

        const existing = document.getElementById('loadoutManagerModal');
        if (existing) existing.remove();

        const overlay = document.createElement('div');
        overlay.id = 'loadoutManagerModal';
        overlay.className = 'stats-modal js-modal-overlay';
        overlay.style.cssText = 'display:flex; align-items:center; justify-content:center; z-index:30000;';

        const box = document.createElement('div');
        box.className = 'stats-content js-modal-content';
        box.style.cssText = 'max-width: 560px; padding: 20px 24px 24px; position: relative;';

        const title = this.t(isTeam ? 'modal.loadoutManagerTitleTeam' : 'modal.loadoutManagerTitleDaycare');
        
        let html = `
            <div class="stats-header">
                <h2 style="display:flex; align-items:center; gap:8px;">
                    <img src="img/sac.png" alt="Bag" style="width:20px; height:20px; object-fit:contain; image-rendering:pixelated;">
                    ${title}
                </h2>
                <button class="stats-close" data-action="closeLoadoutManager">&times;</button>
            </div>
        `;
        
        html += `<p style="margin: 0 0 16px; color:#c0c8d4; font-size:12px; line-height:1.4; background:rgba(0,0,0,0.2); padding:8px 12px; border-left:3px solid #64748b; font-style:italic;">${this.t(isTeam ? 'modal.loadoutManagerHelpContext' : 'modal.loadoutManagerHelp')}</p>`;
        if (isTeam) {
            this.ensureLoadoutBindings();
            const autoChecked = this.loadoutAutoSwitch ? 'checked' : '';
            html += `<label style="display:flex;align-items:center;gap:8px;margin:0 0 12px;font-size:12px;color:#e2e8f0;cursor:pointer;"><input id="loadoutAutoSwitchToggle" type="checkbox" ${autoChecked} data-action="toggleLoadoutAutoSwitch" style="margin:0;">${this.t('modal.loadoutAutoSwitch')}</label>`;
        }

        html += '<div style="display:flex; flex-direction:column; gap:8px;">';
        for (let i = 0; i < maxSlots; i++) {
            const defaultName = this.t(isTeam ? 'modal.loadoutSlotTeam' : 'modal.loadoutSlotDaycare', { slot: i + 1 });
            const def: LoadoutSlotDef = slots[i] ?? { name: defaultName, slots: [], saveHeld: false };
            const inputId = `loadoutName_${typeKey}_${i}`;
            const checkboxId = `loadoutHeld_${typeKey}_${i}`;

            // Construire un aperçu visuel de l'équipe du loadout (sprites)
            let previewHtml = '';
            if (def.slots && def.slots.length) {
                const usedUids = new Set<string>();
                def.slots.forEach((s) => {
                    const uid = typeof s === 'string' ? s : coerceStr(s.uid);
                    if (!uid || usedUids.has(uid)) return;
                    usedUids.add(uid);

                    const found = findCreatureByUidTyped(this, uid);
                    const creature = found?.creature ?? null;
                    const name = creature?.name ?? '';
                    if (!name) return;

                    const safeName = name.replace(/"/g, '&quot;');
                    let spriteUrl = '';
                    try {
                        spriteUrl = getPokemonSpriteUrl(name, false, false) || '';
                    } catch {
                        spriteUrl = '';
                    }

                    if (spriteUrl) {
                        previewHtml += `<img src="${spriteUrl}" alt="${safeName}" title="${safeName}" class="loadout-slot-sprite">`;
                    } else {
                        previewHtml += `<span class="loadout-slot-sprite-fallback">${safeName}</span>`;
                    }
                });
            }

            let contextBindHtml = '';
            if (isTeam) {
                const contexts: LoadoutContext[] = ['zone', 'arena', 'tower', 'subway'];
                contextBindHtml = '<div style="display:flex;gap:4px;flex-wrap:wrap;width:100%;margin-top:2px;">';
                for (const ctx of contexts) {
                    const active = this.loadoutBindings[ctx] === i;
                    const btnStyle = active
                        ? 'font-size:9px;padding:2px 6px;border-radius:2px;background:#3b82f6;color:#fff;border:1px solid #60a5fa;cursor:pointer;'
                        : 'font-size:9px;padding:2px 6px;border-radius:2px;background:rgba(0,0,0,0.25);color:#94a3b8;border:1px solid #475569;cursor:pointer;';
                    contextBindHtml += `<button type="button" style="${btnStyle}" data-action="setLoadoutBinding" data-arg="${ctx}:${i}">${this.t(`loadout.contextShort.${ctx}`)}</button>`;
                }
                contextBindHtml += '</div>';
            }

            html += `
                <div class="loadout-modal-slot" style="display:flex; align-items:center; gap:8px; padding:10px; border-radius:3px;">
                    <div class="loadout-modal-number" style="display:flex; align-items:center; justify-content:center; width:22px; height:22px; font-weight:800; font-size:11px; border-radius:2px; box-shadow:inset 0 1px 0 rgba(255,255,255,0.2);">
                        ${i + 1}
                    </div>
                    <div style="flex:1; display:flex; flex-direction:row; align-items:center; gap:8px;">
                        <input class="loadout-modal-input" id="${inputId}" type="text" value="${def.name || ''}" placeholder="${defaultName}"
                            style="flex:0 0 140px; box-sizing:border-box; padding:6px 8px; font-size:12px; outline:none; transition:border-color 0.2s; min-width:0;">
                        <label for="${checkboxId}" style="display:flex; align-items:center; gap:4px; font-size:10px; color:#cbd5e1; cursor:pointer; user-select:none; white-space:nowrap;">
                            <input id="${checkboxId}" type="checkbox" ${def.saveHeld ? 'checked' : ''} style="margin:0; width:12px; height:12px; cursor:pointer; filter: grayscale(1);">
                            ${this.t('modal.loadoutManagerHeld')}
                        </label>
                        <div class="loadout-modal-preview" id="loadoutPreview_${typeKey}_${i}">${previewHtml}</div>
                        ${contextBindHtml}
                    </div>
                    <div style="display:flex; flex-direction:column; gap:6px;">
                        <button type="button" id="loadoutSave_${typeKey}_${i}" class="btn loadout-modal-btn loadout-btn-save"
                            data-action="save${isTeam ? 'Team' : 'Pension'}Loadout" data-arg="${i}">
                            ${this.t('modal.loadoutManagerSave')}
                        </button>
                        <button type="button" class="btn loadout-modal-btn loadout-btn-load"
                            data-action="apply${isTeam ? 'Team' : 'Pension'}Loadout" data-arg="${i}">
                            ${this.t('modal.loadoutManagerLoad')}
                        </button>
                    </div>
                </div>`;
        }
        html += '</div>';

        box.innerHTML = html;
        overlay.appendChild(box);
        overlay.addEventListener('click', (e: Event) => {
            if (e.target === overlay) overlay.remove();
        });
        document.body.appendChild(overlay);

        for (let i = 0; i < maxSlots; i++) {
            const input = getInput(`loadoutName_${typeKey}_${i}`);
            const checkbox = getInput(`loadoutHeld_${typeKey}_${i}`);
            if (input) {
                input.addEventListener('change', () => {
                    this.ensureLoadoutStructure();
                    const list = isTeam ? this.loadouts.team : this.loadouts.pension;
                    const defaultName = this.t(isTeam ? 'modal.loadoutSlotTeam' : 'modal.loadoutSlotDaycare', { slot: i + 1 });
                    const def: LoadoutSlotDef = list[i] ?? { name: input.value || defaultName, slots: [], saveHeld: false };
                    def.name = input.value || def.name;
                    list[i] = def;
                    this.saveGame();
                });
            }
            if (checkbox) {
                checkbox.addEventListener('change', () => {
                    this.ensureLoadoutStructure();
                    const list = isTeam ? this.loadouts.team : this.loadouts.pension;
                    const defaultName = this.t(isTeam ? 'modal.loadoutSlotTeam' : 'modal.loadoutSlotDaycare', { slot: i + 1 });
                    const def: LoadoutSlotDef = list[i] ?? { name: input?.value || defaultName, slots: [], saveHeld: false };
                    def.saveHeld = checkbox.checked;
                    list[i] = def;
                    this.saveGame();
                });
            }
        }
    };
}
