/**
 * Shared Team Rocket loan repayment math (combat and other income withholding).
 */

import type { RocketLoanState } from '../types/game/state.js';

export interface DebtPaymentResult {
  payment: number;
  netGross: number;
}

/**
 * Amount taken from gross income toward remaining debt.
 * At least 1$ when gross >= 1 and debt > 0 (avoids floor(0.5) = 0 stalls).
 */
export function computeDebtPayment(remainingDebt: number, gross: number, rate: number): number {
  const remaining = Math.max(0, Math.floor(Number(remainingDebt) || 0));
  const raw = Math.max(0, Math.floor(Number(gross) || 0));
  const r = Number(rate);
  if (remaining <= 0 || raw <= 0 || !Number.isFinite(r) || r <= 0) return 0;
  const fromRate = Math.floor(raw * r);
  const payment = Math.min(remaining, Math.max(1, fromRate));
  return payment;
}

/** Gross minus debt payment (never negative). */
export function netAfterDebtPayment(gross: number, payment: number): number {
  const raw = Math.max(0, Math.floor(Number(gross) || 0));
  const pay = Math.max(0, Math.floor(Number(payment) || 0));
  return Math.max(0, raw - pay);
}

export function shouldWithholdRocketDebt(loan: RocketLoanState | null | undefined): boolean {
  if (!loan) return false;
  return !!loan.active && Math.max(0, Number(loan.remainingDebt) || 0) > 0;
}

export function computeDebtPaymentFromLoan(
  loan: RocketLoanState,
  gross: number,
  rate?: number,
): DebtPaymentResult {
  const withholdingRate = Number.isFinite(Number(rate))
    ? Number(rate)
    : (Number(loan.withholdingRate) || 0.5);
  const payment = computeDebtPayment(loan.remainingDebt, gross, withholdingRate);
  return { payment, netGross: netAfterDebtPayment(gross, payment) };
}

export interface ApplyDebtRepaymentResult {
  payment: number;
  netGross: number;
  repaidFully: boolean;
}

/**
 * Mutates loan counters when payment > 0. Does not touch wallet/bank.
 */
export function applyDebtRepaymentToLoan(
  loan: RocketLoanState,
  gross: number,
  rate?: number,
): ApplyDebtRepaymentResult {
  const { payment, netGross } = computeDebtPaymentFromLoan(loan, gross, rate);
  if (payment <= 0) {
    return { payment: 0, netGross, repaidFully: false };
  }
  loan.remainingDebt = Math.max(0, Math.floor(Number(loan.remainingDebt) || 0) - payment);
  loan.repaidTotal = Math.max(0, Math.floor(Number(loan.repaidTotal) || 0)) + payment;
  const repaidFully = loan.remainingDebt <= 0;
  return { payment, netGross, repaidFully };
}
