/**
 * Random offensive TM (CT) picks — shared by Poké Mart and promo codes.
 */

import { SHOP_ITEMS } from '../../constants/balance/shopAndAggregation.ts';
import { hasMoveDefinition, isDamagingMove, resolveMoveName } from '../../constants/movesDb.ts';
import type { GameRuntime } from '../types/game.js';

function resolveMoveFromCtItemKey(ctItemKey: string, moveName?: string): string | null {
  if (moveName) return resolveMoveName(moveName);
  const fallback = ctItemKey.replace(/^ct_/, '').replace(/_/g, ' ');
  return resolveMoveName(fallback);
}

/** Same rules as mart `__ct_random__` (offensive CT from SHOP_ITEMS). */
export function isOffensiveCtItemKey(ctItemKey: string, game?: GameRuntime): boolean {
  if (typeof game?.isDamagingCtItemKey === 'function') {
    return game.isDamagingCtItemKey(ctItemKey);
  }
  const shopEntry = Object.values(SHOP_ITEMS).find(
    (entry) =>
      entry &&
      typeof entry === 'object' &&
      (entry as { type?: string; item?: string }).type === 'ct' &&
      (entry as { item?: string }).item === ctItemKey,
  ) as { moveName?: string } | undefined;
  const moveName = resolveMoveFromCtItemKey(ctItemKey, shopEntry?.moveName);
  if (!moveName || !hasMoveDefinition(moveName)) return false;
  return isDamagingMove(moveName);
}

export function listOffensiveCtItemKeys(game?: GameRuntime): string[] {
  const keys = new Set<string>();
  for (const entry of Object.values(SHOP_ITEMS)) {
    if (!entry || typeof entry !== 'object') continue;
    const row = entry as { type?: string; item?: string };
    if (row.type !== 'ct' || typeof row.item !== 'string' || !row.item.startsWith('ct_')) continue;
    if (isOffensiveCtItemKey(row.item, game)) keys.add(row.item);
  }
  return [...keys];
}

export function pickRandomOffensiveCtKeys(count: number, game?: GameRuntime): string[] {
  const pool = listOffensiveCtItemKeys(game);
  if (pool.length === 0) return [];
  const n = Math.min(Math.max(1, Math.floor(count)), 20);
  const out: string[] = [];
  for (let i = 0; i < n; i++) {
    out.push(pool[Math.floor(Math.random() * pool.length)]!);
  }
  return out;
}

export function aggregateItemKeyCounts(keys: string[]): Record<string, number> {
  const out: Record<string, number> = {};
  for (const key of keys) out[key] = (out[key] || 0) + 1;
  return out;
}
