const _g = globalThis as unknown as Record<string, unknown>;

/** Capture UI previews — prefer static PNG to avoid animated GIF 404 noise. */
function capturePreviewSpriteUrl(name: string, shiny: boolean): string {
    const prevCfg = _g.POKETIME_ANIMATED_SPRITES_CONFIG as Record<string, boolean> | undefined;
    if (prevCfg && typeof prevCfg === 'object') {
        _g.POKETIME_ANIMATED_SPRITES_CONFIG = { ...prevCfg, team: false, pension: false, all: false };
    }
    try {
        const url = getPokemonSpriteUrl(name, shiny);
        return getStaticFallbackFromAnimatedUrl(url) ?? url;
    } finally {
        if (prevCfg) _g.POKETIME_ANIMATED_SPRITES_CONFIG = prevCfg;
    }
}

type GameCtor = { prototype: Record<string, unknown> };
type ThisGame = GameRuntime;

function captureTargetSlotLabel(game: GameRuntime, name: string): string {
    return (typeof uiPokemonName === 'function') ? uiPokemonName(game, name) : name;
}

export function bindCaptureTargetWrapperTooltipEvents(container: HTMLElement, game: GameRuntime): void {
    if (container.dataset.captureTargetTooltipBound === '1') return;
    if (!game || typeof game.scheduleTooltip !== 'function') return;
    container.dataset.captureTargetTooltipBound = '1';

    container.addEventListener('mouseover', (ev) => {
        const node = (ev.target as HTMLElement).closest('.target-slot[data-tooltip-title]');
        if (!node) return;
        const el = node as HTMLElement;
        game.scheduleTooltip(ev, el.dataset.tooltipTitle || '', '', 50);
    });
    container.addEventListener('mouseout', (ev) => {
        const node = (ev.target as HTMLElement).closest('.target-slot[data-tooltip-title]');
        if (node && typeof game.hideTooltip === 'function') {
            game.hideTooltip();
        }
    });
}

type PokedexDirectEntry = {
    name: string;
    type: string;
    rarity: string;
    hasShiny?: boolean;
    hasShadow?: boolean;
    count?: number;
    shinyCount?: number;
    shadowCount?: number;
    firstDiscoveredAt?: number;
    [key: string]: unknown;
};

export function applyCaptureSystem(GameClass: GameCtor): void {

    const REGION_ORDER_FOR_ACQUISITION = ['kanto', 'johto', 'hoenn', 'sinnoh', 'unova', 'kalos', 'alola', 'galar', 'paldea']
        .filter((id) => isRegionReleased(id));

    function escapeHtmlCapture(s: unknown): string {
        return coerceStr(s, '')
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;');
    }

    function getRegionOrderIndex(regionId: string): number {
        const idx = REGION_ORDER_FOR_ACQUISITION.indexOf(String(regionId || ''));
        return idx >= 0 ? idx : 999;
    }

    function getRegionDisplayNameForAcquisition(regionId: string): string {
        const rid = String(regionId || 'kanto');
        const r = getRegions()[rid] as Record<string, unknown> | undefined;
        if (r && r.name) {
            return coerceStr(r.name, rid);
        }
        return rid;
    }

    /** Scan ZONE_POKEMON / ZONES — espèce présente dans la table (terre + surf + pêche via zoneSystem). */
    function collectZonesForSpecies(speciesName: string): Array<{ zoneId: number; zoneName: string; regionId: string; regionOrder: number; regionOrderIdx: number }> {
        const out: Array<{ zoneId: number; zoneName: string; regionId: string; regionOrder: number; regionOrderIdx: number }> = [];
        if (!speciesName) return out;
        const getter = getAllPokemonInZoneLogic;

        const zoneIds = new Set<number>();
        (Object.keys(ZONES)).forEach(function (this: void, k: string) {
            const n = Number(k);
            if (Number.isFinite(n)) zoneIds.add(n);
        });
        if (ZONE_POKEMON) {
            (Object.keys(ZONE_POKEMON)).forEach(function (this: void, k: string) {
                const n = Number(k);
                if (Number.isFinite(n)) zoneIds.add(n);
            });
        }

        zoneIds.forEach(function (this: void, zoneId: number) {
            const names = getter(null as unknown as GameRuntime, zoneId);
            if (!names || names.indexOf(speciesName) === -1) return;
            const z = (ZONES as Record<number, Record<string, unknown>>)[zoneId];
            const zoneName = z && z.name ? coerceStr(z.name, '') : ('Zone ' + zoneId);
            let regionId = 'kanto';
            const zgrFn = _g._getZoneRegionId as ((zoneId: number) => string) | undefined;
            if (typeof zgrFn === 'function') {
                regionId = String(zgrFn(zoneId));
            } else if (z && z.regionId) {
                regionId = coerceStr(z.regionId, 'kanto');
            }
            if (!isRegionReleased(regionId)) return;
            const regionOrder = z && Number.isFinite(Number(z.regionOrder)) ? Number(z.regionOrder) : zoneId;
            out.push({
                zoneId,
                zoneName,
                regionId,
                regionOrder,
                regionOrderIdx: getRegionOrderIndex(regionId)
            });
        });

        out.sort(function (this: void, a, b) {
            if (a.regionOrderIdx !== b.regionOrderIdx) return a.regionOrderIdx - b.regionOrderIdx;
            if (a.regionId !== b.regionId) return String(a.regionId).localeCompare(String(b.regionId));
            if (a.regionOrder !== b.regionOrder) return a.regionOrder - b.regionOrder;
            return a.zoneId - b.zoneId;
        });
        return out;
    }

    /** Buckets POKEMON_POOL où l'espèce apparaît (rareté capsule × slot de type), si éclosion possible sur cette save. */
    function collectEggPoolsForSpecies(
        game: GameRuntime,
        speciesName: string,
    ): Array<{ rarity: string; typeSlot: string }> {
        const rows: Array<{ rarity: string; typeSlot: string }> = [];
        if (!speciesName || !isSpeciesHatchableForGame(game, speciesName)) {
            return rows;
        }
        const r = RARITY;
        const order = [r.COMMON, r.RARE, r.EPIC, r.LEGENDARY];
        const seen: Record<string, boolean> = {};
        const poolObj = POKEMON_POOL;
        order.forEach(function (this: void, rarity: string) {
            const pool = poolObj[rarity];
            if (!pool || typeof pool !== 'object') return;
            (Object.keys(pool)).forEach(function (this: void, typeSlot: string) {
                const arr = pool[typeSlot];
                if (!Array.isArray(arr) || arr.indexOf(speciesName) === -1) return;
                const key = rarity + '|' + typeSlot;
                if (seen[key]) return;
                seen[key] = true;
                rows.push({ rarity, typeSlot: String(typeSlot) });
            });
        });
        return rows;
    }

    GameClass.prototype.getPokemonAcquisitionDetails = function (this: ThisGame, speciesName: string): {
        speciesName: string;
        zones: ReturnType<typeof collectZonesForSpecies>;
        eggs: ReturnType<typeof collectEggPoolsForSpecies>;
        evolutions: ReturnType<typeof collectEvolutionParentsForSpecies>;
        evolvesTo: ReturnType<typeof collectEvolutionChildrenForSpecies>;
        moves: {
            natural: string[];
            ct: string[];
            unlocked: string[];
        };
    } {
        const name = speciesName ? String(speciesName) : '';
        const learnset = getSpeciesLearnsetDisplay(name);
        const unlockedFn: unknown = this['getUnlockedMovesForCreature'];
        const unlocked = (typeof unlockedFn === 'function' && name)
            ? (unlockedFn as (this: ThisGame, n: string) => string[]).call(this, name)
            : [];
        return {
            speciesName: name,
            zones: collectZonesForSpecies(name),
            eggs: collectEggPoolsForSpecies(this, name),
            evolutions: collectEvolutionParentsForSpecies(name),
            evolvesTo: collectEvolutionChildrenForSpecies(name),
            moves: {
                natural: learnset.natural,
                ct: learnset.ct,
                unlocked,
            },
        };
    };

    GameClass.prototype.closePokedexAcquisitionModal = function (this: ThisGame): void {
        const el = document.getElementById('pokedexAcquisitionModal');
        if (el && (el as unknown as Record<string, unknown>)._pokedexViewportListener) {
            window.removeEventListener('resize', (el as unknown as Record<string, unknown>)._pokedexViewportListener as () => void);
            (el as unknown as Record<string, unknown>)._pokedexViewportListener = null;
        }
        if (el) el.remove();
    };

    /**
     * Place la carte compacte près du clic (ou du centre de la carte source),
     * avec origine dâ€™animation au point dâ€™ancrage. Recalcule largeur/hauteur après layout.
     */
    function positionPokedexAcquisitionPopover(box: HTMLElement, anchorEl: HTMLElement | undefined, event: Event | undefined, preferAnchorRect: boolean): void {
        function anchorPoint(): { ax: number; ay: number } {
            if (preferAnchorRect && anchorEl && anchorEl.isConnected && anchorEl.getBoundingClientRect) {
                const r = anchorEl.getBoundingClientRect();
                return { ax: r.left + r.width / 2, ay: r.top + r.height / 2 };
            }
            if (!preferAnchorRect && event && typeof (event as MouseEvent).clientX === 'number' && typeof (event as MouseEvent).clientY === 'number') {
                return { ax: (event as MouseEvent).clientX, ay: (event as MouseEvent).clientY };
            }
            if (anchorEl && anchorEl.getBoundingClientRect) {
                const r = anchorEl.getBoundingClientRect();
                return { ax: r.left + r.width / 2, ay: r.top + r.height / 2 };
            }
            return { ax: window.innerWidth / 2, ay: window.innerHeight / 2 };
        }

        function apply(): void {
            const pt = anchorPoint();
            const ax = pt.ax;
            const ay = pt.ay;
            const bw = Math.max(box.offsetWidth || 280, 120);
            const bh = Math.max(box.offsetHeight || 160, 80);
            const margin = 8;
            const gap = 6;
            const belowTop = ay + gap;
            const aboveTop = ay - bh - gap;
            let top: number;
            if (belowTop + bh <= window.innerHeight - margin) {
                top = belowTop;
            } else if (aboveTop >= margin) {
                top = aboveTop;
            } else {
                top = Math.max(margin, Math.min(belowTop, window.innerHeight - bh - margin));
            }
            let left = ax - bw / 2;
            left = Math.max(margin, Math.min(left, window.innerWidth - bw - margin));

            box.style.left = left + 'px';
            box.style.top = top + 'px';
            box.style.position = 'fixed';

            const ox = Math.max(0, Math.min(100, ((ax - left) / bw) * 100));
            const oy = Math.max(0, Math.min(100, ((ay - top) / bh) * 100));
            box.style.transformOrigin = ox + '% ' + oy + '%';
        }

        apply();
        requestAnimationFrame(function () {
            apply();
        });
    }

    GameClass.prototype.openPokedexAcquisitionModal = function (this: ThisGame, encodedName: string | null | undefined, anchorEl?: HTMLElement, event?: Event): void {
        let speciesName = '';
        if (encodedName != null && encodedName !== '') {
            try {
                speciesName = decodeURIComponent(String(encodedName));
            } catch {
                speciesName = String(encodedName);
            }
        }
        if (!speciesName) return;

        const details = this.getPokemonAcquisitionDetails(speciesName);

        const zonesHtml = details.zones.length
            ? `<ul class="pokedex-acquisition-list">${details.zones.map(function (this: ThisGame, z: any) {
                const rName = escapeHtmlCapture(getRegionDisplayNameForAcquisition(z.regionId));
                const zName = escapeHtmlCapture(z.zoneName);
                return `<li><span class="pokedex-acquisition-region">${rName}</span> — ${zName} <span class="pokedex-acquisition-zone-id">(#${z.zoneId})</span></li>`;
            }, this).join('')}</ul>`
            : `<p class="pokedex-acquisition-empty">${escapeHtmlCapture(this.t('pokedex.acquisitionNoZones'))}</p>`;

        const eggsHtml = details.eggs.length
            ? `<ul class="pokedex-acquisition-list">${details.eggs.map(function (this: ThisGame, row: any) {
                const capLabel = (typeof this.getRarityLabel === 'function')
                    ? this.getRarityLabel(row.rarity)
                    : row.rarity;
                const typeLbl = row.typeSlot ? row.typeSlot.charAt(0).toUpperCase() + row.typeSlot.slice(1) : '';
                const line = this.t('pokedex.acquisitionEggLine', {
                    capsule: capLabel,
                    typeSlot: typeLbl
                });
                return `<li>${escapeHtmlCapture(line)}</li>`;
            }, this).join('')}</ul>`
            : `<p class="pokedex-acquisition-empty">${escapeHtmlCapture(this.t('pokedex.acquisitionNoEggs'))}</p>`;

        const evoFromHtml = details.evolutions.length
            ? `<ul class="pokedex-acquisition-list">${details.evolutions.map(function (this: ThisGame, e: any) {
                const from = escapeHtmlCapture(e.from);
                const det = e.detail ? ` <span class="pokedex-acquisition-evo-detail">(${escapeHtmlCapture(e.detail)})</span>` : '';
                const prefix = escapeHtmlCapture(this.t('pokedex.acquisitionEvoFrom'));
                return `<li>${prefix} <strong>${from}</strong>${det}</li>`;
            }, this).join('')}</ul>`
            : `<p class="pokedex-acquisition-empty">${escapeHtmlCapture(this.t('pokedex.acquisitionNoEvolution'))}</p>`;

        const evoToHtml = details.evolvesTo.length
            ? `<ul class="pokedex-acquisition-list">${details.evolvesTo.map(function (this: ThisGame, e: any) {
                const to = escapeHtmlCapture(e.to);
                const det = e.detail ? ` <span class="pokedex-acquisition-evo-detail">(${escapeHtmlCapture(e.detail)})</span>` : '';
                const prefix = escapeHtmlCapture(this.t('pokedex.acquisitionEvoTo'));
                return `<li>${prefix} <strong>${to}</strong>${det}</li>`;
            }, this).join('')}</ul>`
            : `<p class="pokedex-acquisition-empty">${escapeHtmlCapture(this.t('pokedex.acquisitionNoEvolvesTo'))}</p>`;

        const evoHtml = `
                    <p class="pokedex-acquisition-evo-direction">${escapeHtmlCapture(this.t('pokedex.acquisitionEvoFromHeading'))}</p>
                    ${evoFromHtml}
                    <p class="pokedex-acquisition-evo-direction">${escapeHtmlCapture(this.t('pokedex.acquisitionEvoToHeading'))}</p>
                    ${evoToHtml}`;

        const noWildNoEgg = details.zones.length === 0 && details.eggs.length === 0;
        const emptyNote = noWildNoEgg && details.evolutions.length === 0
            ? `<p class="pokedex-acquisition-note">${escapeHtmlCapture(this.t('pokedex.acquisitionNoneWildOrEgg'))}</p>`
            : (noWildNoEgg && details.evolutions.length > 0
                ? `<p class="pokedex-acquisition-note">${escapeHtmlCapture(this.t('pokedex.acquisitionOnlyEvolutionHint'))}</p>`
                : '');

        const title = this.t('pokedex.acquisitionModalTitle', { name: speciesName });

        const unlockedSet = new Set(details.moves.unlocked);
        const renderMovePills = (moveNames: string[]): string => {
            if (!moveNames.length) {
                return `<p class="pokedex-acquisition-empty">${escapeHtmlCapture(this.t('pokedex.acquisitionNoMoves'))}</p>`;
            }
            const pills = moveNames.map((moveName) => {
                const label = escapeHtmlCapture(
                    typeof this.getLocalizedMoveNamePlain === 'function'
                        ? this.getLocalizedMoveNamePlain(moveName)
                        : moveName,
                );
                const knownClass = unlockedSet.has(moveName) ? 'pokedex-move-known' : 'pokedex-move-unknown';
                const tooltipMoveName = String(resolveMoveName(moveName)).replace(/"/g, '&quot;');
                return `<span class="pokedex-move-pill ${knownClass}" data-move-tooltip-name="${tooltipMoveName}">${label}</span>`;
            }).join('');
            return `<div class="pokedex-moves-grid">${pills}</div>`;
        };

        const naturalMovesHtml = renderMovePills(details.moves.natural);
        const ctMovesHtml = renderMovePills(details.moves.ct);

        const html = `
            <div class="stats-header pokedex-acquisition-header">
                <h2 id="pokedexAcquisitionModalTitle" class="pokedex-acquisition-title">${escapeHtmlCapture(title)}</h2>
                <button type="button" class="stats-close" data-action="closePokedexAcquisitionModal">&#10005;</button>
            </div>
            <div class="pokedex-acquisition-body">
                ${emptyNote}
                <section class="pokedex-acquisition-section" aria-labelledby="pokedexAcquisitionZonesHeading">
                    <h3 id="pokedexAcquisitionZonesHeading" class="pokedex-acquisition-section-title">${escapeHtmlCapture(this.t('pokedex.acquisitionSectionZones'))}</h3>
                    ${zonesHtml}
                </section>
                <section class="pokedex-acquisition-section" aria-labelledby="pokedexAcquisitionEggsHeading">
                    <h3 id="pokedexAcquisitionEggsHeading" class="pokedex-acquisition-section-title">${escapeHtmlCapture(this.t('pokedex.acquisitionSectionEggs'))}</h3>
                    ${eggsHtml}
                </section>
                <section class="pokedex-acquisition-section" aria-labelledby="pokedexAcquisitionEvoHeading">
                    <h3 id="pokedexAcquisitionEvoHeading" class="pokedex-acquisition-section-title">${escapeHtmlCapture(this.t('pokedex.acquisitionSectionEvolution'))}</h3>
                    ${evoHtml}
                </section>
                <section class="pokedex-acquisition-section" aria-labelledby="pokedexAcquisitionNaturalMovesHeading">
                    <h3 id="pokedexAcquisitionNaturalMovesHeading" class="pokedex-acquisition-section-title">${escapeHtmlCapture(this.t('pokedex.acquisitionSectionNaturalMoves'))}</h3>
                    ${naturalMovesHtml}
                </section>
                <section class="pokedex-acquisition-section" aria-labelledby="pokedexAcquisitionCtMovesHeading">
                    <h3 id="pokedexAcquisitionCtMovesHeading" class="pokedex-acquisition-section-title">${escapeHtmlCapture(this.t('pokedex.acquisitionSectionCtMoves'))}</h3>
                    ${ctMovesHtml}
                </section>
            </div>
        `;

        this.closePokedexAcquisitionModal();

        const overlay = document.createElement('div');
        overlay.id = 'pokedexAcquisitionModal';
        overlay.className = 'pokedex-acquisition-overlay show js-modal-overlay';
        overlay.setAttribute('role', 'dialog');
        overlay.setAttribute('aria-modal', 'true');
        overlay.setAttribute('aria-labelledby', 'pokedexAcquisitionModalTitle');

        const box = document.createElement('div');
        box.className = 'stats-content pokedex-acquisition-modal-content pokedex-acquisition-pop';
        box.setAttribute('data-action-stop', '');
        box.innerHTML = html;

        overlay.appendChild(box);
        overlay.addEventListener('click', function (e: Event) {
            if (e.target === overlay) {
                const w = window as unknown as { game?: ThisGame | null };
                if (w.game && typeof w.game.closePokedexAcquisitionModal === 'function') {
                    w.game.closePokedexAcquisitionModal();
                }
            }
        });

        document.body.appendChild(overlay);

        const reposition = function (): void {
            positionPokedexAcquisitionPopover(box, anchorEl, event, true);
        };
        const overlayEx = overlay as unknown as Record<string, unknown>;
        overlayEx._pokedexViewportListener = reposition;
        window.addEventListener('resize', reposition);

        positionPokedexAcquisitionPopover(box, anchorEl, event, false);
        requestAnimationFrame(function () {
            positionPokedexAcquisitionPopover(box, anchorEl, event, false);
        });
    };

    GameClass.prototype.startCapturePhase = function (this: ThisGame): void {
        // Sécurités
        if (this.towerState.isActive || this.arenaState.active || this.isOfflineSimulating) {
            this.finalizeCombat(false);
            return;
        }

        this.combatState = 'capture';
        if (typeof this._applyActiveFirstAfterCombatIfNeeded === 'function') {
            this._applyActiveFirstAfterCombatIfNeeded();
        }
        const enemy = this.currentEnemy;
        const modal = document.getElementById('captureModal');
        const captureTitle = document.getElementById('capturePanelTitleLabel');

        if (!modal || !enemy) {
            this.finalizeCombat(false);
            return;
        }

        if (captureTitle) captureTitle.textContent = this.t('capture.panelTitle');

        const baseChance = recordGetOr(
            POKEMON_CATCH_RATES as Record<string, number>,
            enemy.name,
            recordGetOr(CATCH_RATES as Record<string, number>, enemy.rarity, 0.1)
        );
        const spriteUrl = capturePreviewSpriteUrl(enemy.name, !!enemy.isShiny);
        const enemyDisplayName = this.getLocalizedPokemonName(enemy.name);

        const ballTypes = ['pokeball', 'greatball', 'hyperball', 'masterball'];
        const balls: Array<{
            type: string;
            count: number;
            name: string;
            img: string;
            icon: string;
            visualRate: number;
            barColor: string;
            disabled: boolean;
        }> = [];

        ballTypes.forEach((type: string) => {
            const count = (this.items)[type] || 0;
            // On récupère la définition depuis notre constante BALLS
            const ballDef = recordGet(BALLS as Record<string, Record<string, unknown>>, type)
                ?? { name: type, catchMult: 1, img: '', icon: '' };
            const catchMult = Number(ballDef.catchMult) || 1;

            // Calcul du taux visuel
            const charmBonus = (typeof (this as Record<string, unknown>).getCharmeurBonus === 'function')
                ? ((this as Record<string, unknown>).getCharmeurBonus as () => number)()
                : 1.0;
            const accountCaptureBonus = this.getAccountTalentBonus
                ? (this.getAccountTalentBonus('capture_chance') || 0)
                : 0;
            const leadType = this.currentPlayerCreature?.type;
            const academyCaptureBonus = getAcademyCourseBonus(this, 'capture_chance', leadType);
            const masteryCaptureBonus = this.getMasteryBonus
                ? (this.getMasteryBonus('capture_chance') || 0)
                : 0;
            const masteryManualCaptureBonus = this.getMasteryBonus
                ? (this.getMasteryBonus('manual_capture_bonus') || 0)
                : 0;
            let visualRate = Math.min(100, ((baseChance * catchMult * charmBonus) + Math.max(0, accountCaptureBonus) + Math.max(0, academyCaptureBonus) + Math.max(0, masteryCaptureBonus) + Math.max(0, masteryManualCaptureBonus)) * 100);
            if (type === 'masterball') visualRate = 100;

            // Couleur de la barre de chance
            let barColor = '#ef4444'; // Rouge
            if (visualRate > 30) barColor = '#f59e0b'; // Orange
            if (visualRate > 70) barColor = '#22c55e'; // Vert

            // L'Image de la Ball (Fallback sur l'emoji si pas d'image)
            balls.push({
                type,
                count,
                name: coalesceStr(ballDef.name, type),
                img: coerceStr(ballDef.img, ''),
                icon: coerceStr(ballDef.icon, ''),
                visualRate,
                barColor,
                disabled: count === 0,
            });
        });

        const sceneStyles: Record<string, string> = {};
        const battleDisplay = document.getElementById('battleDisplay');
        if (battleDisplay) {
            const battleStyles = window.getComputedStyle(battleDisplay);
            sceneStyles['--capture-scene-game-bg-image'] = battleStyles.backgroundImage || '';
            sceneStyles['--capture-scene-game-bg-position'] = battleStyles.backgroundPosition || '';
            sceneStyles['--capture-scene-game-bg-size'] = battleStyles.backgroundSize || '';
            sceneStyles['--capture-scene-game-bg-repeat'] = battleStyles.backgroundRepeat || '';
            sceneStyles['--capture-scene-game-bg-color'] = battleStyles.backgroundColor || 'transparent';
        }

        void import('./src/bridge/captureModalBridge.js').then((m) => {
            m.showCaptureModal({
                title: this.t('capture.panelTitle'),
                enemyName: enemyDisplayName,
                enemyRarity: String(enemy.rarity),
                enemyLevel: Number(enemy.level) || 1,
                spriteUrl,
                skipLabel: this.t('capture.skipButton'),
                balls,
                sceneStyles,
            });
        });
    };

    /**
     * Toggle simple OFFâ†”TARGET du sélecteur de capture (action principale du
     * bouton AUTO-like). Ne ré-ouvre PAS le picker si une liste de cibles est
     * déjà mémorisée (gain UX : 1 clic = ré-armer). En revanche, si on passe
     * en TARGET sans aucune cible, on ouvre le picker pour aider l'utilisateur
     * à choisir (sinon "armé sans cible" = silence radio = bug perçu).
     */
    GameClass.prototype.toggleCaptureMode = function (this: ThisGame): void {
        this._syncCaptureTargetsToCurrentZone();
        const wasOff = (this.captureMode === 0);
        this.captureMode = wasOff ? 2 : 0;

        if (this.captureMode === 2) {
            if (this.captureTarget && this.captureTargets && !this.captureTargets.includes(this.captureTarget)) {
                this.captureTargets.push(this.captureTarget);
            }
            const hasTargets = (this.captureTargets && this.captureTargets.length > 0) || false;
            if (!hasTargets) {
                this.openCaptureTargets();
            } else {
                // Picker fermé : ré-armement silencieux
                const wrapper = document.getElementById('captureTargetWrapper');
                if (wrapper && wrapper.classList.contains('show')) {
                    wrapper.classList.remove('show');
                    wrapper.style.display = 'none';
                }
            }
        } else {
            // Passage en OFF : on ferme le picker s'il était ouvert
            const wrapper = document.getElementById('captureTargetWrapper');
            if (wrapper) {
                wrapper.classList.remove('show');
                wrapper.style.display = 'none';
            }
        }

        this.updateCaptureButtonDisplay();
        if (typeof this.saveGame === 'function') this.saveGame();
    };

    /**
     * Ouvre explicitement le picker de cibles (icône engrenage du split button).
     * Bascule en mode TARGET si nécessaire, puis affiche la grille.
     */
    GameClass.prototype.openCaptureTargets = function (this: ThisGame): void {
        this._syncCaptureTargetsToCurrentZone();
        if (this.captureMode !== 2) {
            this.captureMode = 2;
        }
        if (this.updateCaptureTargetList) {
            this.updateCaptureTargetList();
        }

        // OUVERTURE EXPLICITE du picker (seul point d'entrée légitime).
        const wrapper = document.getElementById('captureTargetWrapper');
        if (wrapper) {
            wrapper.classList.add('show');
            wrapper.style.display = 'flex';
        }
        requestAnimationFrame(() => {
            if (this.updateCaptureTargetList) this.updateCaptureTargetList();
            if (this.refreshCaptureTargetSlots) this.refreshCaptureTargetSlots();
        });

        // Positionnement explicite autour du split button (cohérent avec
        // openAutoSettings). Ancrage sur le groupe pour tenir compte de la
        // largeur "main + gear".
        if (typeof this.positionCompactModal === 'function') {
            this.positionCompactModal('captureTargetWrapper', 'captureSelectGroup');
        }
        this.updateCaptureButtonDisplay();
        if (typeof this.saveGame === 'function') this.saveGame();
    };

    /**
     * Vide la liste des cibles. Le mode reste TARGET (le bouton passera en
     * état "armé sans cible" ambré pour signaler l'absence de target).
     */
    GameClass.prototype.clearCaptureTargets = function (this: ThisGame): void {
        this._syncCaptureTargetsToCurrentZone();
        // Mutation in-place (length = 0) au lieu de réassignation, pour
        // préserver la référence partagée avec captureTargetsByZone.
        this.captureTargets!.length = 0;
        this.captureTarget = null;
        this.refreshCaptureTargetSlots();
        this.updateCaptureButtonDisplay();
        if (typeof this.saveGame === 'function') this.saveGame();
    };

    /**
     * Wrapper de compat : conserve l'ancien nom pour les call sites/tests
     * existants. Délègue au nouveau toggleCaptureMode.
     */
    GameClass.prototype.cycleCaptureMode = function (this: ThisGame): void {
        this.toggleCaptureMode();
    };

    /// UI : Mise à jour de la grille de cibles (Ton Design Grid)
    /**
     * Synchronise this.captureTargets vers la liste persistée de la zone
     * courante (this.captureTargetsByZone[currentZone]). Crée la map et
     * l'entrée de zone si absentes. Idempotent et bon marché — peut être
     * appelé en tête de chaque API publique sans craindre de doublon.
     *
     * Garantie clé : this.captureTargets et captureTargetsByZone[currentZone]
     * partagent la MÃŠME référence array. Toute mutation push/splice/length=0
     * sur captureTargets modifie donc directement la map persistée. En
     * revanche, une RÃ‰ASSIGNATION (this.captureTargets = [...]) casse le
     * lien — dans ce cas il faut re-sync explicitement (ou mieux : muter
     * via splice(0, ..., ...newItems) pour garder la même ref).
     */
    GameClass.prototype._syncCaptureTargetsToCurrentZone = function (this: ThisGame): void {
        const cz = currentZone;
        const zoneId = (typeof cz !== 'undefined' && Number.isFinite(Number(cz)))
            ? Number(cz)
            : 1;

        if (!this.captureTargetsByZone || typeof this.captureTargetsByZone !== 'object') {
            this.captureTargetsByZone = {};
        }

        // Migration douce : si this.captureTargets contient des données legacy
        // (array non vide chargée depuis un save d'avant la migration par zone)
        // et que la map est vide, on hydrate la zone courante avec ces données.
        if (Array.isArray(this.captureTargets) && this.captureTargets.length > 0
            && !Array.isArray(this.captureTargetsByZone[zoneId])) {
            this.captureTargetsByZone[zoneId] = this.captureTargets.slice();
        }

        if (!Array.isArray(this.captureTargetsByZone[zoneId])) {
            this.captureTargetsByZone[zoneId] = [];
        }

        // Pointer vers la même référence (mutations partagées avec la map).
        this.captureTargets = this.captureTargetsByZone[zoneId];
    };

    /**
     * Calcule maxSlots de capture (scope + bonus mastery). Centralisé pour
     * éviter la duplication entre updateCaptureTargetList, refreshCaptureTargetSlots
     * et toggleCaptureTarget.
     */
    GameClass.prototype._getCaptureMaxSlots = function (this: ThisGame): number {
        const hasScope = !!(this.items && ((this.items)['scope'] || 0) > 0);
        const extraSlot = (this.getMasteryBonus ? Math.floor(this.getMasteryBonus('extra_capture_slot') || 0) : 0);
        return (hasScope ? 2 : 1) + extraSlot;
    };

    /**
     * Reconstruction COMPLÃˆTE de la grille (DOM rebuild).
     * Ã€ n'utiliser que lors d'un changement de zone ou à l'ouverture du picker.
     * Pour une simple sélection/désélection, préférer refreshCaptureTargetSlots()
     * qui met à jour en place sans détruire les nÅ“uds (sinon on casse le bubble
     * du clic vers le listener click-outside global â†’ fermeture intempestive
     * du wrapper).
     */
    GameClass.prototype.updateCaptureTargetList = function (this: ThisGame): void {
        const grid = document.getElementById('captureTargetGrid');
        const wrapper = document.getElementById('captureTargetWrapper');
        if (!grid || !wrapper) return;

        bindCaptureTargetWrapperTooltipEvents(wrapper, this);

        this._syncCaptureTargetsToCurrentZone();

        const zoneId = Number(this.currentZone) || getActiveZoneId() || 1;
        const zonePokemon = this.getReachablePokemonInZone(zoneId);

        if (this.captureTarget && this.captureTargets && !this.captureTargets.includes(this.captureTarget)) {
            this.captureTargets.push(this.captureTarget);
            this.captureTarget = null;
        }

        // Purge des cibles invalides pour la zone courante (au cas où les
        // données de zone auraient changé entre deux saves, ou pour nettoyer
        // un legacy). Mutation in-place pour préserver la référence partagée
        // avec captureTargetsByZone[zoneId].
        if (Array.isArray(zonePokemon) && zonePokemon.length > 0 && this.captureTargets) {
            for (let i = this.captureTargets.length - 1; i >= 0; i--) {
                if (!zonePokemon.includes(this.captureTargets[i])) {
                    this.captureTargets.splice(i, 1);
                }
            }
        }

        grid.innerHTML = '';

        if (!zonePokemon || zonePokemon.length === 0) {
            grid.innerHTML = `<div style="font-size:10px; color:#666; padding:10px;">${this.t('capture.targetNone')}</div>`;
        } else {
            zonePokemon.forEach((name: string) => {
                const slot = document.createElement('div');
                slot.className = 'target-slot';
                slot.setAttribute('data-name', name);
                slot.setAttribute('data-action', 'toggleCaptureTarget');
                slot.setAttribute('data-arg', name);
                slot.setAttribute('role', 'checkbox');
                slot.setAttribute('tabindex', '0');
                const displayName = captureTargetSlotLabel(this, name);
                slot.setAttribute('data-tooltip-title', displayName);
                slot.setAttribute('aria-label', displayName);

                const img = document.createElement('img');
                img.src = capturePreviewSpriteUrl(name, false);
                img.alt = displayName;
                slot.appendChild(img);

                grid.appendChild(slot);
            });
        }

        // Pose les classes selected/disabled + aria + textes (compteur, clear)
        // sur les slots fraichement créés.
        this.refreshCaptureTargetSlots();

        // NOTE : on n'OUVRE PAS le wrapper ici. Cette fonction ne fait que
        // construire/rafraîchir la grille (responsabilité unique). L'ouverture
        // du picker passe exclusivement par openCaptureTargets() — sinon, au
        // chargement du jeu, un save avec captureMode === 2 forcerait
        // l'apparition du picker dès le boot, comportement non désiré.
    };

    /**
     * Met à jour EN PLACE l'état visuel des slots existants (classes
     * selected/disabled + aria-checked) et les éléments dépendants du
     * compteur (texte limite, état du bouton clear). Ne touche PAS au
     * DOM des slots — indispensable pour ne pas casser la propagation
     * du clic en cours qui ferait fermer le wrapper.
     *
     * Ã€ utiliser après toggleCaptureTarget / clearCaptureTargets.
     */
    GameClass.prototype.refreshCaptureTargetSlots = function (this: ThisGame): void {
        const grid = document.getElementById('captureTargetGrid');
        const limitText = document.getElementById('captureTargetLimit');
        const clearBtn = document.getElementById('captureTargetClearBtn');
        if (!grid) return;

        this._syncCaptureTargetsToCurrentZone();

        const hasScope = !!(this.items && ((this.items)['scope'] || 0) > 0);
        const maxSlots = this._getCaptureMaxSlots();
        const currentSlots = this.captureTargets ? this.captureTargets.length : 0;

        if (limitText) {
            limitText.textContent = this.t('capture.targetLimit', {
                current: currentSlots,
                max: maxSlots,
                scope: hasScope ? this.t('capture.targetScopeSuffix') : ''
            });
        }

        if (clearBtn) {
            (clearBtn as HTMLButtonElement).disabled = (currentSlots === 0);
            clearBtn.setAttribute('aria-disabled', (clearBtn as HTMLButtonElement).disabled ? 'true' : 'false');
            const clearLabel = document.getElementById('captureTargetClearLabel');
            if (clearLabel) clearLabel.textContent = this.t('capture.clearAll');
            clearBtn.setAttribute('aria-label', this.t('capture.clearAllAria'));
        }

        const slots = grid.querySelectorAll('.target-slot');
        slots.forEach((slot: Element) => {
            const name = slot.getAttribute('data-name');
            if (!name) return;
            const isSelected = this.captureTargets ? this.captureTargets.includes(name) : false;
            const wouldOverflow = !isSelected && currentSlots >= maxSlots && maxSlots > 1;
            slot.classList.toggle('selected', isSelected);
            slot.classList.toggle('disabled', wouldOverflow);
            slot.setAttribute('aria-checked', isSelected ? 'true' : 'false');
            const displayName = captureTargetSlotLabel(this, name);
            slot.setAttribute('data-tooltip-title', displayName);
            slot.setAttribute('aria-label', displayName);
            const img = slot.querySelector('img');
            if (img) img.alt = displayName;
        });
    };

    GameClass.prototype.toggleCaptureTarget = function (this: ThisGame, name: string): void {
        this._syncCaptureTargetsToCurrentZone();
        if (this.captureTarget && this.captureTargets && this.captureTargets.length === 0) {
            this.captureTargets.push(this.captureTarget);
            this.captureTarget = null;
        }

        const maxSlots = this._getCaptureMaxSlots();
        const index = this.captureTargets ? this.captureTargets.indexOf(name) : -1;

        if (index > -1) {
            this.captureTargets!.splice(index, 1);
        } else {
            if (this.captureTargets && this.captureTargets.length < maxSlots) {
                this.captureTargets.push(name);
            } else if (maxSlots === 1) {
                // 1 seul slot : remplacement in-place (préserve la référence
                // partagée avec captureTargetsByZone[currentZone]).
                if (this.captureTargets) {
                    this.captureTargets.splice(0, this.captureTargets.length, name);
                }
            } else {
                if (toast) {
                    toast.warning(this.t('toast.scopeFullTitle'), this.t('toast.scopeFullBody'));
                }
                return;
            }
        }

        // IMPORTANT : refresh IN-PLACE (pas de rebuild DOM) pour ne pas
        // détacher le slot pendant que le clic remonte. Sinon le listener
        // click-outside global verrait e.target.closest('.compact-popup')
        // === null et fermerait le wrapper. Ce bug a été identifié et fixé.
        this.refreshCaptureTargetSlots();
        this.updateCaptureButtonDisplay();
        if (typeof this.saveGame === 'function') this.saveGame();
    };

    /**
     * Thin wrapper conservé pour compat. Toute la logique visuelle vit
     * désormais dans uiManager.refreshCaptureButtonUI (source unique).
     * On gère aussi la fermeture défensive du picker quand on n'est plus
     * en mode TARGET (au cas où un appelant externe modifie captureMode
     * sans passer par toggleCaptureMode).
     */
    GameClass.prototype.updateCaptureButtonDisplay = function (this: ThisGame): void {
        const wrapper = document.getElementById('captureTargetWrapper');
        if (wrapper && this.captureMode !== 2 && wrapper.classList.contains('show')) {
            wrapper.classList.remove('show');
            wrapper.style.display = 'none';
        }
        const fn = refreshCaptureButtonUI;
        if (typeof fn === 'function') {
            fn(this);
        }
    };

    // Passe la capture
    GameClass.prototype.skipCapture = function (this: ThisGame): void {
        void import('./src/bridge/captureModalBridge.js').then((m) => m.closeCaptureModal());
        const logFn = _g.logMessage as ((...args: unknown[]) => void) | undefined;
        if (logFn) logFn(this.t('log.enemySpared'));
        this.finalizeCombat(false);
    };

    // triggerAutoCatch -> logique déplacée vers combatSystem.js
    GameClass.prototype.triggerAutoCatch = function (this: ThisGame): boolean {
        const fn = triggerAutoCatchLogic;
        return typeof fn === 'function' ? fn(this) : false;
    };

    GameClass.prototype.normalizeAutoCatcherSettings = function (this: ThisGame): {
        enabled: boolean;
        catchShiny: boolean;
        catchRoamer: boolean;
        catchLegendary: boolean;
        minCatchChancePct: number;
        useMasterballActiveTargets: boolean;
        useMasterballShiny: boolean;
        useMasterballRoamer: boolean;
        useMasterballLegendary: boolean;
    } {
        if (!this.autoCatcherSettings || typeof this.autoCatcherSettings !== 'object') {
            this.autoCatcherSettings = {
                enabled: true,
                catchShiny: true,
                catchRoamer: true,
                catchLegendary: true,
                minCatchChancePct: 75,
                useMasterballActiveTargets: false,
                useMasterballShiny: true,
                useMasterballRoamer: true,
                useMasterballLegendary: false,
            };
        }
        const s = this.autoCatcherSettings as ThisGame['autoCatcherSettings'] & {
            masterballLegendaryShinyOnly?: boolean;
            useMasterballActiveTargets?: boolean;
            useMasterballShinyRoamer?: boolean;
            catchRoamer?: boolean;
            catchLegendary?: boolean;
            useMasterballShiny?: boolean;
            useMasterballRoamer?: boolean;
            useMasterballLegendary?: boolean;
        };
        s.enabled = s.enabled !== false;
        s.catchShiny = s.catchShiny !== false;

        if (s.catchRoamer === undefined) s.catchRoamer = s.catchShiny !== false;
        if (s.catchLegendary === undefined) s.catchLegendary = s.catchShiny !== false;
        s.catchRoamer = s.catchRoamer !== false;
        s.catchLegendary = s.catchLegendary !== false;

        if (s.useMasterballActiveTargets === undefined && s.useMasterballShinyRoamer === undefined
            && s.useMasterballShiny === undefined) {
            if (s.masterballLegendaryShinyOnly !== undefined) {
                if (s.masterballLegendaryShinyOnly === false) {
                    s.useMasterballActiveTargets = true;
                    s.useMasterballShinyRoamer = true;
                } else {
                    s.useMasterballActiveTargets = false;
                    s.useMasterballShinyRoamer = true;
                }
            } else {
                s.useMasterballActiveTargets = false;
                s.useMasterballShinyRoamer = true;
            }
        }
        delete s.masterballLegendaryShinyOnly;

        const legacyMbRare = s.useMasterballShinyRoamer;
        if (s.useMasterballShiny === undefined) {
            s.useMasterballShiny = legacyMbRare !== undefined ? legacyMbRare !== false : true;
        }
        if (s.useMasterballRoamer === undefined) {
            s.useMasterballRoamer = legacyMbRare !== undefined ? legacyMbRare !== false : true;
        }
        if (s.useMasterballLegendary === undefined) {
            s.useMasterballLegendary = legacyMbRare !== undefined ? legacyMbRare !== false : false;
        }
        delete s.useMasterballShinyRoamer;

        let minPct = Number(s.minCatchChancePct);
        if (!Number.isFinite(minPct)) {
            const legacyThreshold = Math.round(Number(s.pokeballThresholdPct));
            const legacyMode = typeof s.ballMode === 'string' ? s.ballMode : '';
            if (legacyMode === 'pokeball') minPct = 0;
            else if (legacyMode === 'greatball') minPct = 50;
            else if (Number.isFinite(legacyThreshold)) minPct = legacyThreshold;
            else minPct = 75;
        }
        s.minCatchChancePct = Math.max(0, Math.min(100, Math.round(minPct)));
        s.useMasterballActiveTargets = s.useMasterballActiveTargets === true;
        s.useMasterballShiny = s.useMasterballShiny !== false;
        s.useMasterballRoamer = s.useMasterballRoamer !== false;
        s.useMasterballLegendary = s.useMasterballLegendary === true;
        return {
            enabled: s.enabled !== false,
            catchShiny: s.catchShiny !== false,
            catchRoamer: s.catchRoamer !== false,
            catchLegendary: s.catchLegendary !== false,
            minCatchChancePct: s.minCatchChancePct,
            useMasterballActiveTargets: s.useMasterballActiveTargets === true,
            useMasterballShiny: s.useMasterballShiny !== false,
            useMasterballRoamer: s.useMasterballRoamer !== false,
            useMasterballLegendary: s.useMasterballLegendary === true,
        };
    };

    // UI : Mise à jour du panneau Auto-Catcher
    GameClass.prototype.updateAutoCatcherUI = function (this: ThisGame): void {
        publishBagChanged();
    };

    GameClass.prototype.toggleAutoCatch = function (this: ThisGame, setting: string): void {
        if (!this.autoCatcherSettings || typeof this.autoCatcherSettings !== 'object') {
            this.autoCatcherSettings = {
                enabled: true,
                catchShiny: true,
                catchRoamer: true,
                catchLegendary: true,
                minCatchChancePct: 75,
                useMasterballActiveTargets: false,
                useMasterballShiny: true,
                useMasterballRoamer: true,
                useMasterballLegendary: false,
            };
        }
        this.normalizeAutoCatcherSettings();
        const ac = this.autoCatcherSettings as ThisGame['autoCatcherSettings'];
        if (setting === 'enabled') ac.enabled = !(ac.enabled !== false);
        if (setting === 'shiny') ac.catchShiny = !(ac.catchShiny !== false);
        if (setting === 'roamer') ac.catchRoamer = !(ac.catchRoamer !== false);
        if (setting === 'legendary') ac.catchLegendary = !(ac.catchLegendary !== false);
        if (setting === 'masterActive') {
            ac.useMasterballActiveTargets = !(ac.useMasterballActiveTargets === true);
        }
        if (setting === 'masterShiny') {
            ac.useMasterballShiny = !(ac.useMasterballShiny !== false);
        }
        if (setting === 'masterRoamer') {
            ac.useMasterballRoamer = !(ac.useMasterballRoamer !== false);
        }
        if (setting === 'masterLegendary') {
            ac.useMasterballLegendary = !(ac.useMasterballLegendary === true);
        }
        this.updateAutoCatcherUI();
        this.saveGame();
    };

    GameClass.prototype.setAutoCatchMinChance = function (this: ThisGame, value: string | number): void {
        this.normalizeAutoCatcherSettings();
        const threshold = Math.max(0, Math.min(100, Math.round(Number(value))));
        this.autoCatcherSettings.minCatchChancePct = Number.isFinite(threshold) ? threshold : 75;
        this.updateAutoCatcherUI();
        this.saveGame();
    };

    /** @deprecated use setAutoCatchMinChance */
    GameClass.prototype.setAutoCatchPokeballThreshold = function (this: ThisGame, value: string | number): void {
        this.setAutoCatchMinChance(value);
    };

    /** @deprecated ball mode removed; no-op kept for old DOM */
    GameClass.prototype.setAutoCatchBallMode = function (this: ThisGame, _mode: string): void {
        void _mode;
        this.normalizeAutoCatcherSettings();
        this.updateAutoCatcherUI();
    };

    GameClass.prototype.isCreaturePerfect = function (this: ThisGame, creature: CreatureData | null | undefined): boolean {
        if (!creature || typeof creature !== 'object') return false;
        return (
            Number(creature.ivHP) >= 31
            && Number(creature.ivAttack) >= 31
            && Number(creature.ivSpAttack) >= 31
            && Number(creature.ivDefense) >= 31
            && Number(creature.ivSpDefense) >= 31
            && Number(creature.ivSpeed) >= 31
        );
    };

    GameClass.prototype.recordPerfectCreatureObtained = function (this: ThisGame, creature: CreatureData | null | undefined, options: Record<string, unknown> = {}): boolean {
        if (!this.isCreaturePerfect(creature!)) return false;
        if (!this.stats || typeof this.stats !== 'object') this.stats = {} as ThisGame['stats'];

        this.stats.perfectIvCount = (Number(this.stats.perfectIvCount) || 0) + 1;
        if (options.skipAchievementCheck !== true && typeof this.checkAchievements === 'function') {
            this.checkAchievements('perfectIvCount');
        }

        if (creature && creature.isShiny) {
            this.stats.perfectShinyCount = (Number(this.stats.perfectShinyCount) || 0) + 1;
            if (options.skipAchievementCheck !== true && typeof this.checkAchievements === 'function') {
                this.checkAchievements('perfectShinyCount');
            }
        }

        if (typeof this.trackHolyGrailCreature === 'function') {
            this.trackHolyGrailCreature(creature!, { skipAchievementCheck: options.skipAchievementCheck === true });
        }
        return true;
    };

    GameClass.prototype.refreshPerfectCreatureProgress = function (this: ThisGame, options: Record<string, unknown> = {}): { perfectIvOwned: number; perfectShinyOwned: number; changed: boolean } {
        if (!this.stats || typeof this.stats !== 'object') this.stats = {} as ThisGame['stats'];

        let perfectIvOwned = 0;
        let perfectShinyOwned = 0;
        const groups: CreatureData[][] = [this.playerTeam, this.storage, this.pension];
        for (const group of groups) {
            for (const creature of group) {
                if (!this.isCreaturePerfect(creature)) continue;
                perfectIvOwned++;
                if (creature.isShiny) perfectShinyOwned++;
            }
        }

        let changed = false;
        if ((Number(this.stats.perfectIvCount) || 0) < perfectIvOwned) {
            this.stats.perfectIvCount = perfectIvOwned;
            changed = true;
            if (options.skipAchievementCheck !== true && typeof this.checkAchievements === 'function') {
                this.checkAchievements('perfectIvCount');
            }
        }
        if ((Number(this.stats.perfectShinyCount) || 0) < perfectShinyOwned) {
            this.stats.perfectShinyCount = perfectShinyOwned;
            changed = true;
            if (options.skipAchievementCheck !== true && typeof this.checkAchievements === 'function') {
                this.checkAchievements('perfectShinyCount');
            }
        }

        return { perfectIvOwned, perfectShinyOwned, changed };
    };

    /** Pierre méga : espèce dans la table + 6 IV parfaits + palier Pokérus stocké â‰¥ 5 (accordé une fois, définitif). */
    GameClass.prototype.tryGrantMegaStone = function (this: ThisGame, creature: CreatureData | null | undefined, options?: Record<string, unknown>): boolean {
        if (!creature || typeof creature !== 'object') return false;
        if (creature.megaStoneUnlocked) return false;
        const getMegaCfg = getMegaEvolutionConfig;
        if (typeof getMegaCfg !== 'function' || !getMegaCfg(String(creature.name), creature)) {
            return false;
        }
        if (!this.isCreaturePerfect(creature)) return false;
        if ((Number(creature.pokerusLevel) || 0) < 5) return false;
        creature.megaStoneUnlocked = true;
        const silent = options && options.silent;
        if (!silent) {
            const smsuFn = _g.showMegaStoneUnlockModal as ((g: ThisGame, c: Record<string, unknown>) => void) | undefined;
            if (typeof smsuFn === 'function') {
                smsuFn(this, creature);
            } else if (typeof this.t === 'function') {
                toast.success(
                    this.t('mega.stoneUnlockTitle'),
                    this.t('mega.stoneUnlockBody', { name: String(creature.name) })
                );
            }
        }
        if (!silent) {
            const logFn = _g.logMessage as ((...args: unknown[]) => void) | undefined;
            if (logFn && typeof this.t === 'function') {
                logFn(this.t('mega.stoneUnlockLog', { name: String(creature.name) }));
            }
        }
        if (!(options && options.skipSave) && typeof this.saveGame === 'function') this.saveGame();
        return true;
    };

    /** Passe toutes les créatures possédées et accorde les pierres méga éligibles (rattrapage save). */
    GameClass.prototype.refreshMegaStoneGrants = function (this: ThisGame, options?: Record<string, unknown>): boolean {
        const groups: CreatureData[][] = [this.playerTeam, this.storage, this.pension];
        let any = false;
        for (const group of groups) {
            for (const c of group) {
                if (this.tryGrantMegaStone(c, { silent: true, skipSave: true })) any = true;
            }
        }
        if (any && typeof this.saveGame === 'function' && !(options && options.skipSave)) this.saveGame();
        return any;
    };

    GameClass.prototype.isHolyGrailCreature = function (this: ThisGame, creature: CreatureData | null | undefined): boolean {
        if (!creature || typeof creature !== 'object') return false;
        const hasPokerus = (typeof (creature as unknown as Record<string, unknown>).hasActivePokerus === 'function')
            ? (creature as unknown as { hasActivePokerus(): boolean }).hasActivePokerus()
            : ((Number(creature.pokerusUntil) || 0) > Date.now());
        return (
            creature.rarity === (RARITY).LEGENDARY
            && !!creature.isShiny
            && this.isCreaturePerfect(creature)
            && hasPokerus
        );
    };

    GameClass.prototype.trackHolyGrailCreature = function (this: ThisGame, creature: CreatureData | null | undefined, options: Record<string, unknown> = {}): boolean {
        if (!this.isHolyGrailCreature(creature)) return false;
        if (!this.stats || typeof this.stats !== 'object') this.stats = {} as ThisGame['stats'];
        if (!this.stats.holyGrailRegistry || typeof this.stats.holyGrailRegistry !== 'object') {
            this.stats.holyGrailRegistry = {};
        }

        const c = creature!;
        const registry = this.stats.holyGrailRegistry as Record<string, unknown>;
        const uid = String(
            c.uid
            || `${c.name || 'unknown'}_${c.rarity || 'na'}_${c.isShiny ? 1 : 0}_${c.ivHP || 0}_${c.ivAttack || 0}_${c.ivDefense || 0}_${c.ivSpeed || 0}`
        );
        if (registry[uid]) return false;

        registry[uid] = true;
        this.stats.holyGrailCount = (this.stats.holyGrailCount || 0) + 1;

        if (!options || options.skipAchievementCheck !== true) {
            this.checkAchievements('holyGrailCount');
        }
        return true;
    };

    GameClass.prototype.refreshHolyGrailProgress = function (this: ThisGame, options: Record<string, unknown> = {}): number {
        if (!this.stats || typeof this.stats !== 'object') this.stats = {} as ThisGame['stats'];
        if (!this.stats.holyGrailRegistry || typeof this.stats.holyGrailRegistry !== 'object') {
            this.stats.holyGrailRegistry = {};
        }

        let added = 0;
        const allGroups: CreatureData[][] = [this.playerTeam, this.storage, this.pension];
        allGroups.forEach((group: CreatureData[]) => {
            group.forEach((creature: CreatureData) => {
                if (this.trackHolyGrailCreature(creature, { skipAchievementCheck: true })) {
                    added++;
                }
            });
        });

        const registryCount = Object.keys(this.stats.holyGrailRegistry).length;
        if ((this.stats.holyGrailCount || 0) < registryCount) {
            this.stats.holyGrailCount = registryCount;
        }

        if (added > 0 && (!options || options.skipAchievementCheck !== true)) {
            this.checkAchievements('holyGrailCount');
        }
        return added;
    };

    GameClass.prototype.trackTowerGenerationProgress = function (this: ThisGame, enemy: CreatureData | null | undefined): void {
        if (!enemy || !enemy.name || typeof POKEMON_SPRITE_IDS === 'undefined') return;
        if (!this.stats) return;

        const dexId = Number((POKEMON_SPRITE_IDS as Record<string, number>)[String(enemy.name)] || 0);
        if (!Number.isFinite(dexId) || dexId < 1) return;

        const defeated = (this.stats.towerDexDefeated && typeof this.stats.towerDexDefeated === 'object')
            ? this.stats.towerDexDefeated
            : {};
        if (defeated[dexId]) return;

        defeated[dexId] = true;
        this.stats.towerDexDefeated = defeated;

        const prevMastery = Math.max(0, Number(this.stats.towerGenMastery) || 0);
        const mastery = getTowerGenMasteryFromDefeated(defeated);

        if (mastery > prevMastery) {
            this.stats.towerGenMastery = mastery;
            this.checkAchievements('towerGenMastery');
        }
    };

    GameClass.prototype.updatePokedexDisplay = function (this: ThisGame): void {
        if (!this.pokedex) this.pokedex = {};
        resyncPokedexUniqueDiscoveredQuests(this);
        if (this._activeMainTabId === 'pokedexTab') {
            ensureLazyTabMounted('pokedex');
        }
        publishPokedexChanged();
        if (this._activeMainTabId === 'pokedexTab') {
            this.updateCollectionBonusesDisplay();
        }
    };

    GameClass.prototype.switchPokedexSubTab = function (this: ThisGame, subTab: string): void {
        ensureLazyTabMounted('pokedex');
        if (subTab === 'collectionbonuses' && this.unlockedFeatures && !this.unlockedFeatures.collectionSubTab) {
            if (typeof toast !== 'undefined' && toast.info) {
                toast.info(this.t('toast.subtabLockedTitle'), this.t('toast.subtabLockedBody'));
            }
            return;
        }
        this.pokedexSubTab = subTab || 'pokedex';
        const pokedexView = document.getElementById('pokedexSubView-pokedex');
        const synergiesView = document.getElementById('pokedexSubView-collectionbonuses');
        const btnPokedex = document.getElementById('pokedexSubTab-pokedex');
        const btnSynergies = document.getElementById('pokedexSubTab-collectionbonuses');
        const stpsFn = _g.setTabPanelState as ((el: HTMLElement | null, active: boolean) => void) | undefined;
        if (typeof stpsFn === 'function') {
            stpsFn(pokedexView, this.pokedexSubTab === 'pokedex');
            stpsFn(synergiesView, this.pokedexSubTab === 'collectionbonuses');
        } else {
            if (pokedexView) pokedexView.style.display = this.pokedexSubTab === 'pokedex' ? '' : 'none';
            if (synergiesView) synergiesView.style.display = this.pokedexSubTab === 'collectionbonuses' ? '' : 'none';
        }
        const stbsFn = _g.setTabButtonState as ((btn: HTMLElement | null, active: boolean) => void) | undefined;
        if (typeof stbsFn === 'function') {
            stbsFn(btnPokedex, this.pokedexSubTab === 'pokedex');
            stbsFn(btnSynergies, this.pokedexSubTab === 'collectionbonuses');
        } else {
            if (btnPokedex) btnPokedex.classList.toggle('active', this.pokedexSubTab === 'pokedex');
            if (btnSynergies) btnSynergies.classList.toggle('active', this.pokedexSubTab === 'collectionbonuses');
        }
        publishPokedexChanged();
        scheduleExtrasScrollReset(() => resetPokedexTabScroll());
    };

    GameClass.prototype.updateCollectionBonusesDisplay = function (this: ThisGame): void {
        if (this._activeMainTabId === 'pokedexTab') {
            ensureLazyTabMounted('pokedex');
        }
        publishPokedexChanged();
    };


    /**
     * Trouve la rareté naturelle d'un Pokémon dans les constantes.
     */
    GameClass.prototype.getNaturalRarity = function (this: ThisGame, pokemonName: string): string {
        return speciesNaturalRarity(pokemonName);
    };

    GameClass.prototype.sortPokedex = function (this: ThisGame, sortBy: string): void {
        if (!this.pokedex) this.pokedex = {};

        if (this.pokedexSortBy === sortBy) {
            this.pokedexSortOrder = (this.pokedexSortOrder === 'asc') ? 'desc' : 'asc';
        } else {
            this.pokedexSortBy = sortBy;
            this.pokedexSortOrder = (sortBy === 'rarity' || sortBy === 'count') ? 'desc' : 'asc';
        }

        // Tri visuel géré par pokedexSnapshot (Svelte) — ne pas réécrire les clés de stockage.
        this.updatePokedexDisplay();
    };

    /**
     * Wrapper de compat : la mise à jour du badge passe désormais par
     * refreshCaptureButtonUI (gère .length, état armed-empty, classe .warn).
     */
    GameClass.prototype.updateCaptureBadge = function (this: ThisGame): void {
        const fn = refreshCaptureButtonUI;
        if (typeof fn === 'function') fn(this);
    };

    GameClass.prototype.showCaptureTooltip = function (this: ThisGame): void {
        if (this.isTooltipSuppressedOnTouch()) return;

        const tooltip = document.getElementById('captureTooltip');
        if (!tooltip) return;

        this._syncCaptureTargetsToCurrentZone();

        const isOn = (this.captureMode === 2);
        const targets = (this.captureTargets && Array.isArray(this.captureTargets)) ? this.captureTargets.slice() : [];
        if (this.captureTarget && !targets.includes(this.captureTarget)) targets.push(this.captureTarget);

        const statusSpan = document.getElementById('tooltipCaptureStatus');
        if (statusSpan) {
            statusSpan.textContent = isOn ? this.t('state.on') : this.t('state.off');
            statusSpan.className = isOn ? 'tooltip-status' : 'tooltip-status off';
        }

        // Chip-list des cibles avec sprites + noms
        const targetsBlock = document.getElementById('captureTooltipTargetsBlock');
        const targetsList = document.getElementById('captureTooltipTargetsList');
        const targetsLabel = document.getElementById('captureTooltipTargetsLabel');
        if (targetsBlock && targetsList) {
            if (isOn) {
                targetsBlock.style.display = '';
                if (targets.length === 0) {
                    if (targetsLabel) targetsLabel.textContent = this.t('capture.tooltipNoTargets');
                    targetsList.innerHTML = '';
                } else {
                    if (targetsLabel) targetsLabel.textContent = this.t('capture.tooltipTargets');
                    targetsList.innerHTML = targets.map((name: string) => {
                        const url = capturePreviewSpriteUrl(name, false);
                        const uiPnFn = uiPokemonName;
                        const display = (typeof uiPnFn === 'function') ? uiPnFn(this, name) : name;
                        return `<span class="capture-target-chip">
                            <img src="${url}" alt="" class="capture-target-chip-img">
                            <span class="capture-target-chip-name">${display}</span>
                        </span>`;
                    }).join('');
                }
            } else {
                targetsBlock.style.display = 'none';
                targetsList.innerHTML = '';
            }
        }

        // Anchorage : on cible le groupe (split button) plutôt que le bouton
        // principal seul, pour un positionnement stable au survol des deux moitiés.
        const anchor = document.getElementById('captureSelectGroup') || document.getElementById('captureModeBtn');
        if (anchor) {
            const rect = anchor.getBoundingClientRect();
            const btnCenterX = rect.left + (rect.width / 2);
            const btnCenterY = rect.top + (rect.height / 2);
            const offsetX = 50;
            const offsetY = 50;
            tooltip.style.left = `${btnCenterX + offsetX}px`;
            tooltip.style.bottom = `${(window.innerHeight - btnCenterY) + offsetY}px`;
            tooltip.style.transform = 'none';
        }

        tooltip.classList.add('show');
        if (this.isTouchUi()) this.scheduleTooltipAutoHide();
    };

    GameClass.prototype.hideCaptureTooltip = function (this: ThisGame): void {
        const tooltip = document.getElementById('captureTooltip');
        if (tooltip) {
            tooltip.classList.remove('show');
        }
    };
}
