initServiceWorkerUpdates();

type GameCtor = { prototype: Record<string, unknown> };
const GameClass: GameCtor = Game;

// Etape A ? Appliquer les 14 mixins a Game.prototype
applyCombatSystem(GameClass);
applyTalentSystem(GameClass);
applyItemSystem(GameClass);
applyEggSystem(GameClass);
applyCaptureSystem(GameClass);
applyEvolutionSystem(GameClass);
applyStatsSystem(GameClass);
applyMasterySystem(GameClass);
applyFeticheSystem(GameClass);
applyTeamSystem(GameClass);
applyUltimateSlotSystem(GameClass);
applyMiltankFarmIntroSystem(GameClass);
applyZRingSystem(GameClass);
applyDynamaxSystem(GameClass);
applyPokePelagoSystem(GameClass);
applyAcademyCoursesSystem(GameClass);
applyChampionsTowerSystem(GameClass);
applyArenaSystem(GameClass);
applyLoadoutSystem(GameClass);
applyRocketSystem(GameClass);
applyI18nSystem(GameClass);
applySettingsSystem(GameClass);

// Etape B ? Enregistrer les donnees regionales (source ESM : regionsRuntime)
const registries = getRegionRegistries();
registerJohtoData(registries);
registerHoennData(registries);
registerSinnohData(registries);
registerUnovaData(registries);
registerKalosData(registries);
registerAlolaData(registries);
registerGalarData(registries);
registerPaldeaData(registries);
syncRegionsToGlobal();
enrichEggPoolGen5To9ByFamilyRarity();

// Etape C ? Afficher l'ecran de chargement de profil, puis creer l'instance
function showBootstrapFailure(err: unknown): void {
    const message = err instanceof Error ? err.message : String(err);
    console.error('[bootstrap]', err);
    showSaveBootBootstrapFailure(message);
}

/** Warm Continue critical chunks while the player reads the slot screen. */
function prefetchContinueBootstrapChunks(): void {
    void import('./ui/index.ts');
    void import('./components/OfflineModal.svelte');
}

prefetchContinueBootstrapChunks();
initSaveSlotBoot(() => {
    void (async function onBootstrap() {
    try {
    const gameInstance = new Game();
    const runtime = gameInstance as unknown as GameRuntime;
    if (runtime.bootLoadFailed) {
        return;
    }
    setGameInstance(runtime);

    // Phase 7 ? UI bootstrap (listeners, globalThis ponts, auto-init tabs/mobile)
    await import('./ui/index.ts');
    devLog('[vite] Phase 7 ? ui/index loaded.');
    if (isVerboseDebugEnabled()) {
        attachQaGrantToGame(runtime, {
            setFeticheLevel: (level, xpPct) => setFeticheLevelForQa(runtime, level, xpPct),
        });
        devLog('[qa] game.qaGrant attached (poketime:debug=1)');
    }
    bindGameCommandHandlers(() => game as GameRuntime);
    registerGameListeners(runtime);

    const preloadCtOverrides = () => {
        const load = (globalThis as { ensureCtTablesLoaded?: () => Promise<void> }).ensureCtTablesLoaded;
        if (typeof load !== 'function') return;
        void load().catch(() => { /* guard CT réessaiera au clic */ });
    };
    if (typeof requestIdleCallback === 'function') {
        requestIdleCallback(preloadCtOverrides, { timeout: 8000 });
    } else {
        setTimeout(preloadCtOverrides, 2000);
    }

    // Etape E ? Initialiser l'event delegation et les bindings statiques
    initEventDelegation();
    initStaticHtmlBindings();

    // Etape F ? Mettre a jour l'UI initiale (tabs, avant montage Svelte)
    callGameVoid(runtime, runtime['updateUnlockedTabsUI']);

    // Phase 3 ? Pilote 2 : Header Svelte remplace le header legacy
    const headerTarget = document.querySelector('.header-afk-stack');
    if (headerTarget) {
        headerTarget.innerHTML = '';
        headerTarget.setAttribute('data-svelte-ui', '');
        mount(Header, { target: headerTarget });
        // Re-appliquer le skin header (CSS variables ont ete perdues au remplacement DOM)
        setTimeout(() => {
            callGame(runtime, runtime['selectHeaderSkin'], runtime.selectedHeaderSkin || '', { save: false, silent: true });
        }, 0);
        devLog('[vite] Pilote 2 ? Header Svelte monte.');
    }

    // Phase 3 ? Pilote 2 : ZoneSelector Svelte remplace le zone selector legacy
    const zoneTarget = document.getElementById('zoneSelector');
    if (zoneTarget) {
        zoneTarget.innerHTML = '';
        zoneTarget.setAttribute('data-svelte-ui', '');
        mount(ZoneSelector, { target: zoneTarget });
        // Re-peupler #regionSelect / #zoneSelect apres remplacement DOM Svelte
        setTimeout(() => callGameVoid(runtime, runtime['updateZoneSelector']), 0);
        setTimeout(() => updateZoneInfo(runtime), 0);
        devLog('[vite] Pilote 2 ? ZoneSelector Svelte monte.');
    }

    // Phase 3 ? Pilote 3 : TeamPanel Svelte remplace le team area legacy
    const teamTarget = document.querySelector('.team-area');
    if (teamTarget) {
        teamTarget.innerHTML = '';
        teamTarget.setAttribute('data-svelte-ui', '');
        mount(TeamPanel, { target: teamTarget });
        // Re-appliquer le rendu legacy des cartes creatures
        setTimeout(() => callGameVoid(runtime, runtime['updateTeamDisplay']), 0);
        setTimeout(() => callGameVoid(runtime, runtime['updatePensionDisplay']), 0);
        setTimeout(() => updateStorageDisplayUI(runtime), 0);
        devLog('[vite] Pilote 3 ? TeamPanel Svelte monte.');
    }

    // Phase 3 ? Pilote 4 : CombatOverlay Svelte remplace le battle screen legacy
    const battleTarget = document.querySelector('.battle-screen');
    if (battleTarget) {
        battleTarget.innerHTML = '';
        battleTarget.setAttribute('data-svelte-ui', '');

        const combatMount = document.createElement('div');
        combatMount.className = 'battle-combat-mount';
        combatMount.style.cssText = 'position:relative;width:100%;height:100%;display:flex;flex-direction:column;flex:1;min-height:0;';
        battleTarget.appendChild(combatMount);
        mount(CombatOverlay, { target: combatMount });

        const farmMount = document.createElement('div');
        farmMount.className = 'miltank-farm-mount';
        battleTarget.appendChild(farmMount);
        mount(MiltankFarmOverlay, { target: farmMount });

        // Re-initialiser le cache DOM du combat (references getElementById)
        setTimeout(() => {
            initUiCacheUI(runtime);
            refreshCombatUiI18nCache(runtime);
            updateCombatDisplayUI(runtime);
        }, 0);
        devLog('[vite] Pilote 4 ? CombatOverlay + MiltankFarmOverlay montes.');
    }

    // Phase 3 ? SaveManagerModal (always in DOM)
    const saveMgrTarget = document.getElementById('saveManagerModal');
    if (saveMgrTarget) {
        saveMgrTarget.innerHTML = '';
        saveMgrTarget.setAttribute('data-svelte-ui', '');
        mount(SaveManagerModal, { target: saveMgrTarget });
        devLog('[vite] Extension ? SaveManagerModal Svelte monte.');
    }

    const mountTabPanel = (tabId: string, ComponentType: Component) => {
        const target = document.getElementById(tabId);
        if (!target) return;
        target.innerHTML = '';
        target.setAttribute('data-svelte-ui', '');
        mount(ComponentType, { target });
    };

  // Lazy tab panels ? first visit via switchTab ? ensureLazyTabMounted (navigation.js)
    registerLazyTabMount('boutique', () => mountTabPanel('boutiqueTab', ShopPanel));
    registerLazyTabMountAsync('sacados', 'sacadosTab', () => import('./components/BagPanel.svelte'));
    registerLazyTabMountAsync('pokedex', 'pokedexTab', () => import('./components/PokedexPanel.svelte'));
    registerLazyTabMountAsync('quests', 'questsTab', () => import('./components/QuestPanel.svelte'));
    registerLazyTabMountAsync('tower', 'towerTab', () => import('./components/TowerPanel.svelte'));
    registerLazyTabMountAsync('expeditions', 'expeditionsTab', () => import('./components/ExpeditionPanel.svelte'));
    registerLazyTabMountAsync('teamrocket', 'teamrocketTab', () => import('./components/RocketPanel.svelte'));
    registerLazyTabMountAsync('arenas', 'arenasTab', () => import('./components/ArenaPanel.svelte'));

    for (const tabId of [
        'sacadosTab',
        'pokedexTab',
        'questsTab',
        'towerTab',
        'expeditionsTab',
        'teamrocketTab',
        'arenasTab',
    ]) {
        const el = document.getElementById(tabId);
        if (el) el.innerHTML = '';
    }

    (globalThis as Record<string, unknown>).ensureLazyTabMounted = ensureLazyTabMounted;
    ensureLazyTabMounted('boutique');

    devLog('[vite] Extensions ? lazy tab mounts registered (boutique eager).');

    // Phase 6 — all modals lazy (empty shells at boot; mount on first open)
    const lazyModalShellIds = [
        'statsModal',
        'creatureModal',
        'relicModal',
        'farmingMetricsModal',
        'martAutoPurchaseModal',
        'dailyLoginModal',
        'masteryModal',
        'miltankFarmModal',
        'berryTreeModal',
        'ultimateSlotModal',
        'logModal',
        'synergyListModal',
        'captureModalBody',
        'eggHatchModal',
        'evolutionModal',
        'zoneTierModal',
        'profChenWikiModal',
    ];
    for (const id of lazyModalShellIds) {
        const shell = document.getElementById(id);
        if (shell) shell.innerHTML = '';
    }
    // offlineModal: keep index.html shell — auto-opens at load before user interaction.
    const captureShell = document.getElementById('captureModal');
    if (captureShell) {
        captureShell.innerHTML =
            '<div class="stats-content capture-modal-content" data-action="stopPropagation" data-action-stop>'
            + '<div id="captureModalBody" class="capture-modal-body"></div></div>';
    }

    mountLazyModalComponentAsync('statsModal', 'statsModal', () => import('./components/StatsModal.svelte'));
    mountLazyModalComponentAsync('creatureModal', 'creatureModal', () => import('./components/CreatureModal.svelte'));
    mountLazyModalComponentAsync('relicModal', 'relicModal', () => import('./components/RelicModal.svelte'));
    mountLazyModalComponentAsync('farmingMetricsModal', 'farmingMetricsModal', () => import('./components/FarmingMetricsModal.svelte'));
    mountLazyModalComponentAsync('martAutoPurchaseModal', 'martAutoPurchaseModal', () => import('./components/shop/MartAutoPurchaseModal.svelte'));
    mountLazyModalComponentAsync('dailyLoginModal', 'dailyLoginModal', () => import('./components/DailyLoginCalendarModal.svelte'));
    mountLazyModalComponentAsync('masteryModal', 'masteryModal', () => import('./components/MasteryModal.svelte'));
    const academyMount = document.getElementById('academyCoursesMount');
    if (academyMount) {
        const { default: AcademyCoursesPanel } = await import('./components/AcademyCoursesPanel.svelte');
        mount(AcademyCoursesPanel, { target: academyMount });
    }
    mountLazyModalComponentAsync('zoneMapModal', 'zoneMapModal', () => import('./components/ZoneMapModal.svelte'));
    mountLazyModalComponentAsync('miltankFarmModal', 'miltankFarmModal', () => import('./components/MiltankFarmModal.svelte'));
    mountLazyModalComponentAsync('berryTreeModal', 'berryTreeModal', () => import('./components/BerryTreeModal.svelte'));
    mountLazyModalComponentAsync('pokePelagoModal', 'pokePelagoModal', () => import('./components/PokePelagoModalShell.svelte'));
    mountLazyModalComponentAsync('ultimateSlotModal', 'ultimateSlotModal', () => import('./components/UltimateSlotModal.svelte'));
    mountLazyModalComponentAsync('logModal', 'logModal', () => import('./components/LogModal.svelte'));
    mountLazyModalComponentAsync('synergyListModal', 'synergyListModal', () => import('./components/SynergyListModal.svelte'));
    mountLazyModalComponentAsync('captureModal', 'captureModalBody', () => import('./components/CaptureModal.svelte'));
    mountLazyModalComponentAsync('eggHatchModal', 'eggHatchModal', () => import('./components/EggHatchModal.svelte'));
    mountLazyModalComponentAsync('evolutionModal', 'evolutionModal', () => import('./components/EvolutionModal.svelte'));
    mountLazyModalComponentAsync('zoneTierModal', 'zoneTierModal', () => import('./components/ZoneTierModal.svelte'));
    mountLazyModalComponentAsync('offlineModal', 'offlineModal', () => import('./components/OfflineModal.svelte'));
    mountLazyModalComponentAsync('profChenWikiModal', 'profChenWikiModal', () => import('./components/ProfChenWikiModal.svelte'));
    (globalThis as Record<string, unknown>).ensureLazyModalMounted = ensureLazyModalMounted;
    (globalThis as Record<string, unknown>).ensureLazyModalReady = ensureLazyModalReady;
    devLog('[vite] Phase 6 — modals (14 lazy shells).');

    const rocketCasinoRoot = document.createElement('div');
    rocketCasinoRoot.id = 'rocketCasinoModalRoot';
    document.body.appendChild(rocketCasinoRoot);
    mount(RocketCasinoModal, { target: rocketCasinoRoot });
    devLog('[vite] RocketCasinoModal monte (hors panneau onglet).');

    const rocketContractRoot = document.createElement('div');
    rocketContractRoot.id = 'rocketContractModalRoot';
    document.body.appendChild(rocketContractRoot);
    mount(RocketContractSelectModal, { target: rocketContractRoot });
    devLog('[vite] RocketContractSelectModal monte.');

    const rocketMiniBarDockRoot = document.createElement('div');
    rocketMiniBarDockRoot.id = 'rocketCombatMiniBarDockRoot';
    document.body.appendChild(rocketMiniBarDockRoot);
    mount(RocketCombatMiniBarHost, { target: rocketMiniBarDockRoot, props: { placement: 'dock' } });
    devLog('[vite] RocketCombatMiniBar dock monte (mobile, hors panneau combat).');

    devLog('[vite] Phase 3 ? UI Svelte 5 bootstrap complete.');

    // Storage/recycler bindings MUST run after Svelte components render the DOM elements
    initLateHtmlBindings();

    // Phase 5.4 ? Hydrate Svelte stores from game data (sync team to avoid debounce delay)
    callGameVoid(runtime, runtime['updatePlayerStatsDisplay']);
    facade.invalidateSnapshotCache();
    const snap = facade.getSnapshot();
    if (snap) {
        hydrateTeamStore(snap.team);
        facade.publish({ type: GameEventType.RESOURCES_CHANGED, resources: snap.resources });
        facade.publish({ type: GameEventType.TEAM_CHANGED, team: snap.team });
        facade.publish({ type: GameEventType.ZONE_CHANGED, zone: snap.zone.currentZone, region: snap.zone.currentRegion, maxReachedZone: snap.zone.maxReachedZone, zoneName: snap.zone.zoneName });
    }
    callGameVoid(runtime, runtime['updateTeamDisplay']);
    callGameVoid(runtime, runtime['updateStorageDisplay']);

    if (runtime.miltankFarmState?.unlocked || runtime.unlockedFeatures?.miltankFarm) {
        publishMiltankFarmChanged();
    }
    if (runtime.pokePelagoState?.unlocked || runtime.unlockedFeatures?.pokePelago) {
        publishPokePelagoChanged({ force: true });
    }
    publishFeticheChanged({ force: true });

    // Phase 6 fix: re-initialize edge-scroll + tab accessibility + mobile layout
    // AFTER Svelte mounts replace the DOM elements. The auto-init in src/ui/index.ts
    // ran on the pre-Svelte DOM which is now destroyed.
    initSubTabEdgeAutoScroll();
    initTabsEdgeAutoScroll();
    initializeTabAccessibility();
    initMobileLayout();
    initMobileTouchListeners();

    const activeTabEl = document.querySelector('.tab-content.active');
    const tabId = String(runtime._activeMainTabId || activeTabEl?.id || 'boutiqueTab');
    syncMainTabState(tabId.replace(/Tab$/, '') || 'boutique');

    // Langue écran profils : réappliquer après montage Svelte (même pipeline que SET_LANGUAGE / menu Options).
    callGame(runtime, runtime['setLanguage'], getSaveBootLanguage(), { silent: true, force: true, save: false });
    refreshUpdateBannerLabels();
    // Close boot modal before offline catch-up so Continue feels ready once UI is mounted.
    finishSaveSlotBootstrap();
    await ensureLazyModalReady('offlineModal');
    callGameVoid(runtime, runtime['flushDeferredLoadOfflineCatchup']);
    callGameVoid(runtime, runtime['flushDeferredStartupNotifications']);
    } catch (err) {
        showBootstrapFailure(err);
    }
    })();
});
