/**
 * Promo code normalization and hashing (shared by game logic and scripts/hash-promo-code.mjs).
 */

import { sha256Hex } from './sha256Hex.ts';

export const PROMO_HASH_SALT = 'poketime-promo-v1';

const MAX_PROMO_INPUT_LEN = 32;

export function normalizePromoInput(raw: unknown): string {
  if (raw == null) return '';
  const base = typeof raw === 'string' ? raw : typeof raw === 'number' ? String(raw) : '';
  const s = base.trim().toUpperCase().replace(/[\s-]+/g, '');
  return s.length > MAX_PROMO_INPUT_LEN ? s.slice(0, MAX_PROMO_INPUT_LEN) : s;
}

export function hashPromoInputSync(normalized: string): string {
  return sha256Hex(`${PROMO_HASH_SALT}:${normalized}`);
}
