/** Quest-token cost for player mastery full reset (after free lifetime resets). */

import { BALANCE } from '../../constants/balance/balance.js';

const cfg = BALANCE.MASTERY_RESET as {
    freeResets: number;
    tokenBaseCost: number;
    tokenEscalation: number;
};

/** Cost for the next reset after `resetsDone` resets already performed. */
export function getMasteryResetCost(resetsDone: number): number {
    const done = Math.max(0, Math.floor(Number(resetsDone) || 0));
    const freeResets = Math.max(0, Math.floor(Number(cfg.freeResets) || 0));
    if (done < freeResets) return 0;
    const paidIndex = done - freeResets;
    const base = Math.max(0, Math.floor(Number(cfg.tokenBaseCost) || 0));
    const escalation = Math.max(1, Number(cfg.tokenEscalation) || 1);
    return Math.floor(base * Math.pow(escalation, paidIndex));
}

export interface MasteryResetRequirements {
    cost: number;
    canAfford: boolean;
    isFree: boolean;
}

export function getMasteryResetRequirements(
    resetsDone: number,
    questTokens: number,
): MasteryResetRequirements {
    const cost = getMasteryResetCost(resetsDone);
    const tokens = Math.max(0, Math.floor(Number(questTokens) || 0));
    return {
        cost,
        canAfford: cost <= 0 || tokens >= cost,
        isFree: cost <= 0,
    };
}
