/**
 * Offline combat simulation accumulator — shared by game.ts and gameCombatSystem.
 */

export interface OfflineSimStats {
    simulated: number;
    won: number;
    lost: number;
    xp: number;
    money: number;
    items: Record<string, number>;
    captured: number;
    capturedPokemonList: Record<string, unknown>[];
    offlineCapturedTypes: Record<string, boolean>;
    legendariesObtainedOffline: number;
    [key: string]: unknown;
}

export interface OfflineSimCaptured {
    wasNewDiscovery?: boolean;
    wasNewShinyDiscovery?: boolean;
    isShiny?: boolean;
    shiny?: boolean;
    rarity?: string;
    creatureType?: string;
    secondaryType?: string;
    [key: string]: unknown;
}

export type OfflineSimResult = {
    xp?: number;
    money?: number;
    items?: Record<string, number>;
    captured?: OfflineSimCaptured;
} | null;

export function mergeSimulationResult(stats: OfflineSimStats, result: OfflineSimResult): void {
    stats.simulated++;
    if (result) {
        stats.won++;
        stats.xp += result.xp || 0;
        stats.money += result.money || 0;
        if (result.items) {
            for (const [k, v] of Object.entries(result.items)) {
                stats.items[k] = (stats.items[k] || 0) + v;
            }
        }
        if (result.captured) {
            stats.captured++;
            const cap = result.captured;
            const isHighlight = !!(
                cap.wasNewDiscovery
                || cap.wasNewShinyDiscovery
                || cap.isShiny
                || cap.shiny
                || cap.rarity === 'legendary'
                || cap.rarity === 'epic'
            );
            if (isHighlight || stats.capturedPokemonList.length < 50) {
                stats.capturedPokemonList.push(cap);
            }
            if (cap.creatureType) {
                stats.offlineCapturedTypes[cap.creatureType] = true;
            }
            if (cap.secondaryType) {
                stats.offlineCapturedTypes[cap.secondaryType] = true;
            }
            if (cap.rarity === 'legendary') {
                stats.legendariesObtainedOffline = (stats.legendariesObtainedOffline || 0) + 1;
            }
        }
    } else {
        stats.lost++;
    }
}
