<script lang="ts">
  import { onMount } from 'svelte';
  import { zone } from '../stores/zone.svelte.ts';
  import { miltankFarm } from '../stores/miltankFarm.svelte.ts';
  import { pokePelago } from '../stores/pokePelago.svelte.ts';
  import { ui as uiStore } from '../stores/ui.svelte.ts';
  import { GameEventType } from '../bus/events.ts';
  import { facade } from '../bus/gameFacade.ts';
  import { game } from '../../gameManager.ts';
  import { getRegions } from '../lib/regionsRuntime.ts';
  import { _getAvailableRegionIds, _isRegionUnlocked, ensureRegionProgressStateLogic } from '../../zoneSystem.ts';
  import { updateZoneInfo } from '../ui/zoneDisplay.ts';
  import { useFacadeSubscription } from '../lib/useFacadeSubscription.ts';
  import { useGameLanguageTick } from '../lib/useGameLanguageTick.svelte.ts';
  import { showGameTooltip, hideGameTooltip } from '../ui/scheduleTooltipHelpers.ts';
  import { isPokePelagoHeaderVisible } from '../lib/pokePelagoLogic.ts';

  const { trackGameLanguage } = useGameLanguageTick();

  function refreshZoneInfoPanel(): void {
    if (game) updateZoneInfo(game);
  }

  /** Badges mutate game in place; bump tick so region lock state re-derives after arena wins. */
  let regionUnlockTick = $state(0);
  /** Tower mode toggles via legacy game mutations — bump on zone/combat events for Svelte. */
  let towerModeTick = $state(0);
  let lastTowerActive: boolean | null = null;

  function onArenaChanged(): void {
    regionUnlockTick += 1;
    refreshZoneInfoPanel();
  }

  function onTowerModeMaybeChanged(): void {
    lastTowerActive = !!game?.towerState?.isActive;
    towerModeTick += 1;
    refreshZoneInfoPanel();
    closeIslesMenu();
  }

  function onCombatStateChangedForTower(): void {
    const active = !!game?.towerState?.isActive;
    if (active === lastTowerActive) return;
    lastTowerActive = active;
    towerModeTick += 1;
    closeIslesMenu();
  }

  useFacadeSubscription(
    GameEventType.ARENA_CHANGED,
    onArenaChanged,
  );

  useFacadeSubscription(
    GameEventType.ZONE_CHANGED,
    onTowerModeMaybeChanged,
  );

  useFacadeSubscription(
    GameEventType.COMBAT_STATE_CHANGED,
    onCombatStateChangedForTower,
  );

  onMount(() => {
    refreshZoneInfoPanel();
    return () => clearIslesCloseTimer();
  });

  function t(key: string, fallback: string, vars: Record<string, string> = {}): string {
    if (!game?.t) return fallback;
    const got = game.t(key, vars);
    return got && got !== key ? got : fallback;
  }

  let regionOptions = $derived.by(() => {
    void regionUnlockTick;
    if (!game) return [];
    ensureRegionProgressStateLogic(game);
    const regions = getRegions();
    return _getAvailableRegionIds().map((id) => ({
      id,
      label: (regions[id]?.name ?? id).toUpperCase(),
      disabled: !_isRegionUnlocked(game, id),
    }));
  });

  let mapTooltip = $derived.by(() => {
    trackGameLanguage();
    void zone.currentRegion;
    const regions = getRegions();
    const regionName = regions[zone.currentRegion]?.name ?? zone.currentRegion;
    return {
      title: t('zone.mapButtonTitleRegion', 'Ouvrir la carte de {region}', { region: regionName }),
      body: t('zone.mapButtonBody', 'Cliquez pour choisir une zone sur la carte de la région.'),
      aria: t('zone.mapButtonTitle', 'Ouvrir la carte de la région'),
    };
  });

  let farmVisible = $derived(
    !!(miltankFarm.snapshot.unlocked || game?.unlockedFeatures?.miltankFarm),
  );

  let farmActive = $derived(!!miltankFarm.snapshot.farmViewActive);

  let towerActive = $derived.by(() => {
    void towerModeTick;
    void zone.zoneName;
    return !!game?.towerState?.isActive;
  });

  let farmActionBadgeCount = $derived(miltankFarm.snapshot.farmActionBadgeCount);
  let farmActionBadgeTitle = $derived(miltankFarm.snapshot.farmActionBadgeTitle);

  let farmTooltip = $derived.by(() => {
    trackGameLanguage();
    return {
      title: t('miltankFarm.openTitle', 'Ferme Écrémeuh', {}),
      body: t('miltankFarm.openBody', 'Nourris Écrémeuh et récupère du Lait Meumeu.', {}),
      aria: t('miltankFarm.openAria', 'Ouvrir la ferme Écrémeuh'),
      label: t('miltankFarm.openBtn', 'Ferme'),
    };
  });

  function onFarmBtnEnter(e: MouseEvent | FocusEvent): void {
    if (!farmActive && farmActionBadgeCount > 0 && farmActionBadgeTitle) {
      showGameTooltip(e, '', farmActionBadgeTitle);
      return;
    }
    showGameTooltip(e, farmTooltip.title, farmTooltip.body);
  }

  let pelagoVisible = $derived(
    isPokePelagoHeaderVisible(
      !!(pokePelago.snapshot.unlocked || game?.pokePelagoState?.unlocked),
      !!game?.unlockedFeatures?.pokePelago,
    ),
  );

  let pelagoClaimableCount = $derived(pokePelago.snapshot.claimableCount);
  let pelagoModalOpen = $derived(uiStore.openModals.has('pokePelagoModal'));

  let pelagoTooltip = $derived.by(() => {
    trackGameLanguage();
    return {
      title: t('pokePelago.openTitle', 'Poké Pelago', {}),
      body: t('pokePelago.openBody', 'Assignez des Pokémon du stockage aux îles pour des récompenses idle.', {}),
      aria: t('pokePelago.openAria', 'Ouvrir Poké Pelago'),
      label: t('pokePelago.openBtn', 'Pelago'),
    };
  });

  let selectorMode = $derived(pelagoVisible);

  let islesMenuOpen = $state(false);
  let islesCloseTimer: ReturnType<typeof setTimeout> | null = null;
  /** Avoid focusin→open then click→close flicker on the same tap. */
  let skipNextIslesToggle = false;

  let islesLabel = $derived.by(() => {
    trackGameLanguage();
    return selectorMode ? t('farmPelago.islesBtn', 'Îles') : farmTooltip.label;
  });

  let islesAria = $derived.by(() => {
    trackGameLanguage();
    return selectorMode
      ? t('farmPelago.islesAria', 'Ferme et Poké Pelago')
      : farmTooltip.aria;
  });

  let combinedBadge = $derived(
    (farmVisible && !farmActive ? farmActionBadgeCount : 0)
    + (pelagoVisible && !pelagoModalOpen ? pelagoClaimableCount : 0),
  );

  function clearIslesCloseTimer(): void {
    if (islesCloseTimer != null) {
      clearTimeout(islesCloseTimer);
      islesCloseTimer = null;
    }
  }

  function closeIslesMenu(): void {
    clearIslesCloseTimer();
    skipNextIslesToggle = false;
    islesMenuOpen = false;
  }

  function onIslesEnter(e: FocusEvent | MouseEvent): void {
    clearIslesCloseTimer();
    if (!islesMenuOpen) {
      islesMenuOpen = true;
      // Only skip the following click when focusin opened the menu (pointer tap race).
      if (e.type === 'focusin') {
        skipNextIslesToggle = true;
        queueMicrotask(() => {
          skipNextIslesToggle = false;
        });
      }
    }
  }

  function onIslesLeave(): void {
    clearIslesCloseTimer();
    islesCloseTimer = setTimeout(() => {
      islesMenuOpen = false;
      islesCloseTimer = null;
    }, 120);
  }

  function toggleIslesMenu(e: MouseEvent): void {
    e.preventDefault();
    clearIslesCloseTimer();
    if (skipNextIslesToggle) {
      skipNextIslesToggle = false;
      islesMenuOpen = true;
      return;
    }
    islesMenuOpen = !islesMenuOpen;
  }
</script>

<div class="zone-selector-header">
  {#if farmVisible || pelagoVisible}
    <div
      class="farm-pelago-select"
      class:farm-pelago-select--tower={towerActive}
      class:is-open={islesMenuOpen}
      role="group"
      aria-label={selectorMode ? islesAria : undefined}
      onmouseenter={selectorMode ? onIslesEnter : undefined}
      onmouseleave={selectorMode ? onIslesLeave : undefined}
      onfocusin={selectorMode ? onIslesEnter : undefined}
      onfocusout={selectorMode ? onIslesLeave : undefined}
    >
      {#if selectorMode}
        <button
          type="button"
          id={towerActive ? 'miltankFarmTowerBtn' : 'miltankFarmBtn'}
          class={towerActive ? 'miltank-farm-tower-btn farm-pelago-select-trigger' : 'zone-map-btn miltank-farm-btn farm-pelago-select-trigger'}
          class:farm-view-active={farmActive}
          aria-expanded={islesMenuOpen}
          aria-haspopup="menu"
          aria-label={islesAria}
          onclick={toggleIslesMenu}
        >
          <span id={towerActive ? 'miltankFarmTowerBtnLabel' : 'miltankFarmBtnLabel'}>{islesLabel}</span>
          {#if combinedBadge > 0}
            <span class="tab-badge tab-badge-claim miltank-farm-action-badge">{combinedBadge}</span>
          {/if}
        </button>
        {#if islesMenuOpen}
          <div class="farm-pelago-menu" role="menu">
            {#if farmVisible}
              <button
                type="button"
                role="menuitem"
                class={towerActive
                  ? 'miltank-farm-tower-btn farm-pelago-menu-item'
                  : 'zone-map-btn miltank-farm-btn farm-pelago-menu-item'}
                class:farm-view-active={farmActive}
                aria-label={farmTooltip.aria}
                data-action="toggleMiltankFarmView"
                onclick={closeIslesMenu}
              >
                <span>{farmTooltip.label}</span>
                {#if farmActionBadgeCount > 0 && !farmActive}
                  <span class="tab-badge tab-badge-claim miltank-farm-action-badge">{farmActionBadgeCount}</span>
                {/if}
              </button>
            {/if}
            <button
              type="button"
              role="menuitem"
              id="pokePelagoBtn"
              class={towerActive
                ? 'miltank-farm-tower-btn farm-pelago-menu-item'
                : 'zone-map-btn poke-pelago-btn farm-pelago-menu-item'}
              aria-label={pelagoTooltip.aria}
              data-action="openPokePelagoModal"
              onclick={closeIslesMenu}
            >
              <span id="pokePelagoBtnLabel">{pelagoTooltip.label}</span>
              {#if pelagoClaimableCount > 0 && !pelagoModalOpen}
                <span class="tab-badge tab-badge-claim poke-pelago-action-badge">{pelagoClaimableCount}</span>
              {/if}
            </button>
          </div>
        {/if}
      {:else if towerActive}
        <button type="button" id="miltankFarmTowerBtn" class="miltank-farm-tower-btn"
          class:farm-view-active={farmActive}
          aria-label={farmTooltip.aria}
          aria-pressed={farmActive}
          data-tooltip-variant="miltank-farm"
          onmouseenter={onFarmBtnEnter}
          onmouseleave={hideGameTooltip}
          onfocus={onFarmBtnEnter}
          onblur={hideGameTooltip}
          data-action="toggleMiltankFarmView">
          <span id="miltankFarmTowerBtnLabel">{farmTooltip.label}</span>
          {#if farmActionBadgeCount > 0 && !farmActive}
            <span class="tab-badge tab-badge-claim miltank-farm-action-badge">{farmActionBadgeCount}</span>
          {/if}
        </button>
      {:else}
        <button type="button" id="miltankFarmBtn" class="zone-map-btn miltank-farm-btn"
          class:farm-view-active={farmActive}
          aria-label={farmTooltip.aria}
          aria-pressed={farmActive}
          data-tooltip-variant="miltank-farm"
          onmouseenter={onFarmBtnEnter}
          onmouseleave={hideGameTooltip}
          onfocus={onFarmBtnEnter}
          onblur={hideGameTooltip}
          data-action="toggleMiltankFarmView">
          <span id="miltankFarmBtnLabel">{farmTooltip.label}</span>
          {#if farmActionBadgeCount > 0 && !farmActive}
            <span class="tab-badge tab-badge-claim miltank-farm-action-badge">{farmActionBadgeCount}</span>
          {/if}
        </button>
      {/if}
    </div>
  {/if}
  {#if !towerActive}
    <button type="button" id="zoneMapBtn" class="zone-map-btn"
      aria-expanded={false} aria-controls="zoneMapModal"
      aria-label={mapTooltip.aria}
      onmouseenter={(e) => showGameTooltip(e, mapTooltip.title, mapTooltip.body)}
      onmouseleave={hideGameTooltip}
      onfocus={(e) => showGameTooltip(e, mapTooltip.title, mapTooltip.body)}
      onblur={hideGameTooltip}
      onclick={() => facade.dispatch({ type: 'OPEN_ZONE_MAP' })}>
      <span id="zoneMapBtnLabel">Carte</span>
    </button>
    <label for="regionSelect" class="zone-map-label">Region</label>
    <select id="regionSelect" class="region-select"
      value={zone.currentRegion}
      onchange={(e) => {
        const target = e.target as HTMLSelectElement;
        closeIslesMenu();
        facade.dispatch({ type: 'CHANGE_REGION', region: target.value });
      }}
    >
      {#each regionOptions as region (region.id)}
        <option value={region.id} disabled={region.disabled}>{region.label}</option>
      {/each}
    </select>
  {/if}
  <div class="zone-info" id="zoneInfo"></div>
</div>
<select id="zoneSelect" aria-hidden="true" tabindex="-1" class="zone-select-hidden"></select>
