/// <reference types="svelte" />
import { facade } from '@bus/facade';
import { GameEventType as Evt } from '../bus/events.js';
import type { ArenaPanelUiSnapshot, ArenaSnapshot } from '../bus/snapshots.js';

const EMPTY_UI: ArenaPanelUiSnapshot = {
  language: 'fr',
  title: 'Arènes de Combat',
  subGyms: 'Arènes',
  subElite: 'Conseil des 4',
  subTabsAriaLabel: 'Sous-sections arènes',
};

const EMPTY: ArenaSnapshot = {
  ui: EMPTY_UI,
  trainerCardTitle: '',
  badgesHtml: '',
  arenasHtml: '',
  eliteFourHtml: '',
  eliteFourTrainers: [],
};

class ArenaStore {
  snapshot: ArenaSnapshot = $state(EMPTY);
}

export const arena = new ArenaStore();

facade.subscribe(Evt.ARENA_CHANGED, (evt) => {
  if (!('arena' in evt)) return;
  arena.snapshot = evt.arena;
});
