<script lang="ts">
  import { resources } from '../stores/resources.svelte.ts';
  import { game } from '../../gameManager.js';
  import type { GameRuntime } from '../types/game.js';
  import ResourceBar from './ResourceBar.svelte';

  let moneyLabel = $derived.by((): string => {
    const gm = game as GameRuntime | null;
    if (!gm) return 'Dollars';
    void gm.language;
    return gm.t?.('header.resourceMoney') ?? 'Dollars';
  });

  let tokensLabel = $derived.by((): string => {
    const gm = game as GameRuntime | null;
    if (!gm) return 'Jetons';
    void gm.language;
    return gm.t?.('header.resourceTokens') ?? 'Jetons';
  });

  let marksLabel = $derived.by((): string => {
    const gm = game as GameRuntime | null;
    if (!gm) return 'Marques';
    void gm.language;
    return gm.t?.('header.resourceMarks') ?? 'Marques';
  });
</script>

<div class="resources-group">
  <ResourceBar label={moneyLabel} value={resources.pokedollars} icon="img/pokedollars.png" id="headerStatMoney" />
  <ResourceBar label={tokensLabel} value={resources.questTokens} icon="https://raw.githubusercontent.com/msikma/pokesprite/master/items/key-item/magma-emblem.png" id="headerStatTokens" />
  <ResourceBar label={marksLabel} value={resources.triumphMarks} icon="https://raw.githubusercontent.com/msikma/pokesprite/master/items/valuable-item/relic-crown.png" id="headerStatMarques" />
</div>
