    getVersionTokenFromAssets(this: GameRuntime) {
        if (typeof document === 'undefined') return '';
        const withVersion = document.querySelector('script[src*="?v="], link[href*="?v="]');
        if (!withVersion) return '';
        const raw = withVersion.getAttribute('src') || withVersion.getAttribute('href') || '';
        const m = raw.match(/[?&]v=([^&]+)/);
        const token = m?.[1];
        return token ? decodeURIComponent(token) : '';
    }

    getMenuVersionText(this: GameRuntime) {
        const version = coerceStr(this.appVersion, '').trim();
        const build = Number.isFinite(Number(this.appBuild)) ? Number(this.appBuild) : null;
        if (version && build !== null) return `v${version} (build ${build})`;
        if (version) return `v${version}`;
        const token = coerceStr(this.appCacheToken, '').trim();
        return token ? `v${token}` : 'vdev';
    }

    updateMenuVersionLabel(this: GameRuntime) {
        const versionEl = document.getElementById('menuVersionLabel');
        if (versionEl) versionEl.textContent = this.getMenuVersionText();
    }

    async loadRuntimeVersionInfo(this: GameRuntime) {
        if (typeof fetch !== 'function') return;
        try {
            const response = await fetch(`VERSION.json?t=${Date.now()}`, { cache: 'no-store' });
            if (!response.ok) return;
            const data: unknown = await response.json();
            if (data && typeof data === 'object') {
                const versionInfo = data as { version?: unknown; build?: unknown; cacheToken?: unknown };
                if (typeof versionInfo.version === 'string' && versionInfo.version.trim()) {
                    this.appVersion = versionInfo.version.trim();
                }
                if (versionInfo.build !== undefined && versionInfo.build !== null && versionInfo.build !== '') {
                    this.appBuild = coerceStr(versionInfo.build, '');
                }
                if (typeof versionInfo.cacheToken === 'string' && versionInfo.cacheToken.trim()) {
                    this.appCacheToken = versionInfo.cacheToken.trim();
                }
            }
        } catch (_) {
            // Fallback silencieux: le label reste aliment� par le token d'assets.
        }
        this.updateMenuVersionLabel();
    }

    initRuntimeVersionInfo(this: GameRuntime) {
        const token = this.getVersionTokenFromAssets();
        if (token) {
            this.appCacheToken = token;
            if (!this.appVersion || this.appVersion === '0.1.0') {
                const semverLike = token.match(/^(\d+\.\d+\.\d+)/);
                if (semverLike) this.appVersion = semverLike[1];
            }
        }
        this.updateMenuVersionLabel();
        void this.loadRuntimeVersionInfo();
    }

