    // S?CURIT? : V?rifie l'int?grit? de la base de donn?es (Compatible Zones Complexes)
    runSanityCheck(this: GameRuntime) {
        debugLog('--- Diagnostic des Donnees ---');
        let errors = 0;

        // 1. V?rifier les Zones
        if (!ZONES) { debugWarn('ZONES not available for diagnostic'); return; }
        for (const [zoneId, zone] of Object.entries(ZONES)) {

            // ? FIX : On utilise le helper pour aplatir la zone avant de la scanner
            const enemies = this.getAllPokemonInZone(zoneId);

            if (!enemies || enemies.length === 0) {
                if (isHubZoneWithoutWildEncounters(zone)) continue;
                debugError(`Zone ${zoneId} (${zone.name}) est vide ou mal configur?e !`);
                errors++;
                continue;
            }

            enemies.forEach((name: string) => {
                if (!POKEMON_BASE_STATS[resolveRosterSpeciesKey(name)]) {
                    debugWarn(`[WARN] MISSING STATS: ${name} (Zone ${zoneId})`);
                    errors++;
                }
                if (!(name in POKEMON_SPRITE_IDS)) {
                    debugWarn(`[WARN] MISSING SPRITE ID: ${name}`);
                }
            });
        }

        // 2. V?rifier les ?volutions
        if (true) {
            for (const [base, evoData] of Object.entries(EVOLUTIONS)) {
                if (!POKEMON_BASE_STATS[base]) {
                    debugWarn(`[WARN] Evolution orpheline: ${base} n'a pas de stats.`);
                }
                const targets = [];
                if (evoData.evolves_to) targets.push(evoData.evolves_to);
                if (Array.isArray(evoData.options)) {
                    evoData.options.forEach((opt) => {
                        if (opt && opt.evolves_to) targets.push(opt.evolves_to);
                    });
                }
                targets.forEach((targetName) => {
                    if (!POKEMON_BASE_STATS[targetName]) {
                        debugError(`[ERROR] Evolution brisee: ${base} -> ${targetName} (Cible inexistante)`);
                        errors++;
                    }
                });
            }
        }

        if (errors === 0) {
            debugLog("Validation terminee: donnees coherentes.");
        } else {
            debugLog(`[ERROR] ${errors} erreur(s) trouvee(s). Verifiez constants.js et pokemonStats.js`);
        }
        debugLog('--- Fin diagnostic ---');
    }


