    selectRegionalStarter(this: GameRuntime, regionId: string, type: string) {
        const region = String(regionId || '').toLowerCase();
        const starters = REGIONAL_RESONANCE.startersByRegion[region];
        if (!starters) return;
        const nameMap: Record<string, string> = starters;
        const name = nameMap[type];
        if (!name) return;
        const findTypeFn = this.findTypeForPokemon as ((n: string) => string) | undefined;
        const creatureType = findTypeFn ? findTypeFn(name) : TYPES.NORMAL;
        const starter = new Creature(name, creatureType, 1, RARITY.EPIC, false);
        starter.regionalArcId = region;
        starter.ivHP = 1;
        starter.ivAttack = 1;
        starter.ivDefense = 1;
        starter.ivSpeed = 1;
        starter.recalculateStats();
        starter.heal();
        const maxTeamSize = getMaxTeamSize(this);
        if (this.playerTeam.length < maxTeamSize) {
            this.playerTeam.push(starter);
        } else if (Array.isArray(this.storage)) {
            this.storage.push(starter);
        } else {
            this.storage = [starter];
        }
        if (typeof this.registerCreatureMovesForFamily === 'function') {
            this.registerCreatureMovesForFamily(starter);
        }
        if (!this.regionalStarterOffered) this.regionalStarterOffered = {};
        this.regionalStarterOffered[region] = true;
        (this as GameRuntime & { _pendingRegionalStarterRegion?: string })._pendingRegionalStarterRegion = undefined;
        invalidateResonanceCache(this);
        changeRegionLogic(this, region);
        logMessage(this.t('log.starterChosen', { name }));
        toast.success(this.t('toast.adventureStartTitle'), this.t('log.starterChosen', { name }));
        const modal = document.getElementById('starterModal');
        if (modal) modal.classList.remove('show');
        setStarterResonancePanelVisible(false);
        this.updateTeamDisplay();
        this.updateStorageDisplay();
        this.saveGame({ immediate: true, reason: 'new_game' });
    }

