    /** Valide towerRelicAutoSettings contre TOWER_RELICS (cles connues) et migre priorities[] legacy vers prioritySlots. */
    normalizeTowerRelicAutoSettings(this: GameRuntime) {
        const keys = Object.keys(TOWER_RELICS);
        const valid = new Set(keys);
        const PM = TOWER_RELIC_PRIORITY_META;
        const metaKeys = PM ? new Set([PM.BY_RARITY]) : new Set();
        const slotCount = PM && PM.SLOT_COUNT != null ? Number(PM.SLOT_COUNT) : 4;
        const validMinRarities: string[] = [RARITY.COMMON, RARITY.RARE, RARITY.EPIC, RARITY.LEGENDARY];
        const validMin = new Set(validMinRarities);
        const emptySlot = () => ({ key: null, minRarity: RARITY.COMMON });
        const legacyMetaToByRarity = (sk: string) => {
            if (sk === '__tower_prio_any_legendary__' || sk === '__tower_prio_any_epic__') {
                return PM && PM.BY_RARITY ? PM.BY_RARITY : '__tower_prio_by_rarity__';
            }
            return null;
        };

        if (!this.towerRelicAutoSettings || typeof this.towerRelicAutoSettings !== 'object') {
            this.towerRelicAutoSettings = {
                enabled: false,
                prioritySlots: Array.from({ length: slotCount } as ArrayLike<unknown>, () => emptySlot()),
                blacklist: [],
                skipItemLoot: false
            };
            return;
        }
        const s = this.towerRelicAutoSettings;
        s.enabled = !!s.enabled;
        s.skipItemLoot = !!s.skipItemLoot;

        type TowerRelicLegacySettings = TowerRelicAutoSettings & { priorities?: string[] };
        const legacySettings = s as TowerRelicLegacySettings;
        let slots: TowerRelicPrioritySlot[] = [];
        if (Array.isArray(s.prioritySlots) && s.prioritySlots.length > 0) {
            slots = s.prioritySlots.slice(0, slotCount);
        } else if (Array.isArray(legacySettings.priorities)) {
            slots = legacySettings.priorities.slice(0, slotCount).map((k: string) => ({
                key: k && valid.has(String(k)) ? String(k) : null,
                minRarity: RARITY.COMMON
            }));
        }
        while (slots.length < slotCount) slots.push(emptySlot());
        s.prioritySlots = slots.slice(0, slotCount).map((sl: TowerRelicPrioritySlot | Record<string, unknown>) => {
            const o = sl && typeof sl === 'object' ? sl : {};
            let key: string | null = null;
            if (o.key != null && o.key !== '') {
                const sk = coerceStr(o.key, '');
                if (valid.has(sk) || metaKeys.has(sk)) key = sk;
                else {
                    const migrated = legacyMetaToByRarity(sk);
                    if (migrated) key = coerceStr(migrated, '');
                }
            }
            let mr = coerceStr(o.minRarity, RARITY.COMMON).toLowerCase();
            if (!validMin.has(mr)) mr = RARITY.COMMON;
            return { key, minRarity: mr } satisfies TowerRelicPrioritySlot;
        });
        const seenPrioKeys = new Set();
        for (let i = 0; i < s.prioritySlots.length; i++) {
            const slot = s.prioritySlots[i];
            if (!slot) continue;
            const k = slot.key;
            if (!k) continue;
            if (seenPrioKeys.has(k)) slot.key = null;
            else seenPrioKeys.add(k);
        }
        if (Object.prototype.hasOwnProperty.call(s, 'priorities')) delete legacySettings.priorities;

        const bl = Array.isArray(s.blacklist) ? s.blacklist.map((k) => String(k)).filter((k) => valid.has(k)) : [];
        s.blacklist = [...new Set(bl)].slice(0, 3);
    }

    /** Vitesse max combat Tour débloquée via boutique (x1 à x5). */
    getMaxTowerCombatSpeed(this: GameRuntime) {
        const level = Math.min(
            TOWER_COMBAT_SPEED_MAX_SHOP_LEVEL,
            Math.max(0, Math.floor(Number(this.permanentBoosts?.tower_combat_speed) || 0)),
        );
        return 1 + level;
    }

    /** Multiplicateur de vitesse combat Tour (1–5). Uniquement sur étages déjà vaincus et vitesses débloquées en boutique. */
    getTowerCombatSpeedMultiplier(this: GameRuntime) {
        if (!this.towerState || !this.towerState.isActive) return 1;
        if (this.towerState.currentFloor > this.towerRecord) return 1;
        const max = this.getMaxTowerCombatSpeed();
        const speed = Number(this.towerCombatSpeed) || 1;
        if (speed <= 1 || max <= 1) return 1;
        return Math.min(speed, max);
    }

    toggleTowerCombatSpeed(this: GameRuntime) {
        if (!this.towerState || !this.towerState.isActive) return;
        const max = this.getMaxTowerCombatSpeed();
        if (max <= 1) {
            if (typeof this.showFeatureLockedToast === 'function') {
                this.showFeatureLockedToast('towerCombatSpeed');
            }
            return;
        }
        const speed = Number(this.towerCombatSpeed) || 1;
        this.towerCombatSpeed = speed >= max ? 1 : speed + 1;
        this.saveGame({ immediate: true, reason: 'tower_speed' });
        updateTowerSpeedButton(this);
    }

