    setupEggHandler(this: GameRuntime) {
        if (this._eggHandlerRegistered) return;
        this._eggHandlerRegistered = true;
        let isProcessingEgg = false;

        document.addEventListener('click', (event) => {
            if (isProcessingEgg) return;

            const eggElement = event.target && (event.target as Element).closest
                ? (event.target as Element).closest('.egg-clickable')
                : null;

            if (!eggElement) return;

            // Safety: only accept clicks from the egg inventory container.
            if (!eggElement.closest('#ballsContainer')) return;

            const rarity = eggElement.getAttribute('data-rarity') || eggElement.getAttribute('data-egg-rarity');
            if (!rarity) return;

            event.preventDefault();
            event.stopPropagation();
            event.stopImmediatePropagation();

            isProcessingEgg = true;

            let eggsOpened = 0;

            // Ctrl+Clic : ouvrir jusqu'a 100 oeufs via capsules uniquement
            if (event.ctrlKey || event.metaKey) {
                const maxToOpen = Math.min(100, this.eggs[rarity] ?? 0);
                if (maxToOpen > 0) {
                    const prevSuppress = this.suppressLogs;
                    let _openedViaCapsules = 0;
                    try {
                        this.suppressLogs = true;
                        logMessage(this.t('log.eggsOpenStart', { count: maxToOpen, rarity }));

                        _openedViaCapsules = this.useEggCapsulesForRarity(rarity, maxToOpen);
                        eggsOpened += _openedViaCapsules;
                    } finally {
                        this.suppressLogs = prevSuppress;
                    }
                    logMessage(this.t('log.eggsOpenedCount', { count: eggsOpened, rarity }));
                    if (_openedViaCapsules <= 0) {
                        logMessage(this.t('log.notEnoughItems'));
                    }
                }
            }
            // Shift+Clic : ouvrir jusqu'a 5 oeufs via capsules uniquement
            else if (event.shiftKey) {
                const maxToOpen = Math.min(5, this.eggs[rarity] ?? 0);
                if (maxToOpen > 0) {
                    const _openedViaCapsules = this.useEggCapsulesForRarity(rarity, maxToOpen);
                    if (_openedViaCapsules <= 0) {
                        logMessage(this.t('log.notEnoughItems'));
                    }
                }
            }
            // Clic simple : 1 capsule pour 1 oeuf, sinon refus
            else {
                const openedViaCapsule = this.useEggCapsulesForRarity(rarity, 1);
                if (openedViaCapsule <= 0) {
                    logMessage(this.t('log.notEnoughItems'));
                }
            }

            requestAnimationFrame(() => {
                this.updateEggsDisplay();
                this.updateTeamDisplay();
                this.updatePlayerStatsDisplay();
                this.updatePokedexDisplay();
                this.updateStorageDisplay();
            });

            setTimeout(() => {
                isProcessingEgg = false;
            }, 100);
        }, true);
    }


