    startAutoSave(this: GameRuntime) {
        if (this._autoSaveIntervalId != null) {
            clearInterval(this._autoSaveIntervalId);
            this._autoSaveIntervalId = null;
        }

        bindAutoSaveInterval(this, AUTOSAVE_CHECK_INTERVAL_MS);
        bindAutoSaveLifecycle(this);

        this._lastAutoSaveSignature = buildAutoSaveSignature(this);
        const now = Date.now();
        this._lastAutoSaveAt = Math.max(now, Number(this.lastSaveTime) || 0);
        this._lastAutoSaveIndicatorAt = now;
        this._pendingAutoSaveSignature = null;
        this._autoSaveFlushScheduled = false;
    }

    tickAutoSave(this: GameRuntime) {
        if (typeof document !== 'undefined' && document.hidden) return;

        const now = Date.now();
        const lastSave = getAutoSaveLastFlushAt(this) ?? now;
        const currentSignature = buildAutoSaveSignature(this);
        const action = evaluateAutoSaveTick({
            pendingSignature: this._pendingAutoSaveSignature,
            inCombat: this.combatState === 'fighting',
            now,
            lastSaveAt: lastSave,
            lastSignature: this._lastAutoSaveSignature,
            currentSignature,
            minFlushMs: AUTOSAVE_MIN_FLUSH_MS,
            combatMinFlushMs: AUTOSAVE_COMBAT_MIN_FLUSH_MS,
        });

        switch (action.type) {
            case 'noop':
                return;
            case 'clear_pending':
                this._pendingAutoSaveSignature = null;
                return;
            case 'defer_combat':
            case 'defer_min_interval':
                this._pendingAutoSaveSignature = action.signature;
                return;
            case 'flush':
                this.flushAutoSaveInternal(action.signature, false, action.reason);
                return;
            default:
                return;
        }
    }

    flushAutoSaveInternal(
        this: GameRuntime,
        _signature: string,
        immediate: boolean,
        reason: AutoSaveFlushReason = 'dirty',
    ) {
        const now = Date.now();
        const msSinceLastSave = now - (this._lastAutoSaveAt ?? 0);
        const currentSignature = buildAutoSaveSignature(this);

        if (!canPerformAutoSaveFlush(this, { force: immediate, now })) {
            traceAutoSaveFlush({
                blocked: true,
                reason,
                immediate,
                msSinceLastSave,
                signatureDiffAt: firstSignatureSegmentDiff(this._lastAutoSaveSignature, currentSignature),
            });
            return;
        }

        traceAutoSaveFlush({
            blocked: false,
            reason,
            immediate,
            msSinceLastSave,
            signatureDiffAt: firstSignatureSegmentDiff(this._lastAutoSaveSignature, currentSignature),
        });

        const showAutoSaveIndicator = () => {
            const indicator = document.getElementById('autoSaveIndicator');
            if (indicator) {
                const time = new Date().toLocaleTimeString();
                indicator.innerHTML = `<span class="auto-save-dot"></span> ${this.t('menu.autoSavedAt', { time })}`;
                indicator.style.color = "#16a34a";
                setTimeout(() => {
                    indicator.style.color = "#94a3b8";
                }, 1000);
            }
        };

        const runFlush = (forceFlush: boolean) => {
            const flushNow = Date.now();
            if (!canPerformAutoSaveFlush(this, { force: forceFlush, now: flushNow })) return;
            this.saveGame({ immediate: true, reason: 'autosave' });
            if (shouldShowAutoSaveIndicator(this, reason, { now: flushNow })) {
                this._lastAutoSaveIndicatorAt = flushNow;
                showAutoSaveIndicator();
            }
        };

        if (immediate) {
            flushPendingDebouncedSave();
            runFlush(true);
            return;
        }
        scheduleIdleAutoSaveFlush(
            () => runFlush(false),
            () => !!this._autoSaveFlushScheduled,
            (scheduled) => { this._autoSaveFlushScheduled = scheduled; },
        );
    }

