    on(this: GameRuntime, event: string, fn: (...args: unknown[]) => void) {
        if (!this._listeners) this._listeners = {};
        (this._listeners[event] ||= []).push(fn);
        return this;
    }

    off(this: GameRuntime, event: string, fn: (...args: unknown[]) => void) {
        const list = this._listeners?.[event];
        if (list && this._listeners) this._listeners[event] = list.filter((f) => f !== fn);
        return this;
    }

    emit(this: GameRuntime, event: string, data: unknown) {
        const list = this._listeners?.[event];
        if (!list) return;
        for (let i = 0; i < list.length; i++) {
            const listener = list[i];
            if (!listener) continue;
            try {
                listener(data);
            } catch (err) {
                debugError(`Game.emit("${event}") listener error:`, err);
            }
        }
    }

