    _getTooltipDomHost(this: GameRuntime, event: Event | null | undefined) {
        if (!event) return null;
        const ct = event.currentTarget;
        if (ct instanceof Element) return ct;
        const t = event.target;
        if (t instanceof Element) return t;
        return null;
    }

    _restoreStashedNativeTooltipTitle(this: GameRuntime) {
        const host = this._tooltipTitleHost;
        if (!host) return;
        const key = '_poketimeNativeTitleStash';
        if (Object.prototype.hasOwnProperty.call(host, key)) {
            (host as HTMLElement & Record<string, unknown>).title = coerceStr((host as HTMLElement & Record<string, unknown>)[key], '');
            delete (host as HTMLElement & Record<string, unknown>)[key];
        }
        this._tooltipTitleHost = null;
    }

    _ensureNativeTooltipTitleStashedForHost(this: GameRuntime, host: HTMLElement) {
        if (!host || host.nodeType !== 1) return;
        if (host === this._tooltipTitleHost) return;
        (this)._restoreStashedNativeTooltipTitle();
        if (host.title) {
            (host as HTMLElement & Record<string, unknown>)._poketimeNativeTitleStash = (host as HTMLElement & Record<string, unknown>).title;
            (host as HTMLElement & Record<string, unknown>).title = '';
        }
        this._tooltipTitleHost = host;
    }

    /**
     * Lance le chrono pour afficher l'infobulle.
     * @param {MouseEvent} event - L'?v?nement de la souris.
     * @param {string} title - Le titre de l'objet.
     * @param {string} description - La description.
     */
    scheduleTooltip(this: GameRuntime, event: MouseEvent | Event, title: string, description: string, delayMs: number) {
        if (this.isTooltipSuppressedOnTouch()) return;

        // 1. Annuler la fermeture programm?e si la souris vient juste de "sortir" (Anti-clignotement)
        if (this.hideTooltipTimer) {
            clearTimeout(Number(this.hideTooltipTimer));
            this.hideTooltipTimer = null;
        }

        // 2. Annuler tout autre chrono d'ouverture en attente
        let hadPendingOpenTimer = false;
        if (this.tooltipTimer) {
            hadPendingOpenTimer = true;
            clearTimeout(Number(this.tooltipTimer));
            this.tooltipTimer = null;
        }

        const tooltip = document.getElementById('customTooltip');
        if (!tooltip || !event) {
            if (hadPendingOpenTimer) (this)._restoreStashedNativeTooltipTitle();
            return;
        }

        let x: number | undefined;
        let y: number | undefined;
        if (event instanceof MouseEvent) {
            x = event.clientX;
            y = event.clientY;
        } else {
            const pointerLike = event as { clientX?: unknown; clientY?: unknown };
            if (typeof pointerLike.clientX === 'number' && typeof pointerLike.clientY === 'number') {
                x = pointerLike.clientX;
                y = pointerLike.clientY;
            }
        }
        if (typeof x !== 'number' || typeof y !== 'number') {
            if (hadPendingOpenTimer) (this)._restoreStashedNativeTooltipTitle();
            return;
        }

        const domHost = (this)._getTooltipDomHost(event);
        if (domHost) (this)._ensureNativeTooltipTitleStashedForHost(domHost);

        const delay = typeof delayMs === 'number' ? delayMs : this.TOOLTIP_DELAY;

        // Fonction pour remplir et positionner le tooltip
        const showNow = () => {
            const isMissionMastery = domHost?.classList.contains('expedition-mission-mastery-controls') ?? false;
            const isMiltankFarm = domHost?.getAttribute('data-tooltip-variant') === 'miltank-farm';
            const isRocketTrust = domHost?.getAttribute('data-tooltip-variant') === 'rocket-trust';
            const isBaseStats = domHost?.getAttribute('data-tooltip-variant') === 'base-stats';
            tooltip.classList.toggle('custom-tooltip--mission-mastery', isMissionMastery && !isMiltankFarm && !isRocketTrust && !isBaseStats);
            tooltip.classList.toggle('custom-tooltip--miltank-farm', isMiltankFarm);
            tooltip.classList.toggle('custom-tooltip--rocket-trust', isRocketTrust);
            tooltip.classList.toggle('custom-tooltip--base-stats', isBaseStats);
            tooltip.innerHTML = `<span class="tooltip-title">${title}</span>${description}`;
            tooltip.style.display = 'block';
            const placement = domHost?.getAttribute('data-tooltip-placement');
            const mode = this.isTouchUi()
                ? 'touchCenter'
                : placement === 'left'
                    ? 'anchorLeft'
                    : 'pointer';
            const tooltipOffsets = isMiltankFarm ? { anchorGap: 16, pointerGap: 20 } : undefined;
            positionCustomTooltip(
                tooltip,
                mode,
                { x, y },
                12,
                domHost,
                tooltipOffsets,
            );

            // Sur mobile, on auto-ferme rapidement pour éviter les tooltips persistants.
            if (this.isTouchUi()) this.scheduleTooltipAutoHide();
        };

        // 3. Si le tooltip est D?J? affich? (ex: UI qui se rafra?chit sous la souris),
        // on l'actualise IMM?DIATEMENT sans attendre le d?lai.
        if (tooltip.style.display === 'block') {
            showNow();
        } else {
            // 4. Sinon (nouvel ?l?ment survol?), on utilise le d?lai (d?faut TOOLTIP_DELAY, ou 50ms pour la carte)
            this.tooltipTimer = setTimeout(showNow, Number(delay));
        }
    }

