    /**
     * Cache l'infobulle et annule le timer en cours.
     * Utilise un debounce de 50ms pour ignorer les micro-sorties de souris (rafra?chissement DOM).
     */
    hideTooltip(this: GameRuntime) {
        let cancelledPendingOpen = false;
        // Annuler toute ouverture programm?e
        if (this.tooltipTimer) {
            clearTimeout(Number(this.tooltipTimer));
            this.tooltipTimer = null;
            cancelledPendingOpen = true;
        }
        if (cancelledPendingOpen) (this)._restoreStashedNativeTooltipTitle();

        // Lancer la fermeture avec 50ms de sursis
        if (!this.hideTooltipTimer) {
            this.hideTooltipTimer = setTimeout(() => {
                const tooltip = document.getElementById('customTooltip');
                if (tooltip) tooltip.style.display = 'none';
                (this)._restoreStashedNativeTooltipTitle();
                this.hideTooltipTimer = null;
            }, 50);
        }
    }

    isTouchUi(this: GameRuntime) {
        if (typeof window === 'undefined') return false;
        if ('ontouchstart' in window || (navigator && navigator.maxTouchPoints > 0)) return true;
        return !!(window.matchMedia && window.matchMedia('(hover: none)').matches);
    }

    startTouchTooltipGuard(this: GameRuntime) {
        if (!this.isTouchUi()) return;
        if (this.touchTooltipLongPressTimer) {
            clearTimeout(Number(this.touchTooltipLongPressTimer));
            this.touchTooltipLongPressTimer = null;
        }
        this.touchTooltipLongPressTimer = setTimeout(() => {
            this.clearTooltip();
        }, Number(this.TOUCH_TOOLTIP_LONG_PRESS_MS));
    }

    cancelTouchTooltipGuard(this: GameRuntime) {
        if (this.touchTooltipLongPressTimer) {
            clearTimeout(Number(this.touchTooltipLongPressTimer));
            this.touchTooltipLongPressTimer = null;
        }
    }

    isTooltipSuppressedOnTouch(this: GameRuntime) {
        return this.isTouchUi() && (this).touchTooltipSuppressUntil > Date.now();
    }

    scheduleTooltipAutoHide(this: GameRuntime, delayMs = GAME_TIMINGS.TOOLTIP_AUTO_HIDE) {
        if (this.tooltipAutoHideTimer) {
            clearTimeout(Number(this.tooltipAutoHideTimer));
            this.tooltipAutoHideTimer = null;
        }
        this.tooltipAutoHideTimer = setTimeout(() => {
            (this).hideAllTooltips(true);
        }, delayMs);
    }

    hideAllTooltips(this: GameRuntime, immediate = false) {
        if (this.tooltipAutoHideTimer) {
            clearTimeout(Number(this.tooltipAutoHideTimer));
            this.tooltipAutoHideTimer = null;
        }
        if (this.tooltipTimer) {
            clearTimeout(Number(this.tooltipTimer));
            this.tooltipTimer = null;
        }
        if (this.hideTooltipTimer) {
            clearTimeout(Number(this.hideTooltipTimer));
            this.hideTooltipTimer = null;
        }

        (this)._restoreStashedNativeTooltipTitle();

        const customTooltip = document.getElementById('customTooltip');
        if (customTooltip) customTooltip.style.display = 'none';

        const autoTooltip = document.getElementById('autoTooltip');
        if (autoTooltip) autoTooltip.classList.remove('show');

        const captureTooltip = document.getElementById('captureTooltip');
        if (captureTooltip) captureTooltip.classList.remove('show');

        const forfeitTooltip = document.getElementById('forfeitTooltip');
        if (forfeitTooltip) forfeitTooltip.classList.remove('show');

        if (!immediate) this.hideTooltip();
    }

