    getAchievementTrackingValue(this: GameRuntime, trackingKey: string) {
        const key = String(trackingKey || '');
        if (key.indexOf('typedDamageDealt_') === 0) {
            const typeKey = key.slice('typedDamageDealt_'.length).toLowerCase();
            const typed = (this.stats && this.stats.typedDamageDealt && typeof this.stats.typedDamageDealt === 'object')
                ? this.stats.typedDamageDealt
                : null;
            return Number((typed && typed[typeKey]) || 0);
        }
        if (key.indexOf('moveStatusInflicted_') === 0) {
            const statusKey = key.slice('moveStatusInflicted_'.length);
            const byType = (this.stats && this.stats.moveStatusInflictedByType && typeof this.stats.moveStatusInflictedByType === 'object')
                ? this.stats.moveStatusInflictedByType
                : null;
            return Number((byType && byType[statusKey]) || 0);
        }
        if (key === 'totalPlayTime') {
            const now = Date.now();
            const total = Number(this.stats && this.stats.totalPlayTime) || 0;
            const start = Number(this.stats && this.stats.startTime) || now;
            return Math.max(0, total + Math.max(0, now - start));
        }
        if (key === 'offlineTimeSimulatedMs') {
            return Math.max(0, Number(this.stats && this.stats.offlineTimeSimulatedMs) || 0);
        }
        if (key === 'vitaminsUsedTotal') {
            return sumVitaminsConsumed(this.stats && this.stats.vitaminsConsumed);
        }
        return Number((this.stats && Number(this.stats[key as keyof typeof this.stats])) || 0);
    }

