    buyPokeMartItem(this: GameRuntime, key: string, opts?: { auto?: boolean; skipDisplayRefresh?: boolean }) {
        const isAuto = !!opts?.auto;
        const skipDisplayRefresh = !!opts?.skipDisplayRefresh;
        const now = Date.now();
        type MartOfferEntry = { key: string; item: Record<string, unknown> & { itemId: string; amount: number; cost?: number; costItems?: Array<{ itemId: string; qty: number }>; name?: string } };
        const offer = (this).getPokeMartOfferItems(now).find((entry: MartOfferEntry) => entry.key === key) as MartOfferEntry | undefined;
        const item = offer?.item ?? null;
        if (!item) {
            if (!isAuto) logMessage(this.t('log.martNoItem'));
            return false;
        }
        if ((this).isPokeMartOfferSoldOut(key, now)) {
            if (!isAuto) logMessage(this.t('log.martSoldOut'));
            return false;
        }

        const hasBarter = Array.isArray(item.costItems) && item.costItems.length > 0;
        const isDust = !hasBarter && (item as Record<string, unknown>).dustCost
            && Number((item as Record<string, unknown>).dustCost) > 0;
        let rjFee = 0;

        if (isAuto) {
            if (!(this).canAffordPokeMartItemAuto(key, now)) return false;
            rjFee = (this).getPokeMartAutoPurchaseRjFee();
            if (!this.teamRocketState || typeof this.teamRocketState !== 'object') return false;
            this.teamRocketState.rj = Math.max(0, (this.teamRocketState.rj || 0) - rjFee);
        }

        if (hasBarter) {
            if (!(this).canAffordPokeMartItem(item)) {
                if (!isAuto) logMessage(this.t('log.martNotEnoughItems'));
                if (isAuto && rjFee > 0 && this.teamRocketState) {
                    this.teamRocketState.rj += rjFee;
                }
                return false;
            }
            for (let i = 0; i < (item.costItems?.length ?? 0); i++) {
                const c = item.costItems![i];
                if (!c || !c.itemId) continue;
                const need = Math.max(0, Math.floor(Number(c.qty) || 0));
                if (need <= 0) continue;
                const prevQty = this.items[c.itemId] ?? 0;
                this.items[c.itemId] = prevQty - need;
                if ((this.items[c.itemId] ?? 0) <= 0) delete this.items[c.itemId];
            }
        } else if (isDust) {
            const dCost = Math.floor(Number((item as Record<string, unknown>).dustCost) || 0);
            if ((this.essenceDust || 0) < dCost) {
                if (!isAuto) logMessage(this.t('log.dustNotEnough'));
                if (isAuto && rjFee > 0 && this.teamRocketState) {
                    this.teamRocketState.rj += rjFee;
                }
                return false;
            }
            this.essenceDust -= dCost;
        } else {
            const baseCost = Number(item.cost) || 0;
            const cost = isAuto
                ? (this).getPokeMartAutoPurchasePokedollarCost(baseCost)
                : baseCost;
            if (this.pokedollars < cost) {
                if (!isAuto) logMessage(this.t('log.notEnoughPokedollars'));
                if (isAuto && rjFee > 0 && this.teamRocketState) {
                    this.teamRocketState.rj += rjFee;
                }
                return false;
            }
            this.pokedollars -= cost;
            recordPokedollarsSpent(this, cost);
            this.checkSpecialQuests('money_spent'); // Important pour les qu?tes "?conome" ou "D?pensier"
            if (typeof this.applyRocketPokedollarCashback === 'function') {
                this.applyRocketPokedollarCashback(isAuto ? baseCost : cost, { fromPokeMartPokedollars: true });
            }
        }

        const grantItemId = String(item.itemId || (item as { item?: string }).item || '');

        // Ajout de l'objet
        if (item.itemId === '__ct_random__') {
            const ctEntries = Object.entries(SHOP_ITEMS as Record<string, Record<string, unknown>>)
                .filter(([, entry]) => entry.type === 'ct' && typeof entry.item === 'string' && entry.item.startsWith('ct_'))
                .filter(([, entry]) => typeof this.isDamagingCtItemKey === 'function' && this.isDamagingCtItemKey(entry.item as string));
            if (ctEntries.length > 0) {
                const idx = Math.floor(Math.random() * ctEntries.length);
                const picked = ctEntries[idx];
                if (!picked) {
                    if (!isAuto) logMessage(this.t('log.tokenUnknownItem'));
                    if (isAuto && rjFee > 0 && this.teamRocketState) {
                        this.teamRocketState.rj += rjFee;
                    }
                    return false;
                }
                const ctKey = picked[1].item as string;
                const moveName = (picked[1].moveName as string)
                    || ctKey.replace(/^ct_/, '').replace(/_/g, ' ');
                const ctName = typeof this.getLocalizedMoveNamePlain === 'function'
                    ? this.getLocalizedMoveNamePlain(moveName)
                    : moveName;
                this.addItem(ctKey, Math.floor(Number(item.amount) || 1));
                const locName = this.getLocalizedShopEntryName('pokeMart', key, item.name || key);
                if (isAuto) {
                    logMessage(this.t('log.martAutoPurchaseLine', {
                        amount: item.amount,
                        name: `${locName} (${ctName})`,
                        rj: rjFee,
                    }));
                } else {
                    toast.success(this.t('toast.ctObtainedTitle'), this.t('toast.ctObtainedBody', { name: ctName }));
                    logMessage(this.t('log.purchaseLine', { amount: item.amount, name: `${locName} (${ctName})`, cost: 0 }));
                }
            } else {
                if (!isAuto) logMessage(this.t('log.tokenUnknownItem'));
                if (isAuto && rjFee > 0 && this.teamRocketState) {
                    this.teamRocketState.rj += rjFee;
                }
                return false;
            }
        } else {
            if (!grantItemId) {
                if (!isAuto) logMessage(this.t('log.tokenUnknownItem'));
                if (isAuto && rjFee > 0 && this.teamRocketState) {
                    this.teamRocketState.rj += rjFee;
                }
                return false;
            }
            this.addItem(grantItemId, item.amount);
        }
        if (!this.martState!.purchasedOfferKeys || typeof this.martState!.purchasedOfferKeys !== 'object') this.martState!.purchasedOfferKeys = {};
        this.martState!.purchasedOfferKeys[key] = (this.martState!.purchasedOfferKeys[key] || 0) + 1;

        // Feedback
        const locName = this.getLocalizedShopEntryName('pokeMart', key, item.name || key);
        if (isAuto) {
            if (item.itemId !== '__ct_random__' && grantItemId) {
                logMessage(this.t('log.martAutoPurchaseLine', {
                    amount: item.amount,
                    name: locName,
                    rj: rjFee,
                }));
            }
        } else if (hasBarter) {
            const costLine = (item.costItems || []).map((c: { itemId: string; qty: number }) => {
                const def = (ALL_ITEMS as ItemRecord)[c.itemId] ?? null;
                const nm = this.getLocalizedItemName(c.itemId, def && def.name ? def.name : c.itemId, def);
                return `${c.qty}�${nm}`;
            }).join(', ');
            const barterMsg = this.t('log.martPurchaseBarter', { name: locName, cost: costLine });
            logMessage(barterMsg);
        } else if (isDust) {
            if (item.itemId !== '__ct_random__' && grantItemId) {
                const purchaseMsg = this.t('log.dustItemBought', { name: locName, qty: item.amount });
                logMessage(purchaseMsg);
            }
        } else {
            const purchaseMsg = this.t('log.purchaseLine', { amount: item.amount, name: locName, cost: item.cost });
            logMessage(purchaseMsg);
        }

        if (!skipDisplayRefresh) {
            (this).updatePokeMartDisplay();
            this.updatePlayerStatsDisplay();
            this.updateItemsDisplay();
            if (isDust) {
                this.updateRecyclerDisplay();
            }
        }
        return true;
    }

