    getActiveExpeditionOccupants(this: GameRuntime) {
        const occupants: Array<Record<string, unknown>> = [];
        (this.activeExpeditions || []).forEach((exp, expeditionIndex) => {
            if (Array.isArray(exp.squadData)) {
                exp.squadData.forEach((data, slotIndex) => {
                    if (!data || !(data as Record<string, unknown>).name) return;
                    occupants.push({
                        name: (data as Record<string, unknown>).name,
                        isShiny: !!(data as Record<string, unknown>).isShiny,
                        data,
                        expeditionIndex,
                        slotType: 'squadData',
                        slotIndex
                    });
                });
            } else if (exp.creatureData && (exp.creatureData as Record<string, unknown>).name) {
                occupants.push({
                    name: (exp.creatureData as Record<string, unknown>).name,
                    isShiny: !!(exp.creatureData as Record<string, unknown>).isShiny,
                    data: exp.creatureData,
                    expeditionIndex,
                    slotType: 'creatureData',
                    slotIndex: 0
                });
            }
        });
        return occupants;
    }

    persistExpeditionCreatureData(this: GameRuntime, creature: CreatureData) {
        const ref = creature && creature._expeditionRef;
        if (!ref) return;
        const expedition = (this.activeExpeditions || [])[ref.expeditionIndex];
        if (!expedition) return;
        const serialized = (typeof creature.serialize === 'function') ? creature.serialize() : creature;
        if (ref.slotType === 'squadData') {
            if (!Array.isArray(expedition.squadData)) return;
            if (ref.slotIndex < 0 || ref.slotIndex >= expedition.squadData.length) return;
            expedition.squadData[ref.slotIndex] = serialized;
        } else if (ref.slotType === 'creatureData') {
            expedition.creatureData = serialized;
        }
    }

