    // LOGIQUE : Tenter de faire appara?tre un Roamer pour le prochain combat
    rollRoamingEncounter(this: GameRuntime) {
        // 1. Conditions : Pas en Tour, Pas en Ar?ne
        if (this.towerState.isActive || this.arenaState.active) return;

        // 2. Probabilit? (0.5% soit 1 chance sur 200 par combat)
        // Tu peux ajuster ce taux (ex: 0.002 pour 1/500)
        const roamingChance = 0.0005;
        let roamerMult = 1 + (this.getMasteryBonus ? (this.getMasteryBonus('roamer_spawn_mult') || 0) : 0);
        const now = Date.now();
        const incenseBoost = (this.activeBoosts || []).find(
            (b) => b.type === 'roamerSpawn' && Number(b.endTime) > now,
        );
        if (incenseBoost) {
            roamerMult *= (1 + (Number(incenseBoost.value) || 0));
        }

        if (Math.random() < roamingChance * roamerMult) {
            // 3. Choix du Roamer
            const zone = (ZONES as ZoneMap)[currentZone] ?? null;
            const regionId = String((zone && zone.regionId) || this.currentRegion || 'kanto').toLowerCase();
            const regionalPool = (true)
                ? (ROAMING_POKEMON_BY_REGION as Record<string, string[]>)[regionId]
                : ROAMING_POKEMON;
            if (!Array.isArray(regionalPool) || regionalPool.length === 0) return;
            // Anti-farm : on s'appuie sur le m�me cooldown global "wild legendary" que Mewtwo
            // (cf. zoneSystem.js -> LEGENDARY_WILD_SPAWN_COOLDOWN_MS, persistant). Une esp�ce roamer
            // qui vient juste de spawn ne peut plus r�appara�tre pendant la dur�e du cooldown.
            const availablePool = regionalPool.filter(
                (n) => !isLegendaryWildCooldownActiveLogic(this, n),
            );
            if (availablePool.length === 0) return;
            const radarTargets = this.getEggRadarTargets?.() ?? [];
            const radarMult = this.getPokedexRadarWeightMultiplier?.() ?? 1;
            const name = pickRoamerSpecies(availablePool, radarTargets, radarMult);
            if (!name) return;

            // 4. On stocke l'info pour le prochain startCombat (cooldown au spawn effectif du roamer).
            this.pendingRoamer = name;

            // 5. HYPE : On pr?vient le joueur !
            toast.legendary(this.t('toast.roamerAlertTitle'), this.t('toast.roamerAlertBody', { name }));
            logMessage(this.t('log.roamerApproach'));
        }
    }

