    _getFamilyRarity(this: GameRuntime, familyName: string): string {
        const pool = POKEMON_POOL as Record<string, Record<string, string[]> | undefined>;
        const hasFamily = (entries: Record<string, string[]> | undefined): boolean => {
            if (!entries) return false;
            for (const typeKey in entries) {
                if (entries[typeKey]?.includes(familyName)) return true;
            }
            return false;
        };
        if (hasFamily(pool[RARITY.COMMON])) return RARITY.COMMON;
        if (hasFamily(pool[RARITY.RARE])) return RARITY.RARE;
        if (hasFamily(pool[RARITY.EPIC])) return RARITY.EPIC;
        if (hasFamily(pool[RARITY.LEGENDARY])) return RARITY.LEGENDARY;
        return RARITY.COMMON;
    }

    /**
     * Recycle les shards d'un type en Poussi?re d'Essence
     * @param {string} shardKey
     * @param {string} rarity
     * @param {number|string|undefined|null} requestedAmount - si omis ou invalide, recycle tout le stock de ce type
     */
    recycleShards(this: GameRuntime, shardKey: string, rarity: string, requestedAmount?: number | string | null) {
        const available = this.shards[shardKey] || 0;
        if (available === 0) return;
        if (Array.isArray(this.protectedShards) && this.protectedShards.includes(shardKey)) {
            toast.warning(this.t('shop.recyclerProtected'), this.t('shop.recyclerProtectedSkip', { name: shardKey }));
            return;
        }

        let recycleCount = available;
        if (requestedAmount !== undefined && requestedAmount !== null && requestedAmount !== '') {
            const n = Math.floor(Number(requestedAmount));
            if (!Number.isFinite(n) || n < 1) return;
            recycleCount = Math.min(n, available);
        }

        const dustRates = DUST_CONVERSION_RATES as Record<string, number> | undefined;
        const rate = dustRates?.[rarity] ?? 1;
        const masteryDust = (this.getMasteryBonus ? (this.getMasteryBonus('dust_mult') || 0) : 0) + (this.getMasteryBonus ? (this.getMasteryBonus('recycle_efficiency') || 0) : 0) + (this.getMasteryBonus ? (this.getMasteryBonus('duplicate_value') || 0) : 0);
        const dustGained = Math.floor(recycleCount * rate * (1 + masteryDust));

        if (!this.stats || typeof this.stats !== 'object') this.stats = {} as GameRuntime['stats'];
        this.essenceDust += dustGained;
        this.stats.essenceDustRecycled = (this.stats.essenceDustRecycled || 0) + dustGained;
        this.checkAchievements('essenceDustRecycled');
        this.shards[shardKey] = available - recycleCount;

        const count = recycleCount;
        logMessage(this.t('log.recyclerLog', { count, shard: shardKey, dust: dustGained }));
        toast.success(this.t('toast.shardsRecycleTitle'), this.t('toast.shardsRecycleBody', { dust: dustGained }));
        if (typeof this.checkSpecialQuests === 'function') this.checkSpecialQuests('recyclerUsed');

        this.updateRecyclerDisplay();
        this.updateStorageDisplay(); // Mettre ? jour les compteurs de shards sur les cartes
        this.updateTeamDisplay();
        this.updatePensionDisplay();
    }

    toggleProtectShard(this: GameRuntime, shardKey: string) {
        if (!Array.isArray(this.protectedShards)) this.protectedShards = [];
        const idx = this.protectedShards.indexOf(shardKey);
        if (idx >= 0) {
            this.protectedShards.splice(idx, 1);
        } else {
            this.protectedShards.push(shardKey);
        }
        this.updateRecyclerDisplay();
    }

    recycleAllByRarity(this: GameRuntime, rarity: string) {
        const protectedSet = new Set(Array.isArray(this.protectedShards) ? this.protectedShards : []);
        const dustRates = DUST_CONVERSION_RATES as Record<string, number> | undefined;
        const rate = dustRates?.[rarity] ?? 1;
        const masteryDust = (this.getMasteryBonus ? (this.getMasteryBonus('dust_mult') || 0) : 0) + (this.getMasteryBonus ? (this.getMasteryBonus('recycle_efficiency') || 0) : 0) + (this.getMasteryBonus ? (this.getMasteryBonus('duplicate_value') || 0) : 0);
        let totalRecycled = 0;
        let totalDust = 0;
        const shardKeys = Object.keys(this.shards || {});
        for (const shardKey of shardKeys) {
            const available = this.shards[shardKey] || 0;
            if (available <= 0) continue;
            if (protectedSet.has(shardKey)) continue;
            const familyRarity = this._getFamilyRarity ? this._getFamilyRarity(shardKey) : 'common';
            if (familyRarity !== rarity) continue;
            const dustGained = Math.floor(available * rate * (1 + masteryDust));
            this.essenceDust += dustGained;
            if (!this.stats || typeof this.stats !== 'object') this.stats = {} as GameRuntime['stats'];
            this.stats.essenceDustRecycled = (this.stats.essenceDustRecycled || 0) + dustGained;
            this.shards[shardKey] = 0;
            totalRecycled += available;
            totalDust += dustGained;
        }
        if (totalRecycled > 0) {
            this.checkAchievements('essenceDustRecycled');
            logMessage(this.t('log.recyclerLog', { count: totalRecycled, shard: rarity, dust: totalDust }));
            toast.success(this.t('toast.shardsRecycleTitle'), this.t('toast.shardsRecycleBody', { dust: totalDust }));
            if (typeof this.checkSpecialQuests === 'function') this.checkSpecialQuests('recyclerUsed');
        }
        this.updateRecyclerDisplay();
        this.updateStorageDisplay();
        this.updateTeamDisplay();
        this.updatePensionDisplay();
    }

