    showMasteryModal(this: GameRuntime) {
        const modal = document.getElementById('biomeMasteryModal');
        const grid = document.getElementById('biomeMasteryListGrid');
        if (!modal || !grid) return;

        grid.innerHTML = '';

        const biomeNameKeys = {
            FOREST: 'expeditions.biomeForest',
            CAVE: 'expeditions.biomeCave',
            CITY: 'expeditions.biomeCity',
            DARK: 'expeditions.biomeDark',
            VOLCANO: 'expeditions.biomeVolcano',
            ICE: 'expeditions.biomeIce',
            SKY: 'expeditions.biomeSky'
        };
        const masteryDescKeys: Record<number, string> = {
            1: 'expeditions.masteryDesc1',
            2: 'expeditions.masteryDesc2',
            3: 'expeditions.masteryDesc3',
            4: 'expeditions.masteryDesc4',
            5: 'expeditions.masteryDesc5',
            6: 'expeditions.masteryDesc6',
            7: 'expeditions.masteryDesc7',
            8: 'expeditions.masteryDesc8',
            9: 'expeditions.masteryDesc9',
            10: 'expeditions.masteryDesc10',
        };

        // 1. V?rification de s?curit? (si l'objet n'existe pas encore)
        if (!this.expeditionMastery) this.expeditionMastery = { level: 0, xp: 0 };

        // 2. Parcourir tous les biomes d?finis
        Object.keys(BIOME_DISPLAY).forEach(biomeKey => {
            const xp = (this.expeditionMastery as Record<string, number>)[biomeKey] || 0;
            const displayInfo = biomeDisplayByKey[biomeKey];
            if (!displayInfo) return;
            const biomeNameKey = (biomeNameKeys as Record<string, string>)[biomeKey];
            let biomeName = displayInfo.name;
            if (biomeNameKey) {
                const translatedBiome = this.t(biomeNameKey);
                if (translatedBiome && translatedBiome !== biomeNameKey) biomeName = translatedBiome;
            }

            // 3. Calculer le niveau actuel
            let currentLevel = 1;
            let nextLevelXP = (BIOME_MASTERY_LEVELS as BiomeMasteryMap)[2]?.xpRequired ?? 0;
            let prevLevelXP = 0;
            let bonusDesc = this.t('expeditions.masteryNoBonus');

            // On cherche le niveau le plus haut atteint
            for (let lvl = BIOME_MASTERY_MAX_LEVEL; lvl >= 1; lvl--) {
                const lvlDef = (BIOME_MASTERY_LEVELS as BiomeMasteryMap)[lvl];
                if (!lvlDef) continue;
                if (xp >= lvlDef.xpRequired) {
                    currentLevel = lvl;
                    const descKey = (masteryDescKeys as Record<string, string>)[lvl];
                    const translatedDesc = descKey ? this.t(descKey) : '';
                    bonusDesc = (translatedDesc && translatedDesc !== descKey)
                        ? translatedDesc
                        : String(lvlDef.desc ?? '');

                    // D?finir les bornes pour la barre de progression
                    if (lvl < BIOME_MASTERY_MAX_LEVEL) {
                        prevLevelXP = lvlDef.xpRequired;
                        const nextDef = (BIOME_MASTERY_LEVELS as BiomeMasteryMap)[lvl + 1];
                        nextLevelXP = nextDef?.xpRequired ?? lvlDef.xpRequired;
                    } else {
                        const maxDef = BIOME_MASTERY_LEVELS[BIOME_MASTERY_MAX_LEVEL as keyof typeof BIOME_MASTERY_LEVELS];
                        prevLevelXP = maxDef?.xpRequired ?? lvlDef.xpRequired;
                        nextLevelXP = xp;
                    }
                    break;
                }
            }

            // 4. Calcul du pourcentage
            let percent = 0;
            if (currentLevel < BIOME_MASTERY_MAX_LEVEL) {
                percent = ((xp - prevLevelXP) / (nextLevelXP - prevLevelXP)) * 100;
            } else {
                percent = 100;
            }

            // 5. Cr?ation de la carte
            const card = document.createElement('div');
            card.className = 'biome-mastery-card';

            card.innerHTML = `
            <div class="biome-mastery-icon">
                ${displayInfo.icon}
            </div>

            <div style="flex: 1; min-width: 0;">
                <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px; gap:8px;">
                    <strong class="biome-mastery-name">${biomeName}</strong>
                    <span class="biome-mastery-level">${this.t('expeditions.masteryLevel', { level: currentLevel })}</span>
                </div>

                <div class="biome-mastery-progress-track">
                    <div class="biome-mastery-progress-fill" style="width: ${percent}%;"></div>
                </div>

                <div class="biome-mastery-meta">
                    <span>${this.t('expeditions.masteryXp', { current: xp, next: currentLevel < BIOME_MASTERY_MAX_LEVEL ? nextLevelXP : this.t('expeditions.masteryMax') })}</span>
                    <span class="biome-mastery-bonus">${bonusDesc}</span>
                </div>
            </div>
        `;

            grid.appendChild(card);
        });

        modal.classList.add('show');
    }
