    /**
     * Met ? jour les indicateurs des onglets Qu?tes et Exp?ditions :
     * - Qu?tes : r?compenses ? r?cup?rer, qu?tes ? accepter, qu?te sc?nario
     * - Exp?ditions : r?compenses ? r?cup?rer, slot disponible
     */
    updateTabBadges(this: GameRuntime) {
        const displayableQuests = (this.quests || []).filter(q => !q.claimed);
        const toClaimQuests = displayableQuests.filter(q => q.completed && !q.claimed);
        const toAcceptQuests = displayableQuests.filter(q => !q.accepted);
        const inProgressQuestsCount = displayableQuests.filter(q => q.accepted && !q.completed).length;
        const achievToClaim = (this.achievements && Object.values(this.achievements).filter(a => {
            const ap = a as unknown as AchievementProgress;
            return ap.completed && !ap.claimed;
        }).length) || 0;
        const toClaimTotal = toClaimQuests.length + achievToClaim;

        const achSubBadge = document.getElementById('achievementsSubTabBadge');
        if (achSubBadge) {
            if (achievToClaim > 0) {
                achSubBadge.textContent = String(achievToClaim);
                achSubBadge.className = 'tab-badge tab-badge-claim';
            } else {
                achSubBadge.textContent = '';
                achSubBadge.className = '';
            }
        }

        const questBadge = document.getElementById('questsTabBadge');
        if (questBadge) {
            const parts = [];
            if (toClaimTotal > 0) parts.push(`<span class="tab-badge tab-badge-claim" title="${this.t('tabBadge.questClaimTitle')}">${toClaimTotal}</span>`);
            if (toAcceptQuests.length > 0) parts.push(`<span class="tab-badge tab-badge-accept" title="${this.t('tabBadge.questAcceptTitle')}">${toAcceptQuests.length}</span>`);
            // Quand il n'y a ni qu�tes � r�clamer ni qu�tes � accepter, on affiche le nombre de qu�tes en cours (accepted && !completed).
            if (toClaimTotal === 0 && toAcceptQuests.length === 0 && inProgressQuestsCount > 0) {
                parts.push(`<span class="tab-badge tab-badge-inprogress" title="Qu�tes en cours">${inProgressQuestsCount}</span>`);
            }
            questBadge.innerHTML = parts.join('');
            questBadge.style.display = parts.length ? '' : 'none';
        }

        const expToClaim = (this.activeExpeditions || []).filter(e => Date.now() >= (e.endTime ?? 0)).length;
        const maxExpSlots = typeof this.getMaxExpeditionSlots === 'function'
            ? this.getMaxExpeditionSlots()
            : (this.maxExpeditionSlots ?? 3);
        const expSlotsFree = this.activeExpeditions && maxExpSlots != null && this.activeExpeditions.length < maxExpSlots;
        const expBadge = document.getElementById('expeditionsTabBadge');
        if (expBadge) {
            const parts = [];
            if (expToClaim > 0) parts.push(`<span class="tab-badge tab-badge-claim" title="${this.t('tabBadge.expClaimTitle')}">${expToClaim}</span>`);

            // Calcul du nombre de missions disponibles (non lanc?es) et slots libres
            const availableMissionsCount = this.availableExpeditions ? this.availableExpeditions.length : 0;
            const freeSlotsCount = maxExpSlots - (this.activeExpeditions ? this.activeExpeditions.length : 0);

            // On affiche le nombre de missions qu'on peut REELLEMENT lancer (le minimum entre les slots libres et les missions disponibles)
            const playableMissionsCount = Math.min(availableMissionsCount, freeSlotsCount);

            if (playableMissionsCount > 0) {
                parts.push(`<span class="tab-badge tab-badge-accept" title="${this.t('tabBadge.expAvailableTitle')}">${playableMissionsCount}</span>`);
            }

            expBadge.innerHTML = parts.join('');
            expBadge.style.display = parts.length ? '' : 'none';
        }

        const tr = this.teamRocketState || {};
        const staking = tr.staking || {};
        const hasActiveSession = !!staking.activeSession;
        const rocketToClaim = hasActiveSession ? 1 : 0;
        const rocketToAccept = hasActiveSession ? 0 : this.getRocketStakeableOfferItems(Date.now()).length;
        const teamRocketBadge = document.getElementById('teamRocketTabBadge');
        if (teamRocketBadge) {
            const parts = [];
            if (rocketToClaim > 0) parts.push(`<span class="tab-badge tab-badge-claim" title="${this.t('tabBadge.rocketSessionTitle')}">${rocketToClaim}</span>`);
            if (rocketToAccept > 0) parts.push(`<span class="tab-badge tab-badge-accept" title="${this.t('tabBadge.rocketStakeablesTitle')}">${rocketToAccept}</span>`);
            teamRocketBadge.innerHTML = parts.join('');
            teamRocketBadge.style.display = parts.length ? '' : 'none';
        }

        (this).updateExtrasBadge();
    }

