    saveGame(this: GameRuntime, opts?: { immediate?: boolean; reason?: string }) {
        const runCore = () => this._saveGameCore(opts?.reason);
        if (opts?.immediate || this.__forceBackupSave) {
            flushPendingDebouncedSave();
            return runCore();
        }
        scheduleDebouncedSave(runCore);
    }

    _saveGameCore(this: GameRuntime, reason?: string) {
        traceSaveGame(reason, true);
        this.syncTalentConsumablesInInventory();
        if (this.stats) {
            const now = Date.now();
            const start = Number(this.stats.startTime) || now;
            this.stats.totalPlayTime = (Number(this.stats.totalPlayTime) || 0) + Math.max(0, now - start);
            this.stats.startTime = now;
        }
        const result = saveGameLogic(this);
        this._lastAutoSaveAt = Date.now();
        this._lastAutoSaveSignature = buildAutoSaveSignature(this);
        this._pendingAutoSaveSignature = null;
        return result;
    }

