    getOfflineReportDisplayThresholdMs(this: GameRuntime, rawValue?: string | number) {
        const fallback = 30000;
        const value = (rawValue !== undefined) ? Number(rawValue) : Number(this.offlineReportDisplayThresholdMs);
        if (!Number.isFinite(value)) return fallback;
        const clamped = Math.min(1800000, Math.max(30000, value));
        return Math.round(clamped / 30000) * 30000;
    }

    formatOfflineReportThresholdLabel(this: GameRuntime, ms: number) {
        const seconds = Math.round(ms / 1000);
        if (seconds < 60) return `${seconds}s`;
        const minutes = Math.floor(seconds / 60);
        const remainingSeconds = seconds % 60;
        return remainingSeconds === 0 ? `${minutes} min` : `${minutes}m ${remainingSeconds}s`;
    }

    updateOfflineReportSliderLabel(this: GameRuntime, rawValue: string | number) {
        const value = this.getOfflineReportDisplayThresholdMs(rawValue);
        const label = document.getElementById('optOfflineReportValue');
        if (label) {
            label.textContent = this.formatOfflineReportThresholdLabel(value);
        }
    }

    updateOfflineReportFromSlider(this: GameRuntime, rawValue: string | number) {
        const value = this.getOfflineReportDisplayThresholdMs(rawValue);
        this.offlineReportDisplayThresholdMs = value;
        this.updateOfflineReportSliderLabel(value);
        this.updateOptionButtons();
    }

