    updateDisplay(this: GameRuntime, domains?: DisplayDomain[]) {
        const active = displayDomainSet(domains);
        const all = active === null;
        const has = (d: DisplayDomain) => all || active.has(d);

        if (has('zone')) updateZoneInfo(this);
        if (has('combat') && typeof this.refreshBattleFeatureButtons === 'function') {
            this.refreshBattleFeatureButtons();
        }
        if (has('team')) this.updateTeamDisplay();
        if (has('storage')) this.updateStorageDisplay();
        if (has('pension')) this.updatePensionDisplay();
        if (has('eggs')) this.updateEggsDisplay();
        if (has('incubators')) this.updateIncubatorsDisplay();
        if (has('shop')) this.updateUpgradesDisplay();
        if (has('combat')) this.updateCombatDisplay();
        if (has('tower')) (this).updateTowerBuffsDisplay();
        if (has('pokedex')) this.updatePokedexDisplay();
        if (has('arena')) this.updateArenasDisplay();
        if (has('achievements')) (this).updateAchievementsDisplay();
        if (has('quests')) (this).updateQuestsDisplay();
        if (has('items')) this.updateItemsDisplay();
        if (has('statBoosts')) this.updateStatBoostsDisplay();
        if (has('tower')) {
            (this).updateTowerDisplay();
            (this).updateTowerShopDisplay();
        }
        if (has('shop')) this.updateShopDisplay();
        if (has('visibility')) {
            this.updatePensionVisibility();
            this.updateStorageVisibility();
            this.updateStorageControlsVisibility();
        }
        if (has('boosts')) this.updateBoostsDisplay();
        if (has('expeditions')) this.updateExpeditionsDisplay();
        if (has('rocket')) this.updateTeamRocketDisplay();
        if (has('afk') && this.afkMode && typeof this.refreshAfkSummaryBar === 'function') {
            this.refreshAfkSummaryBar();
        }
    }

