    // Positionner un modal compact par rapport au centre de son bouton d?clencheur
    positionCompactModal(this: GameRuntime, modalId: string, btnId: string) {
        const modal = document.getElementById(modalId);
        if (!modal) return;

        if (modalId === 'autoSettingsModal') {
            modal.style.left = '';
            modal.style.top = '';
            modal.style.bottom = '';
            modal.style.right = '';
            modal.style.transform = '';
            modal.style.margin = '';
            return;
        }

        const btn = document.getElementById(btnId);
        if (!btn) return;

        if (isMobileViewport()) {
            modal.style.left = '';
            modal.style.bottom = '';
            modal.style.transform = '';
            modal.style.margin = '';
            return;
        }

        const rect = btn.getBoundingClientRect();
        const btnCenterX = rect.left + (rect.width / 2);
        const btnCenterY = rect.top + (rect.height / 2);

        const offsetX = 10;
        const offsetY = 10;

        modal.style.left = `${btnCenterX + offsetX}px`;
        modal.style.bottom = `${(window.innerHeight - btnCenterY) + offsetY}px`;

        modal.style.transform = 'none';
        modal.style.margin = '0';
    }

