/**
 * Dust recycler shop purchase logic (boutique Poussière).
 */
import { ACCOUNT_TALENTS } from '../../constants/balance/arenasTrainers.js';
import { logMessage } from '../ui/modals.ts';
import { toast } from '../../toastManager.ts';
import type { GameRuntime } from '../types/game.js';
import { getDustShopItemCost, isEscalatingDustShopKey } from './dustShopCost.js';
import { dustShopCatalogId, resolveDustShopEntry } from './dustShopResolve.js';

function ensureDustShopPurchaseCounts(game: GameRuntime): Record<string, number> {
    if (!game.dustShopPurchaseCounts || typeof game.dustShopPurchaseCounts !== 'object') {
        game.dustShopPurchaseCounts = {};
    }
    return game.dustShopPurchaseCounts;
}

function incrementDustShopPurchaseCount(game: GameRuntime, shopKey: string): void {
    if (!isEscalatingDustShopKey(shopKey)) return;
    const counts = ensureDustShopPurchaseCounts(game);
    counts[shopKey] = Math.max(0, Math.floor(Number(counts[shopKey]) || 0)) + 1;
}

function resolveDustCost(game: GameRuntime, shopKey: string, baseCost: number): number {
    return getDustShopItemCost(baseCost, shopKey, game.dustShopPurchaseCounts);
}

export function executeBuyDustItem(game: GameRuntime, itemId: string): void {
    const resolved = resolveDustShopEntry(itemId);
    if (!resolved) return;

    const { shopKey, item } = resolved;
    const catalogId = dustShopCatalogId(itemId, item);

    if (item.requiredBadge && !game.hasBadge(item.requiredBadge)) {
        const requiredBadgeName = game.getLocalizedAccountTalentName(
            item.requiredBadge,
            (ACCOUNT_TALENTS as Record<string, { name?: string }>)[item.requiredBadge]?.name ?? item.requiredBadge,
        );
        logMessage(game.t('log.dustLockedBadge', { badge: requiredBadgeName }));
        return;
    }

    const requiresRadar = !!(item as { requiresRadar?: boolean }).requiresRadar;
    const hasRadar = typeof game.getMasteryBonus === 'function'
        && (game.getMasteryBonus('pokedex_radar') || 0) > 0;
    if (requiresRadar && !hasRadar) {
        logMessage(game.t('shop.dustRadarRequired'));
        return;
    }

    if (catalogId === 'auto_catcher' && game.hasAutoCatcher) {
        logMessage(game.t('log.dustAlreadyOwned'));
        return;
    }

    if (catalogId === 'radar_slot_plus' && (game.dustShopRadarSlotBonus || 0) > 0) {
        logMessage(game.t('log.dustAlreadyOwned'));
        return;
    }

    if (item.type === 'upgrade') {
        const upg = game.upgrades[catalogId];
        if (!upg || upg.level >= upg.maxLevel) return;
        const nextLevel = upg.level + 1;
        const upgRec = upg as unknown as Record<string, Record<number, number> | undefined>;
        const cost = (upgRec.dustCosts && upgRec.dustCosts[nextLevel]) || 0;
        if (game.essenceDust < cost) {
            logMessage(game.t('log.dustNotEnough'));
            return;
        }
        game.essenceDust -= cost;
        upg.level++;
        if (catalogId === 'incubatorAutoClick') {
            const cd = (upgRec.cooldownSecs && upgRec.cooldownSecs[upg.level]) || 0;
            const reduc = (upgRec.reductionSecs && upgRec.reductionSecs[upg.level]) || 0;
            logMessage(game.t('log.incubatorAutoClickUpgraded', { level: upg.level, cd, reduc }));
        } else {
            const ms = (upgRec.msValues && upgRec.msValues[upg.level]) || 0;
            logMessage(game.t('log.incubatorClickUpgraded', { level: upg.level, ms }));
        }
        game.updateRecyclerDisplay();
        game.updateIncubatorsDisplay();
        game.updatePlayerStatsDisplay();
        return;
    }

    const baseCost = Math.floor(Number(item.cost) || 0);
    const dustCost = resolveDustCost(game, shopKey, baseCost);
    if (game.essenceDust < dustCost) {
        logMessage(game.t('log.dustNotEnough'));
        return;
    }

    game.essenceDust -= dustCost;

    if (catalogId === 'talent_reroll') {
        game.talentRerolls++;
        incrementDustShopPurchaseCount(game, shopKey);
        logMessage(game.t('log.dustCrystalBought', { total: game.talentRerolls }));
    } else if (catalogId === 'talent_choice') {
        game.talentChoices++;
        incrementDustShopPurchaseCount(game, shopKey);
        logMessage(game.t('log.dustOrbBought', { total: game.talentChoices }));
    } else if (catalogId === 'auto_catcher') {
        game.hasAutoCatcher = true;
        toast.legendary(game.t('toast.systemUpgradeTitle'), game.t('toast.systemUpgradeBody'));
        logMessage(game.t('log.dustAutoCatchEnabled'));
        game.updateAutoCatcherUI();
    } else if (catalogId === 'radar_slot_plus') {
        game.dustShopRadarSlotBonus = 1;
        toast.legendary(game.t('toast.systemUpgradeTitle'), game.t('toast.radarSlotPlusBody'));
        logMessage(game.t('log.dustRadarSlotPlusEnabled'));
    } else if (item.type === 'item' && item.item) {
        const qty = item.amount || 1;
        game.addItem(item.item, qty);
        incrementDustShopPurchaseCount(game, shopKey);
        logMessage(game.t('log.dustItemBought', {
            name: game.getLocalizedShopEntryName('dustShop', catalogId, item.name ?? catalogId),
            qty,
        }));
    }

    game.syncTalentConsumablesInInventory();
    game.updateRecyclerDisplay();
    game.updatePlayerStatsDisplay();
    game.updateItemsDisplay();
}
