/// <reference types="svelte" />
import { facade } from '@bus/facade';
import { GameEventType as Evt } from '../bus/events.js';
import type { PokedexSnapshot } from '../bus/snapshots.js';

const EMPTY: PokedexSnapshot = {
  languageTag: 'fr',
  ui: {
    language: 'fr',
    subTabsAriaLabel: '',
    subMain: '',
    subBonus: '',
    title: '',
    discovered: '',
    genAll: '',
    gen1: '',
    gen2: '',
    gen3: '',
    gen4: '',
    gen5: '',
    gen6: '',
    gen7: '',
    gen8: '',
    gen9: '',
    collectionTitle: '',
    collectionHint: '',
    collectionFilterAll: '',
    collectionFilterCompletable: '',
  },
  pokedexCount: '0',
  pokedexTotal: '?',
  activeSubTab: 'pokedex',
  sortButtons: [],
  collectionToolbarHtml: '',
  collectionTabsHtml: '',
  collectionTabsClass: 'collection-bonus-tabs',
  collectionBonusesHtml: '',
  cards: [],
  cardsEmptyMessage: '',
};

class PokedexStore {
  snapshot: PokedexSnapshot = $state(EMPTY);
}

export const pokedex = new PokedexStore();

facade.subscribe(Evt.POKEDEX_CHANGED, (evt) => {
  if (!('pokedex' in evt)) return;
  pokedex.snapshot = evt.pokedex;
});
