<script lang="ts">
  import { game } from '../../gameManager.ts';
  import type { GameRuntime } from '../types/game.js';
  import { Z_CRYSTAL_EFFECTS, Z_CRYSTAL_IDS } from '../../constants/balance/zRing.ts';
  import { useGameLanguageTick } from '../lib/useGameLanguageTick.svelte.ts';
  import { useFacadeSubscription } from '../lib/useFacadeSubscription.ts';
  import { GameEventType as Evt } from '../bus/events.js';

  const { trackGameLanguage } = useGameLanguageTick();

  let zRingGen = $state(0);

  useFacadeSubscription(Evt.Z_RING_CHANGED, () => {
    zRingGen += 1;
  });

  function t(key: string, fallback: string): string {
    const gm = game as GameRuntime | null;
    if (!gm?.t) return fallback;
    const got = gm.t(key);
    return got && got !== key ? got : fallback;
  }

  let visible = $derived.by(() => {
    void zRingGen;
    trackGameLanguage();
    const gm = game as GameRuntime | null;
    return !!(gm?.zRingState?.unlockedCrystalIds?.length);
  });

  let unlocked = $derived.by(() => {
    void zRingGen;
    const gm = game as GameRuntime | null;
    return gm?.zRingState?.unlockedCrystalIds ?? [];
  });

  let activeId = $derived.by(() => {
    void zRingGen;
    const gm = game as GameRuntime | null;
    return gm?.zRingState?.activeCrystalId ?? null;
  });

  function labelFor(id: string): string {
    trackGameLanguage();
    const def = Z_CRYSTAL_EFFECTS[id as keyof typeof Z_CRYSTAL_EFFECTS];
    if (!def) return id;
    const lang = (game as GameRuntime | null)?.language === 'en' ? 'en' : 'fr';
    return lang === 'en' ? def.moveNameEn : def.moveNameFr;
  }

  function descFor(id: string): string {
    const def = Z_CRYSTAL_EFFECTS[id as keyof typeof Z_CRYSTAL_EFFECTS];
    if (!def) return '';
    const lang = (game as GameRuntime | null)?.language === 'en' ? 'en' : 'fr';
    return lang === 'en' ? def.descEn : def.descFr;
  }

  function selectCrystal(id: string): void {
    const gm = game as GameRuntime | null;
    if (!gm?.setActiveZCrystal) return;
    if (gm.setActiveZCrystal(id)) {
      zRingGen += 1;
    }
  }
</script>

{#if visible}
  <div class="z-ring-picker" id="zRingPicker">
    <h3 class="z-ring-picker-title">{t('zRing.title', 'Anneau Z')}</h3>
    <p class="z-ring-picker-hint">{t('zRing.hint', 'Un seul cristal actif. Effets actifs aussi en PVP ; changement de cristal indisponible en arène, tour, métro ou combat dresseur.')}</p>
    <div class="z-ring-crystal-grid">
      {#each Z_CRYSTAL_IDS as crystalId (crystalId)}
        {@const isUnlocked = unlocked.includes(crystalId)}
        {@const isActive = activeId === crystalId}
        <button
          type="button"
          class="z-ring-crystal-btn"
          class:z-ring-crystal-btn--active={isActive}
          class:z-ring-crystal-btn--locked={!isUnlocked}
          disabled={!isUnlocked}
          title={isUnlocked ? descFor(crystalId) : t('zRing.lockedCrystal', 'Gagnez l\'épreuve correspondante.')}
          onclick={() => selectCrystal(crystalId)}
        >
          <span class="z-ring-crystal-name">{labelFor(crystalId)}</span>
        </button>
      {/each}
    </div>
  </div>
{/if}

<style>
  .z-ring-picker {
    margin-top: 16px;
    padding: 12px;
    border: 1px solid #3a3a4a;
    border-radius: 8px;
    background: rgba(20, 20, 32, 0.6);
  }
  .z-ring-picker-title {
    margin: 0 0 6px;
    font-size: 14px;
    color: #e8d44a;
  }
  .z-ring-picker-hint {
    margin: 0 0 10px;
    font-size: 11px;
    color: #999;
  }
  .z-ring-crystal-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
    gap: 6px;
  }
  .z-ring-crystal-btn {
    padding: 8px 6px;
    font-size: 11px;
    border-radius: 6px;
    border: 1px solid #444;
    background: #2a2a38;
    color: #ddd;
    cursor: pointer;
  }
  .z-ring-crystal-btn--active {
    border-color: #e8d44a;
    box-shadow: 0 0 8px rgba(232, 212, 74, 0.35);
  }
  .z-ring-crystal-btn--locked {
    opacity: 0.4;
    cursor: not-allowed;
  }
</style>
