    GameClass.prototype.hasShadowOfSpecies = function (this: ThisGame, speciesName: string) {
        if (!this.pokedex || typeof this.pokedex !== 'object') return false;
        const targetName = String(speciesName || '');
        if (!targetName) return false;
        for (const entry of Object.values(this.pokedex)) {
            if (!entry || typeof entry !== 'object') continue;
            const e = entry as Record<string, unknown>;
            if (e.name !== targetName) continue;
            if (e.hasShadow || (e.shadowCount && (e.shadowCount as number) > 0)) return true;
        }
        return false;
    };

    GameClass.prototype.hasShadowOfSpeciesFamily = function (this: ThisGame, speciesName: string) {
        const targetName = String(speciesName || '');
        if (!targetName) return false;
        const targetFamily: string = EVOLUTION_FAMILIES[targetName] || targetName;
        if (!this.pokedex || typeof this.pokedex !== 'object') return false;
        for (const entry of Object.values(this.pokedex)) {
            if (!entry || typeof entry !== 'object') continue;
            const e = entry as Record<string, unknown>;
            if (!(e.hasShadow || (e.shadowCount && (e.shadowCount as number) > 0))) continue;
            const entryName = coerceStr(e.name);
            if (!entryName) continue;
            const entryFamily: string = EVOLUTION_FAMILIES[entryName] || entryName;
            if (entryFamily === targetFamily) return true;
        }
        return false;
    };

    GameClass.prototype.getPokemonBaseDefinition = function (this: ThisGame, name: string): { rarity: string; type: string } | null {
        if (!POKEMON_POOL) return null;
        const targetName = String(name || '');
        if (!targetName) return null;
        for (const [rarityKey, byType] of Object.entries(POKEMON_POOL)) {
            if (!byType || typeof byType !== 'object') continue;
            for (const [typeKey, list] of Object.entries(byType)) {
                if (Array.isArray(list) && list.indexOf(targetName) !== -1) {
                    return { rarity: rarityKey, type: typeKey };
                }
            }
        }
        return null;
    };

    GameClass.prototype.grantRocketShadowCreature = function (this: ThisGame, options: { showModal?: boolean } = {}): { creature: CreatureData; wasFusion: boolean } {
        const showModal = options.showModal !== false;
        const chosenName = pickRocketShadowSpeciesName(this);

        const baseDef = this.getPokemonBaseDefinition(chosenName) || { rarity: RARITY.EPIC, type: this.findTypeForPokemon(chosenName) ?? 'normal' };
        const level = 1;
        const secondaryType = (typeof POKEMON_SECONDARY_TYPES !== 'undefined' && POKEMON_SECONDARY_TYPES)
            ? POKEMON_SECONDARY_TYPES[chosenName]
            : undefined;

        const creature = new Creature(
            chosenName,
            baseDef.type,
            level,
            baseDef.rarity,
            false,
            false,
            secondaryType,
            false,
            false,
            true
        );

        (creature as unknown as { recalculateStats: () => void; heal: () => void }).recalculateStats();
        (creature as unknown as { recalculateStats: () => void; heal: () => void }).heal();

        const c = creature as unknown as CreatureData & { name: string; isShiny: boolean; isShadow: boolean; type: string; rarity: string };
        if (this.playerTeam && !Array.isArray(this.storage)) (this as Record<string, unknown>).storage = [];
        const existing = this.findCreatureByName(c.name, c.isShiny, c.isShadow);
        let wasFusion = false;
        if (existing) {
            this.processFusion(c, existing);
            wasFusion = true;
        } else {
            if (!Array.isArray(this.storage)) (this as Record<string, unknown>).storage = [];
            this.storage.push(c);
        }

        if (!this.pokedex || typeof this.pokedex !== 'object') (this as Record<string, unknown>).pokedex = {};
        const pokedexKey = c.name + "_" + c.type + "_" + c.rarity;
        const existingPokedexEntry =
            this.pokedex[pokedexKey] ||
            Object.values(this.pokedex).find((e: unknown) => e && (e as Record<string, unknown>).name === c.name && (e as Record<string, unknown>).type === c.type && (e as Record<string, unknown>).rarity === c.rarity) as Record<string, unknown> | undefined;

        if (!existingPokedexEntry) {
            this.pokedex[pokedexKey] = {
                seen: true,
                caught: true,
                shinySeen: false,
                shinyCaught: false,
                count: 1,
                discovered: true,
                shadowCount: 1,
                hasShadow: true,
                name: c.name,
                type: c.type,
                rarity: c.rarity,
                firstDiscoveredAt: Date.now()
            };
            logMessage(this.t('log.pokedexNew', { name: c.name, shiny: '' }));
            if (typeof this.checkSpecialQuests === 'function') this.checkSpecialQuests('new_discovery');
        } else {
            existingPokedexEntry.count = (Number(existingPokedexEntry.count) || 0) + 1;
            existingPokedexEntry.shadowCount = ((existingPokedexEntry.shadowCount as number) || 0) + 1;
            existingPokedexEntry.hasShadow = true;
        }

        this.stats.shadowiesObtained = (this.stats.shadowiesObtained || 0) + 1;

        if (typeof this.trackHolyGrailCreature === 'function') this.trackHolyGrailCreature(c);
        if (c.rarity === RARITY.LEGENDARY && typeof this.checkSpecialQuests === 'function') {
            this.checkSpecialQuests('legendary_obtained');
        }

        if (showModal) {
            this.showRocketShadowRewardModal(c, { wasFusion });
        }

        return { creature: c, wasFusion };
    };

    GameClass.prototype.grantRocketCasinoEasterEggReward = function (this: ThisGame) {
        const { creature, wasFusion } = this.grantRocketShadowCreature({ showModal: false });
        logMessage(this.t('log.rocketCasinoEasterEgg', { name: creature.name }));
        this.showRocketShadowRewardModal(creature, { wasFusion });
    };

    GameClass.prototype.handleRocketCasinoLoss = function (this: ThisGame) {
        if (!this.teamRocketState || !this.teamRocketState.casino) return;
        const casino = this.teamRocketState.casino;
        const current = Math.max(0, Number(casino.easterEggLossStreak) || 0);
        casino.easterEggLossStreak = current + 1;
        if (casino.easterEggLossStreak >= 10) {
            casino.easterEggLossStreak = 0;
            this.grantRocketCasinoEasterEggReward();
        }
    };

    GameClass.prototype.rollRocketCasinoSymbol = function (this: ThisGame): { key: string; weight: number; id?: number | string } | null {
        const cfg = ROCKET_CASINO_CONFIG as unknown as { symbols?: Array<{ key: string; weight: number; id?: number | string }> } | undefined;
        const symbols = Array.isArray(cfg?.symbols) ? cfg.symbols : [];
        if (symbols.length === 0) return null;
        const totalWeight = symbols.reduce((sum: number, s: { weight: number }) => sum + Math.max(0, Number(s.weight) || 0), 0) || 1;
        let r = Math.random() * totalWeight;
        for (const symbol of symbols) {
            r -= Math.max(0, Number(symbol.weight) || 0);
            if (r <= 0) return symbol;
        }
        return symbols[0] ?? null;
    };

    GameClass.prototype.generateRocketCasinoMatrix = function (this: ThisGame): string[][] {
        const matrix: string[][] = [[], [], []];
        for (let col = 0; col < 3; col++) {
            if (!matrix[col]) matrix[col] = [];
            for (let row = 0; row < 3; row++) {
                const symbol = this.rollRocketCasinoSymbol();
                matrix[col]![row] = symbol ? symbol.key : 'zubat';
            }
        }
        return matrix;
    };

    GameClass.prototype.evaluateRocketCasinoMatrix = function (this: ThisGame, matrix: string[][], activePaylines: number = 5): RocketCasinoEvaluation {
        const cfg = ROCKET_CASINO_CONFIG as unknown as { lineCostRJ?: number; symbols?: Array<{ key: string; id?: number | string }> } | undefined;
        const lineCost = Math.max(1, Math.floor(Number(cfg?.lineCostRJ) || 250));
        const allPaylines = this.getRocketCasinoPaylines();
        const maxPaylines = allPaylines.length;
        const paylines = allPaylines.slice(0, Math.max(1, Math.min(maxPaylines, Math.floor(Number(activePaylines) || maxPaylines))));
        const symbolMap = Object.fromEntries((cfg?.symbols || []).map((s: { key: string; id?: number | string }) => [s.key, s]));
        const winningLines: RocketCasinoWinLine[] = [];

        paylines.forEach((line: RocketCasinoPayline) => {
            const [aPos, bPos, cPos] = line.coords;
            if (!aPos || !bPos || !cPos) return;
            const [aRow, aColIdx] = aPos;
            const [bRow, bColIdx] = bPos;
            const [cRow, cColIdx] = cPos;
            if (aRow == null || aColIdx == null || bRow == null || bColIdx == null || cRow == null || cColIdx == null) return;
            const aColArr = matrix[aRow];
            const bColArr = matrix[bRow];
            const cColArr = matrix[cRow];
            const a = aColArr?.[aColIdx];
            const b = bColArr?.[bColIdx];
            const c = cColArr?.[cColIdx];
            if (!a || !b || !c) return;
            if (a !== b || b !== c) return;
            const sym = symbolMap[a];
            winningLines.push({
                lineId: line.id,
                lineLabel: line.label,
                symbolKey: a,
                symbolId: sym && sym.id ? sym.id : null,
                coords: line.coords
            });
        });
        return { totalPayout: 0, winningLines, lineCost, linesPlayed: paylines.length };
    };

    GameClass.prototype.pickRocketWeightedReward = function (this: ThisGame, pool: unknown[]) {
        const candidates = Array.isArray(pool) ? pool.filter(Boolean) : [];
        if (candidates.length === 0) return null;
        const totalWeight = candidates.reduce((sum: number, entry: unknown) => sum + Math.max(0, Number((entry as Record<string, unknown>).weight) || 0), 0) || 1;
        let r = Math.random() * totalWeight;
        for (const entry of candidates) {
            r -= Math.max(0, Number((entry as Record<string, unknown>).weight) || 0);
            if (r <= 0) return entry;
        }
        return candidates[0];
    };

    GameClass.prototype.getRocketSlotRewardPool = function (this: ThisGame, symbolId: number | string | null | undefined) {
        if (typeof SLOT_REWARDS === 'undefined' || !Array.isArray(SLOT_REWARDS)) return [];
        return (SLOT_REWARDS as Array<Record<string, unknown>>).filter((entry: Record<string, unknown>) => entry && entry.symbolId === symbolId);
    };

    GameClass.prototype.computeRocketCasinoScaledPokedollars = function (this: ThisGame, multiplier: number = 1) {
        const totalEarned = Math.max(0, Number(this.stats && this.stats.totalPokedollarsEarned) || 0);
        const base = Math.max(1800, Math.floor(totalEarned * 0.0018));
        const amount = Math.floor(base * Math.max(0.2, Number(multiplier) || 1));
        return Math.max(500, Math.min(5000000, amount));
    };

    GameClass.prototype.resolveRocketCasinoLineRewards = function (this: ThisGame, win: RocketCasinoWinLine) {
        const symbolId = win && win.symbolId ? win.symbolId : null;
        if (!symbolId) return [] as unknown[];

        const pickFrom = (id: number | string, predicate: ((entry: Record<string, unknown>) => boolean) | null = null): Record<string, unknown> | null => {
            const pool = (this.getRocketSlotRewardPool(id) as Array<Record<string, unknown>>).filter((entry: Record<string, unknown>) => (typeof predicate === 'function' ? predicate(entry) : true));
            return this.pickRocketWeightedReward(pool) as Record<string, unknown> | null;
        };
        const rewards: Record<string, unknown>[] = [];
        const pushIf = (entry: Record<string, unknown> | null) => { if (entry) rewards.push({ ...entry }); };
        const pushScaledMoney = (id: number | string) => {
            const moneyReward = pickFrom(id, (entry: Record<string, unknown>) => entry.rewardType === 'currency' && entry.targetId === 'pokedollars_scaled');
            pushIf(moneyReward);
        };

        if (symbolId === 'ID_1') {
            pushScaledMoney('ID_1');
            return rewards;
        }

        if (symbolId === 'ID_2') {
            pushScaledMoney('ID_2');
            pushIf(pickFrom('ID_2', (entry: Record<string, unknown>) => entry.rewardType !== 'currency' || entry.targetId !== 'pokedollars_scaled'));
            return rewards;
        }

        if (symbolId === 'ID_3') {
            pushScaledMoney('ID_3');
            pushIf(pickFrom('ID_2', (entry: Record<string, unknown>) => entry.rewardType !== 'currency' || entry.targetId !== 'pokedollars_scaled'));
            pushIf(pickFrom('ID_3', (entry: Record<string, unknown>) => entry.rewardType === 'item'));
            return rewards;
        }

        if (symbolId === 'ID_4') {
            pushScaledMoney('ID_4');
            pushIf(pickFrom('ID_4', (entry: Record<string, unknown>) => entry.rewardType === 'item'));
            pushIf(pickFrom('ID_4', (entry: Record<string, unknown>) => entry.rewardType === 'quest_token' || (entry.rewardType === 'currency' && entry.targetId === 'marques_du_triomphe')));
            return rewards;
        }

        if (symbolId === 'ID_6') {
            pushScaledMoney('ID_1');
            pushScaledMoney('ID_2');
            pushScaledMoney('ID_4');
            pushScaledMoney('ID_6');
            pushIf(pickFrom('ID_2', (entry: Record<string, unknown>) => entry.rewardType !== 'currency' || entry.targetId !== 'pokedollars_scaled'));
            pushIf(pickFrom('ID_4', (entry: Record<string, unknown>) => entry.rewardType === 'item'));
            pushIf(pickFrom('ID_4', (entry: Record<string, unknown>) => entry.rewardType === 'quest_token' || (entry.rewardType === 'currency' && entry.targetId === 'marques_du_triomphe')));
            pushIf(pickFrom('ID_6', (entry: Record<string, unknown>) => entry.rewardType === 'item'));
            return rewards;
        }

        if (symbolId === 'ID_5') {
            // Miaouss jackpot: reprend les gains cumulés + bonus Giovanni + CT.
            pushScaledMoney('ID_1');
            pushScaledMoney('ID_2');
            pushScaledMoney('ID_4');
            pushScaledMoney('ID_5');
            pushIf(pickFrom('ID_2', (entry: Record<string, unknown>) => entry.rewardType !== 'currency' || entry.targetId !== 'pokedollars_scaled'));
            pushIf(pickFrom('ID_4', (entry: Record<string, unknown>) => entry.rewardType === 'item'));
            pushIf(pickFrom('ID_4', (entry: Record<string, unknown>) => entry.rewardType === 'quest_token' || (entry.rewardType === 'currency' && entry.targetId === 'marques_du_triomphe')));
            pushIf(pickFrom('ID_6', (entry: Record<string, unknown>) => entry.rewardType === 'item'));
            pushIf(pickFrom('ID_5', (entry: Record<string, unknown>) => entry.rewardType === 'item' && coerceStr(entry.targetId).startsWith('ct_') && this.isDamagingCtItemKey(coerceStr(entry.targetId))));
            pushIf(pickFrom('ID_5', (entry: Record<string, unknown>) => entry.rewardType === 'item' && coerceStr(entry.targetId) === MIAOUSS_STATUETTE_ITEM_KEY));
            return rewards;
        }

        pushScaledMoney(symbolId);
        return rewards;
    };

    GameClass.prototype.applyRocketCasinoRewards = function (this: ThisGame, rawRewards: unknown[]): RocketCasinoRewardsResult {
        const rewards = Array.isArray(rawRewards) ? rawRewards as Array<Record<string, unknown>> : [];
        if (!this.items) (this as Record<string, unknown>).items = {};
        const aggregated: Record<string, { rewardType: string; targetId: string; amount: number }> = {};

        const trustLevel = Math.max(1, Math.floor(Number(this.teamRocketState && this.teamRocketState.trustLevel) || 1));
        const trustScaledCurrency: Record<string, boolean> = { pokedollars_scaled: true, pokedollars: true, marques_du_triomphe: true, essence_dust: true };
        const trustScaledItems: Record<string, boolean> = { hyperball: true, greatball: true, time_dust_1h: true, prism_iv: true, dynite_ore: true, time_dust_3h: true };

        rewards.forEach((entry: Record<string, unknown>) => {
            if (!entry || !entry.rewardType) return;
            const rewardType = coerceStr(entry.rewardType);
            const targetId = coerceStr(entry.targetId);
            const sourceAmount = Math.max(0, Number(entry.amount) || 0);
            let amount = sourceAmount;
            if (rewardType === 'currency' && targetId === 'pokedollars_scaled') {
                amount = this.computeRocketCasinoScaledPokedollars(sourceAmount || 1);
            }
            if (amount <= 0 && rewardType !== 'jackpot') return;
            const isScaled = (rewardType === 'currency' && trustScaledCurrency[targetId])
                || (rewardType === 'quest_token' && targetId === 'quest_token')
                || (rewardType === 'item' && trustScaledItems[targetId]);
            if (isScaled) {
                amount = (rewardType === 'currency') ? (amount * trustLevel) : Math.floor(amount * trustLevel);
            }
            const key = `${rewardType}:${targetId || 'none'}`;
            if (!aggregated[key]) {
                aggregated[key] = { rewardType, targetId, amount: 0 };
            }
            aggregated[key].amount += amount;
        });

        const finalRewards = Object.values(aggregated);
        const rewardMessages: string[] = [];
        let jackpotCount = 0;
        const isEn = this.normalizeLanguage(this.language) === 'en';

        finalRewards.forEach((reward: { rewardType: string; targetId: string; amount: number }) => {
            const amount = Math.floor(Number(reward.amount) || 0);
            if (reward.rewardType === 'currency') {
                if (reward.targetId === 'pokedollars_scaled' || reward.targetId === 'pokedollars') {
                    const pdResult = typeof this.addCombatPokedollars === 'function'
                        ? this.addCombatPokedollars(amount, 'silent')
                        : { creditedToWallet: amount, net: amount };
                    const credited = Math.max(0, Number(pdResult.creditedToWallet ?? pdResult.net) || 0);
                    rewardMessages.push(`+${formatNumber(credited)} ${this.t('offline.moneyLabel')}`);
                } else if (reward.targetId === 'marques_du_triomphe') {
                    this.triumphMarks = (this.triumphMarks || 0) + amount;
                    if (this.stats) this.stats.totalTriumphMarksEarned = (this.stats.totalTriumphMarksEarned || 0) + amount;
                    rewardMessages.push(`+${formatNumber(amount)} ${isEn ? 'Triumph Marks' : 'Marques du Triomphe'}`);
                } else if (reward.targetId === 'essence_dust') {
                    this.essenceDust = (this.essenceDust || 0) + amount;
                    rewardMessages.push(`+${formatNumber(amount)} ${isEn ? 'Essence dust' : 'Poussiere d essence'}`);
                }
            } else if (reward.rewardType === 'quest_token') {
                this.questTokens = (this.questTokens || 0) + amount;
                if (this.stats) this.stats.totalQuestTokensEarned = (this.stats.totalQuestTokensEarned || 0) + amount;
                rewardMessages.push(`+${formatNumber(amount)} ${isEn ? 'Quest Tokens' : 'Jetons de Quete'}`);
            } else if (reward.rewardType === 'item') {
                if (typeof reward.targetId === 'string' && reward.targetId.startsWith('ct_') && !this.isDamagingCtItemKey(reward.targetId)) {
                    return;
                }
                this.addItem(reward.targetId, amount, false);
                const itemDef = (typeof ALL_ITEMS !== 'undefined' && ALL_ITEMS) ? (ALL_ITEMS as Record<string, unknown>)[reward.targetId] as Record<string, unknown> | undefined : undefined;
                const itemName = this.getLocalizedItemName(reward.targetId, itemDef ? coalesceStr(itemDef.name, reward.targetId) : reward.targetId, itemDef);
                rewardMessages.push(`+${formatNumber(amount)} ${itemName}`);
                if (reward.targetId === MIAOUSS_STATUETTE_ITEM_KEY) {
                    jackpotCount++;
                    rewardMessages.push(isEn ? 'MEOWTH JACKPOT!' : 'JACKPOT MIAOUSS !');
                }
            } else if (reward.rewardType === 'jackpot') {
                jackpotCount++;
                rewardMessages.push(isEn ? 'MEOWTH JACKPOT!' : 'JACKPOT MIAOUSS !');
            }
        });

        if (finalRewards.some((r: { rewardType: string; targetId: string }) => r.rewardType === 'currency' && (r.targetId === 'pokedollars_scaled' || r.targetId === 'pokedollars'))) {
            this.checkSpecialQuests('pokedollars_gained');
            this.checkAchievements('totalPokedollarsEarned');
        }
        return { finalRewards, rewardMessages, jackpotCount };
    };

    GameClass.prototype.spinRocketSlot = function (this: ThisGame, linesPlayed: number | null = null): RocketSpinResult | null {
        if (typeof ROCKET_CASINO_CONFIG === 'undefined') return null;
        const cfg = ROCKET_CASINO_CONFIG as unknown as { defaultActivePaylines?: number; lineCostRJ?: number };
        const maxPaylines = this.getRocketCasinoPaylines().length;
        const defaultLines = Math.max(1, Math.min(maxPaylines, Math.floor(Number(cfg.defaultActivePaylines) || maxPaylines)));
        const activeLines = Math.max(1, Math.min(maxPaylines, Math.floor(Number(linesPlayed) || defaultLines)));
        const lineCost = Math.max(1, Math.floor(Number(cfg.lineCostRJ) || 500));
        let totalStake = lineCost * activeLines;

        if (this.upgrades && (this.upgrades as Record<string, unknown>).casinoRoyal) {
            const reduction = ((this.upgrades as Record<string, unknown>).casinoRoyal as { level: number }).level * 0.05;
            totalStake = Math.floor(totalStake * (1 - reduction));
        }

        if (this.teamRocketState.rj < totalStake) {
            logMessage(this.t('log.rocketCasinoNotEnoughRj', { cost: formatNumber(totalStake) }));
            return null;
        }

        const matrix = this.generateRocketCasinoMatrix();
        const evaluation = this.evaluateRocketCasinoMatrix(matrix, activeLines);
        if (isRocketCasinoFullBoard(evaluation.winningLines)) {
            this.stats.rocketCasinoFullBoards = Math.max(0, Number(this.stats.rocketCasinoFullBoards) || 0) + 1;
            this.checkAchievements('rocketCasinoFullBoards');
        }
        const rewardsToApply: unknown[] = [];
        evaluation.winningLines.forEach((win: RocketCasinoWinLine) => {
            rewardsToApply.push(...this.resolveRocketCasinoLineRewards(win));
        });

        this.teamRocketState.rj -= totalStake;
        this.teamRocketState.casino.stats.spins++;
        this.teamRocketState.casino.stats.rjSpent += totalStake;
        if (this.teamRocketState && this.teamRocketState.staking && this.teamRocketState.staking.activeSession) {
            this.stats.rocketDoubleOrNothing = Math.max(0, Number(this.stats.rocketDoubleOrNothing) || 0) + 1;
            if (typeof this.checkSpecialQuests === 'function') this.checkSpecialQuests('rocket_double_or_nothing');
        }

        this.addRocketTrustProgress('spin', 1);
        this.stats.rocketCasinoSpins = (this.stats.rocketCasinoSpins || 0) + 1;
        this.checkAchievements('rocketCasinoSpins');
        if (typeof this.checkSpecialQuests === 'function') this.checkSpecialQuests('rocket_spins');

        const appliedRewards = this.applyRocketCasinoRewards(rewardsToApply);
        if (appliedRewards.jackpotCount > 0) {
            this.teamRocketState.casino.stats.jackpots += appliedRewards.jackpotCount;
        }

        const pokedollarsGain = (appliedRewards.finalRewards || [])
            .filter((r: unknown) => (r as Record<string, unknown>).rewardType === 'currency' && ((r as Record<string, unknown>).targetId === 'pokedollars_scaled' || (r as Record<string, unknown>).targetId === 'pokedollars'))
            .reduce((sum: number, r: unknown) => sum + (Math.floor(Number((r as Record<string, unknown>).amount)) || 0), 0);

        let insuranceRjRefund = 0;
        if (appliedRewards.rewardMessages.length > 0) {
            this.stats.rocketCasinoWinningSpins = Math.max(0, Number(this.stats.rocketCasinoWinningSpins) || 0) + 1;
            if (typeof this.checkSpecialQuests === 'function') this.checkSpecialQuests('rocket_precision_gambler');
            this.teamRocketState.casino.easterEggLossStreak = 0;
            this.teamRocketState.casino.insuranceLossStreak = 0;
            logMessage(this.t('log.rocketCasinoResult', { result: appliedRewards.rewardMessages.join('  ') }));
        } else {
            const casino = this.teamRocketState.casino;
            const streakMastery = (this.getMasteryBonus && (this.getMasteryBonus('rocket_insurance_streak') || 0) > 0);
            const lossStreak = Math.max(0, Math.floor(Number(casino.insuranceLossStreak) || 0));
            const streakRefund = streakMastery && lossStreak >= 2;

            if (streakRefund) {
                insuranceRjRefund = totalStake;
                this.teamRocketState.rj = (this.teamRocketState.rj || 0) + insuranceRjRefund;
                casino.stats.rjSpent = Math.max(0, (casino.stats.rjSpent || 0) - insuranceRjRefund);
                casino.insuranceLossStreak = 0;
                const msg = this.t('log.rocketCasinoInsuranceStreakRefund', { amount: formatNumber(insuranceRjRefund) });
                logMessage(msg);
                if (typeof toast !== 'undefined' && toast.success) {
                    toast.success(this.t('toast.rocketStealTitle'), msg);
                }
            } else {
                this.handleRocketCasinoLoss();
                if (streakMastery) {
                    casino.insuranceLossStreak = lossStreak + 1;
                }
                const insP = (this.getMasteryBonus && this.getMasteryBonus('rocket_insurance_token')) || 0;
                if (insP > 0 && Math.random() < Math.min(0.25, insP)) {
                    insuranceRjRefund = totalStake;
                    this.teamRocketState.rj = (this.teamRocketState.rj || 0) + insuranceRjRefund;
                    casino.stats.rjSpent = Math.max(0, (casino.stats.rjSpent || 0) - insuranceRjRefund);
                    const msg = this.t('log.rocketCasinoInsuranceRefund', { amount: formatNumber(insuranceRjRefund) });
                    logMessage(msg);
                    if (typeof toast !== 'undefined' && toast.success) {
                        toast.success(this.t('toast.rocketStealTitle'), msg);
                    }
                } else {
                    logMessage(this.t('log.rocketCasinoLost'));
                }
            }
        }

        if (!this.teamRocketState.casino.history) this.teamRocketState.casino.history = [];
        this.teamRocketState.casino.history.unshift({
            at: Date.now(),
            stake: totalStake,
            pokedollarsGain,
            insuranceRjRefund: insuranceRjRefund,
            matrix: matrix.map((col: string[]) => col.slice()),
            winningLines: evaluation.winningLines.map((w: RocketCasinoWinLine) => ({ ...w })),
            rewards: appliedRewards.finalRewards.map((r: unknown) => ({ ...(r as Record<string, unknown>) })),
            rewardMessages: appliedRewards.rewardMessages.slice()
        });
        this.teamRocketState.casino.history = this.teamRocketState.casino.history.slice(0, 12);

        return {
            matrix,
            winningLines: evaluation.winningLines,
            stake: totalStake,
            pokedollarsGain,
            rewards: appliedRewards.finalRewards,
            rewardMessages: appliedRewards.rewardMessages,
            lineCost,
            linesPlayed: activeLines
        };
    };

