    GameClass.prototype.resetRocketBankInterestCounter = function (this: ThisGame) {
        const tr = this.teamRocketState;
        if (!tr || !tr.bank) return false;
        const bank = tr.bank;
        const currentDisplayBase = Math.max(0, Number(bank.totalInterestGenerated) || 0) + Math.max(0, Number(bank.interestCarry) || 0);
        bank.interestDisplayOffset = currentDisplayBase;
        bank.interestSinceReset = 0;
        bank.lastResetAt = Date.now();
        logMessage(this.t('log.rocketInterestReset'));
        return true;
    };

    /**
     * Calcule les metriques type "DPS meter" pour la banque Team Rocket.
     * - instantPerHour : dernier tick * 60 (rythme courant)
     * - avg1hPerHour : moyenne sur la fenetre 60 dernieres minutes (extrapolee si < 60)
     * - peakAllTime : record absolu, persistant
     * - projection24h : instantPerHour * 24
     * - sparkline : tableau des 60 derniers samples (gain/min) + max pour normalisation
     */
    GameClass.prototype.getRocketBankInterestStats = function (this: ThisGame): { instantPerMin: number; instantPerHour: number; projection24h: number } {
        const tr = this.teamRocketState;
        const bank = (tr && tr.bank) ? tr.bank : null;
        const empty = { instantPerMin: 0, instantPerHour: 0, projection24h: 0 };
        if (!bank) return empty;
        const balance = Math.max(0, Number(bank.balance) || 0);
        const trustLevel = Math.max(1, Math.floor(Number(tr.trustLevel) || 1));
        const ratePerHour = trustLevel / 100;
        const instantPerHour = Math.floor(balance * ratePerHour);
        const instantPerMin = Math.floor(balance * ratePerHour / 60);
        const projection24h = instantPerHour * 24;
        return { instantPerMin, instantPerHour, projection24h };
    };

