    /**
     * Auto-spin amelioration : niveau actuel (0..4).
     * Debloque par paliers via la boutique aux Jetons, cap dynamique lie a la Confiance Rocket.
     */
    GameClass.prototype.getRocketAutoSpinLevel = function (this: ThisGame) {
        if (!this.permanentBoosts) return 0;
        const lvl = Math.floor(Number(this.permanentBoosts.rocketAutoSpin) || 0);
        return Math.max(0, Math.min(4, lvl));
    };

    /** Nombre d'auto-spins disponibles par session (3 par niveau d'amelioration). */
    GameClass.prototype.getRocketAutoSpinCount = function (this: ThisGame) {
        const base = this.getRocketAutoSpinLevel() * 3;
        const bonus = this.getMasteryBonus
            ? Math.floor(this.getMasteryBonus('rocket_auto_spin_bonus') || 0)
            : 0;
        return base + bonus;
    };

    /** Bonus de vitesse d'animation (0..0.40). */
    GameClass.prototype.getRocketAutoSpinSpeedBonus = function (this: ThisGame) {
        return this.getRocketAutoSpinLevel() * 0.10;
    };

    /** Niveau max d'amelioration debloque par la Confiance Rocket actuelle (palier N => Confiance >= N+1). */
    GameClass.prototype.getRocketAutoSpinMaxLevelAllowed = function (this: ThisGame) {
        const trustLevel = Math.max(1, Math.floor(Number(this.teamRocketState && this.teamRocketState.trustLevel) || 1));
        return Math.max(0, Math.min(4, trustLevel - 1));
    };

    GameClass.prototype.handleRocketCasinoSpin = function (this: ThisGame, linesPlayed: number | null = null) {
        const cfg = typeof ROCKET_CASINO_CONFIG !== 'undefined' ? ROCKET_CASINO_CONFIG as unknown as { defaultActivePaylines?: number } : {};
        const maxPaylines = this.getRocketCasinoPaylines().length;
        const defaultLines = Math.max(1, Math.min(maxPaylines, Math.floor(Number(cfg.defaultActivePaylines) || maxPaylines)));
        const lines = Math.max(1, Math.min(maxPaylines, Math.floor(Number(linesPlayed) || defaultLines)));
        return this.handleRocketCasinoSpinAmount(lines);
    };

    GameClass.prototype.handleRocketCasinoSpinAmount = function (this: ThisGame, linesPlayed: number | null = null) {
        const result = this.spinRocketSlot(linesPlayed);
        if (!document.getElementById('rocketCasinoOverlay')) {
            this.updateTeamRocketDisplay();
        }
        return result;
    };

    GameClass.prototype.buildRocketShadowRewardDisplayPayload = function (this: ThisGame, creature: CreatureData, options: Record<string, unknown> = {}) {
        const wasFusion = !!options.wasFusion;
        const title = this.t('shadowReward.title');
        const subtitle = this.t('shadowReward.subtitle');
        const maxLv = 100 + (Number(creature.prestige) || 0) * 10;
        const shadowBadgeLabel = this.t('shadowReward.shadowBadge');

        let talentHTML = '';
        if (creature.passiveTalent) {
            const creatureObj = creature as unknown as { getTalentInfo: () => { name: string } };
            const talent = creatureObj.getTalentInfo();
            const talentName = this.getLocalizedPassiveTalentName(creature.passiveTalent, talent ? talent.name : creature.passiveTalent);
            talentHTML = `<div style="font-size: 14px; margin-top: 5px;"><strong>${this.t('egg.talent')}:</strong> ${talentName}</div>`;
        }
        let ultimateHTML = '';
        if (creature.ultimateAbility) {
            const ultName = this.getLocalizedUltimateName(creature.name, creature.ultimateAbility.name);
            ultimateHTML = `<div style="font-size: 14px; margin-top: 5px;"><strong>${this.t('egg.ultimate')}:</strong> ${ultName}</div>`;
        }

        const fusionNote = wasFusion
            ? `<div class="rocket-shadow-fusion-note">${this.t('shadowReward.fusionNote')}</div>`
            : '';

        const statsHTML = `${fusionNote}
                <div class="rocket-shadow-level-line"><strong>${this.t('shadowReward.levelLine', { current: creature.level, max: maxLv })}</strong></div>
                <strong>${this.t('egg.baseStats')}:</strong><br>
                ${this.t('egg.statsInline', { atk: creature.attack, def: creature.defense, speed: creature.speed, hp: creature.maxHp })}
                <br>
                <span style='color:#93c5fd; font-weight:bold;'>${this.t('egg.ivsLine', { hp: creature.ivHP, atk: creature.ivAttack, def: creature.ivDefense, speed: creature.ivSpeed })}</span>
                ${talentHTML}
                ${ultimateHTML}`;

        const spriteUrl = getPokemonSpriteUrl(creature.name, creature.isShiny, false);

        return {
            data: {
                title,
                subtitle,
                shadowBadgeLabel,
                spriteUrl,
                name: creature.name,
                type: creature.type,
                secondaryType: creature.secondaryType || '',
                statsHTML,
                rarityBadgeLabel: this.getEggRarityBadgeLabel(creature.rarity),
                rarity: creature.rarity,
                confirmLabel: this.t('egg.confirm')
            }
        };
    };

    GameClass.prototype.showRocketShadowRewardModal = function (this: ThisGame, creature: CreatureData, options: Record<string, unknown> = {}) {
        if (this.isOfflineSimulating) return;
        const modal = document.getElementById('rocketShadowRewardModal');
        const content = document.getElementById('rocketShadowRewardContent');
        if (!modal || !content) return;

        const payload = this.buildRocketShadowRewardDisplayPayload(creature, options);
        showRocketShadowRewardModalUI(modal, content, payload.data, { rarity: creature.rarity });
    };

