    /**
     * Affiche un toast pedagogique la premiere fois que le joueur utilise sa banque.
     * Pointe vers l'option "Injecter 50% des gains de combat" cachee derriere la roue dentee.
     */
    GameClass.prototype.maybeShowRocketBankFeatureToast = function (this: ThisGame) {
        const tr = this.teamRocketState;
        if (!tr || !tr.bank) return;
        if (tr.bank.featureToastShown) return;
        const balance = Math.max(0, Number(tr.bank.balance) || 0);
        const totalInterest = Math.max(0, Number(tr.bank.totalInterestGenerated) || 0);
        if (balance <= 0 && totalInterest <= 0) return;
        if (typeof toast === 'undefined' || !toast || typeof toast.info !== 'function') return;
        tr.bank.featureToastShown = true;
        const title = this.t('toast.rocketBankFeatureTitle');
        const body = this.t('toast.rocketBankFeatureBody');
        toast.info(title, body, 9000);
    };

