<script lang="ts">
  import { rocket } from '../../stores/rocket.svelte.ts';
  import { mainTab } from '../../stores/mainTab.svelte.ts';
  import {
    resolveRocketCombatMiniBarVisibility,
    resolveRocketStakingSessionForUi,
    resolveMobileExtrasPanelActive,
  } from '../../lib/rocketCombatMiniBar.ts';
  import { MOBILE_PANEL_CHANGED_EVENT } from '../../ui/mobile.ts';
  import RocketStakingMiniBar from './RocketStakingMiniBar.svelte';
  import RocketCasinoMiniBar from './RocketCasinoMiniBar.svelte';

  let { placement = 'inline' }: { placement?: 'inline' | 'dock' } = $props();

  let mobilePanelEpoch = $state(0);

  $effect(() => {
    const bump = () => {
      mobilePanelEpoch += 1;
    };
    window.addEventListener(MOBILE_PANEL_CHANGED_EVENT, bump);
    return () => window.removeEventListener(MOBILE_PANEL_CHANGED_EVENT, bump);
  });

  let visibility = $derived.by(() => {
    void mobilePanelEpoch;
    return resolveRocketCombatMiniBarVisibility({
      stakingSession: resolveRocketStakingSessionForUi(
        rocket.snapshot.staking,
        rocket.realtime,
      ),
      casinoBackgroundSession: rocket.casinoModal.backgroundSession,
      isTeamRocketTabActive: mainTab.isTeamRocketTabActive,
      isMobileExtrasPanelActive: resolveMobileExtrasPanelActive(),
    });
  });
</script>

{#if visibility.showStakingMini}
  <RocketStakingMiniBar {placement} />
{:else if visibility.showCasinoMini}
  <RocketCasinoMiniBar {placement} />
{/if}
