/// <reference types="svelte" />
/**
 * Store: quests — QuestPanel daily/story/rocket list
 */

import { facade } from '@bus/facade';
import { GameEventType as Evt } from '../bus/events.js';
import type { AchievementsSnapshot, QuestsSnapshot } from '../bus/snapshots.js';
import { captureUiScrollPositions, restoreUiScrollPositions } from '../lib/uiScrollPreserve.ts';
import { deferIfMobileScrolling } from '../lib/mobileScrollGate.ts';

const EMPTY_ACHIEVEMENTS: AchievementsSnapshot = {
  language: 'fr',
  emptyHtml: null,
  categories: [],
  achievementsCount: 0,
  achievementsTotal: 0,
};

const EMPTY: QuestsSnapshot = {
  ui: {
    language: 'fr',
    subTabQuests: 'Quêtes',
    subTabAchievements: 'Succès',
    dailyTitle: 'Quêtes du Jour',
    nextLabel: 'Prochaine :',
    achievementsTitle: 'Succès Permanents',
    subTabsAriaLabel: 'Sous-sections quêtes',
  },
  emptyMessage: null,
  storySection: null,
  rocketSection: null,
  weeklySection: { unlocked: false, weekKey: '', sectionTitle: '', sectionDesc: '', challenges: [] },
  classicQuests: [],
  classicQuestsUnlocked: false,
  rocketUnlocked: false,
  questCount: 0,
  questTokens: 0,
  questsCompleted: 0,
};

class QuestsStore {
  snapshot: QuestsSnapshot = $state(EMPTY);
  achievements: AchievementsSnapshot = $state(EMPTY_ACHIEVEMENTS);
}

export const quests = new QuestsStore();

facade.subscribe(Evt.QUESTS_CHANGED, (evt) => {
  if (!('quests' in evt)) return;
  deferIfMobileScrolling('quests', () => {
    const scrollSaved = captureUiScrollPositions();
    quests.snapshot = evt.quests;
    restoreUiScrollPositions(scrollSaved);
  });
});

facade.subscribe(Evt.ACHIEVEMENTS_CHANGED, (evt) => {
  if (!('achievements' in evt)) return;
  quests.achievements = evt.achievements;
});
