<script lang="ts">
  import { miltankFarm } from '../stores/miltankFarm.svelte.ts';
  import { game } from '../../gameManager.ts';
  import type { GameRuntime } from '../types/game.ts';
  import { updateCombatDisplayUI } from '../ui/combatDisplay.ts';

  let snap = $derived(miltankFarm.snapshot);
  let visible = $derived(snap.farmThreatCombatActive);

  let bannerSubtitle = $derived.by((): string => {
    const gm = game as GameRuntime | null;
    const gts = gm?.gymTrainerState;
    if (!gts?.isFarmThreat) return '';
    const pastureName = snap.pastureSprites.find((s) => s.uid === gts.farmPastureUid)?.name ?? null;
    const threat = snap.activeThreatSprites.find((t) => t.id === gts.farmThreatId);
    const detail = threat?.label ?? gts.trainerName ?? '';
    if (pastureName && detail) return `${pastureName} · ${detail}`;
    return pastureName ?? detail;
  });

  $effect(() => {
    const active = visible;
    document.body.classList.toggle('farm-threat-combat-active', active);
    if (active) {
      const gm = game as GameRuntime | null;
      if (gm) {
        requestAnimationFrame(() => updateCombatDisplayUI(gm));
      }
    }
    return () => {
      document.body.classList.remove('farm-threat-combat-active');
    };
  });
</script>

{#if visible}
  <div class="farm-threat-combat-banner" role="status" aria-live="polite">
    <span class="farm-threat-combat-banner-title">{snap.ui.threatCombatBanner}</span>
    {#if bannerSubtitle}
      <span class="farm-threat-combat-banner-detail">{bannerSubtitle}</span>
    {/if}
  </div>
{/if}
