/**
 * @file gameUltimateSlotSystem.ts
 * Ultimate slot: mentor Pokémon that buffs team stats (not combat / pension / account).
 */

import { Creature } from './Creature.ts';
import { toast } from './toastManager.ts';
import type { GameRuntime } from './src/types/game.js';
import type { CreatureData } from './src/types/creature.js';
import { isUltimateSlotUnlocked, shouldShowUltimateSlotIntro } from './src/lib/playerCombatRoster.ts';
import { publishTeamChanged } from './src/bus/publishHooks.js';
import { logMessage, showUltimateSlotUnlockModal } from './src/ui/modals.ts';
import { refreshOpenCreatureModalIfVisible } from './src/lib/refreshOpenCreatureModal.ts';
import { unassignMiltankFromPastureIfPresent, unassignGuardianIfPresent } from './miltankFarmSystem.ts';
import { awaitLazyModalReady } from './src/lib/lazyModalMounts.ts';
import { getById } from './src/lib/dom.ts';
import { getMaxTeamSize } from './src/lib/playerCombatRoster.ts';

type GameCtor = { prototype: Record<string, unknown> };
type ThisGame = GameRuntime;

export type StatBlock = {
    hp: number;
    attack: number;
    spattack: number;
    defense: number;
    spdefense: number;
    speed: number;
};

const EMPTY_STATS: StatBlock = {
    hp: 0, attack: 0, spattack: 0, defense: 0, spdefense: 0, speed: 0,
};

function recalcMentorStats(creature: CreatureData): void {
    if (creature && typeof (creature as { recalculateStats?: () => void }).recalculateStats === 'function') {
        (creature as { recalculateStats: () => void }).recalculateStats();
    }
}

export function applyUltimateSlotSystem(GameClass: GameCtor): void {
    GameClass.prototype.isUltimateSlotUnlocked = function (this: ThisGame): boolean {
        return isUltimateSlotUnlocked(this);
    };

    GameClass.prototype.getUltimateSlotTransferRate = function (this: ThisGame): number {
        if (!isUltimateSlotUnlocked(this)) return 0;
        const level = Number(this.upgrades?.ultimateSlotTransfer?.level) || 0;
        const raw = 0.01 + level * 0.01;
        return Math.min(0.16, Math.round(raw * 100) / 100);
    };

    GameClass.prototype.getUltimateSlotCreature = function (this: ThisGame): CreatureData | null {
        return this.ultimateSlot ?? null;
    };

    GameClass.prototype.isCreatureInUltimateSlot = function (this: ThisGame, creature: CreatureData | null | undefined): boolean {
        if (!creature?.uid || !this.ultimateSlot?.uid) return false;
        return String(creature.uid) === String(this.ultimateSlot.uid);
    };

    GameClass.prototype.isUidInUltimateSlot = function (this: ThisGame, uid: unknown): boolean {
        const searched = uid != null ? String(uid) : '';
        if (!searched || !this.ultimateSlot?.uid) return false;
        return String(this.ultimateSlot.uid) === searched;
    };

    GameClass.prototype.getUltimateSlotTeamFlatBonus = function (this: ThisGame): StatBlock {
        const rate = this.getUltimateSlotTransferRate();
        const mentor = this.ultimateSlot;
        if (!mentor || rate <= 0) return { ...EMPTY_STATS };

        Creature.setResonanceGameRef(this);
        recalcMentorStats(mentor);

        return {
            hp: Math.floor((mentor.maxHp || 0) * rate),
            attack: Math.floor((mentor.attack || 0) * rate),
            spattack: Math.floor((mentor.spattack || 0) * rate),
            defense: Math.floor((mentor.defense || 0) * rate),
            spdefense: Math.floor((mentor.spdefense || 0) * rate),
            speed: Math.floor((mentor.speed || 0) * rate),
        };
    };

    GameClass.prototype.getUltimateSlotPreview = function (this: ThisGame) {
        const bonus = this.getUltimateSlotTeamFlatBonus();
        const rate = this.getUltimateSlotTransferRate();
        const teamSize = Array.isArray(this.playerTeam) ? this.playerTeam.length : 0;
        const totalPerStat = {
            hp: bonus.hp * teamSize,
            attack: bonus.attack * teamSize,
            spattack: bonus.spattack * teamSize,
            defense: bonus.defense * teamSize,
            spdefense: bonus.spdefense * teamSize,
            speed: bonus.speed * teamSize,
        };
        return { bonus, totalPerStat, transferRate: rate, teamSize };
    };

    GameClass.prototype.moveToUltimateSlot = function (
        this: ThisGame,
        creatureIndex: number,
        from: 'team' | 'storage' | 'pension',
    ): void {
        if (!this.isUltimateSlotUnlocked()) {
            logMessage(this.t('ultimateSlot.locked', 'Slot ultime verrouille.'));
            return;
        }
        if (this.isTeamRosterEditLocked()) {
            logMessage(this.t('log.teamEditLocked'));
            return;
        }
        if (this.ultimateSlot) {
            logMessage(this.t('ultimateSlot.alreadyFilled', 'Le slot ultime est deja occupe.'));
            return;
        }

        let creature: CreatureData | undefined;
        if (from === 'team') {
            if (this.playerTeam.length <= 1) {
                logMessage(this.t('log.cannotRemoveLast'));
                return;
            }
            if (creatureIndex < 0 || creatureIndex >= this.playerTeam.length) return;
            if (creatureIndex === this.activeCreatureIndex) {
                this.activeCreatureIndex = creatureIndex === 0 ? 1 : 0;
            } else if (creatureIndex < this.activeCreatureIndex) {
                this.activeCreatureIndex--;
            }
            creature = this.playerTeam.splice(creatureIndex, 1)[0];
        } else if (from === 'storage') {
            if (creatureIndex < 0 || creatureIndex >= this.storage.length) return;
            if (this.isCreatureRocketLocked(this.storage[creatureIndex])) {
                logMessage(this.t('log.rocketLockedCreature'));
                return;
            }
            creature = this.storage.splice(creatureIndex, 1)[0];
        } else {
            if (creatureIndex < 0 || creatureIndex >= this.pension.length) return;
            creature = this.pension.splice(creatureIndex, 1)[0];
            if (this.stats) this.stats.pensionCount = this.pension.length;
        }

        if (!creature) return;
        this.ultimateSlot = creature;
        if (creature.uid) {
            unassignMiltankFromPastureIfPresent(this, String(creature.uid));
            unassignGuardianIfPresent(this, String(creature.uid));
        }

        logMessage(this.t('ultimateSlot.placed', { name: creature.name }));
        this.calculateTeamStats();
        this.invalidateStatsCache();
        this.updateTeamDisplay();
        this.updateStorageDisplay();
        this.updatePensionDisplay();
        publishTeamChanged();
        refreshOpenCreatureModalIfVisible(this);
    };

    GameClass.prototype.removeFromUltimateSlot = function (this: ThisGame): void {
        if (!this.ultimateSlot) return;
        if (this.isTeamRosterEditLocked()) {
            logMessage(this.t('log.teamEditLocked'));
            return;
        }
        const creature = this.ultimateSlot;
        this.ultimateSlot = null;
        this.storage.push(creature);
        logMessage(this.t('ultimateSlot.removed', { name: creature.name }));
        this.calculateTeamStats();
        this.invalidateStatsCache();
        this.updateTeamDisplay();
        this.updateStorageDisplay();
        publishTeamChanged();
        refreshOpenCreatureModalIfVisible(this);
    };

    GameClass.prototype.openUltimateSlotModal = async function (this: ThisGame): Promise<void> {
        if (!this.isUltimateSlotUnlocked()) {
            if (typeof toast !== 'undefined' && toast.info) {
                toast.info(
                    this.t('ultimateSlot.lockedTitle', 'Slot ultime'),
                    this.t('ultimateSlot.lockedBody', 'Obtenez le Badge Legend a Unova.'),
                );
            }
            return;
        }
        await awaitLazyModalReady('ultimateSlotModal');
        const modal = getById('ultimateSlotModal');
        if (!modal) return;
        modal.classList.add('show');
        publishTeamChanged();
    };

    GameClass.prototype.closeUltimateSlotModal = function (this: ThisGame): void {
        const modal = getById('ultimateSlotModal');
        if (modal) modal.classList.remove('show');
    };

    GameClass.prototype.maybeShowUltimateSlotIntro = function (this: ThisGame): void {
        if (!shouldShowUltimateSlotIntro(this)) return;

        const finalizeIntro = (): void => {
            if (!shouldShowUltimateSlotIntro(this)) return;
            if (!showUltimateSlotUnlockModal(this)) return;
            this.ultimateSlotIntroShown = true;
            publishTeamChanged();
            if (typeof this.saveGame === 'function') {
                this.saveGame({ immediate: true, reason: 'ultimate_slot_intro' });
            }
        };

        if (typeof requestAnimationFrame === 'function') {
            requestAnimationFrame(() => requestAnimationFrame(finalizeIntro));
            return;
        }
        setTimeout(finalizeIntro, 0);
    };

    GameClass.prototype.catchUpUltimateSlotIntroOnLoad = function (this: ThisGame): void {
        this.maybeShowUltimateSlotIntro();
    };

    GameClass.prototype.migrateUltimateSlotOnLoad = function (this: ThisGame): void {
        // Must run after game.badges is restored in loadGameLogic (getMaxTeamSize reads team_slot talents).
        const maxTeam = getMaxTeamSize(this);
        while (this.playerTeam.length > maxTeam) {
            const removed = this.playerTeam.pop();
            if (removed) this.storage.push(removed);
        }

        const mentorUid = this.ultimateSlot?.uid ? String(this.ultimateSlot.uid) : null;
        if (!mentorUid) return;

        const stripDuplicate = (list: CreatureData[]) => {
            for (let i = list.length - 1; i >= 0; i--) {
                if (list[i]?.uid && String(list[i].uid) === mentorUid) {
                    list.splice(i, 1);
                }
            }
        };
        stripDuplicate(this.playerTeam);
        stripDuplicate(this.storage);
        stripDuplicate(this.pension);
    };
}
