/**
 * Scroll-linked virtual window for lazy grids (storage, pokedex, etc.).
 */

import { getLazyListScrollRoot } from '../../formatters.ts';

export const DEFAULT_STORAGE_ROW_HEIGHT = 88;
export const DEFAULT_POKEDEX_ROW_HEIGHT = 168;
const DEFAULT_GAP = 6;
/** Avoid row-index flicker when scrollIntoList / rowHeight lands on fractional pixels (scaled viewports). */
const ROW_SCROLL_EPSILON = 0.5;

/** Snap layout px to the nearest device pixel in CSS space. */
export function roundLayoutPx(value: number): number {
    if (!Number.isFinite(value)) return 0;
    const dpr = typeof window !== 'undefined' && window.devicePixelRatio > 0
        ? window.devicePixelRatio
        : 1;
    return Math.round(value * dpr) / dpr;
}

export type GridRowMetrics = {
    cols: number;
    rowHeight: number;
};

function parseGridGap(listEl: HTMLElement): number {
    const style = getComputedStyle(listEl);
    return parseFloat(style.gap || String(DEFAULT_GAP)) || DEFAULT_GAP;
}

function estimateColumnCount(listEl: HTMLElement): number {
    const style = getComputedStyle(listEl);
    const template = style.gridTemplateColumns;
    const gap = parseGridGap(listEl);
    const listWidth = listEl.clientWidth || listEl.offsetWidth || listEl.getBoundingClientRect().width || 1;

    if (template && template !== 'none') {
        if (template.includes('auto-fill') || template.includes('auto-fit')) {
            const minMatch = template.match(/minmax\(\s*(\d+(?:\.\d+)?)px/i);
            const minCol = minMatch ? parseFloat(minMatch[1]) : 80;
            return Math.max(1, Math.floor((listWidth + gap) / (minCol + gap)));
        }
        const repeatMatch = template.match(/repeat\(\s*(\d+)/i);
        if (repeatMatch) {
            return Math.max(1, parseInt(repeatMatch[1], 10));
        }
    }

    const card = listEl.querySelector('.creature-card');
    const cardWidth = card?.getBoundingClientRect().width ?? 85;
    return Math.max(1, Math.floor((listWidth + gap) / (cardWidth + gap)));
}

/** Measure vertical distance between grid row 0 and row 1 from rendered cards. */
export function measureGridRowStride(
    listEl: HTMLElement,
    cols: number,
    defaultRowHeight: number,
): number {
    const cards = listEl.querySelectorAll('.creature-card');
    if (cards.length > cols) {
        const first = cards[0] as HTMLElement;
        const secondRow = cards[cols] as HTMLElement;
        const stride = secondRow.offsetTop - first.offsetTop;
        if (stride > 0) return stride;
    }

    const gap = parseGridGap(listEl);
    if (cards.length > 0) {
        let maxH = 0;
        for (let i = 0; i < Math.min(cols, cards.length); i++) {
            maxH = Math.max(maxH, (cards[i] as HTMLElement).getBoundingClientRect().height);
        }
        if (maxH > 0) return maxH + gap;
    }

    return defaultRowHeight;
}

/** Merge measured grid metrics with a realistic floor (no unbounded growth). */
export function stabilizeRowMetrics(
    cached: GridRowMetrics,
    measured: GridRowMetrics,
    defaultRowHeight: number,
): GridRowMetrics {
    return {
        cols: measured.cols || cached.cols,
        rowHeight: roundLayoutPx(Math.max(measured.rowHeight, defaultRowHeight)),
    };
}

/** Measure row stride as max across the first few visible grid rows. */
export function measureStableGridMetrics(
    listEl: HTMLElement,
    defaultRowHeight: number,
    cached?: GridRowMetrics,
): GridRowMetrics {
    const cols = estimateColumnCount(listEl);
    const cards = listEl.querySelectorAll('.creature-card');
    let measuredStride = 0;

    const rowPairs = Math.min(3, Math.floor(cards.length / cols) - 1);
    for (let r = 0; r < rowPairs; r++) {
        const top = cards[r * cols] as HTMLElement;
        const next = cards[(r + 1) * cols] as HTMLElement;
        const stride = next.offsetTop - top.offsetTop;
        if (stride > 0) measuredStride = Math.max(measuredStride, stride);
    }

    if (measuredStride <= 0) {
        measuredStride = measureGridRowStride(listEl, cols, defaultRowHeight);
    }

    const measured: GridRowMetrics = { cols, rowHeight: measuredStride };
    if (cached) {
        return stabilizeRowMetrics(cached, measured, defaultRowHeight);
    }
    return {
        cols,
        rowHeight: roundLayoutPx(Math.max(measuredStride, defaultRowHeight)),
    };
}

export function estimateStorageRowMetrics(
    listEl: HTMLElement | null,
    defaultRowHeight = DEFAULT_STORAGE_ROW_HEIGHT,
): GridRowMetrics {
    if (!listEl) return { cols: 4, rowHeight: defaultRowHeight };
    return measureStableGridMetrics(listEl, defaultRowHeight);
}

function resolveGridMetrics(
    listEl: HTMLElement | null,
    defaultRowHeight: number,
    fixedMetrics?: GridRowMetrics,
): GridRowMetrics {
    if (fixedMetrics) return fixedMetrics;
    if (!listEl) return { cols: 4, rowHeight: defaultRowHeight };
    return estimateStorageRowMetrics(listEl, defaultRowHeight);
}

/** Virtual spacers simulate roster height outside the rendered card window. */
export function getStorageVirtualSpacerHeights(
    listEl: HTMLElement | null,
    windowStart: number,
    visibleCount: number,
    creaturesLength: number,
    defaultRowHeight = DEFAULT_STORAGE_ROW_HEIGHT,
    fixedMetrics?: GridRowMetrics,
): { topPx: number; bottomPx: number } {
    if (creaturesLength <= 0) return { topPx: 0, bottomPx: 0 };

    const { cols, rowHeight } = resolveGridMetrics(listEl, defaultRowHeight, fixedMetrics);
    const topPx = roundLayoutPx(Math.floor(windowStart / cols) * rowHeight);
    const tailCount = Math.max(0, creaturesLength - windowStart - visibleCount);
    const tailRows = tailCount > 0 ? Math.ceil(tailCount / cols) + 1 : 0;
    const bottomPx = roundLayoutPx(tailRows * rowHeight);
    return { topPx, bottomPx };
}

function listOffsetInScrollRoot(listEl: HTMLElement, root: HTMLElement): number {
    let top = 0;
    let el: HTMLElement | null = listEl;
    while (el && el !== root) {
        top += el.offsetTop;
        el = el.offsetParent as HTMLElement | null;
    }
    return top;
}

/** Clamp virtual window so the grid never renders zero cards for a non-empty roster. */
export function clampStorageWindow(
    creaturesLength: number,
    windowStart: number,
    visibleCount: number,
    defaultBatch: number,
    maxDom: number,
): { windowStart: number; visibleCount: number } {
    if (creaturesLength <= 0) {
        return { windowStart: 0, visibleCount: 0 };
    }
    let ws = windowStart;
    let vc = visibleCount;
    if (ws >= creaturesLength) {
        ws = Math.max(0, creaturesLength - defaultBatch);
    }
    vc = Math.min(vc, creaturesLength - ws, maxDom);
    if (vc <= 0) {
        vc = Math.min(defaultBatch, creaturesLength);
    }
    return { windowStart: ws, visibleCount: vc };
}

/**
 * Derive virtual window from scroll root position.
 * windowStart follows user scroll; visibleCount fills up to maxDom.
 */
export function syncStorageWindowFromScroll(
    listEl: HTMLElement | null,
    creaturesLength: number,
    maxDom: number,
    batchBuffer = 12,
    scrollRootFallback = '.team-area',
    defaultRowHeight = DEFAULT_STORAGE_ROW_HEIGHT,
    fixedMetrics?: GridRowMetrics,
): { windowStart: number; visibleCount: number } | null {
    if (!listEl || creaturesLength <= 0) {
        return { windowStart: 0, visibleCount: 0 };
    }

    const root = getLazyListScrollRoot(listEl, scrollRootFallback);
    if (!(root instanceof HTMLElement)) return null;

    const listTop = listOffsetInScrollRoot(listEl, root);
    const scrollIntoList = root.scrollTop - listTop;

    if (scrollIntoList <= 0) {
        return clampStorageWindow(creaturesLength, 0, maxDom, batchBuffer, maxDom);
    }

    const { cols, rowHeight } = resolveGridMetrics(listEl, defaultRowHeight, fixedMetrics);
    const rowsScrolled = Math.max(0, Math.floor((scrollIntoList + ROW_SCROLL_EPSILON) / rowHeight));
    const bufferRows = Math.max(1, Math.ceil(batchBuffer / cols));
    const firstIndex = Math.max(0, (rowsScrolled - bufferRows) * cols);
    const windowStart = Math.min(firstIndex, Math.max(0, creaturesLength - 1));

    return clampStorageWindow(
        creaturesLength,
        windowStart,
        maxDom,
        batchBuffer,
        maxDom,
    );
}

/** Whether the lazy-load sentinel is inside the IO root viewport. */
export function isStorageSentinelIntersecting(
    listEl: HTMLElement | null,
    sentinelEl: HTMLElement | null,
    rootMarginPx = 200,
    scrollRootFallback = '.team-area',
): boolean {
    if (!listEl || !sentinelEl) return false;
    const root = getLazyListScrollRoot(listEl, scrollRootFallback);
    const rootRect = root instanceof HTMLElement
        ? root.getBoundingClientRect()
        : { top: 0, bottom: window.innerHeight, left: 0, right: window.innerWidth };

    const margin = rootMarginPx;
    const expandedRoot = {
        top: rootRect.top - margin,
        bottom: rootRect.bottom + margin,
        left: rootRect.left - margin,
        right: rootRect.right + margin,
    };
    const rect = sentinelEl.getBoundingClientRect();
    return (
        rect.bottom >= expandedRoot.top &&
        rect.top <= expandedRoot.bottom &&
        rect.right >= expandedRoot.left &&
        rect.left <= expandedRoot.right
    );
}
