/**
 * Bridge for RocketCasinoModal — legacy rocketDisplay opens/closes via these hooks.
 */

type OpenFn = () => void;
type CloseFn = () => void;

let _open: OpenFn | null = null;
let _close: CloseFn | null = null;

export function setRocketCasinoOpen(fn: OpenFn): void {
  _open = fn;
}

export function setRocketCasinoClose(fn: CloseFn): void {
  _close = fn;
}

export function openRocketCasinoModal(): void {
  _open?.();
}

export function closeRocketCasinoModal(): void {
  _close?.();
}
