import type { CreatureData } from '../types/creature.js';
import { scaleTalentMultiplierAboveOne } from './eluTalentBoost.ts';

/** Count passive Antivax talents in a team, daycare, or storage group. */
export function countAntivaxInGroup(group: CreatureData[]): number {
    if (!Array.isArray(group)) return 0;
    let n = 0;
    for (const c of group) {
        if (c && c.passiveTalent === 'antivax') n++;
    }
    return n;
}

/**
 * Group-wide Pokérus spread multiplier from Antivax count.
 * 0 → ×1 ; 1 → ×2 ; 2 → ×2.5 ; 3 → ×2.75 ; asymptote ×3.
 * With Élu active: scales the bonus above ×1 by 1.30.
 */
export function getAntivaxGroupPokerusMultiplier(antivaxCount: number, eluActive = false): number {
    if (!Number.isFinite(antivaxCount) || antivaxCount <= 0) return 1;
    const base = 3 - 2 * Math.pow(0.5, antivaxCount);
    if (!eluActive) return base;
    return scaleTalentMultiplierAboveOne(base, 1.30);
}

/** Multiplier for one creature in a group (uniform for all members). */
export function getAntivaxPokerusRollMultiplierForCreature(
    creature: CreatureData | null | undefined,
    group: CreatureData[],
    eluActive = false,
): number {
    if (!creature || !Array.isArray(group) || group.indexOf(creature) < 0) return 1;
    return getAntivaxGroupPokerusMultiplier(countAntivaxInGroup(group), eluActive);
}
