export function migrateKalosFlareClimaxV1(data: {
    kalosFlareClimaxV1?: boolean;
    completedStoryQuests?: string[];
    quests?: Array<{ id?: string; completed?: boolean; claimed?: boolean }>;
}): void {
    if (data.kalosFlareClimaxV1 === true) return;

    const completed = data.completedStoryQuests;
    const hadPostLeagueXerneas = Array.isArray(completed)
        && completed.includes('story_kalos_xerneas_yveltal')
        && !completed.includes('story_kalos_flare_hq');

    if (hadPostLeagueXerneas && Array.isArray(completed)) {
        if (!completed.includes('story_kalos_flare_hq')) {
            completed.push('story_kalos_flare_hq');
        }
        const xIdx = completed.indexOf('story_kalos_xerneas_yveltal');
        if (xIdx !== -1) completed.splice(xIdx, 1);
        if (!completed.includes('story_kalos_xerneas_yveltal')) {
            const eliteIdx = completed.indexOf('story_kalos_elite_four');
            if (eliteIdx >= 0) {
                completed.splice(eliteIdx, 0, 'story_kalos_xerneas_yveltal');
            } else {
                completed.push('story_kalos_xerneas_yveltal');
            }
        }
    }

    data.kalosFlareClimaxV1 = true;
}

export function migrateKalosRouteProgressionV1(data: {
    kalosRouteProgressionV1?: boolean;
    badges?: Record<string, boolean>;
    completedStoryQuests?: string[];
    zoneProgress?: Record<string, { bossesDefeated?: number; [key: string]: unknown }>;
}): void {
    if (data.kalosRouteProgressionV1 === true) return;

    const badges = data.badges;
    const zoneProgress = data.zoneProgress;
    const completed = data.completedStoryQuests;
    const hasPsychic = !!(badges?.psychic);
    const hasIceberg = !!(badges?.iceberg);
    const frostQuestDone = Array.isArray(completed)
        && (completed.includes('story_kalos_frost_cavern') || completed.includes('story_kalos_flare_frost'));

    if (zoneProgress && (hasPsychic || hasIceberg || frostQuestDone)) {
        const frostKey = '543';
        const existing = zoneProgress[frostKey] || {};
        const bossesDone = Number(existing.bossesDefeated) || 0;
        if (bossesDone < 1) {
            zoneProgress[frostKey] = { ...existing, bossesDefeated: 1 };
        }
    }

    data.kalosRouteProgressionV1 = true;
}

export function migrateKalosPostLeagueQuestGatingV1(data: {
    kalosPostLeagueQuestGatingV1?: boolean;
    completedStoryQuests?: string[];
}): void {
    if (data.kalosPostLeagueQuestGatingV1 === true) return;

    const completed = data.completedStoryQuests;
    if (Array.isArray(completed) && !completed.includes('story_kalos_elite_four')) {
        for (const questId of STORY_QUEST_KALOS_POST_LEAGUE_IDS) {
            const idx = completed.indexOf(questId);
            if (idx !== -1) completed.splice(idx, 1);
        }
    }

    data.kalosPostLeagueQuestGatingV1 = true;
}

export function migrateKalosBerryFeticheTutorialV1(data: {
    kalosBerryFeticheTutorialV1?: boolean;
    completedStoryQuests?: string[];
    unlockedFeatures?: Record<string, boolean>;
    miltankFarmState?: { berryTree?: { unlockedBerryKeys?: string[] } } | null;
    feticheState?: { speciesKey?: string | null; level?: number; xp?: number } | null;
    items?: Record<string, number>;
}): void {
    if (data.kalosBerryFeticheTutorialV1 === true) return;

    const ufs = data.unlockedFeatures ?? {};
    data.unlockedFeatures = ufs;
    const completed = data.completedStoryQuests;
    if (!Array.isArray(completed)) {
        data.kalosBerryFeticheTutorialV1 = true;
        return;
    }

    const markComplete = (questId: string): void => {
        if (!completed.includes(questId)) completed.push(questId);
    };

    const berryKeys = data.miltankFarmState?.berryTree?.unlockedBerryKeys ?? [];
    const hasBerryRecipe = berryKeys.length > 0;
    const items = data.items ?? {};
    const hasBerryInBag = BERRY_DEX_KEYS.some((key) => (Number(items[key]) || 0) > 0);
    const fetiche = data.feticheState;
    const hasFetiche = !!fetiche?.speciesKey;
    const likelyFed = hasFetiche
        && ((Number(fetiche?.level) || 0) > 1 || (Number(fetiche?.xp) || 0) > 0);

    if (hasBerryRecipe) {
        ufs.berryTree = true;
        markComplete('story_kalos_berry_recipe');
    }
    if (hasBerryRecipe && hasBerryInBag) {
        markComplete('story_kalos_berry_harvest');
    }
    if (hasFetiche) {
        ufs.fetiche = true;
        markComplete('story_kalos_fetiche_choose');
    }
    if (likelyFed) {
        markComplete('story_kalos_fetiche_feed');
    }

    data.kalosBerryFeticheTutorialV1 = true;
}

