<script lang="ts">
  import { formatNumber } from '../../formatters.js';

  let { label, value, icon, id = '', format = 'number' }:
    { label: string; value: number; icon: string; id?: string; format?: 'number' | 'short' | 'percent' }
    = $props();

  let displayValue = $derived(((): string => {
    if (format === 'percent') return `${value.toFixed(1)}%`;
    if (format === 'short') {
      if (value >= 1e6) return `${(value / 1e6).toFixed(1)}M`;
      if (value >= 1e3) return `${(value / 1e3).toFixed(1)}k`;
      return value.toFixed(0);
    }
    if (format === 'number') return formatNumber(value);
    return value.toLocaleString();
  })());
</script>

<div class="resource-chip" {id}>
  <img src={icon} class="resource-icon resource-icon-img" alt={label}>
  <div>
    <div class="resource-val">{displayValue}</div>
    <div class="resource-name">{label}</div>
  </div>
</div>
