/**
 * Audit storage / egg scope vs released regions (e.g. Gen 7 at Sinnoh-only progress).
 */
import type { GameRuntime } from '../types/game.js';
import type { CreatureData } from '../types/creature.js';
import { RELEASED_REGION_IDS } from '../../constants/balance/regionRelease.ts';
import {
    filterEggSpeciesNamesForProgress,
    getEggNativeRegionIdForSpecies,
    isEggRegionUnlockedForGame,
} from '../../constants/balance/eggRegionMap.ts';
import { getSpeciesGeneration } from './nationalDexGeneration.ts';

export type StorageGenScopeEntry = {
    name: string;
    generation: number | null;
    nativeRegionId: string | null;
};

/** Highest generation hatchable from eggs given current regional egg unlocks. */
export function getMaxHatchableGenerationForGame(game: GameRuntime | null | undefined): number {
    if (!game) return 1;
    const released = RELEASED_REGION_IDS as readonly string[];
    let maxGen = 1;
    for (let g = 1; g <= 9; g++) {
        const probeName = generationProbeSpecies(g);
        if (!probeName) continue;
        const native = getEggNativeRegionIdForSpecies(probeName);
        const unlockKey = native || 'kanto';
        if (!released.includes(unlockKey)) continue;
        if (isEggRegionUnlockedForGame(game, unlockKey)) {
            maxGen = Math.max(maxGen, g);
        }
    }
    return maxGen;
}

function generationProbeSpecies(gen: number): string | null {
    const table: Record<number, string> = {
        1: 'Bulbasaur',
        2: 'Chikorita',
        3: 'Treecko',
        4: 'Turtwig',
        5: 'Victini',
        6: 'Chespin',
        7: 'Rowlet',
        8: 'Grookey',
        9: 'Sprigatito',
    };
    return table[gen] ?? null;
}

/** Species in team + storage whose generation exceeds max hatchable for this save. */
export function listOwnedSpeciesBeyondEggScope(
    game: GameRuntime | null | undefined,
): StorageGenScopeEntry[] {
    if (!game) return [];
    const maxGen = getMaxHatchableGenerationForGame(game);
    const seen = new Set<string>();
    const out: StorageGenScopeEntry[] = [];

    const buckets: CreatureData[][] = [];
    if (Array.isArray(game.playerTeam)) buckets.push(game.playerTeam);
    if (Array.isArray(game.storage)) buckets.push(game.storage);

    for (const list of buckets) {
        for (const creature of list) {
            if (!creature?.name) continue;
            const name = String(creature.name);
            if (seen.has(name)) continue;
            seen.add(name);
            const generation = getSpeciesGeneration(name);
            if (generation == null || generation <= maxGen) continue;
            out.push({
                name,
                generation,
                nativeRegionId: getEggNativeRegionIdForSpecies(name),
            });
        }
    }

    out.sort((a, b) => (a.generation ?? 0) - (b.generation ?? 0) || a.name.localeCompare(b.name));
    return out;
}

/** True when species could hatch from an egg on this save right now. */
export function isSpeciesHatchableForGame(
    game: GameRuntime | null | undefined,
    speciesName: string,
): boolean {
    if (!speciesName) return false;
    if (!game) return false;
    return filterEggSpeciesNamesForProgress(game, [speciesName]).includes(speciesName);
}
