/**
 * @file src/lib/displayDomains.ts
 * Selective invalidation for Game.updateDisplay() — avoids full UI shotgun refresh.
 */

export const DISPLAY_DOMAINS = [
  'zone',
  'team',
  'storage',
  'pension',
  'eggs',
  'incubators',
  'shop',
  'combat',
  'tower',
  'pokedex',
  'arena',
  'quests',
  'achievements',
  'items',
  'statBoosts',
  'boosts',
  'expeditions',
  'rocket',
  'visibility',
  'afk',
] as const;

export type DisplayDomain = (typeof DISPLAY_DOMAINS)[number];

/** Boot / load save / offline catch-up — full refresh. */
export const DISPLAY_ALL: DisplayDomain[] | undefined = undefined;

export function displayDomainSet(
  domains?: readonly DisplayDomain[],
): Set<DisplayDomain> | null {
  if (!domains || domains.length === 0) return null;
  return new Set(domains);
}
