/**
 * @file zRingSystem.ts
 * Z-Ring mixin: select active Z-Crystal, unlock from trials.
 */

import type { GameRuntime } from './src/types/game.js';
import { logMessage } from './src/ui/modals.ts';
import { toast } from './toastManager.ts';
import { publishZRingChanged } from './src/bus/publishHooks.js';
import {
    canConfigureZRing,
    getActiveZCrystalId,
    getZRingState,
    isZCrystalUnlocked,
    isZRingUnlocked,
    setActiveZCrystal,
    syncZCrystalsFromAlolaBadges,
    unlockZCrystal,
} from './src/lib/zRingLogic.ts';
import { tryActivateZPower, getZPowerActivationAttackCount } from './src/lib/zRingCombat.ts';
import { Z_CRYSTAL_EFFECTS } from './constants/balance/zRing.ts';

type GameCtor = { prototype: Record<string, unknown> };
type ThisGame = GameRuntime;

export function unlockZRingCrystalLogic(game: GameRuntime, crystalId: string): void {
    if (!unlockZCrystal(game, crystalId)) return;
    const def = Z_CRYSTAL_EFFECTS[crystalId as keyof typeof Z_CRYSTAL_EFFECTS];
    const name = def?.moveNameFr ?? crystalId;
    logMessage(
        typeof game.t === 'function'
            ? game.t('zRing.crystalUnlocked', { name })
            : `Cristal Z ${name} ajouté à l'anneau.`,
    );
    if (getActiveZCrystalId(game) && typeof game.checkSpecialQuests === 'function') {
        game.checkSpecialQuests('z_ring_configured');
    }
    publishZRingChanged();
}

export function applyZRingSystem(GameClass: GameCtor): void {
    GameClass.prototype.isZRingUnlocked = function (this: ThisGame): boolean {
        return isZRingUnlocked(this);
    };

    GameClass.prototype.getActiveZCrystalId = function (this: ThisGame): string | null {
        return getActiveZCrystalId(this);
    };

    GameClass.prototype.setActiveZCrystal = function (this: ThisGame, crystalId: string): boolean {
        if (!canConfigureZRing(this)) {
            const title = this.t('toast.zRingSwitchBlockedTitle');
            const body = this.t('toast.zRingSwitchBlockedBody');
            const titleSafe = title && title !== 'toast.zRingSwitchBlockedTitle'
                ? title
                : 'Anneau Z';
            const bodySafe = body && body !== 'toast.zRingSwitchBlockedBody'
                ? body
                : 'Impossible de changer de cristal Z en combat PVP (arène, tour, métro ou dresseur).';
            if (typeof toast !== 'undefined' && typeof toast.warning === 'function') {
                toast.warning(titleSafe, bodySafe);
            }
            logMessage(bodySafe);
            return false;
        }
        const ok = setActiveZCrystal(this, crystalId);
        if (ok) {
            if (typeof this.checkSpecialQuests === 'function') {
                this.checkSpecialQuests('z_ring_configured');
            }
            if (typeof this.saveGame === 'function') this.saveGame();
            publishZRingChanged();
        }
        return ok;
    };

    GameClass.prototype.activateZPower = function (this: ThisGame): boolean {
        const ok = tryActivateZPower(this);
        if (ok) {
            const double = getZPowerActivationAttackCount(this) >= 2;
            const title = typeof this.t === 'function' ? this.t('toast.zPowerActivatedTitle') : 'Z-Power';
            const bodyKey = double ? 'toast.zPowerActivatedBodyDouble' : 'toast.zPowerActivatedBody';
            const bodyFallback = double
                ? 'Z-Power activé ! Deux prochaines attaques amplifiées.'
                : 'Z-Power activé ! Prochaine attaque amplifiée.';
            const body = typeof this.t === 'function' ? this.t(bodyKey) : bodyFallback;
            const titleSafe = title && title !== 'toast.zPowerActivatedTitle' ? title : 'Z-Power';
            const bodySafe = body && body !== bodyKey ? body : bodyFallback;
            if (typeof toast !== 'undefined' && typeof toast.success === 'function') {
                toast.success(titleSafe, bodySafe);
            }
            logMessage(bodySafe);
        }
        return ok;
    };

    GameClass.prototype.syncZRingFromBadges = function (this: ThisGame): void {
        syncZCrystalsFromAlolaBadges(this);
        publishZRingChanged();
    };
}

export function onAlolaTrialBadgeWon(game: GameRuntime, badgeKey: string): void {
    if (!badgeKey || badgeKey === 'maitre_alola') return;
    unlockZRingCrystalLogic(game, badgeKey);
}

export function ensureZRingOnLoad(game: GameRuntime): void {
    getZRingState(game);
    syncZCrystalsFromAlolaBadges(game);
}

export { isZCrystalUnlocked, getZRingState };
