/**
 * Offline / visibility passive stat catch-up (batched, no per-second loop).
 */

import type { CreatureData, GameRuntime, PlayerMainStats } from '../types/game.js';
import {
    applyFetichePassiveGainBatch,
    getFeticheTransmissionSeconds,
    normalizeFeticheState,
} from './feticheLogic.ts';

/** Wall-clock passive seconds applied per flush during interleaved offline combat. */
export const PASSIVE_CATCHUP_SEGMENT_MS = 60_000;

const STAT_KEYS: (keyof PlayerMainStats)[] = [
    'hp', 'attack', 'spattack', 'defense', 'spdefense', 'speed',
];

export function creatureAtMaxLevelForPassive(c: CreatureData | null | undefined): boolean {
    return !!(c && typeof c.isAtMaxLevel === 'function' && c.isAtMaxLevel());
}

/** True when combat XP can no longer change team or pension contribution rates. */
export function isPassiveGainRateFrozenForOffline(game: GameRuntime): boolean {
    const team = game.playerTeam ?? [];
    const pension = game.pension ?? [];
    const allTeamMax = !team.length || team.every(creatureAtMaxLevelForPassive);
    const allPensionMax = !pension.length || pension.every(creatureAtMaxLevelForPassive);
    return allTeamMax && allPensionMax;
}

function applyGainTicks(stats: PlayerMainStats, gain: PlayerMainStats, ticks: number): void {
    for (const key of STAT_KEYS) {
        const perSec = Number(gain[key]) || 0;
        if (perSec === 0) continue;
        stats[key] = (Number(stats[key]) || 0) + perSec * ticks;
    }
}

function batchStaminaAndPp(game: GameRuntime, deltaTimeMs: number): void {
    const regenTime = typeof game.getStaminaRegenTime === 'function'
        ? Number(game.getStaminaRegenTime())
        : 5000;
    if (!Number.isFinite(regenTime) || regenTime <= 0) return;

    let regenTicks = Math.floor(deltaTimeMs / regenTime);
    if (regenTicks <= 0) return;

    if (typeof game.fastForwardPpRegenTicks === 'function') {
        while (regenTicks > 0) {
            const chunk = Math.min(regenTicks, 200);
            game.fastForwardPpRegenTicks(chunk);
            regenTicks -= chunk;
        }
    }

    game.lastStaminaRegen = Date.now();
}

/**
 * Applies passive main-stat growth for `deltaTimeMs` at the current team/pension rates.
 * Equivalent to the legacy per-second loop when rates are constant over the interval.
 */
export function applyPassiveCatchupBatch(game: GameRuntime, deltaTimeMs: number): number {
    const ms = Math.max(0, Number(deltaTimeMs) || 0);
    const ticks = Math.floor(ms / 1000);
    if (ticks <= 0) return 0;

    const getGain = game.getPassiveStatGainPerSecond;
    if (typeof getGain !== 'function') return 0;

    const gain = getGain.call(game);
    if (!gain) return 0;

    const batchingFlag = '_batchingPassiveCatchup';
    (game as GameRuntime & { _batchingPassiveCatchup?: boolean })[batchingFlag] = true;
    try {
        applyGainTicks(game.playerMainStats, gain, ticks);
        if (game.unlockedFeatures?.fetiche && game.feticheState?.speciesKey) {
            const now = Date.now();
            const batchStartMs = now - ticks * 1000;
            const state = normalizeFeticheState(game.feticheState, now);
            const startSec = getFeticheTransmissionSeconds(state, batchStartMs);
            applyFetichePassiveGainBatch(state.stats, startSec, ticks, game.playerMainStats);
        }
        batchStaminaAndPp(game, ms);
    } finally {
        (game as GameRuntime & { _batchingPassiveCatchup?: boolean })[batchingFlag] = false;
    }

    if (!game.isOfflineSimulating && typeof game.updatePlayerStatsDisplay === 'function') {
        game.updatePlayerStatsDisplay();
    }

    return ticks * 1000;
}

/** Applies up to one segment of passive time; returns ms applied. */
export function flushPassiveCatchupSegment(
    game: GameRuntime,
    missedTimeMs: number,
    appliedMs: number,
): { appliedMs: number; segmentAppliedMs: number } {
    const totalPassiveMs = Math.floor(Math.max(0, missedTimeMs) / 1000) * 1000;
    const remaining = totalPassiveMs - appliedMs;
    if (remaining <= 0) {
        return { appliedMs, segmentAppliedMs: 0 };
    }
    const segmentMs = Math.min(remaining, PASSIVE_CATCHUP_SEGMENT_MS);
    applyPassiveCatchupBatch(game, segmentMs);
    return { appliedMs: appliedMs + segmentMs, segmentAppliedMs: segmentMs };
}
