type ItemDef = { name?: string; img?: string | null; icon?: string; [key: string]: unknown };

function finiteGameNumber(game: GameRuntime, method: unknown, ...args: unknown[]): number {
    const n = callGame<number>(game, method, ...args);
    return typeof n === 'number' && Number.isFinite(n) ? n : 0;
}

function getMaxExpeditionSlotsForGame(game: GameRuntime): number {
    if (typeof game.getMaxExpeditionSlots === 'function') return game.getMaxExpeditionSlots();
    return Math.max(1, Math.floor(Number(game.maxExpeditionSlots) || 3));
}

function collectionBonuses(game: GameRuntime): Record<string, unknown> {
    const b = callGame<Record<string, unknown>>(game, game['getCollectionBonuses']);
    return b && typeof b === 'object' ? b : {};
}

const EXPEDITION_DEFS = EXPEDITION_DEFINITIONS as Record<string, ExpeditionDefinition>;
const EXPEDITION_SUCCESS_RATE_MAX = 2.0;

function getExpeditionDef(id: string): ExpeditionDefinition | undefined {
    return EXPEDITION_DEFS[id];
}

function invokeGame(game: GameRuntime, method: unknown, ...args: unknown[]): void {
    callGame<void>(game, method, ...args);
}

function expeditionTranslate(game: GameRuntime, key: string, params?: Record<string, string | number>): string {
    if (typeof game.t === 'function') {
        const translated = game.t(key, params);
        if (translated && translated !== key) return translated;
    }
    return key;
}

function getMissionLevelForDef(game: GameRuntime, defId: string): number {
    if (!game.expeditionMissionMastery) game.expeditionMissionMastery = {};
    return getMissionMasteryEntry(game.expeditionMissionMastery, defId).activeLevel;
}

function withMissionDifficulty(expeditionDef: ExpeditionDefinition, missionLevel: number): ExpeditionDefinition {
    return {
        ...expeditionDef,
        difficulty: getEffectiveExpeditionDifficulty(expeditionDef.difficulty || 100, missionLevel),
    };
}

