export function expeditionFormatText(game: GameRuntime, text: string, vars: Record<string, unknown> = {}): string {
    const localized = localizeTemplateSubstitutionVars(game, vars);
    return String(text || '').replace(/\{(\w+)\}/g, (_match: string, k: string) => {
        const v = localized[k];
        return v != null ? coerceStr(v) : '';
    });
}

export function expeditionIsEn(game: GameRuntime): boolean {
    const lang = callGame<string>(game, game['normalizeLanguage'], game.language) ?? 'fr';
    return lang === 'en';
}

export function expeditionText(game: GameRuntime, key: string, fallbackFr: string, fallbackEn: string, vars: Record<string, unknown> = {}): string {
    if (key) {
        const translated = callGame<string>(game, game['t'], key, vars);
        if (translated && translated !== key) return translated;
    }
    const fallback = expeditionIsEn(game) ? fallbackEn : fallbackFr;
    return expeditionFormatText(game, fallback, vars);
}

export function getExpeditionDisplayName(game: GameRuntime, expeditionDef: ExpeditionDefinition | null, expeditionId: string): string {
    const fallback = expeditionDef && expeditionDef.name ? expeditionDef.name : String(expeditionId || '');
    const key = String(expeditionId || (expeditionDef && expeditionDef.id) || '');
    const map = expeditionIsEn(game) ? EXPEDITION_I18N_EN : EXPEDITION_I18N_FR;
    const mapped = map[key];
    return (mapped && mapped.name) ? mapped.name : fallback;
}

export function getExpeditionDisplayDescription(game: GameRuntime, expeditionDef: ExpeditionDefinition | null, expeditionId: string): string {
    const fallback = expeditionDef && expeditionDef.description ? expeditionDef.description : '';
    const key = String(expeditionId || (expeditionDef && expeditionDef.id) || '');
    const map = expeditionIsEn(game) ? EXPEDITION_I18N_EN : EXPEDITION_I18N_FR;
    const mapped = map[key];
    return (mapped && mapped.description) ? mapped.description : fallback;
}

export function getExpeditionItemName(game: GameRuntime, itemKey: string): string {
    const itemDef = (ALL_ITEMS as Record<string, ItemDef>)[itemKey] ?? null;
    const fallbackName = coalesceStr(itemDef?.name, itemKey);
    return callGame<string>(game, game['getLocalizedItemName'], itemKey, fallbackName, itemDef) ?? fallbackName;
}

export function escapeExpeditionHtml(value: unknown): string {
    return coerceStr(value == null ? '' : value)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

export function buildExpeditionRewardsToastHtml(game: GameRuntime, rewards: ExpeditionRewards, leader: CreatureData | null): string {
    const eggSpriteByRarity: Record<string, string> = {
        common: 'img/common-egg.png',
        rare: 'img/rare-egg.png',
        epic: 'img/epic-egg.png',
        legendary: 'img/legendary-egg.png'
    };
    const parts = [];
    const notes = [];

    if (rewards.performance === 'CRITICAL') {
        notes.push(`<div class="toast-reward-note">${escapeExpeditionHtml(expeditionText(game, 'expedition.criticalBody', 'Performance exceptionnelle ! (Butin x2)', 'Outstanding performance! (Loot x2)'))}</div>`);
    } else if (rewards.performance === 'FAILURE') {
        notes.push(`<div class="toast-reward-note">${escapeExpeditionHtml(expeditionText(game, 'expedition.failureBody', "L'expedition a mal tourne...", 'The expedition went badly...'))}</div>`);
    }

    if (rewards.pokedollars > 0) {
        parts.push(`<span class="quest-reward-item"><img src="img/pokedollars.png" class="quest-reward-inline-img" alt="Pokedollars"> ${formatNumber(rewards.pokedollars)}</span>`);
    }
    if (rewards.tokens > 0) {
        parts.push(`<span class="quest-reward-item"><img src="https://raw.githubusercontent.com/msikma/pokesprite/master/items/key-item/magma-emblem.png" class="quest-token-inline" alt="Quest Tokens"> ${rewards.tokens}</span>`);
    }
    if (rewards.shards > 0) {
        const leaderNameRaw = leader ? coerceStr(leader.name) : '';
        const leaderDisplay = leaderNameRaw
            ? (callGame<string>(game, game['getLocalizedPokemonName'], leaderNameRaw) ?? escapeExpeditionHtml(leaderNameRaw))
            : escapeExpeditionHtml('Pokemon');
        parts.push(`<span class="quest-reward-item"><img src="img/shard.png" class="quest-reward-inline-img" alt="Shards"> ${rewards.shards}x ${leaderDisplay} Shards</span>`);
    }
    if (rewards.eggs) {
        Object.entries(rewards.eggs).forEach(([rarity, amount]) => {
            const qty = Math.max(0, Math.floor(Number(amount) || 0));
            if (qty <= 0) return;
            const rarityKey = String(rarity || '').toLowerCase();
            const eggSprite = eggSpriteByRarity[rarityKey] || eggSpriteByRarity.common;
            const rarityLabel = callGame<string>(game, game['getRarityLabel'], rarity) ?? rarity;
            parts.push(`<span class="quest-reward-item"><img src="${eggSprite}" class="quest-reward-inline-img quest-reward-egg" alt="${escapeExpeditionHtml(rarityLabel)} egg"> ${qty}x ${escapeExpeditionHtml(rarityLabel)}</span>`);
        });
    }
    if (rewards.items) {
        Object.entries(rewards.items).forEach(([itemKey, amount]) => {
            const qty = Math.max(0, Math.floor(Number(amount) || 0));
            if (qty <= 0) return;
            const itemDef: ItemDef = (ALL_ITEMS as Record<string, ItemDef>)[itemKey]
                ?? { name: itemKey, img: null, icon: 'OBJ' };
            const itemName = getExpeditionItemName(game, itemKey);
            const iconHTML = getItemIconHTML(itemDef as import('./src/ui/uiTypes.ts').UiItemLike);
            parts.push(`<span class="quest-reward-item">${iconHTML} ${qty}x ${escapeExpeditionHtml(itemName)}</span>`);
        });
    }

    if (parts.length === 0) {
        notes.push(`<div class="toast-reward-note">${escapeExpeditionHtml(expeditionText(game, 'expedition.noReward', 'Aucune recompense notable', 'No notable reward'))}</div>`);
    }

    return `${notes.join('')}${parts.length ? `<div class="toast-reward-summary">${parts.join('')}</div>` : ''}`;
}

export function buildExpeditionLootStripHTML(
    game: GameRuntime,
    expeditionDef: ExpeditionDefinition,
    missionMasteryLevel = 1,
): string {
    const pool = (expeditionDef && expeditionDef.rewardPool) || {};
    const scaled = getScaledExpeditionLootPreview(pool, missionMasteryLevel);
    const parts = [];

    // FIXED: Pokedollars (toujours octroyés dans une fourchette min-max)
    if (scaled.pokedollars) {
        const min = formatNumber(scaled.pokedollars.min);
        const max = formatNumber(scaled.pokedollars.max);
        const tip = expeditionText(
            game,
            'expedition.lootPokedollarsTip',
            'Pokedollars : {min} - {max} (garanti)',
            'Pokedollars: {min} - {max} (guaranteed)',
            { min, max }
        );
        parts.push(
            `<span class="exp-loot exp-loot-fixed" title="${escapeExpeditionHtml(tip)}" data-tooltip-title="${escapeExpeditionHtml(expeditionText(game, 'expedition.lootPokedollarsTitle', 'Pokedollars', 'Pokedollars'))}" data-tooltip-desc="${escapeExpeditionHtml(tip)}">`
            + `<img src="img/pokedollars.png" class="exp-loot-img" alt="Pokedollars">`
            + `</span>`
        );
    }

    // PROBABLE: Tokens
    if (scaled.tokens) {
        const chance = Math.round(scaled.tokens.chance * 100);
        const min = scaled.tokens.min;
        const max = scaled.tokens.max;
        const titleStr = expeditionText(game, 'expedition.lootTokensTitle', 'Quest Tokens', 'Quest Tokens');
        const tip = expeditionText(
            game,
            'expedition.lootTokensTip',
            'Quest Tokens : {min}-{max} ({chance}% de chance)',
            'Quest Tokens: {min}-{max} ({chance}% chance)',
            { min, max, chance }
        );
        parts.push(
            `<span class="exp-loot exp-loot-probable" title="${escapeExpeditionHtml(tip)}" data-tooltip-title="${escapeExpeditionHtml(titleStr)}" data-tooltip-desc="${escapeExpeditionHtml(tip)}">`
            + `<img src="img/quest-token.png" class="exp-loot-img" alt="Tokens">`
            + `<span class="exp-loot-chance">${chance}%</span>`
            + `</span>`
        );
    }

    // PROBABLE: Shards
    if (scaled.shards) {
        const chance = Math.round(scaled.shards.chance * 100);
        const amount = scaled.shards.amount;
        const titleStr = expeditionText(game, 'expedition.lootShardsTitle', 'Shards', 'Shards');
        const tip = expeditionText(
            game,
            'expedition.lootShardsTip',
            'Shards x{amount} ({chance}% de chance)',
            'Shards x{amount} ({chance}% chance)',
            { amount, chance }
        );
        parts.push(
            `<span class="exp-loot exp-loot-probable" title="${escapeExpeditionHtml(tip)}" data-tooltip-title="${escapeExpeditionHtml(titleStr)}" data-tooltip-desc="${escapeExpeditionHtml(tip)}">`
            + `<img src="img/shard.png" class="exp-loot-img" alt="Shards">`
            + `<span class="exp-loot-chance">${chance}%</span>`
            + `</span>`
        );
    }

    // PROBABLE: Eggs (par rareté)
    if (scaled.eggs) {
        const eggSpriteByRarity: Record<string, string> = {
            common: 'img/common-egg.png',
            rare: 'img/rare-egg.png',
            epic: 'img/epic-egg.png',
            legendary: 'img/legendary-egg.png'
        };
        Object.entries(scaled.eggs).forEach(([rarity, eggInfo]) => {
            const chance = Math.round(eggInfo.chance * 100);
            const amount = eggInfo.amount;
            const rarityKey = String(rarity || '').toLowerCase();
            const eggSprite = eggSpriteByRarity[rarityKey] || eggSpriteByRarity.common;
            const rarityLabel = callGame<string>(game, game['getRarityLabel'], rarity) ?? rarity;
            const titleStr = expeditionText(
                game,
                'expedition.lootEggTitle',
                'Œuf {rarity}',
                '{rarity} Egg',
                { rarity: rarityLabel }
            );
            const tip = expeditionText(
                game,
                'expedition.lootEggTip',
                'Œuf {rarity} x{amount} ({chance}% de chance)',
                '{rarity} Egg x{amount} ({chance}% chance)',
                { rarity: rarityLabel, amount, chance }
            );
            parts.push(
                `<span class="exp-loot exp-loot-probable exp-loot-egg" title="${escapeExpeditionHtml(tip)}" data-tooltip-title="${escapeExpeditionHtml(titleStr)}" data-tooltip-desc="${escapeExpeditionHtml(tip)}">`
                + `<img src="${eggSprite}" class="exp-loot-img" alt="${escapeExpeditionHtml(rarityLabel)} egg">`
                + `<span class="exp-loot-chance">${chance}%</span>`
                + `</span>`
            );
        });
    }

    // PROBABLE: Items
    if (scaled.items) {
        Object.entries(scaled.items).forEach(([itemKey, itemInfo]) => {
            const chance = Math.round(itemInfo.chance * 100);
            const amount = itemInfo.amount;
            const itemDef: ItemDef = (ALL_ITEMS as Record<string, ItemDef>)[itemKey]
                ?? { name: itemKey, img: null, icon: 'OBJ' };
            const itemName = getExpeditionItemName(game, itemKey);
            const iconHTML = itemDef && itemDef.img
                ? `<img src="${itemDef.img}" class="exp-loot-img" alt="${escapeExpeditionHtml(itemName)}">`
                : `<span class="exp-loot-icon">${escapeExpeditionHtml((itemDef && itemDef.icon) || 'OBJ')}</span>`;
            const tip = expeditionText(
                game,
                'expedition.lootItemTip',
                '{name} x{amount} ({chance}% de chance)',
                '{name} x{amount} ({chance}% chance)',
                { name: itemName, amount, chance }
            );
            parts.push(
                `<span class="exp-loot exp-loot-probable" title="${escapeExpeditionHtml(tip)}" data-tooltip-title="${escapeExpeditionHtml(itemName)}" data-tooltip-desc="${escapeExpeditionHtml(tip)}">`
                + iconHTML
                + `<span class="exp-loot-chance">${chance}%</span>`
                + `</span>`
            );
        });
    }

    return parts.join('');
}

export function getExpeditionTalentName(game: GameRuntime, talentKey: string): string {
    const talentDef = (PASSIVE_TALENTS as Record<string, { name?: string }>)[talentKey] ?? null;
    const fallbackName = coalesceStr(talentDef?.name, talentKey);
    return callGame<string>(game, game['getLocalizedPassiveTalentName'], talentKey, fallbackName) ?? fallbackName;
}

export function normalizeExpeditionDurationMs(rawDuration: unknown): number {
    const duration = Number(rawDuration) || 0;
    if (duration <= 0) return 0;
    // Legacy expedition definitions use seconds; normalize to milliseconds at runtime.
    return duration < 60000 ? duration * 1000 : duration;
}

function notifyExpeditionPanelChanged(_game: GameRuntime): void {
    publishExpeditionChanged();
}

export function buildActiveExpeditionsHtml(game: GameRuntime): string {
    if (game.activeExpeditions.length === 0) {
        return `<p style="color: #94a3b8; text-align: center; padding: 20px; font-style: italic; border: 2px dashed #e2e8f0; border-radius: 10px;">${expeditionText(game, 'expedition.noneActive', 'Aucune expedition en cours...', 'No expedition in progress...')}</p>`;
    }
    const now = Date.now();
    let html = '';
    game.activeExpeditions.forEach((exp, index) => {
        const expeditionDef = getExpeditionDef(exp.expeditionId ?? '');
        if (!expeditionDef) return;

        let creatureName = expeditionText(game, 'state.unknown', 'Inconnu', 'Unknown');
        let spriteUrl = '';
        let levelText = '';
        try {
            if (exp.squadData && exp.squadData.length > 0) {
                const leader = Creature.deserialize(exp.squadData[0] as CreatureData);
                creatureName = coerceStr(leader.name);
                levelText = `(${expeditionText(game, 'expedition.levelShort', 'Niv {level}', 'Lvl {level}', { level: leader.level })})`;
                spriteUrl = getPokemonSpriteUrl(leader.name, leader.isShiny);
                if (exp.squadData.length > 1) creatureName += ` +${exp.squadData.length - 1}`;
            } else if (exp.creatureData) {
                const creature = Creature.deserialize(exp.creatureData as CreatureData);
                creatureName = coerceStr(creature.name);
                levelText = `(${expeditionText(game, 'expedition.levelShort', 'Niv {level}', 'Lvl {level}', { level: creature.level })})`;
                spriteUrl = getPokemonSpriteUrl(creature.name, creature.isShiny);
            } else return;
        } catch (e) {
            debugError('Expedition display error:', e);
            return;
        }

        const timeLeft = (exp.endTime ?? 0) - now;
        let statusClass = '';
        let actionHTML = '';
        let progressHTML = '';

        if (timeLeft > 0) {
            statusClass = 'accepted';
            const { hours, minutes, seconds } = formatTime(timeLeft);
            const totalDuration = Math.max(1, normalizeExpeditionDurationMs(expeditionDef.duration ?? 0));
            const elapsed = totalDuration - timeLeft;
            const percent = Math.min(100, (elapsed / totalDuration) * 100);
            progressHTML = `<div class="quest-progress-container" style="margin: 10px 0;"><div class="quest-progress-bar"><div class="quest-progress-fill" style="width: ${percent}%"></div></div><div class="quest-progress-text" style="font-size:10px; color:#64748b;">${expeditionText(game, 'expedition.remaining', 'Reste: {h}h {m}m {s}s', 'Remaining: {h}h {m}m {s}s', { h: hours, m: minutes, s: seconds })}</div></div>`;
            actionHTML = `<button class="quest-btn" disabled style="background: #cbd5e1; color: #64748b; cursor: wait; width:100%;">${expeditionText(game, 'expedition.inProgress', 'En cours...', 'In progress...')}</button>`;
        } else {
            statusClass = 'completed';
            progressHTML = `<div class="quest-progress-container" style="margin: 10px 0;"><div class="quest-progress-bar"><div class="quest-progress-fill" style="width: 100%; background: #22c55e;"></div></div><div class="quest-progress-text" style="color:#22c55e; font-weight:bold;">${expeditionText(game, 'expedition.completed', 'Terminee !', 'Completed!')}</div></div>`;
            actionHTML = `<button class="quest-btn btn-claim" data-action="claimExpedition" data-arg="${index}">${expeditionText(game, 'expedition.claimRewards', 'Recuperer les recompenses', 'Claim rewards')}</button>`;
        }

        const expeditionName = getExpeditionDisplayName(game, expeditionDef, exp.expeditionId ?? '');
        const line = expeditionText(game, 'expedition.activeLine', '<strong>{name}</strong> {level} explorent cette zone.', '<strong>{name}</strong> {level} are exploring this area.', { name: creatureName, level: levelText });

        html += `<div class="quest-card ${statusClass}"><div class="quest-header"><div class="quest-title" style="display:flex; align-items:center; gap:10px;"><img src="${spriteUrl}" style="width:32px; height:32px; vertical-align:middle;"><span>${expeditionName}</span></div></div><div class="quest-description">${line}</div>${progressHTML}${actionHTML}</div>`;
    });
    return html;
}

export function bindExpeditionLootTooltips(container: HTMLElement, game: GameRuntime): void {
    if (typeof game['scheduleTooltip'] !== 'function') return;
    const bind = (selector: string) => {
        container.querySelectorAll(selector).forEach((node) => {
            const title = node.getAttribute('data-tooltip-title') || '';
            const desc = node.getAttribute('data-tooltip-desc') || '';
            node.addEventListener('mouseenter', (ev) => { invokeGame(game, game['scheduleTooltip'], ev, title, desc); });
            node.addEventListener('mouseleave', () => { callGameVoid(game, game['hideTooltip']); });
        });
    };
    bind('.exp-loot[data-tooltip-title]');
    container.querySelectorAll('.expedition-mission-mastery-controls[data-expedition-def-id]').forEach((node) => {
        node.addEventListener('mouseenter', (ev) => {
            const defId = node.getAttribute('data-expedition-def-id') || '';
            if (!defId) return;
            const expeditionDef = getExpeditionDef(defId);
            const missionName = expeditionDef
                ? getExpeditionDisplayName(game, expeditionDef, defId)
                : defId;
            const entry = getMissionMasteryEntry(game.expeditionMissionMastery ?? {}, defId);
            const tooltip = buildMissionMasteryTooltip(
                ((key, params) => expeditionTranslate(game, key, params)) as MissionMasteryTranslate,
                missionName,
                entry,
            );
            invokeGame(game, game['scheduleTooltip'], ev, tooltip.title, tooltip.descriptionHtml);
        });
        node.addEventListener('mouseleave', () => { callGameVoid(game, game['hideTooltip']); });
    });
}

export function buildAvailableExpeditionsHtml(game: GameRuntime): string {
    let headerHtml = '';
    if (game.availableExpeditions.length < game.maxAvailableExpeditions) {
        const minutes = Math.floor(game.expeditionTimer / 60000);
        const seconds = Math.floor((game.expeditionTimer % 60000) / 1000);
        headerHtml = `<div style="text-align:center; font-size:12px; color:#666; margin-bottom:10px;">${expeditionText(game, 'expedition.nextIn', 'Prochaine mission dans :', 'Next mission in:')} <strong>${minutes}m ${seconds}s</strong></div>`;
    } else {
        headerHtml = `<div style="text-align:center; font-size:12px; color:#e74c3c; margin-bottom:10px;">${expeditionText(game, 'expedition.tableFull', 'Tableau des missions complet ! ({current}/{max})', 'Mission board full! ({current}/{max})', { current: game.availableExpeditions.length, max: game.maxAvailableExpeditions })}</div>`;
    }

    if (game.availableExpeditions.length === 0) {
        return headerHtml + `<p style="text-align:center; color:#999;">${expeditionText(game, 'expedition.noneAvailable', 'Aucune mission disponible.', 'No mission available.')}</p>`;
    }

    let finalHTML = headerHtml;

    game.availableExpeditions.forEach(inst => {
        const exp = getExpeditionDef(inst.defId ?? '');
        if (!exp) return;
        const missionLevel = getMissionLevelForDef(game, inst.defId ?? '');
        const expName = getExpeditionDisplayName(game, exp, inst.defId ?? '');
        const expDescription = getExpeditionDisplayDescription(game, exp, inst.defId ?? '');

        const lootIcons = buildExpeditionLootStripHTML(game, exp, missionLevel);
        const lootLabel = expeditionText(game, 'expedition.lootLabel', 'Butin', 'Loot');

        let reqText = '';
        const reqBadges: string[] = [];
        if (exp.regionId) {
            const regionLabel = getExpeditionRegionLabel(game, String(exp.regionId));
            reqBadges.push(`<span style="background:#6366f1; color:white; border-radius:4px; padding:2px 6px; font-size:10px;">${expeditionText(game, 'expedition.regionalPokemon', 'Pokémon {region}', '{region} Pokémon', { region: regionLabel })}</span>`);
        }
        if (exp.rewardPool.requirements && exp.rewardPool.requirements.length > 0) {
            exp.rewardPool.requirements.forEach((req: ExpeditionRequirement) => {
                if (req.type === 'type') reqBadges.push(`<span class="type-badge type-${req.value}" style="font-size:10px; padding:2px 6px;">${req.value}</span>`);
                if (req.type === 'talent') {
                    const talentName = getExpeditionTalentName(game, req.value);
                    reqBadges.push(`<span style="background:#4b5563; color:white; border-radius:4px; padding:2px 6px; font-size:10px;">* ${talentName}</span>`);
                }
            });
        }
        if (reqBadges.length > 0) {
            reqText = `<div style="margin-top:8px; display:flex; align-items:center; gap:5px; flex-wrap:wrap;"><span style="font-size:11px; font-weight:bold; color:#333;">${expeditionText(game, 'expedition.required', 'Requis:', 'Required:')}</span> ${reqBadges.join(' ')}</div>`;
        }

        const regionLabel = exp.regionId ? getExpeditionRegionLabel(game, String(exp.regionId)) : '';
        const effectiveDifficulty = getEffectiveExpeditionDifficulty(Number(exp.difficulty) || 0, missionLevel);
        const tierLabel = getExpeditionDifficultyTierLabel(game, effectiveDifficulty);
        const requiredPower = formatNumber(effectiveDifficulty);
        const missionEntry = getMissionMasteryEntry(game.expeditionMissionMastery ?? {}, inst.defId ?? '');
        const masteryControls = buildMissionMasteryControlsHtml(
            ((key, params) => expeditionTranslate(game, key, params)) as MissionMasteryTranslate,
            inst.defId ?? '',
            inst.uid ?? '',
            missionEntry,
        );
        const requiredPowerLabel = missionLevel > 1
            ? expeditionText(
                game,
                'expedition.requiredPowerMastery',
                '{power} puissance (niv. {level})',
                '{power} power (lvl {level})',
                { power: requiredPower, level: missionLevel },
            )
            : expeditionText(
                game,
                'expedition.requiredPower',
                '{power} puissance',
                '{power} power',
                { power: requiredPower },
            );
        const durationLabel = formatTimeString(normalizeExpeditionDurationMs(exp.duration));
        const metaLine = [tierLabel, requiredPowerLabel, durationLabel].filter(Boolean).join(' · ');
        const regionBadge = regionLabel
            ? `<div class="quest-badge badge-medium">${regionLabel}</div>`
            : '';

        const maxExpSlots = getMaxExpeditionSlotsForGame(game);
        const canLaunch = game.activeExpeditions.length < maxExpSlots;

        finalHTML += `
            <div class="quest-card">
            <div class="quest-header" style="display:flex; justify-content:space-between; align-items:center; gap:8px;">
                <div style="display:flex; align-items:center; gap:8px; flex-wrap:wrap;">
                    <div class="quest-title">${expName}</div>
                    ${regionBadge}
                </div>
                ${masteryControls}
            </div>
            <div class="quest-description">
                ${expDescription}${reqText}
            </div>
            <div class="quest-rewards expedition-meta-row" style="justify-content: space-between; margin-top:5px;">
                <span style="font-size:12px; color:#666;">${metaLine}</span>
            </div>
            <div class="expedition-loot-block">
                <div class="expedition-loot-label">${lootLabel}</div>
                <div class="expedition-rewards-strip">
                    ${lootIcons}
                </div>
            </div>
            <button class="quest-btn btn-accept"
                    data-action="showCreatureSelectForExpedition" data-arg="${inst.uid}" data-arg2="${inst.defId}"
                    ${canLaunch ? '' : 'disabled style="background:#ccc; cursor:not-allowed;"'}>
                ${canLaunch
                    ? expeditionText(game, 'expedition.chooseTeam', 'Choisir une equipe', 'Choose a team')
                    : expeditionText(game, 'expedition.activeSlotsFull', 'Actifs ({current}/{max})', 'Active ({current}/{max})', { current: game.activeExpeditions.length, max: maxExpSlots })}
            </button>
            </div>
        `;
    });

    return finalHTML;
}

export function updateExpeditionsDisplayLogic(game: GameRuntime): void {
    notifyExpeditionPanelChanged(game);
    callGameVoid(game, game['updateTabBadges']);
}

export function updateAvailableExpeditionsListLogic(game: GameRuntime): void {
    notifyExpeditionPanelChanged(game);
}

export function updateExpeditionTimerLogic(game: GameRuntime, deltaTime: number): void {
    if (!game.unlockedFeatures || !game.unlockedFeatures.expeditionsTab) return;
    if (game.availableExpeditions.length >= game.maxAvailableExpeditions) {
        game.expeditionTimer = game.EXPEDITION_GEN_TIME;
        return;
    }
    game.expeditionTimer -= deltaTime;
    if (game.expeditionTimer <= 0) {
        callGameVoid(game, game['generateRandomExpedition']);
        game.expeditionTimer = game.EXPEDITION_GEN_TIME;
    }
}

export function meetsExpeditionUnlockRequirement(game: GameRuntime, expeditionDef: ExpeditionDefinition): boolean {
    const req = expeditionDef.unlockRequirement;
    if (!req || typeof req !== 'string') return true;
    if (req.startsWith('badge:')) {
        const badgeKey = req.slice('badge:'.length);
        return typeof game.hasBadge === 'function' && game.hasBadge(badgeKey);
    }
    return true;
}

export function meetsExpeditionRegionalRequirement(creature: CreatureData, expeditionDef: ExpeditionDefinition): boolean {
    const regionId = expeditionDef.regionId;
    if (!regionId || typeof regionId !== 'string') return true;
    return inferRegionalArcId(creature) === regionId;
}

function getAllExpeditionCandidateCreatures(game: GameRuntime): CreatureData[] {
    return [
        ...(game.playerTeam || []),
        ...(game.storage || []),
        ...(game.pension || []),
    ].filter(Boolean) as CreatureData[];
}

export function hasEligibleExpeditionPokemon(game: GameRuntime, expeditionDef: ExpeditionDefinition): boolean {
    return getAllExpeditionCandidateCreatures(game).some(creature =>
        meetsExpeditionRegionalRequirement(creature, expeditionDef)
        && meetsExpeditionRequirementsLogic(game, creature, expeditionDef)
    );
}

function getExpeditionRegionLabel(game: GameRuntime, regionId: string): string {
    const labels: Record<string, { fr: string; en: string }> = {
        kanto: { fr: 'Kanto', en: 'Kanto' },
        johto: { fr: 'Johto', en: 'Johto' },
        hoenn: { fr: 'Hoenn', en: 'Hoenn' },
        sinnoh: { fr: 'Sinnoh', en: 'Sinnoh' },
        unova: { fr: 'Unova', en: 'Unova' },
        kalos: { fr: 'Kalos', en: 'Kalos' },
        paldea: { fr: 'Paldea', en: 'Paldea' },
    };
    const row = labels[regionId];
    if (!row) return regionId;
    return expeditionIsEn(game) ? row.en : row.fr;
}

function getExpeditionDifficultyTierLabel(game: GameRuntime, difficulty: number): string {
    const d = Number(difficulty) || 0;
    if (d >= 28000) return expeditionText(game, 'expedition.tier.raid', 'Raid', 'Raid');
    if (d >= 22000) return expeditionText(game, 'expedition.tier.expert', 'Expert', 'Expert');
    if (d >= 15000) return expeditionText(game, 'expedition.tier.hard', 'Difficile', 'Hard');
    if (d >= 8000) return expeditionText(game, 'expedition.tier.moderate', 'Modéré', 'Moderate');
    return expeditionText(game, 'expedition.tier.easy', 'Facile', 'Easy');
}

export function meetsExpeditionRequirementsLogic(game: GameRuntime, creature: CreatureData, expeditionDef: ExpeditionDefinition): boolean {
    if (!expeditionDef.rewardPool || !expeditionDef.rewardPool.requirements || expeditionDef.rewardPool.requirements.length === 0) return true;
    return expeditionDef.rewardPool.requirements.some(req => {
        if (req.type === 'type') return creature.type === req.value || creature.secondaryType === req.value;
        if (req.type === 'talent') return creature.passiveTalent === req.value;
        return false;
    });
}

export function calculateIndividualScoreLogic(game: GameRuntime, creature: CreatureData, expeditionDef: ExpeditionDefinition): number {
    return getCreatureCombatPower(creature);
}

export function calculateTeamSuccessRateLogic(game: GameRuntime, squad: CreatureData[], expeditionDef: ExpeditionDefinition): number {
    let totalScore = 0;
    squad.forEach(c => { totalScore += finiteGameNumber(game, game['calculateIndividualScore'], c, expeditionDef); });
    const difficulty = expeditionDef.difficulty || 100;
    return Math.max(0.1, Math.min(EXPEDITION_SUCCESS_RATE_MAX, totalScore / difficulty));
}

export function calculateExpeditionSuccessRateLogic(game: GameRuntime, creature: CreatureData, expeditionDef: ExpeditionDefinition): number {
    const creatureScore = finiteGameNumber(game, game['calculateIndividualScore'], creature, expeditionDef);
    const difficulty = expeditionDef.difficulty || 100;
    return Math.max(0.1, Math.min(EXPEDITION_SUCCESS_RATE_MAX, creatureScore / difficulty));
}

export function generateRandomExpeditionLogic(game: GameRuntime): void {
    if (game.availableExpeditions.length >= game.maxAvailableExpeditions) return;
    const allKeys = Object.keys(EXPEDITION_DEFS);
    const eligibleKeys = allKeys.filter(key => {
        const def = EXPEDITION_DEFS[key];
        return def
            && meetsExpeditionUnlockRequirement(game, def)
            && hasEligibleExpeditionPokemon(game, def);
    });
    const unlockedKeys = allKeys.filter(key => {
        const def = EXPEDITION_DEFS[key];
        return def && meetsExpeditionUnlockRequirement(game, def);
    });
    const pool = eligibleKeys.length > 0 ? eligibleKeys : (unlockedKeys.length > 0 ? unlockedKeys : allKeys);
    const randomKey = pool[Math.floor(Math.random() * pool.length)];
    game.availableExpeditions.push({
        uid: Date.now() + Math.random(),
        defId: randomKey,
        generatedAt: Date.now()
    });
    toast.info(
        expeditionText(game, 'expedition.newMissionTitle', 'Nouvelle mission', 'New mission'),
        expeditionText(game, 'expedition.newMissionBody', 'Une nouvelle expedition est disponible !', 'A new expedition is available!')
    );
    callGameVoid(game, game['updateExpeditionsDisplay']);
}

export function startExpeditionLogic(game: GameRuntime, storageIndices: number | number[], expeditionUid: string, expeditionId: string): void {
    if (game.activeExpeditions.length >= getMaxExpeditionSlotsForGame(game)) {
        logMessage(`[X] ${expeditionText(game, 'expedition.slotsFull', "Slots d'expedition pleins !", 'Expedition slots are full!')}`);
        return;
    }
    let missionIndex = -1;
    if (expeditionUid != null) {
        missionIndex = game.availableExpeditions.findIndex(e => String(e.uid) === String(expeditionUid));
        if (missionIndex === -1) {
            logMessage(`[X] ${expeditionText(game, 'expedition.unavailable', "Cette expedition n'est plus disponible.", 'This expedition is no longer available.')}`);
            callGameVoid(game, game['updateAvailableExpeditionsList']);
            return;
        }
    }
    const expeditionDef = getExpeditionDef(expeditionId);
    if (!expeditionDef) return;
    if (!meetsExpeditionUnlockRequirement(game, expeditionDef)) {
        logMessage(`[X] ${expeditionText(game, 'expedition.locked', 'Cette expédition est verrouillée.', 'This expedition is locked.')}`);
        return;
    }

    const indicesArray = Array.isArray(storageIndices) ? storageIndices : [storageIndices];
    indicesArray.sort((a, b) => b - a);
    const squad = [];
    for (const idx of indicesArray) {
        const creature = game.storage[idx];
        if (!creature) continue;
        if (!meetsExpeditionRegionalRequirement(creature, expeditionDef)) {
            toast.error(
                expeditionText(game, 'expedition.wrongRegionTitle', 'Région incompatible', 'Wrong region'),
                expeditionText(
                    game,
                    'expedition.wrongRegionBody',
                    "{name} n'est pas un Pokémon de cette région.",
                    '{name} is not a Pokémon from this region.',
                    { name: coerceStr(creature.name) }
                )
            );
            return;
        }
        if (!meetsExpeditionRequirementsLogic(game, creature, expeditionDef)) {
            toast.error(
                expeditionText(game, 'expedition.incompatibleTitle', 'Pokémon incompatible', 'Incompatible Pokémon'),
                expeditionText(
                    game,
                    'expedition.incompatibleBody',
                    "{name} ne remplit pas les conditions de l'expédition.",
                    '{name} does not meet the expedition requirements.',
                    { name: coerceStr(creature.name) }
                )
            );
            return;
        }
        squad.push(creature);
    }
    if (squad.length === 0) return;

    const missionLevel = getMissionLevelForDef(game, expeditionId);
    const effectiveDef = withMissionDifficulty(expeditionDef, missionLevel);
    const successRate = finiteGameNumber(game, game['calculateTeamSuccessRate'], squad, effectiveDef) || 0.1;
    for (const idx of indicesArray) {
        game.storage.splice(idx, 1);
    }

    let duration = normalizeExpeditionDurationMs(expeditionDef.duration);
    let timeReduction = 0;

    const biome = EXPEDITION_BIOMES[expeditionId as keyof typeof EXPEDITION_BIOMES];
    if (biome && game.expeditionMastery) {
        const xp = Number(game.expeditionMastery[biome]) || 0;
        timeReduction += getBiomeMasteryTimeBonus(xp);
    }

    const collBonus = Number(collectionBonuses(game).expedition_time_reduction) || 0;
    timeReduction += collBonus;
    timeReduction += finiteGameNumber(game, game['getAccountTalentBonus'], 'expedition_time_reduction');
    timeReduction += finiteGameNumber(game, game['getMasteryBonus'], 'expedition_time_reduction');

    // Cap à 90% de réduction maximum pour éviter les softlocks ou durées négatives
    if (timeReduction > 0) {
        timeReduction = Math.min(0.9, timeReduction);
        duration = Math.floor(duration * (1 - timeReduction));
    }

    const expedition = {
        squadData: squad.map(c => c.serialize?.() ?? c),
        expeditionId: expeditionId,
        startTime: Date.now(),
        endTime: Date.now() + duration,
        successRateSnapshot: successRate,
        missionMasteryLevel: missionLevel,
    };
    if (missionIndex >= 0) game.availableExpeditions.splice(missionIndex, 1);
    game.activeExpeditions.push(expedition);
    invalidateResonanceCache(game);
    invokeGame(game, game['trackBalanceEvent'], 'expedition_launched', { expeditionId });
    game.stats.expeditionLaunched = (game.stats.expeditionLaunched || 0) + 1;
    invokeGame(game, game['checkAchievements'], 'expeditionLaunched');
    invokeGame(game, game['checkSpecialQuests'], 'expeditionLaunched');

    const names = squad.map(c => c.name).join(', ');
    const expeditionName = getExpeditionDisplayName(game, expeditionDef, expeditionId);
    const chanceStr = successRate >= EXPEDITION_SUCCESS_RATE_MAX
        ? expeditionText(game, 'expedition.successCriticalGuaranteed', ' (Butin double garanti)', ' (Double loot guaranteed)')
        : successRate >= 1
            ? expeditionText(game, 'expedition.successGuaranteed', ' (Succes garanti)', ' (Guaranteed success)')
            : expeditionText(game, 'expedition.successPercent', ' ({percent}%)', ' ({percent}%)', { percent: Math.floor(successRate * 100) });

    logMessage(expeditionText(
        game,
        'expedition.launchLog',
        '[OK] Depart : {names} vers {expedition}{chance}',
        '[OK] Departure: {names} to {expedition}{chance}',
        { names, expedition: expeditionName, chance: chanceStr }
    ));

    toast.info(
        expeditionText(game, 'expedition.launchedTitle', 'Expedition lancee', 'Expedition launched'),
        expeditionText(game, 'expedition.returnIn', 'Retour dans {duration}.', 'Back in {duration}.', { duration: formatTimeString(duration) })
    );

    const selectModal = document.getElementById('creatureSelectModal');
    if (selectModal) document.body.removeChild(selectModal);

    callGameVoid(game, game['updateStorageDisplay']);
    callGameVoid(game, game['updateExpeditionsDisplay']);
}

export function claimExpeditionLogic(game: GameRuntime, index: number): void {
    const expedition = game.activeExpeditions[index];
    if (!expedition || Date.now() < (expedition.endTime ?? 0)) return;

    const expeditionDef = getExpeditionDef(expedition.expeditionId ?? '');
    if (!expeditionDef) {
        logMessage(`[X] ${expeditionText(game, 'expedition.definitionMissing', "Erreur critique : definition d'expedition introuvable.", 'Critical error: missing expedition definition.')}`);
        game.activeExpeditions.splice(index, 1);
        callGameVoid(game, game['updateExpeditionsDisplay']);
        return;
    }

    let squad: Creature[] = [];
    try {
        if (expedition.squadData && Array.isArray(expedition.squadData)) {
            squad = expedition.squadData.map(data => Creature.deserialize(data as CreatureData));
        } else if (expedition.creatureData) {
            squad = [Creature.deserialize(expedition.creatureData as CreatureData)];
        } else throw new Error(expeditionText(game, 'expedition.noCreatureData', 'Aucune donnee de creature trouvee.', 'No creature data found.'));
    } catch (e) {
        debugError(expeditionText(game, 'expedition.squadRecoverError', "Erreur lors de la recuperation de l'escouade :", 'Error while restoring squad:'), e);
        game.activeExpeditions.splice(index, 1);
        callGameVoid(game, game['updateExpeditionsDisplay']);
        return;
    }

    const successRate = expedition.successRateSnapshot || 1.0;
    const leader = squad[0];
    if (!leader) {
        game.activeExpeditions.splice(index, 1);
        callGameVoid(game, game['updateExpeditionsDisplay']);
        return;
    }
    const missionLevel = Math.max(1, Math.floor(Number(expedition.missionMasteryLevel) || getMissionLevelForDef(game, expedition.expeditionId ?? '')));
    const rewards = callGame<ExpeditionRewards>(
        game,
        game['calculateExpeditionRewards'],
        expeditionDef,
        leader,
        successRate,
        missionLevel,
    ) ?? { pokedollars: 0, tokens: 0, shards: 0, eggs: {}, items: {}, performance: 'NORMAL' };

    squad.forEach(creature => {
        creature.heal();
        game.storage.push(creature);
    });

    const biome = EXPEDITION_BIOMES[(expedition.expeditionId ?? '') as keyof typeof EXPEDITION_BIOMES];
    if (!game.expeditionMastery) game.expeditionMastery = { level: 0, xp: 0 };
    const xpMult = finiteGameNumber(game, game['getMasteryBonus'], 'biome_mastery_xp_mult');
    const performanceGain = applyMasteryXpMultiplier(computePerformanceXpGain(rewards.performance), xpMult);
    if (biome) {
        game.expeditionMastery[biome] = (game.expeditionMastery[biome] || 0) + performanceGain;
    }
    if (!game.expeditionMissionMastery) game.expeditionMissionMastery = {};
    grantMissionMasteryXp(
        game.expeditionMissionMastery,
        expedition.expeditionId ?? '',
        rewards.performance,
        xpMult,
    );

    const rewardMessages = [];
    let title = expeditionText(game, 'expedition.returnTitle', "Retour d'expedition", 'Expedition return');
    let toastType: ExpeditionToastType = 'success';
    if (rewards.performance === 'CRITICAL') {
        title = expeditionText(game, 'expedition.criticalTitle', '[CRITICAL SUCCESS]', '[CRITICAL SUCCESS]');
        toastType = 'legendary';
        rewardMessages.push(expeditionText(game, 'expedition.criticalBody', 'Performance exceptionnelle ! (Butin x2)', 'Outstanding performance! (Loot x2)'));
    } else if (rewards.performance === 'FAILURE') {
        title = expeditionText(game, 'expedition.failureTitle', '[Failure]', '[Failure]');
        toastType = 'warning';
        rewardMessages.push(expeditionText(game, 'expedition.failureBody', "L'expedition a mal tourne...", 'The expedition went badly...'));
    }

    if (rewards.pokedollars > 0) {
        const pdResult = typeof game.addCombatPokedollars === 'function'
            ? game.addCombatPokedollars(rewards.pokedollars, 'silent')
            : { creditedToWallet: rewards.pokedollars, net: rewards.pokedollars };
        const credited = Math.max(0, Number(pdResult.creditedToWallet ?? pdResult.net) || 0);
        rewardMessages.push(expeditionText(game, 'expedition.rewardPokedollars', '{amount}$', '{amount}$', { amount: formatNumber(credited) }));
    }
    if (rewards.tokens > 0) {
        const tokenReward = callGameNumber(game, game['scaleMasteryQuestTokenAmount'], rewards.tokens);
        game.questTokens += tokenReward;
        if (game.stats) game.stats.totalQuestTokensEarned = (game.stats.totalQuestTokensEarned || 0) + tokenReward;
        rewardMessages.push(expeditionText(game, 'expedition.rewardTokens', '{amount} tokens', '{amount} tokens', { amount: tokenReward }));
    }
    if (rewards.shards > 0) {
        const shardKey = getShardKey(coerceStr(leader.name), leader.rarity);
        game.shards[shardKey] = (game.shards[shardKey] || 0) + rewards.shards;
        rewardMessages.push(expeditionText(game, 'expedition.rewardShards', '{amount} shards ({name})', '{amount} shards ({name})', { amount: rewards.shards, name: coerceStr(leader.name) }));
        invokeGame(game, game['checkSpecialQuests'], 'totalShards');
    }
    if (rewards.eggs) {
        Object.entries(rewards.eggs).forEach(([rarity, amount]) => {
            game.eggs[rarity] = (game.eggs[rarity] || 0) + amount;
            const rarityLabel = callGame<string>(game, game['getRarityLabel'], rarity) ?? rarity;
            rewardMessages.push(expeditionText(game, 'expedition.rewardEgg', '{amount}x egg {rarity}', '{amount}x {rarity} egg', { amount, rarity: rarityLabel }));
        });
    }
    if (rewards.items) {
        Object.entries(rewards.items).forEach(([itemKey, amount]) => {
            invokeGame(game, game['addItem'], itemKey, amount);
            const itemName = getExpeditionItemName(game, itemKey);
            rewardMessages.push(expeditionText(game, 'expedition.rewardItem', '{amount}x {item}', '{amount}x {item}', { amount, item: itemName }));
        });
    }
    if (rewardMessages.length === 0) {
        rewardMessages.push(expeditionText(game, 'expedition.noReward', 'Aucune recompense notable', 'No notable reward'));
    }

    game.activeExpeditions.splice(index, 1);
    invalidateResonanceCache(game);
    invokeGame(game, game['trackBalanceEvent'], 'expedition_claimed', { expeditionId: expedition.expeditionId, performance: rewards.performance });
    const names = squad.map(c => c.name).join(', ');
    logMessage(expeditionText(
        game,
        'expedition.returnLog',
        '[OK] {names} de retour. {rewards}',
        '[OK] {names} are back. {rewards}',
        { names, rewards: rewardMessages.join(', ') }
    ));
    // Toast permanent de résumé des gains (fermeture manuelle par le joueur).
    toast.show({
        title,
        message: buildExpeditionRewardsToastHtml(game, rewards, leader),
        type: toastType,
        duration: 0,
        html: true
    });

    callGameVoid(game, game['updateStorageDisplay']);
    callGameVoid(game, game['updateExpeditionsDisplay']);
    callGameVoid(game, game['updateEggsDisplay']);
    callGameVoid(game, game['updateShopDisplay']);
    callGameVoid(game, game['updatePlayerStatsDisplay']);
    if (rewards.items && Object.keys(rewards.items).length > 0) {
        if (typeof game.syncTalentConsumablesInInventory === 'function') {
            game.syncTalentConsumablesInInventory();
        }
        callGameVoid(game, game['updateItemsDisplay']);
    }
}

export function calculateExpeditionRewardsLogic(
    game: GameRuntime,
    expeditionDef: ExpeditionDefinition,
    creature: CreatureData,
    successRate: number,
    missionMasteryLevel = 1,
): ExpeditionRewards {
    let performance = 'NORMAL';
    const roll = Math.random();
    if (successRate > 1.0 && roll < (successRate - 1.0)) performance = 'CRITICAL';
    else if (roll > successRate) performance = 'FAILURE';

    const rewards: ExpeditionRewards = { pokedollars: 0, tokens: 0, shards: 0, eggs: {}, items: {}, performance };
    const pool = expeditionDef.rewardPool;
    let lootMultiplier = 1;
    if (performance === 'FAILURE') lootMultiplier = 0.25;
    if (performance === 'CRITICAL') lootMultiplier = 2.0;

    // Reward scaling by mission duration so long expeditions pay better.
    const durationMs = normalizeExpeditionDurationMs(expeditionDef.duration);
    const durationHours = durationMs > 0 ? (durationMs / (60 * 60 * 1000)) : 0;
    let durationRewardMultiplier = 1.0;
    if (durationHours >= 8) durationRewardMultiplier = 2.1;
    else if (durationHours >= 5) durationRewardMultiplier = 1.7;
    else if (durationHours >= 3) durationRewardMultiplier = 1.4;
    else if (durationHours >= 2) durationRewardMultiplier = 1.2;
    const valueMultiplier = lootMultiplier * durationRewardMultiplier;
    const durationChanceBonus = Math.min(0.45, Math.max(0, durationRewardMultiplier - 1) * 0.6);
    const missionMults = getMissionMasteryMultipliers(missionMasteryLevel);
    const missionRewardMult = missionMults.rewardMult;
    const missionRateMult = missionMults.rateMult;

    if (pool.pokedollars) {
        const base = Math.floor(Math.random() * (pool.pokedollars.max - pool.pokedollars.min) + pool.pokedollars.min);
        const masteryExpBonus = finiteGameNumber(game, game['getMasteryBonus'], 'expedition_reward_mult');
        rewards.pokedollars = Math.floor(base * valueMultiplier * missionRewardMult * (1 + masteryExpBonus));
    }
    if (pool.tokens && performance !== 'FAILURE') {
        const tokenChance = Math.min(1, pool.tokens.chance * (1 + durationChanceBonus) * missionRateMult);
        if (Math.random() < tokenChance) {
            const base = Math.floor(Math.random() * (pool.tokens.max - pool.tokens.min) + pool.tokens.min);
            rewards.tokens = Math.floor(base * valueMultiplier * missionRewardMult);
        }
    }
    if (pool.shards && Math.random() < Math.min(1, pool.shards.chance * missionRateMult)) {
        rewards.shards = Math.max(1, Math.floor(pool.shards.amount * valueMultiplier * missionRewardMult));
    }
    if (pool.eggs && performance !== 'FAILURE') {
        Object.entries(pool.eggs).forEach(([rarity, eggInfo]) => {
            let chance = eggInfo.chance * (performance === 'CRITICAL' ? 1.5 : 1) * (1 + durationChanceBonus) * missionRateMult;
            chance = Math.min(1, chance);
            if (Math.random() < chance) rewards.eggs[rarity] = (rewards.eggs[rarity] || 0) + eggInfo.amount;
        });
    }
    if (pool.items && performance !== 'FAILURE') {
        Object.entries(pool.items).forEach(([itemKey, itemInfo]) => {
            let chance = itemInfo.chance * (performance === 'CRITICAL' ? 1.5 : 1) * (1 + durationChanceBonus) * missionRateMult;
            chance = Math.min(1, chance);
            if (Math.random() < chance) rewards.items[itemKey] = (rewards.items[itemKey] || 0) + itemInfo.amount;
        });
    }
    const expeditionBiome = EXPEDITION_BIOMES[expeditionDef.id as keyof typeof EXPEDITION_BIOMES];
    if (expeditionBiome === 'CAVE' && performance !== 'FAILURE' && CAVE_DYNITE_ORE_DROP) {
        let dyniteChance = CAVE_DYNITE_ORE_DROP.chance * (performance === 'CRITICAL' ? 1.5 : 1) * (1 + durationChanceBonus) * missionRateMult;
        dyniteChance = Math.min(1, dyniteChance);
        if (Math.random() < dyniteChance) {
            rewards.items.dynite_ore = (rewards.items.dynite_ore || 0) + CAVE_DYNITE_ORE_DROP.amount;
        }
    }
    let prospectSum = 0;
    let pr = 0;
    if (game.playerTeam && Array.isArray(game.playerTeam)) {
        game.playerTeam.forEach((c) => {
            if (c && c.passiveTalent === 'prospecteur') {
                prospectSum += Math.pow(0.5, pr);
                pr++;
            }
        });
    }
    if (prospectSum > 0) {
        const eluActive = typeof game.hasEluActive === 'function' && game.hasEluActive();
        const prospectRate = scaleTalentRatio(0.12, eluActive ? ELU_TALENT_BOOST : 1);
        const prospectMult = 1 + prospectRate * prospectSum;
        rewards.pokedollars = Math.floor(rewards.pokedollars * prospectMult);
        rewards.tokens = Math.floor(rewards.tokens * prospectMult);
        rewards.shards = Math.floor(rewards.shards * prospectMult);
    }
    return rewards;
}

export function showCreatureSelectForExpeditionLogic(game: GameRuntime, expeditionUid: string, expeditionId: string): void {
    const expeditionDef = getExpeditionDef(expeditionId);
    if (!expeditionDef) return;
    game.tempSquad = [];
    const teamSize = expeditionDef.teamSize || 1;
    const expeditionName = getExpeditionDisplayName(game, expeditionDef, expeditionId);

    const candidates = game.storage.map((creature, index) => {
        const meetsReqs = !!callGame<boolean>(game, game['meetsExpeditionRequirements'], creature, expeditionDef);
        const meetsRegionalReq = meetsExpeditionRegionalRequirement(creature, expeditionDef);
        const rocketLocked = !!callGame<boolean>(game, game['isCreatureRocketLocked'], creature);
        const individualScore = finiteGameNumber(game, game['calculateIndividualScore'], creature, expeditionDef);
        return {
            creature,
            index,
            individualScore,
            compatible: meetsReqs && meetsRegionalReq && !rocketLocked,
        };
    }).filter(c => c.compatible);
    candidates.sort((a, b) => b.individualScore - a.individualScore);

    const existingModal = document.getElementById('creatureSelectModal');
    if (existingModal) document.body.removeChild(existingModal);

    const modal = document.createElement('div');
    modal.id = 'creatureSelectModal';
    modal.className = 'stats-modal show expedition-select-modal';
    modal.addEventListener('click', function (e) { if (e.target === modal) document.body.removeChild(modal); });

    const content = document.createElement('div');
    content.className = 'stats-content creature-select-content';

    const cancelLabel = expeditionText(game, 'expedition.cancel', 'Annuler', 'Cancel');
    const launchLabel = expeditionText(game, 'expedition.launchAction', 'Lancer', 'Launch');
    
    // Use a placeholder string to prevent the translation system from escaping our HTML tags.
    const rawSubtitle = expeditionText(game, 'expedition.selectPokemonCount', 'Selectionnez {count} Pokemon.', 'Select {count} creatures.', { count: '___SQUAD_COUNT___' });
    const formattedSubtitle = rawSubtitle.replace('___SQUAD_COUNT___', `<strong><span id="squadCount">0</span>/${teamSize}</strong>`);

    let html = `
        <div class="stats-header">
            <h2>${expeditionName}</h2>
            <button type="button"
                    class="stats-close"
                    data-action="closeCreatureSelectModal">&#10005;</button>
        </div>
        <p class="creature-select-subtitle">
            ${formattedSubtitle}
        </p>
        <div id="squadList" class="creature-select-list" role="listbox" aria-multiselectable="true">
    `;
    if (candidates.length === 0) {
        const requirements = expeditionDef.rewardPool.requirements || [];
        const reqsHTMLParts: string[] = [];
        if (expeditionDef.regionId) {
            const regionLabel = getExpeditionRegionLabel(game, String(expeditionDef.regionId));
            reqsHTMLParts.push(expeditionText(game, 'expedition.regionalPokemon', 'Pokémon {region}', '{region} Pokémon', { region: regionLabel }));
        }
        const typeTalentHTML = requirements.length > 0
            ? requirements.map((r: ExpeditionRequirement) => {
                if (r.type === 'type') {
                    const raw = expeditionText(game, 'expedition.reqTypeHtml', 'Type <strong>{value}</strong>', 'Type <strong>{value}</strong>', { value: '___VAL___' });
                    return raw.replace('___VAL___', `<strong>${r.value}</strong>`).replace('<strong><strong>', '<strong>').replace('</strong></strong>', '</strong>');
                }
                if (r.type === 'talent') {
                    const talentName = getExpeditionTalentName(game, r.value);
                    const raw = expeditionText(game, 'expedition.reqTalentHtml', 'Talent <strong>{value}</strong>', 'Talent <strong>{value}</strong>', { value: '___VAL___' });
                    return raw.replace('___VAL___', `<strong>${talentName}</strong>`).replace('<strong><strong>', '<strong>').replace('</strong></strong>', '</strong>');
                }
                return '';
            }).filter(Boolean).join(` ${expeditionText(game, 'expedition.or', 'OU', 'OR')} `)
            : '';
        if (typeTalentHTML) reqsHTMLParts.push(typeTalentHTML);
        const reqsHTML = reqsHTMLParts.length > 0
            ? reqsHTMLParts.join(` ${expeditionText(game, 'expedition.and', 'ET', 'AND')} `)
            : expeditionText(game, 'expedition.noRestriction', 'Aucune restriction', 'No restriction');

        html += `<div class="creature-select-empty">${expeditionText(game, 'expedition.noCompatiblePokemon', 'Aucun Pokemon compatible.', 'No compatible creature.')}<br><small>${reqsHTML}</small></div>`;
    } else {
        candidates.forEach(cand => {
            const c = cand.creature;
            const spriteUrl = getPokemonSpriteUrl(c.name, c.isShiny);
            const divId = `cand-${cand.index}`;
            html += `
            <div id="${divId}"
                 class="creature-select-candidate"
                 data-action="toggleSquadSelection" data-arg="${cand.index}" data-arg2="${teamSize}" data-arg3="${divId}" data-expedition-id="${expeditionId}"
                 role="option"
                 aria-selected="false"
                 tabindex="0">
                <img src="${spriteUrl}" class="creature-select-sprite" alt="${c.name}">
                <div class="creature-select-meta">
                    <div class="creature-select-name">
                        ${c.name} <span class="creature-select-level">${expeditionText(game, 'expedition.levelCompact', 'Niv.{level}', 'Lv.{level}', { level: c.level })}</span>
                    </div>
                    <div class="creature-select-power">
                        ${expeditionText(game, 'expedition.powerLabel', 'Puissance', 'Power')}: ${formatNumber(cand.individualScore)}
                    </div>
                </div>
            </div>
        `;
        });
    }
    html += `
        </div>
        <div id="launchButtonContainer" class="creature-select-actions">
            <div class="creature-select-success">
                <span class="creature-select-success-label">
                    ${expeditionText(game, 'expedition.successChance', 'Chances de reussite', 'Success chance')}
                </span>
                <span id="squadSuccessText" class="creature-select-success-value success-low">
                    0%
                </span>
            </div>
            <div class="creature-select-buttons">
                <button type="button"
                        class="btn creature-select-cancel-btn"
                        data-action="closeCreatureSelectModal"
                        >
                    ${cancelLabel}
                </button>
                <button id="btnLaunchExpedition"
                        class="btn btn-save creature-select-launch-btn"
                        disabled
                        data-action="finalizeSquadStart" data-arg="${expeditionUid}" data-arg2="${expeditionId}">
                    ${launchLabel}
                </button>
            </div>
        </div>
    `;
    content.innerHTML = html;
    modal.appendChild(content);
    document.body.appendChild(modal);
}

export function adjustExpeditionMissionLevelLogic(game: GameRuntime, defId: string, delta: number): void {
    if (!defId) return;
    if (!game.expeditionMissionMastery) game.expeditionMissionMastery = {};
    const parsedDelta = Math.floor(Number(delta) || 0);
    if (parsedDelta === 0) return;
    const result = adjustMissionActiveLevel(game.expeditionMissionMastery, defId, parsedDelta);
    if (!result.ok) {
        toast.warning(
            expeditionText(game, 'expedition.missionMasteryAdjustTitle', 'Maîtrise mission', 'Mission mastery'),
            expeditionText(game, result.errorKey ?? 'expedition.missionMasteryLevelInvalid', 'Niveau indisponible.', 'Level unavailable.'),
        );
        return;
    }
    if (typeof game.saveGame === 'function') game.saveGame();
    callGameVoid(game, game['updateExpeditionsDisplay']);
}

export function toggleSquadSelectionLogic(game: GameRuntime, storageIndex: number, maxSize: number, divId: string, expeditionId: string): void {
    const div = document.getElementById(divId);
    if (!div) return;
    const indexInSquad = game.tempSquad.indexOf(storageIndex);
    if (indexInSquad === -1) {
        if (game.tempSquad.length >= maxSize) {
            toast.warning(
                expeditionText(game, 'expedition.teamFullTitle', 'Equipe complete', 'Team full'),
                expeditionText(game, 'expedition.teamFullBody', 'Max {max} Pokemon.', 'Max {max} creatures.', { max: maxSize })
            );
            return;
        }
        game.tempSquad.push(storageIndex);
        div.classList.add('squad-selected');
        div.setAttribute('aria-selected', 'true');
    } else {
        game.tempSquad.splice(indexInSquad, 1);
        div.classList.remove('squad-selected');
        div.setAttribute('aria-selected', 'false');
    }
    const countSpan = document.getElementById('squadCount');
    if (countSpan) countSpan.textContent = String(game.tempSquad.length);
    const expeditionDef = getExpeditionDef(expeditionId);
    let currentRate = 0;
    if (game.tempSquad.length > 0 && expeditionDef) {
        const missionLevel = getMissionLevelForDef(game, expeditionId);
        const effectiveDef = withMissionDifficulty(expeditionDef, missionLevel);
        const tempCreatures = game.tempSquad.map(idx => game.storage[idx]);
        currentRate = finiteGameNumber(game, game['calculateTeamSuccessRate'], tempCreatures, effectiveDef);
    }
    const successText = document.getElementById('squadSuccessText');
    const percent = Math.floor(currentRate * 100);
    if (successText) {
        successText.textContent = `${percent}%`;
        successText.classList.remove('success-low', 'success-medium', 'success-high');
        if (percent >= 100) successText.classList.add('success-high');
        else if (percent >= 70) successText.classList.add('success-medium');
        else successText.classList.add('success-low');
    }
    const btnLaunch = document.getElementById('btnLaunchExpedition');
    if (btnLaunch) {
        if (game.tempSquad.length === maxSize) {
            (btnLaunch as HTMLButtonElement).disabled = false;
            btnLaunch.textContent = expeditionText(game, 'expedition.launchActionUpper', 'LANCER', 'LAUNCH');
        } else {
            (btnLaunch as HTMLButtonElement).disabled = true;
            btnLaunch.textContent = expeditionText(
                game,
                'expedition.chooseMore',
                'CHOISIR ENCORE {remaining}',
                'CHOOSE {remaining} MORE',
                { remaining: maxSize - game.tempSquad.length }
            );
        }
    }
}

