import { currentZone, maxReachedZone } from '../../gameManager.ts';
import type { GameRuntime } from '../types/game.ts';

/** Empreinte structurelle pour dirty-check autosave (farm stats → timer only). */
export function buildAutoSaveSignature(game: GameRuntime): string {
    const stats = game.stats || {};
    const trState = game.teamRocketState || {};
    const trQuestProgress = (trState.questProgress && typeof trState.questProgress === 'object')
        ? trState.questProgress
        : {};
    const trCasinoStats = (trState.casino && trState.casino.stats && typeof trState.casino.stats === 'object')
        ? trState.casino.stats
        : {};
    const trCasinoHistoryLen = (trState.casino && Array.isArray(trState.casino.history))
        ? trState.casino.history.length
        : 0;
    const teamLen = Array.isArray(game.playerTeam) ? game.playerTeam.length : 0;
    const storageLen = Array.isArray(game.storage) ? game.storage.length : 0;
    const pensionLen = Array.isArray(game.pension) ? game.pension.length : 0;

    const currentZoneVal = currentZone;
    const maxReachedZoneVal = maxReachedZone;

    return [
        currentZoneVal,
        maxReachedZoneVal,
        game.questTokens,
        game.triumphMarks,
        game.talentRerolls,
        game.talentChoices,
        game.essenceDust,
        teamLen,
        storageLen,
        pensionLen,
        stats.evolutionsCount || 0,
        Number(trState.rj) || 0,
        Number((trQuestProgress as Record<string, number>).spins) || 0,
        Number((trCasinoStats as Record<string, number>).spins) || 0,
        Number((trCasinoStats as Record<string, number>).rjSpent) || 0,
        Number((trCasinoStats as Record<string, number>).rjWon) || 0,
        Number((trCasinoStats as Record<string, number>).jackpots) || 0,
        trCasinoHistoryLen,
    ].join('|');
}
