/**
 * Resolve dust shop catalog entries by shop key or by `item.id` (UI offer id).
 */
import { DUST_SHOP_ITEMS } from '../../constants/balance/pokemartDust.js';

export interface DustShopCatalogItem {
    id?: string;
    requiredBadge?: string;
    requiresRadar?: boolean;
    type?: string;
    cost?: number;
    item?: string;
    amount?: number;
    name?: string;
    escalatingCost?: boolean;
}

export interface ResolvedDustShopEntry {
    shopKey: string;
    item: DustShopCatalogItem;
}

export function resolveDustShopEntry(itemId: string): ResolvedDustShopEntry | null {
    const entries = DUST_SHOP_ITEMS as Record<string, DustShopCatalogItem>;
    const direct = entries[itemId];
    if (direct) {
        return { shopKey: itemId, item: direct };
    }
    for (const [shopKey, item] of Object.entries(entries)) {
        if (item.id === itemId) {
            return { shopKey, item };
        }
    }
    return null;
}

/** Catalog id used by UI, i18n, and upgrade keys (falls back to lookup id). */
export function dustShopCatalogId(itemId: string, item: DustShopCatalogItem): string {
    return item.id ?? itemId;
}
