<script lang="ts">
  import { facade } from '../bus/gameFacade.js';
  import { game } from '../../gameManager.js';
  import type { GameRuntime } from '../types/game.js';
  import { useGameLanguageTick } from '../lib/useGameLanguageTick.svelte.ts';
  import {
    STORAGE_SORT_KEYS,
    STORAGE_SORT_I18N_KEYS,
    getSortButtonClass,
    getSortButtonMeta,
    getSortButtonOrderSymbol,
    getSortButtonPriority,
    sortStackSignature,
    type StorageSortEntry,
    type StorageSortKey,
  } from '../lib/storageSortUtils.js';

  let {
    idPrefix = '',
    sortStack = [],
  }: {
    idPrefix?: string;
    sortStack?: StorageSortEntry[];
  } = $props();

  const { trackGameLanguage } = useGameLanguageTick();

  const LABEL_FALLBACKS: Record<StorageSortKey, string> = {
    pokedex: 'Pokédex',
    level: 'Niveau',
    rarity: 'Rareté',
    hp: 'HP',
    attack: 'ATK',
    spattack: 'ATK Spé.',
    defense: 'DEF',
    spdefense: 'DEF Spé.',
    speed: 'VIT',
    total: 'Total',
    shards: 'Shards',
    shiny: 'Shiny',
  };

  function t(key: string, fallback: string, params?: Record<string, string | number>): string {
    const gm = game as GameRuntime | null;
    if (!gm?.t) return fallback;
    let got = gm.t(key, params);
    if (!got || got === key) got = fallback;
    if (params) {
      for (const [k, v] of Object.entries(params)) {
        got = got.replace(`{${k}}`, String(v));
      }
    }
    return got;
  }

  let i18n = $derived.by(() => {
    trackGameLanguage();
    const labels = Object.fromEntries(
      STORAGE_SORT_KEYS.map((key) => [
        key,
        t(STORAGE_SORT_I18N_KEYS[key], LABEL_FALLBACKS[key]),
      ]),
    ) as Record<StorageSortKey, string>;
    return {
      labels,
      ascending: t('storage.sortAscending', 'croissant'),
      descending: t('storage.sortDescending', 'décroissant'),
    };
  });

  function onSort(key: StorageSortKey): void {
    facade.dispatch({ type: 'SORT_STORAGE', key });
  }

  function sortDirectionLabel(order: 'asc' | 'desc'): string {
    return order === 'asc' ? i18n.ascending : i18n.descending;
  }

  function sortBadgeTitle(priority: number, order: 'asc' | 'desc'): string {
    const direction = sortDirectionLabel(order);
    return t('storage.sortBadgeTitle', `Priorité ${priority}, ${direction}`, {
      priority,
      direction,
    });
  }

  function sortAriaLabel(key: StorageSortKey): string {
    const meta = getSortButtonMeta(sortStack, key);
    const label = i18n.labels[key];
    if (!meta) return label;
    const direction = sortDirectionLabel(meta.order);
    return t('storage.sortButtonAria', `${label}, priorité ${meta.priority}, ${direction}`, {
      label,
      priority: meta.priority,
      direction,
    });
  }
</script>

{#key sortStackSignature(sortStack)}
  <div class="storage-sort-bar">
    {#each STORAGE_SORT_KEYS as key (key)}
      <button
        type="button"
        class="{getSortButtonClass(sortStack, key)} storage-sort-btn"
        id="{idPrefix}sort-{key}"
        aria-label={sortAriaLabel(key)}
        onclick={() => onSort(key)}
      >
        <span class="storage-sort-btn-label">{i18n.labels[key]}</span>
        {#if getSortButtonPriority(sortStack, key)}
          <span
            class="sort-btn-meta"
            aria-hidden="true"
            title={sortBadgeTitle(
              getSortButtonPriority(sortStack, key)!,
              getSortButtonMeta(sortStack, key)?.order ?? 'desc',
            )}
          >
            <span class="sort-btn-priority">{getSortButtonPriority(sortStack, key)}</span>
            <span class="sort-btn-direction">{getSortButtonOrderSymbol(sortStack, key)}</span>
          </span>
        {/if}
      </button>
    {/each}
  </div>
{/key}

<style>
  .storage-sort-bar {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
  }

  :global(button.sort-btn.storage-sort-btn) {
    display: inline-flex !important;
    align-items: center;
    gap: 6px;
  }

  :global(button.sort-btn.storage-sort-btn.active::after),
  :global(button.sort-btn.storage-sort-btn.active.asc::after) {
    content: none !important;
    display: none !important;
  }

  :global(button.sort-btn.storage-sort-btn .storage-sort-btn-label) {
    line-height: 1.2;
    text-transform: uppercase !important;
  }

  :global(button.sort-btn.storage-sort-btn .sort-btn-meta) {
    display: inline-flex !important;
    align-items: center;
    gap: 3px;
    flex-shrink: 0;
    padding: 2px 5px;
    border-radius: 999px;
    background: #ffcb05 !important;
    color: #1a1a1a !important;
    border: 1px solid #8a6d00 !important;
    box-shadow: 0 1px 0 rgba(0, 0, 0, 0.25);
    line-height: 1;
    font-size: 11px;
    font-weight: 800;
    text-transform: none !important;
    visibility: visible !important;
    opacity: 1 !important;
  }

  :global(button.sort-btn.storage-sort-btn .sort-btn-priority),
  :global(button.sort-btn.storage-sort-btn .sort-btn-direction) {
    color: #1a1a1a !important;
    line-height: 1;
  }

  :global(button.sort-btn.storage-sort-btn .sort-btn-priority) {
    min-width: 10px;
    text-align: center;
  }

  :global(button.sort-btn.storage-sort-btn .sort-btn-direction) {
    font-size: 9px;
  }
</style>
