    GameClass.prototype.setLanguage = function (this: ThisGame, lang: string, options: { save?: boolean; silent?: boolean; force?: boolean } = {}): void {
        const next = this.normalizeLanguage(lang);
        const shouldSave = options.save !== false;
        const silent = !!options.silent;
        const force = !!options.force;

        if (!force && this.language === next) {
            this.applyLanguageToMenu();
            if (typeof this.updateZoneSelector === 'function') this.updateZoneSelector();
            refreshCombatUiI18nCache(this);
            refreshAllLocalizedUi.call(this);
            publishLanguageChanged(next);
            this.updateOptionButtons();
            return;
        }

        this.language = next;
        setSaveBootLanguage(next);
        refreshCombatUiI18nCache(this);
        this.applyLanguageToMenu();
        this.updateHeaderSkinOptionsUI();
        this.updateOptionButtons();
        refreshAllLocalizedUi.call(this);
        publishLanguageChanged(next);

        if (shouldSave) this.saveGame();
        if (!silent && typeof toast !== 'undefined' && toast.info) {
            toast.info(this.t('toast.languageTitle'), this.t('toast.languageChanged', { value: this.getLanguageLabel(next) }));
        }
    };

