    GameClass.prototype.setAnimatedSpriteOption = function (this: ThisGame, key: string, value: boolean): void {
        if (!this.animatedSprites || typeof this.animatedSprites !== 'object') {
            this.animatedSprites = { active: false, team: false, pension: false, all: false };
        }
        (this.animatedSprites as Record<string, boolean>)[key] = !!value;
        if (key === 'all' && value) {
            this.animatedSprites.active = false;
            this.animatedSprites.team = false;
            this.animatedSprites.pension = false;
        }
        if (key !== 'all' && value) {
            this.animatedSprites.all = false;
        }
        globalThis.POKETIME_ANIMATED_SPRITES_CONFIG = this.animatedSprites;
        clearCardSpriteUrlCache();
        if (typeof toast !== 'undefined') {
            toast.info(this.t('toast.animatedSpritesTitle'), this.t('toast.animatedSpritesChanged'));
        }
        this.updateTeamDisplay();
        this.updatePensionDisplay();
        this.updateStorageDisplay();
        if (typeof this.updateCombatDisplay === 'function') this.updateCombatDisplay();
        this.updateOptionButtons();
        this.saveGame();
    };

