        this.optimalMoveSelection = !this.optimalMoveSelection;
        const optimalCheck = document.getElementById('autoOptimalMovesCheck') as HTMLInputElement | null;
        if (optimalCheck) optimalCheck.checked = this.optimalMoveSelection;
        this.updateOptionButtons();
