    GameClass.prototype.colorToRgbTriplet = function (this: ThisGame, colorValue: string, fallback: string = '44, 62, 80'): string {
        if (typeof colorValue !== 'string') return fallback;
        const color = colorValue.trim();

        const hexMatch = color.match(/^#([0-9a-f]{3}|[0-9a-f]{6})$/i);
        if (hexMatch) {
            let hex = hexMatch[1];
            if (!hex) return fallback;
            if (hex.length === 3) {
                hex = hex.split('').map((c) => c + c).join('');
            }
            const intVal = parseInt(hex, 16);
            const r = (intVal >> 16) & 255;
            const g = (intVal >> 8) & 255;
            const b = intVal & 255;
            return `${r}, ${g}, ${b}`;
        }

        const rgbMatch = color.match(/^rgba?\(\s*(\d{1,3})\s*[, ]\s*(\d{1,3})\s*[, ]\s*(\d{1,3})/i);
        if (rgbMatch) {
            const clamp = (n: string) => Math.max(0, Math.min(255, Number(n) || 0));
            const r = rgbMatch[1];
            const g = rgbMatch[2];
            const b = rgbMatch[3];
            if (r == null || g == null || b == null) return fallback;
            return `${clamp(r)}, ${clamp(g)}, ${clamp(b)}`;
        }

        return fallback;
    };

    GameClass.prototype.sampleBottomImageRgbTriplet = function (this: SettingsGame, imagePath: string, fallback: string = '44, 62, 80'): Promise<string> {
        if (typeof imagePath !== 'string' || !imagePath.trim()) {
            return Promise.resolve(fallback);
        }

        // Note: avec un lancement direct en file://, la lecture pixels via canvas
        // peut ?tre bloqu?e (origine opaque). On retourne le fallback pour éviter
        // un comportement instable.
        if (typeof window !== 'undefined' && window.location && window.location.protocol === 'file:') {
            if (!this._headerSkinSamplingFileWarned) {
                this._headerSkinSamplingFileWarned = true;
                debugWarn('[HeaderSkin] Pixel sampling disabled on file://. Use http://localhost to enable accurate sampling.');
            }
            return Promise.resolve(fallback);
        }

        const normalizedPath = imagePath.trim();
        const cacheKey = `${normalizedPath}::v4`;
        const fadeCache = headerSkinFadeCache(this);
        const cachedRgb = fadeCache[cacheKey];
        if (cachedRgb) {
            return Promise.resolve(cachedRgb);
        }

        return new Promise((resolve) => {
            const img = new Image();
            try {
                const parsedUrl = new URL(normalizedPath, window.location.href);
                const isHttp = parsedUrl.protocol === 'http:' || parsedUrl.protocol === 'https:';
                const isCrossOrigin = parsedUrl.origin !== window.location.origin;
                if (isHttp && isCrossOrigin) img.crossOrigin = 'anonymous';
            } catch (_e: unknown) {
                // Ignore URL parsing failures and continue without crossOrigin.
            }
            img.onload = () => {
                try {
                    const srcW = img.naturalWidth || img.width || 0;
                    const srcH = img.naturalHeight || img.height || 0;
                    if (!srcW || !srcH) {
                        resolve(fallback);
                        return;
                    }

                    const collectPixels = (bandRatio: number, minBandPx: number, maxCanvasH: number): Array<{ r: number; g: number; b: number; luminance: number; saturation: number }> => {
                        const bandHeight = Math.max(minBandPx, Math.floor(srcH * bandRatio));
                        const canvasW = Math.min(256, srcW);
                        const canvasH = Math.min(maxCanvasH, bandHeight);
                        const canvas = document.createElement('canvas');
                        canvas.width = canvasW;
                        canvas.height = canvasH;
                        const ctx = canvas.getContext('2d', { willReadFrequently: true });
                        if (!ctx) return [];

                        ctx.drawImage(
                            img,
                            0,
                            Math.max(0, srcH - bandHeight),
                            srcW,
                            bandHeight,
                            0,
                            0,
                            canvasW,
                            canvasH
                        );

                        const data = ctx.getImageData(0, 0, canvasW, canvasH).data;
                        const extracted: Array<{ r: number; g: number; b: number; luminance: number; saturation: number }> = [];
                        for (let i = 0; i < data.length; i += 8) {
                            const alpha = (data[i + 3] ?? 0) / 255;
                            if (alpha <= 0.05) continue;
                            const r = data[i] ?? 0;
                            const g = data[i + 1] ?? 0;
                            const b = data[i + 2] ?? 0;

                            const maxCh = Math.max(r, g, b);
                            const minCh = Math.min(r, g, b);
                            const saturation = maxCh === 0 ? 0 : (maxCh - minCh) / maxCh;
                            const luminance = (0.2126 * r) + (0.7152 * g) + (0.0722 * b);

                            // Ignore les highlights chauds/vifs qui biaisent le fondu.
                            if (luminance > 170 && saturation > 0.22) continue;

                            extracted.push({ r, g, b, luminance, saturation });
                        }
                        return extracted;
                    };

                    let pixels = collectPixels(0.04, 4, 64);
                    if (pixels.length < 24) {
                        pixels = collectPixels(0.18, 10, 96);
                    }

                    if (pixels.length === 0) {
                        resolve(fallback);
                        return;
                    }

                    const sortedLum = pixels.map((p) => p.luminance).sort((a, b) => a - b);
                    const darkCut = sortedLum[Math.max(0, Math.floor(sortedLum.length * 0.36))] ?? 0;
                    const midCut = sortedLum[Math.max(0, Math.floor(sortedLum.length * 0.50))] ?? 0;

                    let corePixels = pixels.filter((p) => p.luminance <= darkCut && p.saturation <= 0.7);
                    if (corePixels.length < Math.max(20, Math.floor(pixels.length * 0.10))) {
                        corePixels = pixels.filter((p) => p.luminance <= midCut);
                    }
                    if (corePixels.length < Math.max(16, Math.floor(pixels.length * 0.08))) {
                        corePixels = pixels;
                    }

                    let weightedR = 0;
                    let weightedG = 0;
                    let weightedB = 0;
                    let totalWeight = 0;

                    for (const p of corePixels) {
                        const darkness = 1 - (p.luminance / 255);
                        const satPenalty = 1 - (0.40 * p.saturation);
                        const weight = Math.max(0.05, darkness * darkness * satPenalty);
                        weightedR += p.r * weight;
                        weightedG += p.g * weight;
                        weightedB += p.b * weight;
                        totalWeight += weight;
                    }

                    if (totalWeight <= 0) {
                        resolve(fallback);
                        return;
                    }

                    const r = Math.round(weightedR / totalWeight);
                    const g = Math.round(weightedG / totalWeight);
                    const b = Math.round(weightedB / totalWeight);
                    const rgb = `${r}, ${g}, ${b}`;
                    headerSkinFadeCache(this)[cacheKey] = rgb;
                    resolve(rgb);
                } catch (_error: unknown) {
                    resolve(fallback);
                }
            };
            img.onerror = () => resolve(fallback);
            img.src = normalizedPath;
        });
    };

    GameClass.prototype.normalizeHeaderSkinState = function (this: ThisGame): void {
        const defaultId = defaultHeaderSkinId();
        if (!Array.isArray(this.unlockedHeaderSkins)) this.unlockedHeaderSkins = [];
        if (!this.unlockedHeaderSkins.includes(defaultId)) this.unlockedHeaderSkins.push(defaultId);

        const skins = headerSkinsRecord();
        if (skins) {
            this.unlockedHeaderSkins = this.unlockedHeaderSkins
                .filter((id: string, index: number, arr: string[]) => !!skins[id] && arr.indexOf(id) === index);
            if (!this.unlockedHeaderSkins.includes(defaultId)) this.unlockedHeaderSkins.push(defaultId);
            pruneInvalidUnlockedHeaderSkins(this, skins);
        }

        if (typeof this.selectedHeaderSkin !== 'string' || !this.selectedHeaderSkin) {
            this.selectedHeaderSkin = defaultId;
        }
    };

    GameClass.prototype.refreshUnlockedHeaderSkins = function (this: ThisGame, options: { silent?: boolean } = {}): boolean {
        const silent = options.silent !== false;
        const skins = headerSkinsRecord();
        if (!skins) return false;
        this.normalizeHeaderSkinState();
        const ctx = headerSkinUnlockContext(this);
        let unlockedAny = false;

        Object.entries(skins).forEach(([skinId, skinDef]) => {
            if (!skinDef) return;
            if (!isHeaderSkinUnlocked(ctx, skinDef)) return;
            if (this.unlockedHeaderSkins.includes(skinId)) return;
            this.unlockedHeaderSkins.push(skinId);
            unlockedAny = true;
            if (skinId !== HEADER_SKIN_ALWAYS_UNLOCKED_ID) {
                notifyHeaderSkinUnlocked(this, skinDef, silent);
            }
        });

        return unlockedAny;
    };

    GameClass.prototype.refreshUnlockedHeaderSkinsFromAchievements = function (this: ThisGame, options: { silent?: boolean } = {}): boolean {
        return this.refreshUnlockedHeaderSkins(options);
    };

    GameClass.prototype.unlockHeaderSkinByAchievement = function (this: ThisGame, achievementId: string, options: { silent?: boolean } = {}): boolean {
        const skins = headerSkinsRecord();
        if (!achievementId || !skins) return false;
        this.normalizeHeaderSkinState();
        const silent = !!options.silent;
        let unlockedAny = false;

        Object.entries(skins).forEach(([skinId, skinDef]) => {
            if (!skinDef) return;
            const cond = resolveSkinUnlockCondition(skinDef);
            if (!cond || cond.type !== 'achievement' || cond.id !== achievementId) return;
            if (this.unlockedHeaderSkins.includes(skinId)) return;
            this.unlockedHeaderSkins.push(skinId);
            unlockedAny = true;
            notifyHeaderSkinUnlocked(this, skinDef, silent);
        });

        if (unlockedAny) this.updateHeaderSkinOptionsUI();
        return unlockedAny;
    };

    GameClass.prototype.unlockHeaderSkinsByStoryQuest = function (this: ThisGame, storyQuestId: string, options: { silent?: boolean } = {}): boolean {
        const skins = headerSkinsRecord();
        if (!storyQuestId || !skins) return false;
        this.normalizeHeaderSkinState();
        const silent = !!options.silent;
        let unlockedAny = false;

        Object.entries(skins).forEach(([skinId, skinDef]) => {
            if (!skinDef) return;
            const cond = resolveSkinUnlockCondition(skinDef);
            if (!cond || cond.type !== 'storyQuest' || cond.id !== storyQuestId) return;
            if (!isHeaderSkinUnlocked(headerSkinUnlockContext(this), skinDef)) return;
            if (this.unlockedHeaderSkins.includes(skinId)) return;
            this.unlockedHeaderSkins.push(skinId);
            unlockedAny = true;
            notifyHeaderSkinUnlocked(this, skinDef, silent);
        });

        if (unlockedAny) this.updateHeaderSkinOptionsUI();
        return unlockedAny;
    };

    GameClass.prototype.applyHeaderSkinVisual = function (this: ThisGame, skinId: string): void {
        const header = document.querySelector('.header');
        const gameContainer = document.querySelector('.game-container');
        const skins = headerSkinsRecord();
        if (!(header instanceof HTMLElement) || !skins) return;
        const defaultId = defaultHeaderSkinId();
        const skin = skins[skinId] ?? skins[defaultId];
        if (!skin) return;
        // Tous les skins (y compris classic_lab) : même pipeline thème (variables CSS, fond global, modals, etc.)

        const colors = skin.colors;
        const imagePath = (typeof skin.imagePath === 'string') ? skin.imagePath.trim() : '';
        const fadeWhiten = getHeaderSkinFadeWhiten();
        const fadeRgbRaw = this.colorToRgbTriplet(colors.fadeFallback || colors.bg || colors.panelBg || '#2c3e50');
        const fadeRgb = brightenHeaderFadeRgbTriplet(fadeRgbRaw, fadeWhiten);
        const resolvedTitleColor = resolveHeaderSkinTitleColor(this, colors, fadeRgb);

        header.style.setProperty('--header-skin-bg', colors.bg || '#947864');
        header.style.setProperty('--header-skin-border', colors.border || '#5d4a3e');
        header.style.setProperty('--header-skin-panel-bg', colors.panelBg || '#bec3c6');
        header.style.setProperty('--header-skin-panel-border', colors.panelBorder || '#3b3b3b');
        header.style.setProperty('--header-skin-panel-bg-themed', colors.panelBgThemed || 'rgba(15, 23, 42, 0.56)');
        header.style.setProperty('--header-skin-panel-border-themed', colors.panelBorderThemed || colors.panelBorder || '#3b3b3b');
        header.style.setProperty('--header-skin-title-color', resolvedTitleColor);
        header.style.setProperty('--header-skin-overlay', colors.overlay || 'rgba(0,0,0,0)');
        header.style.setProperty('--header-skin-glow', colors.glow || 'rgba(0,0,0,0.25)');
        const cssUrl = imagePath ? `url("../${imagePath}")` : 'none';
        header.style.setProperty('--header-skin-image', cssUrl);
        header.classList.add('header-theme-active');

        if (gameContainer instanceof HTMLElement) {
            gameContainer.style.setProperty('--header-skin-container-image', cssUrl);
            gameContainer.style.setProperty('--header-skin-fade-rgb', fadeRgb);
            gameContainer.style.setProperty('--header-panel-opacity', String(this.headerPanelOpacity ?? 0.8));
            gameContainer.classList.add('has-themed-header-bg');

            if (imagePath) {
                const expectedSkinId = skin.id;
                void this.sampleBottomImageRgbTriplet(imagePath, fadeRgbRaw).then((sampledRgb: string) => {
                    if (this.selectedHeaderSkin !== expectedSkinId) return;
                    const currentContainer = document.querySelector('.game-container');
                    if (!(currentContainer instanceof HTMLElement) || !currentContainer.classList.contains('has-themed-header-bg')) return;
                    const rgb = brightenHeaderFadeRgbTriplet(sampledRgb || fadeRgbRaw, fadeWhiten);
                    currentContainer.style.setProperty('--header-skin-fade-rgb', rgb);
                    document.body.style.setProperty('--header-skin-fade-rgb', rgb);
                    const hdr = document.querySelector('.header');
                    const skinRef = skins[expectedSkinId];
                    if (hdr instanceof HTMLElement && skinRef) {
                        const tc = resolveHeaderSkinTitleColor(this, skinRef.colors, rgb);
                        hdr.style.setProperty('--header-skin-title-color', tc);
                        document.body.style.setProperty('--header-skin-title-color', tc);
                    }
                    this.syncHeaderThemeUiReadabilityBoost();
                });
            }
        }

        /* Appliquer les variables au body pour que modals, toasts, tooltips héritent du skin */
        document.body.style.setProperty('--header-skin-fade-rgb', fadeRgb);
        document.body.style.setProperty('--header-skin-title-color', resolvedTitleColor);
        document.body.style.setProperty('--header-panel-opacity', String(this.headerPanelOpacity ?? 0.8));
        document.body.classList.add('has-themed-header-bg');
        this.syncHeaderThemeUiReadabilityBoost();
    };

    GameClass.prototype.updateHeaderPanelOpacitySliderLabel = function (this: ThisGame, rawValue: string | number): void {
        const pct = Number(rawValue) || 25;
        const el = document.getElementById('optHeaderPanelOpacityValue');
        if (el) el.textContent = `${pct}%`;
    };

    GameClass.prototype.setHeaderPanelOpacityFromSlider = function (this: ThisGame, rawValue: string | number): void {
        const pct = Number(rawValue) || 25;
        const value = Math.min(0.8, Math.max(0.05, pct / 100));
        this.headerPanelOpacity = value;
        const gameContainer = document.querySelector('.game-container');
        if (gameContainer instanceof HTMLElement) gameContainer.style.setProperty('--header-panel-opacity', String(value));
        document.body.style.setProperty('--header-panel-opacity', String(value));
        this.updateHeaderPanelOpacitySliderLabel(Math.round(value * 100));
        this.syncHeaderThemeUiReadabilityBoost();
    };

    GameClass.prototype.updateHeaderSkinOptionsUI = function (this: ThisGame): void {
        const select = getById<HTMLSelectElement>('optHeaderSkinSelect');
        const desc = getById('optHeaderSkinDesc');
        const unlockCounter = getById('optHeaderSkinUnlock');
        const skins = headerSkinsRecord();
        if (!select || !skins) return;

        const previousSelected = this.selectedHeaderSkin;
        this.normalizeHeaderSkinState();
        this.refreshUnlockedHeaderSkins({ silent: true });

        const defaultId = defaultHeaderSkinId();
        if (!this.unlockedHeaderSkins.includes(this.selectedHeaderSkin)) {
            this.selectedHeaderSkin = defaultId;
        }
        if (this.selectedHeaderSkin !== previousSelected) {
            this.applyHeaderSkinVisual(this.selectedHeaderSkin);
        }

        select.innerHTML = '';
        Object.values(skins).forEach((skin) => {
            if (!skin?.id) return;
            const skinId = skin.id;
            const skinName = skin.name;
            const unlocked = this.unlockedHeaderSkins.includes(skinId);
            const option = document.createElement('option');
            option.value = skinId;
            option.textContent = unlocked ? skinName : `' ${skinName}`;
            option.disabled = !unlocked;
            if (skinId === this.selectedHeaderSkin) option.selected = true;
            select.appendChild(option);
        });

        if (unlockCounter) {
            unlockCounter.textContent = this.t('menu.unlockCounter', {
                owned: this.unlockedHeaderSkins.length,
                total: Object.keys(skins).length
            });
        }

        const activeSkinId = select.value || this.selectedHeaderSkin || defaultId;
        const activeSkin = skins[activeSkinId] ?? skins[defaultId];
        if (desc && activeSkin) {
            const unlockLabel = getHeaderSkinUnlockLabel(headerSkinUnlockContext(this), activeSkin);
            desc.textContent = `${activeSkin.description}  ${unlockLabel}`;
        }
    };

    GameClass.prototype.selectHeaderSkin = function (this: ThisGame, skinId: string, options: { save?: boolean; silent?: boolean } = {}): void {
        const save = options.save !== false;
        const silent = !!options.silent;
        if (!headerSkinsRecord()) return;

        this.normalizeHeaderSkinState();
        this.refreshUnlockedHeaderSkins({ silent: true });

        const defaultId = defaultHeaderSkinId();
        const targetId = (typeof skinId === 'string' && skinId) ? skinId : defaultId;
        if (!this.unlockedHeaderSkins.includes(targetId)) {
            this.selectedHeaderSkin = defaultId;
            if (!silent && typeof toast !== 'undefined' && toast.warning) {
                toast.warning(this.t('toast.skinLockedTitle'), this.t('toast.skinLockedBody'));
            }
        } else {
            this.selectedHeaderSkin = targetId;
            if (!this.unlockedHeaderSkins.includes(targetId)) {
                this.unlockedHeaderSkins.push(targetId);
            }
        }

        this.applyHeaderSkinVisual(this.selectedHeaderSkin);
        this.updateHeaderSkinOptionsUI();
        if (save && typeof this.saveGame === 'function') this.saveGame();
    }

