/**
 * @file towerGenMasteryRanges.ts
 * National dex generation ranges for Battle Tower defeat mastery (Gen 1–9).
 */

import { EGG_DEX_REGION_THRESHOLDS } from '../../constants/balance/eggRegionMap.js';

export interface TowerGenDexRange {
    gen: number;
    fromDex: number;
    toDex: number;
}

/** Gen 1–9 dex id ranges derived from EGG_DEX_REGION_THRESHOLDS. */
export const TOWER_GEN_DEX_RANGES: readonly TowerGenDexRange[] = EGG_DEX_REGION_THRESHOLDS.map(
    (threshold, index) => {
        const prevMax = index > 0 ? (EGG_DEX_REGION_THRESHOLDS[index - 1]?.maxDex ?? 0) : 0;
        return {
            gen: index + 1,
            fromDex: prevMax + 1,
            toDex: threshold.maxDex,
        };
    },
);

function hasAllInRange(
    defeated: Record<string | number, boolean>,
    fromId: number,
    toId: number,
): boolean {
    for (let id = fromId; id <= toId; id++) {
        if (!defeated[id]) return false;
    }
    return true;
}

/** Highest completed generation mastery (0–9) from towerDexDefeated flags. */
export function getTowerGenMasteryFromDefeated(
    defeated: Record<string | number, boolean>,
): number {
    let mastery = 0;
    for (const range of TOWER_GEN_DEX_RANGES) {
        if (mastery < range.gen && hasAllInRange(defeated, range.fromDex, range.toDex)) {
            mastery = range.gen;
        } else if (mastery < range.gen) {
            break;
        }
    }
    return mastery;
}
