/**
 * Bridge for RocketContractSelectModal — legacy rocketDisplay opens/closes via these hooks.
 */

import type { RocketContractModalSnapshot } from '../bus/snapshots.js';

type OpenFn = (snapshot: RocketContractModalSnapshot) => void;
type CloseFn = () => void;

let openFn: OpenFn = () => {};
let closeFn: CloseFn = () => {};

export function setRocketContractOpen(fn: OpenFn): void {
  openFn = fn;
}

export function setRocketContractClose(fn: CloseFn): void {
  closeFn = fn;
}

export function openRocketContractSelectModal(snapshot: RocketContractModalSnapshot): void {
  openFn(snapshot);
}

export function closeRocketContractSelectModal(): void {
  closeFn();
}
