/// <reference types="svelte" />
/**
 * Store: ui — modals / tabs (see CARTOGRAPHY.md)
 */

import { facade } from '@bus/facade';
import { GameEventType as Evt } from '../bus/events.js';

class UiStore {
  openModals = $state<Set<string>>(new Set());
}

export const ui = new UiStore();

function syncModal(modalId: string, open: boolean): void {
  const next = new Set(ui.openModals);
  if (open) next.add(modalId);
  else next.delete(modalId);
  ui.openModals = next;
}

facade.subscribe(Evt.MODAL_OPENED, (evt) => {
  if (evt.type === Evt.MODAL_OPENED) syncModal(evt.modalId, true);
});

facade.subscribe(Evt.MODAL_CLOSED, (evt) => {
  if (evt.type === Evt.MODAL_CLOSED) syncModal(evt.modalId, false);
});

export function isModalOpen(modalId: string): boolean {
  return ui.openModals.has(modalId);
}
