/**
 * @file src/lib/roamerIncenseCombatIndicator.ts
 * Combat zone indicator when Roamer Incense timed boost is active.
 */

import { formatBoostTimeLeft } from '../../formatters.ts';
import { getAllItem } from '../ui/uiItems.ts';
import { uiMaybeLocalizeItemName } from '../ui/i18n.ts';
import type { GameRuntime } from '../types/game.js';

export const ROAMER_INCENSE_ITEM_KEY = 'roamer_incense_30m';
const ROAMER_BOOST_TYPE = 'roamerSpawn';

export interface RoamerIncenseCombatIndicator {
  visible: boolean;
  spriteUrl: string;
  spriteAlt: string;
  tooltipTitle: string;
  tooltipBody: string;
}

export const EMPTY_ROAMER_INCENSE_COMBAT_INDICATOR: RoamerIncenseCombatIndicator = {
  visible: false,
  spriteUrl: '',
  spriteAlt: '',
  tooltipTitle: '',
  tooltipBody: '',
};

const indicatorListeners = new Set<() => void>();

export function subscribeRoamerIncenseIndicatorChanged(listener: () => void): () => void {
  indicatorListeners.add(listener);
  return () => indicatorListeners.delete(listener);
}

export function notifyRoamerIncenseIndicatorChanged(): void {
  indicatorListeners.forEach((listener) => listener());
}

function itemDisplayName(game: GameRuntime, itemKey: string): string {
  const itemDef = getAllItem(itemKey);
  const fallback = itemDef?.name ?? 'Encens Roamer';
  if (typeof game.getLocalizedItemName === 'function') {
    return game.getLocalizedItemName(itemKey, fallback, itemDef ?? undefined);
  }
  return uiMaybeLocalizeItemName(game, itemDef, itemKey, fallback);
}

function boostTimeLeftLabel(game: GameRuntime, remainingMs: number): string {
  const time = formatBoostTimeLeft(remainingMs, {
    minuteShort: game.t?.('offline.minuteShort') ?? 'min',
    secondShort: game.t?.('offline.secondShort') ?? 's',
  });
  return game.t?.('combatUi.roamerIncenseTimeLeft', { time })
    ?? `${time} restantes`;
}

export function buildRoamerIncenseCombatIndicator(
  game: GameRuntime,
  now = Date.now(),
): RoamerIncenseCombatIndicator {
  const itemDef = getAllItem(ROAMER_INCENSE_ITEM_KEY);
  const spriteUrl = itemDef?.img ?? '';
  const spriteAlt = itemDisplayName(game, ROAMER_INCENSE_ITEM_KEY);

  const boost = (game.activeBoosts || []).find(
    (entry) => entry?.type === ROAMER_BOOST_TYPE && Number(entry.endTime) > now,
  );
  if (!boost) {
    return { ...EMPTY_ROAMER_INCENSE_COMBAT_INDICATOR };
  }

  const remainingMs = Math.max(0, Number(boost.endTime) - now);
  return {
    visible: true,
    spriteUrl,
    spriteAlt,
    tooltipTitle: spriteAlt,
    tooltipBody: boostTimeLeftLabel(game, remainingMs),
  };
}

export function activeRoamerBoostExpired(boost: { type?: string }): boolean {
  return boost?.type === ROAMER_BOOST_TYPE;
}
