/**
 * Storage grid lazy expansion — one chunk per animation frame, merges targets.
 * Only grows visibleCount; windowStart is driven by scroll sync in StorageGrid.
 */

export type StorageExpansionCallbacks = {
    getCreaturesLength: () => number;
    getWindowStart: () => number;
    getVisibleCount: () => number;
    setVisibleCount: (value: number) => void;
    getExpansionTargetEnd: () => number;
    setExpansionTargetEnd: (value: number) => void;
    onBatchComplete?: () => void;
};

export type StorageExpansionParams = StorageExpansionCallbacks & {
    batch: number;
    maxDom: number;
    chunk: number;
};

let expansionRafId: number | null = null;
let activeParams: StorageExpansionParams | null = null;

function scheduleExpansionFrame(): void {
    if (expansionRafId != null) return;
    expansionRafId = requestAnimationFrame(runExpansionChunk);
}

function finishExpansion(params: StorageExpansionParams): void {
    activeParams = null;
    params.onBatchComplete?.();
}

function runExpansionChunk(): void {
    expansionRafId = null;
    const params = activeParams;
    if (!params) return;

    const len = params.getCreaturesLength();
    const windowStart = params.getWindowStart();
    let visibleCount = params.getVisibleCount();
    const visibleEnd = windowStart + visibleCount;

    if (visibleEnd >= len) {
        finishExpansion(params);
        return;
    }

    const targetEnd = params.getExpansionTargetEnd();

    if (visibleEnd >= targetEnd) {
        finishExpansion(params);
        return;
    }

    const maxVisible = Math.min(params.maxDom, len - windowStart);
    const nextEnd = Math.min(visibleEnd + params.chunk, targetEnd, len);
    visibleCount = Math.min(nextEnd - windowStart, maxVisible);

    params.setVisibleCount(visibleCount);

    if (windowStart + visibleCount >= targetEnd || windowStart + visibleCount >= len) {
        finishExpansion(params);
        return;
    }

    scheduleExpansionFrame();
}

/** Request expansion toward currentEnd + batch; merges with an in-flight target. */
export function requestStorageExpansion(params: StorageExpansionParams): void {
    const len = params.getCreaturesLength();
    const visibleEnd = params.getWindowStart() + params.getVisibleCount();
    if (visibleEnd >= len) return;

    const newTarget = Math.min(visibleEnd + params.batch, len);
    const mergedTarget = Math.max(params.getExpansionTargetEnd(), newTarget);
    params.setExpansionTargetEnd(mergedTarget);

    activeParams = params;
    scheduleExpansionFrame();
}

/** Cancel in-flight expansion (e.g. roster reset). */
export function cancelStorageExpansion(): void {
    if (expansionRafId != null) {
        cancelAnimationFrame(expansionRafId);
        expansionRafId = null;
    }
    activeParams = null;
}

/** @internal Vitest only */
export function resetStorageGridExpansionForTests(): void {
    cancelStorageExpansion();
}

/** @internal Vitest only */
export function runStorageExpansionChunkForTests(): void {
    runExpansionChunk();
}

/** @internal Vitest only */
export function isStorageExpansionActiveForTests(): boolean {
    return activeParams != null || expansionRafId != null;
}
