export interface SynergyProgressPart {
  type: string;
  current: number;
  required: number;
}

export type SpeciesPickMode = 'any' | 'all';

export interface SpeciesRequirementDisplay {
  pickMode: SpeciesPickMode;
  requirementLabel: string;
  separator: string;
  tooltipText: string;
}

export interface SynergySpeciesProgress {
  species: string[];
  current: number;
  required: number;
  pickMode: SpeciesPickMode;
  requirementLabel: string;
  separator: string;
  matchedSpecies: string[];
}

export interface SynergyCardView {
  id: string;
  regionId: string;
  name: string;
  shortDesc: string;
  isActive: boolean;
  isRegionLocked: boolean;
  progressPercent: number;
  allRequired: boolean;
  progressParts: SynergyProgressPart[] | null;
  speciesProgress: SynergySpeciesProgress | null;
  simpleProgress: { current: number; required: number } | null;
  types: string[];
  tooltipTitle: string;
  tooltipDesc: string;
}

export interface SynergyRegionTabView {
  regionId: string;
  label: string;
  locked: boolean;
  activeCount: number;
  totalCount: number;
}

export interface BuildSynergyCardsOptions {
  regionId?: string;
}

const REGION_LABELS: Record<string, { fr: string; en: string }> = {
  kanto: { fr: 'Kanto', en: 'Kanto' },
  johto: { fr: 'Johto', en: 'Johto' },
  hoenn: { fr: 'Hoenn', en: 'Hoenn' },
  sinnoh: { fr: 'Sinnoh', en: 'Sinnoh' },
  unova: { fr: 'Unova', en: 'Unova' },
  kalos: { fr: 'Kalos', en: 'Kalos' },
  alola: { fr: 'Alola', en: 'Alola' },
  galar: { fr: 'Galar', en: 'Galar' },
  paldea: { fr: 'Paldea', en: 'Paldea' },
};

function synergyLocale(gm: GameRuntime | null): Record<string, Record<string, string>> {
  const lang =
    gm && typeof gm.normalizeLanguage === 'function'
      ? gm.normalizeLanguage(gm.language)
      : gm?.language;
  const i18n = TEAM_SYNERGIES_I18N as Record<string, Record<string, Record<string, string>>>;
  return i18n?.[lang ?? 'en'] ?? i18n?.en ?? {};
}

function localizedSynergyName(
  synergyId: string,
  synergy: TeamSynergyDef,
  loc: Record<string, Record<string, string>>,
): string {
  return loc[synergyId]?.name || synergy.name;
}

function localizedSynergyMessage(
  synergyId: string,
  synergy: TeamSynergyDef,
  loc: Record<string, Record<string, string>>,
): string {
  return loc[synergyId]?.message || synergy.message;
}

function teamMembersFromSnapshots(playerTeam: CreatureSnapshot[]): TeamSynergyMember[] {
  return playerTeam
    .filter(Boolean)
    .map((c) => ({
      name: c.name,
      type: c.type,
      secondaryType: c.secondaryType,
    }));
}

function countSpeciesOnTeam(team: TeamSynergyMember[], species: string[]): number {
  const set = new Set(species);
  let n = 0;
  for (let i = 0; i < team.length; i++) {
    const c = team[i];
    if (c?.name && set.has(c.name)) n++;
  }
  return n;
}

function matchedSpeciesOnTeam(team: TeamSynergyMember[], species: string[]): string[] {
  const set = new Set(species);
  const matched = new Set<string>();
  for (let i = 0; i < team.length; i++) {
    const c = team[i];
    if (c?.name && set.has(c.name)) matched.add(c.name);
  }
  return [...matched];
}

function translateModal(gm: GameRuntime, key: string, fallback: string): string {
  const got = gm.t(key);
  return got && got !== key ? got : fallback;
}

export function formatSpeciesRequirement(
  rule: { species: string[]; minCount: number },
  gm: GameRuntime,
): SpeciesRequirementDisplay {
  const minCount = Math.max(1, Math.floor(Number(rule.minCount) || 1));
  const species = rule.species;
  const lang =
    typeof gm.normalizeLanguage === 'function' ? gm.normalizeLanguage(gm.language) : gm.language;
  const pickMode: SpeciesPickMode = minCount >= species.length ? 'all' : 'any';
  const orSep = translateModal(gm, 'modal.synergyOr', lang === 'fr' ? 'OU' : 'OR');
  const andSep = translateModal(gm, 'modal.synergyAnd', lang === 'fr' ? 'ET' : 'AND');
  const separator = pickMode === 'all' ? andSep : orSep;

  let requirementLabel: string;
  if (pickMode === 'all') {
    const tpl = translateModal(gm, 'modal.synergyPickAll', lang === 'fr' ? 'Les {count}' : 'All {count} required');
    requirementLabel = tpl.replace('{count}', String(minCount));
  } else if (minCount === 1) {
    requirementLabel = translateModal(gm, 'modal.synergyPickOne', lang === 'fr' ? '1 parmi' : 'Any 1 of');
  } else {
    const tpl = translateModal(gm, 'modal.synergyPickN', lang === 'fr' ? '{count} parmi' : '{count} of any');
    requirementLabel = tpl.replace('{count}', String(minCount));
  }

  const tooltipText = `${requirementLabel} : ${species.join(` ${separator} `)}`;
  return { pickMode, requirementLabel, separator, tooltipText };
}

function computeSynergyProgress(
  synergy: TeamSynergyDef,
  team: TeamSynergyMember[],
  gm: GameRuntime,
): Pick<
  SynergyCardView,
  'isActive' | 'progressPercent' | 'allRequired' | 'progressParts' | 'speciesProgress' | 'simpleProgress'
> {
  const typeCounts = countTeamTypesForSynergy(team, synergy);
  const allRequired = !!synergy.all_required;
  const synTypes = synergy.types ?? [];
  const minCount = synergy.min_count ?? 0;
  const speciesRule = synergy.requiredSpecies;

  let speciesProgress: SynergySpeciesProgress | null = null;
  if (speciesRule) {
    const current = countSpeciesOnTeam(team, speciesRule.species);
    const speciesDisplay = formatSpeciesRequirement(speciesRule, gm);
    speciesProgress = {
      species: speciesRule.species,
      current,
      required: speciesRule.minCount,
      pickMode: speciesDisplay.pickMode,
      requirementLabel: speciesDisplay.requirementLabel,
      separator: speciesDisplay.separator,
      matchedSpecies: matchedSpeciesOnTeam(team, speciesRule.species),
    };
  }

  let progressParts: SynergyProgressPart[] | null = null;
  let simpleProgress: { current: number; required: number } | null = null;
  let progressPercent = 0;

  if (synTypes.length > 0 && minCount > 0) {
    if (allRequired) {
      const totalReq = synTypes.length * minCount;
      const totalCur = synTypes.reduce(
        (sum, t) => sum + Math.min(typeCounts[t] || 0, minCount),
        0,
      );
      progressPercent = totalReq > 0 ? (totalCur / totalReq) * 100 : 0;
      progressParts = synTypes.map((t) => ({
        type: t,
        current: typeCounts[t] || 0,
        required: minCount,
      }));
    } else {
      let currentMax = 0;
      for (const t of synTypes) {
        const count = typeCounts[t] || 0;
        if (count > currentMax) currentMax = count;
      }
      const displayCount = Math.min(currentMax, minCount);
      progressPercent = minCount > 0 ? (displayCount / minCount) * 100 : 0;
      simpleProgress = { current: displayCount, required: minCount };
    }
  } else if (speciesProgress) {
    progressPercent =
      speciesProgress.required > 0
        ? (Math.min(speciesProgress.current, speciesProgress.required) / speciesProgress.required) * 100
        : 0;
  }

  const isActive = isSynergyActiveForTeam(synergy, team, gm);
  if (isActive) progressPercent = 100;

  return {
    isActive,
    progressPercent,
    allRequired,
    progressParts,
    speciesProgress,
    simpleProgress,
  };
}

export function regionLabel(gm: GameRuntime | null, regionId: string): string {
  const labels = REGION_LABELS[regionId];
  if (!labels) return regionId;
  const lang =
    gm && typeof gm.normalizeLanguage === 'function'
      ? gm.normalizeLanguage(gm.language)
      : gm?.language;
  return lang === 'fr' ? labels.fr : labels.en;
}

function synergyLanguage(gm: GameRuntime | null): string {
  return gm && typeof gm.normalizeLanguage === 'function'
    ? gm.normalizeLanguage(gm.language)
    : gm?.language ?? 'en';
}

export function buildSynergyRegionLockedTooltip(
  gm: GameRuntime | null,
  regionId: string,
): string {
  const name = regionLabel(gm, regionId);
  const lang = synergyLanguage(gm);
  const key = 'tooltip.synergyRegionLocked';
  const tpl = gm?.t?.(key);
  if (tpl && tpl !== key) return tpl.replace('{region}', name);
  return lang === 'fr'
    ? `Rendez-vous en ${name} pour débloquer ces synergies`
    : `Travel to ${name} to unlock these synergies`;
}

function buildSynergyCardRegionLockedTooltip(gm: GameRuntime, regionId: string): string {
  const name = regionLabel(gm, regionId);
  const lang = synergyLanguage(gm);
  const key = 'tooltip.synergyCardRegionLocked';
  const tpl = gm.t(key);
  if (tpl && tpl !== key) return tpl.replace('{region}', name);
  return lang === 'fr'
    ? `Région verrouillée — rendez-vous en ${name} pour activer cette synergie`
    : `Region locked — travel to ${name} to activate this synergy`;
}

export function buildSynergyRegionTabs(
  gm: GameRuntime | null,
  playerTeam: CreatureSnapshot[],
): SynergyRegionTabView[] {
  const team = teamMembersFromSnapshots(playerTeam);
  const unlocked = getUnlockedSynergyRegionIds(gm);
  const synergies = TEAM_SYNERGIES as Record<string, TeamSynergyDef>;

  return SYNERGY_REGION_ORDER.map((regionId) => {
    const ids = Object.keys(synergies).filter((id) => synergies[id]?.regionId === regionId);
    let activeCount = 0;
    for (const synergyId of ids) {
      const def = synergies[synergyId];
      if (def && isSynergyActiveForTeam(def, team, gm)) activeCount++;
    }
    return {
      regionId,
      label: regionLabel(gm, regionId),
      locked: !unlocked.includes(regionId),
      activeCount,
      totalCount: ids.length,
    };
  });
}

export function defaultSynergyRegionTab(gm: GameRuntime | null): string {
  const unlocked = getUnlockedSynergyRegionIds(gm);
  const current =
    gm && typeof gm.getCurrentRegionId === 'function'
      ? String(gm.getCurrentRegionId() || 'kanto')
      : gm?.currentRegion || 'kanto';
  if (unlocked.includes(current)) return current;
  return unlocked[0] || 'kanto';
}

export function buildSynergyCards(
  gm: GameRuntime,
  playerTeam: CreatureSnapshot[],
  opts: BuildSynergyCardsOptions = {},
): SynergyCardView[] {
  const team = teamMembersFromSnapshots(playerTeam);
  const loc = synergyLocale(gm);
  const synergies = TEAM_SYNERGIES as Record<string, TeamSynergyDef>;
  const regionFilter = opts.regionId;

  const entries = Object.entries(synergies).filter(([, syn]) => {
    if (!syn) return false;
    if (regionFilter && syn.regionId !== regionFilter) return false;
    return true;
  });

  const sorted = entries.sort(([, a], [, b]) => {
    const aActive = isSynergyActiveForTeam(a, team, gm) ? 1 : 0;
    const bActive = isSynergyActiveForTeam(b, team, gm) ? 1 : 0;
    return bActive - aActive;
  });

  return sorted.map(([synergyId, synergy]) => {
    const dispName = localizedSynergyName(synergyId, synergy, loc);
    const dispMessage = localizedSynergyMessage(synergyId, synergy, loc);
    const synTypes = synergy.types ?? [];
    const minCount = synergy.min_count ?? 0;
    const regionLocked = !isSynergyRegionUnlocked(gm, synergy.regionId);
    const progress = computeSynergyProgress(synergy, team, gm);

    let shortDesc = dispMessage.split('!')[1] || dispMessage;
    shortDesc = shortDesc.replace(/[()]/g, '').trim();

    const separator = progress.allRequired
      ? ` ${gm.t('modal.synergyAnd')} `
      : ` ${gm.t('modal.synergyOr')} `;
    const reqParts: string[] = [];
    if (synTypes.length && minCount) {
      reqParts.push(`${minCount}x (${synTypes.map((t) => t.toUpperCase()).join(separator)})`);
    }
    if (synergy.requiredSpecies) {
      reqParts.push(formatSpeciesRequirement(synergy.requiredSpecies, gm).tooltipText);
    }
    const tooltipTitle = dispName;
    const effectLine = `${gm.t('modal.effectLabel')} : ${shortDesc}`;
    const tooltipDesc = regionLocked
      ? `${buildSynergyCardRegionLockedTooltip(gm, synergy.regionId)}\n\n${effectLine}`
      : `${gm.t('modal.requiredLabel')} : ${reqParts.join(' + ') || '—'}\n\n${effectLine}`;

    return {
      id: synergyId,
      regionId: synergy.regionId,
      name: dispName,
      shortDesc,
      isRegionLocked: regionLocked,
      types: synTypes,
      tooltipTitle,
      tooltipDesc,
      ...progress,
      isActive: regionLocked ? false : progress.isActive,
    };
  });
}

const EFFECT_LABELS: Record<string, { fr: string; en: string }> = {
  attack_mult: { fr: 'Atq.', en: 'ATK' },
  spattack_mult: { fr: 'Atq. Spé.', en: 'Sp. Atk' },
  defense_mult: { fr: 'Déf.', en: 'DEF' },
  spdefense_mult: { fr: 'Déf. Spé.', en: 'Sp. Def' },
  max_hp_mult: { fr: 'PV', en: 'HP' },
  speed_mult: { fr: 'Vit.', en: 'SPD' },
  exp_mult: { fr: 'XP', en: 'XP' },
  heal_mult: { fr: 'soins', en: 'healing' },
  pokedollars_mult: { fr: 'Pokédollars', en: 'Pokédollars' },
};

const EFFECT_STAT_CLS: Record<string, string> = {
  attack_mult: 'atk',
  spattack_mult: 'spatk',
  defense_mult: 'def',
  spdefense_mult: 'spdef',
  max_hp_mult: 'hp',
  speed_mult: 'spd',
  exp_mult: 'misc',
  heal_mult: 'misc',
  pokedollars_mult: 'misc',
};

const EFFECT_ORDER = [
  'attack_mult',
  'spattack_mult',
  'defense_mult',
  'spdefense_mult',
  'max_hp_mult',
  'speed_mult',
  'exp_mult',
  'heal_mult',
  'pokedollars_mult',
] as const;

function effectLabel(key: string, lang: string): string {
  const label = EFFECT_LABELS[key];
  return label ? (lang === 'fr' ? label.fr : label.en) : key;
}

function buildEffectBonusCellHtml(
  getPctForKey: (key: (typeof EFFECT_ORDER)[number]) => number | null,
  lang: string,
): string {
  const items: string[] = [];
  for (const key of EFFECT_ORDER) {
    const pct = getPctForKey(key);
    if (pct === null || pct <= 0) continue;
    const statCls = EFFECT_STAT_CLS[key] || 'misc';
    const name = effectLabel(key, lang);
    items.push(`
      <div class="synergy-tooltip-bonus-item">
        <span class="synergy-tooltip-stat-label ${statCls}">${_tooltipEscapeHtml(name)}</span>
        <span class="synergy-tooltip-stat-value">+${pct}%</span>
      </div>`);
  }
  if (!items.length) {
    return `<span class="synergy-tooltip-table-empty">—</span>`;
  }
  return `<div class="synergy-tooltip-bonus-list">${items.join('')}</div>`;
}

function effectPctFromDef(effect: Record<string, number>, key: string): number | null {
  const val = effect[key];
  if (typeof val !== 'number' || val <= 0) return null;
  return Math.round(val * 100);
}

function effectPctFromBonuses(
  bonuses: ReturnType<typeof aggregateSynergyEffects>,
  key: string,
): number | null {
  const base = key === 'heal_mult' || key === 'pokedollars_mult' ? 0 : 1;
  const val = bonuses[key] - base;
  if (val <= 0) return null;
  return Math.round(val * 100);
}

export const SYNERGY_TOOLTIP_TWO_COLUMN_MIN_ROWS = 7;

export function shouldUseSynergyTooltipTwoColumns(rowCount: number): boolean {
  return rowCount >= SYNERGY_TOOLTIP_TWO_COLUMN_MIN_ROWS;
}

function synergyTooltipColumnLabels(lang: string): {
  synergyCol: string;
  bonusCol: string;
  totalLabel: string;
} {
  return {
    synergyCol: lang === 'fr' ? 'Synergie' : 'Synergy',
    bonusCol: lang === 'fr' ? 'Bonus' : 'Bonus',
    totalLabel: lang === 'fr' ? 'Total' : 'Total',
  };
}

function buildSynergyTooltipBodyRowsHtml(
  rows: Array<{ name: string; effect: Record<string, number> }>,
  lang: string,
): string {
  return rows
    .map(
      ({ name, effect }) => `
    <tr class="synergy-tooltip-table-row">
      <td class="synergy-tooltip-col-name"><strong>${_tooltipEscapeHtml(name)}</strong></td>
      <td class="synergy-tooltip-col-bonus">${buildEffectBonusCellHtml((key) => effectPctFromDef(effect, key), lang)}</td>
    </tr>`,
    )
    .join('');
}

function buildSynergyTooltipPartialTableHtml(
  rows: Array<{ name: string; effect: Record<string, number> }>,
  lang: string,
  synergyCol: string,
  bonusCol: string,
): string {
  return `
    <table class="synergy-tooltip-table">
      <thead>
        <tr>
          <th class="synergy-tooltip-col-name">${_tooltipEscapeHtml(synergyCol)}</th>
          <th class="synergy-tooltip-col-bonus">${_tooltipEscapeHtml(bonusCol)}</th>
        </tr>
      </thead>
      <tbody>
        ${buildSynergyTooltipBodyRowsHtml(rows, lang)}
      </tbody>
    </table>`;
}

function buildSynergyTooltipTotalRowHtml(
  totalBonuses: ReturnType<typeof aggregateSynergyEffects>,
  lang: string,
  totalLabel: string,
): string {
  return `
    <tr class="synergy-tooltip-table-row synergy-tooltip-table-row--total">
      <td class="synergy-tooltip-col-name"><strong>${_tooltipEscapeHtml(totalLabel)}</strong></td>
      <td class="synergy-tooltip-col-bonus">${buildEffectBonusCellHtml((key) => effectPctFromBonuses(totalBonuses, key), lang)}</td>
    </tr>`;
}

export function buildSynergyTooltipTableHtml(
  rows: Array<{ name: string; effect: Record<string, number> }>,
  totalBonuses: ReturnType<typeof aggregateSynergyEffects>,
  lang: string,
): string {
  const { synergyCol, bonusCol, totalLabel } = synergyTooltipColumnLabels(lang);

  if (shouldUseSynergyTooltipTwoColumns(rows.length)) {
    const splitAt = Math.ceil(rows.length / 2);
    const leftRows = rows.slice(0, splitAt);
    const rightRows = rows.slice(splitAt);
    return `
      <div class="synergy-tooltip-table-split">
        ${buildSynergyTooltipPartialTableHtml(leftRows, lang, synergyCol, bonusCol)}
        ${buildSynergyTooltipPartialTableHtml(rightRows, lang, synergyCol, bonusCol)}
      </div>
      <table class="synergy-tooltip-table synergy-tooltip-table--total">
        <tbody>
          ${buildSynergyTooltipTotalRowHtml(totalBonuses, lang, totalLabel)}
        </tbody>
      </table>`;
  }

  return `
    <table class="synergy-tooltip-table">
      <thead>
        <tr>
          <th class="synergy-tooltip-col-name">${_tooltipEscapeHtml(synergyCol)}</th>
          <th class="synergy-tooltip-col-bonus">${_tooltipEscapeHtml(bonusCol)}</th>
        </tr>
      </thead>
      <tbody>
        ${buildSynergyTooltipBodyRowsHtml(rows, lang)}
        ${buildSynergyTooltipTotalRowHtml(totalBonuses, lang, totalLabel)}
      </tbody>
    </table>`;
}

export function buildSynergyButtonTooltip(
  gm: GameRuntime | null,
  playerTeam: CreatureSnapshot[],
): { title: string; body: string } {
  if (!gm) {
    return { title: 'Synergies', body: '' };
  }
  const lang =
    typeof gm.normalizeLanguage === 'function' ? gm.normalizeLanguage(gm.language) : gm.language;
  const team = teamMembersFromSnapshots(playerTeam);
  const active = getActiveSynergyEntries(team, gm);
  const loc = synergyLocale(gm);

  const titleKey = 'tooltip.synergyBtnTitle';
  const title = gm.t(titleKey);
  const resolvedTitle = title !== titleKey ? title : 'Synergies';

  if (!active.length) {
    const noneKey = 'tooltip.synergyNoneActive';
    const none = gm.t(noneKey);
    const noneLine =
      none !== noneKey ? none : lang === 'fr' ? 'Aucune synergie active' : 'No active synergies';
    const hintLine =
      lang === 'fr'
        ? 'Composez votre équipe pour activer des bonus.'
        : 'Build your team to activate bonuses.';
    const body = `
      <div class="team-tooltip-body synergy-tooltip-body synergy-tooltip-empty">
        <div class="synergy-tooltip-summary">${_tooltipEscapeHtml(noneLine)}</div>
        <div class="synergy-tooltip-hint">${_tooltipEscapeHtml(hintLine)}</div>
      </div>`;
    return { title: resolvedTitle, body };
  }

  const summaryKey = 'tooltip.synergyActiveSummary';
  const summaryTpl = gm.t(summaryKey);
  const summaryLine =
    summaryTpl !== summaryKey
      ? summaryTpl.replace('{count}', String(active.length))
      : lang === 'fr'
        ? `Synergies actives (${active.length})`
        : `Active synergies (${active.length})`;

  const tableRows: Array<{ name: string; effect: Record<string, number> }> = [];
  for (let i = 0; i < active.length; i++) {
    const entry = active[i];
    if (!entry) continue;
    const { id, def } = entry;
    tableRows.push({
      name: localizedSynergyName(id, def, loc),
      effect: def.effect,
    });
  }

  const tableHtml = buildSynergyTooltipTableHtml(
    tableRows,
    aggregateSynergyEffects(team, gm),
    lang,
  );
  const wideClass = shouldUseSynergyTooltipTwoColumns(tableRows.length)
    ? ' synergy-tooltip-body--wide'
    : '';
  const body = `
    <div class="team-tooltip-body synergy-tooltip-body${wideClass}">
      <div class="synergy-tooltip-summary">${_tooltipEscapeHtml(summaryLine)}</div>
      ${tableHtml}
    </div>`;

  return { title: resolvedTitle, body };
}
