<script lang="ts">
  import { formatNumber } from '../../formatters.js';

  let {
    current,
    max = 100,
    color = '',
    animated = false,
    showLabel = false,
    fillId = '',
    textId = '',
  }: {
    current: number;
    max?: number;
    color?: string;
    animated?: boolean;
    showLabel?: boolean;
    fillId?: string;
    textId?: string;
  } = $props();

  let pct = $derived(max > 0 ? Math.min(100, Math.max(0, (current / max) * 100)) : 0);

  let fillColor = $derived(
    color || (pct > 50 ? 'var(--hp-green)' : pct > 25 ? 'var(--hp-orange)' : 'var(--hp-red)')
  );

  let motionSafe = $derived(
    typeof window !== 'undefined' &&
    window.matchMedia('(prefers-reduced-motion: reduce)').matches
  );

  let useAnimation = $derived(animated && !motionSafe);

  let hpLabel = $derived(
    showLabel ? `${formatNumber(current)} / ${formatNumber(max)}` : '',
  );
</script>

<div class="health-bar" role="progressbar" aria-valuenow={current} aria-valuemin="0" aria-valuemax={max}>
  <div
    class="health-fill"
    class:animated={useAnimation}
    id={fillId || undefined}
    style:width="100%"
    style:background={fillColor}
    style:transform={"scaleX(" + (pct / 100) + ")"}
    style:transform-origin="left"
    style:will-change={useAnimation ? 'transform' : undefined}
  ></div>
  {#if showLabel}
    <div class="health-text" id={textId || undefined}>{hpLabel}</div>
  {/if}
</div>

<style>
  .animated {
    transition: transform 0.25s ease-out;
  }
  @media (prefers-reduced-motion: reduce) {
    .animated {
      transition: none;
    }
  }
  @media (max-width: 1200px) {
    .animated {
      transition: none;
    }
  }
</style>
