<script lang="ts">
  import { tick } from 'svelte';
  import { shop } from '../../stores/shop.svelte.ts';
  import type { RecyclerShardSnapshot } from '../../bus/snapshots.js';
  import { game } from '../../../gameManager.js';
  import { uiText } from '../../ui/i18n.ts';
  import { facade } from '../../bus/gameFacade.js';
  import RecyclerShardPopover from './RecyclerShardPopover.svelte';

  let snap = $derived(shop.snapshot);
  let selectedKey = $state<string | null>(null);
  let anchorRect = $state<DOMRect | null>(null);
  let showPopover = $state(false);

  let selectedEntry = $derived(
    selectedKey
      ? snap.recyclerShards.find((e) => e.shardKey === selectedKey) ?? null
      : null,
  );

  let protectTitle = $derived(uiText('shop.recyclerUnprotect', 'Déprotéger', {}, game));

  export function closePopover(): void {
    selectedKey = null;
    anchorRect = null;
    showPopover = false;
  }

  async function openTile(entry: RecyclerShardSnapshot, el: HTMLButtonElement, e: MouseEvent) {
    e.stopPropagation();
    if (selectedKey === entry.shardKey) {
      closePopover();
      return;
    }
    selectedKey = entry.shardKey;
    anchorRect = el.getBoundingClientRect();
    showPopover = false;
    await tick();
    showPopover = true;
  }

  function toggleProtect(shardKey: string, e: MouseEvent) {
    e.stopPropagation();
    facade.dispatch({ type: 'TOGGLE_PROTECT_SHARD', shardKey });
  }
</script>

<div class="recycler-shards-panel" id="recyclerShardList">
  {#if snap.recyclerShardsEmpty}
    <p class="recycler-empty-msg">{snap.recyclerShardsEmpty}</p>
  {:else}
    <div class="recycler-shards-grid">
      {#each snap.recyclerShards as entry (entry.shardKey)}
        <div class="recycler-shard-tile-wrap">
          <button
            type="button"
            class="recycler-shard-tile"
            class:selected={selectedKey === entry.shardKey}
            class:protected={entry.isProtected}
            aria-label="{entry.displayName}, x{entry.countFormatted}"
            aria-expanded={selectedKey === entry.shardKey}
            onclick={(e) => openTile(entry, e.currentTarget, e)}
          >
            <img
              src={entry.spriteUrl}
              alt=""
              class="recycler-shard-sprite"
              width="56"
              height="56"
            >
            <span class="recycler-shard-count">x{entry.countFormatted}</span>
            <span class="rarity-label recycler-shard-rarity {entry.rarity}">{entry.rarity}</span>
          </button>
          {#if entry.isProtected}
            <button
              type="button"
              class="recycler-shard-lock-btn"
              title={protectTitle}
              onclick={(e) => toggleProtect(entry.shardKey, e)}
            >🔒</button>
          {/if}
        </div>
      {/each}
    </div>
  {/if}
</div>

{#if selectedKey && selectedEntry && anchorRect}
  {#key selectedKey}
    <RecyclerShardPopover
      entry={selectedEntry}
      {anchorRect}
      open={showPopover}
      onClose={closePopover}
    />
  {/key}
{/if}
