<script lang="ts">
  import { miltankFarm } from '../stores/miltankFarm.svelte.ts';
  import { buildFeedButtonTooltipContent } from '../lib/miltankFarmFeedTooltip.ts';
  import { miltankFarmTooltipHandlers } from '../ui/scheduleTooltipHelpers.ts';

  let snap = $derived(miltankFarm.snapshot);
  let ui = $derived(snap.ui);
  let showAssign = $state(false);

  let canAssignMore = $derived(
    snap.nextPastureSlot != null && snap.pastureCandidates.length > 0,
  );

  let assignSlotLabel = $derived(
    snap.nextPastureSlot === 'shiny' ? ' ✨' : '',
  );

  let assignCountLabel = $derived(
    `${snap.assignedCount}/${snap.maxAssignableSlots}`,
  );
</script>

<div class="miltank-farm-hud-bar" id="miltankFarmHudBar">
  <div class="miltank-farm-hud-meta">
    <span>{ui.farmLevelSumLabel}: <strong>{snap.farmLevelSum}</strong></span>
      <span class="miltank-farm-hud-stock-block">
      {ui.stockLabel}: <strong>{snap.farmStoredMilk}/{snap.farmStockCap}</strong>
      <span
        class="miltank-farm-hud-stock-gauge miltank-farm-tooltip-host"
        data-tooltip-variant="miltank-farm"
        {...miltankFarmTooltipHandlers(() => ({ title: ui.stockLabel, body: ui.stockTooltip }))}
      >
        <span
          class="miltank-farm-bar miltank-farm-bar--stock miltank-farm-bar--hud"
          role="progressbar"
          aria-valuenow={snap.farmStockFillPct}
          aria-valuemin="0"
          aria-valuemax="100"
        >
          <span
            class="miltank-farm-bar-fill miltank-farm-bar-fill--stock"
            style="width: {snap.farmStockFillPct}%"
          ></span>
        </span>
        {#if snap.farmStockFullLabel}
          <span class="miltank-farm-stock-full-hint miltank-farm-stock-full-hint--hud">{snap.farmStockFullLabel}</span>
        {/if}
      </span>
    </span>
    <span>{ui.productionLabel}: <strong>{snap.farmMilkPerHour.toFixed(3)}{ui.perHour}</strong></span>
    {#if snap.threatIntensityLabel}
      <span class="miltank-farm-threat-intensity-hud" role="status">{snap.threatIntensityLabel}</span>
    {/if}
  </div>

  {#if snap.hasActiveThreat && snap.threatAlertLabel}
    <span class="miltank-farm-threat-hud" role="status">{snap.threatAlertLabel}</span>
  {:else if snap.repelledAlertLabel}
    <span class="miltank-farm-repelled-hud" role="status">{snap.repelledAlertLabel}</span>
  {/if}

  <div class="miltank-farm-hud-pasture-row">
    {#if snap.unlocked && snap.pastureAssignSlots.length > 0}
      <div class="miltank-farm-assign-panel miltank-farm-assign-panel--slots">
        <span class="miltank-farm-assign-title">
          {ui.pastureAssignTitle} ({assignCountLabel})
        </span>
        <div class="miltank-farm-assign-slots" role="list" aria-label={ui.pastureAssignTitle}>
          {#each snap.pastureAssignSlots as slot (slot.kind)}
            <div
              class="miltank-farm-assign-slot"
              class:miltank-farm-assign-slot--empty={slot.empty}
              class:miltank-farm-assign-slot--reserved={slot.reserved}
              class:miltank-farm-assign-slot--narrative={slot.kind === 'narrative'}
              class:miltank-farm-assign-slot--filled={slot.filled}
              role="listitem"
            >
              <span
                class="miltank-pasture-sprite"
                class:shiny={slot.shiny}
                aria-hidden="true"
              ></span>
              <span class="miltank-farm-assign-slot-label">{slot.label}</span>
              {#if slot.filled && slot.name && slot.kind !== 'narrative'}
                <span class="miltank-farm-assign-slot-name">{slot.name}</span>
              {:else if slot.reserved && slot.empty}
                <span class="miltank-farm-assign-slot-hint">{ui.pastureShinySlotReserved}</span>
              {/if}
              {#if slot.canUnassign && slot.uid}
                <button
                  type="button"
                  class="miltank-farm-assign-slot-unassign"
                  data-action="unassignMiltankFromPasture"
                  data-arg={slot.uid}
                  aria-label="{ui.unassignBtn} {slot.name}"
                >✕</button>
              {/if}
            </div>
          {/each}
        </div>
      </div>
    {/if}

    <div class="miltank-farm-hud-actions">
    <button
      type="button"
      class="miltank-farm-btn miltank-farm-btn--feed"
      data-action="feedMiltankFarm"
      disabled={!snap.canFeed}
      data-tooltip-variant="miltank-farm"
      {...miltankFarmTooltipHandlers(() => buildFeedButtonTooltipContent(snap))}
    >{ui.feedBtn}</button>
    <button
      type="button"
      class="miltank-farm-btn miltank-farm-btn--claim"
      data-action="claimMiltankFarmMilk"
      disabled={!snap.canClaim}
    >{ui.claimAllBtn}</button>
    {#if canAssignMore}
      <button
        type="button"
        class="miltank-farm-btn miltank-farm-btn--assign"
        onclick={() => { showAssign = !showAssign; }}
      >{ui.assignBtn}{assignSlotLabel}</button>
    {/if}
    <button
      type="button"
      class="miltank-farm-btn miltank-farm-btn--leave"
      data-action="leaveMiltankFarmView"
    >{ui.leaveBtn}</button>
    </div>
  </div>

  {#if showAssign && canAssignMore}
    <div class="miltank-farm-assign-panel">
      <span class="miltank-farm-assign-title">{ui.assignBtn}{assignSlotLabel}</span>
      <div class="miltank-farm-assign-list">
        {#each snap.pastureCandidates as candidate (candidate.uid)}
          <button
            type="button"
            class="miltank-farm-btn miltank-farm-btn--chip miltank-farm-btn--assign"
            data-action="assignMiltankToPasture"
            data-arg="{candidate.source}:{candidate.index}"
          >{candidate.name}{candidate.shiny ? ' ✨' : ''} · {candidate.sourceLabel}</button>
        {/each}
      </div>
    </div>
  {/if}
</div>
