/** One-time save fix: Twist Mountain (446) is mainline between Driftveil and Mistralton. */
export function migrateUnovaRouteProgressionV1(data: {
    unovaRouteProgressionV1?: boolean;
    badges?: Record<string, boolean>;
    zoneProgress?: Record<string, { bossesDefeated?: number; [key: string]: unknown }>;
}): void {
    if (data.unovaRouteProgressionV1 === true) return;

    const badges = data.badges;
    const zoneProgress = data.zoneProgress;
    const hasQuake = !!(badges?.quake);
    const hasJet = !!(badges?.jet);

    if (zoneProgress && (hasQuake || hasJet)) {
        const twistKey = '446';
        const existing = zoneProgress[twistKey] || {};
        const bossesDone = Number(existing.bossesDefeated) || 0;
        if (bossesDone < 1) {
            zoneProgress[twistKey] = { ...existing, bossesDefeated: 1 };
        }
    }

    data.unovaRouteProgressionV1 = true;
}

function ensureZoneBossProgress(
    zoneProgress: Record<string, { bossesDefeated?: number; [key: string]: unknown }>,
    zoneId: number,
    minBosses: number,
): void {
    const key = String(zoneId);
    const existing = zoneProgress[key] || {};
    const bossesDone = Number(existing.bossesDefeated) || 0;
    if (bossesDone < minBosses) {
        zoneProgress[key] = { ...existing, bossesDefeated: minBosses };
    }
}

/** B2W2 route order: Desert/Relic before Nimbasa; Chargestone after Nimbasa. */
export function migrateUnovaRouteProgressionV2(data: {
    unovaRouteProgressionV2?: boolean;
    badges?: Record<string, boolean>;
    zoneProgress?: Record<string, { bossesDefeated?: number; [key: string]: unknown }>;
    maxReachedZoneByRegion?: Record<string, number>;
}): void {
    if (data.unovaRouteProgressionV2 === true) return;

    const badges = data.badges;
    const zoneProgress = data.zoneProgress;

    if (zoneProgress && badges) {
        if (badges.insect || badges.bolt || badges.quake || badges.jet || badges.freeze || badges.legend) {
            ensureZoneBossProgress(zoneProgress, 430, 1);
            if (zoneProgress['442']) {
                const relic = zoneProgress['442'];
                const epicsDone = Number(relic.epicsDefeated) || 0;
                if (epicsDone < 1) {
                    zoneProgress['442'] = { ...relic, epicsDefeated: 1 };
                }
            }
        }
        if (badges.bolt || badges.quake || badges.jet || badges.freeze || badges.legend) {
            ensureZoneBossProgress(zoneProgress, 413, 1);
            if (zoneProgress['416']) {
                const celestial = zoneProgress['416'];
                const epicsDone = Number(celestial.epicsDefeated) || 0;
                if (epicsDone < 1) {
                    zoneProgress['416'] = { ...celestial, epicsDefeated: 1 };
                }
            }
        }
    }

    const maxByRegion = data.maxReachedZoneByRegion;
    if (maxByRegion && badges) {
        let minOrder = 0;
        if (badges.legend) minOrder = 27;
        else if (badges.freeze) minOrder = 25;
        else if (badges.jet) minOrder = 22;
        else if (badges.quake) minOrder = 20;
        else if (badges.bolt) minOrder = 15;
        else if (badges.insect) minOrder = 11;

        if (minOrder > 0) {
            const orderToZone: Record<number, number> = {
                11: 414, 15: 422, 20: 417, 22: 424, 25: 420, 27: 439,
            };
            const floorZone = orderToZone[minOrder];
            if (floorZone != null) {
                const current = Number(maxByRegion.unova) || 0;
                if (current < floorZone) {
                    maxByRegion.unova = floorZone;
                }
            }
        }
    }

    data.unovaRouteProgressionV2 = true;
}

/** Route 12 (453) inserted into mainline; preserve saves that skipped it. */
export function migrateUnovaRouteProgressionV3(data: {
    unovaRouteProgressionV3?: boolean;
    badges?: Record<string, boolean>;
    zoneProgress?: Record<string, { bossesDefeated?: number; epicsDefeated?: number; pokemonTiers?: Record<string, number>; [key: string]: unknown }>;
    maxReachedZoneByRegion?: Record<string, number>;
}): void {
    if (data.unovaRouteProgressionV3 === true) return;

    const zoneProgress = data.zoneProgress;
    const maxByRegion = data.maxReachedZoneByRegion;
    const maxUnova = Number(maxByRegion?.unova) || 0;

    if (zoneProgress) {
        if ((zoneProgress['426'] || maxUnova >= 426) && !zoneProgress['453']) {
            const donor = zoneProgress['423'] || zoneProgress['425'] || zoneProgress['426'];
            if (donor) zoneProgress['453'] = { ...donor };
        }
    }

    if (maxByRegion && maxUnova >= 426 && maxUnova < 453) {
        maxByRegion.unova = 453;
    }

    const badges = data.badges;
    if (maxByRegion && badges?.legend) {
        const current = Number(maxByRegion.unova) || 0;
        if (current < 439) {
            maxByRegion.unova = 439;
        }
    }

    data.unovaRouteProgressionV3 = true;
}

const UNOVA_EASTERN_ARC_ZONE_IDS = [423, 425, 453, 426, 427, 428, 429, 431, 432, 433, 434, 435, 436, 437] as const;

/** Opelucid (439) before eastern arc; Marvelous Bridge (444) optional post-league. */
export function migrateUnovaRouteProgressionV4(data: {
    unovaRouteProgressionV4?: boolean;
    badges?: Record<string, boolean>;
    zoneProgress?: Record<string, { bossesDefeated?: number; epicsDefeated?: number; pokemonTiers?: Record<string, number>; [key: string]: unknown }>;
    maxReachedZoneByRegion?: Record<string, number>;
}): void {
    if (data.unovaRouteProgressionV4 === true) return;

    const zoneProgress = data.zoneProgress;
    const maxByRegion = data.maxReachedZoneByRegion;
    const maxUnova = Number(maxByRegion?.unova) || 0;
    const badges = data.badges;

    const hasEasternProgress = UNOVA_EASTERN_ARC_ZONE_IDS.some(
        (id) => zoneProgress?.[String(id)] || maxUnova >= id,
    );
    const passedRoute9 = !!(zoneProgress?.['421'] || maxUnova >= 421 || badges?.freeze);

    if (zoneProgress && passedRoute9 && !zoneProgress['439'] && (hasEasternProgress || badges?.legend || maxUnova >= 440)) {
        const donor = zoneProgress['421'] || zoneProgress['420'] || zoneProgress['438'] || zoneProgress['423'];
        if (donor) zoneProgress['439'] = { ...donor };
    }

    if (maxByRegion && maxUnova >= 421 && maxUnova < 439 && (hasEasternProgress || badges?.legend)) {
        maxByRegion.unova = 439;
    }

    if (maxByRegion && maxUnova === 444) {
        maxByRegion.unova = 443;
    }

    data.unovaRouteProgressionV4 = true;
}

/** B2W2 late-game order: Route 21 → VR → Route 23 → Giant Chasm → League. */
export function migrateUnovaRouteProgressionV5(data: {
    unovaRouteProgressionV5?: boolean;
    zoneProgress?: Record<string, { bossesDefeated?: number; epicsDefeated?: number; pokemonTiers?: Record<string, number>; [key: string]: unknown }>;
    maxReachedZoneByRegion?: Record<string, number>;
}): void {
    if (data.unovaRouteProgressionV5 === true) return;

    const zoneProgress = data.zoneProgress;
    const maxByRegion = data.maxReachedZoneByRegion;
    const maxUnova = Number(maxByRegion?.unova) || 0;

    if (zoneProgress && (zoneProgress['438'] || maxUnova >= 438)) {
        const donor = zoneProgress['438'] || zoneProgress['437'] || zoneProgress['440'];
        if (donor) {
            for (const id of [440, 441, 443] as const) {
                if (!zoneProgress[String(id)]) {
                    zoneProgress[String(id)] = { ...donor };
                }
            }
        }
    }

    if (maxByRegion && maxUnova === 444) {
        maxByRegion.unova = 443;
    }

    data.unovaRouteProgressionV5 = true;
}

/** Full B2W2 route order: Aspertia start, Humilau 8th badge, BW1 loop post-league. */
export function migrateUnovaRouteProgressionV6(data: {
    unovaRouteProgressionV6?: boolean;
    badges?: Record<string, boolean>;
    zoneProgress?: Record<string, { bossesDefeated?: number; epicsDefeated?: number; pokemonTiers?: Record<string, number>; [key: string]: unknown }>;
    maxReachedZoneByRegion?: Record<string, number>;
}): void {
    if (data.unovaRouteProgressionV6 === true) return;

    const badges = data.badges;
    const zoneProgress = data.zoneProgress;
    const maxByRegion = data.maxReachedZoneByRegion;
    const maxUnova = Number(maxByRegion?.unova) || 0;

    const badgeFloorZone = {
        trileaf: 456,
        basic: 414,
        insect: 422,
        bolt: 417,
        quake: 424,
        jet: 452,
        legend: 466,
        freeze: 438,
    } as const;

    if (maxByRegion && badges?.maitre_sinnoh && maxUnova > 0 && maxUnova < 454 && !badges.trileaf) {
        maxByRegion.unova = 454;
    }

    if (maxByRegion && badges) {
        let floor = 0;
        if (badges.freeze) floor = badgeFloorZone.freeze;
        else if (badges.legend) floor = badgeFloorZone.legend;
        else if (badges.jet) floor = badgeFloorZone.jet;
        else if (badges.quake) floor = badgeFloorZone.quake;
        else if (badges.bolt) floor = badgeFloorZone.bolt;
        else if (badges.insect) floor = badgeFloorZone.insect;
        else if (badges.basic) floor = badgeFloorZone.basic;
        else if (badges.trileaf) floor = badgeFloorZone.trileaf;

        if (floor > 0 && maxUnova < floor) {
            maxByRegion.unova = floor;
        }
    }

    if (zoneProgress) {
        const pastMistralton = !!(zoneProgress['424'] || maxUnova >= 424 || badges?.jet);
        const donorMistralton = zoneProgress['424'] || zoneProgress['413'] || zoneProgress['417'];
        if (pastMistralton && donorMistralton) {
            for (const id of [452, 465] as const) {
                if (!zoneProgress[String(id)]) {
                    zoneProgress[String(id)] = { ...donorMistralton };
                }
            }
        }

        const pastOpelucid = !!(zoneProgress['439'] || maxUnova >= 439 || badges?.legend);
        const donorOpelucid = zoneProgress['439'] || zoneProgress['423'] || zoneProgress['421'];
        if (pastOpelucid && donorOpelucid && !zoneProgress['466']) {
            zoneProgress['466'] = { ...donorOpelucid };
        }

        if (pastOpelucid && !zoneProgress['439'] && donorOpelucid) {
            zoneProgress['439'] = { ...donorOpelucid };
        }

        const pastHumilau = !!(zoneProgress['466'] || maxUnova >= 466 || badges?.freeze);
        const donorClimax = zoneProgress['466'] || zoneProgress['438'] || zoneProgress['437'];
        if (pastHumilau && donorClimax) {
            for (const id of [437, 440, 462, 460, 438, 443, 441] as const) {
                if (!zoneProgress[String(id)]) {
                    zoneProgress[String(id)] = { ...donorClimax };
                }
            }
        }
    }

    if (maxByRegion && badges?.maitre_unova && maxUnova >= 445 && maxUnova < 444) {
        maxByRegion.unova = 445;
    }

    data.unovaRouteProgressionV6 = true;
}

/** Strip false Plasma story completions from saves that advanced before faction quests existed. */
export function migrateUnovaPlasmaCatchUpV1(data: {
    unovaPlasmaCatchUpV1?: boolean;
    completedStoryQuests?: string[];
    rivalState?: { zonesDefeated?: Record<string, boolean> };
}): void {
    if (data.unovaPlasmaCatchUpV1 === true) return;

    const completed = data.completedStoryQuests;
    const defeated = data.rivalState?.zonesDefeated;
    const hasRivalSnapshot = defeated != null && typeof defeated === 'object';
    if (Array.isArray(completed) && hasRivalSnapshot) {
        for (const key of Object.keys(STORY_QUESTS)) {
            if (!key.startsWith('unova_plasma_') && key !== 'unova_p2_laboratory') continue;
            const def = STORY_QUESTS[key as keyof typeof STORY_QUESTS];
            if (!def?.id) continue;
            const idx = completed.indexOf(def.id);
            if (idx === -1) continue;
            const rivalKey = def.specialParams?.rivalKey;
            const requiredZone = def.specialParams?.requiredZone;
            const rivalDone = !!(
                (rivalKey && defeated[rivalKey])
                || (requiredZone != null && defeated[String(requiredZone)])
            );
            if (rivalDone) continue;
            completed.splice(idx, 1);
        }
    }

    data.unovaPlasmaCatchUpV1 = true;
}

/** B2W2 remap: legacy Plasma grunt defeat on Route 2 (404) → Route 19 (454) + rivalKey. */
export function migrateUnovaPlasmaZoneV2(data: {
    unovaPlasmaZoneV2?: boolean;
    rivalState?: { zonesDefeated?: Record<string, boolean> };
    completedStoryQuests?: string[];
    quests?: Array<{ id?: string | number; completed?: boolean; claimed?: boolean }>;
}): void {
    if (data.unovaPlasmaZoneV2 === true) return;

    const defeated = data.rivalState?.zonesDefeated;
    if (defeated && defeated['404'] && !defeated.unova_plasma_accumula) {
        const plasmaClaimed = Array.isArray(data.completedStoryQuests)
            && data.completedStoryQuests.includes('story_unova_plasma_accumula');
        const plasmaQuestRow = Array.isArray(data.quests)
            ? data.quests.find((q) => String(q.id) === 'story_unova_plasma_accumula')
            : undefined;
        const plasmaQuestCompleted = !!(plasmaQuestRow?.completed || plasmaQuestRow?.claimed);
        if (plasmaClaimed || plasmaQuestCompleted) {
            defeated.unova_plasma_accumula = true;
            defeated['454'] = true;
        }
    }

    data.unovaPlasmaZoneV2 = true;
}

/** Strip post-League Unova story completions from saves that never beat the Elite Four. */
export function migrateUnovaPostLeagueQuestGatingV1(data: {
    unovaPostLeagueQuestGatingV1?: boolean;
    completedStoryQuests?: string[];
}): void {
    if (data.unovaPostLeagueQuestGatingV1 === true) return;

    const completed = data.completedStoryQuests;
    if (Array.isArray(completed) && !completed.includes('story_unova_elite_four')) {
        for (const questId of STORY_QUEST_UNOVA_POST_LEAGUE_IDS) {
            const idx = completed.indexOf(questId);
            if (idx !== -1) completed.splice(idx, 1);
        }
    }

    data.unovaPostLeagueQuestGatingV1 = true;
}

