<script lang="ts">
  /* eslint-disable svelte/no-at-html-tags -- upgrade cards from shopSnapshot */
  import { shop } from '../../stores/shop.svelte.ts';
  import { bindUpgradeTooltips } from '../../ui/shopDisplay.ts';
  import { game } from '../../../gameManager.js';

  let snap = $derived(shop.snapshot);
  let container: HTMLDivElement | undefined;

  $effect(() => {
    snap.upgradesHtml;
    const gm = game as import('../../types/game.js').GameRuntime | null;
    if (container && gm) bindUpgradeTooltips(container, gm);
  });
</script>

<div class="upgrades-container" id="upgradesContainer" bind:this={container}>
  {@html snap.upgradesHtml}
</div>
