/// <reference types="svelte" />
/**
 * Store: combat — see CARTOGRAPHY.md
 * Consumers: CombatOverlay → HPBar
 */

import { facade } from '@bus/facade';
import { GameEventType as Evt } from '../bus/events.js';
import type { CombatSnapshot, CreatureSnapshot } from '../bus/snapshots.js';
import { shallowEqualCreature } from './storeUtils.js';

class CombatStore {
  state: string = $state('idle');
  currentEnemy: CreatureSnapshot | null = $state(null);
  currentPlayerCreature: CreatureSnapshot | null = $state(null);
  playerHudCurrentHp: number = $state(0);
  playerHudMaxHp: number = $state(1);
  combatSpeed: number = $state(1);
  captureMode: number = $state(0);
  autoMaster: boolean = $state(false);
}

export const combat = new CombatStore();

function applyCombatSnapshot(s: CombatSnapshot): void {
  if (s.state !== combat.state) combat.state = s.state;
  if (!shallowEqualCreature(combat.currentEnemy, s.currentEnemy)) {
    combat.currentEnemy = s.currentEnemy;
  }
  if (!shallowEqualCreature(combat.currentPlayerCreature, s.currentPlayerCreature)) {
    combat.currentPlayerCreature = s.currentPlayerCreature;
  }
  if (s.playerHudCurrentHp !== combat.playerHudCurrentHp) {
    combat.playerHudCurrentHp = s.playerHudCurrentHp;
  }
  if (s.playerHudMaxHp !== combat.playerHudMaxHp) {
    combat.playerHudMaxHp = s.playerHudMaxHp;
  }
  if (s.combatSpeed !== combat.combatSpeed) combat.combatSpeed = s.combatSpeed;
  if (s.captureMode !== combat.captureMode) combat.captureMode = s.captureMode;
  if (s.autoMaster !== combat.autoMaster) combat.autoMaster = s.autoMaster;
}

facade.subscribe(Evt.COMBAT_STATE_CHANGED, (evt) => {
  if (evt.type !== Evt.COMBAT_STATE_CHANGED) return;
  applyCombatSnapshot(evt.combat);
});

facade.subscribe(Evt.COMBAT_STARTED, (evt) => {
  if (evt.type !== Evt.COMBAT_STARTED) return;
  applyCombatSnapshot(evt.snapshot);
});
