<script lang="ts">
  import type { ResonanceTeamPreview } from '../lib/regionalResonance.ts';
  import { game } from '../../gameManager.js';
  import type { GameRuntime } from '../types/game.js';
  import { GEN5_SUBSTITUTE_SPRITE } from '../ui/utils.ts';
  import { touchTooltipHandlers } from '../ui/scheduleTooltipHelpers.ts';
  import {
    buildResonanceTooltipBody,
    buildResonanceTooltipTitle,
  } from '../lib/resonanceTooltip.ts';
  import { useGameLanguageTick } from '../lib/useGameLanguageTick.svelte.ts';
  import { formatPrestigeSuffix } from '../../formatters.ts';

  let { preview }: { preview: ResonanceTeamPreview | null } = $props();

  const { trackGameLanguage } = useGameLanguageTick();

  function applyVars(template: string, vars?: Record<string, unknown>): string {
    if (!vars) return template;
    return String(template).replace(/\{(\w+)\}/g, (_, k) => {
      const v = vars[k];
      if (v == null) return '';
      return String(v);
    });
  }

  function t(key: string, fallback: string, vars?: Record<string, unknown>): string {
    trackGameLanguage();
    const gm = game as GameRuntime | null;
    if (!gm?.t) return applyVars(fallback, vars);
    const got = gm.t(key, vars);
    return got && got !== key ? got : applyVars(fallback, vars);
  }

  function buildLevelPartPlain(prestige: number, level: number, levelWord: string): string {
    const prestigeSuffix = formatPrestigeSuffix(prestige);
    const prefix = prestigeSuffix ? `${prestigeSuffix} ` : '';
    return `${prefix}${levelWord} ${level}`;
  }

  let visible = $derived(!!preview?.active && (preview?.anchors?.length ?? 0) > 0);

  let levelWord = $derived(t('resonance.previewLevelWord', 'niv.'));

  let ariaLabel = $derived.by(() => {
    if (!visible || !preview?.active) return '';
    const levelPart = buildLevelPartPlain(preview.capPrestige, preview.capLevel, levelWord);
    return t('resonance.previewTitle', 'Résonance {cap} ({levelPart})', {
      cap: preview.capSimLevel,
      levelPart,
    });
  });

  let tooltipHandlers = $derived.by(() => {
    trackGameLanguage();
    const gm = game as GameRuntime | null;
    const p = preview;
    if (!gm || !p?.active) return null;
    return touchTooltipHandlers(() => ({
      title: buildResonanceTooltipTitle(gm, p),
      body: buildResonanceTooltipBody(gm, p),
    }));
  });
</script>

{#if visible && preview && tooltipHandlers}
  <div
    class="resonance-anchors-preview"
    role="button"
    tabindex="0"
    aria-label={ariaLabel}
    onmouseenter={tooltipHandlers.onmouseenter}
    onmouseleave={tooltipHandlers.onmouseleave}
    onfocus={tooltipHandlers.onfocus}
    onblur={tooltipHandlers.onblur}
    onclick={tooltipHandlers.onclick}
    onkeydown={tooltipHandlers.onkeydown}
  >
    {#each preview.anchors as anchor (anchor.uid)}
      <img
        class="resonance-anchor-sprite"
        src={anchor.spriteUrl || GEN5_SUBSTITUTE_SPRITE}
        alt={anchor.displayName}
        draggable="false"
        loading="lazy"
        decoding="async"
      />
    {/each}
  </div>
{/if}
