/** Map a pre-renumber Hoenn zone id to the new sequential id (no-op if already current). */
export function remapHoennLegacyZoneId(zoneId: number): number {
    if (!Number.isFinite(zoneId)) return zoneId;
    const mapped = HOENN_ZONE_ID_REMAP[zoneId];
    return mapped != null ? mapped : zoneId;
}

/** Stable Hoenn ids unchanged by the pre-v2 refonte (201–204, 260–264). */
function isStableHoennV2ZoneId(zoneId: number): boolean {
    return (zoneId >= 201 && zoneId <= 204) || (zoneId >= 260 && zoneId <= 264);
}

function isStableHoennV3ZoneId(zoneId: number): boolean {
    return zoneId >= 201 && zoneId <= 206;
}

/**
 * True when a save still uses a pre-refonte Hoenn zone id (key in REMAP, not stable).
 * Canonical new-layout ids (e.g. Mauville 220 = 200+20) are not remapped once hoennZonesLayoutV2 is set.
 */
export function shouldRemapLegacyHoennZoneId(zoneId: number): boolean {
    if (!Number.isFinite(zoneId) || isStableHoennV2ZoneId(zoneId)) return false;
    return Object.prototype.hasOwnProperty.call(HOENN_ZONE_ID_REMAP, zoneId);
}

export function remapHoennLayoutV3ZoneId(zoneId: number): number {
    if (!Number.isFinite(zoneId)) return zoneId;
    const mapped = HOENN_LAYOUT_V3_REMAP[zoneId];
    return mapped != null ? mapped : zoneId;
}

export function shouldRemapHoennLayoutV3ZoneId(zoneId: number): boolean {
    if (!Number.isFinite(zoneId) || isStableHoennV3ZoneId(zoneId)) return false;
    return Object.prototype.hasOwnProperty.call(HOENN_LAYOUT_V3_REMAP, zoneId);
}

/** @deprecated Prefer shouldRemapLegacyHoennZoneId for migration guards. */
export function isLegacyHoennZoneId(zoneId: number): boolean {
    return shouldRemapLegacyHoennZoneId(zoneId);
}

type ZoneProgressLike = {
    pokemonTiers?: Record<string, number>;
    bossesDefeated?: number;
    epicsDefeated?: number;
    trainersDefeated?: number;
    combatsWon?: number;
};

function mergeZoneProgressEntries(target: ZoneProgressLike, source: ZoneProgressLike): ZoneProgressLike {
    const tiers = { ...(target.pokemonTiers || {}) };
    const srcTiers = source.pokemonTiers || {};
    Object.keys(srcTiers).forEach(function (name) {
        const prev = Number(tiers[name]) || 0;
        const next = Number(srcTiers[name]) || 0;
        tiers[name] = Math.max(prev, next);
    });
    return {
        pokemonTiers: tiers,
        bossesDefeated: Math.max(Number(target.bossesDefeated) || 0, Number(source.bossesDefeated) || 0),
        epicsDefeated: Math.max(Number(target.epicsDefeated) || 0, Number(source.epicsDefeated) || 0),
        trainersDefeated: Math.max(Number(target.trainersDefeated) || 0, Number(source.trainersDefeated) || 0),
        combatsWon: Math.max(Number(target.combatsWon) || 0, Number(source.combatsWon) || 0),
    };
}

/** Remap legacy Hoenn zoneProgress keys (old id → new id, merge on collision). */
export function migrateHoennZoneProgressKeys(
    zoneProgress: Record<string, ZoneProgressLike>,
): void {
    const pending: Array<{ oldKey: string; newKey: string; entry: ZoneProgressLike }> = [];
    Object.keys(zoneProgress).forEach(function (key) {
        const oldId = Number(key);
        if (!Number.isFinite(oldId) || !shouldRemapLegacyHoennZoneId(oldId)) return;
        const newId = remapHoennLegacyZoneId(oldId);
        if (newId === oldId) return;
        const entry = zoneProgress[key];
        if (!entry) return;
        pending.push({ oldKey: key, newKey: String(newId), entry });
    });
    pending.forEach(function ({ oldKey, newKey, entry }) {
        const existing = zoneProgress[newKey];
        if (existing) {
            zoneProgress[newKey] = mergeZoneProgressEntries(existing, entry);
        } else {
            zoneProgress[newKey] = entry;
        }
        delete zoneProgress[oldKey];
    });
}

function migrateHoennZoneProgressKeysV3(
    zoneProgress: Record<string, ZoneProgressLike>,
): void {
    const pending: Array<{ oldKey: string; newKey: string; entry: ZoneProgressLike }> = [];
    Object.keys(zoneProgress).forEach(function (key) {
        const oldId = Number(key);
        if (!Number.isFinite(oldId) || !shouldRemapHoennLayoutV3ZoneId(oldId)) return;
        const newId = remapHoennLayoutV3ZoneId(oldId);
        if (newId === oldId) return;
        const entry = zoneProgress[key];
        if (!entry) return;
        pending.push({ oldKey: key, newKey: String(newId), entry });
    });
    pending.forEach(function ({ oldKey, newKey, entry }) {
        const existing = zoneProgress[newKey];
        if (existing) {
            zoneProgress[newKey] = mergeZoneProgressEntries(existing, entry);
        } else {
            zoneProgress[newKey] = entry;
        }
        delete zoneProgress[oldKey];
    });
}

/** Remap legacy Hoenn zone ids in save payload fields (load + export normalization). */
export function migrateHoennZoneIdsInSavePayload(data: {
    hoennZonesLayoutV2?: boolean;
    hoennZonesLayoutV3?: boolean;
    currentZone?: number;
    maxReachedZone?: number;
    maxReachedZoneByRegion?: Record<string, number>;
    zoneProgress?: Record<string, ZoneProgressLike>;
}): void {
    if (data.hoennZonesLayoutV2 !== true) {
        if (data.currentZone != null && shouldRemapLegacyHoennZoneId(Number(data.currentZone))) {
            data.currentZone = remapHoennLegacyZoneId(Number(data.currentZone));
        }
        if (data.maxReachedZone != null && shouldRemapLegacyHoennZoneId(Number(data.maxReachedZone))) {
            data.maxReachedZone = remapHoennLegacyZoneId(Number(data.maxReachedZone));
        }
        if (data.maxReachedZoneByRegion && data.maxReachedZoneByRegion.hoenn != null) {
            const hoennMax = Number(data.maxReachedZoneByRegion.hoenn);
            if (Number.isFinite(hoennMax) && shouldRemapLegacyHoennZoneId(hoennMax)) {
                data.maxReachedZoneByRegion.hoenn = remapHoennLegacyZoneId(hoennMax);
            }
        }
        if (data.zoneProgress && typeof data.zoneProgress === 'object') {
            migrateHoennZoneProgressKeys(data.zoneProgress);
        }
        data.hoennZonesLayoutV2 = true;
    }

    if (data.hoennZonesLayoutV3 === true) return;

    if (data.currentZone != null && shouldRemapHoennLayoutV3ZoneId(Number(data.currentZone))) {
        data.currentZone = remapHoennLayoutV3ZoneId(Number(data.currentZone));
    }
    if (data.maxReachedZone != null && shouldRemapHoennLayoutV3ZoneId(Number(data.maxReachedZone))) {
        data.maxReachedZone = remapHoennLayoutV3ZoneId(Number(data.maxReachedZone));
    }
    if (data.maxReachedZoneByRegion && data.maxReachedZoneByRegion.hoenn != null) {
        const hoennMax = Number(data.maxReachedZoneByRegion.hoenn);
        if (Number.isFinite(hoennMax) && shouldRemapHoennLayoutV3ZoneId(hoennMax)) {
            data.maxReachedZoneByRegion.hoenn = remapHoennLayoutV3ZoneId(hoennMax);
        }
    }
    if (data.zoneProgress && typeof data.zoneProgress === 'object') {
        migrateHoennZoneProgressKeysV3(data.zoneProgress);
    }
    data.hoennZonesLayoutV3 = true;
}

