/** Remap legacy map hotspot id to current layout v3 zone id. */
export function remapHoennMapHotspotId(oldId: number): number {
    let id = oldId;
    if (!(id >= 201 && id <= 204) && !(id >= 260 && id <= 264)) {
        id = HOENN_ZONE_ID_REMAP[id] ?? id;
    }
    return HOENN_LAYOUT_V3_REMAP[id] ?? id;
}

