        219: 'Lavandia (Badge Dynamo)',
        220: 'Route 117',
        221: 'Route 111',
        222: 'Route 112',
        223: 'Chemin Ardent',
        224: 'Passe Jagged',
        225: 'Route 113',
        226: 'Vermilava (Badge Heat)',
        227: 'Route 114',
