        229: 'Chutes Météore',
        230: 'Clémenti-Ville (Badge Balance)',
        231: 'Nouveau Lavandia',
        232: 'Route 118',
        233: 'Route 119',
        234: 'Cimetronelle (Badge Feather)',
        235: 'Route 120',
