<script lang="ts">
  import { team } from '../stores/team.svelte.ts';
  import { game } from '../../gameManager.js';
  import { uiText } from '../ui/i18n.ts';
  import { _bindPensionDragDelegation } from '../ui/storageDisplay.ts';
  import CreatureCard from './CreatureCard.svelte';

  let listEl = $state<HTMLElement | null>(null);

  $effect(() => {
    const el = listEl;
    const gm = game;
    if (!el || !gm || team.maxPensionSlots === 0) return;

    el.classList.toggle('sprite-only-mode', team.teamSpritesOnly);
    _bindPensionDragDelegation(gm, el);
  });
</script>

{#if team.maxPensionSlots > 0}
  <div
    bind:this={listEl}
    class="team-list"
    id="pensionList"
    class:sprite-only-mode={team.teamSpritesOnly}
  >
    {#if team.pension.length === 0}
      <!-- svelte-ignore a11y_no_static_element_interactions -->
      <div
        class="pension-drop-zone team-slot-empty"
        style="grid-column: 1 / -1; min-height: 80px; display: flex; align-items: center; justify-content: center; color: #9ca3af; font-size: 13px;"
        ondragover={(e) => {
          game?.onTeamDragOver(e);
          e.currentTarget.classList.add('team-drag-over');
        }}
        ondragleave={(e) => e.currentTarget.classList.remove('team-drag-over')}
        ondrop={(e) => {
          e.currentTarget.classList.remove('team-drag-over');
          game?.onDropOnPension(e);
        }}
      >
        {uiText('pension.dropHint', 'Drop a Pokemon here')}
      </div>
    {:else}
      {#each team.pension as creature, i (creature.uid)}
        <CreatureCard
          {creature}
          index={i}
          location="pension"
          teamSpritesOnly={team.teamSpritesOnly}
          pensionContributionLabel={team.labels.pensionContributionPrefix}
          levelShort={team.labels.levelShort}
          viewDetails={team.labels.viewDetails}
        />
      {/each}
    {/if}
  </div>
{/if}
