<script lang="ts">
  import { team } from '../stores/team.svelte.ts';
  import { game } from '../../gameManager.js';
  import type { GameRuntime } from '../types/game.js';
  import type { HeaderStatKey } from '../bus/snapshots.js';
  import { formatNumber, formatNumberHeader } from '../../formatters.js';

  const STAT_KEYS: HeaderStatKey[] = ['hp', 'attack', 'spattack', 'defense', 'spdefense', 'speed'];

  const STAT_I18N_KEYS: Record<HeaderStatKey, string> = {
    hp: 'header.statHp',
    attack: 'header.statAtk',
    spattack: 'header.statSpAtk',
    defense: 'header.statDef',
    spdefense: 'header.statSpDef',
    speed: 'header.statSpd',
  };

  const STAT_LABEL_FALLBACKS: Record<HeaderStatKey, string> = {
    hp: 'HP :',
    attack: 'ATK :',
    spattack: 'ATK SP :',
    defense: 'DEF :',
    spdefense: 'DEF SP :',
    speed: 'SPD :',
  };

  let statLabels = $derived.by((): Record<HeaderStatKey, string> => {
    const gm = game as GameRuntime | null;
    if (!gm) return { ...STAT_LABEL_FALLBACKS };
    void gm.language;
    const labels = { ...STAT_LABEL_FALLBACKS };
    for (const key of STAT_KEYS) {
      labels[key] = gm.t?.(STAT_I18N_KEYS[key]) ?? STAT_LABEL_FALLBACKS[key];
    }
    return labels;
  });

  function fmt(n: number): string {
    return formatNumber(n);
  }

  function fmtGain(n: number): string {
    return `+${formatNumberHeader(n)}/s`;
  }

  function idSuffix(key: HeaderStatKey): string {
    if (key === 'hp') return 'HP';
    if (key === 'attack') return 'Atk';
    if (key === 'spattack') return 'SpAtk';
    if (key === 'defense') return 'Def';
    if (key === 'spdefense') return 'SpDef';
    return 'Spd';
  }

  function gainSuffix(key: HeaderStatKey): string {
    if (key === 'hp') return 'HP';
    if (key === 'attack') return 'Attack';
    if (key === 'spattack') return 'SpAttack';
    if (key === 'defense') return 'Defense';
    if (key === 'spdefense') return 'SpDefense';
    return 'Speed';
  }
</script>

<div class="combat-stats-group">
  {#each STAT_KEYS as key (key)}
    {@const val = team.teamStats[key] ?? 0}
    {@const gain = team.passiveGainsPerSec[key] ?? 0}
    {@const boosted = team.headerStatBoosted[key]}
    <div
      class="stat-chip header-stat-chip"
      class:stat-chip-boosted={boosted}
      id="headerStat{idSuffix(key)}"
      data-stat={key}
    >
      <span class="stat-label">{statLabels[key]}</span>
      <span class="stat-value">{fmt(val)}</span>
      <span class="stat-chip-boost-icon" title="">+</span>
      <span class="stat-sub-info">(<span id="player{gainSuffix(key)}Gain">{fmtGain(gain)}</span>)</span>
    </div>
  {/each}
</div>
