<script lang="ts">
  import { miltankFarm } from '../stores/miltankFarm.svelte.ts';
  import {
    guardianOverworldStyleString,
    hasGuardianOverworldSprites,
  } from '../lib/guardianOverworldSprites.ts';
  import MiltankGuardianPicker from './MiltankGuardianPicker.svelte';
  import { game } from '../../gameManager.ts';

  let snap = $derived(miltankFarm.snapshot);
  let sprites = $derived(snap.pastureSprites);
  let threats = $derived(snap.activeThreatSprites);

  let engagePastureName = $derived(
    sprites.find((s) => s.uid === threats.find((t) => t.id === snap.pendingThreatEngageId)?.pastureUid)?.name
      ?? snap.ui.title,
  );
  let berryTree = $derived(snap.berryTree);
  let berryTreeVisible = $derived(snap.berryTreeVisible);
</script>

<div class="miltank-pasture-scene" role="region" aria-label={snap.ui.title}>
  {#if berryTreeVisible}
  <div class="berry-tree-hotspot-wrap">
    <button
      type="button"
      class="berry-tree-hotspot"
      data-action="openBerryTreeModal"
      title={berryTree.ui.title}
      aria-label={berryTree.ui.title}
    >
      {#if berryTree.hotspotStoredQty > 0}
        <span
          class="berry-tree-harvest-bubble"
          role="button"
          tabindex="0"
          data-action="claimBerryTreeHarvest"
          data-action-stop
          aria-label="{berryTree.ui.claimBtn} ({berryTree.hotspotStoredQty})"
        >{berryTree.hotspotStoredQty}</span>
      {/if}
      {#if berryTree.hasActiveCrop && berryTree.activeCrop?.berryIconUrl}
        <img
          class="berry-tree-hotspot-icon"
          src={berryTree.activeCrop.berryIconUrl}
          alt=""
          width="20"
          height="20"
        />
      {/if}
    </button>
    <button
      type="button"
      class="berry-tree-hotspot-btn"
      data-action="openBerryTreeModal"
      title={berryTree.ui.title}
      aria-label={berryTree.ui.title}
    >{berryTree.ui.hotspotBtnLabel}</button>
  </div>
  {/if}

  {#if snap.hasApproachingThreat && snap.ui.threatEngageHint}
    <p class="miltank-pasture-threat-hint">{snap.ui.threatEngageHint}</p>
  {/if}

  {#each threats as threat (threat.id)}
    {#if threat.phase === 'attacking'}
      <div
        class="miltank-pasture-threat-btn miltank-pasture-threat-attacking threat-face-{threat.approachFacing}"
        class:miltank-pasture-threat-arrived={threat.arrivedAtPasture}
        style="
          --threat-from-left: {threat.attackFromLeft}%;
          --threat-from-top: {threat.attackFromTop}%;
          --threat-to-left: {threat.attackToLeft}%;
          --threat-to-top: {threat.attackToTop}%;
          --threat-attack-duration: {threat.attackDurationMs ?? 2200}ms;
          --threat-attack-elapsed: {threat.attackElapsedMs ?? 0}ms;
          --threat-vanish-delay: {threat.threatVanishDelayMs ?? 0}ms;
          --threat-glow-duration: {threat.threatGlowDurationMs ?? 200}ms;
        "
        title={threat.label}
        role="img"
        aria-label={threat.label}
      >
        {#if hasGuardianOverworldSprites(threat.displaySpecies)}
          <span
            class="miltank-pasture-threat-sprite miltank-pasture-guardian-sprite"
            style={guardianOverworldStyleString(threat.displaySpecies, false)}
            aria-hidden="true"
          ></span>
        {:else if threat.spriteUrl}
          <img
            class="miltank-pasture-threat-fallback"
            src={threat.spriteUrl}
            alt=""
            width="32"
            height="32"
          />
        {/if}
      </div>
    {:else}
    <button
      type="button"
      class="miltank-pasture-threat-btn {threat.walkClass} threat-face-{threat.approachFacing}"
      style="--threat-progress: {threat.progress}"
      title={threat.label}
      data-action="requestFarmThreatEngage"
      data-arg={threat.id}
      aria-label={threat.label}
    >
      {#if hasGuardianOverworldSprites(threat.displaySpecies)}
        <span
          class="miltank-pasture-threat-sprite miltank-pasture-guardian-sprite"
          style={guardianOverworldStyleString(threat.displaySpecies, false)}
          aria-hidden="true"
        ></span>
      {:else if threat.spriteUrl}
        <img
          class="miltank-pasture-threat-fallback"
          src={threat.spriteUrl}
          alt=""
          width="32"
          height="32"
        />
      {/if}
      <span class="miltank-pasture-threat-label">{threat.label}</span>
    </button>
    {/if}
  {/each}

  {#each sprites as sprite (sprite.uid)}
    {#if sprite.hasGuardian && sprite.guardianWalkClass}
      <div
        class="miltank-pasture-guardian-btn {sprite.guardianWalkClass}"
        class:debuffed={sprite.debuffActive}
        class:guardian-repelled={sprite.recentRepelled}
        title={sprite.guardianName ?? sprite.guardianSpecies ?? ''}
        data-action="openMiltankFarmModalForPasture"
        data-arg={sprite.uid}
        role="img"
        aria-label={sprite.guardianName ?? sprite.guardianSpecies ?? ''}
      >
        {#if sprite.guardianSpecies && hasGuardianOverworldSprites(sprite.guardianSpecies)}
          <span
            class="miltank-pasture-guardian-sprite"
            class:shiny={sprite.guardianShiny}
            style={guardianOverworldStyleString(sprite.guardianSpecies, sprite.guardianShiny)}
            aria-hidden="true"
          ></span>
        {:else if sprite.guardianSpriteUrl}
          <span class="miltank-pasture-guardian-fallback">
            <img
              src={sprite.guardianSpriteUrl}
              alt=""
              width="32"
              height="32"
            />
          </span>
        {/if}
        {#if sprite.recentRepelled}
          <span class="miltank-pasture-guardian-repelled-badge" title={sprite.repelledLabel ?? ''}>🛡</span>
        {/if}
      </div>
    {/if}

    <button
      type="button"
      class="miltank-pasture-sprite-btn {sprite.walkClass}"
      class:can-claim={sprite.canClaim}
      class:debuffed={sprite.debuffActive}
      class:rocket-theft={sprite.recentTheft}
      class:threat-hit-pending={sprite.threatHitGlowDelayMs != null}
      class:selected={sprite.isSelected}
      style={sprite.threatHitGlowDelayMs != null
        ? `--threat-hit-delay: ${sprite.threatHitGlowDelayMs}ms; --threat-glow-duration: ${threats.find((t) => t.phase === 'attacking' && t.pastureUid === sprite.uid)?.threatGlowDurationMs ?? 200}ms`
        : undefined}
      data-action="openMiltankFarmModalForPasture"
      data-arg={sprite.uid}
      aria-label="{sprite.name} — {snap.ui.title}"
      aria-pressed={sprite.isSelected}
    >
      {#if sprite.unprotected}
        <span class="miltank-pasture-unprotected" title={snap.ui.threatUnprotected}>!</span>
      {/if}
      <span
        class="miltank-pasture-sprite"
        class:shiny={sprite.shiny}
        role="img"
        aria-hidden="true"
      ></span>
      {#if sprite.debuffActive}
        <span class="miltank-pasture-debuff-badge" title={sprite.debuffLabel ?? ''}>🩹</span>
      {/if}
      {#if sprite.canClaim}
        <span
          class="miltank-pasture-milk-bubble"
          role="button"
          tabindex="0"
          data-action="claimPastureMilk"
          data-action-stop
          data-arg={sprite.uid}
          aria-label="{snap.ui.claimBtn} ({sprite.storedMilk})"
        >{sprite.storedMilk}</span>
      {/if}
      {#if sprite.requestItemIconUrl}
        <span class="miltank-pasture-request-icon" title={snap.ui.requestLabel}>
          <img
            src={sprite.requestItemIconUrl}
            alt=""
            class="item-sprite-img"
            width="24"
            height="24"
            loading="lazy"
            decoding="async"
          />
        </span>
      {/if}
      <span class="miltank-pasture-name">{sprite.name}</span>
      <span class="miltank-pasture-meta">
        <span class="miltank-pasture-level">Lv.{sprite.level}</span>
        <span class="miltank-pasture-satiety-mini">{sprite.satiety}/{sprite.satietyMax}</span>
      </span>
      {#if sprite.storedMilk < sprite.stockCap}
        <span
          class="miltank-pasture-milk-cycle"
          title={sprite.nextMilkLabel ?? ''}
        >
          <span class="miltank-pasture-milk-cycle-bar" role="progressbar" aria-valuenow={sprite.milkCyclePct} aria-valuemin="0" aria-valuemax="100">
            <span class="miltank-pasture-milk-cycle-fill" style="width: {sprite.milkCyclePct}%"></span>
          </span>
          <span class="miltank-pasture-milk-cycle-label">{sprite.milkCyclePct}%</span>
        </span>
      {/if}
      <span class="miltank-pasture-rate">{sprite.milkPerHour.toFixed(3)}{snap.ui.perHour}</span>
      {#if sprite.debuffLabel}
        <span class="miltank-pasture-debuff-label">{sprite.debuffLabel}</span>
      {/if}
    </button>
  {/each}
</div>

{#if snap.pendingThreatEngageId}
  <MiltankGuardianPicker
    mode="combat"
    threatId={snap.pendingThreatEngageId}
    pastureUid={threats.find((t) => t.id === snap.pendingThreatEngageId)?.pastureUid ?? snap.selectedPastureUid}
    pastureName={engagePastureName}
    candidates={snap.threatCombatCandidates}
    hasGuardian={false}
    guardianName={null}
    guardianSpriteUrl={null}
    ui={snap.ui}
    open={true}
    onClose={() => game?.cancelFarmThreatEngage()}
  />
{/if}
