<script lang="ts">
  import { game } from '../../gameManager.ts';
  import type { GameRuntime } from '../types/game.js';
  import {
    getDynamaxUpgradeLevel,
    getDynamaxUpgradeProgress,
  } from '../lib/dynamaxLogic.ts';
  import { useGameLanguageTick } from '../lib/useGameLanguageTick.svelte.ts';
  import { useFacadeSubscription } from '../lib/useFacadeSubscription.ts';
  import { GameEventType as Evt } from '../bus/events.js';
  import { formatNumber } from '../../formatters.ts';
  import DynamaxUpgradeModal from './DynamaxUpgradeModal.svelte';

  const { trackGameLanguage } = useGameLanguageTick();

  let upgradeOpen = $state(false);
  let progressTick = $state(0);

  useFacadeSubscription(
    [Evt.RESOURCES_CHANGED, Evt.BAG_CHANGED, Evt.TEAM_CHANGED, Evt.STATE_UPDATED],
    () => {
      progressTick += 1;
    },
  );

  function t(key: string, fallback: string, params?: Record<string, string | number>): string {
    const gm = game as GameRuntime | null;
    if (!gm?.t) {
      let out = fallback;
      if (params) {
        for (const [k, v] of Object.entries(params)) {
          out = out.replace(`{${k}}`, String(v));
        }
      }
      return out;
    }
    let got = gm.t(key, params);
    if (!got || got === key) got = fallback;
    if (params) {
      for (const [k, v] of Object.entries(params)) {
        got = got.replace(`{${k}}`, String(v));
      }
    }
    return got;
  }

  let visible = $derived.by(() => {
    void progressTick;
    trackGameLanguage();
    const gm = game as GameRuntime | null;
    return !!(gm?.dynamaxState?.unlocked);
  });

  let configured = $derived.by(() => {
    void progressTick;
    const gm = game as GameRuntime | null;
    return gm?.dynamaxState?.configured === true;
  });

  let upgradeLevel = $derived.by(() => {
    void progressTick;
    trackGameLanguage();
    const gm = game as GameRuntime | null;
    return gm ? getDynamaxUpgradeLevel(gm) : 0;
  });

  let progress = $derived.by(() => {
    void progressTick;
    trackGameLanguage();
    const gm = game as GameRuntime | null;
    if (!gm) {
      return getDynamaxUpgradeProgress({
        dynamaxState: { unlocked: false, configured: false, upgradeLevel: 0 },
        money: 0,
        items: {},
      } as GameRuntime);
    }
    return getDynamaxUpgradeProgress(gm);
  });

  function confirmBand(): void {
    const gm = game as GameRuntime | null;
    if (!gm?.confirmDynamaxBand) return;
    gm.confirmDynamaxBand();
    progressTick += 1;
  }

  function openUpgrade(): void {
    if (!configured) return;
    upgradeOpen = true;
  }
</script>

{#if visible}
  <div class="dynamax-band-panel" id="dynamaxBandPanel">
    {#if configured}
      <button
        type="button"
        class="dynamax-band-title dynamax-band-title--clickable"
        id="dynamaxBandTitle"
        onclick={openUpgrade}
      >
        {t('dynamax.title', 'Bande Dynamax')}
        <span class="dynamax-band-level">
          {t('dynamax.levelShort', 'Niv. {level}', { level: upgradeLevel })}
        </span>
      </button>
    {:else}
      <h3 class="dynamax-band-title" id="dynamaxBandTitle">
        {t('dynamax.title', 'Bande Dynamax')}
      </h3>
    {/if}
    <p class="dynamax-band-hint">
      {t('dynamax.hint', 'Une activation Dynamax (compte) : PV et dégâts boostés pendant la fenêtre — clique le titre pour améliorer (items d’évolution + $).')}
    </p>
    {#if configured}
      <div class="dynamax-band-progress-rows">
        <div class="dynamax-band-progress-row">
          <span class="dynamax-band-progress-label">
            {#if progress.atMax}
              {t('dynamax.progressMoneyMax', 'Pokédollars (max)')}
            {:else}
              {t('dynamax.progressMoney', 'Pokédollars {have} / {need}', {
                have: formatNumber(progress.moneyHave),
                need: formatNumber(progress.moneyNeed ?? 0),
              })}
            {/if}
          </span>
          <span
            class="ultimate-slot-pick-tooltip-bar dynamax-band-progress-bar"
            role="progressbar"
            aria-valuemin={0}
            aria-valuemax={100}
            aria-valuenow={Math.round(progress.moneyPct * 100)}
          >
            <span
              class="ultimate-slot-pick-tooltip-bar-fill dynamax-band-progress-fill--money"
              style={`width: ${Math.round(progress.moneyPct * 100)}%`}
            ></span>
          </span>
        </div>
        <div class="dynamax-band-progress-row">
          <span class="dynamax-band-progress-label">
            {#if progress.atMax}
              {t('dynamax.progressItemsMax', 'Items d’évo. (max)')}
            {:else}
              {t('dynamax.progressItems', 'Items d’évo. {have} / {need}', {
                have: formatNumber(progress.itemsHave),
                need: formatNumber(progress.itemsNeed ?? 0),
              })}
            {/if}
          </span>
          <span
            class="ultimate-slot-pick-tooltip-bar dynamax-band-progress-bar"
            role="progressbar"
            aria-valuemin={0}
            aria-valuemax={100}
            aria-valuenow={Math.round(progress.itemsPct * 100)}
          >
            <span
              class="ultimate-slot-pick-tooltip-bar-fill dynamax-band-progress-fill--items"
              style={`width: ${Math.round(progress.itemsPct * 100)}%`}
            ></span>
          </span>
        </div>
      </div>
      <p class="dynamax-band-status">{t('dynamax.ready', 'Bande prête.')}</p>
    {:else}
      <button type="button" class="dynamax-band-confirm-btn" onclick={confirmBand}>
        {t('dynamax.confirm', 'Activer la bande')}
      </button>
    {/if}
  </div>
{/if}

<DynamaxUpgradeModal bind:open={upgradeOpen} />

