/**
 * @file feticheSystem.ts
 * Pokémon Fétiche companion — modal, feed, tick, gains/s hook.
 */

import type { GameRuntime } from './src/types/game.js';
import {
    chooseFeticheSpecies,
    feedFeticheBerry,
    getSpeciesElementTypes,
    getFeticheDisplaySpecies,
    normalizeFeticheState,
    tickFeticheState,
} from './src/lib/feticheLogic.ts';
import {
    buildFeticheSnapshot,
    ensureFeticheState,
    notifyFeticheChanged,
} from './src/lib/feticheSnapshot.ts';
import { publishTeamHeaderStatsChanged } from './src/bus/publishHooks.js';
import { isMasteryFetichePanelVisible } from './src/stores/masteryProfileTab.svelte.ts';
import { notifyBagChanged } from './src/lib/bagSnapshot.ts';
import { logMessage } from './src/ui/modals.ts';
import { BERRY_DEX_KEYS } from './constants/balance/berryTree.ts';
import { uiPokemonName } from '@card-ui/i18n';
import type { FeticheTaste } from './src/lib/feticheLogic.ts';

type GameThis = GameRuntime;

function isFeticheFeatureUnlocked(game: GameThis): boolean {
    return !!game.unlockedFeatures?.fetiche;
}

function feticheText(
    game: GameThis,
    key: string,
    fallbackFr: string,
    fallbackEn: string,
    vars: Record<string, string | number> = {},
): string {
    const lang = game && typeof game.normalizeLanguage === 'function'
        ? game.normalizeLanguage(game.language)
        : 'fr';
    if (typeof game.t === 'function') {
        const out = game.t(`fetiche.${key}`, vars);
        if (out && out !== `fetiche.${key}`) return out;
    }
    const template = lang === 'en' ? fallbackEn : fallbackFr;
    return template.replace(/\{(\w+)\}/g, (_, k: string) => String(vars[k] ?? `{${k}}`));
}

let lastMoodToastIndex = -1;

const FEED_TOAST_KEYS: Record<FeticheTaste, string> = {
    loved: 'feedLoved',
    liked: 'feedLiked',
    neutral: 'feedNeutral',
    disliked: 'feedDisliked',
    hated: 'feedHatedCramp',
};

const FEED_TOAST_FALLBACKS: Record<FeticheTaste, { fr: string; en: string }> = {
    loved: { fr: 'Adoré ! Ton Fétiche a adoré cette baie.', en: 'Loved it! Your favorite adored this berry.' },
    liked: { fr: 'Il aime bien cette baie.', en: 'They liked this berry.' },
    neutral: { fr: 'Baie acceptée.', en: 'Berry accepted.' },
    disliked: { fr: 'Il n\'aime pas trop cette baie…', en: 'They don\'t really like this berry…' },
    hated: { fr: 'Il déteste cette baie — mal au ventre !', en: 'They hate this berry — stomach cramp!' },
};

function showFeticheToast(game: GameThis, key: string, fallbackFr: string, fallbackEn: string): void {
    const msg = feticheText(game, key, fallbackFr, fallbackEn);
    if (typeof game.showToast === 'function') {
        game.showToast(msg);
    } else {
        logMessage(msg);
    }
}

export function tickFeticheLogic(game: GameThis, now = Date.now()): void {
    if (!isFeticheFeatureUnlocked(game)) return;
    const state = game.feticheState;
    if (!state?.speciesKey) return;
    const normalized = normalizeFeticheState(state, now);
    game.feticheState = normalized;
    const tick = tickFeticheState(normalized, now);
    if (tick.moodRotated && normalized.tasteMoodIndex !== lastMoodToastIndex) {
        lastMoodToastIndex = normalized.tasteMoodIndex;
        if (!isMasteryFetichePanelVisible() && typeof game.showToast === 'function') {
            game.showToast(feticheText(
                game,
                'moodChangedToast',
                'Ton Fétiche a changé d\'humeur !',
                'Your favorite Pokémon changed mood!',
            ));
        }
    }
    if (tick.evolved && typeof game.showToast === 'function') {
        const displayName = uiPokemonName(game, getFeticheDisplaySpecies(normalized));
        game.showToast(feticheText(
            game,
            'evolutionToast',
            '{name} a évolué !',
            '{name} evolved!',
            { name: displayName },
        ));
    }
    notifyFeticheChanged(game);
    if (tick.elapsedMs >= 1000) {
        publishTeamHeaderStatsChanged();
        if (typeof game.invalidateStatsCache === 'function') {
            game.invalidateStatsCache();
        }
    }
}

export function catchUpFeticheLogic(game: GameThis, missedTime: number): void {
    if (!game.feticheState?.speciesKey || missedTime <= 0) return;
    tickFeticheLogic(game, Date.now());
}

export function applyFeticheSystem(GameClass: { prototype: Record<string, unknown> }): void {
    'use strict';
    GameClass.prototype.openFetichePanel = function (this: GameThis) {
        if (!isFeticheFeatureUnlocked(this)) return;
        const state = ensureFeticheState(this);
        state.moodChangedPending = false;
        tickFeticheLogic(this, Date.now());
        notifyFeticheChanged(this, { force: true, visible: true });
    };

    GameClass.prototype.dismissFeticheOnboarding = function (this: GameThis) {
        if (!isFeticheFeatureUnlocked(this)) return;
        const state = ensureFeticheState(this);
        if (state.feticheOnboardingSeen) return;
        state.feticheOnboardingSeen = true;
        notifyFeticheChanged(this, { force: true, visible: true });
        this.saveGame?.({ reason: 'fetiche_onboarding' });
    };

    GameClass.prototype.openFeticheModal = async function (this: GameThis) {
        await this.openMasteryModal('fetiche');
    };

    GameClass.prototype.closeFeticheModal = function (this: GameThis) {
        this.closeMasteryModal();
    };

    GameClass.prototype.chooseFeticheSpecies = function (this: GameThis, speciesKey: string) {
        if (!isFeticheFeatureUnlocked(this)) return false;
        const state = ensureFeticheState(this);
        const result = chooseFeticheSpecies(state, speciesKey, this.pokedex ?? {}, Date.now());
        if (!result.ok) {
            if (result.reason === 'already_chosen') {
                logMessage(feticheText(this, 'errorAlreadyChosen', 'Choix déjà effectué.', 'Choice already made.'));
            } else if (result.reason === 'not_caught') {
                logMessage(feticheText(this, 'errorNotCaught', 'Espèce non capturée.', 'Species not caught.'));
            } else if (result.reason === 'legendary_not_allowed') {
                logMessage(feticheText(this, 'errorLegendary', 'Les légendaires ne peuvent pas être Fétiche.', 'Legendaries cannot be favorites.'));
            } else {
                logMessage(feticheText(this, 'errorInvalid', 'Espèce invalide.', 'Invalid species.'));
            }
            return false;
        }
        const displayName = uiPokemonName(this, speciesKey);
        logMessage(feticheText(
            this,
            'chosenToast',
            '{name} est ton Fétiche !',
            '{name} is your favorite!',
            { name: displayName },
        ));
        notifyFeticheChanged(this, { force: true });
        publishTeamHeaderStatsChanged();
        if (typeof this.invalidateStatsCache === 'function') this.invalidateStatsCache();
        if (typeof this.checkSpecialQuests === 'function') {
            this.checkSpecialQuests('fetiche_species_chosen');
        }
        this.saveGame?.({ reason: 'fetiche_choose' });
        return true;
    };

    GameClass.prototype.feedFeticheBerry = function (this: GameThis, berryKey: string) {
        if (!isFeticheFeatureUnlocked(this)) return false;
        const state = ensureFeticheState(this);
        if (!state.speciesKey) return false;
        const key = String(berryKey || '');
        if (!BERRY_DEX_KEYS.includes(key as typeof BERRY_DEX_KEYS[number])) return false;
        if ((Number(this.items?.[key]) || 0) < 1) {
            logMessage(feticheText(this, 'errorNoBerry', 'Baie insuffisante.', 'Not enough berries.'));
            return false;
        }
        const types = getSpeciesElementTypes(state.speciesKey);
        const result = feedFeticheBerry(state, key, types, Date.now());
        if (!result.ok) {
            if (result.reason === 'stomach_cramp') {
                logMessage(feticheText(this, 'errorCramp', 'Mal au ventre — attends un peu.', 'Stomach cramp — wait a bit.'));
            } else if (result.reason === 'satiety_full') {
                logMessage(feticheText(
                    this,
                    'satietyFull',
                    'Rassasié — cette baie dépasserait 100 de satiété.',
                    'Full — this berry would exceed 100 satiety.',
                ));
            }
            notifyFeticheChanged(this, { force: true });
            return false;
        }
        this.items[key] = Math.max(0, (Number(this.items[key]) || 0) - 1);
        notifyBagChanged(this);
        if (result.taste) {
            const fb = FEED_TOAST_FALLBACKS[result.taste];
            showFeticheToast(this, FEED_TOAST_KEYS[result.taste], fb.fr, fb.en);
        }
        if (result.leveledUp) {
            logMessage(feticheText(
                this,
                'levelUpToast',
                'Niveau {level} !',
                'Level {level}!',
                { level: state.level },
            ));
            publishTeamHeaderStatsChanged();
            if (typeof this.invalidateStatsCache === 'function') this.invalidateStatsCache();
        }
        if (result.evolved) {
            const displayName = uiPokemonName(this, getFeticheDisplaySpecies(state));
            const evolutionMsg = feticheText(
                this,
                'evolutionToast',
                '{name} a évolué !',
                '{name} evolved!',
                { name: displayName },
            );
            logMessage(evolutionMsg);
            if (typeof this.showToast === 'function') {
                this.showToast(evolutionMsg);
            }
            publishTeamHeaderStatsChanged();
            if (typeof this.invalidateStatsCache === 'function') this.invalidateStatsCache();
        }
        notifyFeticheChanged(this, { force: true });
        if (typeof this.checkSpecialQuests === 'function') {
            this.checkSpecialQuests('fetiche_berry_fed');
        }
        this.saveGame?.({ reason: 'fetiche_feed' });
        return true;
    };

    GameClass.prototype.getFeticheHeaderSnapshot = function (this: GameThis) {
        return buildFeticheSnapshot(this, false);
    };
}

export {
    openFeticheModalLogic,
    closeFeticheModalLogic,
    chooseFeticheSpeciesLogic,
    feedFeticheBerryLogic,
};

function openFeticheModalLogic(game: GameThis): Promise<void> {
    return game.openFeticheModal();
}

function closeFeticheModalLogic(game: GameThis): void {
    game.closeFeticheModal();
}

function chooseFeticheSpeciesLogic(game: GameThis, speciesKey: string): boolean {
    return game.chooseFeticheSpecies(speciesKey);
}

function feedFeticheBerryLogic(game: GameThis, berryKey: string): boolean {
    return game.feedFeticheBerry(berryKey);
}
