const HELD_ITEMS = _HELD_ITEMS as Record<string, Record<string, unknown>>;
const ZONES = _ZONES as Record<number, Record<string, unknown>>;
type GameCtor = { prototype: Record<string, unknown> };
type ThisGame = GameRuntime;
export function applyCombatSystem(GameClass: GameCtor): void {

    /**
     * Calculates pokedollar reward for a zone combat.
     * Used by both live finalizeCombat and offline processSimulatedVictory.
     * @param {Game} game
     * @param {number} zone - current zone index
     * @param {boolean} isBoss
     * @param {boolean} isEpic
     * @param {number} [trainerMult=1] - extra multiplier for gym trainers
     * @returns {number} final pokedollar amount before addCombatPokedollars
     */
    function calculateCombatPokedollars(game: ThisGame, zone: number, isBoss: boolean, isEpic: boolean, trainerMult?: number): number {
        let amount = Math.floor((zone * 20) + (Math.random() * zone * 10));
        if (trainerMult && trainerMult !== 1) amount = Math.floor(amount * trainerMult);
        if (isBoss) amount *= 5;
        else if (isEpic) amount *= 2;
        const collecteurBonus = game.getTalentStackBonus('collecteur');
        if (collecteurBonus > 0) amount = Math.floor(amount * (1 + collecteurBonus));
        const collGold = (game.getCollectionBonuses ? game.getCollectionBonuses() : {}).gold_mult || 0;
        const masteryGold = game.getMasteryBonus ? (game.getMasteryBonus('pokedollars_mult') || 0) : 0;
        const synGold = (game.getActiveSynergies ? game.getActiveSynergies() : {}).pokedollars_mult || 0;
        const fortuneBonus = 1 + game.getAccountTalentBonus('pokedollars_mult') + collGold + masteryGold + synGold;
        let upgradeBonus = 0;
        if (game.upgrades && game.upgrades.prizeMoney) {
            upgradeBonus = game.upgrades.prizeMoney.level * 0.01;
        }
        return Math.floor(amount * (fortuneBonus + upgradeBonus));
    }

    /**
     * Rolls boss egg rarity using shared thresholds.
     * @returns {string} RARITY value
     */
    function rollBossEggRarity(): string {
        const r = Math.random();
        const bal = BALANCE;
        if (r < bal.BOSS_EGG_ROLL_LEGENDARY) return RARITY.LEGENDARY;
        if (r < bal.BOSS_EGG_ROLL_EPIC) return RARITY.EPIC;
        return RARITY.RARE;
    }

    /**
     * Configuration centralisée du Mode Auto. Fallback défensif si BALANCE absent.
     * @returns {{COOLDOWN_MS:number,MIN_HP_PCT_ADVANTAGE:number,MIN_HP_PCT_DISADVANTAGE:number,MIN_HP_PCT_STAMINA:number,MIN_EFF_GAIN_DISADVANTAGE:number}}
     */
    function getAutoConfig(): { COOLDOWN_MS: number; MIN_HP_PCT_ADVANTAGE: number; MIN_HP_PCT_DISADVANTAGE: number; MIN_HP_PCT_STAMINA: number; MIN_EFF_GAIN_DISADVANTAGE: number } {
        return (BALANCE && BALANCE.AUTO_SWITCH) || {
            COOLDOWN_MS: 2000,
            MIN_HP_PCT_ADVANTAGE: 0.50,
            MIN_HP_PCT_DISADVANTAGE: 0.25,
            MIN_HP_PCT_STAMINA: 0.15,
            MIN_EFF_GAIN_DISADVANTAGE: 0.5,
        };
    }

    function _normalizeCombatStats(raw: PlayerMainStats | Record<string, number>): {
        speed: number; attack: number; spattack: number; defense: number; spdefense: number;
    } {
        return {
            speed: raw.speed ?? 0,
            attack: raw.attack ?? 0,
            spattack: raw.spattack ?? 0,
            defense: raw.defense ?? 0,
            spdefense: raw.spdefense ?? 0,
        };
    }

    /** Ratio PV [0..1] safe pour les Pokémon joueur (utilise maxHp ou stats.HP). */
    function _hpRatio(c: CreatureData | null | undefined): number {
        if (!c) return 0;
        const max = c.maxHp || (c.stats && (c.stats).HP) || 1;
        return Math.max(0, Math.min(1, (c.currentHp || 0) / max));
    }

    /**
     * Wrapper compat : tente un switch d'avantage. Préfère utiliser
     * game.attemptAutoSwitch('advantage') directement dans le nouveau code.
     */
    function tryAutoSwitchAdvantage(game: ThisGame): void {
        if (game && typeof game.attemptAutoSwitch === 'function') {
            game.attemptAutoSwitch('advantage');
        }
    }

    (globalThis as unknown as Record<string, unknown>).mergeSimulationResult = mergeSimulationResult;

    GameClass.prototype.getSpawnDelay = function (this: ThisGame): number {
        const baseDelay = (typeof GAME_SPEEDS !== 'undefined') ? GAME_SPEEDS.RESPAWN_DELAY : 2500;

        let level = 0;
        if (this.upgrades && this.upgrades.respawn) {
            level = this.upgrades.respawn.level;
        }

        const collectionBonus = (this.getCollectionBonuses ? this.getCollectionBonuses() : {}).respawn_delay_reduction || 0;
        const accountBonus = this.getAccountTalentBonus ? (this.getAccountTalentBonus('respawn_delay_reduction') || 0) : 0;
        const reduction = (level * BALANCE.RESPAWN_UPGRADE_REDUCTION_PER_LEVEL) + collectionBonus + accountBonus;

        return Math.max(BALANCE.RESPAWN_DELAY_MIN_MS, baseDelay - reduction);
    };

    GameClass.prototype.showUiFloatingText = function (this: ThisGame, elementId: string, text: string, type?: string): void {
        if (type === undefined) type = 'ft-money';
        const target = document.getElementById(elementId);
        if (!target) return;

        const rect = target.getBoundingClientRect();

        const el = document.createElement('div');
        el.className = `ui-floating-text ${type}`;
        el.textContent = text;

        el.style.left = `${rect.left + (rect.width / 2)}px`;
        el.style.top = `${rect.top}px`;

        el.style.transform = "translateX(-50%)";

        document.body.appendChild(el);

        setTimeout(() => {
            if (el.parentElement) el.remove();
        }, 1500);
    };

    GameClass.prototype.startCombat = function (this: ThisGame, forcedEnemy?: CreatureData): void {
        this.sessionStats.combatStartTime = Date.now();
        resetCombatTurnTally(this);
        this.faintedThisCombat = new Set();
        this.faintedUidsThisCombat = new Set();
        this._advancedEntrySwitchDone = false;
        prepareDynamaxForNewCombat(this);
        this.currentPlayerCreature = null;
        this.reflexActive = false;
        resetZRingCombatState(this);
        resetMasteryCombatState(this);
        // Reset des stacks de talents temporaires (Sentinelle / Berserker)
        if (Array.isArray(this.playerTeam)) {
            this.playerTeam.forEach(c => {
                if (!c) return;
                c.sentinelleStacks = 0;
                c.berserkStacks = 0;
                c._acharnementStacks = 0;
                c._acharnementLastTarget = null;
                c._secondSouffleUsed = false;
                if (c.passiveTalent === 'abri') c._abriReady = true;
                clearRetaliationState(c);
                clearRampageState(c as unknown as ICreature);
            });
        }
        if (typeof this.refreshDpsLiveOverlay === 'function') this.refreshDpsLiveOverlay();

        // Jauge méga : ne pas la réinitialiser ici. Chaque combat sauvage appelle startCombat() alors que
        // tour / arène entrent en combat sans ce chemin — une remise à zéro ici cassait la persistance en zone.
        // La jauge est vidée à l’activation méga (activateMegaEvolution) et suivie par combat.

        const farmThreatActive = !!(this.gymTrainerState?.active && this.gymTrainerState.isFarmThreat);
        const farmFighter = farmThreatActive
            ? (this as ThisGame & { _farmThreatFighter?: CreatureData | null })._farmThreatFighter ?? null
            : null;

        if (!this.gymTrainerState?.active) {
            const allPoolZero = this.playerTeam.every(c => (c.mainAccountCurrentHp || 0) <= 0);
            const anyCurrentAlive = this.playerTeam.some(c => (c.currentHp || 0) > 0);
            if (allPoolZero && anyCurrentAlive && typeof this.getPlayerMaxHp === 'function') {
                const pool = this.getPlayerMaxHp();
                this.playerTeam.forEach(c => { c.mainAccountCurrentHp = pool; });
            }
        }

        if (farmThreatActive) {
            if (!farmFighter) {
                abortFarmThreatCombat(this);
                this.combatState = 'waiting';
                this.lastCombatTime = Date.now();
                return;
            }
            resetFarmThreatFighterCombatStacks(farmFighter);
            clearRetaliationState(farmFighter);
            clearRampageState(farmFighter as unknown as ICreature);
            this.currentPlayerCreature = farmFighter;
        } else {
            const activeAtStart = arrayAt(this.playerTeam, this.activeCreatureIndex);
            if (activeAtStart?.isAlive?.()) {
                this.currentPlayerCreature = activeAtStart;
            } else {
                this.currentPlayerCreature = this.getFirstAliveCreature();
                if (this.currentPlayerCreature) {
                    this.activeCreatureIndex = this.playerTeam.indexOf(this.currentPlayerCreature);
                }
            }
        }

        if (!this.currentPlayerCreature) {
            this.combatState = 'dead';
            this.lastCombatTime = Date.now();
            this._applyActiveFirstAfterCombatIfNeeded();
            return;
        }

        Creature.setResonanceGameRef(this);
        this.currentPlayerCreature.recalculateStats!();

        this.currentPlayerCreature.actionGauge = 0;

        // Radar Pokédex : synchroniser la liste zone (toutes les espèces atteignables)
        if (this.refreshPokedexRadar) this.refreshPokedexRadar(false);

        let enemy = forcedEnemy;
        if (!enemy && farmThreatActive) {
            const gts = this.gymTrainerState;
            enemy = gts?.team?.[gts.currentIndex ?? 0] ?? gts?.team?.[0] ?? null;
        }
        this.currentEnemy = enemy || this.getOrCreateEnemy();
        if (!this.currentEnemy) {
            this.combatState = 'waiting';
            this.lastCombatTime = Date.now();
            return;
        }

        if (this.gymTrainerState && this.gymTrainerState.active) {
            if (this.gymTrainerState.isFarmThreat && farmFighter) {
                farmFighter.heal?.();
                farmFighter.clearStatusEffect?.();
                if (farmFighter.maxHp != null) {
                    farmFighter.currentHp = Math.min(farmFighter.maxHp, farmFighter.currentHp || farmFighter.maxHp);
                }
            } else {
                this.playerTeam.forEach(function (c) {
                    c.heal!();
                    c.clearStatusEffect!();
                    if (c.maxHp != null) {
                        c.currentHp = Math.min(c.maxHp, c.currentHp || c.maxHp);
                    }
                });
            }
        } else {
            this.currentPlayerCreature.mainAccountCurrentHp = this.getPlayerMaxHp();
        }
        if (this.currentPlayerCreature) {
            this.currentPlayerCreature._focusSashUsed = false;
            resetSubwayHeldBattleFlags(this.currentPlayerCreature as unknown as ICreature);
            if (typeof this.currentPlayerCreature.resetCombatStatStages === 'function') {
                this.currentPlayerCreature.resetCombatStatStages();
            }
        }
        if (this.currentEnemy) {
            this.currentEnemy._focusSashUsed = false;
            resetSubwayHeldBattleFlags(this.currentEnemy as unknown as ICreature);
            clearRetaliationState(this.currentEnemy);
            if (typeof this.currentEnemy.resetCombatStatStages === 'function') {
                this.currentEnemy.resetCombatStatStages();
            }
        }
        this.combatState = 'starting';
        syncMegaTimerWithCombatState(this);
        syncDynamaxTimerWithCombatState(this);
        ensureDynamaxHpScaleOnActive(this);
        this.combatStartTime = Date.now();
        if (hasActiveTeamSynergyOnGame(this) && typeof this.checkSpecialQuests === 'function') {
            this.checkSpecialQuests('synergyActive');
        }
        if (this.getCollectionBonusDetails && this.getCollectionBonusDetails().some((d: any) => d.isActive)) {
            this.checkSpecialQuests('collectionBonusActive');
        }

        logMessage(this.t('log.combatStartVs', { name: this.currentEnemy.name, level: this.currentEnemy.level }));

        if (this.currentEnemy) {
            applyHazardEntryTalentOnEnemyEntry(this as unknown as GameRuntime, this.currentEnemy);
        }

        if (this.currentPlayerCreature) {
            applyHazardEntryTalentOnPlayerEntry(
                this as unknown as GameRuntime,
                this.currentPlayerCreature as unknown as ICreature,
            );
        }

        // Switch d'avantage : uniquement à l'entrée en « fighting » (applyAdvantageSwitchIfEnabled
        // dans combatSystem.handleCombat). Ne pas appeler tryAutoSwitchAdvantage ici : un double
        // appel remplaçait le Pokémon actif deux fois et affichait une jauge ultime à 0 alors que
        // la charge persistait sur un autre slot d'équipe.

        // combat_start_ult : appliqué après switch d'avantage dans handleCombatLogic (combatSystem).
    };

    GameClass.prototype.refillTeamPp = function (this: ThisGame): void {
        if (!this.playerTeam || this.playerTeam.length === 0) return;
        for (const creature of this.playerTeam) {
            if (!creature || creature.isEnemy) continue;
            if (!creature.currentMoves || creature.currentMoves.length === 0) continue;
            if (!creature.movePp) creature.movePp = {};
            creature.currentMoves.forEach(name => {
                const def = getMoveDefinition(name);
                if (!creature.movePp[name]) {
                    const basePp = getBasePPForMove(def);
                    creature.movePp[name] = { current: basePp, max: basePp };
                }
                const entry = creature.movePp[name];
                entry.current = entry.max;
            });
        }
    };

    GameClass.prototype._applyPpRegenTick = function (this: ThisGame): void {
        if (!this.playerTeam || this.playerTeam.length === 0) return;
        for (const creature of this.playerTeam) {
            if (!creature || creature.isEnemy) continue;
            if (!creature.currentMoves || creature.currentMoves.length === 0) continue;
            if (!creature.movePp) creature.movePp = {};
            creature.currentMoves.forEach(name => {
                const def = getMoveDefinition(name);
                if (!creature.movePp[name]) {
                    const basePp = getBasePPForMove(def);
                    creature.movePp[name] = { current: basePp, max: basePp };
                }
                const entry = creature.movePp[name];
                if (entry.current < entry.max) entry.current++;
            });
        }
    };

    GameClass.prototype.fastForwardPpRegenTicks = function (this: ThisGame, tickCount: number): void {
        const n = Math.max(0, Math.min(200, Number(tickCount) || 0));
        for (let i = 0; i < n; i++) this._applyPpRegenTick();
        // PP is not shown on Svelte team cards — avoid TEAM_CHANGED churn (~1s tick).
    };

    GameClass.prototype.regenerateStamina = function (this: ThisGame): void {
        const now = Date.now();
        const regenTime = this.getStaminaRegenTime();

        if (now - this.lastStaminaRegen >= regenTime) {
            this.lastStaminaRegen = now;
            this._applyPpRegenTick();
            // PP is not shown on Svelte team cards — avoid TEAM_CHANGED churn (~1s tick).
        }
    };

    GameClass.prototype.incrementPlayerStats = function (this: ThisGame): void {
        const gain = this.getPassiveStatGainPerSecond();
        this.playerMainStats.hp += gain.hp;
        this.playerMainStats.attack += gain.attack;
        this.playerMainStats.spattack += gain.spattack;
        this.playerMainStats.defense += gain.defense;
        this.playerMainStats.spdefense += gain.spdefense;
        this.playerMainStats.speed += gain.speed;

        const batching = !!(this as ThisGame & { _batchingPassiveCatchup?: boolean })._batchingPassiveCatchup;
        if (!this.isOfflineSimulating && !batching) {
            this.updatePlayerStatsDisplay();
        }
    };

    GameClass.prototype.addCombatPokedollars = function (this: ThisGame, amount: number, source?: string): { net: number; withheld: number; injectedToBank?: number; creditedToWallet?: number } {
        if (source === undefined) source = 'combat';
        const raw = Math.max(0, Math.floor(Number(amount) || 0));
        if (raw <= 0) return { net: 0, withheld: 0 };

        let withheld = 0;
        const tr = this.teamRocketState || this.createDefaultTeamRocketState();
        if (tr.loan && shouldWithholdRocketDebt(tr.loan)) {
            const applied = applyDebtRepaymentToLoan(tr.loan, raw);
            withheld = applied.payment;
            if (applied.payment > 0 && typeof this.checkSpecialQuests === 'function') {
                this.checkSpecialQuests('rocket_loan_cycle', { amountRepaid: applied.payment });
            }
            if (applied.repaidFully) {
                this.handleRocketLoanRepaidIfNeeded(tr.loan);
            }
            this.teamRocketState = tr;
        }

        const net = Math.max(0, raw - withheld);
        let injectedToBank = 0;
        let creditedToWallet = net;
        const isCombatSource = (source === 'combat' || source === 'combat_simulated');
        const injectCombatHalf = !!(tr.bank && tr.bank.autoInjectCombatHalf);
        if (isCombatSource && injectCombatHalf) {
            const intendedInject = Math.floor(net * 0.5);
            const credit = typeof this.creditRocketBank === 'function'
                ? this.creditRocketBank(intendedInject)
                : { toBank: intendedInject, toWallet: 0 };
            injectedToBank = credit.toBank;
            creditedToWallet = Math.max(0, net - injectedToBank);
        }
        this.pokedollars += creditedToWallet;
        // Lifetime earnings (loan cap): gross before debt withholding.
        recordPokedollarsEarned(this, raw);
        this.checkSpecialQuests('pokedollars_gained');

        if (withheld > 0 && source !== 'silent') {
            logMessage(this.t('log.rocketWithheld', { amount: formatNumber(withheld) }));
        }
        if (withheld > 0 && this.isTeamRocketTabActive) {
            publishRocketRealtimeTick();
        }
        return { net, withheld, injectedToBank, creditedToWallet };
    };

    GameClass.prototype.findTypeForPokemon = function (this: ThisGame, name: string): string {
        if (!name) return 'normal';

        const rosterKey = resolveRosterSpeciesKey(name);

        for (const [, pool] of Object.entries(POKEMON_POOL)) {
            for (const [type, names] of Object.entries(pool)) {
                if (names.includes(rosterKey)) return type;
            }
        }

        if (typeof POKEMON_PRIMARY_TYPES !== 'undefined' && POKEMON_PRIMARY_TYPES && POKEMON_PRIMARY_TYPES[rosterKey]) {
            return POKEMON_PRIMARY_TYPES[rosterKey];
        }

        debugWarn(`Type inconnu pour ${name}, défaut: normal`);
        return 'normal';
    };

    // Statuts considérés comme buffs (s'appliquent au lanceur, pas à la cible)
    const SIM_BUFF_STATUSES = ['reinforced', 'agile', 'thorny', 'enraged', 'puncher'];

    /**
     * Applique l'effet d'un ultime déclenché côté offline.
     * Stocke les modificateurs (mult dégâts, lifesteal, multi-hit, recoil, def_pen)
     * sur la créature pour que l'attaque suivante les consomme.
     */
    function simulateUltimateActivation(game: ThisGame, caster: CreatureData, target: CreatureData): void {
        if (!caster || !caster.ultimateAbility) return;
        const ult = caster.ultimateAbility;

        // Choice items désactivent l'ult (mirror combatSystem behaviour via heldItem flag).
        const heldDef = (caster.heldItem && typeof HELD_ITEMS !== 'undefined') ? (HELD_ITEMS as Record<string, unknown>)[caster.heldItem] : null;
        if (heldDef && (heldDef as Record<string, unknown>).effect && ((heldDef as Record<string, unknown>).effect as Record<string, unknown>).disable_ultimate) return;

        caster.ultimateCharge = 0;

        // Reset des modifs offline
        type SimCaster = CreatureData & {
            _simUltMult: number;
            _simUltLifesteal: number;
            _simUltDefPen: number;
            _simUltHits: number;
            _simUltRecoil: number;
            _simUltActive: boolean;
        };
        const simCaster = caster as SimCaster;
        simCaster._simUltMult = 1.0;
        simCaster._simUltLifesteal = 0;
        simCaster._simUltDefPen = 0;
        simCaster._simUltHits = 1;
        simCaster._simUltRecoil = 0;
        simCaster._simUltActive = true;

        const sourceAtk = caster.isEnemy
            ? (caster.attack || 0)
            : (game.playerMainStats ? game.playerMainStats.attack : (caster.attack || 0));

        if (!ult.effect) return;
        switch (ult.effect.type) {
            case 'DAMAGE_MULT':
                simCaster._simUltMult = ult.effect.value || 1;
                break;
            case 'RANDOM_DAMAGE': {
                const _rmin = (typeof ult.effect.min === 'number') ? ult.effect.min : 1.0;
                const _rmax = (typeof ult.effect.max === 'number') ? ult.effect.max : (ult.effect.value || _rmin);
                simCaster._simUltMult = _rmin + Math.random() * Math.max(0, _rmax - _rmin);
                break;
            }
            case 'DAMAGE_AND_STATUS': {
                simCaster._simUltMult = ult.effect.value || 1;
                // Façade-style : si le lanceur a déjà un debuff, multiplie les dégâts
                if (ult.effect.statusBoostMult && ult.effect.statusBoostMult > 1
                    && caster.hasStatusEffect && caster.hasStatusEffect()) {
                    const _ursDebuffs = ['paralyzed', 'frozen', 'burned', 'poisoned', 'stunned', 'sleep', 'confused', 'scared'];
                    if (caster.statusEffect && _ursDebuffs.indexOf(caster.statusEffect.type) !== -1) {
                        simCaster._simUltMult *= ult.effect.statusBoostMult;
                    }
                }
                let atk = sourceAtk;
                if (ult.effect.statusMult && ult.effect.statusMult > 1) atk *= ult.effect.statusMult;
                {
                    // Les statuts buff doivent renforcer l'utilisateur de l'ulti et non sa cible.
                    const _isBuff = SIM_BUFF_STATUSES.indexOf(ult.effect.status!) !== -1;
                    const _stTarget = _isBuff ? caster : target;
                    if (_stTarget) {
                        if (_stTarget.hasStatusEffect && _stTarget.hasStatusEffect()) _stTarget.clearStatusEffect!();
                        _stTarget.applyStatusEffect!(ult.effect.status!, atk, caster);
                    }
                }
                if (ult.effect.selfHeal) {
                    const max = caster.isEnemy ? (caster.maxHp || 100)
                        : (game.getPlayerMaxHp ? game.getPlayerMaxHp() : (caster.maxHp || 100));
                    const heal = Math.floor(max * ult.effect.selfHeal);
                    if (caster.isEnemy) caster.currentHp = Math.min(max, (caster.currentHp || 0) + heal);
                    else caster.mainAccountCurrentHp = Math.min(max, (caster.mainAccountCurrentHp || 0) + heal);
                }
                break;
            }
            case 'LIFESTEAL':
                simCaster._simUltMult = ult.effect.value || 1;
                simCaster._simUltLifesteal = ult.effect.steal || 0;
                break;
            case 'DEFENSE_PENETRATION':
                simCaster._simUltMult = ult.effect.value || 1;
                simCaster._simUltDefPen = Math.min(0.75, Math.max(0, ult.effect.penetration || 0));
                break;
            case 'MULTI_HIT':
                simCaster._simUltMult = ult.effect.value || 1;
                simCaster._simUltHits = ult.effect.hits || 1;
                if (ult.effect.status) {
                    let _mhAtk = sourceAtk;
                    if (ult.effect.statusMult && ult.effect.statusMult > 1) _mhAtk *= ult.effect.statusMult;
                    const _isBuff = SIM_BUFF_STATUSES.indexOf(ult.effect.status) !== -1;
                    const _stTarget = _isBuff ? caster : target;
                    if (_stTarget) {
                        if (_stTarget.hasStatusEffect && _stTarget.hasStatusEffect()) _stTarget.clearStatusEffect!();
                        _stTarget.applyStatusEffect!(ult.effect.status, _mhAtk, caster);
                    }
                }
                break;
            case 'RECOIL':
                simCaster._simUltMult = ult.effect.value || 1;
                simCaster._simUltRecoil = ult.effect.recoil || 0;
                if (ult.effect.status) {
                    const _isBuff = SIM_BUFF_STATUSES.indexOf(ult.effect.status) !== -1;
                    const _stTarget = _isBuff ? caster : target;
                    if (_stTarget) {
                        if (_stTarget.hasStatusEffect && _stTarget.hasStatusEffect()) _stTarget.clearStatusEffect!();
                        _stTarget.applyStatusEffect!(ult.effect.status, sourceAtk, caster);
                    }
                }
                break;
            case 'DAMAGE_AND_STATUS_TYPE': {
                simCaster._simUltMult = ult.effect.value || 1;
                const stType = (TYPE_TO_STATUS as Record<string, string>)[caster.type];
                if (stType) {
                    const _isBuff = SIM_BUFF_STATUSES.indexOf(stType) !== -1;
                    const _stTarget = _isBuff ? caster : target;
                    if (_stTarget) {
                        if (_stTarget.hasStatusEffect && _stTarget.hasStatusEffect()) _stTarget.clearStatusEffect!();
                        _stTarget.applyStatusEffect!(stType, sourceAtk, caster);
                    }
                }
                break;
            }
            case 'MULTI_BUFF': {
                simCaster._simUltMult = ult.effect.value || 1;
                if (Array.isArray(ult.effect.status) && ult.effect.status.length > 0) {
                    let atk = sourceAtk;
                    if (ult.effect.statusMult && ult.effect.statusMult > 1) atk *= ult.effect.statusMult;
                    if (ult.effect.pickOne) {
                        // Tirage unique parmi TOUS les statuts (mélange buffs/debuffs).
                        // Cible déduite du type de statut tiré.
                        const statusPool = ult.effect.status.filter((s): s is string => typeof s === 'string');
                        const picked = statusPool[Math.floor(Math.random() * statusPool.length)];
                        if (!picked) break;
                        const _isBuff = SIM_BUFF_STATUSES.indexOf(picked) !== -1;
                        const tgt = _isBuff ? caster : (target || caster);
                        if (tgt.hasStatusEffect && tgt.hasStatusEffect()) tgt.clearStatusEffect!();
                        tgt.applyStatusEffect!(picked, atk, caster);
                    } else {
                        // Même contrainte qu'en combat réel : un seul statut par cible. On regroupe
                        // par cible et on en pioche un au hasard, en libérant le slot si nécessaire.
                        const selfList = ult.effect.status.filter((s): s is string => typeof s === 'string' && SIM_BUFF_STATUSES.indexOf(s) !== -1);
                        const foeList = ult.effect.status.filter((s): s is string => typeof s === 'string' && SIM_BUFF_STATUSES.indexOf(s) === -1);
                        const groups = [
                            { list: selfList, tgt: caster },
                            { list: foeList, tgt: target || caster }
                        ];
                        groups.forEach(g => {
                            if (!g.list.length || !g.tgt) return;
                            const picked = g.list[Math.floor(Math.random() * g.list.length)];
                            if (g.tgt.hasStatusEffect && g.tgt.hasStatusEffect()) g.tgt.clearStatusEffect!();
                            g.tgt.applyStatusEffect!(picked, atk, caster);
                        });
                    }
                }
                // NOTE : on garde _simUltActive=true même sans boost de dégâts pour que la
                // prochaine attaque du tour bloque le gain de charge (sinon Gengar/Vileplume/etc.
                // recharge ~25% plus vite que Pikachu et autres ultimes boost).
                break;
            }
            case 'HEAL': {
                const max = caster.isEnemy ? (caster.maxHp || 100)
                    : (game.getPlayerMaxHp ? game.getPlayerMaxHp() : (caster.maxHp || 100));
                const heal = Math.floor(max * (ult.effect.value || 0));
                if (caster.isEnemy) caster.currentHp = Math.min(max, (caster.currentHp || 0) + heal);
                else caster.mainAccountCurrentHp = Math.min(max, (caster.mainAccountCurrentHp || 0) + heal);
                // _simUltActive reste true : la prochaine attaque ne sera pas boostée
                // (mult=1 par défaut) mais on bloque le gain de charge sur ce tour.
                break;
            }
            case 'APPLY_STATUS': {
                const _isBuff = SIM_BUFF_STATUSES.indexOf(ult.effect.status!) !== -1;
                const _stTarget = _isBuff ? caster : target;
                if (_stTarget) {
                    if (_stTarget.hasStatusEffect && _stTarget.hasStatusEffect()) _stTarget.clearStatusEffect!();
                    _stTarget.applyStatusEffect!(ult.effect.status!, sourceAtk, caster);
                }
                // Idem : pas de boost à appliquer, mais on consomme bien le tour de charge.
                break;
            }
            default:
                simCaster._simUltMult = ult.effect.value || 1;
        }

        // Auto-debuff sur le lanceur (Porygon-Z, Regigigas) : appliqué après le switch
        if (ult.effect && ult.effect.selfStatus) {
            if (caster.hasStatusEffect && caster.hasStatusEffect()) caster.clearStatusEffect!();
            caster.applyStatusEffect!(ult.effect.selfStatus, sourceAtk, caster);
        }

        if (ult.effect && ult.effect.bonusCharge) {
            caster.ultimateCharge = Math.min(ult.chargeNeeded ?? 0, caster.ultimateCharge + (Number(ult.effect.bonusCharge) || 0));
        }

        if (!caster.isEnemy) {
            if (!game.stats || typeof game.stats !== 'object') (game as ThisGame).stats = {} as ThisGame['stats'];
            game.stats.ultimateUsed = (game.stats.ultimateUsed || 0) + 1;
        }
    }

    /**
     * Récupère les modifs ult posés par simulateUltimateActivation et les consomme.
     */
    function consumeSimUlt(creature: CreatureData): { mult: number; lifesteal: number; defPen: number; hits: number; recoil: number; wasUlt: boolean } {
        const simC = creature as Record<string, unknown>;
        const used = simC._simUltActive;
        const out = {
            mult: used ? (Number(simC._simUltMult) || 1) : 1,
            lifesteal: used ? (Number(simC._simUltLifesteal) || 0) : 0,
            defPen: used ? (Number(simC._simUltDefPen) || 0) : 0,
            hits: used ? (Number(simC._simUltHits) || 1) : 1,
            recoil: used ? (Number(simC._simUltRecoil) || 0) : 0,
            wasUlt: !!used
        };
        if (creature) (creature as Record<string, unknown>)._simUltActive = false;
        return out;
    }

    /**
     * Applique des dégâts à la créature joueur (zone) ou ennemie selon son type, et renvoie les dégâts effectivement appliqués.
     */
    function applySimDamage(game: ThisGame, creature: CreatureData, dmg: number): number {
        if (dmg <= 0) return 0;

        if (trySimAbriBlock(creature, dmg)) {
            return 0;
        }

        if (creature.isEnemy) {
            const prev = creature.currentHp || 0;
            creature.currentHp = Math.max(0, prev - dmg);
            const applied = prev - creature.currentHp;
            if (creature.passiveTalent === 'second_souffle') {
                applySimSecondSouffle(
                    game,
                    creature,
                    () => creature.currentHp || 0,
                    () => creature.maxHp || 100,
                    (heal) => { creature.currentHp = Math.min(creature.maxHp || 100, (creature.currentHp || 0) + heal); },
                );
            }
            return applied;
        }

        if (game._simTrainerBattle) {
            const prev = creature.currentHp ?? creature.mainAccountCurrentHp ?? 0;
            creature.currentHp = Math.max(0, prev - dmg);
            const applied = prev - (creature.currentHp ?? 0);
            applySimSecondSouffle(
                game,
                creature,
                () => creature.currentHp ?? creature.mainAccountCurrentHp ?? 0,
                () => creature.maxHp || 100,
                (heal) => {
                    const max = creature.maxHp || 100;
                    creature.currentHp = Math.min(max, (creature.currentHp ?? 0) + heal);
                },
            );
            return applied;
        }

        const prev = creature.mainAccountCurrentHp || 0;
        creature.mainAccountCurrentHp = Math.max(0, prev - dmg);
        const applied = prev - creature.mainAccountCurrentHp;
        applySimSecondSouffle(
            game,
            creature,
            () => creature.mainAccountCurrentHp || 0,
            () => (game.getPlayerMaxHp ? game.getPlayerMaxHp() : creature.maxHp || 100),
            (heal) => {
                const max = game.getPlayerMaxHp ? game.getPlayerMaxHp() : (creature.maxHp || 100);
                creature.mainAccountCurrentHp = Math.min(max, (creature.mainAccountCurrentHp || 0) + heal);
            },
        );
        return applied;
    }

    /** Registered for Creature.processStatusEffect DoT during offline sim. */
    function applySimDamageGlobal(
        game: GameRuntime,
        creature: CreatureData,
        dmg: number,
    ): number {
        if (!game.isOfflineSimulating) return 0;
        return applySimDamage(game as ThisGame, creature, dmg);
    }

    /**
     * Applique du soin à la créature, en respectant maxHp (zone pool pour le joueur).
     */
    function applySimHeal(game: ThisGame, creature: CreatureData, healRaw: number): number {
        if (healRaw <= 0) return 0;
        let heal = healRaw;
        if (!creature.isEnemy && typeof game.getActiveSynergies === 'function') {
            const hm = game.getActiveSynergies().heal_mult || 0;
            if (hm > 0) heal = Math.floor(heal * (1 + hm));
        }
        if (creature.isEnemy) {
            const max = creature.maxHp || 100;
            const prev = creature.currentHp || 0;
            creature.currentHp = Math.min(max, prev + heal);
            return creature.currentHp - prev;
        }
        if (game._simTrainerBattle) {
            const max = creature.maxHp || 100;
            const prev = creature.currentHp ?? creature.mainAccountCurrentHp ?? 0;
            creature.currentHp = Math.min(max, prev + heal);
            return (creature.currentHp ?? 0) - prev;
        }
        const max = game.getPlayerMaxHp ? game.getPlayerMaxHp() : (creature.maxHp || 100);
        const prev = creature.mainAccountCurrentHp || 0;
        creature.mainAccountCurrentHp = Math.min(max, prev + heal);
        return creature.mainAccountCurrentHp - prev;
    }

    /**
     * Renvoie les PV courants utilisés pour les calculs (zone pool pour le joueur).
     */
    function getSimCurrentHp(game: ThisGame, creature: CreatureData): number {
        if (creature.isEnemy) return creature.currentHp || 0;
        if (game._simTrainerBattle) return creature.currentHp ?? creature.mainAccountCurrentHp ?? 0;
        return creature.mainAccountCurrentHp || 0;
    }

    function getSimMaxHp(game: ThisGame, creature: CreatureData): number {
        if (creature.isEnemy) return creature.maxHp || 100;
        if (game._simTrainerBattle) return creature.maxHp || 100;
        return game.getPlayerMaxHp ? game.getPlayerMaxHp() : (creature.maxHp || 100);
    }

    function mergeSimPacingInto(target: SimPacingSnapshot, source: SimPacingSnapshot): void {
        target.wallMs += source.wallMs || 0;
        target.playerActions += source.playerActions || 0;
        target.enemyActions += source.enemyActions || 0;
        target.simTurns += source.simTurns || 0;
    }

    function attachPacingToResult(
        game: ThisGame,
        result: Record<string, unknown>
    ): Record<string, unknown> {
        const pacing = game._lastSimPacing as SimPacingSnapshot | undefined;
        if (pacing) {
            result.pacing = {
                wallMs: pacing.wallMs,
                playerActions: pacing.playerActions,
                enemyActions: pacing.enemyActions,
                simTurns: pacing.simTurns,
            };
        }
        return result;
    }

    /**
     * Choisit un move utilisable côté simulation offline en respectant
     * `requiresHpAbove` (Destruction / Explosion) et `requiresAllOtherMovesExhausted`
     * (Dernier Recours). Si le move par défaut est verrouillé, on tombe sur le premier
     * autre move du moveset utilisable ; sinon on garde le move d'origine.
     */
    function pickSimMoveRespectingGates(game: ThisGame, creature: CreatureData, defaultMoveName: string): string {
        const cur = getSimCurrentHp(game, creature);
        const max = getSimMaxHp(game, creature);
        const hpRatio = max > 0 ? (cur / max) : 1;

        const isBlocked = (name: string): boolean => {
            const d = getMoveDefinition(name);
            if (!d) return true;
            if (typeof d.requiresHpAbove === 'number' && hpRatio <= d.requiresHpAbove) return true;
            if (moveBlockedByExhaustionRule(creature, name, d)) return true;
            if (moveBlockedByRetaliationRule(creature, d)) return true;
            return false;
        };

        const forcedRampage = resolveForcedRampageMove(creature as unknown as ICreature);
        if (forcedRampage && !isBlocked(forcedRampage)) return forcedRampage;

        if (!isBlocked(defaultMoveName)) return defaultMoveName;

        const pool = (creature.currentMoves && creature.currentMoves.length) ? creature.currentMoves : [];
        for (const name of pool) {
            if (name === defaultMoveName) continue;
            if (!getMoveDefinition(name)) continue;
            if (isBlocked(name)) continue;
            if (!creature.isEnemy && creature.movePp) {
                const info = creature.movePp[name];
                if (info && info.current <= 0) continue;
            }
            return name;
        }
        return defaultMoveName;
    }

    function incrementBerserkerStack(creature: CreatureData | null | undefined): void {
        if (!creature || creature.passiveTalent !== 'berserker') return;
        if ((creature.berserkStacks || 0) >= 10) return;
        creature.berserkStacks = (creature.berserkStacks || 0) + 1;
    }

    function resetBerserkStacksForSimCombat(game: ThisGame, enemy: CreatureData): void {
        enemy.berserkStacks = 0;
        if (Array.isArray(game.playerTeam)) {
            game.playerTeam.forEach(c => { if (c) c.berserkStacks = 0; });
        }
    }

    /** Relais après KO en simulation zone (aligné sur pickNextCreatureAfterFaint live). */
    function applySimFaintRelay(
        game: ThisGame,
        previousEnemy: CreatureData | null
    ): { ok: true; player: CreatureData } | { ok: false } {
        const fainted = game.currentPlayerCreature;
        if (fainted) {
            fainted.berserkStacks = 0;
            fainted.sentinelleStacks = 0;
            if (trySimPhoenixRevive(game, fainted, !!game._simTrainerBattle)) {
                return { ok: true, player: fainted };
            }
            if (game.currentEnemy) {
                applyDerniereVolonteOnFaintSim(game, fainted, game.currentEnemy, (dmg) => {
                    game.currentEnemy!.currentHp = Math.max(0, (game.currentEnemy!.currentHp || 0) - dmg);
                });
            }
        }
        const faintedIdx = game.activeCreatureIndex;
        registerTeamFaintThisCombat(game, faintedIdx);
        applySimSentinelleOnAllyFaint(game.playerTeam, faintedIdx, game);
        const picked = pickNextCreatureAfterFaint(game);
        if (!picked) {
            game.processSimulatedDefeat();
            game.currentEnemy = previousEnemy;
            return { ok: false };
        }
        game.currentPlayerCreature = picked.creature as unknown as CreatureData;
        game.activeCreatureIndex = picked.index;
        const player = game.currentPlayerCreature;
        if (!player) {
            game.processSimulatedDefeat();
            game.currentEnemy = previousEnemy;
            return { ok: false };
        }
        if (game._simTrainerBattle) {
            player.currentHp = player.maxHp || player.currentHp || 0;
        } else {
            player.mainAccountCurrentHp = game.getPlayerMaxHp ? game.getPlayerMaxHp() : player.maxHp;
        }
        player.clearStatusEffect!();
        player._focusSashUsed = false;
        player._simUltActive = false;
        clearRetaliationState(player);
        if (typeof player.resetCombatStatStages === 'function') {
            player.resetCombatStatStages();
        }
        applyHazardEntryTalentOnPlayerSim(
            game as unknown as GameRuntime,
            player,
            (dmg) => applySimDamage(game, player, dmg),
        );
        return { ok: true, player };
    }

    function applySimulatedGymTrainerClear(
        game: ThisGame,
        lastEnemy: CreatureData
    ): Record<string, unknown> {
        const zoneKey = String(currentZone);
        const zpGym = game.zoneProgress?.[zoneKey];
        if (zpGym) {
            zpGym.trainersDefeated = (zpGym.trainersDefeated || 0) + 1;
        }

        game.stats.combatsWon = (game.stats.combatsWon || 0) + 1;
        if (typeof game._registerCombatWonForRecords === 'function') game._registerCombatWonForRecords();
        if (typeof game._recordDailyActivity === 'function') game._recordDailyActivity('combats', 1);
        const zpSim = game.zoneProgress?.[zoneKey];
        if (zpSim) {
            zpSim.combatsWon = (zpSim.combatsWon || 0) + 1;
        }
        game.checkAchievements('combatsWon');

        if (!game.isOfflineSimulating) {
            updateZoneInfo(game);
        }

        const balXp = BALANCE;
        const pokedollarsEarned = calculateCombatPokedollars(game, currentZone, false, false, 1.25);
        game.addCombatPokedollars(pokedollarsEarned, 'combat_simulated');
        const baseExpGain = Math.floor(
            lastEnemy.level * balXp.COMBAT_XP_MULT_NORMAL * balXp.GYM_TRAINER_XP_BONUS_MULT
        );
        const expGain = Math.floor(baseExpGain * game.getExpMultiplier());
        game.distributeCombatExp(expGain, { silent: true });

        const pensionRate = BALANCE.PENSION_EXP_RATIO + ((game.permanentBoosts && game.permanentBoosts.pensionXp) || 0);
        const pensionExpGain = Math.floor(expGain * pensionRate);
        if (pensionExpGain > 0 && game.pension && game.pension.length > 0) {
            game.pension.forEach(c => {
                c.gainExp!(pensionExpGain);
            });
        }

        return attachPacingToResult(game, {
            xp: expGain,
            money: pokedollarsEarned,
            items: {},
            captured: null,
        });
    }

    function returnSimCombatResult(
        game: ThisGame,
        result: Record<string, unknown> | null,
        previousEnemy: CreatureData | null
    ): Record<string, unknown> | null {
        game.currentEnemy = previousEnemy;
        if (game.isOfflineSimulating) {
            const pacing = game._lastSimPacing as SimPacingSnapshot | undefined;
            if (pacing && result) {
                result.pacing = {
                    wallMs: pacing.wallMs,
                    playerActions: pacing.playerActions,
                    enemyActions: pacing.enemyActions,
                    simTurns: pacing.simTurns,
                };
            }
        }
        return result;
    }

    function finishSimEnemyFaint(
        game: ThisGame,
        enemy: CreatureData,
        player: CreatureData,
        previousEnemy: CreatureData | null,
    ): { done: boolean; result: Record<string, unknown> | null } {
        if (trySimEnemyFaintBeforeVictory(
            game,
            enemy,
            (dmg) => applySimDamage(game, player, dmg),
        )) {
            return { done: false, result: null };
        }
        return {
            done: true,
            result: returnSimCombatResult(game, game.processSimulatedVictory(enemy), previousEnemy),
        };
    }

    /**
     * Offline zone combat simulator (ATB). Passive/ult parity matrix: src/lib/offlineTalentParityMatrix.ts
     */
    GameClass.prototype.simulateCombat = function (this: ThisGame): Record<string, unknown> | null {
        this._offlineAbortNoEnemy = false;
        resetCombatTurnTally(this);
        if (this.isOfflineSimulating) {
            this._lastSimPacing = createSimPacingState();
        }

        if (!this.currentPlayerCreature || !this.currentPlayerCreature.isAlive!()) {
            this.currentPlayerCreature = this.isOfflineSimulating
                ? this.getOfflinePreferredCreature()
                : this.getFirstAliveCreature();
            if (!this.currentPlayerCreature) return null;
        }

        // Tracking offline combats : 1 entrée par combat simulé (sauf boucle dresseur gym)
        if (this.isOfflineSimulating && !this._offlineGymTrainerMode
            && typeof this.ensureDpsOfflineBucket === 'function') {
            const off = this.ensureDpsOfflineBucket();
            off.combats = (off.combats || 0) + 1;
        }

        const enemy = this.getOrCreateEnemy();
        if (!enemy) {
            this._offlineAbortNoEnemy = true;
            return null;
        }
        enemy.currentHp = enemy.maxHp;
        enemy.clearStatusEffect!();
        enemy._focusSashUsed = false;
        enemy._simUltActive = false;
        clearRampageState(enemy as unknown as ICreature);
        resetBerserkStacksForSimCombat(this, enemy);
        resetSimCombatTalentState(this.playerTeam);

        // Auto-switch en simulation offline : advanced ou avantage classique.
        if (this.isOfflineSimulating
            && this.autoSelectEnabled
            && this.unlockedFeatures && this.unlockedFeatures.autoMode
            && !isPlayerUltReadyForAuto(this as unknown as GameRuntime)) {
            if (this.unlockedFeatures.autoFightAdvanced && this.autoSwitchAdvanced) {
                tryAdvancedOfflineEntrySwitch(this as unknown as GameRuntime);
            } else if (this.autoSwitchAdvantage
                && usesLegacyTypeAutoSwitch(this as unknown as GameRuntime)) {
                const newIdx = this._pickOfflineBestMatchup(enemy);
                if (newIdx >= 0 && newIdx !== this.activeCreatureIndex) {
                    this.activeCreatureIndex = newIdx;
                    this.currentPlayerCreature = arrayAt(this.playerTeam, newIdx) ?? null;
                }
            }
        }

        // Reset état combat sur la créature active (potentiellement remplacée ci-dessus)
        let player = this.currentPlayerCreature;
        if (!player) return null;
        if (!this._simTrainerBattle) {
            player.mainAccountCurrentHp = this.getPlayerMaxHp ? this.getPlayerMaxHp() : player.maxHp;
        }
        player.clearStatusEffect!();
        player._focusSashUsed = false;
        player._simUltActive = false;

        applyCombatStartUltIfEnabled(this as unknown as GameRuntime, { simTrainerOnly: true });

        const previousEnemy = this.currentEnemy;
        this.currentEnemy = enemy;

        const hazardResult = applyHazardEntryTalentOnEnemySim(
            this as unknown as GameRuntime,
            enemy,
            (dmg) => applySimDamage(this, enemy, dmg),
        );
        if (hazardResult?.isDead) {
            const faint = finishSimEnemyFaint(this, enemy, player, previousEnemy);
            if (faint.done) return faint.result;
        }

        // ─── Cache stats & bonus une seule fois (la team active ne change pas en plein combat) ───
        let playerStats = _normalizeCombatStats(this.getEffectiveStats());
        const collBonuses = this.getCollectionBonuses ? this.getCollectionBonuses() : {};
        const accDamage = this.getAccountTalentBonus ? (this.getAccountTalentBonus('damage_mult') || 0) : 0;
        const accReduction = this.getAccountTalentBonus ? (this.getAccountTalentBonus('damage_reduction') || 0) : 0;
        const accLifesteal = (this.getAccountTalentBonus ? (this.getAccountTalentBonus('life_steal') || 0) : 0)
            + (this.getMasteryBonus ? (this.getMasteryBonus('lifesteal_mult') || 0) : 0);
        const accUltCharge = this.getAccountTalentBonus ? (this.getAccountTalentBonus('ultimate_charge_bonus') || 0) : 0;
        const masterySpec = this.getMasteryArenaTowerCombatBonus ? (this.getMasteryArenaTowerCombatBonus() || 0) : 0;
        const masterySynergyDmg = this.getMasterySynergyDamageBonus ? (this.getMasterySynergyDamageBonus() || 0) : 0;
        const masteryDmg = (this.getMasteryBonus ? (this.getMasteryBonus('damage_mult') || 0) : 0) + masterySpec + masterySynergyDmg;
        const masteryRed = (this.getMasteryBonus ? (this.getMasteryBonus('damage_reduction') || 0) : 0) + masterySpec;
        const masteryFinisher = this.getMasteryBonus ? (this.getMasteryBonus('finisher_damage_mult') || 0) : 0;
        const masteryBossHunter = this.getMasteryBonus ? (this.getMasteryBonus('boss_hunter') || 0) : 0;
        const masteryIgnoreDef = this.getMasteryBonus ? (this.getMasteryBonus('ignore_defense_pct') || 0) : 0;
        const masteryUlt = this.getMasteryBonus ? (this.getMasteryBonus('ult_charge_mult') || 0) : 0;
        const masteryUltPersist = this.getMasteryBonus ? (this.getMasteryBonus('ult_persist_charge') || 0) : 0;
        const simTrainerBattle = !!this._simTrainerBattle;
        const towerBuffs = (this.towerState && this.towerState.isActive && this.towerState.buffs)
            ? (this.towerState.buffs as Record<string, number>)
            : null;
        const collDmg = collBonuses.damage_mult || 0;
        const collLifesteal = collBonuses.life_steal || 0;
        const collRegen = collBonuses.hp_regen_per_turn || 0;
        const upgradeExecutor = (this.upgrades && this.upgrades.executor) || 0;
        const upgradeElementMaster = (this.upgrades && this.upgrades.element_master) || 0;
        const playerDmgBonusMult = 1 + accDamage + collDmg + masteryDmg;
        const enemyDmgReductionMult = Math.max(0, 1 - accReduction - masteryRed);

        let simPlayerGauge = 0;
        let simEnemyGauge = 0;
        const bal = BALANCE;
        const threshold = bal.ATB_ACTION_THRESHOLD;

        let turns = 0;
        const maxTurns = bal.COMBAT_SIM_MAX_TURNS;

        while (turns < maxTurns) {
            turns++;

            const playerSpeed = playerStats.speed;
            const enemySpeed = enemy.speed * (enemy.getSpeedMultiplier ? enemy.getSpeedMultiplier(this) : 1);
            const safePSpeed = Math.max(0.001, playerSpeed);
            const safeESpeed = Math.max(0.001, enemySpeed);

            const ticksToPlayer = Math.max(0, threshold - simPlayerGauge) / safePSpeed;
            const ticksToEnemy = Math.max(0, threshold - simEnemyGauge) / safeESpeed;
            const timeJump = Math.min(ticksToPlayer, ticksToEnemy);

            simPlayerGauge += playerSpeed * timeJump + 0.01;
            simEnemyGauge += enemySpeed * timeJump + 0.01;

            const regenSec = convertSimTimeJumpToWallMs(timeJump, safePSpeed, safeESpeed) / 1000;
            if (regenSec > 0) {
                const pRegen = computeRegenerationTalentHeal(this, player, getSimMaxHp(this, player), regenSec);
                if (pRegen > 0) applySimHeal(this, player, pRegen);
                const eRegen = computeRegenerationTalentHeal(this, enemy, getSimMaxHp(this, enemy), regenSec);
                if (eRegen > 0) applySimHeal(this, enemy, eRegen);
            }

            // Quick Claw : si les deux sont prêts, l'item peut faire passer son porteur en premier (simple priorité d'ordre).
            if (simPlayerGauge >= threshold && simEnemyGauge >= threshold) {
                if (enemy.heldItem === 'quick_claw' && Math.random() < 0.25) {
                    const tmp = simPlayerGauge; simPlayerGauge = simEnemyGauge; simEnemyGauge = tmp;
                } else if (player.heldItem === 'quick_claw' && Math.random() < 0.25) {
                    // déjà dans cet ordre via la branche player en premier
                }
            }

            // ─────────────── PLAYER TURN ───────────────
            if (simPlayerGauge >= threshold) {
                if (this.isOfflineSimulating && this._lastSimPacing) {
                    const pacing = this._lastSimPacing as SimPacingSnapshot;
                    accumulateSimTimeJump(pacing, timeJump, safePSpeed, safeESpeed);
                    pacing.simTurns = turns;
                }
                simPlayerGauge -= threshold;
                recordCombatTurn(this, true);
                consumeNextActionSpeedBoost(player as unknown as ICreature);

                // Tick statut (DoT / durée)
                player.processStatusEffect?.(this);
                const trapTickPlayer = processPartialTrapTick(
                    player as unknown as ICreature,
                    this,
                    playerStats as Record<string, number>,
                    { silent: true },
                );
                if (trapTickPlayer.isDead) {
                    const relay = applySimFaintRelay(this, previousEnemy);
                    if (!relay.ok) return returnSimCombatResult(this, null, previousEnemy);
                    player = relay.player;
                    simPlayerGauge = 0;
                    playerStats = _normalizeCombatStats(this.getEffectiveStats());
                    continue;
                }
                if (getSimCurrentHp(this, player) <= 0) {
                    const relay = applySimFaintRelay(this, previousEnemy);
                    if (!relay.ok) return returnSimCombatResult(this, null, previousEnemy);
                    player = relay.player;
                    simPlayerGauge = 0;
                    playerStats = _normalizeCombatStats(this.getEffectiveStats());
                    continue;
                }

                // Déclenchement ULT si jauge pleine (respecte autoUltimate en offline)
                if (player.ultimateAbility && player.ultimateCharge >= player.ultimateAbility.chargeNeeded!) {
                    const _pHeld = player.heldItem ? HELD_ITEMS[player.heldItem] : null;
                    const _pUltLock = !!(_pHeld && (_pHeld.effect as Record<string, unknown> | undefined)
                        && ((_pHeld.effect as Record<string, unknown>).disable_ultimate));
                    const _allowSimUlt = !this.isOfflineSimulating
                        || (this.autoSelectEnabled && this.autoUltimate && !_pUltLock);
                    if (_allowSimUlt) {
                    if (this.isOfflineSimulating && this._lastSimPacing) {
                        accumulateSimActionDelay(this._lastSimPacing as SimPacingSnapshot, true);
                    }
                    simulateUltimateActivation(this, player, enemy);
                    }
                    if (enemy.currentHp <= 0) {
                        const faint = finishSimEnemyFaint(this, enemy, player, previousEnemy);
                        if (faint.done) return faint.result;
                        continue;
                    }
                }

                // Confusion : 30% auto-dégât
                if (player.hasStatusEffect!() && player.statusEffect.type === STATUS_EFFECTS.CONFUSED && Math.random() < 0.30 && player.passiveTalent !== 'sans_repos') {
                    const selfDmg = Math.floor(playerStats.attack * 0.5);
                    applySimDamage(this, player, selfDmg);
                    if (getSimCurrentHp(this, player) <= 0) {
                        const relay = applySimFaintRelay(this, previousEnemy);
                        if (!relay.ok) return returnSimCombatResult(this, null, previousEnemy);
                        player = relay.player;
                        simPlayerGauge = 0;
                        playerStats = _normalizeCombatStats(this.getEffectiveStats());
                    }
                    continue;
                }

                // Statut bloquant (gel, paralysie, étourdi)
                if (!player.canAttack!()) {
                    if (player.statusEffect && player.statusEffect.duration > 0) player.statusEffect.duration--;
                    if (this.isOfflineSimulating && this._lastSimPacing) {
                        accumulateSimBlockedTurnDelay(this._lastSimPacing as SimPacingSnapshot);
                    }
                    continue;
                }

                // Esquive AGILE de la cible (50% comme takeDamage live)
                if (enemy.hasStatusEffect!() && enemy.statusEffect.type === STATUS_EFFECTS.AGILE && (enemy.statusEffect.dodgeCount || 0) < STATUS_AGILE_MAX_DODGES && Math.random() < STATUS_AGILE_DODGE_CHANCE) {
                    enemy.statusEffect.dodgeCount = (enemy.statusEffect.dodgeCount || 0) + 1;
                    if (this.isOfflineSimulating && this._lastSimPacing) {
                        accumulateSimMissTurnDelay(this._lastSimPacing as SimPacingSnapshot);
                    }
                    continue;
                }

                // Bright Powder côté ennemi : 10% miss
                if (enemy.heldItem === 'bright_powder' && Math.random() < 0.10) {
                    if (this.isOfflineSimulating && this._lastSimPacing) {
                        accumulateSimMissTurnDelay(this._lastSimPacing as SimPacingSnapshot);
                    }
                    continue;
                }

                // Choix de l'attaque (avec garde HP : Destruction/Explosion bloqués sous 50% PV)
                let moveName = player.getMove ? player.getMove() : 'Charge';
                moveName = pickSimMoveRespectingGates(this, player, moveName);
                const move = getMoveDefinition(moveName);
                const moveRecoil = (move && typeof move.recoil === 'number') ? move.recoil : 0;
                const moveDrain = (move && typeof move.drain === 'number') ? move.drain : 0;

                // Bonus de mult sur dégâts (executor, element_master, finisher)
                const enemyHpRatio = (enemy.currentHp || 0) / Math.max(1, enemy.maxHp || 1);
                let bonusMult = 1.0;
                if (upgradeExecutor && enemyHpRatio < 0.30) bonusMult *= (1 + Number(upgradeExecutor) * 0.15);
                if (upgradeElementMaster && enemy.hasStatusEffect!()) bonusMult *= (1 + Number(upgradeElementMaster) * 0.10);
                if (masteryFinisher > 0 && enemyHpRatio < 0.25) bonusMult *= (1 + masteryFinisher);

                // Modifs ult posées sur le joueur
                const u = consumeSimUlt(player);
                let ultMult = u.mult;
                if (player.heldItem === 'life_orb') ultMult *= 1.3;

                if (this.isOfflineSimulating && this._lastSimPacing) {
                    accumulateSimActionDelay(this._lastSimPacing as SimPacingSnapshot, true);
                }

                const hitCount = resolveMoveHitCount(move as Record<string, unknown>, {
                    wasUltimate: u.wasUlt,
                    ultimateHits: u.hits,
                    heldItem: player.heldItem,
                });

                // Multi-hit loop
                let totalApplied = 0;
                let attackerDied = false;
                for (let h = 0; h < hitCount; h++) {
                    if (enemy.currentHp <= 0) break;

                    if (!rollMoveHit(player as unknown as ICreature, enemy as unknown as ICreature, move as Record<string, unknown>)) {
                        if (this.isOfflineSimulating && this._lastSimPacing) {
                            accumulateSimMissTurnDelay(this._lastSimPacing as SimPacingSnapshot);
                        }
                        applyBlunderPolicyOnMiss(player as unknown as ICreature, this);
                        continue;
                    }

                    const hitTargetHealthRatio = (enemy.currentHp || 0) / Math.max(1, enemy.maxHp || 1);
                    const isHitCrit = rollCreatureCritHit(this, player as unknown as ICreature, {
                        towerBuffs,
                        targetHealthRatio: hitTargetHealthRatio,
                        moveDef: move as Record<string, unknown>,
                    });

                    const proxyAttacker = {
                        attack: playerStats.attack,
                        spattack: playerStats.spattack,
                        defense: playerStats.defense,
                        spdefense: playerStats.spdefense,
                        type: player.type,
                        secondaryType: player.secondaryType,
                        passiveTalent: player.passiveTalent,
                        heldItem: player.heldItem,
                        movePp: player.movePp,
                        currentMoves: player.currentMoves,
                        isEnemy: false
                    };

                    let dmg: number;
                    if (isRetaliationMove(move)) {
                        const retaliation = resolveRetaliationDamage({
                            attacker: player,
                            moveDef: move as Record<string, unknown>,
                            target: enemy,
                        });
                        if (retaliation.blocked) {
                            if (this.isOfflineSimulating && this._lastSimPacing) {
                                accumulateSimMissTurnDelay(this._lastSimPacing as SimPacingSnapshot);
                            }
                            continue;
                        }
                        dmg = retaliation.damage;
                    } else {
                        const moveRecord = move as Record<string, unknown>;
                        const movePower = resolveEffectiveMovePower(moveRecord, {
                            target: enemy as unknown as ICreature,
                            attacker: player as unknown as ICreature,
                            game: this,
                        });
                        dmg = Creature.calculateDamageOutput(
                            proxyAttacker as unknown as Creature,
                            enemy as unknown as Creature,
                            {
                                isCritical: isHitCrit,
                                ultMultiplier: ultMult * bonusMult,
                                ignoreDefensePct: Math.min(0.75, Math.max(0, (u.defPen || 0) + masteryIgnoreDef)),
                                attackCategory: moveRecord.category as string | undefined,
                                movePower,
                                moveType: (moveRecord.type as string) || player.type,
                                moveName,
                                gameContext: this
                            }
                        );
                    }
                    dmg = Math.floor(dmg * playerDmgBonusMult);
                    if (masteryBossHunter > 0 && enemy && (enemy.isBoss || enemy.isEpic)) {
                        dmg = Math.floor(dmg * (1 + masteryBossHunter));
                    }
                    dmg = applyPlayerOffensivePassiveDamageMods(this, player as unknown as ICreature, enemy as unknown as ICreature, dmg);

                    // Thorny reflect (la cible est THORNY → renvoie 15%)
                    if (enemy.hasStatusEffect!() && enemy.statusEffect.type === STATUS_EFFECTS.THORNY && player.passiveTalent !== 'sans_repos') {
                        const thornsDmg = Math.floor(dmg * 0.15);
                        if (thornsDmg > 0) {
                            applySimDamage(this, player, thornsDmg);
                            if (getSimCurrentHp(this, player) <= 0) attackerDied = true;
                        }
                        dmg = Math.floor(dmg * 0.67);
                    }

                    const applied = applySimDamage(this, enemy, dmg);
                    totalApplied += applied;
                    if (applied > 0) {
                        recordOpponentHitDamage(enemy, applied, coerceStr((move as Record<string, unknown>).category, ''));
                        const moveType = coerceStr((move as Record<string, unknown>).type as string, player.type);
                        const effectiveness = getTypeMultiplier(moveType, enemy.type, enemy.secondaryType ?? null);
                        if (effectiveness > 1) {
                            applyWeaknessPolicyOnSuperEffectiveHit(enemy as unknown as ICreature, this);
                        }
                        if (isRetaliationMove(move)) {
                            consumeRetaliationCharge(player, move);
                        }
                    }

                    const reflDmgPlayerHit = computeSimReflexionDamage(
                        this,
                        enemy,
                        player,
                        applied,
                        (move as Record<string, unknown>).category as string | undefined,
                    );
                    if (reflDmgPlayerHit > 0) {
                        applySimDamage(this, player, reflDmgPlayerHit);
                        if (getSimCurrentHp(this, player) <= 0) attackerDied = true;
                    }

                    const simMoveType = normalizeTrackedDamageType((move && move.type) || 'normal');
                    if (simMoveType) {
                        const typedStats = this.stats?.typedDamageDealt;
                        if (typedStats && typeof typedStats === 'object') {
                            typedStats[simMoveType] = (Number(typedStats[simMoveType]) || 0) + applied;
                        }
                    }

                    // Charge ult ennemi en défense
                    if (isTrainerBattle(this)
                        && enemy.ultimateAbility && enemy.ultimateCharge < enemy.ultimateAbility.chargeNeeded!) {
                        let defCharge = 6;
                        if (enemy.passiveTalent === 'epineux') defCharge += 6;
                        enemy.ultimateCharge = Math.min(enemy.ultimateAbility.chargeNeeded!, enemy.ultimateCharge + defCharge);
                    }

                    // Item Rocky Helmet : ennemi renvoie 15% des dégâts physiques subis
                    if (enemy.heldItem === 'rocky_helmet' && applied > 0 && player.passiveTalent !== 'sans_repos'
                        && !isContactBlockedByPunchingGlove(player, 'physical')) {
                        const ref = Math.floor(applied * 0.15);
                        if (ref > 0) {
                            applySimDamage(this, player, ref);
                            if (getSimCurrentHp(this, player) <= 0) attackerDied = true;
                        }
                    }

                    // Item Boue Noire : si l'ennemi porte black_sludge et que le coup est physique,
                    // 30% de chance d'empoisonner l'attaquant (le joueur ici).
                    if (enemy.heldItem === 'black_sludge' && applied > 0
                        && move && move.category === 'physical' && !player.hasStatusEffect!()
                        && !isContactBlockedByPunchingGlove(player, 'physical')) {
                        const chance = (typeof HELD_ITEMS !== 'undefined' && (HELD_ITEMS['black_sludge']?.effect as Record<string, unknown> | undefined)?.contact_poison_chance as number) || 0.30;
                        if (Math.random() < chance) {
                            player.applyStatusEffect!(STATUS_EFFECTS.POISONED, enemy.attack || 0, enemy);
                        }
                    }

                    // Life Orb recoil
                    if (player.heldItem === 'life_orb' && player.passiveTalent !== 'sans_repos') {
                        const recoil = Math.floor(getSimMaxHp(this, player) * 0.10);
                        if (recoil > 0) {
                            applySimDamage(this, player, recoil);
                            if (getSimCurrentHp(this, player) <= 0) attackerDied = true;
                        }
                    }

                    // Shell Bell soin sur dégâts infligés
                    if (player.heldItem === 'shell_bell' && applied > 0) {
                        applySimHeal(this, player, Math.floor(applied * 0.15));
                    }

                    // Lifesteal d'ult
                    if (u.lifesteal > 0 && applied > 0) {
                        applySimHeal(this, player, Math.floor(applied * u.lifesteal));
                    }

                    // Drain du move classique (Vole-Vie, Giga-Sangsue, etc.)
                    if (moveDrain > 0 && applied > 0) {
                        applySimHeal(this, player, Math.floor(applied * moveDrain));
                    }

                    // Recoil d'ult
                    if (u.recoil > 0 && applied > 0 && player.passiveTalent !== 'sans_repos') {
                        const rc = Math.floor(applied * u.recoil);
                        if (rc > 0) {
                            applySimDamage(this, player, rc);
                            if (getSimCurrentHp(this, player) <= 0) attackerDied = true;
                        }
                    }

                    // Recoil du move classique (Destruction/Explosion)
                    if (moveRecoil > 0 && applied > 0 && player.passiveTalent !== 'sans_repos') {
                        const mrc = Math.floor(applied * moveRecoil);
                        if (mrc > 0) {
                            applySimDamage(this, player, mrc);
                            if (getSimCurrentHp(this, player) <= 0) attackerDied = true;
                        }
                    }

                    // Focus Sash : si KO et 1er coup et HP plein avant ce coup
                    if (getSimCurrentHp(this, player) <= 0 && player.heldItem === 'focus_sash' && !player._focusSashUsed) {
                        if (player.isEnemy) player.currentHp = 1;
                        else if (this._simTrainerBattle) player.currentHp = 1;
                        else player.mainAccountCurrentHp = 1;
                        player._focusSashUsed = true;
                        attackerDied = false;
                    } else if (getSimCurrentHp(this, player) <= 0) {
                        attackerDied = true;
                        break;
                    }

                    if (enemy.currentHp > 0 && applied > 0 && move && !shouldSkipForceBruteSecondary(player, moveName, move as Record<string, unknown>)) {
                        applyMoveSecondaryEffects({
                            game: this,
                            attacker: player,
                            target: enemy,
                            move: move as Record<string, unknown>,
                            appliedDamage: applied,
                            sourceAttack: playerStats.attack,
                        });
                        rollSimTypeStatusProcOnHit(
                            this,
                            player as unknown as ICreature,
                            enemy as unknown as ICreature,
                            playerStats.attack,
                        );
                    }
                }

                applyMoveSelfStatusOnHit({
                    game: this,
                    attacker: player as unknown as ICreature,
                    move: move as Record<string, unknown>,
                    totalApplied,
                    sourceAttack: playerStats.attack,
                });

                if (totalApplied > 0 && enemy.currentHp > 0 && move) {
                    applyPartialTrapOnHit(
                        enemy as unknown as ICreature,
                        player as unknown as ICreature,
                        move as Record<string, unknown>,
                        moveName,
                    );
                    clearPartialTrapFromMove(player as unknown as ICreature, move as Record<string, unknown>);
                }

                tickRampageAfterAction({
                    game: this,
                    attacker: player as unknown as ICreature,
                    moveName,
                    move: move as Record<string, unknown>,
                    sourceAttack: playerStats.attack,
                });

                applyPriorityMoveNextActionBoost({
                    game: this,
                    attacker: player as unknown as ICreature,
                    move: move as Record<string, unknown>,
                    totalApplied,
                });

                if (totalApplied > 0) {
                    incrementMetronomeBandOnHit(player as unknown as ICreature);
                }

                incrementBerserkerStack(player);
                incrementSimAcharnement(player, enemy);
                const vampHeal = computeSimVampireHeal(this, player, totalApplied);
                if (vampHeal > 0) applySimHeal(this, player, vampHeal);

                // Lifesteal collection / talent
                if ((collLifesteal + accLifesteal) > 0 && totalApplied > 0) {
                    applySimHeal(this, player, Math.floor(totalApplied * (collLifesteal + accLifesteal)));
                }

                // Régénération passive (leftovers + collection grass starters + black sludge réservé Poison)
                let regenPct = 0;
                if (collRegen > 0) regenPct += collRegen;
                if (player.heldItem === 'leftovers') regenPct += 0.02;
                if (player.heldItem === 'black_sludge'
                    && (player.type === TYPES.POISON || player.secondaryType === TYPES.POISON)) {
                    regenPct += 0.01;
                }
                if (regenPct > 0) {
                    applySimHeal(this, player, Math.floor(getSimMaxHp(this, player) * regenPct));
                }

                // Charge ult joueur (si pas en pleine ult)
                if (player.ultimateAbility && player.ultimateCharge < player.ultimateAbility.chargeNeeded! && !u.wasUlt) {
                    let charge = 12;
                    if (player.passiveTalent === 'adrenaline') {
                        const eluFactor = typeof this.getEluFactorFor === 'function'
                            ? this.getEluFactorFor(player)
                            : 1.0;
                        charge += scaleTalentFlat(12, eluFactor);
                    }
                    if (simTrainerBattle) charge += 6;
                    if (towerBuffs && towerBuffs.ult_charge_bonus) {
                        const tb = Math.min(0.10, Number(towerBuffs.ult_charge_bonus));
                        charge += (player.ultimateAbility.chargeNeeded ?? 100) * tb;
                    }
                    if (accUltCharge > 0) charge += accUltCharge;
                    if (masteryUlt > 0) charge += player.ultimateAbility.chargeNeeded! * masteryUlt;
                    player.ultimateCharge = Math.min(player.ultimateAbility.chargeNeeded!, player.ultimateCharge + charge);
                }

                if (u.wasUlt && enemy.currentHp > 0 && getSimCurrentHp(this, player) > 0 && masteryUltPersist > 0 && player.ultimateAbility) {
                    player.ultimateCharge = Math.floor((player.ultimateAbility.chargeNeeded ?? 100) * masteryUltPersist);
                }

                if (enemy.currentHp <= 0) {
                    const faint = finishSimEnemyFaint(this, enemy, player, previousEnemy);
                    if (faint.done) return faint.result;
                    continue;
                }

                if (attackerDied) {
                    const relay = applySimFaintRelay(this, previousEnemy);
                    if (!relay.ok) return returnSimCombatResult(this, null, previousEnemy);
                    player = relay.player;
                    simPlayerGauge = 0;
                    playerStats = _normalizeCombatStats(this.getEffectiveStats());
                }
                continue;
            }

            // ─────────────── ENEMY TURN ───────────────
            if (simEnemyGauge >= threshold) {
                if (this.isOfflineSimulating && this._lastSimPacing) {
                    const pacing = this._lastSimPacing as SimPacingSnapshot;
                    accumulateSimTimeJump(pacing, timeJump, safePSpeed, safeESpeed);
                    pacing.simTurns = turns;
                }
                simEnemyGauge -= threshold;
                recordCombatTurn(this, false);
                consumeNextActionSpeedBoost(enemy as unknown as ICreature);

                enemy.processStatusEffect?.(this);
                const trapTickEnemy = processPartialTrapTick(
                    enemy as unknown as ICreature,
                    this,
                    playerStats as Record<string, number>,
                    { silent: true },
                );
                if (trapTickEnemy.isDead) {
                    const faint = finishSimEnemyFaint(this, enemy, player, previousEnemy);
                    if (faint.done) return faint.result;
                    continue;
                }
                if (enemy.currentHp <= 0) {
                    const faint = finishSimEnemyFaint(this, enemy, player, previousEnemy);
                    if (faint.done) return faint.result;
                    continue;
                }

                // Activation ult ennemie
                if (shouldEnemyActivateUltimateNow(this, enemy)) {
                    if (this.isOfflineSimulating && this._lastSimPacing) {
                        accumulateSimActionDelay(this._lastSimPacing as SimPacingSnapshot, false);
                    }
                    simulateUltimateActivation(this, enemy, player);
                    if (getSimCurrentHp(this, player) <= 0) {
                        // Possible si HEAL ult enemy ne nous tue pas, mais APPLY_STATUS oui-non. Sécurité.
                        if (!(player.heldItem === 'focus_sash' && !player._focusSashUsed)) {
                            const relay = applySimFaintRelay(this, previousEnemy);
                            if (!relay.ok) return returnSimCombatResult(this, null, previousEnemy);
                            player = relay.player;
                            simPlayerGauge = 0;
                            playerStats = _normalizeCombatStats(this.getEffectiveStats());
                            continue;
                        }
                    }
                }

                // Confusion ennemi
                if (enemy.hasStatusEffect!() && enemy.statusEffect.type === STATUS_EFFECTS.CONFUSED && Math.random() < 0.30 && enemy.passiveTalent !== 'sans_repos') {
                    const selfDmg = Math.floor(enemy.attack * 0.5);
                    applySimDamage(this, enemy, selfDmg);
                    if (enemy.currentHp <= 0) {
                        const faint = finishSimEnemyFaint(this, enemy, player, previousEnemy);
                        if (faint.done) return faint.result;
                        continue;
                    }
                    continue;
                }

                if (!enemy.canAttack!()) {
                    if (enemy.statusEffect && enemy.statusEffect.duration > 0) enemy.statusEffect.duration--;
                    if (this.isOfflineSimulating && this._lastSimPacing) {
                        accumulateSimBlockedTurnDelay(this._lastSimPacing as SimPacingSnapshot);
                    }
                    continue;
                }

                // Esquive AGILE du joueur (50% comme takeDamage live)
                if (player.hasStatusEffect!() && player.statusEffect.type === STATUS_EFFECTS.AGILE && (player.statusEffect.dodgeCount || 0) < STATUS_AGILE_MAX_DODGES && Math.random() < STATUS_AGILE_DODGE_CHANCE) {
                    player.statusEffect.dodgeCount = (player.statusEffect.dodgeCount || 0) + 1;
                    if (this.isOfflineSimulating && this._lastSimPacing) {
                        accumulateSimMissTurnDelay(this._lastSimPacing as SimPacingSnapshot);
                    }
                    continue;
                }

                if (player.heldItem === 'bright_powder' && Math.random() < 0.10) {
                    if (this.isOfflineSimulating && this._lastSimPacing) {
                        accumulateSimMissTurnDelay(this._lastSimPacing as SimPacingSnapshot);
                    }
                    continue;
                }

                let enemyMoveName = enemy.getMove ? enemy.getMove() : 'Charge';
                enemyMoveName = pickSimMoveRespectingGates(this, enemy, enemyMoveName);
                const enemyMove = getMoveDefinition(enemyMoveName);
                const enemyMoveRecoil = (enemyMove && typeof enemyMove.recoil === 'number') ? enemyMove.recoil : 0;
                const enemyMoveDrain = (enemyMove && typeof enemyMove.drain === 'number') ? enemyMove.drain : 0;

                const uE = consumeSimUlt(enemy);
                let ultMultE = uE.mult;
                if (enemy.heldItem === 'life_orb') ultMultE *= 1.3;

                if (this.isOfflineSimulating && this._lastSimPacing) {
                    accumulateSimActionDelay(this._lastSimPacing as SimPacingSnapshot, false);
                }

                const hitCountE = resolveMoveHitCount(enemyMove as Record<string, unknown>, {
                    wasUltimate: uE.wasUlt,
                    ultimateHits: uE.hits,
                    heldItem: enemy.heldItem,
                });

                let _totalAppliedE = 0;
                let playerDied = false;
                for (let h = 0; h < hitCountE; h++) {
                    if (getSimCurrentHp(this, player) <= 0) break;

                    if (!rollMoveHit(enemy as unknown as ICreature, player as unknown as ICreature, enemyMove as Record<string, unknown>)) {
                        if (this.isOfflineSimulating && this._lastSimPacing) {
                            accumulateSimMissTurnDelay(this._lastSimPacing as SimPacingSnapshot);
                        }
                        continue;
                    }

                    const enemyHeldDef = enemy.heldItem ? HELD_ITEMS[enemy.heldItem] : null;
                    const enemyHeldCrit = (enemyHeldDef && (enemyHeldDef.effect as Record<string, unknown> | undefined)?.crit_chance as number) || 0;
                    const hitTargetHealthRatioE = getSimCurrentHp(this, player) / Math.max(1, getSimMaxHp(this, player));
                    const isHitCritE = rollCreatureCritHit(this, enemy as unknown as ICreature, {
                        targetHealthRatio: hitTargetHealthRatioE,
                        heldCritChance: enemyHeldCrit,
                        moveDef: enemyMove as Record<string, unknown>,
                    });

                    const atkMultE = enemy.getAttackMultiplier ? enemy.getAttackMultiplier(this) : 1;
                    const proxyAttackerE = {
                        attack: Math.floor((enemy.attack || 0) * atkMultE),
                        spattack: Math.floor((enemy.spattack || 0) * atkMultE),
                        defense: enemy.defense,
                        spdefense: enemy.spdefense,
                        type: enemy.type,
                        secondaryType: enemy.secondaryType,
                        passiveTalent: enemy.passiveTalent,
                        heldItem: enemy.heldItem,
                        isEnemy: true
                    };

                    let dmg: number;
                    if (isRetaliationMove(enemyMove)) {
                        const retaliation = resolveRetaliationDamage({
                            attacker: enemy,
                            moveDef: enemyMove as Record<string, unknown>,
                            target: player,
                        });
                        if (retaliation.blocked) {
                            if (this.isOfflineSimulating && this._lastSimPacing) {
                                accumulateSimMissTurnDelay(this._lastSimPacing as SimPacingSnapshot);
                            }
                            continue;
                        }
                        dmg = retaliation.damage;
                    } else {
                        const enemyMoveRecord = enemyMove as Record<string, unknown>;
                        const movePower = resolveEffectiveMovePower(enemyMoveRecord, {
                            target: player as unknown as ICreature,
                            attacker: enemy as unknown as ICreature,
                            game: this,
                        });
                        dmg = Creature.calculateDamageOutput(
                            proxyAttackerE as unknown as Creature,
                            player as unknown as Creature,
                            {
                                isCritical: isHitCritE,
                                ultMultiplier: ultMultE,
                                ignoreDefensePct: uE.defPen,
                                attackCategory: enemyMoveRecord.category as string | undefined,
                                movePower,
                                moveType: (enemyMoveRecord.type as string) || enemy.type,
                                moveName: enemyMoveName,
                                gameContext: this
                            }
                        );
                    }
                    dmg = Math.floor(dmg * enemyDmgReductionMult);
                    if (dmg < 0) dmg = 0;
                    dmg = applyZRingFiriumEnemyDamageMod(this, enemy as unknown as ICreature, dmg);

                    // Thorny reflect (le joueur THORNY renvoie 15%)
                    if (player.hasStatusEffect!() && player.statusEffect.type === STATUS_EFFECTS.THORNY && enemy.passiveTalent !== 'sans_repos') {
                        const thornsDmg = Math.floor(dmg * 0.15);
                        if (thornsDmg > 0) applySimDamage(this, enemy, thornsDmg);
                        dmg = Math.floor(dmg * 0.67);
                    }

                    const applied = applySimDamage(this, player, dmg);
                    _totalAppliedE += applied;
                    if (applied > 0) {
                        recordOpponentHitDamage(player, applied, coerceStr((enemyMove as Record<string, unknown>).category, ''));
                        const moveType = coerceStr((enemyMove as Record<string, unknown>).type as string, enemy.type);
                        const effectiveness = getTypeMultiplier(moveType, player.type, player.secondaryType ?? null);
                        if (effectiveness > 1) {
                            applyWeaknessPolicyOnSuperEffectiveHit(player as unknown as ICreature, this);
                        }
                        if (isRetaliationMove(enemyMove)) {
                            consumeRetaliationCharge(enemy, enemyMove);
                        }
                    }

                    const reflDmg = computeSimReflexionDamage(
                        this,
                        player,
                        enemy,
                        applied,
                        (enemyMove as Record<string, unknown>).category as string | undefined,
                    );
                    if (reflDmg > 0) applySimDamage(this, enemy, reflDmg);

                    // Rocky Helmet côté joueur
                    if (player.heldItem === 'rocky_helmet' && applied > 0 && enemy.passiveTalent !== 'sans_repos'
                        && !isContactBlockedByPunchingGlove(enemy, 'physical')) {
                        const ref = Math.floor(applied * 0.15);
                        if (ref > 0) applySimDamage(this, enemy, ref);
                    }

                    // Boue Noire côté joueur : si le joueur porte black_sludge et subit un coup physique,
                    // 30% de chance d'empoisonner l'attaquant (l'ennemi ici).
                    if (player.heldItem === 'black_sludge' && applied > 0
                        && enemyMove && enemyMove.category === 'physical' && !enemy.hasStatusEffect!()
                        && !isContactBlockedByPunchingGlove(enemy, 'physical')) {
                        const chance = (typeof HELD_ITEMS !== 'undefined' && (HELD_ITEMS['black_sludge']?.effect as Record<string, unknown> | undefined)?.contact_poison_chance as number) || 0.30;
                        if (Math.random() < chance) {
                            enemy.applyStatusEffect!(STATUS_EFFECTS.POISONED, player.attack || 0, player);
                        }
                    }

                    // Life Orb recoil ennemi
                    if (enemy.heldItem === 'life_orb' && enemy.passiveTalent !== 'sans_repos') {
                        const recoil = Math.floor((enemy.maxHp || 100) * 0.10);
                        if (recoil > 0) applySimDamage(this, enemy, recoil);
                    }

                    // Shell Bell ennemi
                    if (enemy.heldItem === 'shell_bell' && applied > 0) {
                        applySimHeal(this, enemy, Math.floor(applied * 0.15));
                    }

                    // Lifesteal d'ult ennemi
                    if (uE.lifesteal > 0 && applied > 0) {
                        applySimHeal(this, enemy, Math.floor(applied * uE.lifesteal));
                    }

                    // Drain du move classique ennemi
                    if (enemyMoveDrain > 0 && applied > 0) {
                        applySimHeal(this, enemy, Math.floor(applied * enemyMoveDrain));
                    }

                    if (uE.recoil > 0 && applied > 0 && enemy.passiveTalent !== 'sans_repos') {
                        const rc = Math.floor(applied * uE.recoil);
                        if (rc > 0) applySimDamage(this, enemy, rc);
                    }

                    // Recoil du move classique ennemi (Destruction/Explosion)
                    if (enemyMoveRecoil > 0 && applied > 0 && enemy.passiveTalent !== 'sans_repos') {
                        const mrc = Math.floor(applied * enemyMoveRecoil);
                        if (mrc > 0) applySimDamage(this, enemy, mrc);
                    }

                    // Charge ult joueur en défense
                    if (player.ultimateAbility && player.ultimateCharge < player.ultimateAbility.chargeNeeded!) {
                        let defCharge = 6;
                        if (player.passiveTalent === 'epineux') {
                            const eluFactor = typeof this.getEluFactorFor === 'function'
                                ? this.getEluFactorFor(player)
                                : 1.0;
                            defCharge += scaleTalentFlat(6, eluFactor);
                        }
                        if (simTrainerBattle) defCharge += 3;
                        if (towerBuffs && towerBuffs.ult_charge_bonus) {
                            const tb = Math.min(0.10, Number(towerBuffs.ult_charge_bonus));
                            defCharge += (player.ultimateAbility.chargeNeeded ?? 100) * tb;
                        }
                        if (accUltCharge > 0) defCharge += accUltCharge;
                        if (masteryUlt > 0) defCharge += player.ultimateAbility.chargeNeeded! * masteryUlt;
                        player.ultimateCharge = Math.min(player.ultimateAbility.chargeNeeded!, player.ultimateCharge + defCharge);
                    }

                    // Focus Sash côté joueur
                    if (getSimCurrentHp(this, player) <= 0 && player.heldItem === 'focus_sash' && !player._focusSashUsed) {
                        if (this._simTrainerBattle) player.currentHp = 1;
                        else player.mainAccountCurrentHp = 1;
                        player._focusSashUsed = true;
                    } else if (getSimCurrentHp(this, player) <= 0) {
                        playerDied = true;
                        break;
                    }

                    if (getSimCurrentHp(this, player) > 0 && applied > 0 && enemyMove && !shouldSkipForceBruteSecondary(enemy, enemyMoveName, enemyMove as Record<string, unknown>)) {
                        applyMoveSecondaryEffects({
                            game: this,
                            attacker: enemy,
                            target: player,
                            move: enemyMove as Record<string, unknown>,
                            appliedDamage: applied,
                            sourceAttack: enemy.attack || 0,
                        });
                        rollSimTypeStatusProcOnHit(
                            this,
                            enemy as unknown as ICreature,
                            player as unknown as ICreature,
                            enemy.attack || 0,
                        );
                    }
                }

                applyMoveSelfStatusOnHit({
                    game: this,
                    attacker: enemy as unknown as ICreature,
                    move: enemyMove as Record<string, unknown>,
                    totalApplied: _totalAppliedE,
                    sourceAttack: enemy.attack || 0,
                });

                if (_totalAppliedE > 0 && getSimCurrentHp(this, player) > 0 && enemyMove) {
                    applyPartialTrapOnHit(
                        player as unknown as ICreature,
                        enemy as unknown as ICreature,
                        enemyMove as Record<string, unknown>,
                        enemyMoveName,
                    );
                    clearPartialTrapFromMove(enemy as unknown as ICreature, enemyMove as Record<string, unknown>);
                }

                tickRampageAfterAction({
                    game: this,
                    attacker: enemy as unknown as ICreature,
                    moveName: enemyMoveName,
                    move: enemyMove as Record<string, unknown>,
                    sourceAttack: enemy.attack || 0,
                });

                applyPriorityMoveNextActionBoost({
                    game: this,
                    attacker: enemy as unknown as ICreature,
                    move: enemyMove as Record<string, unknown>,
                    totalApplied: _totalAppliedE,
                });

                if (_totalAppliedE > 0) {
                    incrementMetronomeBandOnHit(enemy as unknown as ICreature);
                }

                incrementBerserkerStack(enemy);
                incrementSimAcharnement(enemy, player);

                // Charge ult ennemi (si pas en pleine ult)
                if (isTrainerBattle(this)
                    && enemy.ultimateAbility && enemy.ultimateCharge < enemy.ultimateAbility.chargeNeeded! && !uE.wasUlt) {
                    let charge = 12;
                    if (enemy.passiveTalent === 'adrenaline') charge += 12;
                    enemy.ultimateCharge = Math.min(enemy.ultimateAbility.chargeNeeded!, enemy.ultimateCharge + charge);
                }

                if (enemy.currentHp <= 0) {
                    const faint = finishSimEnemyFaint(this, enemy, player, previousEnemy);
                    if (faint.done) return faint.result;
                    continue;
                }

                if (playerDied) {
                    const relay = applySimFaintRelay(this, previousEnemy);
                    if (!relay.ok) return returnSimCombatResult(this, null, previousEnemy);
                    player = relay.player;
                    simPlayerGauge = 0;
                    playerStats = _normalizeCombatStats(this.getEffectiveStats());
                }
            }
        }

        this.processSimulatedDefeat();
        return returnSimCombatResult(this, null, previousEnemy);
    };

    GameClass.prototype.simulateGymTrainerEncounter = function (this: ThisGame): Record<string, unknown> | null {
        this._offlineAbortNoEnemy = false;

        if (this.gymTrainerState && this.gymTrainerState.active) {
            this.gymTrainerState = null;
        }

        if (this.isOfflineSimulating && typeof this.ensureDpsOfflineBucket === 'function') {
            const off = this.ensureDpsOfflineBucket();
            off.combats = (off.combats || 0) + 1;
        }

        const gymTeam = createGymTrainerLogic(this);
        if (!gymTeam || gymTeam.length === 0) {
            this._offlineAbortNoEnemy = true;
            return null;
        }

        this.playerTeam.forEach((c) => {
            c.heal!();
            c.clearStatusEffect!();
            if (c.maxHp != null) c.currentHp = c.maxHp;
        });

        const gts = this.gymTrainerState;
        if (!gts || !gts.team || gts.team.length === 0) {
            this._offlineAbortNoEnemy = true;
            return null;
        }

        gts.currentIndex = 0;
        this._offlineGymTrainerMode = true;
        this._simTrainerBattle = true;
        if (typeof this.invalidateStatsCache === 'function') {
            this.invalidateStatsCache();
        }

        const aggregatePacing = createSimPacingState();
        let lastResult: Record<string, unknown> | null = null;

        try {
            while (this.gymTrainerState && this.gymTrainerState.active) {
                this.currentPlayerCreature = this.getOfflinePreferredCreature
                    ? this.getOfflinePreferredCreature()
                    : this.getFirstAliveCreature();
                if (!this.currentPlayerCreature) {
                    this.gymTrainerState = null;
                    return null;
                }

                this._lastSimPacing = createSimPacingState();
                const monResult = this.simulateCombat();
                if (this._offlineAbortNoEnemy) {
                    return null;
                }

                const monPacing = this._lastSimPacing as SimPacingSnapshot | undefined;
                if (monPacing) {
                    mergeSimPacingInto(aggregatePacing, monPacing);
                }

                if (!monResult) {
                    this.gymTrainerState = null;
                    return null;
                }

                lastResult = monResult;

                if (!this.gymTrainerState || !this.gymTrainerState.active) {
                    break;
                }
            }
        } finally {
            this._offlineGymTrainerMode = false;
            this._simTrainerBattle = false;
            this.gymTrainerState = null;
        }

        if (!lastResult) {
            return null;
        }

        lastResult.pacing = {
            wallMs: aggregatePacing.wallMs,
            playerActions: aggregatePacing.playerActions,
            enemyActions: aggregatePacing.enemyActions,
            simTurns: aggregatePacing.simTurns,
        };
        return lastResult;
    };

    GameClass.prototype.processSimulatedVictory = function (this: ThisGame, enemy: CreatureData): Record<string, unknown> | null {
        if (enemy.isGymTrainer && this.gymTrainerState && this.gymTrainerState.active) {
            const gts = this.gymTrainerState;
            const idx = gts.currentIndex ?? 0;
            const isLastMember = idx >= gts.team.length - 1;
            if (!isLastMember) {
                gts.currentIndex = idx + 1;
                return attachPacingToResult(this, { xp: 0, money: 0, items: {}, captured: null });
            }
            const clearResult = applySimulatedGymTrainerClear(this, enemy);
            this.gymTrainerState = null;
            this.faintedThisCombat = new Set();
        this.faintedUidsThisCombat = new Set();
            return clearResult;
        }

        if (enemy.isGymTrainer) {
            return attachPacingToResult(this, { xp: 0, money: 0, items: {}, captured: null });
        }

        const isBoss = enemy.isBoss;
        const isEpic = enemy.isEpic;

        if (this.isOfflineSimulating) {
            applyLegendaryWildCooldownAfterOfflineEncounterLogic(this, enemy);
        }

        this.stats.combatsWon++;
        if (typeof this._registerCombatWonForRecords === 'function') this._registerCombatWonForRecords();
        if (typeof this._recordDailyActivity === 'function') this._recordDailyActivity('combats', 1);
        const zpSim = this.zoneProgress?.[currentZone];
        if (zpSim) {
            zpSim.combatsWon = (zpSim.combatsWon || 0) + 1;
        }
        if (isBoss) {
            this.stats.bossDefeated++;
            if (zpSim) zpSim.bossesDefeated = (zpSim.bossesDefeated || 0) + 1;
            if (this.isOfflineSimulating && this._offlineStatsContext) {
                recordOfflineBossEpicQuestTally(this._offlineStatsContext, {
                    isBoss: true,
                    species: enemy.name,
                    zoneId: Number(currentZone),
                });
            } else {
                this.checkSpecialQuests('bossDefeated', { species: enemy.name, zoneId: Number(currentZone) });
            }
        }
        if (isEpic) {
            this.stats.epicDefeated++;
            if (zpSim) zpSim.epicsDefeated = (zpSim.epicsDefeated || 0) + 1;
            if (this.isOfflineSimulating && this._offlineStatsContext) {
                recordOfflineBossEpicQuestTally(this._offlineStatsContext, {
                    isEpic: true,
                    species: enemy.name,
                    zoneId: Number(currentZone),
                });
            } else {
                this.checkSpecialQuests('epicDefeated', { species: enemy.name, zoneId: Number(currentZone) });
            }
        }

        this.checkAchievements('combatsWon');
        this.checkAchievements('bossDefeated');
        this.checkAchievements('epicDefeated');

        if (enemy && typeof enemy.hasActivePokerus === 'function' && enemy.hasActivePokerus()) {
            if (this.currentPlayerCreature && typeof this.currentPlayerCreature.tryInfectPokerus === 'function') {
                const prevActive = this.currentPlayerCreature.hasActivePokerus?.();
                const pokerusResult = this.currentPlayerCreature.tryInfectPokerus?.(Date.now(), { source: 'combat' });
                if (typeof this.currentPlayerCreature.recalculateStats === 'function') {
                    this.currentPlayerCreature._pokerusWasActive = true;
        this.currentPlayerCreature.recalculateStats();
                }
                if (!prevActive) {
                    this.stats.pokerusInfections = (this.stats.pokerusInfections || 0) + 1;
                    this.checkAchievements('pokerusInfections');
                    this.trackHolyGrailCreature(this.currentPlayerCreature);
                    if (this.isOfflineSimulating && this._offlineStatsContext) {
                        (this._offlineStatsContext as Record<string, number>).pokerusInfections = ((this._offlineStatsContext as Record<string, number>).pokerusInfections || 0) + 1;
                    }
                }

                // Suivi du palier Pokérus le plus élevé atteint (pour succès "Virulent Strain")
                const reachedLevel = Number((pokerusResult as { level?: number } | undefined)?.level) || 0;
                if (reachedLevel > (this.stats.pokerusHighestLevel || 0)) {
                    this.stats.pokerusHighestLevel = reachedLevel;
                    this.checkAchievements('pokerusHighestLevel');
                }
                if (typeof this.tryGrantMegaStone === 'function') {
                    this.tryGrantMegaStone(this.currentPlayerCreature, { silent: true });
                }
            }
        }

        const balZ = BALANCE;
        const expMultiplier = isBoss ? balZ.COMBAT_XP_MULT_BOSS : (isEpic ? balZ.COMBAT_XP_MULT_EPIC : balZ.COMBAT_XP_MULT_NORMAL);
        const baseExpGain = Math.floor(enemy.level * expMultiplier);
        const expGain = Math.floor(baseExpGain * this.getExpMultiplier());
        this.distributeCombatExp(expGain, { silent: true });

        const pensionRate = BALANCE.PENSION_EXP_RATIO + ((this.permanentBoosts && this.permanentBoosts.pensionXp) || 0);
        const pensionExpGain = Math.floor(expGain * pensionRate);
        if (pensionExpGain > 0 && this.pension && this.pension.length > 0) {
            let pensionLeveledUp = false;
            this.pension.forEach(c => {
                if (c.gainExp!(pensionExpGain) as unknown as boolean) pensionLeveledUp = true;
            });
            if (pensionLeveledUp && !this.isOfflineSimulating) {
                this.updatePensionDisplay();
                this.incrementPlayerStats();
            }
        }

        const pokedollars = calculateCombatPokedollars(this, currentZone, isBoss, isEpic);
        const combatGoldSim = this.addCombatPokedollars(pokedollars, 'combat_simulated');

        const zoneDef = ZONES[currentZone];
        const maxTier = Number(zoneDef?.maxTier) || 50;
        if (zpSim) {
            if (!zpSim.pokemonTiers) zpSim.pokemonTiers = {};
            incrementZonePokemonTier(zpSim.pokemonTiers, enemy.name, maxTier);
        }

        const dropsInThisCombat: Record<string, number> = {};

        const droppedItem = this.rollItemDrop(true, isBoss
            ? { excludeHeldItemsAtRarities: ['legendary'], premiumLootWeightMult: OUTSIDE_TOWER_PREMIUM_LOOT_MULT }
            : { premiumLootWeightMult: OUTSIDE_TOWER_PREMIUM_LOOT_MULT });

        if (droppedItem) {
            dropsInThisCombat[droppedItem] = 1;
        }
        if (isBoss) {
            const tradeStoneDrop = this.tryDropTradeStone('Boss (Simulation)');
            if (tradeStoneDrop) {
                dropsInThisCombat[tradeStoneDrop] = (dropsInThisCombat[tradeStoneDrop] || 0) + 1;
            }
            const prestigeStoneDrop = this.tryDropPrestigeStone('Boss (Simulation)');
            if (prestigeStoneDrop) {
                dropsInThisCombat[prestigeStoneDrop] = (dropsInThisCombat[prestigeStoneDrop] || 0) + 1;
            }
            const tmEraserDrop = this.tryDropTmEraser(
                'Boss (Simulation)',
                TM_ERASER_BOSS_DROP_CHANCE * OUTSIDE_TOWER_TM_ERASER_MULT,
            );
            if (tmEraserDrop) {
                dropsInThisCombat[tmEraserDrop] = (dropsInThisCombat[tmEraserDrop] || 0) + 1;
            }
            const heldDrop = this.tryDropHeldItem('Boss (Simulation)');
            if (heldDrop) {
                dropsInThisCombat[heldDrop] = (dropsInThisCombat[heldDrop] || 0) + 1;
            }
        } else if (isEpic) {
            const prestigeStoneDrop = this.tryDropPrestigeStone('Epic (Simulation)', 0.025);
            if (prestigeStoneDrop) {
                dropsInThisCombat[prestigeStoneDrop] = (dropsInThisCombat[prestigeStoneDrop] || 0) + 1;
            }
        }

        const balTk = BALANCE;
        const ticketDropMult = this.getMasteryBonus ? (this.getMasteryBonus('combat_ticket_drop_mult') || 0) : 0;
        const bossTicketChance = balTk.COMBAT_TICKET_CHANCE_BOSS * (1 + ticketDropMult);
        const epicTicketChance = balTk.COMBAT_TICKET_CHANCE_EPIC * (1 + ticketDropMult);
        if ((isBoss && Math.random() < bossTicketChance) || (isEpic && Math.random() < epicTicketChance)) {
            this.combatTickets++;
            logMessage(this.t('log.combatTicketFound'));
        }

        if (isBoss) {
            const timeDustDrop = this.tryDropTimeDust('Boss (Simulation)', 0, { outsideTower: true });
            if (timeDustDrop) {
                dropsInThisCombat[timeDustDrop] = (dropsInThisCombat[timeDustDrop] || 0) + 1;
            }
        }

        if (isBoss) {
            const bossEggRarity = rollBossEggRarity();
            this.addEgg(bossEggRarity);
            const bossEggKey = `egg_${bossEggRarity}`;
            dropsInThisCombat[bossEggKey] = (dropsInThisCombat[bossEggKey] || 0) + 1;

            if (Math.random() < 0.5) {
                const bonusEggRarity = this.determineEggRarity();
                this.addEgg(bonusEggRarity);
                const bonusKey = `egg_${bonusEggRarity}`;
                dropsInThisCombat[bonusKey] = (dropsInThisCombat[bonusKey] || 0) + 1;
            }
        } else if (isEpic) {
            const rareKey = `egg_${RARITY.RARE}`;
            this.addEgg(RARITY.RARE);
            dropsInThisCombat[rareKey] = (dropsInThisCombat[rareKey] || 0) + 1;

            if (Math.random() < 0.3) {
                const epicKey = `egg_${RARITY.EPIC}`;
                this.addEgg(RARITY.EPIC);
                dropsInThisCombat[epicKey] = (dropsInThisCombat[epicKey] || 0) + 1;
            }
        } else {
            const baseEggChance = currentZone * 0.001 + 0.01;
            const classicZoneEggChance = (baseEggChance + this.getEggDropBonus()) * 0.5;
            if (Math.random() < classicZoneEggChance) {
                const eggRarity = this.determineEggRarity();
                this.addEgg(eggRarity);

                const eggName = `egg_${eggRarity}`;
                dropsInThisCombat[eggName] = (dropsInThisCombat[eggName] || 0) + 1;
            }
        }

        let capturedData = null;


        if (this.hasAutoCatcher) {
            if (typeof this._syncCaptureTargetsToCurrentZone === 'function') {
                this._syncCaptureTargetsToCurrentZone();
            }
            const targets = [];
            if (Array.isArray(this.captureTargets)) targets.push(...this.captureTargets);
            if (this.captureTarget && !targets.includes(this.captureTarget)) targets.push(this.captureTarget);
            const settings = this.normalizeAutoCatcherSettings
                ? this.normalizeAutoCatcherSettings()
                : (this.autoCatcherSettings || {
                    enabled: true,
                    catchShiny: true,
                    catchRoamer: true,
                    catchLegendary: true,
                    minCatchChancePct: 75,
                    useMasterballActiveTargets: false,
                    useMasterballShiny: true,
                    useMasterballRoamer: true,
                    useMasterballLegendary: false,
                });
            const autoTargetsEnabled = settings.enabled !== false;
            const inTargetMode = this.captureMode === 2;
            const targetMatches = targets.includes(enemy.name);
            const enemyPayload = {
                name: enemy.name,
                rarity: enemy.rarity,
                isShiny: enemy.isShiny,
                isRoaming: enemy.isRoaming,
            };
            const shouldCatchTarget = autoTargetsEnabled && inTargetMode && targetMatches;
            const shouldCatchSpecial = isAutoCatchSpecialEligible(this, enemyPayload, settings);
            if (!shouldCatchTarget && !shouldCatchSpecial) {
                return {
                    xp: expGain,
                    money: pokedollars,
                    items: dropsInThisCombat,
                    captured: null
                };
            }

            if (shouldCatchTarget || shouldCatchSpecial) {
                const captureContext = shouldCatchSpecial
                    ? resolveAutoCatchCaptureContext(this, enemyPayload, settings)
                    : 'active';
                const ballType = pickAutoCatchBall(this, enemyPayload, settings, captureContext);
                if (ballType && (this.items[ballType] || 0) > 0) {
                    const recycleLevel = (this.upgrades && this.upgrades.recycle) ? this.upgrades.recycle.level : 0;
                    const recycleChance = recycleLevel * 0.025;
                    if (Math.random() >= recycleChance) {
                        const ballCount = this.items[ballType];
                        if (ballCount !== undefined && ballCount > 0) this.items[ballType] = ballCount - 1;
                    }

                    const finalCatchChance = getEffectiveCatchRate(this, {
                        name: enemy.name,
                        rarity: enemy.rarity,
                    }, ballType, { isAutoCatch: true });

                    if (Math.random() < finalCatchChance) {
                        this.stats.creaturesObtained++;
                        if (typeof this._recordDailyActivity === 'function') this._recordDailyActivity('captures', 1);
                        this.addRocketTrustProgress('capture', 1, { species: enemy.name });

                        const capturedName = resolveCanonicalSpeciesName(enemy.name);
                        const trueRarity = speciesRarityForCapture(this, capturedName);
                        const capturedCreature = new Creature(
                            capturedName,
                            enemy.type,
                            enemy.level,
                            trueRarity,
                            false,
                            enemy.isShiny,
                            enemy.secondaryType,
                            false,
                            false,
                            !!enemy.isShadow
                        );
                        capturedCreature.ivHP = enemy.ivHP; capturedCreature.ivAttack = enemy.ivAttack;
                        capturedCreature.ivSpAttack = enemy.ivSpAttack; capturedCreature.ivSpDefense = enemy.ivSpDefense;
                        capturedCreature.ivDefense = enemy.ivDefense; capturedCreature.ivSpeed = enemy.ivSpeed;
                        capturedCreature.nature = normalizeNatureId(
                            typeof enemy.nature === 'string' ? enemy.nature : pickRandomNature(),
                        );
                        assignRegionalArcId(
                            capturedCreature,
                            typeof this.getCurrentRegionId === 'function'
                                ? this.getCurrentRegionId()
                                : 'kanto',
                        );
                        capturedCreature.recalculateStats();
                        invalidateResonanceCache(this);
                        if (capturedCreature.isShiny) {
                            this.stats.shiniesObtained++;
                            this.checkAchievements('shiniesObtained');
                            if (!this.isOfflineSimulating && typeof this.checkSpecialQuests === 'function') {
                                this.checkSpecialQuests('shiniesObtained');
                            }
                        }
                        if (typeof this.recordPerfectCreatureObtained === 'function') {
                            this.recordPerfectCreatureObtained(capturedCreature);
                        } else {
                            const isPerfectCapture = typeof this.isCreaturePerfect === 'function' && this.isCreaturePerfect(capturedCreature);
                            if (isPerfectCapture) {
                                this.stats.perfectIvCount++;
                                this.checkAchievements('perfectIvCount');
                                if (capturedCreature.isShiny) {
                                    this.stats.perfectShinyCount++;
                                    this.checkAchievements('perfectShinyCount');
                                }
                            }
                            this.trackHolyGrailCreature(capturedCreature);
                        }

                        let unlockedNatureForFamily = false;
                        let unlockedNatureName = '';
                        let unlockedMoveForFamily = false;
                        let unlockedMoveName = '';
                        if (typeof this.tryUnlockMoveFromCaptureOrEgg === 'function') {
                            const moveToUnlock = capturedCreature.getMove();
                            const unlockRes = this.tryUnlockMoveFromCaptureOrEgg(capturedCreature.name, moveToUnlock);
                            unlockedMoveForFamily = !!unlockRes;
                            unlockedMoveName = typeof unlockRes === 'string' ? unlockRes : '';
                            if (unlockedMoveForFamily && !this.isOfflineSimulating && typeof toast !== 'undefined') {
                                const title = combatText(this, '', 'Nouvelle Attaque', 'New Move');
                                const body = combatText(
                                    this,
                                    '',
                                    '{name} a debloque {move} pour toute sa famille !',
                                    '{name} unlocked {move} for its whole family!',
                                    { name: capturedCreature.name, move: unlockedMoveName }
                                );
                                toast.info(title, body, 2500, true);
                            }
                            if (unlockedMoveForFamily && this.isOfflineSimulating && this._offlineStatsContext) {
                                const ctx = this._offlineStatsContext as Record<string, number>;
                                ctx.moveUnlocksByFarm = (ctx.moveUnlocksByFarm || 0) + 1;
                            }
                        }

                        const pokedexKey = capturedCreature.name + "_" + capturedCreature.type + "_" + capturedCreature.rarity;
                        const existing = this.findCreatureByName(capturedCreature.name, capturedCreature.isShiny, capturedCreature.isShadow);
                        // Snapshot pre-capture: detecte une nouvelle decouverte d'espece et une 1ere forme shiny.
                        const wasNewDiscovery = !this.pokedex[pokedexKey];
                        const existingShiny = capturedCreature.isShiny
                            ? this.findCreatureByName(capturedCreature.name, true, capturedCreature.isShadow)
                            : null;
                        const wasNewShinyDiscovery = !!capturedCreature.isShiny && !existingShiny;
                        if (!this.pokedex[pokedexKey]) {
                            this.pokedex[pokedexKey] = createPokedexEntryFromCapture({
                                name: capturedCreature.name,
                                type: capturedCreature.type,
                                rarity: capturedCreature.rarity,
                                isShiny: !!capturedCreature.isShiny,
                                isShadow: !!capturedCreature.isShadow,
                            });
                        } else {
                            applyPokedexCaptureEntry(this.pokedex[pokedexKey], {
                                isShiny: !!capturedCreature.isShiny,
                                isShadow: !!capturedCreature.isShadow,
                            });
                        }
                        if (existing) {
                            if (typeof this.tryUnlockNatureFromCaptureOrEgg === 'function') {
                                const natureUnlockRes = this.tryUnlockNatureFromCaptureOrEgg(capturedCreature.name);
                                unlockedNatureForFamily = !!natureUnlockRes;
                                unlockedNatureName = typeof natureUnlockRes === 'string' ? natureUnlockRes : '';
                                if (unlockedNatureForFamily && !this.isOfflineSimulating && typeof toast !== 'undefined') {
                                    const natureTitle = combatText(this, '', 'Nouvelle Nature', 'New Nature');
                                    const natureLabel = typeof this.getLocalizedNatureName === 'function'
                                        ? this.getLocalizedNatureName(unlockedNatureName)
                                        : unlockedNatureName;
                                    const natureBody = combatText(
                                        this,
                                        '',
                                        '{name} a debloque la nature {nature} pour toute sa famille !',
                                        '{name} unlocked nature {nature} for its whole family!',
                                        { name: capturedCreature.name, nature: natureLabel },
                                    );
                                    toast.info(natureTitle, natureBody, 2500, true);
                                }
                            }
                            if (unlockedMoveForFamily && typeof this.checkSpecialQuests === 'function') {
                                this.checkSpecialQuests('move_unlocked_by_farm', { species: capturedCreature.name, moveName: unlockedMoveName });
                            }
                            if (typeof this.checkSpecialQuests === 'function') {
                                this.checkSpecialQuests('fusion_completed', { species: capturedCreature.name });
                                const natRarity = (typeof this.getNaturalRarity === 'function')
                                    ? this.getNaturalRarity(enemy.name)
                                    : null;
                                if (capturedCreature.rarity === 'rare' || natRarity === RARITY.RARE) {
                                    this.checkSpecialQuests('rareObtained', { rarity: 'rare' });
                                }
                            }
                            this.processFusion(capturedCreature, existing);
                        } else {
                            this.storage.push(capturedCreature);
                            if (typeof this.registerCreatureMovesForFamily === 'function') {
                                this.registerCreatureMovesForFamily(capturedCreature);
                            }
                            if (typeof this.registerCreatureNaturesForFamily === 'function') {
                                this.registerCreatureNaturesForFamily(capturedCreature);
                            }
                        }
                        const captureQuestParams = buildCaptureQuestEventParams(
                            capturedCreature,
                            Number(currentZone),
                            { isAutoCatch: true },
                        );
                        capturedData = {
                            name: enemy.name,
                            shiny: enemy.isShiny,
                            isShiny: !!enemy.isShiny,
                            rarity: capturedCreature.rarity,
                            creatureType: capturedCreature.type,
                            secondaryType: capturedCreature.secondaryType,
                            wasNewDiscovery: !!wasNewDiscovery,
                            wasNewShinyDiscovery: !!wasNewShinyDiscovery,
                            zoneId: Number(currentZone),
                            ivHP: capturedCreature.ivHP,
                            ivAttack: capturedCreature.ivAttack,
                            ivDefense: capturedCreature.ivDefense,
                            ivSpAttack: capturedCreature.ivSpAttack,
                            ivSpDefense: capturedCreature.ivSpDefense,
                            ivSpeed: capturedCreature.ivSpeed,
                            ivPercent: captureQuestParams.ivPercent,
                        };
                        if (typeof this.checkSpecialQuests === 'function') {
                            const natRarity = (typeof this.getNaturalRarity === 'function')
                                ? this.getNaturalRarity(enemy.name)
                                : null;
                            if (this.isOfflineSimulating && this._offlineStatsContext) {
                                if (gameHasActiveOfflineCaptureQuest(this)) {
                                    recordOfflineCaptureQuestTally(this._offlineStatsContext, captureQuestParams);
                                }
                            } else {
                                if (capturedCreature.rarity === RARITY.LEGENDARY || natRarity === RARITY.LEGENDARY) {
                                    this.checkSpecialQuests('legendary_obtained');
                                }
                                this.checkSpecialQuests('creature_captured_any', captureQuestParams);
                            }
                        }
                    }
                }
            }
        }

        if (this.farmingMetrics && this.farmingMetrics.recording) {
            const simEggs: Record<string, number> = {};
            const simItems: string[] = [];
            Object.keys(dropsInThisCombat).forEach(k => {
                const count = dropsInThisCombat[k] || 0;
                if (k.indexOf('egg_') === 0) {
                    const r = k.replace('egg_', '');
                    simEggs[r] = (simEggs[r] || 0) + count;
                } else {
                    for (let i = 0; i < count; i++) simItems.push(k);
                }
            });
            const collecteurBonus = this.getTalentStackBonus('collecteur');
            const mentorBonus = this.getTalentStackBonus('mentor');
            const expMult = this.getExpMultiplier();
            const combatType = isBoss ? 'boss' : (isEpic ? 'epic' : (enemy.isRoaming ? 'roamer' : 'classic'));
            const combatDurationMs = this.combatStartTime ? Math.max(0, Date.now() - this.combatStartTime) : 0;
            const shinyEncountered = !!(enemy && enemy.isShiny);
            const shinyCaptured = shinyEncountered && !!capturedData;
            this.recordFarmingMetricsCombat({
                pokedollarsTotal: pokedollars,
                pokedollarsToWallet: (combatGoldSim && combatGoldSim.creditedToWallet) || 0,
                pokedollarsToBank: (combatGoldSim && combatGoldSim.injectedToBank) || 0,
                pokedollarsToDebt: (combatGoldSim && combatGoldSim.withheld) || 0,
                xp: expGain,
                pokedollarsFromCollecteur: collecteurBonus > 0 ? Math.floor(pokedollars * (collecteurBonus / (1 + collecteurBonus))) : 0,
                xpFromMentor: mentorBonus > 0 && expMult > 0 ? Math.floor(expGain * (mentorBonus / expMult)) : 0,
                eggs: simEggs,
                items: simItems,
                captures: capturedData ? 1 : 0,
                combatType,
                combatDurationMs,
                combatDurationTurns: getCombatDurationTurns(this),
                shinyEncountered,
                shinyCaptured
            });
        }

        return {
            xp: expGain,
            money: pokedollars,
            items: dropsInThisCombat,
            captured: capturedData
        };
    };

    /**
     * Heal a creature by a flat HP amount.
     * Delegates to applyCombatHeal for HP pool logic (trainer-battle vs shared pool vs enemy).
     * @param {object} creature   - Target creature
     * @param {number} healAmount - Flat HP to restore (caller computes from % if needed)
     */
    GameClass.prototype.applyHeal = function (this: ThisGame, creature: CreatureData, healAmount: number): void {
        if (!creature || !creature.isAlive!() || healAmount <= 0) return;
        const actual = applyCombatHeal(this, creature, Math.floor(healAmount));
        if (actual > 0) {
            logMessage(this.t('log.healRecovered', { name: creature.name, hp: formatNumber(actual) }));
            this.updateCombatDisplay();
        }
    };

    GameClass.prototype.activateUltimate = function (this: ThisGame, options?: Record<string, unknown>): void {
        const creature = this.currentPlayerCreature;
        if (!creature) return;
        activateCreatureUltimate(this, creature, {
            source: options && typeof options === 'object' ? String(options.source ?? '') : undefined,
            trackPlayerStats: true,
        });
    };

    GameClass.prototype.activateMegaEvolution = function (this: ThisGame): void {
        const creature = this.currentPlayerCreature;
        if (!creature) return;
        if (!creature.megaStoneUnlocked) return;
        const megaCfg = getMegaEvolutionConfig(creature.name, creature);
        if (!megaCfg) return;
        if (creature._megaStatsSourceName) {
            logMessage(this.t('log.megaAlreadyActive'));
            return;
        }
        const megaMax = typeof this.getMegaGaugeRequired === 'function'
            ? this.getMegaGaugeRequired()
            : (typeof MEGA_GAUGE_MAX === 'number' ? MEGA_GAUGE_MAX : 100);
        if ((creature.megaGauge || 0) < megaMax) {
            logMessage(this.t('log.megaGaugeLow'));
            return;
        }
        const dur = typeof this.getMegaEvolutionDurationMs === 'function'
            ? this.getMegaEvolutionDurationMs()
            : (typeof MEGA_EVOLUTION_DURATION_MS === 'number' ? MEGA_EVOLUTION_DURATION_MS : 60000);
        const trainerBattleMega = isTrainerBattle(this);
        let ratio = 1;
        if (trainerBattleMega) {
            ratio = creature.maxHp > 0 ? creature.currentHp / creature.maxHp : 1;
        } else if (typeof this.getPlayerMaxHp === 'function') {
            const mh = this.getPlayerMaxHp();
            ratio = mh > 0 ? (creature.mainAccountCurrentHp || 0) / mh : 1;
        }
        creature.megaGauge = 0;
        creature._megaStatsSourceName = String(megaCfg.megaFormName);
        const applyMegaCombatTypes = creature.applyMegaCombatTypes;
        if (typeof applyMegaCombatTypes === 'function') {
            applyMegaCombatTypes.call(creature, {
                type: megaCfg.type,
                secondaryType: megaCfg.secondaryType
            });
        }
        creature._megaRemainingMs = dur;
        creature._megaDurationMs = dur;
        creature._megaTimerLastTickAt = null;
        if (this.combatState === 'fighting' && typeof creature.resumeMegaEvolutionTimer === 'function') {
            creature.resumeMegaEvolutionTimer();
        }
        if (typeof this.invalidateStatsCache === 'function') this.invalidateStatsCache();
        creature.recalculateStats!();
        if (isTrainerBattle) {
            creature.currentHp = Math.min(creature.maxHp, Math.max(0, Math.floor(creature.maxHp * ratio)));
        } else if (typeof this.getPlayerMaxHp === 'function') {
            const nh = this.getPlayerMaxHp();
            const nc = Math.min(nh, Math.max(0, Math.floor(nh * ratio)));
            creature.mainAccountCurrentHp = nc;
            creature.currentHp = Math.min(creature.maxHp, nc);
        }
        logMessage(this.t('log.megaEvolutionUsed', { name: creature.name }));
        this.updateCombatDisplay();
    };

    GameClass.prototype.finalizeCombat = function (this: ThisGame, captured?: boolean): void {
        const enemy = this.currentEnemy;
        if (!enemy) return;

        const persistSentinelle = !!this.arenaState?.active;
        if (this.currentPlayerCreature) {
            this.currentPlayerCreature.clearStatusEffect!();
            this.currentPlayerCreature.berserkStacks = 0;
            if (!persistSentinelle) this.currentPlayerCreature.sentinelleStacks = 0;
        }
        // Fin de round : plus d'ultime « en attente de frappe » (sinon le 1er tour du combat suivant
        // consomme le drapeau sans gain de charge et la jauge semble bloquée à 0).
        if (Array.isArray(this.playerTeam)) {
            this.playerTeam.forEach(c => { if (c) c.ultimateActive = false; });
        }
        // Méga : ne pas terminer ici. Budget + tickMegaEvolutionIfExpired (pause hors fighting / banc).

        // Reset Berserker chaque fin de round ; Sentinelle seulement hors arène (run arène = un seul combat)
        if (Array.isArray(this.playerTeam)) {
            this.playerTeam.forEach(c => {
                if (!c) return;
                if (!persistSentinelle) c.sentinelleStacks = 0;
                c.berserkStacks = 0;
            });
        }

        // =================================================
        // CAS 0 : MENACE FERME (avant subway/tour — runs toujours actifs en arrière-plan)
        // =================================================
        if (this.gymTrainerState?.active && this.gymTrainerState.isFarmThreat) {
            const gts = this.gymTrainerState;
            gts.currentIndex = (gts.currentIndex || 0) + 1;
            if (gts.currentIndex < gts.team.length) {
                commitCombatTurnDuelAndReset(this);
                const idx = gts.currentIndex;
                this.currentEnemy = arrayAt(gts.team, idx) ?? null;
                const threatEnemy = this.currentEnemy;
                if (!threatEnemy) return;
                threatEnemy._focusSashUsed = false;
                threatEnemy.clearStatusEffect?.();
                logMessage(this.t('log.championSends', { name: threatEnemy.name }));
                this.combatState = 'fighting';
                syncMegaTimerWithCombatState(this);
                syncDynamaxTimerWithCombatState(this);
                tryAutoSwitchAdvantage(this);
                if (this.currentPlayerCreature) this.currentPlayerCreature.actionGauge = 0;
                if (this.currentEnemy) this.currentEnemy.actionGauge = 0;
                applyHazardEntryTalentOnEnemyEntry(this as unknown as GameRuntime, threatEnemy);
                refreshTeamAfterCombat(this);
                this.updateCombatDisplay();
                return;
            }
            if (gts.farmThreatId) {
                flushCombatTurnRecords(this);
                const threatId = String(gts.farmThreatId);
                this.gymTrainerState = null;
                this.faintedThisCombat = new Set();
                this.faintedUidsThisCombat = new Set();
                resolveFarmThreatCombatWin(this, threatId);
                syncMegaTimerWithCombatState(this);
                syncDynamaxTimerWithCombatState(this);
                if (typeof this._applyActiveFirstAfterCombatIfNeeded === 'function') {
                    this._applyActiveFirstAfterCombatIfNeeded();
                }
                refreshTeamAfterCombat(this);
                this.updateCombatDisplay();
                return;
            }
            return;
        }

        // =================================================
        // CAS 0.45 : CHAMPIONS TOWER
        // =================================================
        if (this.championsTowerState?.isActive) {
            advanceChampionsTowerAfterPokemonWinLogic(this);
            flushCombatTurnRecords(this);
            refreshTeamAfterCombat(this);
            this.updateCombatDisplay();
            return;
        }

        // =================================================
        // CAS 0.5 : BATTLE SUBWAY
        // =================================================
        if (this.subwayState?.isActive) {
            this.subwayState.currentEnemyIndex++;
            if (this.subwayState.currentEnemyIndex < this.subwayState.enemyTeam.length) {
                commitCombatTurnDuelAndReset(this);
                this.currentEnemy = arrayAt(this.subwayState.enemyTeam, this.subwayState.currentEnemyIndex) ?? null;
                const subwayEnemy = this.currentEnemy;
                if (!subwayEnemy) return;
                subwayEnemy._focusSashUsed = false;
                subwayEnemy.clearStatusEffect?.();
                logMessage(this.t('log.championSends', { name: subwayEnemy.name }));
                this.combatState = 'fighting';
                syncMegaTimerWithCombatState(this);
                syncDynamaxTimerWithCombatState(this);
                tryAutoSwitchAdvantage(this);
                if (this.currentPlayerCreature) this.currentPlayerCreature.actionGauge = 0;
                if (this.currentEnemy) this.currentEnemy.actionGauge = 0;
                applyHazardEntryTalentOnEnemyEntry(this as unknown as GameRuntime, subwayEnemy);
                refreshTeamAfterCombat(this);
                this.updateCombatDisplay();
                return;
            }
            advanceSubwayAfterTrainerWinLogic(this);
            flushCombatTurnRecords(this);
            refreshTeamAfterCombat(this);
            this.updateCombatDisplay();
            return;
        }

        // =================================================
        // CAS 1 : TOUR DE COMBAT
        // =================================================
        if (this.towerState.isActive) {
            this.trackTowerGenerationProgress(enemy);

            const towerMult = getTowerVictoryExpLevelMult(BALANCE.TOWER_VICTORY_EXP_LEVEL_MULT, this.permanentBoosts);
            const expGain = Math.floor(enemy.level * towerMult * this.getExpMultiplier());
            this.playerTeam.forEach(c => c.gainExp!(expGain));

            let pensionExpGain = 0;
            if (this.unlockedFeatures?.towerPensionXp) {
                const pensionRate = BALANCE.PENSION_EXP_RATIO + ((this.permanentBoosts && this.permanentBoosts.pensionXp) || 0);
                pensionExpGain = Math.floor(expGain * pensionRate);
                if (pensionExpGain > 0 && this.pension && this.pension.length > 0) {
                    let pensionLeveledUp = false;
                    this.pension.forEach(c => {
                        if (c.gainExp!(pensionExpGain) as unknown as boolean) pensionLeveledUp = true;
                    });
                    if (pensionLeveledUp) {
                        this.updatePensionDisplay();
                        this.incrementPlayerStats();
                    }
                }
            }
            recordTowerRunXp(this.towerState.runStats, expGain, pensionExpGain);

            this.triumphMarks = Number(this.triumphMarks) || 0;
            const floor = this.towerState.currentFloor;
            const isTowerBossFloor = floor % BALANCE.TOWER_ENEMY.BOSS_FLOOR_INTERVAL === 0;
            let marksWon = 1 + Math.floor(floor / 100);
            if (Math.random() < ((floor % 100) / 100)) marksWon++;
            const towerPrime = this.towerState && this.towerState.buffs ? Number(this.towerState.buffs.triumph_marks_flat || 0) : 0;
            if (towerPrime > 0) marksWon += Math.min(3, towerPrime);
            if (isTowerBossFloor) {
                const bossBonus = Math.min(5, Math.max(0, Math.floor(Number((this.permanentBoosts && this.permanentBoosts.boss_mark_bonus) || 0))));
                if (bossBonus > 0) marksWon += bossBonus;
            }

            if (marksWon > 0) {
                if (typeof this.scaleMasteryTriumphMarksAmount === 'function') {
                    marksWon = this.scaleMasteryTriumphMarksAmount(marksWon);
                }
                this.triumphMarks += marksWon;
                if (this.stats) this.stats.totalTriumphMarksEarned = (this.stats.totalTriumphMarksEarned || 0) + marksWon;
                if (this.towerState.runStats) {
                    this.towerState.runStats.marksGained = (this.towerState.runStats.marksGained || 0) + marksWon;
                }
                if (document.getElementById('enemySpriteContainer')) {
                    const marksSpriteUrl = 'https://raw.githubusercontent.com/msikma/pokesprite/master/items/valuable-item/relic-crown.png';
                    const marksHtml = `<span class="floating-marks-reward"><img src="${marksSpriteUrl}" alt="" class="floating-marks-reward-icon">+${marksWon}</span>`;
                    showFloatingText(
                        { text: `+${marksWon}`, html: marksHtml },
                        document.getElementById('enemySpriteContainer'),
                        'ft-damage-enemy ft-tower-marks'
                    );
                }
            }

            if (isTowerBossFloor) {
                const lootBonus = getTowerBossLootBonus(
                    this.permanentBoosts && this.permanentBoosts.tower_boss_loot_bonus,
                );
                const droppedItem = this.rollItemDrop(false, {
                    excludeHeldItemsAtRarities: ['legendary'],
                    lootMultBonus: lootBonus,
                });
                if (droppedItem && this.towerState.runStats) {
                    const stats = this.towerState.runStats;
                    stats.items = stats.items || {};
                    stats.items[droppedItem] = (stats.items[droppedItem] || 0) + 1;
                }
                const timeDustDrop = this.tryDropTimeDust('Boss Tour', lootBonus);
                this.tryDropHeldItem('Boss Tour', lootBonus);
                if (timeDustDrop && this.towerState.runStats) {
                    const stats = this.towerState.runStats;
                    stats.items = stats.items || {};
                    stats.items[timeDustDrop] = (stats.items[timeDustDrop] || 0) + 1;
                }
                const tradeStoneDrop = this.tryDropTradeStone('Boss Tour', lootBonus);
                if (tradeStoneDrop && this.towerState.runStats) {
                    const stats = this.towerState.runStats;
                    stats.items = stats.items || {};
                    stats.items[tradeStoneDrop] = (stats.items[tradeStoneDrop] || 0) + 1;
                }
                const prestigeStoneDrop = this.tryDropPrestigeStone(
                    'Boss Tour',
                    effectiveDropChance(0.05, lootBonus),
                );
                if (prestigeStoneDrop && this.towerState.runStats) {
                    const stats = this.towerState.runStats;
                    stats.items = stats.items || {};
                    stats.items[prestigeStoneDrop] = (stats.items[prestigeStoneDrop] || 0) + 1;
                }
                const tmEraserDrop = this.tryDropTmEraser(
                    'Boss Tour',
                    effectiveDropChance(0.02, lootBonus),
                );
                if (tmEraserDrop && this.towerState.runStats) {
                    const stats = this.towerState.runStats;
                    stats.items = stats.items || {};
                    stats.items[tmEraserDrop] = (stats.items[tmEraserDrop] || 0) + 1;
                }

                const bossEggRarity = rollBossEggRarityWithBonus(lootBonus);
                this.addEgg(bossEggRarity);
                if (this.towerState.runStats) {
                    const stats = this.towerState.runStats;
                    stats.eggs = stats.eggs || {};
                    stats.eggs[bossEggRarity] = (stats.eggs[bossEggRarity] || 0) + 1;
                }

                logMessage(this.t('log.towerBossDefeatedLog', { marks: marksWon, rarity: bossEggRarity }));
                toast.success(this.t('toast.towerBossTitle'), this.t('toast.towerBossBody', { marks: marksWon, rarity: bossEggRarity }));
            }

            this.towerState.currentEnemyIndex++;
            if (this.towerState.currentEnemyIndex < this.towerState.enemyTeam.length) {
                commitCombatTurnDuelAndReset(this);
                this.currentEnemy = arrayAt(this.towerState.enemyTeam, this.towerState.currentEnemyIndex) ?? null;
                if (this.currentEnemy) this.currentEnemy._focusSashUsed = false;
                this.combatState = 'starting';
                syncMegaTimerWithCombatState(this);
                syncDynamaxTimerWithCombatState(this);
                this.combatStartTime = Date.now();
                if (this.currentPlayerCreature) this.currentPlayerCreature.actionGauge = 0;
                if (this.currentEnemy) this.currentEnemy.actionGauge = 0;
                onTowerEnemyEntered(this as unknown as GameRuntime, this.currentEnemy);
            } else {
                flushCombatTurnRecords(this);
                this.nextTowerFloor();
            }

            refreshTeamAfterCombat(this);
            this.updateCombatDisplay();
            return;
        }

        // =================================================
        // CAS 2 : ARENE
        // =================================================
        if (this.arenaState.active) {
            const team = this.arenaState.championTeam;
            let idx = (this.arenaState.currentChampionIndex ?? 0) + 1;
            while (idx < team.length && !arrayAt(team, idx)) idx++;
            this.arenaState.currentChampionIndex = idx;
            if (idx >= team.length) {
                flushCombatTurnRecords(this);
                this.winArena();
            } else {
                commitCombatTurnDuelAndReset(this);
                this.currentEnemy = arrayAt(team, idx) ?? null;
                const arenaEnemy = this.currentEnemy;
                if (!arenaEnemy) {
                    flushCombatTurnRecords(this);
                    this.winArena();
                    return;
                }
                arenaEnemy._focusSashUsed = false;
                arenaEnemy.clearStatusEffect!();
                if (this.isEliteFourArenaId(this.arenaState.arenaId!)) {
                    const prevTrainer = this.getEliteFourTrainerNameAtSlot(idx - 1, this.arenaState.arenaId);
                    const curTrainer = this.getEliteFourTrainerNameAtSlot(idx, this.arenaState.arenaId);
                    if (curTrainer && curTrainer !== prevTrainer) {
                        logMessage(this.t('log.trainerChallenges', { name: curTrainer }));
                        resetEnemyArenaSwitchCountersOnEliteFourTrainerChange(
                            this as unknown as GameRuntime,
                            idx - 1,
                            idx,
                        );
                    }
                }
                logMessage(this.t('log.championSends', { name: arenaEnemy.name }));
                this.combatState = 'fighting';
                syncMegaTimerWithCombatState(this);
                syncDynamaxTimerWithCombatState(this);
                tryAutoSwitchAdvantage(this);
                if (this.currentPlayerCreature) this.currentPlayerCreature.actionGauge = 0;
                if (this.currentEnemy) this.currentEnemy.actionGauge = 0;
                applyHazardEntryTalentOnEnemyEntry(this as unknown as GameRuntime, arenaEnemy);
                refreshTeamAfterCombat(this);
                this.updateCombatDisplay();
            }
            return;
        }

        // =================================================
        // CAS 2.5 : DRESSEUR GYM
        // =================================================
        if (this.gymTrainerState && this.gymTrainerState.active) {
            const gts = this.gymTrainerState;
            gts.currentIndex = (gts.currentIndex || 0) + 1;
            if (gts.currentIndex < gts.team.length) {
                commitCombatTurnDuelAndReset(this);
                const idx = gts.currentIndex;
                this.currentEnemy = arrayAt(gts.team, idx) ?? null;
                const gymEnemy = this.currentEnemy;
                if (!gymEnemy) return;
                gymEnemy._focusSashUsed = false;
                gymEnemy.clearStatusEffect!();
                logMessage(this.t('log.championSends', { name: gymEnemy.name }));
                this.combatState = 'fighting';
                syncMegaTimerWithCombatState(this);
                syncDynamaxTimerWithCombatState(this);
                tryAutoSwitchAdvantage(this);
                if (this.currentPlayerCreature) this.currentPlayerCreature.actionGauge = 0;
                if (this.currentEnemy) this.currentEnemy.actionGauge = 0;
                applyHazardEntryTalentOnEnemyEntry(this as unknown as GameRuntime, gymEnemy);
                refreshTeamAfterCombat(this);
                this.updateCombatDisplay();
                return;
            } else {
                const zpGym = this.zoneProgress?.[currentZone];
                if (zpGym) {
                    zpGym.trainersDefeated = (zpGym.trainersDefeated || 0) + 1;
                }
                const pokedollarsEarned = calculateCombatPokedollars(this, currentZone, false, false, 1.25);
                const combatGold = this.addCombatPokedollars(pokedollarsEarned, 'combat');
                if (pokedollarsEarned > 0) this.showUiFloatingText('headerStatMoney', `+${formatNumber(combatGold.creditedToWallet || combatGold.net)}$`, 'ft-money');
                const balXp = BALANCE;
                const baseExpGain = Math.floor(enemy.level * balXp.COMBAT_XP_MULT_NORMAL * balXp.GYM_TRAINER_XP_BONUS_MULT);
                const expGain = Math.floor(baseExpGain * this.getExpMultiplier());
                this.distributeCombatExp(expGain, { silent: false });
                this.rollItemDrop(false, { premiumLootWeightMult: OUTSIDE_TOWER_PREMIUM_LOOT_MULT });
                if (this.farmingMetrics && this.farmingMetrics.recording) {
                    const collecteurBonus = this.getTalentStackBonus('collecteur');
                    const mentorBonus = this.getTalentStackBonus('mentor');
                    const expMult = this.getExpMultiplier();
                    const trainerCombatDurationMs = this.combatStartTime ? Math.max(0, Date.now() - this.combatStartTime) : 0;
                    this.recordFarmingMetricsCombat({
                        pokedollarsTotal: pokedollarsEarned,
                        pokedollarsToWallet: (combatGold && combatGold.creditedToWallet) || 0,
                        pokedollarsToBank: (combatGold && combatGold.injectedToBank) || 0,
                        pokedollarsToDebt: (combatGold && combatGold.withheld) || 0,
                        xp: expGain,
                        pokedollarsFromCollecteur: collecteurBonus > 0 ? Math.floor(pokedollarsEarned * (collecteurBonus / (1 + collecteurBonus))) : 0,
                        xpFromMentor: mentorBonus > 0 && expMult > 0 ? Math.floor(expGain * (mentorBonus / expMult)) : 0,
                        eggs: {},
                        items: [],
                        captures: 0,
                        combatType: 'classic',
                        combatDurationMs: trainerCombatDurationMs,
                        combatDurationTurns: getCombatDurationTurns(this),
                    });
                }
                // ================ BONUS RIVAL "APPARITION DE ZONE" ================
                // Si on vient de battre une apparition Rival adossee a une zone (Route 22, Pont
                // Nugget, etc.), on octroie les recompenses bonus une seule fois par zone.
                if (this.gymTrainerState && this.gymTrainerState.isZoneRival && this.gymTrainerState.rivalRewards) {
                    const rZoneId = this.gymTrainerState.rivalZoneId;
                    const rivalRewards = this.gymTrainerState.rivalRewards as Record<string, unknown>;
                    const alreadyDefeatedRival = !!(this.rivalState && this.rivalState.zonesDefeated && this.rivalState.zonesDefeated[String(rZoneId)]);
                    const rKey = this.gymTrainerState && this.gymTrainerState.rivalEncounterKey
                        ? String(this.gymTrainerState.rivalEncounterKey)
                        : undefined;

                    if (!alreadyDefeatedRival) {
                        const granted: { pokedollars?: number; items?: Record<string, number>; combatTickets?: number } = {};

                        const dollarsMult = Number(rivalRewards.pokedollarsMult) || 0;
                        if (dollarsMult > 0) {
                            const bonusBase = calculateCombatPokedollars(this, currentZone, false, false, 1);
                            const bonusDollars = Math.max(0, Math.floor(bonusBase * dollarsMult));
                            if (bonusDollars > 0) {
                                const bonusGold = this.addCombatPokedollars(bonusDollars, 'rival_zone');
                                const credited = (bonusGold && (bonusGold.creditedToWallet || bonusGold.net)) || bonusDollars;
                                if (credited > 0) granted.pokedollars = credited;
                                this.showUiFloatingText('headerStatMoney', `+${formatNumber(credited)}$`, 'ft-money');
                            }
                        }

                        if (rivalRewards.balls && typeof rivalRewards.balls === 'object') {
                            for (const ballKey of Object.keys(rivalRewards.balls)) {
                                const qty = Math.max(0, Math.floor(Number((rivalRewards.balls as Record<string, number>)[ballKey]) || 0));
                                if (qty > 0 && typeof this.addItem === 'function') {
                                    this.addItem(ballKey, qty, false);
                                    if (!granted.items) granted.items = {};
                                    granted.items[ballKey] = qty;
                                }
                            }
                        }

                        const ticketGainRaw = Math.max(0, Math.floor(Number(rivalRewards.combatTickets) || 0));
                        const ticketGain = typeof this.scaleMasteryCombatTicketAmount === 'function'
                            ? this.scaleMasteryCombatTicketAmount(ticketGainRaw)
                            : ticketGainRaw;
                        if (ticketGain > 0) {
                            this.combatTickets = (this.combatTickets || 0) + ticketGain;
                            granted.combatTickets = ticketGain;
                            logMessage(this.t('log.combatTicketFound') || `+${ticketGain} Ticket de Combat`);
                        }

                        try {
                            const formatRewardText = this.formatRewardText;
                            const rewardHtml = typeof formatRewardText === 'function'
                                ? formatRewardText.call(this, granted)
                                : '';
                            const message = rewardHtml
                                ? `<div class="toast-reward-summary">${rewardHtml}</div>`
                                : this.t('toast.rivalVictoryEmpty');
                            toast.success(this.t('toast.rivalVictoryTitle'), message, 4000, true);
                        } catch (_) { /* toast DOM unavailable */ }
                    }

                    if (typeof this.markRivalZoneDefeated === 'function') {
                        this.markRivalZoneDefeated(rZoneId, rKey);
                    }
                }
                // ================ FIN BONUS RIVAL ================

                flushCombatTurnRecords(this);
                this.gymTrainerState = null;
                this.combatState = 'waiting';
                syncMegaTimerWithCombatState(this);
                syncDynamaxTimerWithCombatState(this);
                this.lastCombatTime = Date.now();
                this.currentEnemy = null;
                this.faintedThisCombat = new Set();
        this.faintedUidsThisCombat = new Set();
                if (typeof this._applyActiveFirstAfterCombatIfNeeded === 'function') this._applyActiveFirstAfterCombatIfNeeded();
                const poolHp = Math.min(this.getPlayerMaxHp(), Math.max(0, this.currentPlayerCreature ? this.currentPlayerCreature.currentHp : 0));
                this.playerTeam.forEach(c => {
                    c.mainAccountCurrentHp = poolHp;
                    if (c.mainAccountCurrentHp > 0) {
                        c.currentHp = Math.min(c.maxHp || c.mainAccountCurrentHp, c.mainAccountCurrentHp);
                    }
                });
                this.updateZoneSelector();
                updateZoneInfo(this);
                refreshTeamAfterCombat(this);
                this.updateCombatDisplay();
                this.updateItemsDisplay();
                this.updateEggsDisplay();
            }
            return;
        }

        // =================================================
        // CAS 3 : COMBAT DE ZONE (Standard)
        // =================================================
        flushCombatTurnRecords(this);
        if (!captured) logMessage(this.t('log.enemyDefeated', { name: enemy.name }));

        this._lastCombatEggs = {};
        this._lastCombatItemDrops = [];
        this._farmingMetricsCaptureItems = !!(this.farmingMetrics && this.farmingMetrics.recording);

        const zone = ZONES[currentZone];
        const isBoss = enemy.isBoss;
        const isEpic = enemy.isEpic;

        const zpLive = this.zoneProgress?.[currentZone];
        if (isBoss) {
            this.stats.bossDefeated++;
            if (zpLive) zpLive.bossesDefeated = (zpLive.bossesDefeated || 0) + 1;
            this.checkSpecialQuests('bossDefeated', { species: enemy.name, zoneId: Number(currentZone) });
        }
        if (isEpic) {
            this.stats.epicDefeated++;
            if (zpLive) zpLive.epicsDefeated = (zpLive.epicsDefeated || 0) + 1;
            this.checkSpecialQuests('epicDefeated', { species: enemy.name, zoneId: Number(currentZone) });
        }

        let pokedollarsEarned = calculateCombatPokedollars(this, currentZone, isBoss, isEpic);
        if (captured && this.getMasteryBonus) {
            const captureGoldBonus = this.getMasteryBonus('capture_gold_mult') || 0;
            if (captureGoldBonus > 0) pokedollarsEarned = Math.floor(pokedollarsEarned * (1 + captureGoldBonus));
        }

        const combatGold = this.addCombatPokedollars(pokedollarsEarned, 'combat');
        if (pokedollarsEarned > 0) {
            this.showUiFloatingText('headerStatMoney', `+${formatNumber(combatGold.creditedToWallet || combatGold.net)}$`, 'ft-money');
            if ((combatGold.injectedToBank || 0) > 0) {
                setTimeout(() => {
                    this.showUiFloatingText('headerStatMoney', `+${formatNumber(combatGold.injectedToBank ?? 0)}$ banque`, 'ft-bank');
                }, 80);
            }
            if (combatGold.withheld > 0) {
                setTimeout(() => {
                    this.showUiFloatingText('headerStatMoney', `-${formatNumber(combatGold.withheld)}$ dette`, 'ft-debt');
                }, 120);
            }
        }

        const balZ2 = BALANCE;
        const expMultiplier = isBoss ? balZ2.COMBAT_XP_MULT_BOSS : (isEpic ? balZ2.COMBAT_XP_MULT_EPIC : balZ2.COMBAT_XP_MULT_NORMAL);
        const baseExpGain = Math.floor(enemy.level * expMultiplier);
        const expGain = Math.floor(baseExpGain * this.getExpMultiplier());

        const anyLeveledUp = this.distributeCombatExp(expGain, { silent: false });
        if (anyLeveledUp) this.checkSpecialQuests('level_up');

        const pensionRate2 = BALANCE.PENSION_EXP_RATIO + ((this.permanentBoosts && this.permanentBoosts.pensionXp) || 0);
        const pensionExpGain = Math.floor(expGain * pensionRate2);
        if (pensionExpGain > 0 && this.pension.length > 0) {
            let pensionLeveledUp = false;
            this.pension.forEach(c => {
                if (c.gainExp!(pensionExpGain) as unknown as boolean) pensionLeveledUp = true;
            });
            if (pensionLeveledUp) {
                this.updatePensionDisplay();
                this.incrementPlayerStats();
            }
        }

        const balTk2 = BALANCE;
        const ticketDropMult2 = this.getMasteryBonus ? (this.getMasteryBonus('combat_ticket_drop_mult') || 0) : 0;
        const bossTicketChance2 = balTk2.COMBAT_TICKET_CHANCE_BOSS * (1 + ticketDropMult2);
        const epicTicketChance2 = balTk2.COMBAT_TICKET_CHANCE_EPIC * (1 + ticketDropMult2);
        if ((isBoss && Math.random() < bossTicketChance2) || (isEpic && Math.random() < epicTicketChance2)) {
            this.combatTickets++;
            logMessage(this.t('log.combatTicketFound'));
        }

        this.rollItemDrop(false, isBoss
            ? { excludeHeldItemsAtRarities: ['legendary'], premiumLootWeightMult: OUTSIDE_TOWER_PREMIUM_LOOT_MULT }
            : { premiumLootWeightMult: OUTSIDE_TOWER_PREMIUM_LOOT_MULT });
        if (isBoss) this.tryDropTimeDust('Boss', 0, { outsideTower: true });
        if (isBoss) this.tryDropTradeStone('Boss');
        if (isBoss) this.tryDropPrestigeStone('Boss');
        if (isBoss) this.tryDropTmEraser('Boss', TM_ERASER_BOSS_DROP_CHANCE * OUTSIDE_TOWER_TM_ERASER_MULT);
        if (isEpic) this.tryDropPrestigeStone('Epic', 0.025);
        if (isBoss) this.tryDropHeldItem('Boss');

        if (isBoss) {
            const rarity = rollBossEggRarity();
            this.addEgg(rarity);
            logMessage(this.t('log.bossLootEgg', { rarity }));

            if (Math.random() < 0.5) {
                this.addEgg(this.determineEggRarity());
                logMessage(this.t('log.bonusEgg'));
            }
        } else if (isEpic) {
            this.addEgg(RARITY.RARE);
            if (Math.random() < 0.3) {
                this.addEgg(RARITY.EPIC);
                logMessage(this.t('log.epicLootEgg'));
            }
        } else {
            const baseEggChance = currentZone * 0.001 + 0.01;
            const classicZoneEggChance = (baseEggChance + this.getEggDropBonus()) * 0.5;
            if (Math.random() < classicZoneEggChance) {
                this.addEgg(this.determineEggRarity());
            }
        }

        if (this.farmingMetrics && this.farmingMetrics.recording) {
            const collecteurBonus = this.getTalentStackBonus('collecteur');
            const mentorBonus = this.getTalentStackBonus('mentor');
            const expMult = this.getExpMultiplier();
            const combatType = enemy.isBoss ? 'boss' : (enemy.isEpic ? 'epic' : (enemy.isRoaming ? 'roamer' : 'classic'));
            const flightCombatDurationMs = this.combatStartTime ? Math.max(0, Date.now() - this.combatStartTime) : 0;
            const flightShinyEnc = !!(enemy && enemy.isShiny);
            this.recordFarmingMetricsCombat({
                pokedollarsTotal: pokedollarsEarned,
                pokedollarsToWallet: (combatGold && combatGold.creditedToWallet) || 0,
                pokedollarsToBank: (combatGold && combatGold.injectedToBank) || 0,
                pokedollarsToDebt: (combatGold && combatGold.withheld) || 0,
                xp: expGain,
                pokedollarsFromCollecteur: collecteurBonus > 0 ? Math.floor(pokedollarsEarned * (collecteurBonus / (1 + collecteurBonus))) : 0,
                xpFromMentor: mentorBonus > 0 && expMult > 0 ? Math.floor(expGain * (mentorBonus / expMult)) : 0,
                eggs: this._lastCombatEggs || {},
                items: this._lastCombatItemDrops || [],
                captures: captured ? 1 : 0,
                combatType,
                combatDurationMs: flightCombatDurationMs,
                combatDurationTurns: getCombatDurationTurns(this),
                shinyEncountered: flightShinyEnc,
                shinyCaptured: flightShinyEnc && captured
            });
        }
        this._lastCombatEggs = {};
        this._lastCombatItemDrops = [] as string[];
        this._farmingMetricsCaptureItems = false;

        const maxTier = Number(zone?.maxTier) || 50;
        const zpZone = this.zoneProgress?.[currentZone];
        if (zpZone) {
            if (!zpZone.pokemonTiers) zpZone.pokemonTiers = {};
            incrementZonePokemonTier(zpZone.pokemonTiers, enemy.name, maxTier);
        }
        if (zone?.regionId === 'paldea') {
            trackAcademyPaldeaZoneWin(this);
        }

        const currentRegionId = this.getCurrentRegionId();
        if (this.isZoneMastered(currentZone)) {
            if (currentZone === 2 && typeof this.checkSpecialQuests === 'function') this.checkSpecialQuests('zone_2_mastered');
            const progression = tryAdvanceRegionalMaxReachedOnMastery(this, currentRegionId, currentZone);
            if (progression.advanced) {
                syncZoneGlobalsToWindow();
            }
            if (progression.shouldAnnounce && progression.nextZoneId != null && ZONES[progression.nextZoneId]) {
                const nextZone = progression.nextZoneId;
                const nextZoneName = this.getLocalizedZoneName(nextZone, (ZONES)[nextZone].name as string);
                logMessage(this.t('log.newZoneUnlocked', { zone: nextZoneName }));
                toast.success(this.t('toast.progressionTitle'), this.t('toast.progressionUnlocked', { zone: nextZoneName }));
                this.checkSpecialQuests('zone_unlocked', { zoneId: Number(nextZone) });
            }
        }
        const nextZone = this.getNextProgressionZoneInRegion(currentZone);

        const nz = nextZone as number;
        const zoneAtNext = (ZONES as Record<number, Record<string, unknown>>)[nz];
        const isZoneUnlocked = (this as Record<string, ((z: number, f?: boolean) => boolean) | undefined>).isZoneUnlocked;
        if (nextZone != null && zoneAtNext && typeof isZoneUnlocked === 'function' && !isZoneUnlocked.call(this, nz) && isZoneUnlocked.call(this, nz, true)) {
            const nextZoneName = this.getLocalizedZoneName(nz, coerceStr(zoneAtNext.name, ''));
            logMessage(this.t('log.zoneUnlocked', { zone: nextZoneName }));
        }

        {
            const now = Date.now();
            const cycleMs = resolveRecordedWinCycleMs(
                now,
                this.lastCombatTime,
                this.combatStartTime
            );
            if (cycleMs != null) {
                if (!this.recentLiveWinDurations) this.recentLiveWinDurations = [];
                recordLiveWinDuration(this.recentLiveWinDurations, cycleMs);
                this.recentCombatDurations = this.recentLiveWinDurations;
                const fightMs = resolveRecordedFightDurationMs(now, this.combatStartTime);
                if (fightMs != null) {
                    if (!this.recentLiveFightDurations) this.recentLiveFightDurations = [];
                    recordLiveFightDuration(this.recentLiveFightDurations, fightMs);
                }
            }
        }

        if (!this.isOfflineSimulating) {
            applyLegendaryWildCooldownAfterEncounterLogic(this, enemy);
        }

        this.combatState = 'waiting';
        this.lastCombatTime = Date.now();
        this.currentEnemy = null;
        this.faintedThisCombat = new Set();
        this.faintedUidsThisCombat = new Set();
        restoreCombatPreferredActiveIfNeeded(this);
        this._applyActiveFirstAfterCombatIfNeeded();

        syncMegaTimerWithCombatState(this);
        syncDynamaxTimerWithCombatState(this);

        this.playerTeam.forEach(c => {
            if (c.mainAccountCurrentHp > 0) {
                c.currentHp = Math.min(c.maxHp || c.mainAccountCurrentHp, c.mainAccountCurrentHp);
            }
        });

        this.updateZoneSelector();
        const rollRoaming = (this as unknown as Record<string, (() => void) | undefined>).rollRoamingEncounter;
        if (typeof rollRoaming === 'function') rollRoaming.call(this);
        updateZoneInfo(this);

        if (captured) {
            this.updateStorageDisplay();
        }
        refreshTeamAfterCombat(this);
        this.updateCombatDisplay();
        this.updateItemsDisplay();
        this.updateEggsDisplay();

        if (captured) {
            this.updatePokedexDisplay();
            const updateAchievements = (this as unknown as Record<string, (() => void) | undefined>).updateAchievementsDisplay;
            if (typeof updateAchievements === 'function') updateAchievements.call(this);
        }
        if (typeof this.checkAndShowCollectionBonusModal === 'function') this.checkAndShowCollectionBonusModal();
    };

    GameClass.prototype.getFirstAliveCreature = function (this: ThisGame): CreatureData | null {
        return this.playerTeam.find(creature => creature.isAlive!()) || null;
    };

    GameClass.prototype.getOfflinePreferredCreature = function (this: ThisGame): CreatureData | null {
        if (!Array.isArray(this.playerTeam) || this.playerTeam.length === 0) return null;

        const active = arrayAt(this.playerTeam, this.activeCreatureIndex);
        if (!this.autoSelectEnabled && active?.isAlive?.()) {
            return active;
        }

        const fallback = this.getFirstAliveCreature();
        if (!fallback) return null;

        const fallbackIndex = this.playerTeam.indexOf(fallback);
        if (fallbackIndex >= 0) this.activeCreatureIndex = fallbackIndex;
        return fallback;
    };

    /**
     * Sélectionne l'index du meilleur Pokémon de l'équipe face à l'ennemi donné,
     * pour la simulation offline. Considère tous les Pokémon vivants disposant
     * d'attaques utilisables (PP > 0). Score = efficacité de type * 1000
     * + total attaque/défense/vitesse (faible poids comme tie-breaker).
     * Retourne -1 si aucun candidat valide.
     *
     * @param {Object} enemy
     * @returns {number}
     */
    GameClass.prototype._pickOfflineBestMatchup = function (this: ThisGame, enemy: CreatureData): number {
        if (!enemy || !Array.isArray(this.playerTeam) || !this.playerTeam.length) return -1;
        let bestIdx = -1;
        let bestScore = -Infinity;
        for (let i = 0; i < this.playerTeam.length; i++) {
            const c = this.playerTeam[i];
            if (!c || !c.isAlive!()) continue;
            if (typeof this.creatureHasUsableMoves === 'function' && !this.creatureHasUsableMoves(c, 1)) continue;
            const eff = this.getCreatureVsEnemyEffectiveness(c, enemy);
            const stats = (c.attack || 0) + (c.defense || 0) + (c.speed || 0);
            const score = eff * 1000 + stats * 0.001;
            if (score > bestScore) {
                bestScore = score;
                bestIdx = i;
            }
        }
        return bestIdx;
    };

    GameClass.prototype.getExpMultiplier = function (this: ThisGame): number {
        let multiplier = 1 + ((this.upgrades && this.upgrades.expBoost ? this.upgrades.expBoost.level : 0) * 0.1);

        multiplier += this.getActiveBoostMultiplier('xp');

        if (this.permanentBoosts && this.permanentBoosts.xp) {
            multiplier += this.permanentBoosts.xp;
        }

        multiplier += this.getAccountTalentBonus('exp_mult');

        const synergies = this.getActiveSynergies();
        if (synergies.exp_mult > 1) {
            multiplier += (synergies.exp_mult - 1);
        }
        const collXp = (this.getCollectionBonuses ? this.getCollectionBonuses() : {}).xp_mult || 0;
        multiplier += collXp;

        multiplier += this.getTalentStackBonus('mentor');

        return multiplier;
    };

    GameClass.prototype.distributeCombatExp = function (this: ThisGame, expGain: number, opts?: { silent?: boolean }): boolean {
        opts = opts || {};
        const silent = !!opts.silent;
        const team = this.playerTeam || [];
        if (!team.length || expGain <= 0) return false;
        const teamTalents = team.filter(c => c.passiveTalent).map(c => c.passiveTalent);
        const hasExpShare = (this.items?.['exp_share'] ?? 0) > 0;
        const active = this.currentPlayerCreature;
        const activeInTeam = active && team.indexOf(active) !== -1;

        const onLevelUp = (c: CreatureData) => {
            if (silent) return;
            if (c.level > this.stats.highestLevelReached) {
                this.stats.highestLevelReached = c.level;
                this.checkAchievements('highestLevelReached');
            }
            if (c.isStarter && typeof this.checkSpecialQuests === 'function') {
                this.checkSpecialQuests('starter_level_up');
            }
            this.updateTeamPowerStat();
        };

        let anyLeveledUp = false;
        const grant = (c: CreatureData, amount: number) => {
            if (amount <= 0) return;
            if ((c.gainExp as (amount: number, talents?: (string | null)[]) => boolean)?.(amount, teamTalents)) {
                anyLeveledUp = true;
                onLevelUp(c);
            }
        };

        if (hasExpShare && activeInTeam) {
            grant(active, expGain);
            const sharePool = Math.floor(expGain * 0.5);
            const shareRecipients = team.filter(c => {
                if (c === active) return false;
                const isAtMaxLevel = c.isAtMaxLevel;
                if (typeof isAtMaxLevel === 'function' && isAtMaxLevel.call(c)) return false;
                return true;
            });
            if (sharePool > 0 && shareRecipients.length > 0) {
                const n = shareRecipients.length;
                const baseShare = Math.floor(sharePool / n);
                const remainder = sharePool - baseShare * n;
                shareRecipients.forEach((c, i) => {
                    grant(c, baseShare + (i < remainder ? 1 : 0));
                });
            }
        } else if (activeInTeam) {
            grant(active, expGain);
        } else {
            team.forEach(c => grant(c, expGain));
        }

        return anyLeveledUp;
    };

    GameClass.prototype.getTeamAverageRarity = function (this: ThisGame): number {
        if (this.playerTeam.length === 0) return 0;
        const total = this.playerTeam.reduce((sum, c) => sum + this.getRarityValue(c.rarity), 0);
        return total / this.playerTeam.length;
    };

    GameClass.prototype.getRarityValue = function (this: ThisGame, rarity: string): number {
        const values: Record<string, number> = {
            [RARITY.COMMON]: 1,
            [RARITY.RARE]: 2,
            [RARITY.EPIC]: 3,
            [RARITY.LEGENDARY]: 4
        };
        return values[rarity] || 1;
    };

    GameClass.prototype.getStatusProcBonus = function (this: ThisGame): number {
        let totalBonus = 0;

        const catalyseurBonus = this.getTalentStackBonus('catalyseur');
        totalBonus += catalyseurBonus;

        const catalyseurSupremeBonus = this.getTalentStackBonus('catalyseur_supreme');
        totalBonus += catalyseurSupremeBonus;

        if (this.getMasteryBonus) {
            totalBonus += this.getMasteryBonus('status_proc_mult') || 0;
        }

        if (this.getCollectionBonuses) {
            totalBonus += (this.getCollectionBonuses().status_proc_mult || 0);
        }

        return totalBonus;
    };

    GameClass.prototype.getStaminaRegenTime = function (this: ThisGame): number {
        const baseTime = 10000;
        const level = (this.upgrades && this.upgrades.staminaRegen && typeof this.upgrades.staminaRegen.level === 'number')
            ? this.upgrades.staminaRegen.level
            : 0;
        const reduction = level * 200;
        return Math.max(1000, baseTime - reduction);
    };

    GameClass.prototype.getTypeEffectiveness = function (this: ThisGame, attackerType: string, defenderType: string, defenderSecondaryType?: string | null): number {
        if (defenderSecondaryType === undefined) defenderSecondaryType = null;
        return getTypeMultiplier(attackerType, defenderType, defenderSecondaryType);
    };

    GameClass.prototype.getCreatureVsEnemyEffectiveness = function (this: ThisGame, creature: CreatureData, enemy: CreatureData): number {
        if (!creature || !enemy) return 1;
        const defenderSec = enemy.secondaryType || null;
        let eff = this.getTypeEffectiveness(creature.type, enemy.type, defenderSec);
        if (creature.secondaryType) {
            const eff2 = this.getTypeEffectiveness(creature.secondaryType, enemy.type, defenderSec);
            eff = Math.max(eff, eff2);
        }
        return eff;
    };

    GameClass.prototype.getEffectivenessText = function (this: ThisGame, effectiveness: number): { text: string; color: string; class: string } {
        if (effectiveness === 0) {
            return { text: this.t('combatUi.noEffect'), color: "#94a3b8", class: "no-effect" };
        }
        if (effectiveness > 1) {
            return { text: this.t('combatUi.superEffective'), color: "#22c55e", class: "super-effective" };
        } else if (effectiveness < 1) {
            return { text: this.t('combatUi.notEffective'), color: "#ef4444", class: "not-effective" };
        } else {
            return { text: this.t('combatUi.normalEffective'), color: "#666", class: "normal-effective" };
        }
    };

    GameClass.prototype.findBestCreatureForEnemy = function (this: ThisGame): CreatureData | null {
        if (!this.currentEnemy || this.playerTeam.length === 0) return null;

        let bestIndex = -1;
        let bestEffectiveness = 0;
        let bestStats = 0;

        for (let i = 0; i < this.playerTeam.length; i++) {
            const creature = arrayAt(this.playerTeam, i);
            if (!creature?.isAlive?.()) continue;
            if (typeof this.creatureHasUsableMoves === 'function' && !this.creatureHasUsableMoves(creature, 3)) continue;

            const effectiveness = this.getCreatureVsEnemyEffectiveness(creature, this.currentEnemy);
            const statsSum = creature.attack + creature.defense + creature.speed;

            if (effectiveness > bestEffectiveness ||
                (effectiveness === bestEffectiveness && statsSum > bestStats)) {
                bestIndex = i;
                bestEffectiveness = effectiveness;
                bestStats = statsSum;
            }
        }

        return bestIndex >= 0 ? (arrayAt(this.playerTeam, bestIndex) ?? null) : null;
    };

    GameClass.prototype.selectBestCreature = function (this: ThisGame): void {
        const bestCreature = this.findBestCreatureForEnemy();

        if (!bestCreature) {
            logMessage(this.t('log.noAliveCreature'));
            return;
        }

        if (bestCreature === this.currentPlayerCreature) {
            logMessage(this.t('log.activeAlreadyOptimal'));
            return;
        }

        const bestIndex = this.playerTeam.indexOf(bestCreature);
        const effectiveness = this.getCreatureVsEnemyEffectiveness(bestCreature, this.currentEnemy!);

        this.setActiveCreature(bestIndex);

        if (effectiveness > 1) logMessage(this.t('log.autoSelectedAdv', { name: bestCreature.name }));
        else if (effectiveness < 1) logMessage(this.t('log.autoSelectedBest', { name: bestCreature.name }));
        else logMessage(this.t('log.autoSelected', { name: bestCreature.name }));
    };

    /**
     * Vérifie si un nouveau switch auto est autorisé (cooldown anti ping-pong).
     * @param {number} [now]
     * @returns {boolean}
     */
    GameClass.prototype._canAutoSwitchNow = function (this: ThisGame, now?: number): boolean {
        const t = (typeof now === 'number') ? now : Date.now();
        const cd = getAutoConfig().COOLDOWN_MS;
        const lastSwitchTime = this._lastAutoSwitchTime;
        if (typeof lastSwitchTime === 'number' && (t - lastSwitchTime) < cd) return false;
        return true;
    };

    /** Marque l'instant du dernier switch auto pour le cooldown partagé. */
    GameClass.prototype._markAutoSwitch = function (this: ThisGame, now?: number): void {
        this._lastAutoSwitchTime = (typeof now === 'number') ? now : Date.now();
    };

    /**
     * Sélectionne le meilleur Pokémon de l'équipe à envoyer en switch auto,
     * en filtrant par PV minimum et PP minimum. Si aucun candidat ne respecte
     * le seuil PV (ex. tout le monde est bas), on autorise un fallback de survie
     * sur le pool complet (le moins risqué de ce qui reste).
     *
     * @param {{minHpRatio?:number, minPp?:number, excludeIndex?:number}} [opts]
     * @returns {number} index dans playerTeam, ou -1 si aucun candidat.
     */
    GameClass.prototype.pickBestSwitchTarget = function (this: ThisGame, opts?: Record<string, unknown>): number {
        opts = opts || {};
        const minHpRatio = (typeof opts.minHpRatio === 'number') ? opts.minHpRatio : 0;
        const minPp = (typeof opts.minPp === 'number') ? opts.minPp : 3;
        const excludeIndex = (typeof opts.excludeIndex === 'number') ? opts.excludeIndex : this.activeCreatureIndex;
        const enemy = this.currentEnemy || null;

        if (!Array.isArray(this.playerTeam) || this.playerTeam.length === 0) return -1;

        const candidates = [];
        for (let i = 0; i < this.playerTeam.length; i++) {
            if (i === excludeIndex) continue;
            const c = this.playerTeam[i];
            if (!c || !c.isAlive!()) continue;
            if (typeof this.creatureHasUsableMoves === 'function' && !this.creatureHasUsableMoves(c, minPp)) continue;
            candidates.push({ idx: i, c });
        }
        if (!candidates.length) return -1;

        const safe = candidates.filter(({ c }) => _hpRatio(c) >= minHpRatio);
        const pool = safe.length ? safe : candidates;

        const score = ({ c }: { c: CreatureData }) => {
            const eff = enemy ? this.getCreatureVsEnemyEffectiveness(c, enemy) : 1;
            const hp = _hpRatio(c);
            const stats = (c.attack || 0) + (c.defense || 0) + (c.speed || 0);
            return eff * 1000 + hp * 100 + stats * 0.001;
        };
        pool.sort((a, b) => score(b) - score(a));
        const top = pool[0];
        return top ? top.idx : -1;
    };

    /**
     * Tente un switch auto unifié. Centralise cooldown, seuils PV et logs.
     * `reason` peut être : 'advantage' | 'disadvantage'. (Stamina garde sa
     * logique propre dans autoCheckStamina, car le critère y est l'absence
     * de PP, pas un meilleur matchup.)
     *
     * @param {'advantage'|'disadvantage'} reason
     * @returns {boolean} true si un switch a été effectué.
     */
    GameClass.prototype.attemptAutoSwitch = function (this: ThisGame, reason?: string): boolean {
        if (isFarmThreatCombatActive(this as unknown as GameRuntime)) return false;
        if (!this.autoSelectEnabled || !this.currentEnemy) return false;
        if (!Array.isArray(this.playerTeam) || this.playerTeam.length === 0) return false;

        if ((reason === 'advantage' || reason === 'disadvantage')
            && !usesLegacyTypeAutoSwitch(this as unknown as GameRuntime)) {
            return false;
        }

        const cfg = getAutoConfig();
        const active = arrayAt(this.playerTeam, this.activeCreatureIndex);
        if (isPlayerUltReadyForAuto(this as unknown as GameRuntime, active)) return false;

        let minHp;
        let validate;

        if (reason === 'advantage') {
            if (!this.autoSwitchAdvantage) return false;
            minHp = cfg.MIN_HP_PCT_ADVANTAGE;
            validate = (cand: CreatureData) => {
                const eff = this.getCreatureVsEnemyEffectiveness(cand, this.currentEnemy!);
                return eff > 1;
            };
        } else if (reason === 'disadvantage') {
            if (!this.autoSwitchDisadvantage) return false;
            if (!active || !active.isAlive!()) return false;
            minHp = cfg.MIN_HP_PCT_DISADVANTAGE;
            const currentEff = this.getCreatureVsEnemyEffectiveness(active, this.currentEnemy);
            validate = (cand: CreatureData) => {
                const candEff = this.getCreatureVsEnemyEffectiveness(cand, this.currentEnemy!);
                return (candEff - currentEff) >= cfg.MIN_EFF_GAIN_DISADVANTAGE;
            };
        } else {
            return false;
        }

        const now = Date.now();
        if (!this._canAutoSwitchNow(now)) return false;

        const targetIdx = this.pickBestSwitchTarget({ minHpRatio: minHp, minPp: 3 });
        if (targetIdx === -1 || targetIdx === this.activeCreatureIndex) return false;

        const cand = arrayAt(this.playerTeam, targetIdx);
        if (!cand || !validate(cand)) return false;

        this._markAutoSwitch(now);
        this.setActiveCreature(targetIdx);
        const logKey = (reason === 'advantage')
            ? 'log.sentWithTypeAdvantage'
            : 'log.autoSwitchDisadvantageEnemy';
        logMessage(this.t(logKey, { name: cand.name }));
        return true;
    };

    GameClass.prototype.autoCheckDisadvantage = function (this: ThisGame): void {
        this.attemptAutoSwitch('disadvantage');
    };

    const tryAdvancedSwitchOnGame = function (
        game: ThisGame,
        opts?: { requireBreakpoint?: boolean },
    ): boolean {
        if (isFarmThreatCombatActive(game as unknown as GameRuntime)) return false;
        if (!game.autoSwitchAdvanced) return false;
        if (!game.unlockedFeatures?.autoFightAdvanced) return false;
        if (!game.autoSelectEnabled || !game.currentEnemy || !game.currentPlayerCreature) return false;
        if (isPlayerUltReadyForAuto(game as unknown as GameRuntime, game.currentPlayerCreature)) return false;

        const requireBreakpoint = opts?.requireBreakpoint === true;

        if (requireBreakpoint && !game._advancedEntrySwitchDone) {
            game._advancedEntrySwitchDone = true;
            if (shouldBlockAdvancedEntrySwitch(game as unknown as GameRuntime)) return false;
        }

        const atCombatEntry = game.combatState === 'starting';
        if (requireBreakpoint && !atCombatEntry && !canAutoSwitchAtAtbBreakpoint(game as unknown as GameRuntime)) {
            return false;
        }

        const active = arrayAt(game.playerTeam, game.activeCreatureIndex);
        if (!active?.isAlive?.()) return false;

        const now = Date.now();

        const options = game.autoFightAdvancedOptions ?? defaultAutoFightAdvancedOptions();
        const enemy = game.currentEnemy;
        const activeCantDamage = enemy
            ? !canActiveDealDamage(game as unknown as GameRuntime, active, enemy)
            : false;
        const useForcedPool = !requireBreakpoint || activeCantDamage;

        const best = useForcedPool
            ? pickBestAdvancedForcedSwitchTarget(game as unknown as GameRuntime, {
                options,
            })
            : pickBestAdvancedSwitchTarget(game as unknown as GameRuntime, {
                posture: game.autoFightSwitchPosture,
                options,
            });
        if (!best || best.index === game.activeCreatureIndex) return false;

        const shouldSwitch = useForcedPool
            ? shouldForceAdvancedSwitchOnNoDamage(game as unknown as GameRuntime, active, best, options)
            : shouldAdvancedSwitch(game as unknown as GameRuntime, active, best, options);
        if (!shouldSwitch) return false;

        game._lastPlayerAdvancedSwitchTime = now;
        game.setActiveCreature(best.index);
        if (game.currentPlayerCreature) {
            game.currentPlayerCreature.actionGauge = 0;
        }
        logMessage(game.t('log.autoSwitchAdvanced', { name: best.creature.name }));
        return true;
    };

    /**
     * Switch désavantage immédiat après un coup à 0 dégât par immunité de type (type de la capacité).
     * Complète autoCheckDisadvantage (type du Pokémon) quand le joueur attaque avec un move immunisé.
     */
    GameClass.prototype.autoCheckDisadvantageAfterImmuneMove = function (this: ThisGame, moveType: string): boolean {
        if (this.unlockedFeatures?.autoFightAdvanced && this.autoSwitchAdvanced) {
            if (!moveType || !this.currentEnemy) return false;
            if (!isTypeImmune(moveType, this.currentEnemy.type, this.currentEnemy.secondaryType ?? null)) {
                return false;
            }
            return tryAdvancedSwitchOnGame(this);
        }
        if (!usesLegacyTypeAutoSwitch(this as unknown as GameRuntime)) return false;
        if (!this.autoSelectEnabled || !this.autoSwitchDisadvantage || !moveType) return false;
        if (!this.currentEnemy || !Array.isArray(this.playerTeam) || this.playerTeam.length === 0) return false;
        if (isPlayerUltReadyForAuto(this as unknown as GameRuntime, this.currentPlayerCreature)) return false;

        const enemy = this.currentEnemy;
        if (!isTypeImmune(moveType, enemy.type, enemy.secondaryType ?? null)) return false;

        const active = arrayAt(this.playerTeam, this.activeCreatureIndex);
        if (!active || !active.isAlive!()) return false;

        const cfg = getAutoConfig();
        const moveEff = getTypeMultiplier(moveType, enemy.type, enemy.secondaryType ?? null);
        const creatureEff = this.getCreatureVsEnemyEffectiveness(active, enemy);
        const currentEff = Math.min(creatureEff, moveEff);

        const now = Date.now();
        if (!this._canAutoSwitchNow(now)) return false;

        const targetIdx = this.pickBestSwitchTarget({
            minHpRatio: cfg.MIN_HP_PCT_DISADVANTAGE,
            minPp: 3,
        });
        if (targetIdx === -1 || targetIdx === this.activeCreatureIndex) return false;

        const cand = arrayAt(this.playerTeam, targetIdx);
        if (!cand || !cand.isAlive!()) return false;

        const candEff = this.getCreatureVsEnemyEffectiveness(cand, enemy);
        if ((candEff - currentEff) < cfg.MIN_EFF_GAIN_DISADVANTAGE) return false;

        this._markAutoSwitch(now);
        this.setActiveCreature(targetIdx);
        logMessage(this.t('log.autoSwitchDisadvantageEnemy', { name: cand.name }));
        return true;
    };

    GameClass.prototype.creatureHasUsableMoves = function (this: ThisGame, creature: CreatureData, minPp?: number): boolean {
        if (minPp === undefined) minPp = 1;
        if (!creature || creature.isEnemy) return true;
        if (!creature.currentMoves || creature.currentMoves.length === 0) return false;
        if (!creature.movePp) return true;
        return creature.currentMoves.some(name => {
            const info = creature.movePp[name];
            return info && info.current >= minPp;
        });
    };

    GameClass.prototype.autoCheckStamina = function (this: ThisGame, minPpPreferred?: number): boolean {
        if (isFarmThreatCombatActive(this as unknown as GameRuntime)) return false;
        if (minPpPreferred === undefined) minPpPreferred = 3;
        if (!this.autoSwitchStamina) return false;
        if (!this.autoSelectEnabled || !this.currentPlayerCreature) return false;
        if (isPlayerUltReadyForAuto(this as unknown as GameRuntime, this.currentPlayerCreature)) return false;

        const hasAnyPp = this.creatureHasUsableMoves(this.currentPlayerCreature, 1);
        if (this.creatureHasUsableMoves(this.currentPlayerCreature, minPpPreferred)) return false;

        if (this.currentPlayerCreature.passiveTalent === 'robustesse') return false;

        const now = Date.now();
        if (!this._canAutoSwitchNow(now)) return false;

        const cfg = getAutoConfig();
        const replacementMinPp = hasAnyPp ? minPpPreferred : 1;

        if (this.unlockedFeatures?.autoFightAdvanced && this.autoSwitchAdvanced) {
            const best = pickBestAdvancedSwitchTarget(this as unknown as GameRuntime, {
                posture: 0,
                minPp: replacementMinPp,
                options: this.autoFightAdvancedOptions,
            });
            if (!best || best.index === this.activeCreatureIndex) return false;
            const newCreature = arrayAt(this.playerTeam, best.index);
            if (!newCreature) return false;
            this._markAutoSwitch(now);
            this.setActiveCreature(best.index);
            logMessage(this.t('log.autoSwitchStaminaLow', { name: newCreature.name }));
            return true;
        }

        const targetIdx = this.pickBestSwitchTarget({
            minHpRatio: cfg.MIN_HP_PCT_STAMINA,
            minPp: replacementMinPp
        });
        if (targetIdx === -1) return false;

        const newCreature = arrayAt(this.playerTeam, targetIdx);
        if (!newCreature) return false;
        this._markAutoSwitch(now);
        this.setActiveCreature(targetIdx);
        logMessage(this.t('log.autoSwitchStaminaLow', { name: newCreature.name }));
        return true;
    };

    GameClass.prototype.markAutoFightAdvancedCustom = function (this: ThisGame): void {
        if (this._applyingAutoFightPreset) return;
        this.autoFightAdvancedPreset = 'custom';
        if (typeof this.syncAutoAdvancedPresetUI === 'function') {
            this.syncAutoAdvancedPresetUI();
        }
    };

    GameClass.prototype.setAutoFightAdvancedPreset = function (this: ThisGame, preset: string): void {
        const allowed = ['safe', 'balanced', 'aggressive', 'custom'] as const;
        if (!allowed.includes(preset as typeof allowed[number])) return;
        this._applyingAutoFightPreset = true;
        try {
            applyAutoFightAdvancedPreset(this as unknown as GameRuntime, preset as typeof allowed[number]);
            this.setAutoFightSwitchPosture(this.autoFightSwitchPosture ?? 50);
            this.setAutoFightMovePreference(this.autoFightMovePreference ?? 0);
            const gainSliderPct = Math.round((this.autoFightAdvancedOptions?.minScoreGainPct ?? 0.20) * 100);
            this.setAutoFightSwitchGainPct(gainSliderPct);
            const opts = this.autoFightAdvancedOptions || defaultAutoFightAdvancedOptions();
            const neverWeak = getInput('autoAdvancedNeverWeakCheck');
            const avoidDouble = getInput('autoAdvancedAvoidDoubleWeakCheck');
            const skipFinish = getInput('autoAdvancedSkipFinishCheck');
            const respectPreferred = getInput('autoAdvancedRespectPreferredCheck');
            const preferXp = getInput('autoAdvancedPreferXpCheck');
            if (neverWeak) neverWeak.checked = opts.neverSendWeakMatchup !== false;
            if (avoidDouble) avoidDouble.checked = opts.avoidDoubleWeakness !== false;
            if (skipFinish) skipFinish.checked = opts.skipIfCanFinish !== false;
            if (respectPreferred) respectPreferred.checked = opts.respectPreferredActive !== false;
            if (preferXp) preferXp.checked = opts.preferXpEligible === true;
        } finally {
            this._applyingAutoFightPreset = false;
        }
        this.syncAutoAdvancedPresetUI();
    };

    GameClass.prototype.syncAutoAdvancedPresetUI = function (this: ThisGame): void {
        const preset = this.autoFightAdvancedPreset ?? detectAutoFightAdvancedPreset(this as unknown as GameRuntime);
        this.autoFightAdvancedPreset = preset;
        const ids = ['safe', 'balanced', 'aggressive', 'custom'] as const;
        for (const id of ids) {
            const btn = document.getElementById(`autoAdvancedPreset${id.charAt(0).toUpperCase()}${id.slice(1)}`);
            if (btn) btn.classList.toggle('active', preset === id);
        }
        const customPanel = document.getElementById('autoAdvancedCustomPanel');
        if (customPanel) customPanel.hidden = preset !== 'custom';
    };

    GameClass.prototype.autoCheckAdvanced = function (this: ThisGame): boolean {
        return tryAdvancedSwitchOnGame(this, { requireBreakpoint: true });
    };

    /** Switch avancé sans breakpoint ATB — immunité, actif à 0 dégât, ou garde pré-attaque. */
    GameClass.prototype.autoCheckAdvancedForced = function (
        this: ThisGame,
        opts?: { requireBreakpoint?: boolean },
    ): boolean {
        return tryAdvancedSwitchOnGame(this, opts);
    };

    GameClass.prototype.setAutoFightSwitchPosture = function (this: ThisGame, value: number): void {
        const v = Math.max(0, Math.min(100, Math.round(Number(value) || 0)));
        this.autoFightSwitchPosture = v;
        const slider = getInput('autoFightPostureSlider');
        if (slider) slider.value = String(v);
        const valueEl = document.getElementById('autoFightPostureValue');
        if (valueEl) {
            let label = this.t('autoPanel.postureBalanced');
            if (v <= 33) label = this.t('autoPanel.postureDefensive');
            else if (v >= 67) label = this.t('autoPanel.postureOffensive');
            valueEl.textContent = label;
        }
    };

    GameClass.prototype.setAutoFightMovePreference = function (this: ThisGame, value: number): void {
        const v = Math.max(0, Math.min(100, Math.round(Number(value) || 0)));
        this.autoFightMovePreference = v;
        const slider = getInput('autoFightMovePrefSlider');
        if (slider) slider.value = String(v);
        const valueEl = document.getElementById('autoFightMovePrefValue');
        if (valueEl) {
            const label = v >= 50
                ? this.t('autoPanel.movePrefStatus')
                : this.t('autoPanel.movePrefDamage');
            valueEl.textContent = label;
        }
    };

    GameClass.prototype.setAutoFightSwitchGainPct = function (this: ThisGame, value: number): void {
        const v = Math.max(10, Math.min(40, Math.round(Number(value) || 20)));
        if (!this.autoFightAdvancedOptions || typeof this.autoFightAdvancedOptions !== 'object') {
            this.autoFightAdvancedOptions = defaultAutoFightAdvancedOptions();
        }
        this.autoFightAdvancedOptions.minScoreGainPct = v / 100;
        const slider = getInput('autoFightSwitchGainSlider');
        if (slider) slider.value = String(v);
        const valueEl = document.getElementById('autoFightSwitchGainValue');
        if (valueEl) valueEl.textContent = `${v}%`;
    };

    GameClass.prototype.syncAutoExcludedSwitchSelects = function (this: ThisGame): void {
        const sel1 = document.getElementById('autoExcludeSlot1Select') as HTMLSelectElement | null;
        const sel2 = document.getElementById('autoExcludeSlot2Select') as HTMLSelectElement | null;
        if (!sel1 || !sel2) return;

        const excluded = this.autoFightAdvancedOptions?.excludedSwitchIndices ?? [];
        const val1 = typeof excluded[0] === 'number' ? excluded[0] : -1;
        const val2 = typeof excluded[1] === 'number' ? excluded[1] : -1;

        const fillSelect = (select: HTMLSelectElement, selected: number): void => {
            select.innerHTML = '';
            const empty = document.createElement('option');
            empty.value = '-1';
            empty.textContent = '—';
            select.appendChild(empty);
            const team = this.playerTeam || [];
            for (let i = 0; i < team.length; i++) {
                const creature = team[i];
                const opt = document.createElement('option');
                opt.value = String(i);
                opt.textContent = creature?.name ? `${i + 1}. ${creature.name}` : String(i + 1);
                select.appendChild(opt);
            }
            select.value = selected >= 0 ? String(selected) : '-1';
        };

        fillSelect(sel1, val1);
        fillSelect(sel2, val2);
    };

    GameClass.prototype.setAutoFightExcludedSlot = function (this: ThisGame, selectSlot: number, rawIndex: number): void {
        if (!this.autoFightAdvancedOptions || typeof this.autoFightAdvancedOptions !== 'object') {
            this.autoFightAdvancedOptions = defaultAutoFightAdvancedOptions();
        }
        const slot = selectSlot === 1 ? 1 : 0;
        const idx = Number(rawIndex);
        const valid = Number.isFinite(idx) && idx >= 0 ? idx : null;
        const list = this.autoFightAdvancedOptions.excludedSwitchIndices || [];
        const pair: Array<number | null> = [
            typeof list[0] === 'number' ? list[0] : null,
            typeof list[1] === 'number' ? list[1] : null,
        ];
        pair[slot] = valid;
        if (valid !== null) {
            const other = slot === 0 ? 1 : 0;
            if (pair[other] === valid) pair[other] = null;
        }
        this.autoFightAdvancedOptions.excludedSwitchIndices = pair
            .filter((i): i is number => typeof i === 'number' && i >= 0)
            .slice(0, 2);
        this.markAutoFightAdvancedCustom();
        this.syncAutoExcludedSwitchSelects();
    };

    GameClass.prototype.syncAutoAdvancedSettingsUI = function (this: ThisGame): void {
        const unlocked = !!(this.unlockedFeatures && this.unlockedFeatures.autoFightAdvanced);
        const classicBlock = document.getElementById('autoClassicOptions');
        if (classicBlock) classicBlock.hidden = unlocked;

        const classicTooltipRows = document.querySelectorAll('.auto-classic-only');
        classicTooltipRows.forEach((el) => {
            (el as HTMLElement).hidden = unlocked;
        });
        const advancedTooltipRow = document.getElementById('autoTooltipAdvancedRow');
        if (advancedTooltipRow) advancedTooltipRow.hidden = !unlocked;

        const featuresLabel = document.getElementById('autoSettingsFeaturesLabel');
        if (featuresLabel) {
            featuresLabel.textContent = unlocked
                ? this.t('autoPanel.featuresAdvanced')
                : this.t('autoPanel.features');
        }

        const section = document.getElementById('autoAdvancedSection');
        const commonBlock = document.getElementById('autoCommonOptions');
        const modal = document.getElementById('autoSettingsModal');
        const lockedHint = document.getElementById('autoAdvancedLockedLabel');
        const sectionTitle = document.getElementById('autoAdvancedSectionTitleLabel');
        const unlockedBadge = document.getElementById('autoAdvancedUnlockedBadge');
        if (modal) modal.classList.toggle('auto-advanced-unlocked', unlocked);
        if (commonBlock && section) {
            commonBlock.classList.toggle('auto-common-in-advanced', unlocked);
            if (unlocked) {
                section.appendChild(commonBlock);
            } else {
                section.parentElement?.insertBefore(commonBlock, section);
            }
        }
        if (section) section.classList.toggle('auto-locked', !unlocked);
        if (sectionTitle) sectionTitle.textContent = this.t('autoPanel.advancedSectionTitle');
        if (unlockedBadge) {
            unlockedBadge.textContent = this.t('autoPanel.advancedUnlocked');
            unlockedBadge.hidden = true;
        }
        if (lockedHint) {
            lockedHint.textContent = this.t('autoPanel.advancedLocked');
            lockedHint.hidden = unlocked;
        }

        const advCheck = getInput('autoSwitchAdvancedCheck');
        if (advCheck) advCheck.checked = !!this.autoSwitchAdvanced;

        this.setAutoFightSwitchPosture(this.autoFightSwitchPosture ?? 50);
        this.setAutoFightMovePreference(this.autoFightMovePreference ?? 0);
        const gainSliderPct = Math.round((this.autoFightAdvancedOptions?.minScoreGainPct ?? 0.20) * 100);
        this.setAutoFightSwitchGainPct(gainSliderPct);

        const optimalCheck = getInput('autoOptimalMovesCheck');
        if (optimalCheck && unlocked) optimalCheck.checked = true;

        const opts = this.autoFightAdvancedOptions || defaultAutoFightAdvancedOptions();
        const neverWeak = getInput('autoAdvancedNeverWeakCheck');
        const avoidDouble = getInput('autoAdvancedAvoidDoubleWeakCheck');
        const skipFinish = getInput('autoAdvancedSkipFinishCheck');
        const respectPreferred = getInput('autoAdvancedRespectPreferredCheck');
        const preferXp = getInput('autoAdvancedPreferXpCheck');
        if (neverWeak) neverWeak.checked = opts.neverSendWeakMatchup !== false;
        if (avoidDouble) avoidDouble.checked = opts.avoidDoubleWeakness !== false;
        if (skipFinish) skipFinish.checked = opts.skipIfCanFinish !== false;
        if (respectPreferred) respectPreferred.checked = opts.respectPreferredActive !== false;
        if (preferXp) preferXp.checked = opts.preferXpEligible === true;

        if (typeof this.syncAutoExcludedSwitchSelects === 'function') {
            this.syncAutoExcludedSwitchSelects();
        }

        if (typeof this.syncAutoAdvancedPresetUI === 'function') {
            this.syncAutoAdvancedPresetUI();
        }

        if (this._scrollAutoAdvancedOnOpen && unlocked && section) {
            const modal = document.getElementById('autoSettingsModal');
            const modalOpen = !!(modal && modal.classList.contains('show'));
            if (modalOpen) {
                this._scrollAutoAdvancedOnOpen = false;
                const scrollTarget = section;
                if (typeof requestAnimationFrame === 'function') {
                    requestAnimationFrame(() => {
                        scrollTarget.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
                    });
                } else {
                    scrollTarget.scrollIntoView({ block: 'nearest' });
                }
            }
        }
    };

    GameClass.prototype.setAutoFightAdvancedOption = function (this: ThisGame, key: string, value: boolean | number): void {
        if (!this.autoFightAdvancedOptions || typeof this.autoFightAdvancedOptions !== 'object') {
            this.autoFightAdvancedOptions = defaultAutoFightAdvancedOptions();
        }
        const opts = this.autoFightAdvancedOptions as unknown as Record<string, boolean | number>;
        if (key in opts) {
            opts[key] = value;
        }
        this.markAutoFightAdvancedCustom();
    };

    GameClass.prototype.openAutoSettings = function (this: ThisGame): void {
        if (!this.unlockedFeatures || !this.unlockedFeatures.autoMode) {
            if (typeof toast !== 'undefined' && toast.info) {
                toast.info(this.t('toast.autoLockedTitle'), this.t('toast.autoLockedMenuBody'));
            } else {
                logMessage(this.t('log.autoLockedMenu'));
            }
            return;
        }
        const modal = document.getElementById('autoSettingsModal');
        if (modal) {
            const masterToggle = getInput('autoMasterToggle');
            const masterLabel = document.getElementById('autoMasterLabel');
            if (masterToggle) masterToggle.checked = this.autoSelectEnabled;
            if (masterLabel) masterLabel.textContent = this.t('auto.masterState', {
                value: this.autoSelectEnabled ? this.t('state.on') : this.t('state.off')
            });

            const disCheck = getInput('autoSwitchDisadvantageCheck');
            const stamCheck = getInput('autoSwitchStaminaCheck');
            const advCheck = getInput('autoSwitchAdvantageCheck');
            const ultCheck = getInput('autoUltimateCheck');
            if (disCheck) disCheck.checked = this.autoSwitchDisadvantage;
            if (stamCheck) stamCheck.checked = this.autoSwitchStamina;
            if (advCheck) advCheck.checked = this.autoSwitchAdvantage;
            if (ultCheck) ultCheck.checked = this.autoUltimate;
            const optimalCheck = getInput('autoOptimalMovesCheck');
            if (optimalCheck) optimalCheck.checked = this.optimalMoveSelection;

            modal.classList.add('show');

            if (typeof this.syncAutoAdvancedSettingsUI === 'function') {
                this.syncAutoAdvancedSettingsUI();
            }

            this.positionCompactModal('autoSettingsModal', 'autoSelectGroup');
        }
    };

    GameClass.prototype.closeAutoSettings = function (this: ThisGame): void {
        const modal = document.getElementById('autoSettingsModal');
        if (modal) {
            modal.classList.remove('show');
        }
    };

    GameClass.prototype.toggleAutoSetting = function (this: ThisGame, setting: string): void {
        const onValue = this.t('state.on');
        const offValue = this.t('state.off');
        if (setting === 'disadvantage') {
            this.autoSwitchDisadvantage = !this.autoSwitchDisadvantage;
            logMessage(this.t('log.autoSwitchDisadvantage', { value: this.autoSwitchDisadvantage ? onValue : offValue }));
        } else if (setting === 'stamina') {
            this.autoSwitchStamina = !this.autoSwitchStamina;
            logMessage(this.t('log.autoSwitchEndurance', { value: this.autoSwitchStamina ? onValue : offValue }));
        } else if (setting === 'advantage') {
            this.autoSwitchAdvantage = !this.autoSwitchAdvantage;
            logMessage(this.t('log.autoSwitchAdvantage', { value: this.autoSwitchAdvantage ? onValue : offValue }));
        } else if (setting === 'ultimate') {
            this.autoUltimate = !this.autoUltimate;
            logMessage(this.t('log.autoUltimate', { value: this.autoUltimate ? onValue : offValue }));
        } else if (setting === 'advanced') {
            if (!this.unlockedFeatures?.autoFightAdvanced) {
                if (typeof toast !== 'undefined' && toast.info) {
                    toast.info(this.t('toast.autoFightAdvancedLockedTitle'), this.t('toast.autoFightAdvancedLockedBody'));
                }
                const chk = getInput('autoSwitchAdvancedCheck');
                if (chk) chk.checked = !!this.autoSwitchAdvanced;
                return;
            }
            this.autoSwitchAdvanced = !this.autoSwitchAdvanced;
            logMessage(this.t('log.autoSwitchAdvancedToggle', { value: this.autoSwitchAdvanced ? onValue : offValue }));
        }
    };

    /**
     * Toggle ON/OFF du Mode Auto (master).
     * NOTE : ne manipule plus directement les classes du bouton ; le rendu
     * visuel est centralisé dans uiManager.refreshCombatButtons() pour éviter
     * les sources de vérité multiples (badge, classe auto-active, aria-pressed).
     */
    GameClass.prototype.toggleAutoMaster = function (this: ThisGame): void {
        if (!this.unlockedFeatures || !this.unlockedFeatures.autoMode) {
            if (typeof toast !== 'undefined' && toast.info) {
                toast.info(this.t('toast.autoLockedTitle'), this.t('toast.autoLockedBody'));
            } else {
                logMessage(this.t('log.autoLocked'));
            }
            return;
        }
        this.autoSelectEnabled = !this.autoSelectEnabled;

        const masterToggle = (document.getElementById('autoMasterToggle') as HTMLInputElement | null);
        if (masterToggle && masterToggle.checked !== this.autoSelectEnabled) {
            masterToggle.checked = this.autoSelectEnabled;
        }
        const masterLabel = document.getElementById('autoMasterLabel');
        if (masterLabel) masterLabel.textContent = this.t('auto.masterState', {
            value: this.autoSelectEnabled ? this.t('state.on') : this.t('state.off')
        });

        logMessage(this.t(this.autoSelectEnabled ? 'log.autoEnabled' : 'log.autoDisabled'));

        refreshCombatButtonsUI(this);
        if (typeof this.saveGame === 'function') this.saveGame();
    };

    /**
     * Conservé pour compat : le badge est désormais rafraîchi par uiManager,
     * mais cette fonction reste appelable pour les anciens flux.
     */
    GameClass.prototype.updateAutoBadge = function (this: ThisGame): void {
        refreshCombatButtonsUI(this);
    };

    GameClass.prototype.showAutoTooltip = function (this: ThisGame): void {
        if (this.isTooltipSuppressedOnTouch()) return;

        const tooltip = document.getElementById('autoTooltip');
        if (!tooltip) return;

        const statusSpan = document.getElementById('tooltipStatus');
        const disSpan = document.getElementById('tooltipDisadvantage');
        const stamSpan = document.getElementById('tooltipStamina');
        const ultSpan = document.getElementById('tooltipUltimate');
        const advSpan = document.getElementById('tooltipAdvantage');
        const advancedSpan = document.getElementById('tooltipAdvanced');
        const optimalSpan = document.getElementById('tooltipOptimalMoves');

        const isAutoUnlocked = this.unlockedFeatures && this.unlockedFeatures.autoMode;
        const advancedOwned = !!(this.unlockedFeatures && this.unlockedFeatures.autoFightAdvanced);

        document.querySelectorAll('.auto-classic-only').forEach((el) => {
            (el as HTMLElement).hidden = advancedOwned;
        });
        const advancedTooltipRow = document.getElementById('autoTooltipAdvancedRow');
        if (advancedTooltipRow) advancedTooltipRow.hidden = !advancedOwned;

        if (!isAutoUnlocked) {
            if (statusSpan) statusSpan.textContent = this.t('state.locked');
            if (disSpan) {
                disSpan.textContent = '-';
                disSpan.className = 'tooltip-status off';
            }
            if (stamSpan) {
                stamSpan.textContent = '-';
                stamSpan.className = 'tooltip-status off';
            }
            if (advSpan) {
                advSpan.textContent = '-';
                advSpan.className = 'tooltip-status off';
            }
            if (ultSpan) {
                ultSpan.textContent = '-';
                ultSpan.className = 'tooltip-status off';
            }
            if (advancedSpan) {
                advancedSpan.textContent = '-';
                advancedSpan.className = 'tooltip-status off';
            }
        } else {
            if (statusSpan) statusSpan.textContent = this.autoSelectEnabled ? this.t('state.on') : this.t('state.off');

            if (!advancedOwned && disSpan) {
                disSpan.textContent = this.autoSwitchDisadvantage ? this.t('state.on') : this.t('state.off');
                disSpan.className = this.autoSwitchDisadvantage ? 'tooltip-status' : 'tooltip-status off';
            }
            if (stamSpan) {
                stamSpan.textContent = this.autoSwitchStamina ? this.t('state.on') : this.t('state.off');
                stamSpan.className = this.autoSwitchStamina ? 'tooltip-status' : 'tooltip-status off';
            }
            if (!advancedOwned && advSpan) {
                advSpan.textContent = this.autoSwitchAdvantage ? this.t('state.on') : this.t('state.off');
                advSpan.className = this.autoSwitchAdvantage ? 'tooltip-status' : 'tooltip-status off';
            }
            if (ultSpan) {
                ultSpan.textContent = this.autoUltimate ? this.t('state.on') : this.t('state.off');
                ultSpan.className = this.autoUltimate ? 'tooltip-status' : 'tooltip-status off';
            }
        }

        if (optimalSpan && !advancedOwned) {
            optimalSpan.textContent = this.optimalMoveSelection ? this.t('combatUi.moveModeOptimalShort') : this.t('combatUi.moveModeListShort');
            optimalSpan.className = this.optimalMoveSelection ? 'tooltip-status' : 'tooltip-status off';
        }

        if (advancedSpan && advancedOwned) {
            const advancedOn = !!(this.unlockedFeatures?.autoFightAdvanced && this.autoSwitchAdvanced);
            advancedSpan.textContent = advancedOn ? this.t('state.on') : this.t('state.off');
            advancedSpan.className = advancedOn ? 'tooltip-status' : 'tooltip-status off';
        }

        const postureRow = document.getElementById('autoTooltipPostureRow');
        const switchGainRow = document.getElementById('autoTooltipSwitchGainRow');
        const respectRow = document.getElementById('autoTooltipRespectPreferredRow');
        const postureSpan = document.getElementById('tooltipPosture');
        const switchGainSpan = document.getElementById('tooltipSwitchGain');
        const respectSpan = document.getElementById('tooltipRespectPreferred');
        if (postureRow) postureRow.hidden = !advancedOwned;
        if (switchGainRow) switchGainRow.hidden = !advancedOwned;
        if (respectRow) respectRow.hidden = !advancedOwned;
        if (advancedOwned && postureSpan) {
            const posture = this.autoFightSwitchPosture ?? 50;
            let postureLabel = this.t('autoPanel.postureBalanced');
            if (posture <= 33) postureLabel = this.t('autoPanel.postureDefensive');
            else if (posture >= 67) postureLabel = this.t('autoPanel.postureOffensive');
            postureSpan.textContent = postureLabel;
        }
        if (advancedOwned && switchGainSpan) {
            const pct = Math.round((this.autoFightAdvancedOptions?.minScoreGainPct ?? 0.20) * 100);
            switchGainSpan.textContent = `${pct}%`;
        }
        if (advancedOwned && respectSpan) {
            const respectOn = this.autoFightAdvancedOptions?.respectPreferredActive !== false;
            respectSpan.textContent = respectOn ? this.t('state.on') : this.t('state.off');
            respectSpan.className = respectOn ? 'tooltip-status' : 'tooltip-status off';
        }

        // Anchor sur le groupe split (centre visuel des deux zones)
        const anchor = document.getElementById('autoSelectGroup') || document.getElementById('autoSelectBtn');
        if (anchor) {
            const rect = anchor.getBoundingClientRect();
            const btnCenterX = rect.left + (rect.width / 2);
            const btnCenterY = rect.top + (rect.height / 2);

            const offsetX = 50;
            const offsetY = 50;

            tooltip.style.left = `${btnCenterX + offsetX}px`;
            tooltip.style.bottom = `${(window.innerHeight - btnCenterY) + offsetY}px`;
            tooltip.style.transform = 'none';
        }

        tooltip.classList.add('show');
        if (this.isTouchUi()) this.scheduleTooltipAutoHide();
    };

    GameClass.prototype.hideAutoTooltip = function (this: ThisGame): void {
        const tooltip = document.getElementById('autoTooltip');
        if (tooltip) {
            tooltip.classList.remove('show');
        }
    };

    GameClass.prototype.showForfeitTooltip = function (this: ThisGame): void {
        if (this.isTooltipSuppressedOnTouch()) return;

        const tooltip = document.getElementById('forfeitTooltip');
        if (!tooltip) return;

        const btn = document.getElementById('forfeitBtn');
        if (btn) {
            const rect = btn.getBoundingClientRect();
            const btnCenterX = rect.left + (rect.width / 2);
            const btnCenterY = rect.top + (rect.height / 2);

            const offsetX = -220;
            const offsetY = 50;

            tooltip.style.left = `${btnCenterX + offsetX}px`;
            tooltip.style.bottom = `${(window.innerHeight - btnCenterY) + offsetY}px`;
            tooltip.style.transform = 'none';
        }

        tooltip.classList.add('show');
        if (this.isTouchUi()) this.scheduleTooltipAutoHide();
    };

    GameClass.prototype.hideForfeitTooltip = function (this: ThisGame): void {
        const tooltip = document.getElementById('forfeitTooltip');
        if (tooltip) {
            tooltip.classList.remove('show');
        }
    };

    GameClass.prototype.forfeitCombat = function (this: ThisGame): void {
        if (this.gymTrainerState?.active && this.gymTrainerState.isFarmThreat && this.gymTrainerState.farmThreatId) {
            const threatId = String(this.gymTrainerState.farmThreatId);
            this.gymTrainerState = null;
            this.faintedThisCombat?.clear();
            this.faintedUidsThisCombat?.clear();
            resolveFarmThreatCombatLoss(this, threatId);
            syncMegaTimerWithCombatState(this);
            syncDynamaxTimerWithCombatState(this);
            logMessage(this.t('log.combatForfeited'));
            refreshTeamAfterCombat(this);
            this.updateCombatDisplay();
            return;
        }

        if (this.towerState.isActive) {
            if (confirm(this.t('modal.leaveTowerConfirm'))) {
                logMessage(this.t('log.towerLeaveWithGains'));
                this.endTowerRun(true);
            }
            return;
        }

        if (this.subwayState?.isActive) {
            if (confirm(this.t('modal.leaveSubwayConfirm') || this.t('modal.leaveTowerConfirm'))) {
                this.endSubwayRun(true);
            }
            return;
        }

        if (this.championsTowerState?.isActive) {
            if (confirm(this.t('modal.leaveChampionsTowerConfirm') || this.t('modal.leaveTowerConfirm'))) {
                this.endChampionsTowerRun(true);
            }
            return;
        }

        if (this.arenaState.active) {
            this.loseArena("Abandon");
            return;
        }

        const captureModal = document.getElementById('captureModal');
        if (captureModal && captureModal.classList.contains('show')) {
            this.skipCapture();
            return;
        }

        if (this.combatState !== 'fighting' && this.combatState !== 'starting') {
            logMessage(this.t('log.noCombatInProgress'));
            return;
        }

        if (this.gymTrainerState?.active) {
            this.gymTrainerState = null;
            this.faintedThisCombat?.clear();
            this.faintedUidsThisCombat?.clear();

            if (this.currentPlayerCreature && typeof this.getPlayerMaxHp === 'function') {
                const poolHp = Math.min(
                    this.getPlayerMaxHp(),
                    Math.max(0, this.currentPlayerCreature.currentHp || 0),
                );
                this.playerTeam.forEach((c) => {
                    c.mainAccountCurrentHp = poolHp;
                    if (c.mainAccountCurrentHp > 0) {
                        c.currentHp = Math.min(c.maxHp || c.mainAccountCurrentHp, c.mainAccountCurrentHp);
                    }
                });
            }

            if (typeof this.invalidateStatsCache === 'function') this.invalidateStatsCache();

            this.combatState = 'waiting';
            syncMegaTimerWithCombatState(this);
            syncDynamaxTimerWithCombatState(this);
            this.lastCombatTime = Date.now();
            this.currentEnemy = null;
            this._applyActiveFirstAfterCombatIfNeeded();
            logMessage(this.t('log.combatForfeited'));
            refreshTeamAfterCombat(this);
            this.updateCombatDisplay();
            return;
        }

        this.combatState = 'waiting';
        syncMegaTimerWithCombatState(this);
        syncDynamaxTimerWithCombatState(this);
        this.lastCombatTime = Date.now();
        this.currentEnemy = null;
        this._applyActiveFirstAfterCombatIfNeeded();

        logMessage(this.t('log.combatForfeited'));
        this.updateCombatDisplay();
    };

    (globalThis as Record<string, unknown>).__applySimCombatDamage = applySimDamageGlobal;
}
