/// <reference types="svelte" />
/**
 * Store: zone — see CARTOGRAPHY.md
 * Consumers: Header (AFK), ZoneSelector
 */

import { facade } from '@bus/facade';
import { GameEventType as Evt } from '../bus/events.js';

class ZoneStore {
  currentZone: number = $state(1);
  maxReachedZone: number = $state(1);
  currentRegion: string = $state('kanto');
  zoneName: string = $state('');
}

export const zone = new ZoneStore();

facade.subscribe(Evt.ZONE_CHANGED, (evt) => {
  if (!('zone' in evt)) return;
  zone.currentZone = evt.zone;
  zone.currentRegion = evt.region;
  zone.maxReachedZone = evt.maxReachedZone;
  zone.zoneName = evt.zoneName;
});
