/**
 * Tooltip HTML for the miltank-farm-btn--feed button (requested item + sprite).
 */

import { escapeHtml } from '../../formatters.ts';

export type FeedTooltipSnap = {
    requestItemKey: string | null;
    requestItemName: string | null;
    requestItemIconUrl: string | null;
    requestQty: number;
    requestOwned: number;
    canFeed: boolean;
    feedBlockedLabel: string | null;
    ui: {
        requestLabel: string;
        noRequest: string;
        inBagLabel: string;
    };
};

export function buildFeedButtonTooltipContent(snap: FeedTooltipSnap): { title: string; body: string } {
    const title = snap.ui.requestLabel;

    if (!snap.requestItemKey) {
        const blocked = !snap.canFeed && snap.feedBlockedLabel
            ? `<div class="miltank-farm-feed-tooltip-blocked">${escapeHtml(snap.feedBlockedLabel)}</div>`
            : '';
        return {
            title,
            body: `<p class="miltank-farm-feed-tooltip-empty">${escapeHtml(snap.ui.noRequest)}</p>${blocked}`,
        };
    }

    const icon = snap.requestItemIconUrl
        ? `<img class="miltank-farm-feed-tooltip-icon item-sprite-img" src="${escapeHtml(snap.requestItemIconUrl)}" alt="" width="36" height="36" loading="lazy" decoding="async">`
        : '';
    const qty = Math.max(1, Math.floor(Number(snap.requestQty) || 0));
    const name = escapeHtml(snap.requestItemName ?? snap.requestItemKey);
    const owned = Math.max(0, Math.floor(Number(snap.requestOwned) || 0));
    const inBag = escapeHtml(snap.ui.inBagLabel);

    let body = `<div class="miltank-farm-feed-tooltip-line">${icon}<span class="miltank-farm-feed-tooltip-text"><strong>${qty}× ${name}</strong><span class="miltank-farm-feed-tooltip-owned">(${owned} ${inBag})</span></span></div>`;

    if (!snap.canFeed && snap.feedBlockedLabel) {
        body += `<div class="miltank-farm-feed-tooltip-blocked">${escapeHtml(snap.feedBlockedLabel)}</div>`;
    }

    return { title, body };
}
