<script lang="ts">
  import { team } from '../stores/team.svelte.ts';
  import { game } from '../../gameManager.js';
  import { PASSIVE_TALENTS } from '../../constants/balance/talentsAndCombat.js';
  import { computeMaternalInstinctFromTeam } from '../../gameEggSystem.ts';
  import {
    formatPassiveTalentDescriptionWithElu,
    formatEluStackBonusSuffix,
    formatMultDeltaValue,
    type TalentEluDisplayOpts,
  } from '../lib/talentEluDisplay.ts';
  import type { GameRuntime } from '../types/game.js';
  import { touchTooltipHandlers } from '../ui/scheduleTooltipHelpers.ts';

  type TalentChip = {
    key: string;
    count: number;
    name: string;
    desc: string;
    bonusText: string;
    rarityClass: string;
  };

  const STACKING_TALENT_KEYS = new Set([
    'mentor',
    'collecteur',
    'maitre',
    'catalyseur',
    'catalyseur_supreme',
    'aura',
    'instinct_maternel',
  ]);

  function buildEluDescOpts(gm: GameRuntime, count: number): TalentEluDisplayOpts {
    return {
      stackCount: count,
      formatUltChargeDelta: (d) => gm.t('teamTalents.eluBonusUltCharge', { value: String(d) }),
      formatMultDelta: (d) => gm.t('teamTalents.eluBonusMult', { value: formatMultDeltaValue(d) }),
    };
  }

  function appendEluStackSuffix(
    gm: GameRuntime,
    talentKey: string,
    bonusText: string,
    eluActive: boolean,
  ): string {
    if (!eluActive || talentKey === 'elu' || !bonusText) return bonusText;

    if (talentKey === 'instinct_maternel') {
      const redWith =
        typeof gm.getMaternalInstinctIncubationReduction === 'function'
          ? gm.getMaternalInstinctIncubationReduction()
          : 0;
      const redWithout = computeMaternalInstinctFromTeam(team.playerTeam, false).reduction;
      const delta = redWith - redWithout;
      return delta > 0 ? bonusText + formatEluStackBonusSuffix(delta) : bonusText;
    }

    if (!STACKING_TALENT_KEYS.has(talentKey) || typeof gm.getTalentStackBonus !== 'function') {
      return bonusText;
    }

    const withElu = gm.getTalentStackBonus(talentKey);
    const withoutElu = gm.getTalentStackBonus(talentKey, { ignoreElu: true });
    const delta = withElu - withoutElu;
    return delta > 0 ? bonusText + formatEluStackBonusSuffix(delta) : bonusText;
  }

  let talentCounts = $derived.by(() => {
    const _sig = team.passiveTalentsSignature;
    const counts: Record<string, number> = {};
    for (const c of team.playerTeam) {
      if (!c?.passiveTalent) continue;
      counts[c.passiveTalent] = (counts[c.passiveTalent] || 0) + 1;
    }
    return counts;
  });

  let chips = $derived.by((): TalentChip[] => {
    const _sig = team.passiveTalentsSignature;
    const gm = game as GameRuntime | null;
    if (!gm) return [];
    const eluActive = typeof gm.hasEluActive === 'function' && gm.hasEluActive();
    const out: TalentChip[] = [];
    for (const [talentKey, count] of Object.entries(talentCounts)) {
      const talent = (PASSIVE_TALENTS as Record<string, { name?: string; description?: string; rarity?: string }>)[talentKey];
      if (!talent) continue;
      const bonus = typeof gm.getTalentStackBonus === 'function' ? gm.getTalentStackBonus(talentKey) : 0;
      let bonusText = '';
      if (talentKey === 'mentor') bonusText = gm.t('teamTalents.bonusMentor', { value: (bonus * 100).toFixed(0) });
      else if (talentKey === 'collecteur') bonusText = gm.t('teamTalents.bonusCollecteur', { value: (bonus * 100).toFixed(0) });
      else if (talentKey === 'maitre') bonusText = gm.t('teamTalents.bonusMaitre', { value: (bonus * 100).toFixed(0) });
      else if (talentKey === 'catalyseur' || talentKey === 'catalyseur_supreme') {
        bonusText = gm.t('teamTalents.bonusCatalyseur', { value: (bonus * 100).toFixed(1) });
      } else if (talentKey === 'aura') bonusText = gm.t('teamTalents.bonusAura', { value: (bonus * 100).toFixed(0) });
      else if (talentKey === 'instinct_maternel') {
        const red = typeof gm.getMaternalInstinctIncubationReduction === 'function'
          ? gm.getMaternalInstinctIncubationReduction()
          : 0;
        bonusText = gm.t('teamTalents.bonusInstinctMaternel', { value: String(Math.round(red * 100)) });
      } else if (talentKey === 'piegeur') {
        bonusText = gm.t('teamTalents.piegeurHighestOnly');
      }

      if (eluActive && talentKey !== 'elu') {
        bonusText = appendEluStackSuffix(gm, talentKey, bonusText, eluActive);
      }

      const talentName =
        typeof gm.getLocalizedPassiveTalentName === 'function'
          ? gm.getLocalizedPassiveTalentName(talentKey, talent.name ?? talentKey)
          : (talent.name ?? talentKey);
      let talentDesc =
        typeof gm.getLocalizedPassiveTalentDescription === 'function'
          ? gm.getLocalizedPassiveTalentDescription(talentKey, talent.description ?? '')
          : (talent.description ?? '');
      if (eluActive && talentKey !== 'elu') {
        talentDesc = formatPassiveTalentDescriptionWithElu(
          talentDesc,
          talentKey,
          eluActive,
          buildEluDescOpts(gm, count),
        );
      }
      const effectLabel = gm.t('teamTalents.effectLabel');
      const activeLabel = gm.t('teamTalents.activeLabel');
      let desc: string;
      if (talentKey === 'piegeur') {
        const carriersLabel = gm.t('teamTalents.piegeurCarriersLabel');
        const highestOnly = gm.t('teamTalents.piegeurHighestOnly');
        const hint = gm.t('teamTalents.piegeurHighestOnlyHint');
        desc = `${carriersLabel}: x${count}\n${effectLabel}: ${highestOnly}\n\n${hint}\n\n${talentDesc}`;
      } else {
        const stackLabel = gm.t('teamTalents.stackLabel');
        desc = `${stackLabel}: x${count}\n${effectLabel}: ${bonusText || activeLabel}\n\n${talentDesc}`;
      }

      out.push({
        key: talentKey,
        count,
        name: talentName,
        desc,
        bonusText,
        rarityClass: talent.rarity === 'legendary' ? 'legendary' : 'epic',
      });
    }
    return out;
  });

  let visible = $derived(chips.length > 0);
  let headerTitle = $derived((game as GameRuntime | null)?.t?.('teamTalents.headerTitle') ?? 'Talents');

  function chipHandlers(chip: TalentChip) {
    return touchTooltipHandlers(() => ({ title: chip.name, body: chip.desc }));
  }
</script>

<div id="activeTalentsDisplay" style:display={visible ? 'block' : 'none'}>
  {#if visible}
    <div class="talents-header-title">&#9889; {headerTitle}</div>
    <div class="talent-summary-grid" id="talentGrid">
      {#each chips as chip (chip.key)}
        {@const handlers = chipHandlers(chip)}
        <div
          id="talent-chip-{chip.key}"
          class="talent-chip {chip.rarityClass}"
          data-count={String(chip.count)}
          role="button"
          tabindex="0"
          onmouseenter={handlers.onmouseenter}
          onmouseleave={handlers.onmouseleave}
          onfocus={handlers.onfocus}
          onblur={handlers.onblur}
          onclick={handlers.onclick}
          onkeydown={handlers.onkeydown}
        >
          <strong>{chip.name}</strong>
          <span style="font-size:9px; opacity:1;">x{chip.count}</span>
          {#if chip.bonusText}
            <span class="talent-bonus-text">{@html chip.bonusText}</span>
          {/if}
        </div>
      {/each}
    </div>
  {/if}
</div>
