/**
 * @file src/lib/moveTooltip.ts
 * Tooltips d'attaques : descriptions officielles + stats mécaniques.
 */

import { getMoveDefinition, getBasePPForMove, resolveMoveName } from '../../constants/movesDb.ts';
import { getLocalizedMoveDescriptionPlain } from '../../constants/moveDescriptionI18n.ts';
import { formatMoveSecondaryTooltipParts } from './moveSecondaryEffects.ts';
import { getMoveBaseAccuracy } from './resolveMoveHit.ts';
import { getRampageConfig } from './rampageMove.ts';
import {
    hasDoublePowerOnTargetStatus,
    isPartialTrapMove,
    moveClearsPartialTrap,
} from './moveCombatModifiers.ts';
import { escapeHtml } from '../../formatters.ts';
import type { GameRuntime } from '../types/game.js';

function normalizeLang(game: GameRuntime): string {
    if (typeof game.normalizeLanguage === 'function') {
        return game.normalizeLanguage(game.language);
    }
    return String(game.language || 'fr').toLowerCase().startsWith('en') ? 'en' : 'fr';
}

function t(game: GameRuntime, key: string, params?: Record<string, string | number>): string {
    if (typeof game.t !== 'function') return key;
    const raw = game.t(key, params);
    return raw && raw !== key ? raw : key;
}

export interface MoveTooltipOptions {
    ppCurrent?: number;
    ppMax?: number;
}

/** Compact row label: "Préc. 85" / "Préc. —" (creature-move-row). */
export function formatMoveAccuracyRowLabel(game: GameRuntime, move: Record<string, unknown>): string {
    const shortKey = 'modal.creature.accuracyShort';
    const short = t(game, shortKey);
    const label = short !== shortKey ? short : (normalizeLang(game) === 'en' ? 'Acc.' : 'Préc.');
    if (move.accuracy === null) return `${label} —`;
    if (move.accuracy === undefined) return `${label} 100`;
    const base = getMoveBaseAccuracy(move);
    return `${label} ${base ?? 100}`;
}

function formatPpPart(
    game: GameRuntime,
    move: Record<string, unknown>,
    opts?: MoveTooltipOptions,
): string | null {
    const cur = opts?.ppCurrent;
    const max = opts?.ppMax;
    if (Number.isFinite(cur) && Number.isFinite(max)) {
        const key = 'modal.creature.moveTooltip.ppCurrent';
        const raw = t(game, key, { current: cur as number, max: max as number });
        return raw !== key ? raw : `PP ${cur}/${max}`;
    }
    const basePp = getBasePPForMove(move);
    if (!Number.isFinite(basePp) || basePp <= 0) return null;
    const key = 'modal.creature.moveTooltip.pp';
    const raw = t(game, key, { value: basePp });
    return raw !== key ? raw : `PP ${basePp}`;
}

function buildStatsLine(
    game: GameRuntime,
    move: Record<string, unknown>,
    opts?: MoveTooltipOptions,
): string {
    const parts: string[] = [];
    const typeKey = String(move.type || 'normal');
    const typeI18n = t(game, `types.${typeKey}`);
    parts.push(typeI18n !== `types.${typeKey}` ? typeI18n : typeKey.charAt(0).toUpperCase() + typeKey.slice(1));

    const category = String(move.category || 'physical');
    if (category === 'special') {
        parts.push(t(game, 'modal.creature.moveTooltip.categorySpecial'));
    } else if (category === 'physical') {
        parts.push(t(game, 'modal.creature.moveTooltip.categoryPhysical'));
    } else if (category === 'status') {
        parts.push(t(game, 'modal.creature.moveTooltip.categoryStatus'));
    }

    const retaliationMult = Number(move.retaliationMultiplier);
    if (Number.isFinite(retaliationMult) && retaliationMult > 0) {
        const retaliationKey = 'modal.creature.moveTooltip.retaliationMultiplier';
        const retaliationRaw = t(game, retaliationKey, { multiplier: retaliationMult });
        if (retaliationRaw !== retaliationKey) {
            parts.push(retaliationRaw);
        } else {
            const lang = normalizeLang(game);
            parts.push(`×${retaliationMult} ${lang === 'en' ? 'last damage taken' : 'derniers dégâts reçus'}`);
        }
        const retaliationCat = String(move.retaliationDamageCategory || '');
        if (retaliationCat === 'physical' || retaliationCat === 'special') {
            const catKey = `modal.creature.moveTooltip.retaliationCategory.${retaliationCat}`;
            const catRaw = t(game, catKey);
            if (catRaw !== catKey) parts.push(catRaw);
        }
    } else if (move.variableHpPowerMode === 'reversal' || move.variableHpPowerMode === 'flail') {
        const varKey = `modal.creature.moveTooltip.variableHpPower.${move.variableHpPowerMode}`;
        const varRaw = t(game, varKey);
        if (varRaw !== varKey) parts.push(varRaw);
    } else if (hasDoublePowerOnTargetStatus(move)) {
        const key = 'modal.creature.moveTooltip.doublePowerOnTargetStatus';
        const raw = t(game, key);
        if (raw !== key) parts.push(raw);
    } else {
        const power = Number(move.power);
        if (Number.isFinite(power) && power > 0) {
            parts.push(`${t(game, 'modal.creature.powerShort')} ${power}`);
        }
    }

    if (move.accuracy === null || move.accuracy === undefined) {
        const alwaysKey = 'modal.creature.moveTooltip.accuracyAlways';
        const alwaysRaw = t(game, alwaysKey);
        if (alwaysRaw !== alwaysKey) parts.push(alwaysRaw);
    } else {
        const acc = Number(move.accuracy);
        if (Number.isFinite(acc) && acc > 0 && acc < 100) {
            const accKey = 'modal.creature.moveTooltip.accuracy';
            const accRaw = t(game, accKey, { value: acc });
            if (accRaw !== accKey) parts.push(accRaw);
        }
    }

    const minHits = Number(move.minHits);
    const maxHits = Number(move.maxHits);
    if (Number.isFinite(minHits) && Number.isFinite(maxHits) && maxHits > 1) {
        const hitsKey = 'modal.creature.moveTooltip.multiHit';
        const hitsRaw = t(game, hitsKey, { min: minHits, max: maxHits });
        if (hitsRaw !== hitsKey) parts.push(hitsRaw);
    }

    const ppPart = formatPpPart(game, move, opts);
    if (ppPart) parts.push(ppPart);

    const drain = Number(move.drain);
    if (Number.isFinite(drain) && drain > 0) {
        parts.push(t(game, 'modal.creature.moveTooltip.drain', { percent: Math.round(drain * 100) }));
    }

    const recoil = Number(move.recoil);
    if (Number.isFinite(recoil) && recoil > 0) {
        parts.push(t(game, 'modal.creature.moveTooltip.recoil', { percent: Math.round(recoil * 100) }));
    }

    if (move.selfStatusOnHit === 'mired') {
        const slowKey = 'modal.creature.moveTooltip.selfSlowOnHit';
        const slowRaw = t(game, slowKey);
        if (slowRaw !== slowKey) parts.push(slowRaw);
    }

    const rampage = getRampageConfig(move);
    if (rampage) {
        const rampageKey = 'modal.creature.moveTooltip.rampage';
        const rampageRaw = t(game, rampageKey, { min: rampage.minTurns, max: rampage.maxTurns });
        if (rampageRaw !== rampageKey) parts.push(rampageRaw);
    }

    if (move.requiresAllOtherMovesExhausted) {
        const lastResortKey = 'modal.creature.moveTooltip.lastResortRequiresExhaustion';
        const lastResortRaw = t(game, lastResortKey);
        if (lastResortRaw !== lastResortKey) parts.push(lastResortRaw);
    }

    const critBonus = Number(move.critRateBonus);
    if (Number.isFinite(critBonus) && critBonus > 0) {
        const critKey = 'modal.creature.moveTooltip.highCrit';
        const critRaw = t(game, critKey);
        if (critRaw !== critKey) parts.push(critRaw);
    }

    if (isPartialTrapMove(move)) {
        const trapKey = 'modal.creature.moveTooltip.partialTrap';
        const trapRaw = t(game, trapKey);
        if (trapRaw !== trapKey) parts.push(trapRaw);
    }

    if (moveClearsPartialTrap(move)) {
        const clearKey = 'modal.creature.moveTooltip.clearsPartialTrap';
        const clearRaw = t(game, clearKey);
        if (clearRaw !== clearKey) parts.push(clearRaw);
    }

    const movePriority = Number(move.priority);
    if (Number.isFinite(movePriority) && movePriority > 0) {
        const priorityKey = 'modal.creature.moveTooltip.priorityNextAction';
        const priorityRaw = t(game, priorityKey);
        if (priorityRaw !== priorityKey) parts.push(priorityRaw);
    }

    parts.push(...formatMoveSecondaryTooltipParts(game, move));

    return parts.join(t(game, 'modal.creature.moveTooltip.statsSeparator'));
}

export function buildMoveTooltipBody(
    game: GameRuntime,
    moveName: string,
    opts?: MoveTooltipOptions,
): string | null {
    const lang = normalizeLang(game);
    const move = getMoveDefinition(moveName);
    if (!move) return null;

    const desc = getLocalizedMoveDescriptionPlain(moveName, lang);
    const statsLine = buildStatsLine(game, move as Record<string, unknown>, opts);
    if (!desc && !statsLine) return null;
    if (!desc) {
        return `<span class="move-tooltip-stats">${escapeHtml(statsLine)}</span>`;
    }
    if (!statsLine) return escapeHtml(desc);
    return `${escapeHtml(desc)}<br><span class="move-tooltip-stats">${escapeHtml(statsLine)}</span>`;
}

export function readMoveTooltipOptionsFromElement(el: HTMLElement): MoveTooltipOptions {
    const ppCurrent = Number(el.dataset.moveTooltipPpCurrent);
    const ppMax = Number(el.dataset.moveTooltipPpMax);
    const opts: MoveTooltipOptions = {};
    if (Number.isFinite(ppCurrent) && Number.isFinite(ppMax)) {
        opts.ppCurrent = ppCurrent;
        opts.ppMax = ppMax;
    }
    return opts;
}

export function isMoveTooltipTapBlocked(target: Element): boolean {
    if (target.closest('button')) return true;
    if (target.closest('[data-action-stop]')) return true;
    if (target.closest('.creature-relearn-equip-btn')) return true;
    return false;
}

export function showMoveTooltipFromElement(
    game: GameRuntime,
    el: HTMLElement,
    tapEvent: { clientX: number; clientY: number; currentTarget?: Element; target?: Element },
): boolean {
    if (typeof game.scheduleTooltip !== 'function') return false;
    const moveName = el.dataset.moveTooltipName || '';
    if (!moveName) return false;
    const opts = readMoveTooltipOptionsFromElement(el);
    const body = buildMoveTooltipBody(game, moveName, opts);
    if (!body) return false;
    const title = getMoveTooltipTitle(game, moveName);
    game.scheduleTooltip(tapEvent, title, body, 50);
    return true;
}

export function getMoveTooltipTitle(game: GameRuntime, moveName: string): string {
    if (typeof game.getLocalizedMoveNamePlain === 'function') {
        const label = game.getLocalizedMoveNamePlain(moveName);
        if (label) return escapeHtml(label);
    }
    return escapeHtml(resolveMoveName(moveName));
}

let moveTooltipEventsBound = false;

export function bindMoveTooltipEvents(root: HTMLElement | Document, game: GameRuntime): void {
    if (moveTooltipEventsBound) return;
    if (!game || typeof game.scheduleTooltip !== 'function' || typeof game.hideTooltip !== 'function') return;
    moveTooltipEventsBound = true;

    const host = root;
    host.addEventListener('mouseover', (ev) => {
        const target = ev.target;
        if (!(target instanceof Element)) return;
        const node = target.closest('[data-move-tooltip-name]');
        if (!node) return;
        showMoveTooltipFromElement(game, node as HTMLElement, ev);
    });

    host.addEventListener('mouseout', (ev) => {
        const target = ev.target;
        if (!(target instanceof Element)) return;
        const node = target.closest('[data-move-tooltip-name]');
        if (!node) return;
        game.hideTooltip();
    });
}
