/**
 * @file src/lib/bonusMoomooMilkStats.ts
 * Moomoo Milk usage + efficiency snapshot for the Bonus modal support tab.
 */

import { MILTANK_FARM_TALENTS } from '../../constants/balance/miltankFarmTalents.ts';
import type { MiltankFarmState } from './miltankFarmLogic.ts';
import {
    computeVitaminEfficiencyFromMilkCount,
    getMilkPotencyVitaminBonusTotal,
    getMoomooMilkConsumedCount,
    getMoomooMilkVitaminBonusPerUse,
} from './miltankFarmTalents.ts';

export interface MoomooMilkBonusSnapshot {
    usedCount: number;
    perUseEfficiency: number;
    basePerUse: number;
    farmBonusPerUse: number;
    totalAccumulatedEfficiency: number;
}

export function buildMoomooMilkBonusSnapshot(
    stats: unknown,
    miltankFarmState: MiltankFarmState | null | undefined,
): MoomooMilkBonusSnapshot {
    const usedCount = getMoomooMilkConsumedCount(stats);
    const farmBonusPerUse = getMilkPotencyVitaminBonusTotal(miltankFarmState);
    const basePerUse = MILTANK_FARM_TALENTS.moomooMilkBaseVitaminEfficiency;
    const perUseEfficiency = getMoomooMilkVitaminBonusPerUse(miltankFarmState);
    const totalAccumulatedEfficiency = computeVitaminEfficiencyFromMilkCount(usedCount, miltankFarmState);

    return {
        usedCount,
        perUseEfficiency,
        basePerUse,
        farmBonusPerUse,
        totalAccumulatedEfficiency,
    };
}
