/**
 * @file src/lib/bonusModalSnapshot.ts
 * Pure bonus-row definitions for the Bonus modal (testable, no DOM).
 */

import { RARITY, RARITY_CHANCES } from '../../constants/core.ts';
import { getTotalVitaminEfficiency, sumVitaminsConsumed } from './vitaminsStats.ts';
import type { GameRuntime } from '../types/game.js';
import { getActiveStatBoostKey } from './statBoostKey.ts';
import { buildMoomooMilkBonusSnapshot } from './bonusMoomooMilkStats.ts';
import { getFeticheStatsForGains } from './feticheLogic.ts';

export type BonusSource = { label: string; value: number };

export type BonusRowInfo = {
    tab: string;
    label: string;
    decimals?: number;
    sources?: BonusSource[];
    total: number;
    formatPct?: boolean;
    impact?: string;
    formulaType?: string;
    impactKey?: string;
    impactBase?: number;
};

export type BonusTranslate = (key: string, vars?: Record<string, unknown>) => string;

export type TeamStatSums = {
    hp: number;
    attack: number;
    spattack: number;
    defense: number;
    speed: number;
};

/** Synergy multipliers are stored as factors (1.04); return additive delta (0.04). */
export function synergyMultDelta(syn: Record<string, number>, key: string): number {
    const v = Number(syn[key]) || 1;
    return v > 1 ? v - 1 : 0;
}

function sumActivePotionBoost(game: GameRuntime, stat: string): number {
    const boosts = game.activeStatBoosts;
    if (!Array.isArray(boosts)) return 0;
    const now = Date.now();
    let sum = 0;
    for (let i = 0; i < boosts.length; i++) {
        const boost = boosts[i];
        if (!boost) continue;
        if (boost.endTime != null && boost.endTime <= now) continue;
        const key = getActiveStatBoostKey(boost);
        if (key === 'all' || key === stat) sum += Number(boost.value) || 0;
    }
    return sum;
}

function countActiveTimedBoosts(game: GameRuntime): number {
    const boosts = game.activeBoosts;
    if (!Array.isArray(boosts)) return 0;
    const now = Date.now();
    let n = 0;
    for (let i = 0; i < boosts.length; i++) {
        const b = boosts[i];
        if (!b) continue;
        if (b.endTime != null && b.endTime <= now) continue;
        if ((Number(b.value) || 0) > 0) n++;
    }
    return n;
}

export function buildTeamStatSums(game: GameRuntime): TeamStatSums {
    const team = Array.isArray(game.playerTeam) ? game.playerTeam : [];
    return {
        hp: team.reduce((acc, c) => acc + (Number(c?.maxHp) || 0), 0),
        attack: team.reduce((acc, c) => acc + (Number(c?.attack) || 0), 0),
        spattack: team.reduce((acc, c) => acc + (Number(c?.spattack) || 0), 0),
        defense: team.reduce((acc, c) => acc + (Number(c?.defense) || 0), 0),
        speed: team.reduce((acc, c) => acc + (Number(c?.speed) || 0), 0),
    };
}

export function buildBonusModalRows(
    game: GameRuntime,
    bonusT: BonusTranslate,
    fmtNum: (n: number) => string = String,
): Record<string, BonusRowInfo> {
    const tal = (k: string) =>
        typeof game.getAccountTalentBonus === 'function' ? (game.getAccountTalentBonus(k) || 0) : 0;
    const coll =
        typeof game.getCollectionBonuses === 'function' ? (game.getCollectionBonuses() || {}) : {};
    const mast = (k: string) =>
        typeof game.getMasteryBonus === 'function' ? (game.getMasteryBonus(k) || 0) : 0;
    const syn =
        typeof game.getActiveSynergies === 'function' ? (game.getActiveSynergies() || {}) : {};

    const teamSums = buildTeamStatSums(game);

    const bonuses: Record<string, BonusRowInfo> = {
        hpMaxTalent: {
            tab: 'combat',
            label: bonusT('bonusMaxHp'),
            decimals: 0,
            sources: [{ label: bonusT('sourceTalent'), value: tal('hp_mult') * 100 }],
            total: tal('hp_mult') * 100,
            impactKey: 'impactTeamHp',
            impactBase: teamSums.hp,
        },
        hpCollection: {
            tab: 'combat',
            label: bonusT('bonusCollectionHp'),
            decimals: 1,
            sources: [{ label: bonusT('sourceCollection'), value: (coll.max_hp_mult || 0) * 100 }],
            total: (coll.max_hp_mult || 0) * 100,
            impactKey: 'impactTeamHp',
            impactBase: teamSums.hp,
        },
        hpSynergy: {
            tab: 'combat',
            label: bonusT('bonusSynergyHp'),
            decimals: 1,
            sources: [
                {
                    label: bonusT('sourceSynergy'),
                    value: synergyMultDelta(syn, 'max_hp_mult') * 100,
                },
            ],
            total: synergyMultDelta(syn, 'max_hp_mult') * 100,
            impactKey: 'impactTeamHp',
            impactBase: teamSums.hp,
        },
        attack: {
            tab: 'combat',
            label: bonusT('bonusAttack'),
            decimals: 1,
            sources: [
                { label: bonusT('sourceCollection'), value: (coll.attack_mult || 0) * 100 },
                {
                    label: bonusT('sourceSynergy'),
                    value: synergyMultDelta(syn, 'attack_mult') * 100,
                },
            ],
            total:
                ((coll.attack_mult || 0) + synergyMultDelta(syn, 'attack_mult')) * 100,
            impactKey: 'impactTeamAtk',
            impactBase: teamSums.attack,
        },
        spattack: {
            tab: 'combat',
            label: bonusT('bonusSpAttack'),
            decimals: 1,
            sources: [
                { label: bonusT('sourceCollection'), value: (coll.spattack_mult || 0) * 100 },
                {
                    label: bonusT('sourceSynergy'),
                    value: synergyMultDelta(syn, 'spattack_mult') * 100,
                },
            ],
            total:
                ((coll.spattack_mult || 0) + synergyMultDelta(syn, 'spattack_mult')) * 100,
            impactKey: 'impactTeamSpAtk',
            impactBase: teamSums.spattack,
        },
        speed: {
            tab: 'combat',
            label: bonusT('bonusSpeed'),
            decimals: 1,
            sources: [
                { label: bonusT('sourceCollection'), value: (coll.speed_mult || 0) * 100 },
                {
                    label: bonusT('sourceSynergy'),
                    value: synergyMultDelta(syn, 'speed_mult') * 100,
                },
            ],
            total: ((coll.speed_mult || 0) + synergyMultDelta(syn, 'speed_mult')) * 100,
            impactKey: 'impactTeamSpeed',
            impactBase: teamSums.speed,
        },
        damage: {
            tab: 'combat',
            label: bonusT('bonusDamage'),
            decimals: 0,
            sources: [
                { label: bonusT('sourceTalent'), value: tal('damage_mult') * 100 },
                { label: bonusT('sourceCollection'), value: (coll.damage_mult || 0) * 100 },
                { label: bonusT('sourceMastery'), value: mast('damage_mult') * 100 },
            ],
            total: (tal('damage_mult') + (coll.damage_mult || 0) + mast('damage_mult')) * 100,
            impactKey: 'impactTeamAtk',
            impactBase: teamSums.attack,
        },
        defense: {
            tab: 'combat',
            label: bonusT('bonusDefense'),
            decimals: 1,
            sources: [
                { label: bonusT('sourceCollection'), value: (coll.defense_mult || 0) * 100 },
                {
                    label: bonusT('sourceSynergy'),
                    value: synergyMultDelta(syn, 'defense_mult') * 100,
                },
            ],
            total:
                ((coll.defense_mult || 0) + synergyMultDelta(syn, 'defense_mult')) * 100,
            impactKey: 'impactTeamDef',
            impactBase: teamSums.defense,
        },
        crit: {
            tab: 'combat',
            label: bonusT('bonusCrit'),
            decimals: 0,
            formulaType: 'flat',
            sources: [
                { label: bonusT('sourceTalent'), value: tal('crit_chance') * 100 },
                { label: bonusT('sourceCollection'), value: (coll.crit_chance || 0) * 100 },
                { label: bonusT('sourceMastery'), value: mast('crit_chance') * 100 },
            ],
            total: (tal('crit_chance') + (coll.crit_chance || 0) + mast('crit_chance')) * 100,
        },
        critDamage: {
            tab: 'combat',
            label: bonusT('bonusCritDamage'),
            decimals: 0,
            sources: [
                { label: bonusT('sourceTalent'), value: tal('crit_damage_mult') * 100 },
                { label: bonusT('sourceCollection'), value: (coll.crit_damage_mult || 0) * 100 },
                { label: bonusT('sourceMastery'), value: mast('crit_damage_mult') * 100 },
            ],
            total:
                (tal('crit_damage_mult') +
                    (coll.crit_damage_mult || 0) +
                    mast('crit_damage_mult')) *
                100,
        },
        capture: {
            tab: 'combat',
            label: bonusT('radarCapture') || 'Capture',
            decimals: 1,
            formulaType: 'flat',
            sources: [
                { label: bonusT('sourceTalent'), value: tal('capture_chance') * 100 },
                { label: bonusT('sourceMastery'), value: mast('capture_chance') * 100 },
            ],
            total: (tal('capture_chance') + mast('capture_chance')) * 100,
        },
        lifesteal: {
            tab: 'support',
            label: bonusT('bonusLifesteal'),
            decimals: 1,
            sources: [{ label: bonusT('sourceCollection'), value: (coll.life_steal || 0) * 100 }],
            total: (coll.life_steal || 0) * 100,
        },
        regen: {
            tab: 'support',
            label: bonusT('bonusRegen'),
            decimals: 1,
            sources: [
                { label: bonusT('sourceCollection'), value: (coll.hp_regen_per_turn || 0) * 100 },
            ],
            total: (coll.hp_regen_per_turn || 0) * 100,
            impactKey: 'impactTeamRegen',
            impactBase: teamSums.hp,
        },
        money: {
            tab: 'economy',
            label: bonusT('bonusMoney'),
            decimals: 0,
            sources: [
                { label: bonusT('sourceTalent'), value: tal('pokedollars_mult') * 100 },
                { label: bonusT('sourceCollection'), value: (coll.gold_mult || 0) * 100 },
                { label: bonusT('sourceMastery'), value: mast('pokedollars_mult') * 100 },
                { label: bonusT('sourceSynergy'), value: (syn.pokedollars_mult || 0) * 100 },
            ],
            total:
                (tal('pokedollars_mult') +
                    (coll.gold_mult || 0) +
                    mast('pokedollars_mult') +
                    (syn.pokedollars_mult || 0)) *
                100,
        },
    };

    const expBoostUpgPct =
        ((game.upgrades?.expBoost ? game.upgrades.expBoost.level : 0) * 0.1) * 100;
    const expActiveBoostPct =
        (typeof game.getActiveBoostMultiplier === 'function'
            ? game.getActiveBoostMultiplier('xp') || 0
            : 0) * 100;
    const expPermaPct = ((game.permanentBoosts?.xp) || 0) * 100;
    const expTalentPct = tal('exp_mult') * 100;
    const expSynPct = synergyMultDelta(syn, 'exp_mult') * 100;
    const expCollPct = (coll.xp_mult || 0) * 100;
    const expMentorPct =
        (typeof game.getTalentStackBonus === 'function'
            ? game.getTalentStackBonus('mentor') || 0
            : 0) * 100;
    bonuses.xpMult = {
        tab: 'combat',
        label: bonusT('bonusXp'),
        decimals: 0,
        sources: [
            { label: bonusT('xpSourceUpgrade'), value: expBoostUpgPct },
            { label: bonusT('xpSourceTempBoost'), value: expActiveBoostPct },
            { label: bonusT('xpSourcePermanent'), value: expPermaPct },
            { label: bonusT('sourceTalent'), value: expTalentPct },
            { label: bonusT('sourceSynergy'), value: expSynPct },
            { label: bonusT('sourceCollection'), value: expCollPct },
            { label: bonusT('xpSourceMentor'), value: expMentorPct },
        ],
        total:
            expBoostUpgPct +
            expActiveBoostPct +
            expPermaPct +
            expTalentPct +
            expSynPct +
            expCollPct +
            expMentorPct,
    };

    const dustMultPct = mast('dust_mult') * 100;
    const dustRecyclePct = mast('recycle_efficiency') * 100;
    bonuses.essenceDust = {
        tab: 'economy',
        label: bonusT('bonusEssenceDust'),
        decimals: 0,
        sources: [
            { label: bonusT('dustSourceMastery'), value: dustMultPct },
            { label: bonusT('dustSourceRecycle'), value: dustRecyclePct },
        ],
        total: dustMultPct + dustRecyclePct,
    };

    const shinyBoostPct =
        (typeof game.getActiveBoostMultiplier === 'function'
            ? game.getActiveBoostMultiplier('shiny') || 0
            : 0) * 100;
    const eggBoostPct =
        (typeof game.getActiveBoostMultiplier === 'function'
            ? game.getActiveBoostMultiplier('egg') || 0
            : 0) * 100;
    if (shinyBoostPct > 0) {
        bonuses.tempShiny = {
            tab: 'economy',
            label: bonusT('tempBoostShiny'),
            decimals: 0,
            formulaType: 'flat',
            sources: [{ label: bonusT('xpSourceTempBoost'), value: shinyBoostPct }],
            total: shinyBoostPct,
        };
    }
    if (eggBoostPct > 0) {
        bonuses.tempEgg = {
            tab: 'economy',
            label: bonusT('tempBoostEgg'),
            decimals: 0,
            formulaType: 'flat',
            sources: [{ label: bonusT('xpSourceTempBoost'), value: eggBoostPct }],
            total: eggBoostPct,
        };
    }

    const vit = game.activeVitamins || {};
    const vitAll = Number(vit.all) || 0;
    const vitEff = getTotalVitaminEfficiency(game.vitaminEfficiency, game.farmMilkEfficiency);
    const baseContribution = 0.1;
    const towerContribBonus = game.permanentBoosts?.team_contribution || 0;
    const teamContributionRate = baseContribution + towerContribBonus;
    const pensionStatsForVit: Record<string, number> =
        typeof game.calculatePensionStats === 'function'
            ? game.calculatePensionStats() || {}
            : {};
    const passiveBaseFor = (statKey: string) => {
        const teamPart = (Number(game.playerTeamStats?.[statKey]) || 0) * teamContributionRate;
        const penPart = Number(pensionStatsForVit[statKey]) || 0;
        let fetichePart = 0;
        if (game.unlockedFeatures?.fetiche && game.feticheState?.speciesKey) {
            fetichePart = Number(getFeticheStatsForGains(game.feticheState, Date.now())[statKey]) || 0;
        }
        return teamPart + penPart + fetichePart;
    };

    const vitStatList = [
        { key: 'hp', label: bonusT('vitaminHp'), statShort: game.t('storage.sortHp') },
        { key: 'attack', label: bonusT('vitaminAtk'), statShort: game.t('storage.sortAttack') },
        { key: 'spattack', label: bonusT('vitaminSpAtk'), statShort: game.t('storage.sortSpAttack') },
        { key: 'defense', label: bonusT('vitaminDef'), statShort: game.t('storage.sortDefense') },
        { key: 'spdefense', label: bonusT('vitaminSpDef'), statShort: game.t('storage.sortSpDefense') },
        { key: 'speed', label: bonusT('vitaminSpd'), statShort: game.t('storage.sortSpeed') },
    ];

    vitStatList.forEach((s) => {
        const specific = Number((vit as Record<string, number>)[s.key]) || 0;
        const portion = specific + vitAll;
        const totalPct = portion * (1 + vitEff) * 100;
        const sources: BonusSource[] = [
            { label: bonusT('sourceVitaminSpecific'), value: specific * 100 },
            { label: bonusT('sourceVitaminAll'), value: vitAll * 100 },
        ];
        if (vitEff > 0) {
            sources.push({
                label: bonusT('sourceVitaminEfficiency'),
                value: portion * vitEff * 100,
            });
        }
        const rec: BonusRowInfo = {
            tab: 'support',
            label: s.label,
            decimals: 0,
            formulaType: 'flat',
            sources,
            total: totalPct,
        };
        const passiveDelta = passiveBaseFor(s.key) * portion * (1 + vitEff);
        if (passiveDelta > 0.4) {
            rec.impact = bonusT('impactPassiveGain', {
                value: fmtNum(Math.round(passiveDelta)),
                stat: s.statShort,
            });
        }
        bonuses['vitamin_' + s.key] = rec;
    });

    const potionStats = [
        { key: 'hp', label: bonusT('potionHp'), impactKey: 'impactTeamHp', impactBase: teamSums.hp },
        {
            key: 'attack',
            label: bonusT('potionAtk'),
            impactKey: 'impactTeamAtk',
            impactBase: teamSums.attack,
        },
        {
            key: 'spattack',
            label: bonusT('potionSpAtk'),
            impactKey: 'impactTeamSpAtk',
            impactBase: teamSums.spattack,
        },
        {
            key: 'defense',
            label: bonusT('potionDef'),
            impactKey: 'impactTeamDef',
            impactBase: teamSums.defense,
        },
        {
            key: 'speed',
            label: bonusT('potionSpd'),
            impactKey: 'impactTeamSpeed',
            impactBase: teamSums.speed,
        },
    ];
    potionStats.forEach((ps) => {
        const pct = sumActivePotionBoost(game, ps.key) * 100;
        if (pct <= 0) return;
        bonuses['potion_' + ps.key] = {
            tab: 'combat',
            label: ps.label,
            decimals: 0,
            formulaType: 'flat',
            sources: [{ label: bonusT('potionSourceTemp'), value: pct }],
            total: pct,
            impactKey: ps.impactKey,
            impactBase: ps.impactBase,
        };
    });

    return bonuses;
}

export function applyBonusRowImpacts(
    bonuses: Record<string, BonusRowInfo>,
    bonusT: BonusTranslate,
    fmtNum: (n: number) => string,
): void {
    Object.values(bonuses).forEach((b) => {
        if (!b.impactKey || b.impact) return;
        const pct = Number(b.total) || 0;
        const base = Number(b.impactBase) || 0;
        if (pct <= 0 || base <= 0) return;
        const delta = (base * pct) / 100;
        b.impact = bonusT(b.impactKey, { value: fmtNum(Math.round(delta)) });
    });
}

export function countHiddenBonusRows(
    bonuses: Record<string, BonusRowInfo>,
    tab: string,
    showAll: boolean,
    sourceFilter: string,
    sourceLabelByKey: Record<string, string>,
): number {
    if (showAll) return 0;
    let hidden = 0;
    for (const b of Object.values(bonuses)) {
        if (b.tab !== tab) continue;
        if ((Number(b.total) || 0) <= 0) hidden++;
        else if (sourceFilter !== 'all') {
            const filterLabel = sourceLabelByKey[sourceFilter];
            const matched = (b.sources || []).find((s) => s && s.label === filterLabel);
            if (!matched || Math.abs(Number(matched.value) || 0) <= 0.0001) hidden++;
        }
    }
    return hidden;
}

export { buildMoomooMilkBonusSnapshot, sumVitaminsConsumed, RARITY, RARITY_CHANCES };
