export interface WeeklyChallengeTemplate {
    id: string;
    trackingKey: string;
    titleKey: string;
    descKey: string;
    baseTarget: number;
    difficulty: WeeklyChallengeDifficulty;
    rewardProfile: WeeklyRewardProfile;
    /** Extra multiplier on scaled currency rewards (pokedollars, tokens, marks, dust). */
    scaledRewardMult?: number;
    minBadges?: number;
    requiresFeature?: 'expeditionsTab' | 'towerTab' | 'miltankFarm';
    /** Increment per matching event (default 1). */
    increment?: number;
    /** If set, any listed event advances this challenge (otherwise trackingKey only). */
    trackingKeys?: string[];
}

