function scaleRewardField(base: number, effortMult: number, weight: number, roundFn: (n: number) => number): number {
    const n = base * effortMult * weight;
    return roundFn(n);
}

export function buildDifficultyBaseRewards(difficulty: WeeklyChallengeDifficulty): DifficultyBaseRewards {
    return { ...DIFFICULTY_BASE_REWARDS[difficulty] };
}

export function resolveWeeklyBonusRewards(tpl: WeeklyChallengeTemplate): WeeklyChallengeRewards {
    const byDiff = WEEKLY_BONUS_REWARDS[tpl.id];
    if (!byDiff) return {};
    const bonus = byDiff[tpl.difficulty];
    if (!bonus) return {};
    return {
        ...bonus,
        eggs: bonus.eggs ? { ...bonus.eggs } : undefined,
        items: bonus.items ? { ...bonus.items } : undefined,
    };
}

function mergeWeeklyChallengeRewards(
    scaled: WeeklyChallengeRewards,
    bonus: WeeklyChallengeRewards,
): WeeklyChallengeRewards {
    const merged: WeeklyChallengeRewards = { ...scaled };
    if (bonus.combatTickets) {
        merged.combatTickets = (merged.combatTickets || 0) + bonus.combatTickets;
    }
    if (bonus.talentRerolls) {
        merged.talentRerolls = (merged.talentRerolls || 0) + bonus.talentRerolls;
    }
    if (bonus.eggs) {
        merged.eggs = { ...(merged.eggs || {}) };
        for (const [rarity, count] of Object.entries(bonus.eggs)) {
            const key = rarity as keyof NonNullable<WeeklyChallengeRewards['eggs']>;
            const qty = Math.max(0, Math.floor(Number(count) || 0));
            if (qty > 0) {
                merged.eggs[key] = (merged.eggs[key] || 0) + qty;
            }
        }
    }
    if (bonus.items) {
        merged.items = { ...(merged.items || {}) };
        for (const [itemKey, count] of Object.entries(bonus.items)) {
            if (!isWeeklyBonusItemKey(itemKey)) continue;
            const qty = Math.max(0, Math.floor(Number(count) || 0));
            if (qty > 0) {
                merged.items[itemKey] = (merged.items[itemKey] || 0) + qty;
            }
        }
    }
    return merged;
}

export function buildWeeklyChallengeRewards(
    tpl: WeeklyChallengeTemplate,
    scaledTarget: number,
): WeeklyChallengeRewards {
    const base = buildDifficultyBaseRewards(tpl.difficulty);
    const effortMult = Math.max(1, scaledTarget / Math.max(1, tpl.baseTarget));
    const weights = WEEKLY_REWARD_PROFILES[tpl.rewardProfile] ?? NEUTRAL_REWARD_WEIGHTS;
    const scaledMult = Math.max(1, Number(tpl.scaledRewardMult) || 1);

    const scaled: WeeklyChallengeRewards = {
        pokedollars: scaleRewardField(
            base.pokedollars,
            effortMult * scaledMult,
            weights.pokedollars ?? 1,
            Math.round,
        ),
        questTokens: Math.max(
            1,
            scaleRewardField(base.questTokens, effortMult * scaledMult, weights.questTokens ?? 1, Math.round),
        ),
        triumphMarks: scaleRewardField(
            base.triumphMarks,
            effortMult * scaledMult,
            weights.triumphMarks ?? 1,
            Math.round,
        ),
        essenceDust: scaleRewardField(
            base.essenceDust,
            effortMult * scaledMult,
            weights.essenceDust ?? 1,
            Math.round,
        ),
    };

    if (scaled.triumphMarks === 0) delete scaled.triumphMarks;

    const bonus = resolveWeeklyBonusRewards(tpl);
    return mergeWeeklyChallengeRewards(scaled, bonus);
}

export function scaleWeeklyTarget(
    baseTarget: number,
    badgesCount: number,
    prestigeCount = 0,
): number {
    const badges = Math.max(0, Math.floor(Number(badgesCount) || 0));
    const prestige = Math.max(0, Math.floor(Number(prestigeCount) || 0));
    const mult = 1 + badges * 0.22 + Math.min(prestige, 50) * 0.04;
    return Math.max(1, Math.round(baseTarget * mult));
}

export function scaleWeeklyDamageTarget(
    baseTarget: number,
    badgesCount: number,
    prestigeCount = 0,
): number {
    const badges = Math.max(0, Math.floor(Number(badgesCount) || 0));
    const prestige = Math.max(0, Math.floor(Number(prestigeCount) || 0));
    const mult = 1 + badges * 0.12 + Math.min(prestige, 50) * 0.02;
    return Math.max(1, Math.round(baseTarget * mult));
}

/** Deterministic PRNG from seed (mulberry32). */
export function mulberry32(seed: number): () => number {
    let s = seed >>> 0;
    return () => {
        s += 0x6D2B79F5;
        let t = s;
        t = Math.imul(t ^ (t >>> 15), t | 1);
        t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
}

export function hashWeekSeed(weekKey: string, salt = 0): number {
    let h = salt;
    for (let i = 0; i < weekKey.length; i++) {
        h = Math.imul(31, h) + weekKey.charCodeAt(i);
        h |= 0;
    }
    return h >>> 0;
}
