/**
 * Per-mission expedition mastery: XP bank, manual active level, difficulty/reward scaling.
 */

import {
    BIOME_MASTERY_MAX_LEVEL,
    BIOME_MASTERY_LEVELS,
    EXPEDITION_MISSION_MASTERY_LEVELS,
    EXPEDITION_MISSION_MASTERY_MAX_LEVEL,
} from '../../constants/balance/expeditions.ts';

export interface ExpeditionMissionMasteryEntry {
    xp: number;
    activeLevel: number;
}

export type ExpeditionMissionMasteryStore = Record<string, ExpeditionMissionMasteryEntry>;

export interface MissionMasteryLevelRow {
    xpRequired: number;
    difficultyMult: number;
    rewardMult: number;
    rateMult: number;
}

export interface MissionMasteryMultipliers {
    difficultyMult: number;
    rewardMult: number;
    rateMult: number;
}

export interface MissionMasteryTooltipContent {
    title: string;
    descriptionHtml: string;
}

export interface MissionMasteryXpProgress {
    currentXp: number;
    prevXp: number;
    nextXp: number | null;
    percent: number;
    isMax: boolean;
}

export function getMissionMasteryXpProgress(xp: number): MissionMasteryXpProgress {
    const currentXp = Math.max(0, Math.floor(Number(xp) || 0));
    const maxUnlocked = getMissionMaxUnlockedLevel(currentXp);
    const prevXp = MISSION_LEVELS[maxUnlocked]?.xpRequired ?? 0;
    if (maxUnlocked >= EXPEDITION_MISSION_MASTERY_MAX_LEVEL) {
        return { currentXp, prevXp, nextXp: null, percent: 100, isMax: true };
    }
    const nextXp = MISSION_LEVELS[maxUnlocked + 1]?.xpRequired ?? prevXp;
    const span = Math.max(1, nextXp - prevXp);
    const percent = Math.min(100, Math.max(0, ((currentXp - prevXp) / span) * 100));
    return { currentXp, prevXp, nextXp, percent, isMax: false };
}

function escapeTooltipHtml(value: string): string {
    return value
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;');
}

const MISSION_LEVELS = EXPEDITION_MISSION_MASTERY_LEVELS as Record<number, MissionMasteryLevelRow>;
const BIOME_LEVELS = BIOME_MASTERY_LEVELS as Record<number, { xpRequired: number; bonus: number; desc?: string }>;

export function createDefaultMissionMasteryEntry(): ExpeditionMissionMasteryEntry {
    return { xp: 0, activeLevel: 1 };
}

export function getMissionMasteryEntry(
    store: ExpeditionMissionMasteryStore | null | undefined,
    defId: string,
): ExpeditionMissionMasteryEntry {
    const raw = store?.[defId];
    if (!raw || typeof raw !== 'object') return createDefaultMissionMasteryEntry();
    const xp = Math.max(0, Math.floor(Number(raw.xp) || 0));
    const maxUnlocked = getMissionMaxUnlockedLevel(xp);
    const activeLevel = clampMissionActiveLevel(xp, Number(raw.activeLevel) || 1);
    return { xp, activeLevel: Math.min(activeLevel, maxUnlocked) };
}

export function getMissionMaxUnlockedLevel(xp: number): number {
    const safeXp = Math.max(0, Math.floor(Number(xp) || 0));
    let level = 1;
    for (let lvl = 1; lvl <= EXPEDITION_MISSION_MASTERY_MAX_LEVEL; lvl++) {
        const row = MISSION_LEVELS[lvl];
        if (row && safeXp >= row.xpRequired) level = lvl;
    }
    return level;
}

export function clampMissionActiveLevel(xp: number, activeLevel: number): number {
    const maxUnlocked = getMissionMaxUnlockedLevel(xp);
    const lvl = Math.floor(Number(activeLevel) || 1);
    return Math.max(1, Math.min(maxUnlocked, lvl));
}

export function getMissionMasteryMultipliers(level: number): MissionMasteryMultipliers {
    const lvl = Math.max(1, Math.min(EXPEDITION_MISSION_MASTERY_MAX_LEVEL, Math.floor(Number(level) || 1)));
    const row = MISSION_LEVELS[lvl] ?? MISSION_LEVELS[1];
    return {
        difficultyMult: row?.difficultyMult ?? 1,
        rewardMult: row?.rewardMult ?? 1,
        rateMult: row?.rateMult ?? 1,
    };
}

export function getEffectiveExpeditionDifficulty(baseDifficulty: number, missionLevel: number): number {
    const base = Math.max(1, Math.floor(Number(baseDifficulty) || 100));
    const mult = getMissionMasteryMultipliers(missionLevel).difficultyMult;
    return Math.max(1, Math.floor(base * mult));
}

export interface ExpeditionLootPoolInput {
    pokedollars?: { min: number; max: number };
    tokens?: { min: number; max: number; chance: number };
    shards?: { amount: number; chance: number };
    eggs?: Record<string, { amount: number; chance: number }>;
    items?: Record<string, { amount: number; chance: number }>;
}

export interface ScaledExpeditionLootPreview {
    pokedollars?: { min: number; max: number };
    tokens?: { min: number; max: number; chance: number };
    shards?: { amount: number; chance: number };
    eggs?: Record<string, { amount: number; chance: number }>;
    items?: Record<string, { amount: number; chance: number }>;
}

function scaleLootChance(baseChance: number, rateMult: number): number {
    return Math.min(1, (Number(baseChance) || 0) * rateMult);
}

/** Preview loot values scaled by mission mastery (matches calculateExpeditionRewardsLogic base scaling). */
export function getScaledExpeditionLootPreview(
    pool: ExpeditionLootPoolInput | null | undefined,
    missionLevel: number,
): ScaledExpeditionLootPreview {
    if (!pool || typeof pool !== 'object') return {};
    const { rewardMult, rateMult } = getMissionMasteryMultipliers(missionLevel);
    const preview: ScaledExpeditionLootPreview = {};

    if (pool.pokedollars) {
        preview.pokedollars = {
            min: Math.floor(pool.pokedollars.min * rewardMult),
            max: Math.floor(pool.pokedollars.max * rewardMult),
        };
    }
    if (pool.tokens) {
        preview.tokens = {
            min: Math.floor(pool.tokens.min * rewardMult),
            max: Math.floor(pool.tokens.max * rewardMult),
            chance: scaleLootChance(pool.tokens.chance, rateMult),
        };
    }
    if (pool.shards) {
        preview.shards = {
            amount: Math.max(1, Math.floor(pool.shards.amount * rewardMult)),
            chance: scaleLootChance(pool.shards.chance, rateMult),
        };
    }
    if (pool.eggs) {
        preview.eggs = {};
        for (const [rarity, eggInfo] of Object.entries(pool.eggs)) {
            preview.eggs[rarity] = {
                amount: eggInfo.amount,
                chance: scaleLootChance(eggInfo.chance, rateMult),
            };
        }
    }
    if (pool.items) {
        preview.items = {};
        for (const [itemKey, itemInfo] of Object.entries(pool.items)) {
            preview.items[itemKey] = {
                amount: itemInfo.amount,
                chance: scaleLootChance(itemInfo.chance, rateMult),
            };
        }
    }
    return preview;
}

export function getMissionNextLevelXp(xp: number): number | null {
    const maxUnlocked = getMissionMaxUnlockedLevel(xp);
    if (maxUnlocked >= EXPEDITION_MISSION_MASTERY_MAX_LEVEL) return null;
    const next = MISSION_LEVELS[maxUnlocked + 1];
    return next?.xpRequired ?? null;
}

export function computePerformanceXpGain(performance: string): number {
    if (performance === 'CRITICAL') return 3;
    if (performance === 'FAILURE') return 1;
    return 2;
}

export function applyMasteryXpMultiplier(baseGain: number, xpMult: number): number {
    const mult = Math.max(0, Number(xpMult) || 0);
    return Math.max(1, Math.ceil(baseGain * (1 + mult)));
}

export function getBiomeMasteryLevelFromXp(xp: number): number {
    const safeXp = Math.max(0, Math.floor(Number(xp) || 0));
    let level = 1;
    for (let lvl = 1; lvl <= BIOME_MASTERY_MAX_LEVEL; lvl++) {
        const row = BIOME_LEVELS[lvl];
        if (row && safeXp >= row.xpRequired) level = lvl;
    }
    return level;
}

export function getBiomeMasteryTimeBonus(xp: number): number {
    const level = getBiomeMasteryLevelFromXp(xp);
    return BIOME_LEVELS[level]?.bonus ?? 0;
}

export interface SetMissionActiveLevelResult {
    ok: boolean;
    entry: ExpeditionMissionMasteryEntry;
    errorKey?: string;
}

export function setMissionActiveLevel(
    store: ExpeditionMissionMasteryStore,
    defId: string,
    targetLevel: number,
): SetMissionActiveLevelResult {
    if (!store[defId]) store[defId] = createDefaultMissionMasteryEntry();
    const entry = getMissionMasteryEntry(store, defId);
    const maxUnlocked = getMissionMaxUnlockedLevel(entry.xp);
    const lvl = Math.floor(Number(targetLevel) || 1);
    if (lvl < 1 || lvl > maxUnlocked) {
        return { ok: false, entry, errorKey: 'expedition.missionMasteryLevelInvalid' };
    }
    store[defId] = { xp: entry.xp, activeLevel: lvl };
    return { ok: true, entry: store[defId] };
}

export function adjustMissionActiveLevel(
    store: ExpeditionMissionMasteryStore,
    defId: string,
    delta: number,
): SetMissionActiveLevelResult {
    const entry = getMissionMasteryEntry(store, defId);
    return setMissionActiveLevel(store, defId, entry.activeLevel + delta);
}

export function grantMissionMasteryXp(
    store: ExpeditionMissionMasteryStore,
    defId: string,
    performance: string,
    xpMult = 0,
): ExpeditionMissionMasteryEntry {
    if (!store[defId]) store[defId] = createDefaultMissionMasteryEntry();
    const entry = getMissionMasteryEntry(store, defId);
    const gain = applyMasteryXpMultiplier(computePerformanceXpGain(performance), xpMult);
    const xp = entry.xp + gain;
    const activeLevel = clampMissionActiveLevel(xp, entry.activeLevel);
    store[defId] = { xp, activeLevel };
    return store[defId];
}

export type MissionMasteryTranslate = (key: string, params?: Record<string, string | number>) => string;

export function buildMissionMasteryTooltip(
    t: MissionMasteryTranslate,
    missionName: string,
    entry: ExpeditionMissionMasteryEntry,
): MissionMasteryTooltipContent {
    const maxUnlocked = getMissionMaxUnlockedLevel(entry.xp);
    const mults = getMissionMasteryMultipliers(entry.activeLevel);
    const diffPct = Math.round((mults.difficultyMult - 1) * 100);
    const rewardPct = Math.round((mults.rewardMult - 1) * 100);
    const ratePct = Math.round((mults.rateMult - 1) * 100);
    const progress = getMissionMasteryXpProgress(entry.xp);

    const title = t('expedition.missionMasteryTooltipTitle', { name: missionName });
    const levelLine = t('expedition.missionMasteryTooltipLevel', {
        active: entry.activeLevel,
        maxUnlocked,
        cap: EXPEDITION_MISSION_MASTERY_MAX_LEVEL,
    });
    const xpLabel = progress.isMax
        ? t('expedition.missionMasteryTooltipXpMax', { xp: progress.currentXp })
        : t('expedition.missionMasteryTooltipXpProgress', {
            current: progress.currentXp,
            next: progress.nextXp ?? progress.currentXp,
        });
    const xpGainLine = t('expedition.missionMasteryTooltipXpGain');
    const effectsLine = t('expedition.missionMasteryTooltipEffects', {
        diff: diffPct,
        reward: rewardPct,
        rate: ratePct,
    });
    const hintLine = t('expedition.missionMasteryTooltipHint');

    const descriptionHtml = `
        <div class="mission-mastery-tooltip">
            <div class="mission-mastery-tooltip-level">${escapeTooltipHtml(levelLine)}</div>
            <div class="mission-mastery-tooltip-xp-row">
                <span class="mission-mastery-tooltip-xp-label">${escapeTooltipHtml(xpLabel)}</span>
                ${progress.isMax
                    ? `<span class="mission-mastery-tooltip-xp-badge">${escapeTooltipHtml(t('expeditions.masteryMax'))}</span>`
                    : ''}
            </div>
            <div class="mission-mastery-tooltip-progress-track" role="progressbar"
                 aria-valuemin="0"
                 aria-valuemax="100"
                 aria-valuenow="${Math.round(progress.percent)}">
                <div class="mission-mastery-tooltip-progress-fill" style="width: ${progress.percent.toFixed(1)}%;"></div>
            </div>
            <div class="mission-mastery-tooltip-detail">${escapeTooltipHtml(xpGainLine)}</div>
            <div class="mission-mastery-tooltip-detail mission-mastery-tooltip-effects">${escapeTooltipHtml(effectsLine)}</div>
            <div class="mission-mastery-tooltip-hint">${escapeTooltipHtml(hintLine)}</div>
        </div>
    `;

    return { title, descriptionHtml };
}

export function buildMissionMasteryControlsHtml(
    t: MissionMasteryTranslate,
    defId: string,
    expeditionUid: string | number,
    entry: ExpeditionMissionMasteryEntry,
): string {
    const maxUnlocked = getMissionMaxUnlockedLevel(entry.xp);
    const minusDisabled = entry.activeLevel <= 1;
    const plusDisabled = entry.activeLevel >= maxUnlocked;
    const levelLabel = t('expedition.missionMasteryLevelShort', { level: entry.activeLevel });
    const escape = (s: string) => s
        .replace(/&/g, '&amp;')
        .replace(/"/g, '&quot;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;');

    return `
        <div class="expedition-header-actions">
            <div class="expedition-mission-mastery-controls"
                 data-tooltip-placement="left"
                 data-expedition-def-id="${escape(defId)}">
                <button type="button"
                        class="expedition-mission-mastery-btn"
                        data-action="adjustExpeditionMissionLevel"
                        data-arg="${escape(defId)}"
                        data-arg2="-1"
                        ${minusDisabled ? 'disabled' : ''}
                        aria-label="${escape(t('expedition.missionMasteryDecrease'))}">−</button>
                <span class="expedition-mission-mastery-level">${levelLabel}</span>
                <button type="button"
                        class="expedition-mission-mastery-btn"
                        data-action="adjustExpeditionMissionLevel"
                        data-arg="${escape(defId)}"
                        data-arg2="1"
                        ${plusDisabled ? 'disabled' : ''}
                        aria-label="${escape(t('expedition.missionMasteryIncrease'))}">+</button>
            </div>
            <button type="button"
                    class="stats-close expedition-delete-btn"
                    data-action="confirmDeleteAvailableExpedition" data-arg="${escape(String(expeditionUid))}">
                ×
            </button>
        </div>
    `;
}
