<script lang="ts">
  import type { RecyclerShardSnapshot } from '../../bus/snapshots.js';
  import { uiText } from '../../ui/i18n.ts';
  import { game } from '../../../gameManager.js';
  import { facade } from '../../bus/gameFacade.js';
  import { portalToBody } from '../../lib/portalToBody.js';
  import { formatNumber } from '../../../formatters.ts';

  const DUST_IMG = 'img/essence-dust.png';

  interface Props {
    entry: RecyclerShardSnapshot;
    anchorRect: DOMRect;
    open?: boolean;
    onClose: () => void;
  }

  let { entry, anchorRect, open = true, onClose }: Props = $props();

  let popoverEl: HTMLDivElement | undefined = $state();
  let qty = $state(1);
  let boundShardKey = $state('');

  let qtyTitle = $derived(uiText('shop.recyclerQtyTitle', 'Quantity to recycle', {}, game));
  let recycleLabel = $derived(uiText('shop.recyclerRecycle', 'Recycle', {}, game));
  let colStat = $derived(uiText('tooltip.tableStat', 'Stat', {}, game));
  let colValue = $derived(uiText('tooltip.tableValue', 'Value', {}, game));
  let colDust = $derived(uiText('shop.essenceDustLabel', 'Essence dust', {}, game));
  let rowStock = $derived(uiText('shop.recyclerSortCount', 'Quantity', {}, game));
  let lockTitle = $derived(
    entry.isProtected
      ? uiText('shop.recyclerUnprotect', 'Déprotéger', {}, game)
      : uiText('shop.recyclerProtect', 'Protéger', {}, game)
  );

  let previewDust = $derived(Math.floor(qty * entry.dustPerUnit));
  let previewDustFormatted = $derived(formatNumber(previewDust));

  const POPOVER_WIDTH = 280;
  const POPOVER_GAP = 8;

  /** Ne réinitialiser la qty qu’au changement de famille (pas à chaque refresh snapshot). */
  $effect(() => {
    const key = entry.shardKey;
    const max = entry.count;
    if (key !== boundShardKey) {
      boundShardKey = key;
      qty = max;
    } else if (qty > max) {
      qty = Math.max(1, max);
    }
  });

  function clampQty(raw: number): number {
    if (!Number.isFinite(raw)) return 1;
    return Math.max(1, Math.min(entry.count, Math.floor(raw)));
  }

  function onQtyInput(e: Event): void {
    const el = e.currentTarget as HTMLInputElement;
    qty = clampQty(parseInt(el.value, 10));
    el.value = String(qty);
  }

  function positionPopover(node: HTMLDivElement, rect: DOMRect) {
    const height = node.offsetHeight || 200;
    let left = rect.left + rect.width / 2 - POPOVER_WIDTH / 2;
    let top = rect.bottom + POPOVER_GAP;
    if (left + POPOVER_WIDTH > window.innerWidth - 8) {
      left = window.innerWidth - POPOVER_WIDTH - 8;
    }
    if (left < 8) left = 8;
    if (top + height > window.innerHeight - 8) {
      top = rect.top - height - POPOVER_GAP;
    }
    if (top < 8) top = 8;
    node.style.left = `${left}px`;
    node.style.top = `${top}px`;
    node.style.width = `${POPOVER_WIDTH}px`;
  }

  $effect(() => {
    if (!open) return;
    const rect = anchorRect;
    const node = popoverEl;
    if (!node || !rect) return;
    positionPopover(node, rect);
    const onResize = () => positionPopover(node, rect);
    window.addEventListener('resize', onResize);
    return () => window.removeEventListener('resize', onResize);
  });

  $effect(() => {
    if (!open) return;
    qty;
    const node = popoverEl;
    const rect = anchorRect;
    if (!node || !rect) return;
    requestAnimationFrame(() => positionPopover(node, rect));
  });

  $effect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  });
</script>

{#if open}
  <div class="recycler-shard-portal" use:portalToBody>
    <!-- svelte-ignore a11y_no_static_element_interactions -->
    <div
      class="recycler-shard-overlay"
      role="presentation"
      onpointerdown={(e) => {
        e.preventDefault();
        onClose();
      }}
    ></div>

    <div
      class="pension-contribution-popover is-dark recycler-shard-popover show"
      bind:this={popoverEl}
      role="dialog"
      tabindex="-1"
      aria-label={entry.displayName}
      onpointerdown={(e) => e.stopPropagation()}
      onkeydown={(e) => e.stopPropagation()}
    >
      <div id="recyclerShardPopoverContent" class="recycler-shard-popover-content">
        <div class="recycler-shard-popover-title-row">
          <div class="recycler-shard-popover-title">
            {entry.displayName}
          </div>
          <button type="button" class="recycler-shard-popover-close" onclick={onClose} aria-label="Close">×</button>
        </div>

        <table class="recycler-shard-popover-table">
          <thead>
            <tr>
              <th>{colStat}</th>
              <th>{colValue}</th>
              <th>{colDust}</th>
            </tr>
          </thead>
          <tbody>
            <tr class="recycler-shard-popover-row-last">
              <td>{rowStock}</td>
              <td class="recycler-shard-popover-td-value">x{formatNumber(qty)}</td>
              <td class="recycler-shard-popover-td-accent">
                <img src={DUST_IMG} class="essence-dust-inline" alt="">
                {previewDustFormatted}
              </td>
            </tr>
          </tbody>
        </table>

        <div class="recycler-shard-popover-line">{qtyTitle}</div>

        {#if entry.isProtected}
          <div class="recycler-shard-popover-protected-msg">
            {uiText('shop.recyclerProtected', 'Protégé', {}, game)}
          </div>
        {/if}

        <div class="recycler-item-actions recycler-shard-popover-actions">
          <button
            type="button"
            class="recycler-shard-lock-toggle-btn"
            title={lockTitle}
            data-action="toggleProtectShard"
            data-arg={entry.shardKey}
          >
            {entry.isProtected ? '🔒' : '🔓'} {lockTitle}
          </button>
          <input
            type="number"
            class="recycler-qty-input"
            min="1"
            max={entry.count}
            value={qty}
            inputmode="numeric"
            title={qtyTitle}
            aria-label={qtyTitle}
            oninput={onQtyInput}
            disabled={entry.isProtected}
          >
          <button
            type="button"
            class="recycler-shard-recycle-btn"
            data-action="recycleShards"
            data-arg={entry.shardKey}
            data-arg2={entry.rarity}
            disabled={entry.isProtected}
          >
            {recycleLabel}
          </button>
        </div>
      </div>
    </div>
  </div>
{/if}
