    // UI : Affiche un texte flottant sur un ?l?ment d'interface (Header, Bouton...)

    GameClass.prototype.getPensionSlots = function (this: ThisGame) {
        // 1. Slots achet?s (Am?liorations)
        const upgradeSlots = this.upgrades?.pension?.level ?? 0;

        // 2. Slots permanents (Tour de combat)
        const towerSlots = this.permanentBoosts.pensionSlots || 0;

        // 3. ? FIX : Slots du Badge Parmanie
        const badgeSlots = this.getAccountTalentBonus('pension_slots');

        return upgradeSlots + towerSlots + badgeSlots;
    };

    GameClass.prototype.getPensionTransferRate = function (this: ThisGame) {
        return (this.upgrades?.pension?.level ?? 0) * 0.01;
    };

    GameClass.prototype.getTeamContributionRate = function (this: ThisGame) {
        const baseContribution = 0.10;
        const towerBonus = this.permanentBoosts.team_contribution || 0;
        return baseContribution + towerBonus;
    };

    GameClass.prototype.onMoveDragStart = function (this: ThisGame, event: DragEvent, creatureIndex: number, location: string, moveName: string) {
        if (!event || !event.dataTransfer) return;
        const payload = { creatureIndex, location, moveName };
        event.dataTransfer.effectAllowed = 'move';
        event.dataTransfer.setData('text/plain', JSON.stringify(payload));
    };

    GameClass.prototype.onMoveDragOver = function (this: ThisGame, event: DragEvent) {
        if (!event) return;
        event.preventDefault();
        if (event.dataTransfer) {
            event.dataTransfer.dropEffect = 'move';
        }
    };

    GameClass.prototype.onMoveDrop = function (this: ThisGame, event: DragEvent, creatureIndex: number, location: string, targetMoveName: string) {
        if (!event || !event.dataTransfer) return;
        event.preventDefault();
        let data: MoveDragPayload | null = null;
        try {
            const parsed: unknown = JSON.parse(event.dataTransfer.getData('text/plain') || '{}');
            if (
                parsed &&
                typeof parsed === 'object' &&
                typeof (parsed as MoveDragPayload).location === 'string' &&
                typeof (parsed as MoveDragPayload).moveName === 'string' &&
                Number.isInteger((parsed as MoveDragPayload).creatureIndex)
            ) {
                data = parsed as MoveDragPayload;
            }
        } catch {
            return;
        }
        if (!data || data.location !== location || data.creatureIndex !== creatureIndex) return;

        const sourceMove = resolveMoveName(data.moveName);
        const resolvedTarget = resolveMoveName(targetMoveName);
        let creature = null;
        if (location === 'team') creature = this.playerTeam[creatureIndex];
        else if (location === 'storage') creature = this.storage[creatureIndex];
        else if (location === 'pension') creature = this.pension[creatureIndex];
        if (!creature || !Array.isArray(creature.currentMoves)) return;

        // On ne réordonne que parmi les attaques équipées
        const moves = creature.currentMoves.map((m) => resolveMoveName(m));
        const fromIndex = moves.indexOf(sourceMove);
        const toIndex = moves.indexOf(resolvedTarget);
        if (fromIndex === -1 || toIndex === -1 || fromIndex === toIndex) return;

        moves.splice(fromIndex, 1);
        moves.splice(toIndex, 0, sourceMove);
        creature.currentMoves = moves;

        this.saveGame();
        if (typeof this.checkSpecialQuests === 'function') this.checkSpecialQuests('move_drag');
        this.showCreatureModal(creatureIndex, location);
    };

    /** Touch drag for move reorder (mobile): long press on row then drag (like creature cards). */

    GameClass.prototype._bindMoveTouchDrag = function (this: ThisGame, container: HTMLElement | null) {
        if (!container || !isMobileViewport()) return;
        const longPressMs = getTouchDragLongPressMs();
        const moveCancelPx = getTouchDragMoveCancelPx();
        const rows = container.querySelectorAll('.creature-move-row');
        const game: ThisGame = this;

        function clearMoveDragHighlight(): void {
            container!.querySelectorAll('.creature-move-row.move-drag-over').forEach((el) => {
                el.classList.remove('move-drag-over');
            });
        }

        function findTargetMoveRow(clientX: number, clientY: number, sourceRow: Element): Element | null {
            const stack =
                typeof document.elementsFromPoint === 'function'
                    ? document.elementsFromPoint(clientX, clientY)
                    : (() => {
                          const hit = document.elementFromPoint(clientX, clientY);
                          return hit ? [hit] : [];
                      })();
            for (let si = 0; si < stack.length; si++) {
                const raw = stack[si];
                if (!(raw instanceof Element)) continue;
                if (raw.closest('.touch-drag-ghost')) continue;
                const targetRow = raw.closest('.creature-move-row');
                if (targetRow && container!.contains(targetRow) && targetRow !== sourceRow) {
                    return targetRow;
                }
            }
            return null;
        }

        function updateMoveDragHighlight(clientX: number, clientY: number, sourceRow: Element): void {
            clearMoveDragHighlight();
            const targetRow = findTargetMoveRow(clientX, clientY, sourceRow);
            if (targetRow) targetRow.classList.add('move-drag-over');
        }

        rows.forEach(function (row: Element) {
            let touchId: number | null = null, startX = 0, startY = 0, longPressTimer: ReturnType<typeof setTimeout> | null = null, ghostEl: HTMLElement | null = null;
            function cancelLongPress() {
                if (longPressTimer) { clearTimeout(longPressTimer); longPressTimer = null; }
                document.removeEventListener('touchmove', onCancelMove);
                document.removeEventListener('touchend', onCancelEnd, true);
                document.removeEventListener('touchcancel', onCancelEnd, true);
            }
            function onCancelMove(e: TouchEvent) {
                if (!e.touches.length) return;
                const t = Array.from(e.touches).find(function (x: Touch) { return x.identifier === touchId; });
                if (!t) return;
                if (Math.abs(t.clientX - startX) > moveCancelPx || Math.abs(t.clientY - startY) > moveCancelPx) cancelLongPress();
            }
            function onCancelEnd(e: TouchEvent) {
                if (!e.changedTouches || !e.changedTouches.length) return;
                if (!Array.from(e.changedTouches).find(function (x: Touch) { return x.identifier === touchId; })) return;
                cancelLongPress();
            }
            function startDrag() {
                longPressTimer = null;
                cancelLongPress();
                if (typeof navigator !== 'undefined' && navigator.vibrate) navigator.vibrate(20);
                const creatureIndex = parseInt(row.getAttribute('data-creature-index') ?? '0', 10);
                const location = row.getAttribute('data-location') || '';
                const moveName = (row.getAttribute('data-move-name') || '').replace(/&quot;/g, '"');
                game._touchMovePayload = { creatureIndex: creatureIndex, location: location, moveName: moveName };
                ghostEl = row.cloneNode(true) as HTMLElement;
                ghostEl.classList.add('touch-drag-ghost');
                const rect = row.getBoundingClientRect();
                ghostEl.style.cssText = 'position:fixed; left:' + (rect.left) + 'px; top:' + (rect.top) + 'px; width:' + rect.width + 'px; height:' + rect.height + 'px; pointer-events:none; z-index:9999; opacity:0.9; box-shadow:0 6px 20px rgba(0,0,0,0.3); transition:none;';
                document.body.appendChild(ghostEl);
                document.addEventListener('touchmove', onDragMove, { passive: false });
                document.addEventListener('touchend', onDragEnd, true);
                document.addEventListener('touchcancel', onDragEnd, true);
            }
            function onDragMove(e: TouchEvent) {
                if (!e.touches.length) return;
                const t = Array.from(e.touches).find(function (x: Touch) { return x.identifier === touchId; });
                if (!t) return;
                e.preventDefault();
                if (ghostEl) {
                    ghostEl.style.left = (t.clientX - ghostEl.offsetWidth / 2) + 'px';
                    ghostEl.style.top = (t.clientY - ghostEl.offsetHeight / 2) + 'px';
                }
                updateMoveDragHighlight(t.clientX, t.clientY, row);
            }
            function onDragEnd(e: TouchEvent) {
                if (!e.changedTouches || !e.changedTouches.length) return;
                const t = Array.from(e.changedTouches).find(function (x: Touch) { return x.identifier === touchId; });
                if (!t) return;
                document.removeEventListener('touchmove', onDragMove);
                document.removeEventListener('touchend', onDragEnd, true);
                document.removeEventListener('touchcancel', onDragEnd, true);
                if (ghostEl && ghostEl.parentNode) ghostEl.parentNode.removeChild(ghostEl);
                ghostEl = null;
                const payload = game._touchMovePayload;
                const highlighted = container!.querySelector('.creature-move-row.move-drag-over');
                let targetRow = highlighted && highlighted !== row ? highlighted : findTargetMoveRow(t.clientX, t.clientY, row);
                clearMoveDragHighlight();
                if (payload && targetRow && targetRow !== row) {
                    const ci = targetRow.getAttribute('data-creature-index');
                    const loc = targetRow.getAttribute('data-location');
                    const targetMoveName = (targetRow.getAttribute('data-move-name') || '').replace(/&quot;/g, '"');
                    if (String(ci) === String(payload.creatureIndex) && loc === payload.location) {
                        game.onMoveDrop({ preventDefault: function () {}, dataTransfer: { getData: function () { return JSON.stringify(payload); } } }, parseInt(ci ?? '0', 10), loc ?? '', targetMoveName);
                    }
                }
                game._touchMovePayload = null;
            }
            (row as HTMLElement).addEventListener('touchstart', function (e: TouchEvent) {
                if (e.touches.length !== 1) return;
                const touch0 = e.touches[0];
                if (!touch0) return;
                touchId = touch0.identifier;
                startX = touch0.clientX;
                startY = touch0.clientY;
                longPressTimer = setTimeout(startDrag, longPressMs);
                document.addEventListener('touchmove', onCancelMove, { passive: true });
                document.addEventListener('touchend', onCancelEnd, true);
                document.addEventListener('touchcancel', onCancelEnd, true);
            }, { passive: true });
        });
    }

    // --- SYST?ME DE D?BLOCAGE GLOBAL D'ATTAQUES ---

    GameClass.prototype.getCreatureByLocation = function (this: ThisGame, location: string, creatureIndex: number) {
        if (location === 'team') return arrayAt(this.playerTeam, creatureIndex) ?? null;
        if (location === 'storage') return arrayAt(this.storage, creatureIndex) ?? null;
        if (location === 'pension') return arrayAt(this.pension, creatureIndex) ?? null;
        return null;
    };

    GameClass.prototype.buildContributionPopoverContent = function (
        this: ThisGame,
        creature: CreatureData,
        rate: number,
        titleText: string,
        accentColor: string,
        dark = false,
        scale: { maxima: ContributionStatBlock; totalMax: number } = {
            maxima: { hp: 0, attack: 0, spattack: 0, defense: 0, spdefense: 0, speed: 0 },
            totalMax: 0,
        },
    ) {
        const contribution = computeCreatureContribution(creature, rate);
        const contributedHP = contribution.hp;
        const contributedATK = contribution.attack;
        const contributedSpATK = contribution.spattack;
        const contributedDEF = contribution.defense;
        const contributedSpDEF = contribution.spdefense;
        const contributedSPD = contribution.speed;
        const totalContribution = sumContributionTotal(contribution);
        const { maxima, totalMax } = scale;

        const rowBorderLast = dark ? 'rgba(58, 63, 75, 0.85)' : '#e2e8f0';
        const rowBorder = dark ? 'rgba(58, 63, 75, 0.45)' : '#f1f5f9';
        const titleColor = dark ? '#b8bcc8' : '#94a3b8';
        const headerBorder = dark ? 'rgba(58, 63, 75, 0.85)' : '#e2e8f0';
        const bodyColor = dark ? '#e0e0e0' : '#334155';

        const rows: Array<{
            label: string;
            value: number;
            contribution: number;
            barMax: number;
        }> = [
            { label: this.t('storage.sortHp'), value: creature.maxHp, contribution: contributedHP, barMax: maxima.hp },
            { label: this.t('storage.sortAttack'), value: creature.attack, contribution: contributedATK, barMax: maxima.attack },
            { label: this.t('storage.sortSpAttack'), value: creature.spattack, contribution: contributedSpATK, barMax: maxima.spattack },
            { label: this.t('storage.sortDefense'), value: creature.defense, contribution: contributedDEF, barMax: maxima.defense },
            { label: this.t('storage.sortSpDefense'), value: creature.spdefense, contribution: contributedSpDEF, barMax: maxima.spdefense },
            { label: this.t('storage.sortSpeed'), value: creature.speed, contribution: contributedSPD, barMax: maxima.speed },
        ];
        const rowsHtml = rows.map((row, idx) => `
            <tr style="border-bottom: 1px solid ${idx === rows.length - 1 ? rowBorderLast : rowBorder};">
                <td style="padding: 4px 8px 4px 0;">${row.label}</td>
                <td style="text-align: right;">${row.value}</td>
                <td style="text-align: right; color: ${accentColor}; font-weight: bold; padding-left: 8px;">+${row.contribution}</td>
                <td class="contribution-popover-bar-cell" style="padding: 4px 0 4px 10px; width: 72px;">${formatContributionBarHtml(row.contribution, row.barMax)}</td>
            </tr>
        `).join('');

        return `
            <div style="font-size: 13px; color: ${titleColor}; margin-bottom: 8px;">${titleText}</div>
            <table style="width: 100%; border-collapse: collapse; font-size: 12px;">
                <thead>
                    <tr style="border-bottom: 1px solid ${headerBorder};">
                        <th style="text-align: left; padding: 4px 8px 4px 0; color: ${titleColor};">${this.t('tooltip.tableStat')}</th>
                        <th style="text-align: right; padding: 4px 0; color: ${titleColor};">${this.t('tooltip.tableValue')}</th>
                        <th style="text-align: right; padding: 4px 0 4px 8px; color: ${titleColor};">${this.t('tooltip.tableContribution')}</th>
                        <th style="padding: 4px 0 4px 10px; width: 72px;"></th>
                    </tr>
                </thead>
                <tbody style="color: ${bodyColor};">
                    ${rowsHtml}
                    <tr>
                        <td colspan="2" style="padding: 6px 8px 4px 0; font-weight: bold; border-top: 1px solid ${headerBorder};">${this.t('tooltip.totalContribution')}</td>
                        <td style="text-align: right; padding: 6px 0 4px 8px; color: ${accentColor}; font-weight: bold; border-top: 1px solid ${headerBorder};">+${totalContribution}</td>
                        <td class="contribution-popover-bar-cell" style="padding: 6px 0 4px 10px; border-top: 1px solid ${headerBorder};">${formatContributionBarHtml(totalContribution, totalMax)}</td>
                    </tr>
                </tbody>
            </table>
        `;
    };

    function _positionContributionPopover(popover: HTMLElement, triggerElement: HTMLElement) {
        const rect = triggerElement.getBoundingClientRect();
        const popoverWidth = 360;
        const popoverHeight = 240;
        let left = rect.right + 8;
        let top = rect.top;
        if (left + popoverWidth > window.innerWidth) left = rect.left - popoverWidth - 8;
        if (top + popoverHeight > window.innerHeight) top = window.innerHeight - popoverHeight - 8;
        if (top < 8) top = 8;
        popover.style.left = left + 'px';
        popover.style.top = top + 'px';
    }

    function _applyContributionPopoverTheme(
        popover: HTMLElement,
        dark: boolean,
        theme: 'team' | 'pension' | null,
    ) {
        popover.classList.toggle('is-dark', dark);
        popover.classList.toggle('team-theme', dark && theme === 'team');
        popover.classList.toggle('pension-theme', dark && theme === 'pension');
        if (!dark) popover.classList.remove('is-dark', 'team-theme', 'pension-theme');
    }

    function _clearContributionPopoverTheme(popover: HTMLElement) {
        popover.classList.remove('is-dark', 'team-theme', 'pension-theme');
    }

    GameClass.prototype.showPensionContributionPopover = function (
        this: ThisGame,
        creatureIndex: number,
        triggerElement: HTMLElement,
        options: { dark?: boolean } = {},
    ) {
        if (this._pensionPopoverHideTimeout) {
            clearTimeout(this._pensionPopoverHideTimeout);
            this._pensionPopoverHideTimeout = null;
        }
        const creature = this.pension[creatureIndex];
        if (!creature) return;
        const rate = this.getPensionTransferRate();
        const transferRate = (rate * 100).toFixed(0);
        const content = document.getElementById('pensionContributionContent');
        const popover = document.getElementById('pensionContributionPopover');
        if (!content || !popover) return;

        const dark = !!options.dark;
        const titleText = `${this.getLocalizedPokemonName(creature.name)} - ${this.t('tooltip.daycareContribution', { percent: transferRate })}`;
        const scale = computeAccountContributionTooltipScale(this, rate);
        content.innerHTML = this.buildContributionPopoverContent(creature, rate, titleText, '#ff1493', dark, scale);
        _applyContributionPopoverTheme(popover, dark, dark ? 'pension' : null);

        _positionContributionPopover(popover, triggerElement);
        popover.classList.add('show');

        if (!this._pensionPopoverListenersAttached) {
            popover.addEventListener('mouseenter', () => {
                if (this._pensionPopoverHideTimeout) {
                    clearTimeout(this._pensionPopoverHideTimeout);
                    this._pensionPopoverHideTimeout = null;
                }
            });
            popover.addEventListener('mouseleave', () => this.scheduleHidePensionContributionPopover(0));
            this._pensionPopoverListenersAttached = true;
        }
    };

    GameClass.prototype.scheduleHidePensionContributionPopover = function (this: ThisGame, delayMs: number) {
        if (this._pensionPopoverHideTimeout) clearTimeout(this._pensionPopoverHideTimeout);
        if (delayMs <= 0) {
            const popover = document.getElementById('pensionContributionPopover');
            if (popover) {
                popover.classList.remove('show');
                _clearContributionPopoverTheme(popover);
            }
            return;
        }
        this._pensionPopoverHideTimeout = setTimeout(() => {
            const popover = document.getElementById('pensionContributionPopover');
            if (popover) {
                popover.classList.remove('show');
                _clearContributionPopoverTheme(popover);
            }
            this._pensionPopoverHideTimeout = null;
        }, delayMs);
    };

    GameClass.prototype.showTeamContributionPopover = function (
        this: ThisGame,
        creatureIndex: number,
        triggerElement: HTMLElement,
        options: { dark?: boolean } = {},
    ) {
        if (this._pensionPopoverHideTimeout) {
            clearTimeout(this._pensionPopoverHideTimeout);
            this._pensionPopoverHideTimeout = null;
        }
        const creature = this.playerTeam[creatureIndex];
        if (!creature) return;
        const rate = this.getTeamContributionRate();
        const transferRate = (rate * 100).toFixed(0);
        const content = document.getElementById('pensionContributionContent');
        const popover = document.getElementById('pensionContributionPopover');
        if (!content || !popover) return;

        const dark = !!options.dark;
        const titleText = `${this.getLocalizedPokemonName(creature.name)} - ${this.t('tooltip.teamContribution', { percent: transferRate })}`;
        const scale = computeAccountContributionTooltipScale(this, rate);
        content.innerHTML = this.buildContributionPopoverContent(creature, rate, titleText, '#22c55e', dark, scale);
        _applyContributionPopoverTheme(popover, dark, dark ? 'team' : null);

        _positionContributionPopover(popover, triggerElement);
        popover.classList.add('show');

        if (!this._pensionPopoverListenersAttached) {
            popover.addEventListener('mouseenter', () => {
                if (this._pensionPopoverHideTimeout) {
                    clearTimeout(this._pensionPopoverHideTimeout);
                    this._pensionPopoverHideTimeout = null;
                }
            });
            popover.addEventListener('mouseleave', () => this.scheduleHidePensionContributionPopover(0));
            this._pensionPopoverListenersAttached = true;
        }
    }

    /**
      * Cherche si une cr?ature existe d?j? dans toutes les collections (équipe, stockage, pension)
      * @param {string} nameToFind - Le nom du Pokémon (ex: "Charizard")
      * @param {boolean} isShiny - Le statut Shiny
      * @returns {Creature|null} La cr?ature trouv?e, ou null
      */

    GameClass.prototype.findCreatureByName = function (this: ThisGame, nameToFind: string, isShiny: boolean, isShadow: boolean) {
        const locations = [this.playerTeam, this.storage, this.pension];
        const targetIsShiny = !!isShiny;
        const targetIsShadow = !!isShadow;
        for (const location of locations) {
            const found = location.find(c => c.name === nameToFind && !!c.isShiny === targetIsShiny && !!c.isShadow === targetIsShadow);
            if (found) {
                return found; // Retourne la premi?re cr?ature trouv?e
            }
        }

        const pastureCreatures = this.miltankFarmState?.pastureCreatures;
        if (Array.isArray(pastureCreatures)) {
            const found = pastureCreatures.find((c) =>
                c && matchesCreatureNameVariant(c, nameToFind, targetIsShiny, targetIsShadow));
            if (found) return found;
        }

        const ultimate = this.ultimateSlot;
        if (
            ultimate
            && matchesCreatureNameVariant(ultimate, nameToFind, targetIsShiny, targetIsShadow)
        ) {
            return ultimate;
        }

        const expeditionMatch = this.getActiveExpeditionOccupants().find(
            (occ: { name: string; isShiny?: boolean; isShadow?: boolean; data?: unknown }) => occ.name === nameToFind && !!occ.isShiny === targetIsShiny && !!occ.isShadow === targetIsShadow
        );
        if (!expeditionMatch || !expeditionMatch.data) return null; // Non trouv?

        const deserialized = Creature.deserialize(expeditionMatch.data) as CreatureData;
        deserialized._expeditionRef = {
            expeditionIndex: expeditionMatch.expeditionIndex,
            slotType: expeditionMatch.slotType,
            slotIndex: expeditionMatch.slotIndex ?? 0
        };
        return deserialized;
    };

    GameClass.prototype.findCreatureContainer = function (this: ThisGame, creature: CreatureData): CreatureContainerRef | null {
        const teamIndex = this.playerTeam.indexOf(creature);
        if (teamIndex >= 0) {
            return { location: 'team', array: this.playerTeam, index: teamIndex };
        }
        const storageIndex = this.storage.indexOf(creature);
        if (storageIndex >= 0) {
            return { location: 'storage', array: this.storage, index: storageIndex };
        }
        const pensionIndex = this.pension.indexOf(creature);
        if (pensionIndex >= 0) {
            return { location: 'pension', array: this.pension, index: pensionIndex };
        }
        return null;
    };

    /**
     * Après fusion évolutive : retire la source et place la cible fusionnée sur le slot libéré.
     */
    GameClass.prototype.relocateFusionTargetAfterSourceRemoved = function (
        this: ThisGame,
        target: CreatureData,
        sourceLocation: RosterLocation,
        sourceIndex: number,
        sourceWasActive: boolean,
    ) {
        const destArray = getRosterArray(this, sourceLocation);
        let touchedTeam = sourceLocation === 'team';
        let touchedStorage = sourceLocation === 'storage';
        let touchedPension = sourceLocation === 'pension';

        const removeSourceOnly = () => {
            if (sourceIndex < 0 || sourceIndex >= destArray.length) return;
            if (sourceLocation === 'team') {
                adjustActiveIndexOnTeamRemove(this, sourceIndex);
            }
            destArray.splice(sourceIndex, 1);
        };

        if (target._expeditionRef) {
            removeSourceOnly();
            if (touchedTeam) {
                this.calculateTeamStats();
                this.updateTeamDisplay();
            }
            if (touchedStorage) this.updateStorageDisplay();
            if (touchedPension) this.updatePensionDisplay();
            refreshOpenCreatureModalIfVisible(this);
            return;
        }

        const targetRef = this.findCreatureContainer(target);
        if (!targetRef) {
            removeSourceOnly();
            if (touchedTeam) {
                this.calculateTeamStats();
                this.updateTeamDisplay();
            }
            if (touchedStorage) this.updateStorageDisplay();
            if (touchedPension) this.updatePensionDisplay();
            refreshOpenCreatureModalIfVisible(this);
            return;
        }

        if (sourceLocation === 'pension' && targetRef.location === 'team' && this.playerTeam.length <= 1) {
            removeSourceOnly();
            if (touchedTeam) {
                this.calculateTeamStats();
                this.updateTeamDisplay();
            }
            if (touchedPension) this.updatePensionDisplay();
            refreshOpenCreatureModalIfVisible(this);
            return;
        }

        touchedTeam = touchedTeam || targetRef.location === 'team';
        touchedStorage = touchedStorage || targetRef.location === 'storage';
        touchedPension = touchedPension || targetRef.location === 'pension';

        const sameContainer = targetRef.location === sourceLocation;

        if (sourceLocation === 'team') {
            adjustActiveIndexOnTeamRemove(this, sourceIndex);
        }

        if (sourceIndex < 0 || sourceIndex >= destArray.length) return;
        destArray.splice(sourceIndex, 1);

        let targetIndex = targetRef.array.indexOf(target);
        if (targetIndex < 0) return;

        if (sameContainer && targetIndex > sourceIndex) {
            targetIndex--;
        }

        if (sameContainer && targetIndex === sourceIndex) {
            if (sourceWasActive) {
                this.activeCreatureIndex = sourceIndex;
                this.currentPlayerCreature = target;
                const updateCombatFn: unknown = this['updateCombatDisplay'];
                if (typeof updateCombatFn === 'function') {
                    (updateCombatFn as (this: ThisGame) => void).call(this);
                }
            }
            if (touchedTeam) {
                this.calculateTeamStats();
                this.updateTeamDisplay();
            }
            if (touchedStorage) this.updateStorageDisplay();
            if (touchedPension) this.updatePensionDisplay();
            refreshOpenCreatureModalIfVisible(this);
            return;
        }

        if (targetRef.location === 'team') {
            adjustActiveIndexOnTeamRemove(this, targetIndex);
        }

        const [moved] = targetRef.array.splice(targetIndex, 1);
        if (!moved) return;

        if (sourceLocation === 'team') {
            adjustActiveIndexOnTeamInsert(this, sourceIndex);
        }

        destArray.splice(sourceIndex, 0, moved);

        if (sourceWasActive) {
            this.activeCreatureIndex = sourceIndex;
            this.currentPlayerCreature = moved;
            const updateCombatFn: unknown = this['updateCombatDisplay'];
            if (typeof updateCombatFn === 'function') {
                (updateCombatFn as (this: ThisGame) => void).call(this);
            }
        }

        if (touchedTeam) {
            this.calculateTeamStats();
            this.updateTeamDisplay();
            const updatePowerFn: unknown = this['updateTeamPowerStat'];
            if (typeof updatePowerFn === 'function') {
                (updatePowerFn as (this: ThisGame) => void).call(this);
            }
            const displayTalentsFn: unknown = this['displayActiveTalents'];
            if (typeof displayTalentsFn === 'function') {
                (displayTalentsFn as (this: ThisGame) => void).call(this);
            }
        }
        if (touchedStorage) this.updateStorageDisplay();
        if (touchedPension) {
            this.stats.pensionCount = this.pension.length;
            this.updatePensionDisplay();
            const checkQuestsFn: unknown = this['checkSpecialQuests'];
            if (typeof checkQuestsFn === 'function') {
                (checkQuestsFn as (this: ThisGame, key: string) => void).call(this, 'pensionCount');
            }
        }
        refreshOpenCreatureModalIfVisible(this);
    };

    GameClass.prototype.moveToTeam = function (this: ThisGame, creatureIndex: number) {
        if (this.isTeamRosterEditLocked()) {
            logMessage(this.t('log.teamEditLocked'));
            return;
        }
        const maxTeamSize = getMaxTeamSize(this);

        if (this.playerTeam.length >= maxTeamSize) {
            logMessage(this.t('log.teamFull', { current: this.playerTeam.length, max: maxTeamSize }));
            return;
        }


        if (creatureIndex < 0 || creatureIndex >= this.storage.length) return;
        if (this.isCreatureRocketLocked(this.storage[creatureIndex])) {
            logMessage(this.t('log.rocketLockedCreature'));
            return;
        }

        const creature = this.storage.splice(creatureIndex, 1)[0];
        if (!creature) return;
        this.playerTeam.push(creature);

        this._afterMoveToTeam(creature);
    }

    /**
     * Retire du stockage et insère l'équipe à l'index voulu (drag & drop entre zones).
     */

    GameClass.prototype.moveToTeamAt = function (this: ThisGame, storageIndex: number, teamIndex: number) {
        if (this.isTeamRosterEditLocked()) {
            logMessage(this.t('log.teamEditLocked'));
            return;
        }
        const maxTeamSize = getMaxTeamSize(this);
        if (this.playerTeam.length >= maxTeamSize) {
            logMessage(this.t('log.teamFull', { current: this.playerTeam.length, max: maxTeamSize }));
            return;
        }
        if (storageIndex < 0 || storageIndex >= this.storage.length) return;
        if (this.isCreatureRocketLocked(this.storage[storageIndex])) {
            logMessage(this.t('log.rocketLockedCreature'));
            return;
        }
        const creature = this.storage.splice(storageIndex, 1)[0];
        if (!creature) return;
        const insertAt = Math.max(0, Math.min(teamIndex | 0, this.playerTeam.length));
        this.playerTeam.splice(insertAt, 0, creature);
        if (insertAt <= this.activeCreatureIndex) this.activeCreatureIndex++;
        this._afterMoveToTeam(creature);
    };

    GameClass.prototype._afterMoveToTeam = function (this: ThisGame, creature: CreatureData) {
        logMessage(this.t('log.movedToMainTeam', { name: creature.name }));
        this.stats.pensionCount = this.pension.length;
        this.calculateTeamStats();
        this.updateTeamDisplay();
        this.updateTeamPowerStat();
        this.checkSpecialQuests('pensionCount');
        this.displayActiveTalents();
        this.updateStorageDisplay();
        refreshOpenCreatureModalIfVisible(this);
    }

    /** Vérifie si un déplacement vers la pension est possible (sans modifier l'état). */

    GameClass.prototype.canMoveToPension = function (this: ThisGame, fromTeam: boolean, creatureIndex: number) {
        if (this.isTeamRosterEditLocked()) return false;
        if (this.getPensionSlots() === 0) return false;
        if (this.pension.length >= this.getPensionSlots()) return false;
        if (fromTeam) {
            if (this.playerTeam.length <= 1) return false;
            if (creatureIndex < 0 || creatureIndex >= this.playerTeam.length) return false;
        } else {
            if (creatureIndex < 0 || creatureIndex >= this.storage.length) return false;
            if (this.isCreatureRocketLocked(this.storage[creatureIndex])) return false;
        }
        return true;
    }

    /** Vérifie si un déplacement de l'équipe vers le stockage est possible. */

    GameClass.prototype.canMoveToStorage = function (this: ThisGame, creatureIndex: number) {
        if (this.isTeamRosterEditLocked()) return false;
        if (this.playerTeam.length <= 1) return false;
        if (creatureIndex < 0 || creatureIndex >= this.playerTeam.length) return false;
        return true;
    }

    /** Vérifie si un déplacement du stockage/pension vers l'équipe à l'index donné est possible. */

    GameClass.prototype.canMoveToTeamAt = function (this: ThisGame, storageIndex: number, teamIndex: number) {
        if (this.isTeamRosterEditLocked()) return false;
        const maxTeamSize = getMaxTeamSize(this);
        if (this.playerTeam.length >= maxTeamSize) return false;
        if (storageIndex < 0 || storageIndex >= this.storage.length) return false;
        if (this.isCreatureRocketLocked(this.storage[storageIndex])) return false;
        return true;
    }

    /** Vérifie si pension -> équipe est possible sans envoyer au stockage (équipe pas pleine). */

    GameClass.prototype.canMoveFromPensionToTeam = function (this: ThisGame, pensionIndex: number) {
        if (this.isTeamRosterEditLocked()) return false;
        if (pensionIndex < 0 || pensionIndex >= this.pension.length) return false;
        const maxTeamSize = getMaxTeamSize(this);
        if (this.playerTeam.length >= maxTeamSize) return false;
        return true;
    };

    GameClass.prototype.moveToStorage = function (this: ThisGame, creatureIndex: number) {
        if (this.isTeamRosterEditLocked()) {
            logMessage(this.t('log.teamEditLocked'));
            return;
        }
        if (this.playerTeam.length <= 1) {
            logMessage(this.t('log.cannotRemoveLast'));
            return;
        }

        if (creatureIndex < 0 || creatureIndex >= this.playerTeam.length) return;

        if (creatureIndex === this.activeCreatureIndex) {
            this.activeCreatureIndex = creatureIndex === 0 ? 1 : 0;
        } else if (creatureIndex < this.activeCreatureIndex) {
            this.activeCreatureIndex--;
        }

        const creature = this.playerTeam.splice(creatureIndex, 1)[0];
        if (!creature) return;
        this.storage.push(creature);

        logMessage(this.t('log.movedToStorage', { name: creature.name }));
        this.stats.pensionCount = this.pension.length;
        this.calculateTeamStats();
        this.updateTeamDisplay();
        this.checkSpecialQuests('pensionCount');
        this.displayActiveTalents();
        this.updateStorageDisplay();
    };

    GameClass.prototype.moveToPension = function (this: ThisGame, creatureIndex: number, fromTeam = false) {
        if (this.isTeamRosterEditLocked()) {
            logMessage(this.t('log.teamEditLocked'));
            return;
        }
        const maxSlots = this.getPensionSlots();

        if (maxSlots === 0) {
            logMessage(this.t('log.daycareLocked'));
            return;
        }

        if (this.pension.length >= maxSlots) {
            logMessage(this.t('log.daycareFull', { current: this.pension.length, max: maxSlots }));
            return;
        }

        let creature;
        if (fromTeam) {
            if (this.playerTeam.length <= 1) {
                logMessage(this.t('log.cannotRemoveLast'));
                return;
            }

            if (creatureIndex < 0 || creatureIndex >= this.playerTeam.length) return;

            if (creatureIndex === this.activeCreatureIndex) {
                this.activeCreatureIndex = creatureIndex === 0 ? 1 : 0;
            } else if (creatureIndex < this.activeCreatureIndex) {
                this.activeCreatureIndex--;
            }

            creature = this.playerTeam.splice(creatureIndex, 1)[0];
            if (!creature) return;
        } else {
            if (creatureIndex < 0 || creatureIndex >= this.storage.length) return;
            if (this.isCreatureRocketLocked(this.storage[creatureIndex])) {
                logMessage(this.t('log.rocketLockedCreature'));
                return;
            }
            creature = this.storage.splice(creatureIndex, 1)[0];
            if (!creature) return;
        }

        this.pension.push(creature);
        if (creature.uid) {
            unassignMiltankFromPastureIfPresent(this, String(creature.uid));
            unassignGuardianIfPresent(this, String(creature.uid));
        }
        logMessage(this.t('log.movedToDaycare', { name: creature.name }));
        this.stats.pensionCount = this.pension.length;
        this.checkAchievements('pensionCount');
        this.checkSpecialQuests('pensionCount');
        this.calculateTeamStats();
        this.displayActiveTalents();
        this.updateTeamDisplay();
        this.updateStorageDisplay();
        this.updatePensionDisplay();
    };

    GameClass.prototype.moveFromPension = function (this: ThisGame, creatureIndex: number, toTeam = false) {
        if (this.isTeamRosterEditLocked()) {
            logMessage(this.t('log.teamEditLocked'));
            return;
        }
        if (creatureIndex < 0 || creatureIndex >= this.pension.length) return;

        // 1. On r?cup?re la cr?ature (retrait de la pension)
        const creature = this.pension.splice(creatureIndex, 1)[0];
        if (!creature) return;

        // 2. Calculer la VRAIE taille max de l'équipe (comme dans l'UI)
        const maxTeamSize = getMaxTeamSize(this);

        if (toTeam) {
            // ? CORRECTION : On compare avec maxTeamSize, pas 6
            if (this.playerTeam.length >= maxTeamSize) {
                logMessage(this.t('log.teamFullSentToStorage'));
                this.storage.push(creature);
                if (typeof toast !== 'undefined') toast.info(this.t('toast.daycareTitle'), this.t('toast.daycareTeamFullBody'));
            } else {
                this.playerTeam.push(creature);
                logMessage(this.t('log.leftDaycareToTeam', { name: creature.name }));
                if (typeof toast !== 'undefined') toast.success(this.t('toast.daycareTitle'), this.t('toast.daycareTeamJoinedBody', { name: creature.name }));
            }
        } else {
            this.storage.push(creature);
            logMessage(this.t('log.leftDaycareToStorage', { name: creature.name }));
        }

        // 3. Mises ? jour
        if (this.stats) this.stats.pensionCount = this.pension.length;

        this.checkAchievements('pensionCount');
        this.checkSpecialQuests('pensionCount');

        this.calculateTeamStats();
        this.updateTeamDisplay();
        this.updateStorageDisplay();

        if (this.displayActiveTalents) this.displayActiveTalents();

        this.updatePensionDisplay();
        refreshOpenCreatureModalIfVisible(this);
        this.saveGame(); // Toujours utile de sauvegarder apr?s un mouvement
    }

    GameClass.prototype.moveAllFromPensionToStorage = function (this: ThisGame) {
        if (this.isTeamRosterEditLocked()) {
            logMessage(this.t('log.teamEditLocked'));
            return;
        }
        if (!this.pension.length) return;

        const count = this.pension.length;
        const creatures = this.pension.splice(0);
        this.storage.push(...creatures);

        if (this.stats) this.stats.pensionCount = this.pension.length;

        this.checkAchievements('pensionCount');
        this.checkSpecialQuests('pensionCount');

        this.calculateTeamStats();
        this.updateTeamDisplay();
        this.updateStorageDisplay();
        if (this.displayActiveTalents) this.displayActiveTalents();
        this.updatePensionDisplay();
        refreshOpenCreatureModalIfVisible(this);
        logMessage(this.t('log.movedAllFromDaycareToStorage', { count }));
        this.saveGame();
    };

