<script lang="ts">
  import { onMount } from 'svelte';
  import { GameEventType as Evt } from '../bus/events.js';
  import {
    buildAfkSummarySnapshot,
    type AfkSummarySnapshot,
  } from '../lib/afkSummarySnapshot.ts';
  import { useFacadeSubscription } from '../lib/useFacadeSubscription.ts';
  import type { GameRuntime } from '../types/game.js';

  function getGame(): GameRuntime | null {
    return (globalThis as { game?: GameRuntime }).game ?? null;
  }

  let refreshGen = $state(0);
  let dpsTick = $state(0);
  let lastCombatRefreshMs = 0;
  const COMBAT_REFRESH_THROTTLE_MS = 300;

  let snap = $derived.by((): AfkSummarySnapshot | null => {
    void refreshGen;
    void dpsTick;
    const g = getGame();
    if (!g?.afkMode) return null;
    return buildAfkSummarySnapshot(g);
  });

  function bumpRefresh(): void {
    refreshGen += 1;
  }

  function bumpRefreshFromCombat(): void {
    const g = getGame();
    if (!g?.afkMode) return;
    const now = performance.now();
    if (now - lastCombatRefreshMs < COMBAT_REFRESH_THROTTLE_MS) return;
    lastCombatRefreshMs = now;
    refreshGen += 1;
  }

  useFacadeSubscription(
    [
      Evt.TEAM_CHANGED,
      Evt.FARMING_METRICS_UPDATED,
      Evt.SETTINGS_CHANGED,
      Evt.AFK_SUMMARY_CHANGED,
      Evt.LANGUAGE_CHANGED,
    ],
    bumpRefresh,
  );

  useFacadeSubscription(Evt.COMBAT_STATE_CHANGED, bumpRefreshFromCombat);

  onMount(() => {
    bumpRefresh();
    const id = setInterval(() => {
      const g = getGame();
      if (g?.afkMode && g.unlockedFeatures?.dpsMeter) dpsTick += 1;
    }, 1000);
    return () => clearInterval(id);
  });
</script>

<aside
  id="afkSummaryBar"
  class="afk-summary-bar"
  aria-label={snap?.ariaLabel ?? 'AFK summary'}
>
  {#if snap}
    <div class="afk-summary-sect afk-summary-team" id="afkSummaryTeam">
      <span class="afk-summary-label">{snap.teamLabel}</span>
      {#if snap.noTeam}
        <span class="afk-summary-locked">{snap.noTeamText}</span>
      {:else}
        <div class="afk-summary-team-row">
          {#each snap.teamSlots as slot, idx (idx)}
            <div class="afk-summary-slot" class:active={slot.isActive}>
              <img
                class="afk-summary-slot-sprite"
                src={slot.spriteUrl}
                alt=""
                loading="lazy"
                decoding="async"
              />
              <div class="afk-summary-slot-hp">
                <div class="afk-summary-slot-hp-fill" style="width: {slot.hpPct}%"></div>
              </div>
            </div>
          {/each}
        </div>
      {/if}
    </div>

    <div class="afk-summary-sect afk-summary-dps" id="afkSummaryDps">
      <span class="afk-summary-label">{snap.dpsLabel}</span>
      {#if snap.dpsLocked}
        <span class="afk-summary-locked">{snap.dpsLockedText}</span>
      {:else}
        <div class="dps-live-overlay" class:has-data={snap.dpsHasData}>
          {#each snap.dpsPills as pill, idx (idx)}
            <div
              class="dps-live-pill"
              class:active={pill.isActive}
              class:empty={pill.isEmpty}
              title={pill.title}
            >
              <img
                src={pill.spriteUrl}
                alt=""
                class="dps-live-sprite"
                loading="lazy"
                decoding="async"
              />
              <span class="dps-live-dps">{pill.dpsText}</span>
            </div>
          {/each}
        </div>
      {/if}
    </div>

    <div class="afk-summary-sect afk-summary-farm" id="afkSummaryFarm">
      <span class="afk-summary-label">
        {snap.farmLabel}{#if !snap.farmLocked} {snap.farmRecSuffix}{/if}
      </span>
      {#if snap.farmLocked}
        <span class="afk-summary-locked">{snap.farmLockedText}</span>
      {:else}
        {#each snap.farmLines as line (line.label)}
          <div class="afk-summary-farm-line">{line.label} {line.value}</div>
        {/each}
      {/if}
    </div>
  {/if}
</aside>
