/**
 * @file src/lib/resonanceTooltip.ts
 * Tooltip HTML for regional resonance anchor preview band.
 */

import type { ResonanceTeamPreview } from './regionalResonance.ts';
import type { GameRuntime } from '../types/game.js';
import { GEN5_SUBSTITUTE_SPRITE } from '../ui/utils.ts';
import {
    escapeHtml,
    formatPrestigeSuffix,
    formatPrestigeSuffixHtml,
} from '../../formatters.ts';
import { buildResonanceTeamPreview } from './regionalResonance.ts';

function applyVars(template: string, vars?: Record<string, unknown>): string {
    if (!vars) return template;
    return String(template).replace(/\{(\w+)\}/g, (_, k) => {
        const v = vars[k];
        if (v == null) return '';
        return String(v);
    });
}

function t(game: GameRuntime, key: string, fallback: string, vars?: Record<string, unknown>): string {
    if (typeof game.t !== 'function') return applyVars(fallback, vars);
    const got = game.t(key, vars);
    return got && got !== key ? got : applyVars(fallback, vars);
}

function getTemplate(game: GameRuntime, key: string, fallback: string): string {
    if (typeof game.t !== 'function') return fallback;

    const placeholderKeys = [...fallback.matchAll(/\{(\w+)\}/g)].map((m) => m[1]);
    const preserveVars: Record<string, string> = {};
    for (const k of placeholderKeys) {
        preserveVars[k] = `{${k}}`;
    }

    const got = game.t(key, preserveVars);
    return got && got !== key ? got : fallback;
}

function buildLevelPartHtml(prestige: number, level: number, levelWord: string): string {
    const prestigeHtml = formatPrestigeSuffixHtml(prestige);
    const prefix = prestigeHtml ? `${prestigeHtml} ` : '';
    return `${prefix}${levelWord} ${level}`;
}

export function buildResonanceTooltipBody(
    game: GameRuntime,
    preview: ResonanceTeamPreview,
): string {
    if (!preview.active || !preview.tooltipAnchors.length) return '';
    const levelWord = t(game, 'resonance.previewLevelWord', 'niv.');
    const spriteRow = preview.tooltipAnchors
        .map((a) => {
            const src = escapeHtml(a.spriteUrl || GEN5_SUBSTITUTE_SPRITE);
            const alt = escapeHtml(a.displayName);
            return `<img class="resonance-tooltip-anchor-sprite" src="${src}" alt="${alt}" draggable="false" loading="lazy" decoding="async">`;
        })
        .join('');
    const lineTemplate = getTemplate(
        game,
        'resonance.previewAnchorLine',
        '{name} — {levelPart} (Niv. total : {sim})',
    );
    const lines = preview.tooltipAnchors
        .map((a) => {
            const levelPart = buildLevelPartHtml(a.prestige, a.level, levelWord);
            return applyVars(lineTemplate, {
                name: escapeHtml(a.displayName),
                levelPart,
                sim: a.simulatedLevel,
            });
        })
        .join('<br>');
    return `<div class="resonance-tooltip-anchors">${spriteRow}</div>${lines}`;
}

export function buildResonanceTooltipTitle(
    game: GameRuntime,
    preview: ResonanceTeamPreview,
): string {
    if (!preview.active) return '';
    const levelWord = t(game, 'resonance.previewLevelWord', 'niv.');
    const levelPart = buildLevelPartHtml(preview.capPrestige, preview.capLevel, levelWord);
    return applyVars(
        getTemplate(game, 'resonance.previewTitle', 'Résonance {cap} ({levelPart})'),
        {
            cap: preview.capSimLevel,
            levelPart,
        },
    );
}

export function showResonanceAnchorsTooltip(
    game: GameRuntime,
    tapEvent: { clientX: number; clientY: number; currentTarget?: Element; target?: Element },
): boolean {
    if (typeof game.scheduleTooltip !== 'function') return false;
    const preview = buildResonanceTeamPreview(game);
    if (!preview?.active || !preview.tooltipAnchors.length) return false;
    const title = buildResonanceTooltipTitle(game, preview);
    const body = buildResonanceTooltipBody(game, preview);
    if (!title || !body) return false;
    game.scheduleTooltip(tapEvent, title, body, 50);
    return true;
}
