let traceEnabled: boolean | null = null;

function isSaveTraceEnabled(): boolean {
    if (traceEnabled != null) return traceEnabled;
    if (typeof window === 'undefined') {
        traceEnabled = false;
        return false;
    }
    try {
        if (localStorage.getItem('poketimeSaveTrace') === '1') {
            traceEnabled = true;
            return true;
        }
        const params = new URLSearchParams(window.location.search);
        traceEnabled = params.get('saveTrace') === '1';
    } catch {
        traceEnabled = false;
    }
    return traceEnabled;
}

export function resetSaveTraceForTests(enabled?: boolean): void {
    traceEnabled = enabled ?? null;
}

export function firstSignatureSegmentDiff(before: string | null | undefined, after: string): number {
    const a = (before || '').split('|');
    const b = after.split('|');
    const n = Math.max(a.length, b.length);
    for (let i = 0; i < n; i++) {
        if ((a[i] ?? '') !== (b[i] ?? '')) return i;
    }
    return -1;
}

export function traceAutoSaveFlush(payload: {
    blocked?: boolean;
    reason?: string;
    immediate?: boolean;
    msSinceLastSave?: number;
    signatureDiffAt?: number;
}): void {
    if (!isSaveTraceEnabled()) return;
    console.info('[poketime:autosave]', payload);
}

export function traceSaveGame(reason?: string, immediate?: boolean): void {
    if (!isSaveTraceEnabled()) return;
    console.info('[poketime:save]', { reason: reason || 'unspecified', immediate: !!immediate });
}
