type GameCtor = { prototype: Record<string, unknown> };
type ThisGame = GameRuntime;

import { ELU_TALENT_BOOST } from './src/lib/eluTalentBoost.ts';

/** Per-stack weight in maternalSum (diminishing returns across team carriers). */
export const MATERNAL_INSTINCT_PER_STACK = 0.15;

export function computeMaternalInstinctFromTeam(
    playerTeam: ReadonlyArray<{ passiveTalent?: string | null } | null | undefined> | null | undefined,
    eluActive = false,
): { maternalSum: number; mult: number; reduction: number } {
    let maternalSum = 0;
    let mi = 0;
    if (Array.isArray(playerTeam)) {
        for (const pc of playerTeam) {
            if (pc && pc.passiveTalent === 'instinct_maternel') {
                maternalSum += Math.pow(0.5, mi);
                mi++;
            }
        }
    }
    const stackRate = eluActive ? MATERNAL_INSTINCT_PER_STACK * ELU_TALENT_BOOST : MATERNAL_INSTINCT_PER_STACK;
    const mult = maternalSum > 0 ? 1 / (1 + stackRate * maternalSum) : 1;
    return { maternalSum, mult, reduction: mult < 1 ? 1 - mult : 0 };
}

export function applyEggSystem(GameClass: GameCtor): void {

    GameClass.prototype.ensureIncubatorArraySize = function (this: ThisGame) {
        if (!Array.isArray(this.incubators)) {
            this.incubators = [];
        }
        while (this.incubators.length < MAX_INCUBATOR_SLOTS) {
            this.incubators.push(null);
        }
        if (this.incubators.length > MAX_INCUBATOR_SLOTS) {
            this.incubators.length = MAX_INCUBATOR_SLOTS;
        }
    };

    GameClass.prototype.hasMasteryIncubatorSlot = function (this: ThisGame) {
        return (this.getMasteryBonus ? (this.getMasteryBonus('incubator_extra_slot') || 0) : 0) > 0;
    };

    GameClass.prototype.getBaseIncubatorSlots = function (this: ThisGame) {
        const geneticsQuestIds = [
            'story_genetics_stage_1',
            'story_genetics_stage_2',
            'story_genetics_stage_3',
            'story_genetics_stage_4'
        ];
        let unlockedByQuest = 0;
        const completed = Array.isArray(this.completedStoryQuests) ? this.completedStoryQuests : [];
        const activeQuests = Array.isArray(this.quests) ? this.quests : [];

        for (let i = 0; i < geneticsQuestIds.length; i++) {
            const questId = geneticsQuestIds[i];
            if (!questId) continue;
            const isCompleted = completed.includes(questId);
            const isActive = activeQuests.some(q => q && q.id === questId && q.questType === 'STORY' && q.claimed !== true);
            if (isCompleted || isActive) {
                unlockedByQuest = i + 1;
            }
        }

        const legacyLevel = (this.upgrades && this.upgrades.incubatorSlots && this.upgrades.incubatorSlots.level) || 0;
        const legacyUnlocked = legacyLevel > 0 ? Math.min(4, 1 + legacyLevel) : 0;

        return Math.min(4, Math.max(unlockedByQuest, legacyUnlocked));
    };

    GameClass.prototype.getDisplayedIncubatorSlotCount = function (this: ThisGame) {
        return 4 + (this.hasMasteryIncubatorSlot() ? 1 : 0);
    };

    GameClass.prototype.getIncubatorLockLabel = function (this: ThisGame, slotIndex: number) {
        if (slotIndex === MASTERY_INCUBATOR_SLOT_INDEX) {
            if (!this.hasMasteryIncubatorSlot()) {
                return this.t('bag.incubatorMasteryRequired');
            }
            const base = this.getBaseIncubatorSlots();
            if (base < 4) {
                return this.t('bag.incubatorQuestRequired', { step: 4 });
            }
        }
        return this.t('bag.incubatorQuestRequired', { step: slotIndex + 1 });
    };

    GameClass.prototype.getIncubatorSlotTooltip = function (this: ThisGame, slotIndex: number) {
        if (slotIndex === 1) return this.t('bag.incubatorAdvanced');
        if (slotIndex === 2) return this.t('bag.incubatorExpert');
        if (slotIndex === 3) return this.t('bag.incubatorMaster');
        if (slotIndex === MASTERY_INCUBATOR_SLOT_INDEX) return this.t('bag.incubatorParallel');
        return this.t('bag.incubatorClassic');
    };

    GameClass.prototype.getEggCapsuleItemKey = function (this: ThisGame, rarity: string) {
        const keyByRarity: Record<string, string> = {
            [RARITY.COMMON]: 'hatch_capsule_common',
            [RARITY.RARE]: 'hatch_capsule_rare',
            [RARITY.EPIC]: 'hatch_capsule_epic',
            [RARITY.LEGENDARY]: 'hatch_capsule_legendary'
        };
        return keyByRarity[rarity] || null;
    };

    GameClass.prototype.useEggCapsulesForRarity = function (this: ThisGame, rarity: string, requestedCount: number = 1) {
        const capsuleKey = this.getEggCapsuleItemKey(rarity);
        if (!capsuleKey) return 0;
        const haveCapsules = Math.max(0, Math.floor(Number(this.items && this.items[capsuleKey]) || 0));
        const haveEggs = Math.max(0, Math.floor(Number(this.eggs && (this.eggs as unknown as Record<string, number>)[rarity]) || 0));
        const toUse = Math.min(Math.max(0, Number(requestedCount) || 0), haveCapsules, haveEggs);
        if (toUse <= 0) return 0;
        const beforeEggCount = Math.max(0, Math.floor(Number((this.eggs as unknown as Record<string, number>)[rarity]) || 0));
        const ok = (this.useItem as unknown as (key: string, qty: number) => number)(capsuleKey, toUse);
        if (!ok) return 0;
        const afterEggCount = Math.max(0, Math.floor(Number((this.eggs as unknown as Record<string, number>)[rarity]) || 0));
        return Math.max(0, beforeEggCount - afterEggCount);
    };

    GameClass.prototype.applyRetroactiveIncubatorSpeedBoost = function (this: ThisGame, speedMultiplier: number = 1) {
        const mult = Number(speedMultiplier) || 1;
        if (mult <= 1 || !Array.isArray(this.incubators)) return 0;

        const now = Date.now();
        let accelerated = 0;
        for (let i = 0; i < this.incubators.length; i++) {
            const slot = this.incubators[i];
            if (!slot || !slot.startTime || !slot.durationMs) continue;
            const remaining = this.getIncubatorRemainingMs(i);
            if (remaining <= 0) continue;

            const nextRemaining = Math.max(1000, Math.floor(remaining / mult));
            slot.startTime = now;
            slot.durationMs = nextRemaining;
            accelerated++;
        }
        return accelerated;
    };

    GameClass.prototype.createDefaultAutoIncubationState = function (this: ThisGame) {
        const hasConfiguredPriority = typeof AUTO_INCUBATION_DEFAULT_PRIORITY !== 'undefined'
            && Array.isArray(AUTO_INCUBATION_DEFAULT_PRIORITY)
            && AUTO_INCUBATION_DEFAULT_PRIORITY.length > 0;
        const defaultPriority = hasConfiguredPriority
            ? [...AUTO_INCUBATION_DEFAULT_PRIORITY]
            : [RARITY.COMMON, RARITY.RARE, RARITY.EPIC, RARITY.LEGENDARY];
        return {
            unlockedAutoSlots: 0,
            slotSettings: Array.from({ length: MAX_INCUBATOR_SLOTS }, () => ({
                enabled: false,
                priorityOrder: [...defaultPriority],
                autoCollectOnlyWhenReady: true
            }))
        };
    };

    GameClass.prototype.normalizeAutoIncubationState = function (this: ThisGame, rawState: Record<string, unknown>) {
        const defaults = this.createDefaultAutoIncubationState();
        const normalized: { unlockedAutoSlots: number; slotSettings: AutoIncubationSlotSettings[] } = {
            unlockedAutoSlots: Math.max(0, Math.min(4, Number(rawState && rawState.unlockedAutoSlots) || 0)),
            slotSettings: []
        };
        for (let i = 0; i < MAX_INCUBATOR_SLOTS; i++) {
            const slotSettings = rawState?.slotSettings;
            const rawSlot = (Array.isArray(slotSettings) && slotSettings[i] && typeof slotSettings[i] === 'object')
                ? slotSettings[i] as Record<string, unknown>
                : null;
            const base = defaults.slotSettings[i] ?? {
                enabled: false,
                priorityOrder: this.normalizePriorityOrder([]),
                autoCollectOnlyWhenReady: true
            };
            const priorityRaw = rawSlot?.priorityOrder;
            const priorityOrder = Array.isArray(priorityRaw)
                ? priorityRaw.filter((v): v is string => typeof v === 'string')
                : base.priorityOrder;
            normalized.slotSettings.push({
                enabled: !!rawSlot?.enabled,
                priorityOrder: this.normalizePriorityOrder(priorityOrder),
                autoCollectOnlyWhenReady: rawSlot?.autoCollectOnlyWhenReady !== undefined
                    ? !!rawSlot.autoCollectOnlyWhenReady
                    : true
            });
        }
        return normalized;
    };

    GameClass.prototype.getEggDropBonus = function (this: ThisGame) {
        let bonus = (this.upgrades.eggDrop?.level ?? 0) * 0.005;

        // Ajouter le bonus de la collection
        const collBonus = ((this.getCollectionBonuses ? this.getCollectionBonuses() : {}) as Record<string, unknown>).egg_drop_chance as number || 0;
        bonus += collBonus;
        if (this.getAccountTalentBonus) bonus += (this.getAccountTalentBonus('egg_drop_chance') || 0);

        // Ajouter les boosts temporaires
        bonus += this.getActiveBoostMultiplier('eggDrop');

        return bonus;
    };

    GameClass.prototype.getMaxIncubatorSlots = function (this: ThisGame) {
        const base = this.getBaseIncubatorSlots();
        const masterySlots = this.hasMasteryIncubatorSlot() ? 1 : 0;
        return Math.min(MAX_INCUBATOR_SLOTS, base + masterySlots);
    };

    GameClass.prototype.getIncubationSpeedMultiplier = function (this: ThisGame) {
        const level = (this.upgrades.incubationSpeed && this.upgrades.incubationSpeed.level) || 0;
        return Math.max(0.5, 1 - level * 0.10);
    };

    GameClass.prototype.getIncubatorClickReductionMs = function (this: ThisGame) {
        const upg = this.upgrades && this.upgrades.incubatorClickPower;
        if (!upg || !(upg as unknown as Record<string, number[]>).msValues) return 20;
        const level = Math.max(0, Math.min(upg.level || 0, upg.maxLevel || 10));
        return (upg as unknown as Record<string, number[]>).msValues?.[level] ?? 20;
    };

    GameClass.prototype.getMaternalInstinctIncubationReduction = function (this: ThisGame): number {
        const eluActive = typeof this.hasEluActive === 'function' && this.hasEluActive();
        return computeMaternalInstinctFromTeam(this.playerTeam, eluActive).reduction;
    };

    GameClass.prototype.getIncubationDurationMs = function (this: ThisGame, rarity: string, slotIndex: number = 0, referenceTs: number = Date.now()) {
        if (typeof EGG_INCUBATION_BASE_MS === 'undefined' || !EGG_INCUBATION_BASE_MS[rarity]) return 5 * 60 * 1000;

        const baseMs = EGG_INCUBATION_BASE_MS[rarity];

        // Bonus specifiques par slot d'incubateur
        // slotIndex 0: Incubateur 1 (temps normal)
        // slotIndex 1: Incubateur 2 (-10% sur Commun/Rare)
        // slotIndex 2: Incubateur 3 (-20% sur Commun/Rare/Epique)
        // slotIndex 3: Incubateur 4 (-30% sur toutes les raretes)
        // slotIndex 4: Incubateur 5 mastery (-40% sur toutes les raretes)

        let slotModifier = 1.0;
        if (slotIndex === 1 && (rarity === RARITY.COMMON || rarity === RARITY.RARE)) {
            slotModifier = 0.90; // -10%
        } else if (slotIndex === 2 && (rarity === RARITY.COMMON || rarity === RARITY.RARE || rarity === RARITY.EPIC)) {
            slotModifier = 0.80; // -20%
        } else if (slotIndex === 3) {
            slotModifier = 0.70; // -30%
        } else if (slotIndex === MASTERY_INCUBATOR_SLOT_INDEX) {
            slotModifier = 0.60; // -40%
        }

        // On applique le modificateur de slot au temps de base
        const timeWithSlotBonus = baseMs * slotModifier;

        // Puis on applique le bonus global de l'am?lioration (incubationSpeed)
        // et le boost temporaire de vitesse d'eclosion.
        // Le Charme Ovale ne doit jamais se cumuler en intensite: on prend la
        // plus grande valeur active (x3), puis seule la duree est etendue.
        let hatchSpeedBoost = 0;
        const atTs = Number.isFinite(Number(referenceTs)) ? Number(referenceTs) : Date.now();
        const shouldUseOfflineSnapshot = atTs <= Date.now() && Array.isArray((this as unknown as Record<string, unknown>)._offlineActiveBoostsSnapshot);
        const boostSources = shouldUseOfflineSnapshot
            ? [this.activeBoosts || [], (this as unknown as Record<string, unknown>)._offlineActiveBoostsSnapshot as StatBoost[]]
            : [this.activeBoosts || []];

        boostSources.forEach((source) => {
            source.forEach((boost) => {
                if (!boost || boost.type !== 'eggHatchSpeed') return;
                if (Number(boost.endTime) <= atTs) return;
                hatchSpeedBoost = Math.max(hatchSpeedBoost, Number(boost.value) || 0);
            });
        });
        const hatchTimeMultiplier = 1 / (1 + hatchSpeedBoost);
        const ec = (this.getMasteryBonus ? (this.getMasteryBonus('egg_curator') || 0) : 0);
        const eggCuratorMult = Math.max(0.25, 1 - ec);
        const eluActive = typeof this.hasEluActive === 'function' && this.hasEluActive();
        const maternalMult = computeMaternalInstinctFromTeam(this.playerTeam, eluActive).mult;
        return Math.max(0, Math.floor(timeWithSlotBonus * this.getIncubationSpeedMultiplier() * hatchTimeMultiplier * eggCuratorMult * maternalMult));
    };

    GameClass.prototype.getIncubatorRemainingMs = function (this: ThisGame, slotIndex: number) {
        const slot = this.incubators[slotIndex];
        if (!slot || !slot.startTime || !slot.durationMs) return 0;
        const elapsed = Date.now() - slot.startTime;
        return Math.max(0, slot.durationMs - elapsed);
    };

    GameClass.prototype.isIncubatorReady = function (this: ThisGame, slotIndex: number) {
        return this.getIncubatorRemainingMs(slotIndex) === 0 && this.incubators[slotIndex] != null;
    };

    GameClass.prototype.placeEggInIncubator = function (this: ThisGame, slotIndex: number, rarity: string, options: Record<string, unknown> = {}) {
        if (slotIndex < 0 || slotIndex >= this.getMaxIncubatorSlots()) return false;
        if (((this.eggs as unknown as Record<string, number>)[rarity] ?? 0) <= 0) return false;
        if (this.incubators[slotIndex] != null) return false;
        (this.eggs as unknown as Record<string, number>)[rarity] = ((this.eggs as unknown as Record<string, number>)[rarity] ?? 0) - 1;
        const nowTs = Number.isFinite(Number(options.nowTs)) ? Number(options.nowTs) : Date.now();
        const durationMs = this.getIncubationDurationMs(rarity, slotIndex, nowTs);
        this.incubators[slotIndex] = { rarity, startTime: nowTs, durationMs };
        if (!options.silent) {
            const maternalPct = Math.round(this.getMaternalInstinctIncubationReduction() * 100);
            const minutes = Math.ceil(durationMs / 60000);
            if (maternalPct > 0) {
                logMessage(this.t('log.incubatorPlacedWithMaternal', {
                    rarity,
                    slot: slotIndex + 1,
                    minutes,
                    pct: maternalPct,
                }));
            } else {
                logMessage(this.t('log.incubatorPlaced', { rarity, slot: slotIndex + 1, minutes }));
            }
        }
        publishBagEggMetaChanged();
        void import('./src/ui/bagEggDisplay.ts').then((m) => m.syncBagEggSectionsUI(this));
        return true;
    };

    GameClass.prototype.openIncubatorEgg = function (this: ThisGame, slotIndex: number, options: Record<string, unknown> = {}) {
        if (slotIndex < 0 || slotIndex >= this.getMaxIncubatorSlots()) return;
        const forceReady = !!options.forceReady;
        if (!forceReady && !this.isIncubatorReady(slotIndex)) return;
        const slot = this.incubators[slotIndex];
        if (!slot) return;
        const rarity = slot.rarity as string;
        if (typeof this.applyEggHatchBatchReduction === 'function') {
            this.applyEggHatchBatchReduction(slotIndex);
        }
        this.incubators[slotIndex] = null;
        // Ne pas re-rendre le DOM ? chaque ?uf en mode silent (simulation offline) ? tr?s co?teux
        if (!options.silent) this.updateIncubatorsDisplay();
        return this.openEgg(rarity, true, {
            silent: !!options.silent,
            source: 'incubator',
            slotIndex,
            offline: !!options.offline
        }); // true = &Suf d?j? retir? de l'inventaire (plac? dans l'incubateur)
    };

    GameClass.prototype.openChooseEggModal = function (this: ThisGame, slotIndex: number) {
        this._chooseEggSlotIndex = slotIndex;
        const modal = document.getElementById('chooseEggModal');
        const optionsEl = document.getElementById('chooseEggOptions');
        if (!modal || !optionsEl) return;
        optionsEl.innerHTML = '';
        const maternalPct = Math.round(this.getMaternalInstinctIncubationReduction() * 100);
        const maternalBadge = maternalPct > 0
            ? `<span class="choose-egg-btn-maternal">-${maternalPct}%</span>`
            : '';
        const rarities = [RARITY.COMMON, RARITY.RARE, RARITY.EPIC, RARITY.LEGENDARY];
        rarities.forEach(rarity => {
            const count = (this.eggs as unknown as Record<string, number>)[rarity] || 0;
            if (count <= 0) return;
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = `choose-egg-btn rarity-${rarity}`;
            const filterClass = rarity === 'common' ? '' : ` egg-filter-${rarity}`;
            const label = this.getRarityLabel(rarity);
            const eggSpriteUrl = `img/${rarity}-egg.png`;
            const durationMs = this.getIncubationDurationMs(rarity, slotIndex, Date.now());
            const durationLabel = `~${Math.ceil(durationMs / 60000)} min`;
            btn.innerHTML = `<img src="${eggSpriteUrl}" alt="" class="choose-egg-btn-icon egg-sprite${filterClass}">`
                + `<span class="choose-egg-btn-center">`
                + `<span class="choose-egg-btn-label">${label}</span>`
                + `<span class="choose-egg-btn-duration-row">`
                + `<span class="choose-egg-btn-duration">${durationLabel}</span>`
                + maternalBadge
                + `</span></span>`
                + `<span class="choose-egg-btn-count">&times; ${count}</span>`;
            btn.onclick = () => this.chooseEggForIncubator(rarity);
            optionsEl.appendChild(btn);
        });
        if (optionsEl.children.length === 0) {
            optionsEl.innerHTML = `<p class="choose-egg-empty-msg">${this.t('egg.chooseEmpty')}</p>`;
        }
        modal.classList.add('show');
    };

    GameClass.prototype.closeChooseEggModal = function (this: ThisGame) {
        (this as unknown as Record<string, unknown>)._chooseEggSlotIndex = undefined;
        const modal = document.getElementById('chooseEggModal');
        if (modal) modal.classList.remove('show');
    };

    GameClass.prototype.chooseEggForIncubator = function (this: ThisGame, rarity: string) {
        if ((this as unknown as Record<string, unknown>)._chooseEggSlotIndex === undefined) return;
        this.placeEggInIncubator((this as unknown as Record<string, unknown>)._chooseEggSlotIndex as number, rarity);
        this.closeChooseEggModal();
    };

    GameClass.prototype.isAutoIncubationUnlockedForSlot = function (this: ThisGame, slotIndex: number) {
        const maxSlots = this.getMaxIncubatorSlots ? this.getMaxIncubatorSlots() : MAX_INCUBATOR_SLOTS - 1;
        if (slotIndex < 0 || slotIndex >= maxSlots) return false;
        const questAuto = (this.autoIncubation && this.autoIncubation.unlockedAutoSlots) || 0;
        if (slotIndex < questAuto) return true;
        if (slotIndex === MASTERY_INCUBATOR_SLOT_INDEX && maxSlots >= MAX_INCUBATOR_SLOTS) {
            return this.hasMasteryIncubatorSlot();
        }
        return false;
    };

    GameClass.prototype.getAutoIncubationSettings = function (this: ThisGame, slotIndex: number) {
        const state = this.autoIncubation || this.createDefaultAutoIncubationState();
        const slotSettings = Array.isArray(state.slotSettings) ? state.slotSettings[slotIndex] : null;
        if (!slotSettings) return { enabled: false, priorityOrder: this.normalizePriorityOrder([RARITY.COMMON]), autoCollectOnlyWhenReady: true };
        return {
            enabled: !!slotSettings.enabled,
            priorityOrder: this.normalizePriorityOrder(slotSettings.priorityOrder),
            autoCollectOnlyWhenReady: slotSettings.autoCollectOnlyWhenReady !== false
        };
    };

    GameClass.prototype.setAutoIncubationEnabled = function (this: ThisGame, slotIndex: number, enabled: boolean) {
        if (!this.autoIncubation) this.autoIncubation = this.createDefaultAutoIncubationState();
        if (!this.isAutoIncubationUnlockedForSlot(slotIndex)) return;
        const settings = this.getAutoIncubationSettings(slotIndex);
        this.autoIncubation.slotSettings[slotIndex] = {
            ...settings,
            enabled: !!enabled
        };
        this.updateIncubatorsDisplay();
        this.saveGame();
    };

    GameClass.prototype.cycleIncubatorPriority = function (this: ThisGame, slotIndex: number) {
        if (!this.autoIncubation || !this.isAutoIncubationUnlockedForSlot(slotIndex)) return;
        const settings = this.getAutoIncubationSettings(slotIndex);
        const current = settings.priorityOrder[0] || RARITY.COMMON;
        const order = [RARITY.COMMON, RARITY.RARE, RARITY.EPIC, RARITY.LEGENDARY];
        const idx = order.indexOf(current);
        const nextFirst = order[(idx + 1) % order.length];
        const nextOrder = [nextFirst, ...order.filter(r => r !== nextFirst)];
        this.autoIncubation.slotSettings[slotIndex] = {
            ...settings,
            priorityOrder: nextOrder
        };
        this.updateIncubatorsDisplay();
        this.saveGame();
    };

    GameClass.prototype.getSlotPriorityLabel = function (this: ThisGame, slotIndex: number) {
        const settings = this.getAutoIncubationSettings(slotIndex);
        const first = settings.priorityOrder[0] || RARITY.COMMON;
        return this.getRarityLabel(first);
    };

    GameClass.prototype.pickNextEggByPriority = function (this: ThisGame, slotIndex: number) {
        const settings = this.getAutoIncubationSettings(slotIndex);
        const priorities = this.normalizePriorityOrder(settings.priorityOrder);
        const target = priorities[0] || RARITY.COMMON;

        const ladder = [RARITY.COMMON, RARITY.RARE, RARITY.EPIC, RARITY.LEGENDARY];
        const targetIndex = Math.max(0, ladder.indexOf(target));

        // Ordre voulu:
        // 1) raret? cibl?e
        // 2) raret?s inf?rieures de la plus proche ? la plus basse
        // 3) raret?s sup?rieures de la plus proche ? la plus haute
        const scanOrder = [target];
        for (let i = targetIndex - 1; i >= 0; i--) scanOrder.push(ladder[i]);
        for (let i = targetIndex + 1; i < ladder.length; i++) scanOrder.push(ladder[i]);

        for (const rarity of scanOrder) {
            if (((this.eggs as unknown as Record<string, number>)[rarity] || 0) > 0) return rarity;
        }
        return null;
    };

    GameClass.prototype.tryAutoRefillIncubator = function (this: ThisGame, slotIndex: number, options: Record<string, unknown> = {}) {
        if (slotIndex < 0 || slotIndex >= this.getMaxIncubatorSlots()) return false;
        if (this.incubators[slotIndex] != null) return false;
        if (!this.isAutoIncubationUnlockedForSlot(slotIndex)) return false;
        const settings = this.getAutoIncubationSettings(slotIndex);
        if (!settings.enabled) return false;
        const rarity = this.pickNextEggByPriority(slotIndex);
        if (!rarity) return false;
        const placed = this.placeEggInIncubator(slotIndex, rarity, {
            silent: options.silent !== false,
            nowTs: options.nowTs
        });
        if (placed && (options).stats && ((options).stats as Record<string, unknown>).incubation) {
            const incStats = ((options).stats as Record<string, unknown>).incubation as Record<string, unknown>;
            const byRarityPlaced = (incStats as Record<string, Record<string, number>>).byRarityPlaced;
            const bySlotPlaced = (incStats as Record<string, Record<string, number>>).bySlotPlaced;
            (incStats as Record<string, number>).placedTotal = ((incStats as Record<string, number>).placedTotal ?? 0) + 1;
            if (byRarityPlaced) byRarityPlaced[rarity] = (byRarityPlaced[rarity] ?? 0) + 1;
            if (bySlotPlaced) bySlotPlaced[slotIndex] = (bySlotPlaced[slotIndex] ?? 0) + 1;
        }
        return placed;
    };

    GameClass.prototype.processAutoIncubatorsOnline = function (this: ThisGame) {
        if (!this.autoIncubation) return;
        for (let i = 0; i < this.getMaxIncubatorSlots(); i++) {
            if (!this.isAutoIncubationUnlockedForSlot(i)) continue;
            const settings = this.getAutoIncubationSettings(i);
            if (!settings.enabled) continue;

            if (this.isIncubatorReady(i)) {
                this.openIncubatorEgg(i, { silent: true });
            }
            if (!this.incubators[i]) {
                this.tryAutoRefillIncubator(i, { silent: true });
            }
        }
    };

    GameClass.prototype.processIncubatorAutoClick = function (this: ThisGame) {
        const upg = this.upgrades && this.upgrades.incubatorAutoClick;
        if (!upg || upg.level <= 0) return;
        const level = Math.min(upg.level, 6);
        const cooldownArr = (upg as unknown as Record<string, number[]>).cooldownSecs;
        const reductionArr = (upg as unknown as Record<string, number[]>).reductionSecs;
        const cooldownMs = (cooldownArr?.[level] ?? 10) * 1000;
        const reductionMs = (reductionArr?.[level] ?? 1) * 1000;
        const now = Date.now();
        if (now - ((this as unknown as Record<string, unknown>)._lastAutoClickTs as number || 0) < cooldownMs) return;

        const eligible = [];
        for (let i = 0; i < this.getMaxIncubatorSlots(); i++) {
            if (this.incubators[i] && !this.isIncubatorReady(i)) eligible.push(i);
        }
        if (eligible.length === 0) return;

        const slotIdx = eligible[Math.floor(Math.random() * eligible.length)];
        if (slotIdx == null) return;
        const slotEntry = this.incubators[slotIdx] as IncubatorSlot | null | undefined;
        if (!slotEntry) return;
        slotEntry.startTime = (slotEntry.startTime || 0) - reductionMs;
        (this.stats as unknown as Record<string, number>).incubatorAutoClickTotalMs = ((this.stats as unknown as Record<string, number>).incubatorAutoClickTotalMs ?? 0) + reductionMs;
        this.checkAchievements('incubatorAutoClickTotalMs');
        (this as unknown as Record<string, unknown>)._lastAutoClickTs = now;

        const container = document.getElementById('incubatorsContainer');
        const slotEl = container?.children[slotIdx];
        if (container && slotEl) {
            showFloatingText("-" + (reductionArr?.[level] ?? 1) + "s", slotEl as HTMLElement, "ft-speedup");
        }
        if (this._activeMainTabId === 'sacadosTab') this.updateIncubatorsDisplay();
    };

    GameClass.prototype.createOfflineIncubationStats = function (this: ThisGame) {
        return {
            hatchedTotal: 0,
            placedTotal: 0,
            byRarity: {},
            bySlot: {},
            byRarityPlaced: {},
            bySlotPlaced: {},
            obtainedPokemonPreview: []
        };
    };

    GameClass.prototype.pushOfflineIncubationPreview = function (this: ThisGame, stats: Record<string, unknown>, hatchResult: Record<string, unknown>) {
        // On collecte un pool plus large (jusqu'a 200) pour pouvoir ensuite
        // afficher uniquement les 10 plus rares / nouveautes dans le rapport.
        const HARD_CAP = 200;
        if (!hatchResult || !hatchResult.creatureName) return;
        const preview = (stats as Record<string, unknown[]>).obtainedPokemonPreview;
        if (!preview || preview.length >= HARD_CAP) return;
        preview.push({
            name: hatchResult.creatureName,
            rarity: hatchResult.rarity,
            isShiny: !!hatchResult.isShiny,
            wasNewDiscovery: !!hatchResult.wasNewDiscovery,
            wasNewShinyDiscovery: !!hatchResult.wasNewShinyDiscovery
        });
    };

    GameClass.prototype.simulateIncubatorsChunk = function (this: ThisGame, chunkMs: number, statsContainer: Record<string, unknown>) {
        if (!chunkMs || chunkMs <= 0 || !statsContainer) return;
        if (!this.autoIncubation || (this.autoIncubation.unlockedAutoSlots || 0) <= 0) return;
        const incubationStats = statsContainer.incubation || this.createOfflineIncubationStats();
        if (!statsContainer.incubation) statsContainer.incubation = incubationStats;
        if (!statsContainer.offlineCapturedTypes || typeof statsContainer.offlineCapturedTypes !== 'object') {
            statsContainer.offlineCapturedTypes = {};
        }
        const stc = statsContainer;
        if (stc.incubationVirtualTs == null) {
            stc.incubationVirtualTs = Date.now() - (Number(stc.offlineMissedTime) || 0);
        }
        const virtualTs = stc.incubationVirtualTs as number;

        for (let i = 0; i < this.getMaxIncubatorSlots(); i++) {
            if (!this.isAutoIncubationUnlockedForSlot(i)) continue;
            const settings = this.getAutoIncubationSettings(i);
            if (!settings.enabled) continue;

            let remainingMs = chunkMs;
            while (remainingMs > 0) {
                const currentVirtualTs = virtualTs + (chunkMs - remainingMs);
                if (!this.incubators[i]) {
                    const placed = this.tryAutoRefillIncubator(i, {
                        silent: true,
                        stats: statsContainer,
                        nowTs: currentVirtualTs
                    });
                    if (!placed) break;
                }

                const slot = this.incubators[i];
                if (!slot) break;
                let slotRemaining = Math.max(0, Number(slot.durationMs) || 0);
                if (slot.startTime != null && slot.startTime < currentVirtualTs) {
                    const elapsedBefore = currentVirtualTs - slot.startTime;
                    slotRemaining = Math.max(0, slotRemaining - elapsedBefore);
                }
                if (slotRemaining <= remainingMs) {
                    remainingMs -= slotRemaining;
                    const result = this.openIncubatorEgg(i, { silent: true, offline: true, forceReady: true });
                    if (!result || !result.ok) break;
                    (incubationStats as Record<string, number>).hatchedTotal = ((incubationStats as Record<string, number>).hatchedTotal ?? 0) + 1;
                    const resultRarity = result.rarity as string | undefined;
                    if (resultRarity) {
                        const byRarity = (incubationStats as Record<string, Record<string, number>>).byRarity;
                        if (byRarity) byRarity[resultRarity] = (byRarity[resultRarity] ?? 0) + 1;
                    }
                    const bySlot = (incubationStats as Record<string, Record<string, number>>).bySlot;
                    if (bySlot) bySlot[i] = (bySlot[i] ?? 0) + 1;
                    this.pushOfflineIncubationPreview(incubationStats as Record<string, unknown>, result);
                    if (result.creatureType) ((statsContainer).offlineCapturedTypes as Record<string, boolean>)[result.creatureType as string] = true;
                    if (result.secondaryType) ((statsContainer).offlineCapturedTypes as Record<string, boolean>)[result.secondaryType as string] = true;
                } else {
                    slot.durationMs = slotRemaining - remainingMs;
                    slot.startTime = currentVirtualTs + remainingMs;
                    remainingMs = 0;
                }
            }
        }
        (statsContainer).incubationVirtualTs = virtualTs + chunkMs;
    };

    GameClass.prototype.simulateIncubatorsForElapsedOffline = function (this: ThisGame, elapsedMs: number, statsContainer: Record<string, unknown>) {
        if (!elapsedMs || elapsedMs <= 0) return;
        if (!this.autoIncubation || (this.autoIncubation.unlockedAutoSlots || 0) <= 0) return;
        const incubationStats = statsContainer && statsContainer.incubation
            ? statsContainer.incubation
            : this.createOfflineIncubationStats();
        if (statsContainer && !statsContainer.incubation) statsContainer.incubation = incubationStats;
        if (statsContainer && (!statsContainer.offlineCapturedTypes || typeof statsContainer.offlineCapturedTypes !== 'object')) {
            statsContainer.offlineCapturedTypes = {};
        }
        const hiddenStartTs = Date.now() - elapsedMs;

        for (let i = 0; i < this.getMaxIncubatorSlots(); i++) {
            if (!this.isAutoIncubationUnlockedForSlot(i)) continue;
            const settings = this.getAutoIncubationSettings(i);
            if (!settings.enabled) continue;

            let remainingMs = elapsedMs;
            while (remainingMs > 0) {
                const currentVirtualTs = hiddenStartTs + (elapsedMs - remainingMs);
                if (!this.incubators[i]) {
                    const placed = this.tryAutoRefillIncubator(i, {
                        silent: true,
                        stats: statsContainer,
                        nowTs: currentVirtualTs
                    });
                    if (!placed) break;
                }

                const slot = this.incubators[i];
                if (!slot) break;
                let slotRemaining = Math.max(0, Number(slot.durationMs) || 0);
                if (slot.startTime && slot.startTime < currentVirtualTs) {
                    const elapsedBeforeHidden = currentVirtualTs - slot.startTime;
                    slotRemaining = Math.max(0, slotRemaining - elapsedBeforeHidden);
                }
                if (slotRemaining <= remainingMs) {
                    remainingMs -= slotRemaining;
                    const result = this.openIncubatorEgg(i, { silent: true, offline: true, forceReady: true });
                    if (!result || !result.ok) break;
                    (incubationStats as Record<string, number>).hatchedTotal = ((incubationStats as Record<string, number>).hatchedTotal ?? 0) + 1;
                    const resultRarity = result.rarity as string | undefined;
                    if (resultRarity) {
                        const byRarity = (incubationStats as Record<string, Record<string, number>>).byRarity;
                        if (byRarity) byRarity[resultRarity] = (byRarity[resultRarity] ?? 0) + 1;
                    }
                    const bySlot = (incubationStats as Record<string, Record<string, number>>).bySlot;
                    if (bySlot) bySlot[i] = (bySlot[i] ?? 0) + 1;
                    this.pushOfflineIncubationPreview(incubationStats as Record<string, unknown>, result);
                    if (statsContainer && result.creatureType) ((statsContainer).offlineCapturedTypes as Record<string, boolean>)[result.creatureType as string] = true;
                    if (statsContainer && result.secondaryType) ((statsContainer).offlineCapturedTypes as Record<string, boolean>)[result.secondaryType as string] = true;
                } else {
                    slot.durationMs = slotRemaining - remainingMs;
                    slot.startTime = Date.now();
                    remainingMs = 0;
                }
            }
        }
    };

    GameClass.prototype.determineEggRarity = function (this: ThisGame) {
        const masteryEggBonus = (this.getMasteryBonus ? (this.getMasteryBonus('egg_rare_chance') || 0) : 0) * 100;
        const roll = Math.random() * 100;
        let cumulative = 0;

        const entries = Object.entries(RARITY_CHANCES);
        for (let i = 0; i < entries.length; i++) {
            const entry = entries[i];
            if (!entry) continue;
            const [rarity, chance] = entry;
            let adjusted = chance;
            if (rarity === RARITY.COMMON && masteryEggBonus > 0) {
                adjusted = Math.max(50, chance - masteryEggBonus);
            } else if (rarity !== RARITY.COMMON && masteryEggBonus > 0) {
                adjusted = chance + (masteryEggBonus / (entries.length - 1));
            }
            cumulative += adjusted;
            if (roll <= cumulative) return rarity;
        }
        return RARITY.COMMON;
    };

    GameClass.prototype.addEgg = function (this: ThisGame, rarity: string) {
        (this.eggs as unknown as Record<string, number>)[rarity] = ((this.eggs as unknown as Record<string, number>)[rarity] ?? 0) + 1;
        if ((this as unknown as Record<string, unknown>)._lastCombatEggs && typeof (this as unknown as Record<string, unknown>)._lastCombatEggs === 'object') {
            ((this as unknown as Record<string, unknown>)._lastCombatEggs as Record<string, number>)[rarity] = (((this as unknown as Record<string, unknown>)._lastCombatEggs as Record<string, number>)[rarity] || 0) + 1;
        }
        logMessage(this.t('log.eggObtained', { rarity }));
    };

    GameClass.prototype.openEgg = function (this: ThisGame, rarity: string, fromIncubator: boolean = false, options: Record<string, unknown> = {}) {
        const silent = !!options.silent;
        const source = options.source || (fromIncubator ? 'incubator' : 'manual');
        const slotIndex = Number.isInteger(options.slotIndex) ? options.slotIndex : null;
        const offline = !!options.offline;
        if (!fromIncubator) {
            if (((this.eggs as unknown as Record<string, number>)[rarity] ?? 0) <= 0) {
                if (!silent) logMessage(this.t('log.noEggAvailable'));
                return { ok: false, reason: 'no_egg', rarity, source, slotIndex };
            }
            (this.eggs as unknown as Record<string, number>)[rarity] = ((this.eggs as unknown as Record<string, number>)[rarity] ?? 0) - 1;
        }

        // 1. Mise ? jour des stats et qu?tes d'ouverture
        this.stats.eggsOpened++;
        this.checkAchievements('eggsOpened');
        this.checkSpecialQuests('eggsOpened');

        if (!silent) {
            logMessage(this.t('log.openingEgg', { rarity }));
        }

        // 2. G?n?ration de la cr?ature
        const egg = new Egg(rarity);
        const creature = egg.open() as unknown as CreatureData;
        assignRegionalArcId(
            creature,
            typeof this.getCurrentRegionId === 'function' ? this.getCurrentRegionId() : 'kanto',
        );
        if (typeof this.registerCreatureMovesForFamily === 'function') {
            this.registerCreatureMovesForFamily(creature);
        }
        if (typeof this.registerCreatureNaturesForFamily === 'function') {
            this.registerCreatureNaturesForFamily(creature);
        }

        // --- D?BLOCAGE D'ATTAQUE GLOBAL ---
        if (typeof this.tryUnlockMoveFromCaptureOrEgg === 'function') {
            const moveToUnlock = creature.getMove!();
            const unlockedMove = this.tryUnlockMoveFromCaptureOrEgg(creature.name, moveToUnlock, true);
            if (unlockedMove && !silent && typeof toast !== 'undefined') {
                const moveKey = typeof unlockedMove === 'string' ? unlockedMove : moveToUnlock;
                const moveLabel = typeof this.getLocalizedMoveNamePlain === 'function'
                    ? this.getLocalizedMoveNamePlain(moveKey)
                    : moveKey;
                toast.info(this.t('toast.newMoveTitle'), this.t('toast.newMoveFamilyBody', { name: creature.name, move: moveLabel }));
            }
        }

        if (typeof this.tryUnlockNatureFromCaptureOrEgg === 'function') {
            const unlockedNature = this.tryUnlockNatureFromCaptureOrEgg(creature.name, true);
            if (unlockedNature && !silent && typeof toast !== 'undefined') {
                const natureKey = typeof unlockedNature === 'string' ? unlockedNature : '';
                const natureLabel = typeof this.getLocalizedNatureName === 'function'
                    ? this.getLocalizedNatureName(natureKey)
                    : natureKey;
                toast.info(this.t('toast.newNatureTitle'), this.t('toast.newNatureFamilyBody', { name: creature.name, nature: natureLabel }));
            }
        }

        // 3. Gestion Pok?dex
        const pokedexKey = creature.name + "_" + creature.type + "_" + creature.rarity;
        const wasNewDiscovery = !this.pokedex[pokedexKey];
        const wasNewShinyDiscovery = creature.isShiny && (!this.pokedex[pokedexKey] || !this.pokedex[pokedexKey].hasShiny);
        if (!this.pokedex[pokedexKey]) {
            this.pokedex[pokedexKey] = createPokedexEntryFromCapture({
                name: creature.name,
                type: creature.type,
                rarity: creature.rarity,
                isShiny: !!creature.isShiny,
                isShadow: !!creature.isShadow,
            });
            logMessage(this.t('log.pokedexNew', { name: creature.name, shiny: creature.isShiny ? ' SHINY' : '' }));
            this.checkSpecialQuests('new_discovery');
        } else {
            applyPokedexCaptureEntry(this.pokedex[pokedexKey], {
                isShiny: !!creature.isShiny,
                isShadow: !!creature.isShadow,
            });
        }

        // 4. Gestion Shiny & L?gendaire (Feedback)
        if (creature.isShiny) {
            this.stats.shiniesObtained++;
            this.checkAchievements('shiniesObtained');
            this.checkSpecialQuests('shiniesObtained');
            if (!silent) toast.shiny(this.t('toast.shinyEggTitle'), this.t('toast.shinyEggBody', { name: creature.name }));
        }

        if (typeof this.recordPerfectCreatureObtained === 'function') {
            this.recordPerfectCreatureObtained(creature);
        } else {
            const isPerfectEgg = typeof this.isCreaturePerfect === 'function' && this.isCreaturePerfect(creature);
            if (isPerfectEgg) {
                this.stats.perfectIvCount++;
                this.checkAchievements('perfectIvCount');
                if (creature.isShiny) {
                    this.stats.perfectShinyCount++;
                    this.checkAchievements('perfectShinyCount');
                }
            }
            this.trackHolyGrailCreature(creature);
        }

        if (creature.rarity === RARITY.LEGENDARY) {
            this.checkSpecialQuests('legendary_obtained');
            if (!creature.isShiny) {
                if (!silent) toast.legendary(this.t('toast.legendaryEggTitle'), this.t('toast.legendaryEggBody', { name: creature.name }));
            }
        }

        // 5. Recherche de doublon (Fusion)
        // Compte le type obtenu même si la cr?ature est imm?diatement fusionn?e.
        this.checkSpecialQuests('creature_obtained', {
            creatureType: creature.type,
            secondaryType: creature.secondaryType
        });
        const existingCreature = this.findCreatureByName(creature.name, creature.isShiny, creature.isShadow);

        if (existingCreature) {
            // â… APPEL DE LA FUSION CENTRALIS?E
            const result = this.processFusion(creature, existingCreature);

            if (!silent) logMessage(this.t('log.duplicateRecycled', { name: creature.name, shards: result.shards }) + (result.ivImproved ? (' ' + this.t('log.duplicateIvImproved')) : '') + (result.becameShiny ? (' ' + this.t('log.duplicateBecameShiny')) : ''));





            // Toast de feedback
            if (result.improved) {
                if (!silent) toast.success(this.t('toast.fusionSuccessTitle'), this.t('toast.fusionSuccessBody', {
                    name: existingCreature.name,
                    shards: result.shards,
                    ivSuffix: result.ivImproved ? ' IVs ameliorees' : ''
                }));
            } else {
                // Optionnel : Toast discret pour le farm
                // toast.info("Doublon", `+${result.shards} Shards`); 
            }

            // La 'creature' temporaire est abandonn?e au Garbage Collector ici

        } else {
            // CE N'EST PAS UN DOUBLON -> Ajout ? l'équipe/stockage puis ?v?nements
            this.stats.creaturesObtained++;
            const maxTeamSize = getMaxTeamSize(this);
            if (this.playerTeam.length < maxTeamSize) {
                this.playerTeam.push(creature);
            } else {
                this.storage.push(creature);
            }
            this.checkSpecialQuests('creature_hatched');
            if (creature.rarity === 'rare') {
                this.checkSpecialQuests('rareObtained', { rarity: 'rare' });
            }
        }

        if (source === 'incubator') {
            this.checkSpecialQuests('incubator_hatched', { rarity: creature.rarity, slotIndex });
            if (this.getRarityValue(creature.rarity) >= this.getRarityValue(RARITY.RARE)) {
                this.checkSpecialQuests('incubator_hatched_rare_plus', { rarity: creature.rarity, slotIndex });
            }
            if (creature.rarity === RARITY.EPIC) {
                this.checkSpecialQuests('incubator_hatched_epic', { rarity: creature.rarity, slotIndex });
            }
            if (creature.rarity === RARITY.LEGENDARY) {
                this.checkSpecialQuests('incubator_hatched_legendary', { rarity: creature.rarity, slotIndex });
            }
        }

        // 6. Affichage final
        // âÅ¡Â ïÂ¸Â Pas de modale d'?closion en mode offline (rattrapage)
        const shouldShowAutoEggMiniModal = !!this.notifyEggHatch;

        if (!offline && !silent) {
            // Ouverture manuelle (inventaire d'oeufs ou clic sur un incubateur pret) :
            // toujours la grande modal complete.
            this.showEggHatchModal(creature, rarity);
        } else {
            // Cas silencieux : autoincubation en ligne
            // minimodal legere uniquement pour les incubateurs, si l'option est activee.
            if (!offline && source === 'incubator' && silent && shouldShowAutoEggMiniModal) {
                this.showAutoEggHatchMiniModal(creature, rarity);
            }
            // Ne pas re-rendre toute l'UI pour chaque ?uf en simulation offline ? catastrophique en perf
            if (!offline) this.updateDisplay(['eggs', 'incubators', 'items', 'team', 'pokedex']);
        }

        invalidateResonanceCache(this);

        return {
            ok: true,
            source,
            slotIndex,
            rarity: creature.rarity,
            creatureName: creature.name,
            isShiny: !!creature.isShiny,
            creatureType: creature.type,
            secondaryType: creature.secondaryType,
            wasNewDiscovery: !!wasNewDiscovery,
            wasNewShinyDiscovery: !!wasNewShinyDiscovery
        };
    };

    GameClass.prototype.showEggHatchModal = async function (this: ThisGame, creature: Record<string, unknown>, rarity: string) {
        if ((this as unknown as Record<string, unknown>).isOfflineSimulating) return;

        const c = creature as unknown as CreatureData;
        const contentClass = c.isShiny ? 'shiny' : (c.rarity === RARITY.LEGENDARY ? 'legendary' : '');
        const displayRarity = coalesceStr(c.rarity, coalesceStr(rarity, RARITY.COMMON));
        const html = buildEggHatchCreatureModalHtml(this, c);

        try {
            await showEggHatch(html, { contentClass, rarity: displayRarity });
        } catch (err) {
            console.error('[eggHatch] show failed:', err);
        }
    };

    GameClass.prototype.buildEggHatchDisplayPayload = function (this: ThisGame, creature: Record<string, unknown>, rarity: string) {
        const c = creature as unknown as CreatureData;
        const displayRarity = coalesceStr(c.rarity, coalesceStr(rarity, RARITY.COMMON));

        return {
            data: {
                rarity: displayRarity,
                rarityBadgeLabel: this.getEggRarityBadgeLabel(displayRarity),
                spriteUrl: getPokemonSpriteUrl(c.name, c.isShiny, false),
                name: c.name,
            },
            contentClass: c.isShiny ? 'shiny' : (displayRarity === RARITY.LEGENDARY ? 'legendary' : '')
        };
    };

    GameClass.prototype.showAutoEggHatchMiniModal = function (this: ThisGame, creature: Record<string, unknown>, rarity: string) {
        if ((this as unknown as Record<string, unknown>).isOfflineSimulating) return;
        const payload = this.buildEggHatchDisplayPayload(creature, rarity);
        const displayRarity = coerceStr((payload.data as { rarity?: string }).rarity, RARITY.COMMON);
        let container = document.getElementById('autoEggHatchMiniContainer');
        if (!container) {
            container = document.createElement('div');
            container.id = 'autoEggHatchMiniContainer';
            container.className = 'auto-egg-hatch-mini-container';
            document.body.appendChild(container);
        }

        const card = document.createElement('div');
        card.className = `auto-egg-hatch-mini quest-completion-content ${coerceStr(payload.contentClass, '')} rarity-${displayRarity}`;
        // Minimodal : contenu all?g? (raret?, nom, sprite)
        card.innerHTML = renderEggHatchModalContentMini(payload.data as Record<string, unknown>);
        const actionBtn = card.querySelector('.btn-super-confirm');
        if (actionBtn) actionBtn.remove();
        container.prepend(card);

        while (container.children.length > 3) {
            container.removeChild(container.lastElementChild!);
        }

        requestAnimationFrame(() => card.classList.add('show'));
        setTimeout(() => {
            card.classList.remove('show');
            setTimeout(() => {
                if (card.parentNode) card.parentNode.removeChild(card);
            }, 220);
        }, 3200);
    };

    GameClass.prototype.closeEggHatchModal = function (this: ThisGame) {
        closeEggHatch();
        this.updateDisplay(['eggs', 'incubators', 'items', 'team']);
    };

    GameClass.prototype.handleIncubatorContainerClick = function (this: ThisGame, e: MouseEvent) {
        const target = e.target as HTMLElement | null;
        if (!target?.closest('#incubatorsContainer')) return;

        const autoBtn = target.closest<HTMLButtonElement>('.incubator-auto-toggle');
        if (autoBtn && !autoBtn.disabled) {
            e.stopPropagation();
            const slotIndex = parseInt(autoBtn.getAttribute('data-slot') || '0', 10);
            const currentState = this.getAutoIncubationSettings(slotIndex).enabled;
            this.setAutoIncubationEnabled(slotIndex, !currentState);
            return;
        }

        const prioBtn = target.closest<HTMLButtonElement>('.incubator-priority-chip');
        if (prioBtn && !prioBtn.disabled) {
            e.stopPropagation();
            const slotIndex = parseInt(prioBtn.getAttribute('data-slot') || '0', 10);
            this.cycleIncubatorPriority(slotIndex);
            return;
        }

        const slotTarget = target.closest<HTMLElement>('.incubator-slot');
        if (!slotTarget) return;

        const slotIndex = parseInt(slotTarget.getAttribute('data-slot') || '0', 10);
        const isReady = slotTarget.classList.contains('incubator-ready');
        const hasEgg = slotTarget.getAttribute('data-has-egg') === 'true';

        if (isReady) {
            e.stopPropagation();
            this.openIncubatorEgg(slotIndex);
        } else if (hasEgg && !isReady) {
            e.stopPropagation();
            const ms = this.getIncubatorClickReductionMs();
            const incubatorSlot = this.incubators[slotIndex] as IncubatorSlot;
            incubatorSlot.startTime = (incubatorSlot.startTime || 0) - ms;
            (this.stats as unknown as Record<string, number>).incubatorClickTotalMs =
                ((this.stats as unknown as Record<string, number>).incubatorClickTotalMs || 0) + ms;
            this.checkAchievements('incubatorClickTotalMs');
            showFloatingText('-' + ms + 'ms', slotTarget, 'ft-speedup');
            this.updateIncubatorsDisplay();
        } else if (!hasEgg && slotIndex < this.getMaxIncubatorSlots()) {
            e.stopPropagation();
            this.openChooseEggModal(slotIndex);
        }
    };

    GameClass.prototype.setupIncubatorHandler = function (this: ThisGame) {
        if ((this as unknown as Record<string, unknown>)._incubatorHandlerRegistered) return;
        (this as unknown as Record<string, unknown>)._incubatorHandlerRegistered = true;
        document.addEventListener('click', (e: MouseEvent) => {
            this.handleIncubatorContainerClick(e);
        });
    };

    GameClass.prototype.initIncubatorsDOM = function (this: ThisGame, container: HTMLElement) {
        container.innerHTML = '';
        container.setAttribute('data-initialized', 'true');
        const displayedCount = this.getDisplayedIncubatorSlotCount();
        container.setAttribute('data-slot-count', String(displayedCount));

        for (let i = 0; i < displayedCount; i++) {
            const slotEl = document.createElement('div');
            slotEl.className = 'incubator-slot';
            slotEl.setAttribute('data-slot', String(i));

            slotEl.innerHTML = `
                <div class="incubator-slot-inner" style="display:none;">
                    <span class="incubator-lock-label">${this.getIncubatorLockLabel(i)}</span>
                </div>
                <div class="incubator-content" style="display:none;">
                    <div class="incubator-capsule">
                        <div class="incubator-body">
                            <div class="incubator-progress-wrap" style="--progress: 0;">
                                <div class="incubator-ring"></div>
                                <div class="incubator-egg-center">
                                    <img src="" class="egg-sprite incubator-egg-breath" alt="${this.t('bag.eggAlt', { rarity: '' }).trim()}" style="display:none;">
                                </div>
                            </div>
                        </div>
                        <div class="incubator-footer">
                            <span class="incubator-timer">--:--</span>
                        </div>
                    </div>
                </div>
                <div class="incubator-auto-controls" style="display:none;">
                    <button type="button" class="incubator-auto-toggle" data-slot="${i}">${this.t('state.off')}</button>
                    <button type="button" class="incubator-priority-chip" data-slot="${i}">${this.getRarityLabel(RARITY.COMMON)}</button>
                </div>
            `;
            container.appendChild(slotEl);
        }
    };

    GameClass.prototype.updateIncubatorsDisplay = function (this: ThisGame) {
        const container = document.getElementById('incubatorsContainer');
        if (!container) return;
        if (container.getAttribute('data-svelte-ui') === '1') {
            void import('./src/lib/bagSnapshot.js').then((m) => m.notifyBagEggSectionsChanged(this));
            return;
        }

        const displayedCount = this.getDisplayedIncubatorSlotCount();
        if (container.getAttribute('data-initialized') !== 'true'
            || container.children.length !== displayedCount) {
            this.initIncubatorsDOM(container);
        } else {
            container.setAttribute('data-slot-count', String(displayedCount));
        }

        this.ensureIncubatorArraySize();
        const maxSlots = this.getMaxIncubatorSlots();

        for (let i = 0; i < displayedCount; i++) {
            const slotEl = container.children[i] as HTMLElement;
            if (!slotEl) continue;
            const slot = this.incubators[i];
            const isAutoUnlocked = this.isAutoIncubationUnlockedForSlot(i);
            const autoSettings = this.getAutoIncubationSettings(i);

            const innerLock = slotEl.querySelector('.incubator-slot-inner') as HTMLElement;
            const contentWrap = slotEl.querySelector('.incubator-content') as HTMLElement;
            const autoControlsWrap = slotEl.querySelector('.incubator-auto-controls') as HTMLElement;

            if (i >= maxSlots) {
                // Incubateur verrouill?
                if (slotEl.className !== 'incubator-slot incubator-locked') slotEl.className = 'incubator-slot incubator-locked';
                if (innerLock.style.display !== 'block') innerLock.style.display = 'block';
                if (contentWrap.style.display !== 'none') contentWrap.style.display = 'none';
                if (autoControlsWrap.style.display !== 'none') autoControlsWrap.style.display = 'none';
                const lockLabel = slotEl.querySelector('.incubator-lock-label') as HTMLElement;
                const expectedLockLabel = this.getIncubatorLockLabel(i);
                if (lockLabel && lockLabel.textContent !== expectedLockLabel) lockLabel.textContent = expectedLockLabel;
                slotEl.removeAttribute('data-has-egg');
            } else {
                // Incubateur D?bloqu?
                if (innerLock.style.display !== 'none') innerLock.style.display = 'none';
                if (contentWrap.style.display !== 'block') contentWrap.style.display = 'block';

                const hasEgg = !!slot;
                slotEl.setAttribute('data-has-egg', hasEgg ? 'true' : 'false');

                const remaining = hasEgg ? this.getIncubatorRemainingMs(i) : 0;
                const ready = hasEgg && remaining === 0;
                const durationMs = hasEgg ? (slot.durationMs || 1) : 1;
                const progress = hasEgg ? Math.min(1, 1 - remaining / durationMs) : 0;
                const rarity = hasEgg ? slot.rarity : 'common';

                let filterClass = '';
                if (rarity === 'rare') filterClass = 'egg-filter-rare';
                else if (rarity === 'epic') filterClass = 'egg-filter-epic';
                else if (rarity === 'legendary') filterClass = 'egg-filter-legendary';

                const expectedClass = 'incubator-slot rarity-' + rarity + (ready ? ' incubator-ready' : '');
                if (slotEl.className !== expectedClass) slotEl.className = expectedClass;

                const tooltipText = this.getIncubatorSlotTooltip(i);
                if (slotEl.title !== tooltipText) slotEl.title = tooltipText;

                // Capsule & Progress
                const capsule = slotEl.querySelector('.incubator-capsule') as HTMLElement;
                const expectedCapsuleClass = `incubator-capsule rarity-${rarity}`;
                if (capsule.className !== expectedCapsuleClass) capsule.className = expectedCapsuleClass;

                const progressWrap = slotEl.querySelector('.incubator-progress-wrap') as HTMLElement;
                progressWrap.style.setProperty('--progress', String(progress));

                // Image Oeuf
                const eggImg = slotEl.querySelector('.egg-sprite') as HTMLImageElement;
                if (hasEgg) {
                    const eggSpriteUrl = `img/${rarity}-egg.png`;
                    if (eggImg.getAttribute('src') !== eggSpriteUrl) eggImg.src = eggSpriteUrl;
                    const expectedImgClass = `egg-sprite incubator-egg-breath ${filterClass}`;
                    if (eggImg.className !== expectedImgClass) eggImg.className = expectedImgClass;
                    if (eggImg.style.display !== 'block') eggImg.style.display = 'block';
                } else {
                    if (eggImg.style.display !== 'none') eggImg.style.display = 'none';
                }

                // Timer texte
                const timerEl = slotEl.querySelector('.incubator-timer') as HTMLElement;
                const timeStr = hasEgg ? (ready ? this.t('bag.incubatorReady') : this.formatMsAsTime(remaining)) : '--:--';
                if (timerEl.textContent !== timeStr) timerEl.textContent = timeStr;

                // Contr?les Auto
                if (autoControlsWrap.style.display !== 'flex') {
                    autoControlsWrap.style.display = 'flex';
                }
                const expectedAutoClass = `incubator-auto-controls ${isAutoUnlocked ? '' : 'incubator-auto-controls-locked'}`;
                if (autoControlsWrap.className !== expectedAutoClass) autoControlsWrap.className = expectedAutoClass;

                const autoBtn = autoControlsWrap.querySelector('.incubator-auto-toggle') as HTMLButtonElement;
                autoBtn.disabled = !isAutoUnlocked;
                const expectedAutoBtnClass = `incubator-auto-toggle ${autoSettings.enabled ? 'incubator-auto-on' : 'incubator-auto-off'}`;
                if (autoBtn.className !== expectedAutoBtnClass) autoBtn.className = expectedAutoBtnClass;
                const expectedAutoBtnText = autoSettings.enabled ? this.t('state.on') : this.t('state.off');
                if (autoBtn.textContent !== expectedAutoBtnText) autoBtn.textContent = expectedAutoBtnText;

                const prioBtn = autoControlsWrap.querySelector('.incubator-priority-chip') as HTMLButtonElement;
                prioBtn.disabled = !isAutoUnlocked;
                const priorityCode = this.getAutoIncubationSettings(i).priorityOrder[0] || RARITY.COMMON;
                const priorityLabel = this.getSlotPriorityLabel(i);
                const priorityClass = `priority-${String(priorityCode || '').toLowerCase()}`;
                const expectedPrioClass = `incubator-priority-chip ${priorityClass}`;
                if (prioBtn.className !== expectedPrioClass) prioBtn.className = expectedPrioClass;
                if (prioBtn.textContent !== priorityLabel) prioBtn.textContent = priorityLabel;
            }
        }
    };

    GameClass.prototype.initEggsDOM = function (this: ThisGame, container: HTMLElement) {
        container.innerHTML = '';
        container.setAttribute('data-initialized', 'true');

        const rarities = ['common', 'rare', 'epic', 'legendary'];
        rarities.forEach(rarity => {
            const eggElement = document.createElement('div');
            eggElement.className = `ball-item rarity-${rarity} egg-item-${rarity} egg-clickable`;
            eggElement.setAttribute('data-rarity', rarity);
            eggElement.setAttribute('data-egg-rarity', rarity);
            eggElement.style.display = 'none';

            let filterClass = "";
            if (rarity === 'rare') filterClass = "egg-filter-rare";
            else if (rarity === 'epic') filterClass = "egg-filter-epic";
            else if (rarity === 'legendary') filterClass = "egg-filter-legendary";

            const eggSpriteUrl = `img/${rarity}-egg.png`;

            eggElement.innerHTML = `
                <div class="rarity-label ${rarity}" style="pointer-events: none; margin-bottom:2px; font-size:9px; padding:1px 4px;">
                    ${this.getRarityLabel(rarity).toUpperCase()}
                </div>
                <img src="${eggSpriteUrl}" class="egg-sprite ${filterClass}" alt="${this.t('bag.eggAlt', { rarity: this.getRarityLabel(rarity) })}">
                <div class="egg-count-label">x0</div>
                <div class="egg-incubator-hint">${this.t('bag.placeInIncubator')}</div>
            `;
            container.appendChild(eggElement);
        });

        const emptyMessage = document.createElement('div');
        emptyMessage.className = 'empty-eggs-message';
        emptyMessage.style.display = 'none';
        emptyMessage.innerHTML = `
            <img src="img/common-egg.png" class="empty-eggs-message-icon" alt="">
            <div class="egg-empty-title">${this.t('bag.eggsEmptyTitle')}</div>
            <div class="egg-empty-hint">${this.t('bag.eggsEmptyHint')}</div>
        `;
        container.appendChild(emptyMessage);
    };

    GameClass.prototype.syncEggsInventoryDisplay = function (this: ThisGame) {
        const eggsContainer = document.getElementById('ballsContainer');

        if (!eggsContainer) return;
        if (eggsContainer.getAttribute('data-svelte-ui') === '1') {
            void import('./src/lib/bagSnapshot.js').then((m) => m.notifyBagEggSectionsChanged(this));
            return;
        }

        if (eggsContainer.getAttribute('data-initialized') !== 'true') {
            this.initEggsDOM(eggsContainer);
        }

        const totalEggs = Object.values(this.eggs).reduce((sum, count) => sum + (count), 0);

        const rarities = ['common', 'rare', 'epic', 'legendary'];
        rarities.forEach(rarity => {
            const count = (this.eggs as unknown as Record<string, number>)[rarity] || 0;
            const eggElement = eggsContainer.querySelector<HTMLElement>(`.egg-item-${rarity}`);
            if (eggElement) {
                const rarityLabel = eggElement.querySelector('.rarity-label');
                const expectedRarityText = this.getRarityLabel(rarity).toUpperCase();
                if (rarityLabel && rarityLabel.textContent.trim() !== expectedRarityText) rarityLabel.textContent = expectedRarityText;

                const eggImg = eggElement.querySelector('.egg-sprite');
                const expectedAlt = this.t('bag.eggAlt', { rarity: this.getRarityLabel(rarity) });
                if (eggImg && eggImg.getAttribute('alt') !== expectedAlt) eggImg.setAttribute('alt', expectedAlt);

                const hint = eggElement.querySelector('.egg-incubator-hint');
                const expectedHint = this.t('bag.placeInIncubator');
                if (hint && hint.textContent !== expectedHint) hint.textContent = expectedHint;

                if (count > 0) {
                    if (eggElement.style.display !== 'block') eggElement.style.display = 'block';
                    const label = eggElement.querySelector('.egg-count-label');
                    const countTxt = `x${count}`;
                    if (label && label.textContent.trim() !== countTxt) label.textContent = countTxt;
                } else {
                    if (eggElement.style.display !== 'none') eggElement.style.display = 'none';
                }
            }
        });

        const emptyMessage = eggsContainer.querySelector<HTMLElement>('.empty-eggs-message');
        if (emptyMessage) {
            const titleEl = emptyMessage.querySelector('.egg-empty-title');
            const hintEl = emptyMessage.querySelector('.egg-empty-hint');
            const emptyTitle = this.t('bag.eggsEmptyTitle');
            const emptyHint = this.t('bag.eggsEmptyHint');
            if (titleEl && titleEl.textContent !== emptyTitle) titleEl.textContent = emptyTitle;
            if (hintEl && hintEl.textContent !== emptyHint) hintEl.textContent = emptyHint;

            if (totalEggs === 0) {
                if (emptyMessage.style.display !== 'block') emptyMessage.style.display = 'block';
            } else {
                if (emptyMessage.style.display !== 'none') emptyMessage.style.display = 'none';
            }
        }
    };

    GameClass.prototype.updateEggsDisplay = function (this: ThisGame) {
        this.syncEggsInventoryDisplay();
        publishBagEggMetaChanged();
    };
}
