<script lang="ts">
  import { game } from '../../gameManager.ts';
  import type { GameRuntime } from '../types/game.js';
  import { ALL_ITEMS } from '../../constants/balance/shopAndAggregation.js';
  import {
    getDynamaxDurationMs,
    getDynamaxHpMult,
  } from '../../constants/balance/dynamax.ts';
  import {
    DYNAMAX_MONEY_SLIDER_NORM_MAX,
    getDynamaxUpgradeLevel,
    getDynamaxUpgradePreview,
    getDynamaxUpgradeProgress,
    listDynamaxUpgradeItemKeys,
    moneyAmountToNorm,
    moneyNormToAmount,
  } from '../lib/dynamaxLogic.ts';
  import { formatNumber } from '../../formatters.ts';
  import { GameEventType as Evt } from '../bus/events.js';
  import { useFacadeSubscription } from '../lib/useFacadeSubscription.ts';
  import { useGameLanguageTick } from '../lib/useGameLanguageTick.svelte.ts';
  import { resources } from '../stores/resources.svelte.ts';
  import { untrack } from 'svelte';

  let {
    open = $bindable(false),
  }: {
    open?: boolean;
  } = $props();

  const { trackGameLanguage } = useGameLanguageTick();

  let selectedCounts = $state<Record<string, number>>({});
  let selectedMoneyState = $state(0);
  let refreshTick = $state(0);

  useFacadeSubscription(
    [Evt.RESOURCES_CHANGED, Evt.BAG_CHANGED, Evt.TEAM_CHANGED, Evt.STATE_UPDATED],
    () => {
      refreshTick += 1;
    },
  );

  $effect(() => {
    if (!open) return;
    untrack(() => {
      resetSelection();
      refreshTick += 1;
    });
  });

  function t(key: string, fallback: string, params?: Record<string, string | number>): string {
    trackGameLanguage();
    const gm = game as GameRuntime | null;
    if (!gm?.t) {
      let out = fallback;
      if (params) {
        for (const [k, v] of Object.entries(params)) {
          out = out.replace(`{${k}}`, String(v));
        }
      }
      return out;
    }
    let got = gm.t(key, params);
    if (!got || got === key) got = fallback;
    if (params) {
      for (const [k, v] of Object.entries(params)) {
        got = got.replace(`{${k}}`, String(v));
      }
    }
    return got;
  }

  function bump(): void {
    refreshTick += 1;
  }

  function resetSelection(): void {
    selectedCounts = {};
    selectedMoneyState = 0;
  }

  let preview = $derived.by(() => {
    void refreshTick;
    void open;
    trackGameLanguage();
    const gm = game as GameRuntime | null;
    if (!gm) {
      return getDynamaxUpgradePreview({
        dynamaxState: { unlocked: false, configured: false, upgradeLevel: 0 },
        combatState: 'idle',
        money: 0,
        items: {},
      } as GameRuntime);
    }
    return getDynamaxUpgradePreview(gm);
  });

  let progress = $derived.by(() => {
    void refreshTick;
    void open;
    trackGameLanguage();
    const gm = game as GameRuntime | null;
    if (!gm) {
      return getDynamaxUpgradeProgress({
        dynamaxState: { unlocked: false, configured: false, upgradeLevel: 0 },
        money: 0,
        items: {},
      } as GameRuntime);
    }
    return getDynamaxUpgradeProgress(gm);
  });

  let wallet = $derived.by(() => {
    void refreshTick;
    void open;
    void resources.pokedollars;
    trackGameLanguage();
    const gm = game as GameRuntime | null;
    return Math.max(0, Number(gm?.pokedollars) || Number(resources.pokedollars) || 0);
  });

  let moneyRemaining = $derived.by(() => {
    if (progress.atMax || progress.moneyNeed == null) return 0;
    return Math.max(0, progress.moneyNeed - progress.moneyHave);
  });

  let itemsRemaining = $derived.by(() => {
    if (progress.atMax || progress.itemsNeed == null) return 0;
    return Math.max(0, progress.itemsNeed - progress.itemsHave);
  });

  let moneySliderMax = $derived(Math.max(0, Math.min(wallet, moneyRemaining)));

  let selectedMoney = $derived(Math.min(selectedMoneyState, moneySliderMax));
  let moneySliderNorm = $derived(moneyAmountToNorm(selectedMoney, moneySliderMax));

  let level = $derived(preview.currentLevel);
  let hpMult = $derived(getDynamaxHpMult(level));
  let durationSec = $derived(Math.round(getDynamaxDurationMs(level) / 1000));
  let nextHpMult = $derived(
    preview.nextLevel != null ? getDynamaxHpMult(preview.nextLevel) : null,
  );
  let nextDurationSec = $derived(
    preview.nextLevel != null ? Math.round(getDynamaxDurationMs(preview.nextLevel) / 1000) : null,
  );

  let itemRows = $derived.by(() => {
    void refreshTick;
    trackGameLanguage();
    const gm = game as GameRuntime | null;
    const items = gm?.items ?? {};
    return listDynamaxUpgradeItemKeys().map((key) => {
      const qty = Number(items[key]) || 0;
      const def = (ALL_ITEMS as Record<string, { name?: string; img?: string }>)[key];
      const name = gm?.getLocalizedItemName
        ? gm.getLocalizedItemName(key, def?.name || key, def as never)
        : (def?.name || key);
      return {
        key,
        qty,
        name,
        img: def?.img || '',
        selected: selectedCounts[key] ?? 0,
      };
    }).filter((row) => row.qty > 0 || row.selected > 0);
  });

  let selectedItemsTotal = $derived(
    Object.values(selectedCounts).reduce((sum, n) => sum + Math.max(0, Math.floor(n) || 0), 0),
  );

  let canConfirm = $derived.by(() => {
    void refreshTick;
    if (!preview.canUpgrade) return false;
    return selectedMoney > 0 || selectedItemsTotal > 0;
  });

  function close(): void {
    resetSelection();
    open = false;
  }

  function onBackdrop(e: MouseEvent): void {
    if (e.target === e.currentTarget) close();
  }

  function onKeydown(e: KeyboardEvent): void {
    if (e.key === 'Escape') close();
  }

  function otherSelected(exceptKey: string): number {
    let sum = 0;
    for (const [k, v] of Object.entries(selectedCounts)) {
      if (k === exceptKey) continue;
      sum += Math.max(0, Math.floor(v) || 0);
    }
    return sum;
  }

  function maxSelectableFor(key: string, owned: number): number {
    const room = Math.max(0, itemsRemaining - otherSelected(key));
    return Math.min(owned, room);
  }

  function onItemClick(key: string, owned: number, e: MouseEvent): void {
    const max = maxSelectableFor(key, owned);
    if (max <= 0) return;
    if (e.ctrlKey || e.metaKey) {
      selectedCounts = { ...selectedCounts, [key]: max };
      return;
    }
    const cur = selectedCounts[key] ?? 0;
    if (cur >= max) return;
    selectedCounts = { ...selectedCounts, [key]: cur + 1 };
  }

  function removeItemClick(key: string, e: MouseEvent): void {
    e.preventDefault();
    const cur = selectedCounts[key] ?? 0;
    if (cur <= 1) {
      const next = { ...selectedCounts };
      delete next[key];
      selectedCounts = next;
      return;
    }
    selectedCounts = { ...selectedCounts, [key]: cur - 1 };
  }

  function onMoneySlider(e: Event): void {
    const el = e.currentTarget as HTMLInputElement;
    const norm = Math.max(0, Math.min(DYNAMAX_MONEY_SLIDER_NORM_MAX, Math.floor(Number(el.value) || 0)));
    selectedMoneyState = moneyNormToAmount(norm, moneySliderMax);
  }

  function confirmDeposit(): void {
    const gm = game as GameRuntime | null;
    if (!gm?.depositDynamaxUpgrade || !canConfirm) return;
    const items: Record<string, number> = {};
    for (const [k, v] of Object.entries(selectedCounts)) {
      const n = Math.max(0, Math.floor(v) || 0);
      if (n > 0) items[k] = n;
    }
    const ok = gm.depositDynamaxUpgrade({
      money: selectedMoney,
      items,
    });
    bump();
    resetSelection();
    if (ok && getDynamaxUpgradeLevel(gm) >= preview.maxLevel) {
      close();
    }
  }
</script>

{#if open}
  <div
    id="dynamaxUpgradeModal"
    class="stats-modal js-modal-overlay show"
    role="dialog"
    aria-modal="true"
    aria-labelledby="dynamaxUpgradeTitle"
    tabindex="-1"
    onclick={onBackdrop}
    onkeydown={onKeydown}
  >
    <div
      class="stats-content js-modal-content dynamax-upgrade-content"
      data-action="stopPropagation"
      data-action-stop
    >
      <div class="stats-header">
        <h2 id="dynamaxUpgradeTitle">{t('dynamax.upgradeTitle', 'Améliorer la Bande Dynamax')}</h2>
        <button type="button" class="stats-close js-close-modal" onclick={close} aria-label="Close">&times;</button>
      </div>

      <p class="dynamax-upgrade-level">
        {t('dynamax.upgradeLevel', 'Niveau {level} / {max}', {
          level,
          max: preview.maxLevel,
        })}
      </p>

      <div class="dynamax-upgrade-progress-rows">
        <div class="dynamax-upgrade-progress-row">
          <span class="dynamax-upgrade-progress-label">
            {#if progress.atMax}
              {t('dynamax.progressMoneyMax', 'Pokédollars (max)')}
            {:else}
              {t('dynamax.progressMoney', 'Pokédollars {have} / {need}', {
                have: formatNumber(progress.moneyHave),
                need: formatNumber(progress.moneyNeed ?? 0),
              })}
            {/if}
          </span>
          <span
            class="ultimate-slot-pick-tooltip-bar dynamax-upgrade-progress-bar"
            role="progressbar"
            aria-valuemin={0}
            aria-valuemax={100}
            aria-valuenow={Math.round(progress.moneyPct * 100)}
          >
            <span
              class="ultimate-slot-pick-tooltip-bar-fill dynamax-upgrade-progress-fill--money"
              style={`width: ${Math.round(progress.moneyPct * 100)}%`}
            ></span>
          </span>
        </div>
        <div class="dynamax-upgrade-progress-row">
          <span class="dynamax-upgrade-progress-label">
            {#if progress.atMax}
              {t('dynamax.progressItemsMax', 'Items d’évo. (max)')}
            {:else}
              {t('dynamax.progressItems', 'Items d’évo. {have} / {need}', {
                have: formatNumber(progress.itemsHave),
                need: formatNumber(progress.itemsNeed ?? 0),
              })}
            {/if}
          </span>
          <span
            class="ultimate-slot-pick-tooltip-bar dynamax-upgrade-progress-bar"
            role="progressbar"
            aria-valuemin={0}
            aria-valuemax={100}
            aria-valuenow={Math.round(progress.itemsPct * 100)}
          >
            <span
              class="ultimate-slot-pick-tooltip-bar-fill dynamax-upgrade-progress-fill--items"
              style={`width: ${Math.round(progress.itemsPct * 100)}%`}
            ></span>
          </span>
        </div>
      </div>

      <div class="dynamax-upgrade-stats">
        <div>
          <span class="dynamax-upgrade-stat-label">{t('dynamax.statPower', 'PV / dégâts')}</span>
          <span class="dynamax-upgrade-stat-value">
            ×{hpMult.toFixed(1)}
            {#if nextHpMult != null}
              <span class="dynamax-upgrade-arrow">→ ×{nextHpMult.toFixed(1)}</span>
            {/if}
          </span>
        </div>
        <div>
          <span class="dynamax-upgrade-stat-label">{t('dynamax.statDuration', 'Durée')}</span>
          <span class="dynamax-upgrade-stat-value">
            {durationSec}s
            {#if nextDurationSec != null}
              <span class="dynamax-upgrade-arrow">→ {nextDurationSec}s</span>
            {/if}
          </span>
        </div>
      </div>

      {#if preview.nextLevel == null}
        <p class="dynamax-upgrade-max">{t('dynamax.upgradeMax', 'Bande au niveau maximum.')}</p>
      {:else}
        <p class="dynamax-upgrade-cost">
          {t('dynamax.upgradeCost', 'Objectif : {money} $ + {stones} item(s) d’évolution', {
            money: formatNumber(preview.moneyCost ?? 0),
            stones: preview.stoneCost ?? 0,
          })}
        </p>

        <div class="dynamax-upgrade-money-select">
          <div class="dynamax-upgrade-money-select-header">
            <span>{t('dynamax.moneySliderLabel', 'Pokédollars à déposer')}</span>
            <span class="dynamax-upgrade-money-select-value">{formatNumber(selectedMoney)} $</span>
          </div>
          <input
            type="range"
            class="dynamax-upgrade-money-slider"
            min={0}
            max={DYNAMAX_MONEY_SLIDER_NORM_MAX}
            step={1}
            value={moneySliderNorm}
            disabled={moneySliderMax <= 0}
            oninput={onMoneySlider}
          />
          <div class="dynamax-upgrade-money-select-meta">
            <span>0</span>
            <span>{formatNumber(moneySliderMax)}</span>
          </div>
        </div>

        <p class="dynamax-upgrade-pick-label">
          {t('dynamax.upgradePickStone', 'Choisissez un item d’évolution à déposer :')}
        </p>

        {#if itemRows.length === 0}
          <p class="dynamax-upgrade-warn">
            {t('dynamax.upgradeNoStones', 'Pas assez d’items d’évolution.')}
          </p>
        {:else}
          <div class="dynamax-upgrade-stone-grid">
            {#each itemRows as row (row.key)}
              <button
                type="button"
                class="dynamax-upgrade-stone"
                class:dynamax-upgrade-stone--active={row.selected > 0}
                class:dynamax-upgrade-stone--short={row.qty < 1}
                disabled={row.qty < 1}
                onclick={(e) => onItemClick(row.key, row.qty, e)}
                oncontextmenu={(e) => removeItemClick(row.key, e)}
              >
                {#if row.selected > 0}
                  <span class="dynamax-upgrade-stone-selected">{row.selected}</span>
                {/if}
                {#if row.img}
                  <img src={row.img} alt="" class="dynamax-upgrade-stone-img" />
                {/if}
                <span class="dynamax-upgrade-stone-name">{row.name}</span>
                <span class="dynamax-upgrade-stone-qty">×{row.qty}</span>
              </button>
            {/each}
          </div>
        {/if}

        <button
          type="button"
          class="dynamax-upgrade-confirm"
          disabled={!canConfirm}
          onclick={confirmDeposit}
        >
          {t('dynamax.upgradeConfirm', 'Déposer')}
        </button>
      {/if}
    </div>
  </div>
{/if}

