/**
 * Coalesce lazy-list IntersectionObserver callbacks so DOM batches
 * do not mount mid-scroll gesture (incl. inertial momentum).
 */

import { MODAL_OPEN_SELECTOR } from '../ui/breakpoints.ts';
import { isMobilePanelScrolling, onMobileScrollEnd } from './mobileScrollGate.ts';

function isModalOpen(): boolean {
    return typeof document !== 'undefined' && !!document.querySelector(MODAL_OPEN_SELECTOR);
}

let pending: (() => void) | null = null;
let scheduled = false;
let scrollEndHooked = false;

type ChunkedRunner = {
    step: (chunkSize: number) => boolean;
    chunkSize: number;
};

let chunkedPending: ChunkedRunner | null = null;
let chunkedRafId: number | null = null;
let chunkedScrollHooked = false;

function flush(): void {
    scheduled = false;
    const fn = pending;
    pending = null;
    fn?.();
}

function scheduleFlush(): void {
    if (scheduled) return;
    scheduled = true;
    const ric = typeof requestIdleCallback === 'function' ? requestIdleCallback : null;
    if (ric) {
        ric(flush, { timeout: 120 });
    } else {
        requestAnimationFrame(flush);
    }
}

function ensureSimpleScrollEndHook(): void {
    if (scrollEndHooked) return;
    scrollEndHooked = true;
    onMobileScrollEnd(() => {
        if (!pending) return;
        flush();
    });
}

function ensureChunkedScrollEndHook(): void {
    if (chunkedScrollHooked) return;
    chunkedScrollHooked = true;
    onMobileScrollEnd(() => {
        if (!chunkedPending) return;
        startChunkedRunner();
    });
}

function runChunkedFrame(): void {
    chunkedRafId = null;
    const runner = chunkedPending;
    if (!runner) return;

    const more = runner.step(runner.chunkSize);
    if (!more) {
        chunkedPending = null;
        return;
    }

    chunkedRafId = requestAnimationFrame(runChunkedFrame);
}

function startChunkedRunner(): void {
    if (chunkedRafId != null) return;
    chunkedRafId = requestAnimationFrame(runChunkedFrame);
}

/** Run callback once, deferred off the IO intersection frame. */
export function scheduleLazyBatch(cb: () => void): void {
    pending = cb;

    if (isMobilePanelScrolling() && !isModalOpen()) {
        ensureSimpleScrollEndHook();
        return;
    }

    scheduleFlush();
}

/**
 * Expand a lazy list in small chunks per animation frame.
 * `step` receives the chunk size and returns true while more work remains.
 */
export function scheduleLazyBatchChunked(
    step: (chunkSize: number) => boolean,
    chunkSize = 6,
): void {
    chunkedPending = { step, chunkSize };

    if (isMobilePanelScrolling() && !isModalOpen()) {
        ensureChunkedScrollEndHook();
        return;
    }

    startChunkedRunner();
}

/** @internal Vitest only */
export function resetScheduleLazyBatchForTests(): void {
    pending = null;
    scheduled = false;
    scrollEndHooked = false;
    chunkedPending = null;
    if (chunkedRafId != null) {
        cancelAnimationFrame(chunkedRafId);
        chunkedRafId = null;
    }
    chunkedScrollHooked = false;
}
