import type { GameRuntime } from '../types/game.js';
import {
    SAVE_KEY,
    clampSaveSlotId,
    getActiveSaveSlot,
    getSaveSlotMetaById,
} from '../../saveSystem.ts';
import { toast } from '../../toastManager.ts';

export const SAVE_EXPORT_REMINDER_MS = 12 * 60 * 60 * 1000;

export function getSaveExportAtKey(slotId: number): string {
    return `${SAVE_KEY}.lastExportAt.slot.${clampSaveSlotId(slotId)}`;
}

export function getSaveExportReminderShownKey(slotId: number): string {
    return `${SAVE_KEY}.lastExportReminderShown.slot.${clampSaveSlotId(slotId)}`;
}

function readStoredTimestamp(key: string): number {
    if (typeof localStorage === 'undefined') return 0;
    const raw = localStorage.getItem(key);
    const n = Number(raw);
    return Number.isFinite(n) && n > 0 ? n : 0;
}

function writeStoredTimestamp(key: string, value: number): void {
    if (typeof localStorage === 'undefined') return;
    localStorage.setItem(key, String(value));
}

export function recordSaveExport(slotId: number, now = Date.now()): void {
    const normalized = clampSaveSlotId(slotId);
    writeStoredTimestamp(getSaveExportAtKey(normalized), now);
}

export function getEffectiveLastExportAt(slotId: number, now = Date.now()): number {
    const stored = readStoredTimestamp(getSaveExportAtKey(slotId));
    if (stored > 0) return stored;

    const meta = getSaveSlotMetaById(slotId);
    if (meta.createdAt > 0) return meta.createdAt;
    if (meta.updatedAt > 0) return meta.updatedAt;
    return now;
}

export function isSaveExportReminderDue(slotId: number, now = Date.now()): boolean {
    const effectiveLastExport = getEffectiveLastExportAt(slotId, now);
    return now - effectiveLastExport >= SAVE_EXPORT_REMINDER_MS;
}

export function shouldShowSaveExportReminder(slotId: number, now = Date.now()): boolean {
    if (!isSaveExportReminderDue(slotId, now)) return false;

    const effectiveLastExport = getEffectiveLastExportAt(slotId, now);
    const elapsed = now - effectiveLastExport;
    const currentWindowStart = effectiveLastExport
        + Math.floor(elapsed / SAVE_EXPORT_REMINDER_MS) * SAVE_EXPORT_REMINDER_MS;
    const lastShown = readStoredTimestamp(getSaveExportReminderShownKey(slotId));
    return lastShown < currentWindowStart;
}

export function markSaveExportReminderShown(slotId: number, now = Date.now()): void {
    writeStoredTimestamp(getSaveExportReminderShownKey(slotId), now);
}

export function maybeShowSaveExportReminderToast(game: GameRuntime, now = Date.now()): void {
    if (game.bootLoadFailed) return;
    if (typeof document !== 'undefined' && document.body?.classList.contains('save-slot-boot-active')) {
        return;
    }

    const slotId = getActiveSaveSlot();
    const meta = getSaveSlotMetaById(slotId);
    if (!meta.hasData) return;
    if (!shouldShowSaveExportReminder(slotId, now)) return;
    if (typeof toast === 'undefined' || typeof toast.showLeft !== 'function') return;
    if (typeof game.t !== 'function') return;

    markSaveExportReminderShown(slotId, now);
    toast.showLeft({
        title: game.t('toast.saveExportReminderTitle'),
        message: game.t('toast.saveExportReminderBody'),
        type: 'info',
        duration: 0,
        closable: true,
    });
}
