const EMPTY_INVENTORY: BagInventorySnapshot = {
  itemCards: [],
  inventoryFilter: 'all',
  itemTypesCountLabel: '',
  inventoryEmpty: true,
  inventoryEmptyMessage: 'Votre sac est vide.',
};

const EMPTY_EGG_META: BagEggMetaSnapshot = {
  eggsTotalCount: '0',
  incubatorBoostText: '',
  incubatorBoostTitle: '',
  incubatorBoostVisible: false,
};

const EMPTY_EGG_SECTIONS: BagSnapshot['eggSections'] = {
  incubators: [],
  displayedSlotCount: 4,
  eggRows: [],
  showEmptyMessage: true,
  emptyTitle: '',
  emptyHint: '',
};

class BagStore {
  ui: BagPanelUiSnapshot = $state(EMPTY_UI);
  autoCatch: BagAutoCatchSnapshot = $state(EMPTY_AUTO_CATCH);
  inventory: BagInventorySnapshot = $state(EMPTY_INVENTORY);
  eggMeta: BagEggMetaSnapshot = $state(EMPTY_EGG_META);
  eggSections: BagEggSectionsSnapshot = $state(EMPTY_EGG_SECTIONS);

  get snapshot(): BagSnapshot {
    return {
      ui: this.ui,
      autoCatch: this.autoCatch,
      ...this.inventory,
      ...this.eggMeta,
      eggSections: this.eggSections,
    };
  }
}

export const bag = new BagStore();

facade.subscribe(Evt.BAG_CHANGED, (evt) => {
  if (!('bag' in evt)) return;
  const next = evt.bag;
  if (next.ui) bag.ui = next.ui;
  if (next.autoCatch) bag.autoCatch = next.autoCatch;
  if (bagInventoryWouldChange(bag.inventory, next)) {
    bag.inventory = pickBagInventory(next);
  }
  if (bagEggMetaWouldChange(bag.eggMeta, next)) {
    bag.eggMeta = pickBagEggMeta(next);
  }
  if (next.eggSections) {
    bag.eggSections = next.eggSections;
  }
});
