/**
 * @file src/lib/offlineAchievementStats.ts
 * Cumulative offline simulation time for achievements.
 */

import type { GameRuntime } from '../types/game.js';

export function recordOfflineSimulationTime(game: GameRuntime, elapsedMs: number): void {
    const ms = Math.max(0, Math.floor(Number(elapsedMs) || 0));
    if (ms <= 0) return;
    if (!game.stats) return;
    game.stats.offlineTimeSimulatedMs = (Number(game.stats.offlineTimeSimulatedMs) || 0) + ms;
    if (typeof game.checkAchievements === 'function') {
        game.checkAchievements('offlineTimeSimulatedMs');
    }
}
