const INVALID_CT_SET = new Set<string>(INVALID_CT_ITEM_KEYS);

/** Keys that may be granted or shown as CT items in the current build. */
export const ALLOWED_CT_ITEM_KEYS = new Set(
    Object.keys(CT_ITEMS_DISPLAY).filter((key) => key.startsWith('ct_') && !INVALID_CT_SET.has(key)),
);

export function isAllowedCtItemKey(itemKey: string): boolean {
    if (typeof itemKey !== 'string' || !itemKey.startsWith('ct_')) return false;
    return ALLOWED_CT_ITEM_KEYS.has(itemKey);
}

export function isInvalidCtItemKey(itemKey: string): boolean {
    return INVALID_CT_SET.has(itemKey);
}
