import { toast } from './toastManager.ts';

const MAX_REDEEMED_IDS = 200;
const MAX_POKEDOLLARS = 1e12;
const MAX_CURRENCY = 1e9;
const MAX_ITEM_QTY = 999;
const MAX_EGG_QTY = 9999;
const MAX_RANDOM_CT = 20;

export interface PromoApplyExtras {
  randomCtItems?: Record<string, number>;
}

export interface PromoApplyResult {
  applied: boolean;
  extras: PromoApplyExtras;
}

export type PromoRedeemFailReason =
  | 'empty'
  | 'invalid'
  | 'expired'
  | 'already'
  | 'locked'
  | 'grant_failed';

export type PromoRedeemResult =
  | { ok: true; codeId: string; summary: string }
  | { ok: false; reason: PromoRedeemFailReason };

export function sanitizeRedeemedPromoCodes(raw: unknown): string[] {
  if (!Array.isArray(raw)) return [];
  const seen = new Set<string>();
  const out: string[] = [];
  for (const entry of raw) {
    if (typeof entry !== 'string') continue;
    const id = entry.trim();
    if (!id || seen.has(id)) continue;
    seen.add(id);
    out.push(id);
    if (out.length >= MAX_REDEEMED_IDS) break;
  }
  return out;
}

export function ensureRedeemedPromoCodesState(game: GameRuntime): string[] {
  game.redeemedPromoCodes = sanitizeRedeemedPromoCodes(game.redeemedPromoCodes);
  return game.redeemedPromoCodes;
}

export { normalizePromoInput, hashPromoInputSync };

export function resolvePromoCodeId(normalized: string): string | null {
  if (!normalized) return null;
  const hash = hashPromoInputSync(normalized);
  const match = PROMO_CODES.find((def) => def.hash === hash);
  return match?.id ?? null;
}

export function getPromoDefinitionById(id: string): PromoCodeDefinition | undefined {
  return PROMO_CODES.find((def) => def.id === id);
}

function parseExpiresAt(expiresAt: string): Date | null {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(expiresAt)) return null;
  const [y, m, d] = expiresAt.split('-').map(Number);
  if (!y || !m || !d) return null;
  return new Date(y, m - 1, d, 23, 59, 59, 999);
}

export function isPromoCodeExpired(def: PromoCodeDefinition, now = new Date()): boolean {
  if (!def.expiresAt) return false;
  const end = parseExpiresAt(def.expiresAt);
  if (!end) return false;
  return now.getTime() > end.getTime();
}

export function canRedeemPromoCode(
  game: GameRuntime,
  codeId: string,
  now = new Date(),
): PromoRedeemFailReason | null {
  const def = getPromoDefinitionById(codeId);
  if (!def) return 'invalid';

  const redeemed = ensureRedeemedPromoCodesState(game);
  if (redeemed.includes(codeId)) return 'already';

  if (isPromoCodeExpired(def, now)) return 'expired';

  if (def.requiresUnlock) {
    const key = def.requiresUnlock;
    const features = game.unlockedFeatures;
    if (!features || !features[key]) return 'locked';
  }

  return null;
}

function sanitizeAmount(value: unknown, max: number): number {
  const n = Math.floor(Number(value));
  if (!Number.isFinite(n) || n <= 0) return 0;
  return Math.min(n, max);
}

function escapePromoHtml(value: unknown): string {
  return coerceStr(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

/** Sanitized reward payload for formatRewardText (game.ts). */
function buildSanitizedPromoRewardPayload(rewards: PromoCodeReward): Record<string, unknown> {
  const payload: Record<string, unknown> = {};
  const pd = sanitizeAmount(rewards.pokedollars, MAX_POKEDOLLARS);
  if (pd > 0) payload.pokedollars = pd;
  const tokens = sanitizeAmount(rewards.questTokens, MAX_CURRENCY);
  if (tokens > 0) payload.questTokens = tokens;
  const tickets = sanitizeAmount(rewards.combatTickets, MAX_CURRENCY);
  if (tickets > 0) payload.combatTickets = tickets;
  const eggs = rewards.eggs;
  if (eggs && typeof eggs === 'object') {
    const eggOut: Record<string, number> = {};
    const ec = sanitizeAmount(eggs.common, MAX_EGG_QTY);
    if (ec > 0) eggOut.common = ec;
    const er = sanitizeAmount(eggs.rare, MAX_EGG_QTY);
    if (er > 0) eggOut.rare = er;
    const ee = sanitizeAmount(eggs.epic, MAX_EGG_QTY);
    if (ee > 0) eggOut.epic = ee;
    const el = sanitizeAmount(eggs.legendary, MAX_EGG_QTY);
    if (el > 0) eggOut.legendary = el;
    if (Object.keys(eggOut).length > 0) payload.eggs = eggOut;
  }
  const items = rewards.items;
  if (items && typeof items === 'object') {
    const itemOut: Record<string, number> = {};
    for (const [key, qty] of Object.entries(items)) {
      const n = sanitizeAmount(qty, MAX_ITEM_QTY);
      if (n > 0) itemOut[key] = n;
    }
    if (Object.keys(itemOut).length > 0) payload.items = itemOut;
  }
  return payload;
}

function promoItemIconHtml(game: GameRuntime, itemDef: Record<string, unknown>): string {
  let iconHTML =
    typeof game.getItemIconHTML === 'function'
      ? game.getItemIconHTML(itemDef)
      : getItemIconHTML(itemDef as { name?: string; img?: string; icon?: string });
  if (!iconHTML || iconHTML === 'OBJ') return '';
  if (iconHTML.includes('item-sprite-img')) {
    return iconHTML.replace(/class="item-sprite-img[^"]*"/, 'class="quest-reward-inline-img"');
  }
  if (iconHTML.includes('<img ') && !iconHTML.includes('quest-reward-inline-img')) {
    return iconHTML.replace('<img ', '<img class="quest-reward-inline-img" ');
  }
  return iconHTML;
}

function appendPromoItemToastParts(
  game: GameRuntime,
  parts: string[],
  items: Record<string, number> | undefined,
): void {
  if (!items || typeof items !== 'object') return;
  const allItems = ALL_ITEMS as Record<string, { name?: string; img?: string; icon?: string }>;
  for (const [itemKey, qty] of Object.entries(items)) {
    const amount = sanitizeAmount(qty, MAX_ITEM_QTY);
    if (amount <= 0) continue;
    const itemDef =
      allItems[itemKey] ??
      (itemKey.startsWith('ct_')
        ? { name: `CT ${itemKey.replace('ct_', '')}`, icon: 'CT' }
        : { name: itemKey, icon: 'OBJ' });
    const iconHTML = promoItemIconHtml(game, itemDef as Record<string, unknown>);
    const itemName =
      typeof game.getLocalizedItemName === 'function'
        ? game.getLocalizedItemName(itemKey, itemDef.name || itemKey, itemDef as Record<string, unknown>)
        : (itemDef.name || itemKey);
    parts.push(
      `<span class="quest-reward-item">${iconHTML} ${amount}x ${escapePromoHtml(itemName)}</span>`,
    );
  }
}

function mergePromoItemRewards(
  rewards: PromoCodeReward,
  extras?: PromoApplyExtras,
): Record<string, number> | undefined {
  const base = rewards.items && typeof rewards.items === 'object' ? { ...rewards.items } : {};
  const randomCt = extras?.randomCtItems;
  if (randomCt && typeof randomCt === 'object') {
    for (const [key, qty] of Object.entries(randomCt)) {
      const n = sanitizeAmount(qty, MAX_ITEM_QTY);
      if (n > 0) base[key] = (base[key] || 0) + n;
    }
  }
  return Object.keys(base).length > 0 ? base : undefined;
}

function appendPromoCreatureToastParts(
  game: GameRuntime,
  parts: string[],
  rewards: PromoCodeReward,
): void {
  const creatures = rewards.creatures;
  if (!Array.isArray(creatures)) return;
  for (const spec of creatures) {
    if (!spec?.name) continue;
    const isShiny = spec.isShiny !== false;
    const display =
      typeof game.getLocalizedPokemonName === 'function'
        ? game.getLocalizedPokemonName(spec.name)
        : spec.name;
    const shinySuffix = isShiny ? ` ${game.t('promo.shinyTag')}` : '';
    const spriteUrl = getPokemonSpriteUrl(spec.name, isShiny);
    const imgTag = spriteUrl
      ? `<img src="${escapePromoHtml(spriteUrl)}" class="quest-reward-inline-img" alt="${escapePromoHtml(display)}"> `
      : '';
    parts.push(
      `<span class="quest-reward-item">${imgTag}${escapePromoHtml(display)}${escapePromoHtml(shinySuffix)}</span>`,
    );
  }
}

/** HTML toast body with sprites (quest-reward-item pattern). */
export function buildPromoRewardsToastHtml(
  game: GameRuntime,
  rewards: PromoCodeReward,
  extras?: PromoApplyExtras,
): string {
  const parts: string[] = [];
  const mapped = buildSanitizedPromoRewardPayload(rewards);
  const itemRewards = mergePromoItemRewards(rewards, extras);
  if (mapped.items) delete mapped.items;
  const baseHtml = callGame<string>(game, game['formatRewardText'], mapped);
  if (baseHtml && String(baseHtml).trim()) parts.push(String(baseHtml));
  appendPromoItemToastParts(game, parts, itemRewards);
  appendPromoCreatureToastParts(game, parts, rewards);

  const dust = sanitizeAmount(rewards.essenceDust, MAX_CURRENCY);
  if (dust > 0) {
    parts.push(
      `<span class="quest-reward-item"><img src="img/essence-dust.png" class="quest-reward-inline-img" alt="${escapePromoHtml(game.t('promo.dustShort'))}"> ${formatNumber(dust)}</span>`,
    );
  }
  const marks = sanitizeAmount(rewards.triumphMarks, MAX_CURRENCY);
  if (marks > 0) {
    parts.push(
      `<span class="quest-reward-item"><img src="img/marque-triomphe.png" class="quest-reward-inline-img" alt="${escapePromoHtml(game.t('promo.markShort'))}"> ${formatNumber(marks)}</span>`,
    );
  }

  if (Array.isArray(rewards.headerSkins)) {
    const skinsRecord = HEADER_SKINS as Record<string, { name?: string; imagePath?: string }>;
    for (const skinId of rewards.headerSkins) {
      if (typeof skinId !== 'string' || !skinId.trim()) continue;
      const skin = skinsRecord[skinId];
      if (!skin) continue;
      const skinName = escapePromoHtml(skin.name || skinId);
      const imgPath = skin.imagePath ? escapePromoHtml(skin.imagePath) : '';
      const imgTag = imgPath
        ? `<img src="${imgPath}" class="quest-reward-inline-img" alt="${skinName}"> `
        : '';
      parts.push(`<span class="quest-reward-item">${imgTag}${skinName}</span>`);
    }
  }

  if (rewards.unlockFeatures && typeof rewards.unlockFeatures === 'object') {
    const unlockCount = Object.keys(rewards.unlockFeatures).filter(
      (k) => rewards.unlockFeatures?.[k as keyof UnlockedFeatures],
    ).length;
    if (unlockCount > 0) {
      parts.push(
        `<span class="quest-reward-item toast-reward-note">${escapePromoHtml(game.t('promo.unlockFeatures', { count: unlockCount }))}</span>`,
      );
    }
  }

  const inner = parts.join('');
  return inner ? `<div class="toast-reward-summary">${inner}</div>` : '';
}

function summarizePromoReward(
  game: GameRuntime,
  rewards: PromoCodeReward,
  extras?: PromoApplyExtras,
): string {
  const parts: string[] = [];
  const pd = sanitizeAmount(rewards.pokedollars, MAX_POKEDOLLARS);
  if (pd > 0) parts.push(`${formatNumber(pd)} $`);
  const tokens = sanitizeAmount(rewards.questTokens, MAX_CURRENCY);
  if (tokens > 0) parts.push(`${formatNumber(tokens)} ${game.t('promo.tokenShort')}`);
  const dust = sanitizeAmount(rewards.essenceDust, MAX_CURRENCY);
  if (dust > 0) parts.push(`${formatNumber(dust)} ${game.t('promo.dustShort')}`);
  const tickets = sanitizeAmount(rewards.combatTickets, MAX_CURRENCY);
  if (tickets > 0) parts.push(`${formatNumber(tickets)} ${game.t('promo.ticketShort')}`);
  const marks = sanitizeAmount(rewards.triumphMarks, MAX_CURRENCY);
  if (marks > 0) parts.push(`${formatNumber(marks)} ${game.t('promo.markShort')}`);
  const eggs = rewards.eggs;
  if (eggs) {
    const ec = sanitizeAmount(eggs.common, MAX_EGG_QTY);
    if (ec > 0) parts.push(`${ec}× ${game.t('promo.eggCommon')}`);
    const er = sanitizeAmount(eggs.rare, MAX_EGG_QTY);
    if (er > 0) parts.push(`${er}× ${game.t('promo.eggRare')}`);
    const ee = sanitizeAmount(eggs.epic, MAX_EGG_QTY);
    if (ee > 0) parts.push(`${ee}× ${game.t('promo.eggEpic')}`);
    const el = sanitizeAmount(eggs.legendary, MAX_EGG_QTY);
    if (el > 0) parts.push(`${el}× ${game.t('promo.eggLegendary')}`);
  }
  const mergedItems = mergePromoItemRewards(rewards, extras);
  if (mergedItems) {
    for (const [key, qty] of Object.entries(mergedItems)) {
      const n = sanitizeAmount(qty, MAX_ITEM_QTY);
      if (n > 0) parts.push(`${n}× ${key}`);
    }
  }
  const randomCtCount = sanitizeAmount(rewards.randomOffensiveCt, MAX_RANDOM_CT);
  if (randomCtCount > 0 && extras?.randomCtItems && Object.keys(extras.randomCtItems).length > 0) {
    parts.push(game.t('promo.randomCtGranted', { count: randomCtCount }));
  } else if (randomCtCount > 0) {
    parts.push(game.t('promo.randomCtSummary', { count: randomCtCount }));
  }
  if (Array.isArray(rewards.creatures)) {
    for (const spec of rewards.creatures) {
      if (!spec?.name) continue;
      const display =
        typeof game.getLocalizedPokemonName === 'function'
          ? game.getLocalizedPokemonName(spec.name)
          : spec.name;
      const shinySuffix = spec.isShiny !== false ? ` ${game.t('promo.shinyTag')}` : '';
      parts.push(`${display}${shinySuffix}`);
    }
  }
  if (Array.isArray(rewards.headerSkins) && rewards.headerSkins.length > 0) {
    parts.push(game.t('promo.headerSkins', { count: rewards.headerSkins.length }));
  }
  if (rewards.unlockFeatures && typeof rewards.unlockFeatures === 'object') {
    const keys = Object.keys(rewards.unlockFeatures).filter((k) => rewards.unlockFeatures?.[k as keyof UnlockedFeatures]);
    if (keys.length > 0) parts.push(game.t('promo.unlockFeatures', { count: keys.length }));
  }
  return parts.join(' · ') || '—';
}

/** Returns whether at least one reward was applied, plus rolled extras for display. */
export function applyPromoReward(game: GameRuntime, rewards: PromoCodeReward): PromoApplyResult {
  let applied = false;
  const extras: PromoApplyExtras = {};

  const pd = sanitizeAmount(rewards.pokedollars, MAX_POKEDOLLARS);
  if (pd > 0) {
    if (typeof game['addCombatPokedollars'] === 'function') {
      game['addCombatPokedollars'](pd, 'promo');
    } else {
      game.pokedollars = (game.pokedollars || 0) + pd;
      recordPokedollarsEarned(game, pd);
    }
    applied = true;
  }

  const tokens = sanitizeAmount(rewards.questTokens, MAX_CURRENCY);
  if (tokens > 0) {
    game.questTokens = (game.questTokens || 0) + tokens;
    if (game.stats) {
      game.stats.totalQuestTokensEarned = (game.stats.totalQuestTokensEarned || 0) + tokens;
    }
    applied = true;
  }

  const dust = sanitizeAmount(rewards.essenceDust, MAX_CURRENCY);
  if (dust > 0) {
    game.essenceDust = (game.essenceDust || 0) + dust;
    applied = true;
  }

  const tickets = sanitizeAmount(rewards.combatTickets, MAX_CURRENCY);
  if (tickets > 0) {
    game.combatTickets = (game.combatTickets || 0) + tickets;
    applied = true;
  }

  const marks = sanitizeAmount(rewards.triumphMarks, MAX_CURRENCY);
  if (marks > 0) {
    game.triumphMarks = (game.triumphMarks || 0) + marks;
    applied = true;
  }

  const eggs = rewards.eggs;
  if (eggs && game.eggs) {
    const ec = sanitizeAmount(eggs.common, MAX_EGG_QTY);
    if (ec > 0) {
      game.eggs.common = (game.eggs.common || 0) + ec;
      applied = true;
    }
    const er = sanitizeAmount(eggs.rare, MAX_EGG_QTY);
    if (er > 0) {
      game.eggs.rare = (game.eggs.rare || 0) + er;
      applied = true;
    }
    const ee = sanitizeAmount(eggs.epic, MAX_EGG_QTY);
    if (ee > 0) {
      game.eggs.epic = (game.eggs.epic || 0) + ee;
      applied = true;
    }
    const el = sanitizeAmount(eggs.legendary, MAX_EGG_QTY);
    if (el > 0) {
      game.eggs.legendary = (game.eggs.legendary || 0) + el;
      applied = true;
    }
  }

  const items = rewards.items;
  if (items && typeof items === 'object' && typeof game['addItem'] === 'function') {
    for (const [itemKey, qty] of Object.entries(items)) {
      const n = sanitizeAmount(qty, MAX_ITEM_QTY);
      if (n > 0) {
        game['addItem'](itemKey, n, false);
        applied = true;
      }
    }
  }

  if (Array.isArray(rewards.headerSkins)) {
    const skinsRecord = HEADER_SKINS as Record<string, unknown>;
    if (!Array.isArray(game.unlockedHeaderSkins)) game.unlockedHeaderSkins = [];
    for (const skinId of rewards.headerSkins) {
      if (typeof skinId !== 'string' || !skinId.trim()) continue;
      if (!skinsRecord[skinId]) continue;
      if (!game.unlockedHeaderSkins.includes(skinId)) {
        game.unlockedHeaderSkins.push(skinId);
        applied = true;
      }
    }
  }

  if (rewards.unlockFeatures && typeof rewards.unlockFeatures === 'object') {
    if (!game.unlockedFeatures || typeof game.unlockedFeatures !== 'object') {
      game.unlockedFeatures = {} as UnlockedFeatures;
    }
    for (const key of Object.keys(rewards.unlockFeatures) as (keyof UnlockedFeatures)[]) {
      if (rewards.unlockFeatures[key]) {
        game.unlockedFeatures[key] = true;
        applied = true;
      }
    }
  }

  const randomCtCount = sanitizeAmount(rewards.randomOffensiveCt, MAX_RANDOM_CT);
  if (randomCtCount > 0 && typeof game['addItem'] === 'function') {
    const keys = pickRandomOffensiveCtKeys(randomCtCount, game);
    const rolled = aggregateItemKeyCounts(keys);
    for (const [itemKey, qty] of Object.entries(rolled)) {
      game['addItem'](itemKey, qty, false);
    }
    if (Object.keys(rolled).length > 0) {
      extras.randomCtItems = rolled;
      applied = true;
    }
  }

  if (Array.isArray(rewards.creatures)) {
    for (const spec of rewards.creatures) {
      if (grantPromoCreature(game, spec)) applied = true;
    }
  }

  return { applied, extras };
}

let lastPromoRedeemResult: PromoRedeemResult | null = null;

export function getLastPromoRedeemResult(): PromoRedeemResult | null {
  return lastPromoRedeemResult;
}

export function redeemPromoCodeLogic(game: GameRuntime, rawInput: unknown, now = new Date()): PromoRedeemResult {
  const normalized = normalizePromoInput(rawInput);
  if (!normalized) {
    lastPromoRedeemResult = { ok: false, reason: 'empty' };
    return lastPromoRedeemResult;
  }

  const codeId = resolvePromoCodeId(normalized);
  if (!codeId) {
    lastPromoRedeemResult = { ok: false, reason: 'invalid' };
    return lastPromoRedeemResult;
  }

  const blockReason = canRedeemPromoCode(game, codeId, now);
  if (blockReason) {
    lastPromoRedeemResult = { ok: false, reason: blockReason };
    return lastPromoRedeemResult;
  }

  const def = getPromoDefinitionById(codeId);
  if (!def) {
    lastPromoRedeemResult = { ok: false, reason: 'invalid' };
    return lastPromoRedeemResult;
  }

  const { applied, extras } = applyPromoReward(game, def.rewards);
  if (!applied) {
    lastPromoRedeemResult = { ok: false, reason: 'grant_failed' };
    return lastPromoRedeemResult;
  }

  const redeemed = ensureRedeemedPromoCodesState(game);
  if (!redeemed.includes(codeId)) redeemed.push(codeId);

  const summary = summarizePromoReward(game, def.rewards, extras);
  lastPromoRedeemResult = { ok: true, codeId, summary };

  callGameVoid(game, game['saveGame']);
  const rewardsHtml = buildPromoRewardsToastHtml(game, def.rewards, extras);
  if (rewardsHtml) {
    toast.success(game.t('promo.toastTitle'), rewardsHtml, 5000, true);
  } else {
    toast.success(game.t('promo.toastTitle'), summary, 5000);
  }
  callGame(game, game['logMessage'], game.t('promo.successToast', { summary }));
  publishResourcesChanged();

  return lastPromoRedeemResult;
}

export function hasUnclaimedActivePromoCode(game: GameRuntime, now = new Date()): boolean {
  return PROMO_CODES.some((def) => canRedeemPromoCode(game, def.id, now) === null);
}

export function showDiscordPromoReminderToast(game: GameRuntime): void {
  if (!hasUnclaimedActivePromoCode(game)) return;

  const url = escapePromoHtml(SAVE_BOOT_DISCORD_URL);
  const label = escapePromoHtml(game.t('menu.discord'));
  const link = `<a href="${url}" class="promo-discord-link" target="_blank" rel="noopener noreferrer">${label}</a>`;
  // game.t() escapeHtml tous les vars string — placeholder neutre puis injection HTML.
  const linkPlaceholder = '__DISCORD_LINK__';
  const body = game.t('promo.discordReminderBody', { link: linkPlaceholder }).replace(linkPlaceholder, link);

  toast.showLeft({
    title: game.t('promo.discordReminderTitle'),
    message: body,
    type: 'info',
    duration: 0,
    closable: true,
    html: true,
  });
}
