                forever_alone: '+3% bonus shard per collection level',
                out_of_this_world: '-15% expedition time per collection level',
                the_600_club: '+3% damage per collection level',
                modern_era_starters: '+7% XP per collection level',
                unova_tao_trio: '+2% ATK and +2% Sp. Atk per collection level',
                unova_swords_of_justice: '+3% ATK per collection level',
                unova_relic_fossils: '+2% DEF per collection level',
                unova_forces_of_nature: '+2% speed per collection level',
                club_620: '+3.6% damage per collection level',
                fairy_ballet: '+1.2% life steal per collection level',
                mega_beetles: '+3% speed per collection level',
                stone_age_fossils: '+3% defense per collection level',
