    GameClass.prototype.getActiveSynergies = function (this: ThisGame): Record<string, number> {
        if (!this._cachedSynergiesDirty && this._cachedSynergies) return this._cachedSynergies;

        const team = (this.playerTeam || []).map((c) => ({
            name: c?.name,
            type: c?.type,
            secondaryType: c?.secondaryType,
        }));
        const bonuses = synergyBonusesToRecord(aggregateSynergyEffects(team, this));
        this._cachedSynergies = bonuses;
        this._cachedSynergiesDirty = false;
        return bonuses;
    };

