    GameClass.prototype.getShardBonusChance = function (this: ThisGame): number {
        let chance = (this.upgrades?.shardBonus?.level ?? 0) * 0.02;

        chance += this.getAccountTalentBonus('shard_chance');

        const collBonus = (this.getCollectionBonuses ? this.getCollectionBonuses() : {} as Record<string, number>).bonus_shard_chance || 0;
        chance += collBonus;

        return chance;
    };

    GameClass.prototype.getPrestigeCost = function (this: ThisGame, currentPrestige: number): number {
        if (currentPrestige === undefined || currentPrestige === null) return 1;

        const cost = currentPrestige + 1;

        return Math.max(1, cost);
    };

    GameClass.prototype.getPrestigeStoneCost = function (this: ThisGame, currentPrestige: number): number {
        if (typeof this.getPrestigeCost === 'function') {
            return this.getPrestigeCost(currentPrestige);
        }
        if (currentPrestige === undefined || currentPrestige === null) return 1;
        return Math.max(1, currentPrestige + 1);
    };

    GameClass.prototype.getUpgradeCost = function (this: ThisGame, upgradeKey: string): number {
        const upgrade = this.upgrades[upgradeKey];
        if (!upgrade) return 0;
        const upg = upgrade as unknown as Record<string, unknown>;
        const base = Math.floor(Number(upg.baseCost) * Math.pow(Number(upg.costMultiplier), Number(upg.level)));
        if (upg.featureUnlockKey) return Math.max(1, base);
        const reduction = this.getMasteryBonus ? (this.getMasteryBonus('upgrade_cost_reduction') || 0) : 0;
        return Math.max(1, Math.floor(base * (1 - reduction)));
    };

    GameClass.prototype.unlockAnalyticsFeature = function (this: ThisGame, featureKey: string, options?: Record<string, unknown>): void {
        if (!featureKey) return;
        if (!this.unlockedFeatures || typeof this.unlockedFeatures !== 'object') return;
        const wasUnlocked = !!(this.unlockedFeatures as unknown as Record<string, unknown>)[featureKey];
        (this.unlockedFeatures as unknown as Record<string, unknown>)[featureKey] = true;
        if (!wasUnlocked && featureKey === 'autoFightAdvanced') {
            this._scrollAutoAdvancedOnOpen = true;
            this.autoSwitchAdvanced = true;
            this.optimalMoveSelection = true;
            this.autoSwitchDisadvantage = false;
            this.autoSwitchAdvantage = false;
            if (!this.autoFightAdvancedOptions || typeof this.autoFightAdvancedOptions !== 'object') {
                this.autoFightAdvancedOptions = {
                    neverSendWeakMatchup: true,
                    avoidDoubleWeakness: true,
                    minHpPct: 0.25,
                    skipIfCanFinish: true,
                    minScoreGainPct: 0.20,
                    respectPreferredActive: true,
                    excludedSwitchIndices: [],
                    preferXpEligible: false,
                };
            } else {
                this.autoFightAdvancedOptions.respectPreferredActive = true;
                if (!Array.isArray(this.autoFightAdvancedOptions.excludedSwitchIndices)) {
                    this.autoFightAdvancedOptions.excludedSwitchIndices = [];
                }
            }
        }
        if (typeof this.refreshBattleFeatureButtons === 'function') {
            this.refreshBattleFeatureButtons();
        }
        if (typeof this.syncAutoAdvancedSettingsUI === 'function') {
            this.syncAutoAdvancedSettingsUI();
        }
        if (wasUnlocked) return;

        const opt = options || {};
        const lang = (typeof this.normalizeLanguage === 'function')
            ? this.normalizeLanguage(this.language)
            : 'fr';
        const isEn = lang === 'en';
        const defaults: Record<string, Record<string, { title: string; msg: string }>> = {
            dpsMeter: {
                fr: { title: '⚔️ DPS Meter débloqué !', msg: 'Le compteur de dégâts est désormais actif. Clique sur ⚔️ en haut à gauche pendant un combat pour le rouvrir.' },
                en: { title: '⚔️ DPS Meter unlocked!', msg: 'The damage counter is now active. Click ⚔️ at the top-left during combat to reopen it.' }
            },
            statsBreakdownModal: {
                fr: { title: '🔍 Lentille d\'Analyse débloquée !', msg: 'Le bouton ⓘ "Détails des stats" est désormais actif sur chaque créature de ton équipe, stockage ou pension.' },
                en: { title: '🔍 Analysis Lens unlocked!', msg: 'The ⓘ "Stats Breakdown" button is now active on every creature in your team, storage or daycare.' }
            },
            farmingMetricsModal: {
                fr: { title: '📈 Métriques de Farm débloquées !', msg: 'Le bouton 📈 en haut à droite de la scène de combat ouvre désormais le suivi de rendement par session.' },
                en: { title: '📈 Farm Metrics unlocked!', msg: 'The 📈 button at the top-right of the battle scene now opens the per-session yield tracker.' }
            },
            towerRelicAuto: {
                fr: { title: '⚙️ Pilote de Reliques débloqué !', msg: "Configure les priorités et la liste noire dans l'onglet Tour." },
                en: { title: '⚙️ Relic Pilot unlocked!', msg: 'Set priorities and blacklist on the Tower tab.' }
            },
            autoFightAdvanced: {
                fr: { title: '🧠 Auto Fight Advanced débloqué !', msg: 'Le switch intelligent est activé. Endurance et ultime restent configurables dans le panneau Auto.' },
                en: { title: '🧠 Auto Fight Advanced unlocked!', msg: 'Smart switching is now enabled. Endurance and ultimate remain configurable in the Auto panel.' }
            }
        };
        const def = defaults[featureKey] || {};
        const fallbacks = (isEn ? def.en : def.fr) || { title: 'Feature unlocked', msg: '' };
        const title = (opt.toastTitle || fallbacks.title) as string;
        const message = (opt.toastMessage || fallbacks.msg) as string;
        const icon = (opt.toastIcon || '🎉') as string;

        const winToast = window.toast as { show?: (opts: Record<string, unknown>) => void } | undefined;
        if (typeof window !== 'undefined' && winToast?.show) {
            winToast.show({ type: 'success', icon, title, message, duration: 6000 });
        } else {
            logMessage(title + ' — ' + message);
        }

        if (typeof opt.openFn === 'function') {
            setTimeout(() => { try { (opt.openFn as () => void)(); } catch (_e) { /* no-op */ } }, 250);
        }
        if (this.afkMode) publishAfkSummaryChanged();
    };

