    GameClass.prototype.canAffordUpgrade = function (this: ThisGame, upgradeKey: string): boolean {
        const cost = this.getUpgradeCost(upgradeKey);
        return this.pokedollars >= cost;
    };

    GameClass.prototype.buyUpgrade = function (this: ThisGame, upgradeKey: string): boolean {
        const upgrade = this.upgrades[upgradeKey];
        if (!upgrade) return false;
        if (upgradeKey === 'incubatorSlots' || upgradeKey === 'incubatorAutoClick') return false;

        if (upgrade.level >= upgrade.maxLevel) {
            logMessage(this.t('log.upgradeMaxed'));
            return false;
        }

        const cost = this.getUpgradeCost(upgradeKey);
        if (!this.canAffordUpgrade(upgradeKey)) {
            logMessage(this.t('log.upgradeNotEnoughMoney', { have: this.pokedollars, need: cost }));
            return false;
        }

        const previousMoney = this.pokedollars;
        this.pokedollars -= cost;
        recordPokedollarsSpent(this, cost);
        this.stats.upgradesPurchased = (this.stats.upgradesPurchased || 0) + 1;
        this.checkAchievements('upgradesPurchased');

        this.checkSpecialQuests('money_spent');
        if (typeof this.applyRocketPokedollarCashback === 'function') this.applyRocketPokedollarCashback(cost);
        if (upgradeKey === 'pension') this.checkSpecialQuests('pensionUpgradeBought');
        upgrade.level++;

        const localizedUpgradeName = this.getLocalizedShopEntryName('upgrades', upgradeKey, upgrade.name);
        const upgradeMsg = this.t('log.upgradeBought', { name: localizedUpgradeName, level: upgrade.level });
        logMessage(upgradeMsg);

        this.updateUpgradesDisplay();
        this.updatePlayerStatsDisplay();
        this.updateTeamDisplay();
        this.updateStorageDisplay();
        this.updatePensionDisplay();

        if (upgrade.featureUnlockKey && typeof this.unlockAnalyticsFeature === 'function') {
            const featureKey = upgrade.featureUnlockKey;
            const openFn = (featureKey === 'farmingMetricsModal' && typeof this.openFarmingMetricsModal === 'function')
                ? () => this.openFarmingMetricsModal()
                : undefined;
            this.unlockAnalyticsFeature(featureKey, { openFn });
        }

        const totalBefore = previousMoney;
        if (totalBefore > 0) {
            const ratio = cost / totalBefore;
            if (ratio >= 0.7 && typeof (this as Record<string, unknown>).maybeShowRivalToast === 'function') {
                ((this as Record<string, unknown>).maybeShowRivalToast as (opts: Record<string, unknown>) => void)({ type: 'big_purchase', amount: cost, ratio });
            }
        }

        return true;
    };

