    GameClass.prototype.addBoost = function (this: ThisGame, boost: BoostInput): void {
        const boostObj = {
            type: boost.type,
            value: boost.value,
            endTime: Date.now() + boost.duration
        };

        this.activeBoosts.push(boostObj);

        logMessage(this.t('log.boostActivated', { percent: (boost.value * 100), name: this.getBoostTypeLabel(boost.type) }));

        this.updateBoostsDisplay();
    };

    GameClass.prototype.updateBoosts = function (this: ThisGame): void {
        const now = Date.now();
        const expiredBoosts: StatBoost[] = [];

        this.activeBoosts = this.activeBoosts.filter((boost) => {
            if (boost.endTime <= now) {
                expiredBoosts.push(boost);
                return false;
            }
            return true;
        });

        if (expiredBoosts.length > 0) {
            this.updateBoostsDisplay();
            if (expiredBoosts.some((boost) => activeShinyBoostExpired(boost))) {
                notifyShinyCharmIndicatorChanged();
            }
            if (expiredBoosts.some((boost) => activeRoamerBoostExpired(boost))) {
                notifyRoamerIncenseIndicatorChanged();
            }
        }
    };

    GameClass.prototype.openSynergyListModal = async function (this: ThisGame): Promise<void> {
        await awaitLazyModalReady('synergyListModal');
        const modal = getById('synergyListModal');
        if (!modal) return;
        modal.classList.add('show');
    };

    GameClass.prototype.updateBoostsDisplay = function (this: ThisGame): void {
        const boostsDiv = getById('activeBoosts');
        const boostsList = getById('boostsList');
        if (!boostsDiv || !boostsList) return;

        if (this.activeBoosts.length === 0) {
            boostsDiv.style.display = 'none';
            return;
        }

        boostsDiv.style.display = 'block';
        boostsList.innerHTML = '';

        this.activeBoosts.forEach(boost => {
            const timeLeft = boost.endTime - Date.now();
            const minutes = Math.floor(timeLeft / 60000);
            const seconds = Math.floor((timeLeft % 60000) / 1000);
            const isEggHatchBoost = boost.type === 'eggHatchSpeed';
            const isPassiveGainTurbo = typeof boost.type === 'string' && boost.type.startsWith('passiveGain_');
            const isMultiplierBoost = isEggHatchBoost || isPassiveGainTurbo;
            const boostLabel = isMultiplierBoost
                ? `x${Math.max(1, Math.round(1 + (Number(boost.value) || 0)))} ${this.getBoostTypeLabel(boost.type)}`
                : `+${(boost.value * 100)}% ${this.getBoostTypeLabel(boost.type)}`;

            const boostItem = document.createElement('div');
            boostItem.className = 'boost-item';
            boostItem.innerHTML = `
            <span class="boost-name">&#9889; ${boostLabel}</span>
            <span class="boost-timer">${minutes}:${seconds < 10 ? '0' : ''}${seconds}</span>
        `;
            boostsList.appendChild(boostItem);
        });
    };

    GameClass.prototype.getActiveBoostMultiplier = function (this: ThisGame, type: string): number {
        let multiplier = 0;

        this.activeBoosts.forEach(boost => {
            if (boost.type === type) {
                multiplier += boost.value;
            }
        });

        return multiplier;
    };

    GameClass.prototype.getStatBoostMultiplier = function (this: ThisGame, stat: string): number {
        let multiplier = 0;

        this.activeStatBoosts.forEach(boost => {
            const key = getActiveStatBoostKey(boost);
            if (key === 'all' || key === stat) {
                multiplier += boost.value;
            }
        });

        return multiplier;
    };

    GameClass.prototype.getBoostInfoForStat = function (this: ThisGame, stat: string): BoostInfo[] {
        const now = Date.now();
        const list: BoostInfo[] = [];
        (this.activeStatBoosts || []).forEach(boost => {
            if (boost.endTime <= now) return;
            const key = getActiveStatBoostKey(boost);
            const affects = (key === stat || key === 'all');
            if (!affects) return;
            const timeLeftMs = boost.endTime - now;
            let label = 'Bonus';
            if (boost.itemId && (ALL_ITEMS as Record<string, { name?: string }>)[boost.itemId]) {
                const itemDef = (ALL_ITEMS as Record<string, { name?: string }>)[boost.itemId];
                if (itemDef) label = this.getLocalizedItemName(boost.itemId, itemDef.name || label, itemDef);
            } else if (key === 'all') {
                label = this.t('tooltip.allStats');
            }
            list.push({
                label: label,
                valuePct: Math.round(boost.value * 100),
                timeLeftMs: timeLeftMs,
                kind: 'percent',
            });
        });

        const wing = getPassiveGainWingState(this.activeBoosts || [], stat, now);
        if (wing) {
            const wingType = `passiveGain_${stat}`;
            const wingEntry = (this.activeBoosts || []).find(
                (b) => b && b.type === wingType && Number(b.endTime) > now,
            );
            let label = this.getBoostTypeLabel(wingType);
            const itemId = wingEntry?.itemId;
            if (itemId && (ALL_ITEMS as Record<string, { name?: string }>)[itemId]) {
                const itemDef = (ALL_ITEMS as Record<string, { name?: string }>)[itemId];
                if (itemDef) label = this.getLocalizedItemName(itemId, itemDef.name || label, itemDef);
            }
            list.push({
                label,
                valuePct: 0,
                timeLeftMs: wing.endTime - now,
                kind: 'multiplier',
                multiplier: Math.max(1, Math.round(wing.multiplier)),
            });
        }

        return list;
    };

    GameClass.prototype.showBoostTooltip = function (this: ThisGame, event: Event, stat: string): void {
        const growthLines = formatHeaderStatGrowthTooltipLines(this, stat);
        const growthTitle = getHeaderStatGrowthTooltipTitle(this, stat);
        const statLabel = this.getStatDisplayLabel(stat);
        const infos = this.getBoostInfoForStat(stat);
        const boostLines = infos.length === 0
            ? [this.t('tooltip.boostNone')]
            : infos.map((b: BoostInfo) => {
                const timeStr = formatBoostTimeLeft(b.timeLeftMs, {
                    minuteShort: this.t('offline.minuteShort'),
                    secondShort: this.t('offline.secondShort'),
                });
                if (b.kind === 'multiplier' && b.multiplier != null) {
                    return this.t('tooltip.wingBoostLine', { label: b.label, mult: b.multiplier, time: timeStr });
                }
                return this.t('tooltip.boostLine', { label: b.label, value: b.valuePct, time: timeStr });
            });
        const title = growthTitle ?? this.t('tooltip.boostTitle', { stat: statLabel });
        const description = growthLines.length > 0
            ? `${growthLines.join('\n')}\n\n${boostLines.join('\n')}`
            : boostLines.join('\n');
        this.scheduleTooltip(event, title, description);
    };

