    /** Max HP for growth / Temps x2 — same as getPlayerMaxHp but without team potion (Defense+ style) HP boost. */
    GameClass.prototype.getPlayerMaxHpForGrowthAnalysis = function (this: ThisGame): number {
        const hpBonus = 1 + this.getAccountTalentBonus('hp_mult');
        const synergies = this.getActiveSynergies();
        const synergyMaxHpMult = synergies.max_hp_mult || 1;

        let total = Math.floor((this.playerMainStats.hp || 0) * hpBonus * synergyMaxHpMult);

        if (this.towerState.isActive && this.towerState.buffs && this.towerState.buffs.max_hp_mult) {
            total = Math.floor(total * Number(this.towerState.buffs.max_hp_mult));
        }
        const collHpMult = (this.getCollectionBonuses ? this.getCollectionBonuses() : {}).max_hp_mult || 0;
        total = Math.floor(total * (1 + collHpMult));

        const auraMult = 1 + this.getTalentStackBonus('aura');
        total = Math.floor(total * auraMult);

        return total;
    };

    // ─── Passive Growth Analysis ─────────────────────────────────────

    GameClass.prototype.getPassiveGrowthAnalysis = function (this: ThisGame): PassiveGrowthAnalysis {
        const safe = (value: unknown): number => {
            const n = Number(value);
            return Number.isFinite(n) && n > 0 ? n : 0;
        };

        const now = Date.now();
        const perSec = this.getPassiveStatGainPerSecond();

        const growthOpts = { includePotions: false as const };
        const current: PlayerMainStats = {
            hp: safe(this.getPlayerMaxHpForGrowthAnalysis()),
            attack: safe(getDisplayedHeaderStat(this, 'attack', growthOpts)),
            spattack: safe(getDisplayedHeaderStat(this, 'spattack', growthOpts)),
            defense: safe(getDisplayedHeaderStat(this, 'defense', growthOpts)),
            spdefense: safe(getDisplayedHeaderStat(this, 'spdefense', growthOpts)),
            speed: safe(getDisplayedHeaderStat(this, 'speed', growthOpts)),
        };

        const gains: PlayerMainStats = {
            hp: safe(perSec.hp),
            attack: safe(perSec.attack),
            spattack: safe(perSec.spattack),
            defense: safe(perSec.defense),
            spdefense: safe(perSec.spdefense),
            speed: safe(perSec.speed),
        };

        const labels: Record<string, string> = {
            hp: this.t('statsUi.growthStatHp'),
            attack: this.t('statsUi.growthStatAttack'),
            spattack: this.t('statsUi.growthStatSpAttack'),
            defense: this.t('statsUi.growthStatDefense'),
            spdefense: this.t('statsUi.growthStatSpDefense'),
            speed: this.t('statsUi.growthStatSpeed'),
        };
        const keys = ['hp', 'attack', 'spattack', 'defense', 'spdefense', 'speed'] as const;
        const boosts = this.activeBoosts || [];

        const rows: PassiveGrowthRow[] = keys.map((key) => {
            const currentValue = safe(current[key]);
            const gainPerSecond = safe(gains[key]);
            const wing = getPassiveGainWingState(boosts, key, now);
            const wingMult = wing?.multiplier ?? 1;
            const baseGainPerSec = wingMult > 1 ? gainPerSecond / wingMult : gainPerSecond;

            const metrics1h = computePassiveGrowthMetrics({
                currentValue,
                baseGainPerSec,
                wingMultiplier: wingMult,
                wingEndTimeMs: wing?.endTime ?? null,
                nowMs: now,
                horizonSec: 3600,
            });
            const metrics24h = computePassiveGrowthMetrics({
                currentValue,
                baseGainPerSec,
                wingMultiplier: wingMult,
                wingEndTimeMs: wing?.endTime ?? null,
                nowMs: now,
                horizonSec: 86400,
            });

            const doublingSeconds = metrics1h.doublingSeconds;
            const projected1h = metrics1h.projectedAtHorizon;
            const projected24h = metrics24h.projectedAtHorizon;
            const gainPerHour = projected1h - currentValue;
            const hourlyPercent = currentValue > 0 ? ((gainPerHour / currentValue) * 100) : 0;

            return {
                key,
                label: labels[key] || key,
                current: currentValue,
                gainPerSecond,
                gainPerHour,
                doublingSeconds,
                doublingText: Number.isFinite(doublingSeconds)
                    ? this.formatDurationFromSeconds(doublingSeconds)
                    : this.t('statsUi.growthInfinite'),
                projected1h,
                projected24h,
                hourlyPercent,
            };
        });

        return {
            capturedAt: now,
            current,
            gains,
            rows,
        };
    };

