    GameClass.prototype.saveFarmingSession = function (this: ThisGame, name: string): void {
        if (!this.farmingMetrics) this.farmingMetrics = this.getDefaultFarmingMetrics();
        if (!Array.isArray(this.farmingSavedSessions)) this.farmingSavedSessions = [];
        const m = this.farmingMetrics;
        const trimmedName = (name || '').toString().trim().slice(0, 40) || ('Session ' + (this.farmingSavedSessions.length + 1));
        const snapshot: FarmingSessionSnapshot = {
            name: trimmedName,
            startTime: m.sessionStart || Date.now(),
            endTime: Date.now(),
            pokedollarsTotal: m.pokedollarsTotal || 0,
            xp: m.xp || 0,
            combats: m.combats || 0,
            captures: m.captures || 0,
            shiniesEncountered: m.shiniesEncountered || 0,
            shiniesCaptured: m.shiniesCaptured || 0,
            combatsWithDuration: m.combatsWithDuration || 0,
            combatDurationsTotalMs: m.combatDurationsTotalMs || 0,
            eggs: m.eggs ? { ...m.eggs } : {}
        };
        this.farmingSavedSessions.unshift(snapshot);
        if (this.farmingSavedSessions.length > 12) this.farmingSavedSessions.length = 12;
        this._refreshFarmingSessionsList();
    };

