    GameClass.prototype._checkFarmingGoalReachedNotify = function (this: ThisGame): void {
        const m = this.farmingMetrics;
        if (!m || !m.recording) return;
        if (m.estimationMode !== 'goal') return;
        const target = Number(m.estimationGoalAmount) || 0;
        if (target <= 0) return;
        const metric = m.estimationGoalMetric || 'pokedollarsTotal';
        const current = Number((m as unknown as Record<string, unknown>)[metric]) || 0;
        if (current < target) return;
        const signature = metric + '|' + target;
        if (m.goalNotifiedSignature === signature) return;
        m.goalNotifiedSignature = signature;

        const lang = (this.normalizeLanguage && this.normalizeLanguage(this.language)) || 'fr';
        const fmt = formatNumber;
        const metricLabels: Record<string, Record<string, string>> = {
            pokedollarsTotal: { fr: 'Argent', en: 'Money' },
            xp: { fr: 'XP', en: 'XP' },
            captures: { fr: 'Captures', en: 'Captures' },
            combats: { fr: 'Combats', en: 'Combats' }
        };
        const metricLabel = (metricLabels[metric] && metricLabels[metric][lang === 'en' ? 'en' : 'fr']) || metric;
        const title = lang === 'en' ? 'Farming goal reached!' : 'Objectif de farm atteint !';
        const message = metricLabel + ' : ' + fmt(Math.round(current)) + ' / ' + fmt(target);

        if (typeof toast !== 'undefined' && typeof toast.success === 'function') {
            toast.success(title, message);
        } else {
            const winToastFallback = window.toast as { show?: (opts: Record<string, unknown>) => void } | undefined;
            if (typeof window !== 'undefined' && winToastFallback?.show) {
                winToastFallback.show({ type: 'success', icon: '', title, message, duration: 6000 });
            }
        }
        if (typeof playSound === 'function') playSound('success');
        _playFarmingGoalChime();
        logMessage(title + ' ' + message);
    };

    function _playFarmingGoalChime(): void {
        try {
            if (typeof window === 'undefined') return;
            const Ctx = (window as unknown as Record<string, unknown>).AudioContext || (window as unknown as Record<string, unknown>).webkitAudioContext;
            if (!Ctx) return;
            const Ctor = Ctx as new () => AudioContext;
            if (!(_playFarmingGoalChime as unknown as Record<string, unknown>)._ctx) (_playFarmingGoalChime as unknown as Record<string, unknown>)._ctx = new Ctor();
            const ctx = (_playFarmingGoalChime as unknown as Record<string, unknown>)._ctx as AudioContext;
            if (ctx.state === 'suspended' && typeof ctx.resume === 'function') ctx.resume().catch(() => {});
            const now = ctx.currentTime;
            const playNote = (freq: number, start: number, duration: number, peak: number = 0.18) => {
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.type = 'triangle';
                osc.frequency.setValueAtTime(freq, now + start);
                gain.gain.setValueAtTime(0, now + start);
                gain.gain.linearRampToValueAtTime(peak, now + start + 0.02);
                gain.gain.exponentialRampToValueAtTime(0.0001, now + start + duration);
                osc.connect(gain).connect(ctx.destination);
                osc.start(now + start);
                osc.stop(now + start + duration + 0.02);
            };
            playNote(660, 0,    0.18);
            playNote(880, 0.14, 0.28);
        } catch (_) { /* ignore */ }
    }

