<script lang="ts">
  import { team } from '../stores/team.svelte.ts';
  import { game } from '../../gameManager.js';
  import type { GameRuntime } from '../types/game.js';
  import { _bindTeamDragDelegation } from '../ui/teamDisplay.ts';
  import CreatureCard from './CreatureCard.svelte';

  let listEl = $state<HTMLElement | null>(null);
  /** Sync anchor for card animations — set once per mount (legacy updateTeamDisplayUI). */
  const animationDelaySec = (performance.now() % 1900) / 1000;

  let faintedSet = $derived(new Set(team.faintedTeamIndices));

  $effect(() => {
    const el = listEl;
    const gm = game;
    if (!el || !gm) return;
    _bindTeamDragDelegation(gm, el);
  });

  $effect(() => {
    const _sig = team.synergyTypesSignature;
    const gm = game as GameRuntime | null;
    if (!gm || typeof gm.updateSynergyDisplay !== 'function') return;
    gm.updateSynergyDisplay();
  });
</script>

<div
  bind:this={listEl}
  class="team-list"
  id="teamList"
  class:sprite-only-mode={team.teamSpritesOnly}
>
  {#each Array(team.maxTeamSize) as _, slotIndex (slotIndex)}
    {#if slotIndex < team.playerTeam.length}
      {@const creature = team.playerTeam[slotIndex]}
      {#if creature}
        <CreatureCard
          {creature}
          index={slotIndex}
          location="team"
          animationDelaySec={animationDelaySec}
          isActive={slotIndex === team.activeCreatureIndex}
          isFainted={!creature.isAlive || faintedSet.has(slotIndex)}
          teamSpritesOnly={team.teamSpritesOnly}
          teamContributionRatePercent={team.teamContributionRatePercent}
          levelShort={team.labels.levelShort}
          viewDetails={team.labels.viewDetails}
        />
      {:else}
        <div
          class="team-slot-empty"
          data-slot-index={String(slotIndex)}
          data-team-slot-index={String(slotIndex)}
        >
          +
        </div>
      {/if}
    {:else}
      <div
        class="team-slot-empty"
        data-slot-index={String(slotIndex)}
        data-team-slot-index={String(slotIndex)}
      >
        +
      </div>
    {/if}
  {/each}
</div>
