﻿/**
 * @file staticHtmlBindings.ts
 * Binds static controls in index.html (no inline onchange / oninput / onmouse*).
 * Runs once after Game is constructed (see bootstrapGame in index.html).
 *
 * Phase 1.5 — Migrated to facade.dispatch() for game state mutations.
 * Tooltip bindings remain direct (UI presentation only).
 * Phase 5.4 — @ts-nocheck removed, full typing.
 */
import { facade } from './src/bus/gameFacade.js';
import { game } from './gameManager.js';
import { callGame as invokeOnGame, callGameVoid } from './src/lib/callBound.ts';
import type { GameMethods, GameRuntime } from './src/types/game.js';

let done = false;
let lateDone = false;

type ListenerFn = (this: HTMLElement, ev: Event) => void;

function runtime(): GameRuntime | null {
    return game ?? (globalThis as { game?: GameRuntime | null }).game ?? null;
}

function callGame(fnName: keyof GameMethods, ...args: unknown[]): void {
    const g = runtime();
    if (!g) return;
    invokeOnGame(g, g[fnName], ...args);
}

function bindTooltipEvent(id: string, showMethod: keyof GameMethods): void {
    const el = document.getElementById(id);
    if (!el) return;
    el.addEventListener('mouseenter', (ev) => { callGame(showMethod, ev); });
    el.addEventListener('mouseleave', () => {
        const g = runtime();
        if (g) g.hideTooltip();
    });
}

export function initStaticHtmlBindings(): void {
    if (done) return;
    done = true;

    const on = function (id: string, event: string, fn: ListenerFn): void {
        const el = document.getElementById(id);
        if (el) el.addEventListener(event, fn);
    };

    // Region change: ZoneSelector.svelte dispatches CHANGE_REGION via facade.

    // ─── Tooltip bindings (UI presentation, no state change) ───
    const bindHover = function (id: string, show: keyof GameMethods, hide: keyof GameMethods): void {
        const el = document.getElementById(id);
        if (!el) return;
        el.addEventListener('mouseenter', () => { callGame(show); });
        el.addEventListener('mouseleave', () => {
            const g = runtime();
            if (!g) return;
            callGameVoid(g, g[hide]);
        });
    };

    bindHover('captureSelectGroup', 'showCaptureTooltip', 'hideCaptureTooltip');
    bindHover('autoSelectGroup', 'showAutoTooltip', 'hideAutoTooltip');
    bindHover('forfeitBtn', 'showForfeitTooltip', 'hideForfeitTooltip');

    // ─── Farming metrics (UI only) ───
    on('farmingMetricsItemSelect', 'change', function (this: HTMLElement) {
        callGame('setFarmingMetricsSelectedItem', (this as HTMLSelectElement).value);
        callGame('refreshFarmingMetricsModal');
    });

    on('farmingMetricsEstimationSelect', 'change', () => {
        callGame('refreshFarmingMetricsModal');
    });

    // ─── Auto settings toggles ───
    on('autoMasterToggle', 'change', () => {
        facade.dispatch({ type: 'TOGGLE_AUTO_MASTER' });
    });

    on('autoSwitchDisadvantageCheck', 'change', () => { callGame('toggleAutoSetting', 'disadvantage'); });
    on('autoSwitchStaminaCheck', 'change', () => { callGame('toggleAutoSetting', 'stamina'); });
    on('autoSwitchAdvantageCheck', 'change', () => { callGame('toggleAutoSetting', 'advantage'); });
    on('autoUltimateCheck', 'change', () => { callGame('toggleAutoSetting', 'ultimate'); });
    on('autoSwitchAdvancedCheck', 'change', () => { callGame('toggleAutoSetting', 'advanced'); });

    (['Safe', 'Balanced', 'Aggressive', 'Custom'] as const).forEach((suffix) => {
        on(`autoAdvancedPreset${suffix}`, 'click', function (this: HTMLElement) {
            const preset = (this as HTMLButtonElement).dataset.preset;
            if (preset) callGame('setAutoFightAdvancedPreset', preset);
        });
    });

    on('autoFightPostureSlider', 'input', function (this: HTMLElement) {
        callGame('setAutoFightSwitchPosture', Number((this as HTMLInputElement).value));
        callGame('markAutoFightAdvancedCustom');
    });
    on('autoFightMovePrefSlider', 'input', function (this: HTMLElement) {
        callGame('setAutoFightMovePreference', Number((this as HTMLInputElement).value));
        callGame('markAutoFightAdvancedCustom');
    });
    on('autoFightSwitchGainSlider', 'input', function (this: HTMLElement) {
        callGame('setAutoFightSwitchGainPct', Number((this as HTMLInputElement).value));
        callGame('markAutoFightAdvancedCustom');
    });

    on('autoAdvancedRespectPreferredCheck', 'change', function (this: HTMLElement) {
        callGame('setAutoFightAdvancedOption', 'respectPreferredActive', (this as HTMLInputElement).checked);
    });
    on('autoExcludeSlot1Select', 'change', function (this: HTMLElement) {
        callGame('setAutoFightExcludedSlot', 0, Number((this as HTMLSelectElement).value));
    });
    on('autoExcludeSlot2Select', 'change', function (this: HTMLElement) {
        callGame('setAutoFightExcludedSlot', 1, Number((this as HTMLSelectElement).value));
    });

    on('autoAdvancedNeverWeakCheck', 'change', function (this: HTMLElement) {
        callGame('setAutoFightAdvancedOption', 'neverSendWeakMatchup', (this as HTMLInputElement).checked);
    });
    on('autoAdvancedAvoidDoubleWeakCheck', 'change', function (this: HTMLElement) {
        callGame('setAutoFightAdvancedOption', 'avoidDoubleWeakness', (this as HTMLInputElement).checked);
    });
    on('autoAdvancedSkipFinishCheck', 'change', function (this: HTMLElement) {
        callGame('setAutoFightAdvancedOption', 'skipIfCanFinish', (this as HTMLInputElement).checked);
    });
    on('autoAdvancedPreferXpCheck', 'change', function (this: HTMLElement) {
        callGame('setAutoFightAdvancedOption', 'preferXpEligible', (this as HTMLInputElement).checked);
    });

    on('autoOptimalMovesCheck', 'change', (ev) => {
        const t = ev.target as HTMLInputElement | null;
        if (t && game && game.unlockedFeatures?.autoFightAdvanced) {
            t.checked = true;
            return;
        }
        if (t && game && typeof game.setOptimalMoveSelectionFromModal === 'function') {
            game.setOptimalMoveSelectionFromModal(!!t.checked);
        }
    });

    // ─── Settings ───
    on('optLanguageSelect', 'change', function (this: HTMLElement) {
        facade.dispatch({ type: 'SET_LANGUAGE', lang: (this as HTMLSelectElement).value });
    });

    on('optDamagePopupModeSelect', 'change', function (this: HTMLElement) {
        facade.dispatch({ type: 'SET_DAMAGE_POPUP_MODE', mode: (this as HTMLSelectElement).value });
    });

    on('optOfflineReportSlider', 'input', function (this: HTMLElement) {
        callGame('updateOfflineReportSliderLabel', (this as HTMLInputElement).value);
    });

    on('optOfflineReportSlider', 'change', function (this: HTMLElement) {
        callGame('updateOfflineReportFromSlider', Number((this as HTMLInputElement).value));
    });

    on('optHeaderSkinSelect', 'change', function (this: HTMLElement) {
        facade.dispatch({ type: 'SET_HEADER_SKIN', skinId: (this as HTMLSelectElement).value });
    });

    on('optHeaderPanelOpacitySlider', 'input', function (this: HTMLElement) {
        const v = (this as HTMLInputElement).value;
        callGame('updateHeaderPanelOpacitySliderLabel', v);
        callGame('setHeaderPanelOpacityFromSlider', v);
    });

    on('optHeaderPanelOpacitySlider', 'change', function (this: HTMLElement) {
        const v = Number((this as HTMLInputElement).value);
        callGame('setHeaderPanelOpacityFromSlider', v);
        callGame('saveGame');
    });
}

// Storage & recycler search bindings — called AFTER Svelte components mount
// (DOM elements live inside TeamPanel.svelte / ShopPanel.svelte, not in static HTML)
export function initLateHtmlBindings(): void {
    if (lateDone) return;
    lateDone = true;

    const onLate = function (id: string, event: string, fn: ListenerFn): void {
        const el = document.getElementById(id);
        if (el) el.addEventListener(event, fn);
    };

    // TeamPanel.svelte replaces legacy DOM — bind after mount
    bindTooltipEvent('teamContributionInfoIcon', 'showTeamContributionTooltip');
    bindTooltipEvent('pensionContributionInfoIcon', 'showPensionContributionTooltip');

    onLate('storageSearchInput', 'input', () => { callGame('updateStorageDisplay'); });
    onLate('storageTypeFilter', 'change', () => { callGame('updateStorageDisplay'); });
    onLate('storageTypeFilter2', 'change', () => { callGame('updateStorageDisplay'); });
    onLate('storageGenFilter', 'change', () => { callGame('updateStorageDisplay'); });
    onLate('pokedexSearchInput', 'input', () => { callGame('updatePokedexDisplay'); });
    onLate('pokedexGenFilter', 'change', () => { callGame('updatePokedexDisplay'); });
    onLate('collectionBonusGenFilter', 'change', () => {
        const el = document.getElementById('collectionBonusGenFilter') as HTMLSelectElement | null;
        const g = runtime();
        if (g && el) {
            g.collectionBonusGenFilter = el.value;
            if (typeof g.updatePokedexDisplay === 'function') g.updatePokedexDisplay();
        }
    });
    onLate('collectionBonusOwnershipFilter', 'change', () => {
        const el = document.getElementById('collectionBonusOwnershipFilter') as HTMLSelectElement | null;
        const g = runtime();
        if (g && el) {
            g.collectionBonusOwnershipFilter = el.value;
            if (typeof g.updatePokedexDisplay === 'function') g.updatePokedexDisplay();
        }
    });
    onLate('recyclerSearchInput', 'input', () => { callGame('updateRecyclerDisplay'); });
}

// TODO(remove-legacy-staticHtmlBindings): supprimer ce pont quand tous les consommateurs seront convertis.
(globalThis as unknown as Record<string, unknown>).initStaticHtmlBindings = initStaticHtmlBindings;
