    GameClass.prototype.tryDropHeldItem = function (this: ThisGame, sourceLabel: string = 'Boss', lootMultBonus: number = 0): string | null {
        const BOSS_HELD_ITEMS: string[] = [
            'focus_sash', 'quick_claw', 'metal_coat', 'charcoal', 'muscle_band', 'wise_glasses', 'bright_powder'
        ];
        const BOSS_HATCH_CAPSULES: string[] = [
            'hatch_capsule_common', 'hatch_capsule_common',
            'hatch_capsule_rare', 'hatch_capsule_rare',
            'hatch_capsule_epic',
            'hatch_capsule_legendary'
        ];
        const mult = 1 + Math.max(0, Number(lootMultBonus) || 0);
        const heldChance = Math.min(1, 0.01 * mult);
        const hatchCapsuleChance = Math.min(1, 0.12 * mult);
        const roll = Math.random();

        let itemKey: string | null = null;
        if (roll < heldChance) {
            itemKey = BOSS_HELD_ITEMS[Math.floor(Math.random() * BOSS_HELD_ITEMS.length)] ?? null;
        } else if (roll < heldChance + hatchCapsuleChance) {
            itemKey = BOSS_HATCH_CAPSULES[Math.floor(Math.random() * BOSS_HATCH_CAPSULES.length)] ?? null;
        } else {
            return null;
        }
        if (!itemKey) return null;

        this.addItem(itemKey, 1);
        const itemDef = (typeof ALL_ITEMS !== 'undefined' && (ALL_ITEMS as Record<string, unknown>)[itemKey])
            ? (ALL_ITEMS as Record<string, Record<string, unknown>>)[itemKey]
            : ((typeof HELD_ITEMS !== 'undefined' && (HELD_ITEMS as Record<string, unknown>)[itemKey]) ? (HELD_ITEMS as Record<string, Record<string, unknown>>)[itemKey] : null);
        const itemName = this.getLocalizedItemName(itemKey, itemDef ? ((itemDef).name as string || itemKey) : itemKey, itemDef);
        logMessage(this.t('log.bossDropLog', { source: sourceLabel, item: itemName }));
        if (!this.isOfflineSimulating) {
            if (typeof toast !== 'undefined' && toast.success) {
                toast.success(this.t('toast.bossDropTitle'), this.t('toast.bossDropBody', { item: itemName }));
            }
            if (this.notifyRareDrop) {
                showRareItemToast(itemKey);
            }
        }
        return itemKey;
    };

    GameClass.prototype.resolveMoveNameFromCtItemKey = function (this: ThisGame, ctItemKey: string): string {
        if (typeof ctItemKey !== 'string' || !ctItemKey.startsWith('ct_')) return '';
        const fromMovesDb = Object.keys(MOVES_DB || {}).find((m: string) => ('ct_' + m) === ctItemKey);
        if (fromMovesDb) return resolveMoveName(fromMovesDb);
        const fromShop = Object.values((SHOP_ITEMS || {}) as Record<string, Record<string, unknown>>).find((entry: Record<string, unknown>) =>
            entry && entry.type === 'ct' && entry.item === ctItemKey && entry.moveName
        );
        if (fromShop && fromShop.moveName) {
            return resolveMoveName(fromShop.moveName as string);
        }
        const fallback = ctItemKey.replace(/^ct_/, '').replace(/_/g, ' ');
        return resolveMoveName(fallback);
    };

    GameClass.prototype.isDamagingCtItemKey = function (this: ThisGame, ctItemKey: string): boolean {
        if (typeof ctItemKey !== 'string' || !ctItemKey.startsWith('ct_')) return true;
        const moveName = this.resolveMoveNameFromCtItemKey(ctItemKey);
        if (!moveName) return false;
        if (typeof hasMoveDefinition === 'function' && !hasMoveDefinition(moveName)) return false;
        if (typeof isDamagingMove === 'function' && !isDamagingMove(moveName)) return false;
        return true;
    };

    GameClass.prototype.removeNonDamagingCtItemsFromInventory = function (this: ThisGame, updateUI: boolean = false): number {
        if (!this.items || typeof this.items !== 'object') return 0;
        let removed = 0;
        Object.keys(this.items).forEach((itemKey: string) => {
            if (typeof itemKey !== 'string' || !itemKey.startsWith('ct_')) return;
            if (this.isDamagingCtItemKey(itemKey)) return;
            delete this.items[itemKey];
            removed++;
        });
        if (removed > 0 && updateUI) this.updateItemsDisplay();
        return removed;
    };

    GameClass.prototype.sanitizeCreatureMoveSet = function (this: ThisGame, creature: Record<string, unknown>): void {
        if (!creature || !Array.isArray(creature.currentMoves)) return;
        const cleanedMoves = (creature.currentMoves as string[])
            .map((name: string) => resolveMoveName(name))
            .filter((name: string) => {
                if (!name) return false;
                if (!hasMoveDefinition(name)) return false;
                if (!isDamagingMove(name)) return false;
                return true;
            })
            .slice(0, 4);
        creature.currentMoves = cleanedMoves.length > 0 ? cleanedMoves : ['Charge'];

        if (!creature.movePp || typeof creature.movePp !== 'object') creature.movePp = {};
        const nextMovePp: Record<string, { current: number; max: number }> = {};
        (creature.currentMoves as string[]).forEach((name: string) => {
            const def = getMoveDefinition(name);
            const basePp = getBasePPForMove(def);
            const prev = (creature.movePp as Record<string, { current: number; max: number }>)[name];
            const prevCurrent = (prev && typeof prev.current === 'number') ? prev.current : basePp;
            nextMovePp[name] = { current: Math.max(0, Math.min(basePp, Math.floor(prevCurrent))), max: basePp };
        });
        creature.movePp = nextMovePp;
    };

    GameClass.prototype.sanitizeAllCreaturesMoves = function (this: ThisGame): void {
        const list: Record<string, unknown>[] = [];
        if (Array.isArray(this.playerTeam)) list.push(...this.playerTeam as unknown as Record<string, unknown>[]);
        if (Array.isArray(this.storage)) list.push(...this.storage as unknown as Record<string, unknown>[]);
        if (Array.isArray(this.pension)) list.push(...this.pension as unknown as Record<string, unknown>[]);
        if (this.currentPlayerCreature) list.push(this.currentPlayerCreature);
        if (this.currentEnemy) list.push(this.currentEnemy);
        const seen = new Set<Record<string, unknown>>();
        list.forEach((creature: Record<string, unknown>) => {
            if (!creature || seen.has(creature)) return;
            seen.add(creature);
            this.sanitizeCreatureMoveSet(creature);
        });
    };

    GameClass.prototype.addItem = function (this: ThisGame, itemKey: string, quantity: number = 1, updateUI: boolean = true): void {
        const item = (ALL_ITEMS as Record<string, Record<string, unknown>>)[itemKey];
        if (!item && !(typeof itemKey === 'string' && itemKey.startsWith('ct_'))) return;
        if (typeof itemKey === 'string' && itemKey.startsWith('ct_') && !isAllowedCtItemKey(itemKey)) return;
        if (typeof itemKey === 'string' && itemKey.startsWith('ct_') && !this.isDamagingCtItemKey(itemKey)) return;
        if (!this.items) this.items = {};

        const qty = Math.max(0, Math.floor(Number(quantity) || 0));
        if (qty <= 0) return;

        if (itemKey === 'talent_reroll') {
            this.talentRerolls = (this.talentRerolls || 0) + qty;
            if ((this as Record<string, unknown>)._farmingMetricsCaptureItems && (this as Record<string, unknown>)._lastCombatItemDrops && Array.isArray((this as Record<string, unknown>)._lastCombatItemDrops)) {
                for (let i = 0; i < qty; i++) ((this as Record<string, unknown>)._lastCombatItemDrops as string[]).push(itemKey);
            }
            logMessage(this.t('log.rewardTalentPill', { amount: qty }));
            this.syncTalentConsumablesInInventory();
            if (updateUI) this.updateItemsDisplay();
            return;
        }
        if (itemKey === 'talent_choice') {
            this.talentChoices = (this.talentChoices || 0) + qty;
            if ((this as Record<string, unknown>)._farmingMetricsCaptureItems && (this as Record<string, unknown>)._lastCombatItemDrops && Array.isArray((this as Record<string, unknown>)._lastCombatItemDrops)) {
                for (let i = 0; i < qty; i++) ((this as Record<string, unknown>)._lastCombatItemDrops as string[]).push(itemKey);
            }
            logMessage(this.t('log.rewardTalentPatch', { amount: qty }));
            this.syncTalentConsumablesInInventory();
            if (updateUI) this.updateItemsDisplay();
            return;
        }

        this.items[itemKey] = (this.items[itemKey] || 0) + qty;

        if ((this as Record<string, unknown>)._farmingMetricsCaptureItems && (this as Record<string, unknown>)._lastCombatItemDrops && Array.isArray((this as Record<string, unknown>)._lastCombatItemDrops)) {
            for (let i = 0; i < qty; i++) ((this as Record<string, unknown>)._lastCombatItemDrops as string[]).push(itemKey);
        }

        const displayName = this.getLocalizedItemLogLabel(itemKey, item ? item.name as string : itemKey, item, true);
        logMessage(this.t('log.itemObtained', { name: displayName, qty }));

        if (updateUI) {
            this.updateItemsDisplay();
        }
    };

    GameClass.prototype.syncTalentConsumablesInInventory = function (this: ThisGame): void {
        if (!this.items) this.items = {};
        const rerolls = Math.max(0, Math.floor(Number(this.talentRerolls) || 0));
        const choices = Math.max(0, Math.floor(Number(this.talentChoices) || 0));

        if (rerolls > 0) this.items.talent_reroll = rerolls;
        else delete this.items.talent_reroll;

        if (choices > 0) this.items.talent_choice = choices;
        else delete this.items.talent_choice;
    };

    GameClass.prototype.updateItemsDisplay = function (this: ThisGame): void {
        this.syncTalentConsumablesInInventory();
        updateItemsDisplayUI(this);
        this.updateAutoCatcherUI();
    };

