    GameClass.prototype.showItemSelectModal = function (this: ThisGame, creatureIndex: number, location: string): void {
        let creature: Record<string, unknown> | null = null;
        if (location === 'team') creature = this.playerTeam[creatureIndex] ?? null;
        else if (location === 'storage') creature = this.storage[creatureIndex] ?? null;
        else if (location === 'pension') creature = this.pension[creatureIndex] ?? null;

        const itemsData: Array<{ itemKey: string; name: string; description: string; count: number; iconHtml: string }> = [];
        Object.keys(this.items).forEach((itemKey: string) => {
            const itemQty = this.items[itemKey] ?? 0;
            const itemDef = (typeof HELD_ITEMS !== 'undefined')
                ? (HELD_ITEMS as Record<string, Record<string, unknown>>)[itemKey]
                : undefined;
            if (itemQty > 0 && itemDef) {

                if (itemDef.restrict_type && creature) {
                    if (creature.type !== itemDef.restrict_type && creature.secondaryType !== itemDef.restrict_type) {
                        return;
                    }
                }

                let iconHtml: string = (itemDef.icon as string) || 'OBJ';
                const itemImg = coerceStr(itemDef.img, '');
                if (itemImg) iconHtml = `<img src="${itemImg}" style="width:32px; height:32px; vertical-align:middle;">`;
                itemsData.push({
                    itemKey,
                    name: this.getLocalizedItemName(
                        itemKey,
                        (itemDef.name as string) || '',
                        itemDef,
                    ),
                    description: this.getLocalizedItemDescription(
                        itemKey,
                        (itemDef.description as string) || '',
                        itemDef,
                    ),
                    count: itemQty,
                    iconHtml
                });
            }
        });
        showItemSelectModalUI(itemsData, creatureIndex, location);
    };

    GameClass.prototype.openTeachCTFromBag = function (this: ThisGame, ctItemKey: string): void {
        if (typeof ctItemKey !== 'string' || !ctItemKey.startsWith('ct_')) return;
        if (!isAllowedCtItemKey(ctItemKey)) {
            if (typeof toast !== 'undefined') toast.error(this.t('modal.ct.errorTitle'), this.t('modal.ct.unknown'));
            return;
        }
        if (!this.items || !this.items[ctItemKey] || this.items[ctItemKey] <= 0) {
            if (typeof toast !== 'undefined') toast.error(this.t('modal.ct.noLongerHaveTitle'), this.t('modal.ct.noLongerHaveBody'));
            return;
        }

        if (!isCtTablesReady()) {
            runWhenCtTablesReady(
                () => this.openTeachCTFromBag(ctItemKey),
                () => {
                    if (typeof toast !== 'undefined') toast.error(this.t('modal.ct.errorTitle'), this.t('modal.ct.unknown'));
                },
            );
            return;
        }

        let moveName: string =
            Object.keys(MOVES_DB || {}).find((m: string) => ('ct_' + m) === ctItemKey) as string
            || ((Object.values(SHOP_ITEMS || {}) as Array<Record<string, unknown>>).find((entry: Record<string, unknown>) => entry && entry.type === 'ct' && entry.item === ctItemKey && entry.moveName) || {}).moveName as string
            || ctItemKey.replace(/^ct_/, '').replace(/_/g, ' ');
        moveName = resolveMoveName(moveName);
        if (!hasMoveDefinition(moveName)) {
            if (typeof toast !== 'undefined') toast.error(this.t('modal.ct.errorTitle'), this.t('modal.ct.unknown'));
            return;
        }
        if (!isDamagingMove(moveName)) {
            if (typeof toast !== 'undefined') toast.error(this.t('modal.ct.incompatibleTitle'), this.t('modal.ct.unknown'));
            return;
        }

        const moveDisplay = typeof this.getLocalizedMoveNamePlain === 'function'
            ? this.getLocalizedMoveNamePlain(moveName)
            : moveName;
        const encodedCt = encodeURIComponent(ctItemKey);

        interface TeachCTRow {
            index: number;
            location: string;
            creature: Record<string, unknown>;
            displayName: string;
            lvl: number;
        }

        const collectRows = function (this: ThisGame, list: Record<string, unknown>[], location: string): TeachCTRow[] {
            const rows: TeachCTRow[] = [];
            if (!Array.isArray(list)) return rows;
            list.forEach((creature: Record<string, unknown>, index: number) => {
                if (!creature) return;
                if (typeof canLearnCT !== 'function' || !canLearnCT(creature.name as string, moveName)) return;
                const displayName = (typeof this.getLocalizedPokemonName === 'function')
                    ? this.getLocalizedPokemonName(creature.name as string)
                    : creature.name as string;
                const lvl = Math.max(1, Math.floor(Number(creature.level) || 1));
                rows.push({ index, location, creature, displayName, lvl });
            });
            return rows;
        };

        const teamRows = collectRows.call(this, this.playerTeam, 'team');
        const storageRows = collectRows.call(this, this.storage, 'storage');
        const pensionRows = collectRows.call(this, this.pension, 'pension');
        const allRows = [...teamRows, ...storageRows, ...pensionRows];
        if (allRows.length === 0) {
            if (typeof toast !== 'undefined') {
                toast.info(this.t('modal.ct.errorTitle'), this.t('modal.ct.pickCreatureNoCompatible', { move: moveDisplay }));
            }
            return;
        }

        const renderSection = function (this: ThisGame, title: string, rows: TeachCTRow[]): string {
            if (!rows.length) return '';
            let block = `<div class="teach-ct-bag-section"><div class="teach-ct-bag-section-title">${title}</div><div class="teach-ct-bag-grid">`;
            rows.forEach((r: TeachCTRow) => {
                const spriteUrl = getPokemonSpriteUrl(r.creature.name as string, !!r.creature.isShiny, false);
                const levelLabel = this.t('modal.ct.pickCreatureLevel', { n: r.lvl });
                block += `<button type="button" class="btn teach-ct-bag-pick"
                    data-action="beginTeachCT" data-arg="${r.index}" data-arg2="${r.location}" data-arg3="${encodedCt}"
                    title="${r.displayName} (${levelLabel})"
                    aria-label="${r.displayName}">
                    <img src="${spriteUrl}" class="teach-ct-bag-sprite" alt="${r.displayName}">
                </button>`;
            });
            block += '</div></div>';
            return block;
        };

        const html = `
            <div class="stats-header">
                <h2>${this.t('modal.ct.pickCreatureTitle', { move: moveDisplay })}</h2>
                <button type="button" class="stats-close" data-action="closePickCreatureForCTModal">&#10005;</button>
            </div>
            <p class="teach-ct-hint">${this.t('modal.ct.pickCreatureHint')}</p>
            <div class="teach-ct-list teach-ct-bag-list">
            ${renderSection.call(this, this.t('modal.ct.sectionTeam'), teamRows)}
            ${renderSection.call(this, this.t('modal.ct.sectionStorage'), storageRows)}
            ${renderSection.call(this, this.t('modal.ct.sectionPension'), pensionRows)}
            </div>
            <button type="button" class="btn teach-ct-cancel" data-action="closePickCreatureForCTModal">${this.t('modal.ct.cancel')}</button>
        `;

        const existing = document.getElementById('pickCreatureForCTModal');
        if (existing) existing.remove();

        const overlay = document.createElement('div');
        overlay.id = 'pickCreatureForCTModal';
        overlay.className = 'stats-modal show';
        overlay.style.zIndex = '10000';
        const box = document.createElement('div');
        box.className = 'stats-content teach-ct-content';
        box.innerHTML = html;
        overlay.appendChild(box);
        overlay.onclick = (e: MouseEvent) => { if (e.target === overlay) overlay.remove(); };
        document.body.appendChild(overlay);
    };

    GameClass.prototype.showTeachCTModal = function (this: ThisGame, creatureIndex: number, location: string): void {
        let creature: Record<string, unknown> | undefined;
        if (location === 'team') creature = this.playerTeam[creatureIndex];
        else if (location === 'storage') creature = this.storage[creatureIndex];
        else if (location === 'pension') creature = this.pension[creatureIndex];
        if (!creature) return;

        if (!isCtTablesReady()) {
            runWhenCtTablesReady(
                () => this.showTeachCTModal(creatureIndex, location),
                () => {
                    if (typeof toast !== 'undefined') toast.error(this.t('modal.ct.errorTitle'), this.t('modal.ct.unknown'));
                },
            );
            return;
        }

        const ctEntries = Object.entries(this.items || {}).filter(([k, v]) => k.startsWith('ct_') && v > 0);
        const damagingCtEntries = ctEntries.filter(([itemKey]) => {
            const moveName = resolveMoveNameFromCTKey(itemKey);
            if (!hasMoveDefinition(moveName)) return false;
            if (typeof this.isDamagingCtItemKey === 'function' && !this.isDamagingCtItemKey(itemKey)) return false;
            return true;
        });
        if (damagingCtEntries.length === 0) {
            if (typeof toast !== 'undefined') toast.info(this.t('modal.ct.noneTitle'), this.t('modal.ct.noneBody'));
            return;
        }

        const creatureName = creature.name as string;
        const compatibleEntries = damagingCtEntries.filter(([itemKey]) =>
            canLearnCT(creatureName, resolveMoveNameFromCTKey(itemKey)),
        );

        let equipped: string[] = Array.isArray(creature.currentMoves) && creature.currentMoves.length
            ? (creature.currentMoves as string[]).slice(0, 4)
            : ['Charge'];
        if (equipped.length > 4) equipped = equipped.slice(0, 4);
        const freeSlots = Math.max(0, 4 - equipped.length);

        const displayName = typeof this.getLocalizedPokemonName === 'function'
            ? this.getLocalizedPokemonName(creatureName)
            : creatureName;

        const renderTeachCtEntryHtml = (itemKey: string, qty: number, moveName: string): string => {
            const itemDef = (ALL_ITEMS as Record<string, Record<string, unknown>>)[itemKey];
            const iconFromDef = getItemIconHTML(itemDef as UiItemLike);
            const iconHtml = iconFromDef !== 'OBJ'
                ? iconFromDef
                : `<img src="${getItemIconPath(itemKey)}" class="item-sprite-img" alt="">`;
            const moveLabel = typeof this.getLocalizedMoveNamePlain === 'function'
                ? this.getLocalizedMoveNamePlain(moveName)
                : moveName;
            const encodedItemKey = encodeURIComponent(itemKey);
            const tooltipMoveAttr = escapeHtmlText(resolveMoveName(moveName));
            return `<button type="button" class="btn teach-ct-entry teach-ct-entry-card"
                data-move-tooltip-name="${tooltipMoveAttr}"
                data-action="beginTeachCT" data-arg="${creatureIndex}" data-arg2="${location}" data-arg3="${encodedItemKey}">
                <span class="teach-ct-entry-icon">${iconHtml}</span>
                <span class="teach-ct-entry-body">
                    <span class="teach-ct-entry-name">${escapeHtmlText(moveLabel)}</span>
                    <span class="teach-ct-qty">x${qty}</span>
                </span>
            </button>`;
        };

        let html = `
            <div class="stats-header">
                <h2>${this.t('modal.ct.chooseFor', { name: displayName })}</h2>
                <button type="button" class="stats-close" data-action="closeTeachCTModal">&#10005;</button>
            </div>
        `;

        if (freeSlots > 0) {
            html += `<p class="teach-ct-hint">${this.t('modal.ct.slotFreeHint', { n: freeSlots })}</p>`;
        } else {
            html += `<p class="teach-ct-hint">${this.t('modal.ct.fullMovesHint')}</p>`;
        }

        if (compatibleEntries.length === 0) {
            html += `<p class="teach-ct-empty">${this.t('modal.ct.noCompatible')}</p>`;
        } else {
            html += '<div class="teach-ct-list" id="teachCtMovesList">';
            compatibleEntries.forEach(([itemKey, qty]) => {
                html += renderTeachCtEntryHtml(itemKey, qty, resolveMoveNameFromCTKey(itemKey));
            });
            html += '</div>';
        }

        const overlay = document.createElement('div');
        overlay.id = 'teachCTModal';
        overlay.className = 'stats-modal show';
        overlay.style.zIndex = '10000';
        const box = document.createElement('div');
        box.className = 'stats-content teach-ct-content';
        box.innerHTML = html;
        overlay.appendChild(box);
        overlay.onclick = (e: MouseEvent) => { if (e.target === overlay) overlay.remove(); };
        document.body.appendChild(overlay);
    };

    GameClass.prototype.beginTeachCT = function (this: ThisGame, creatureIndex: number, location: string, ctItemKey: string): void {
        const bagPickModal = document.getElementById('pickCreatureForCTModal');
        if (bagPickModal) bagPickModal.remove();

        let creature: Record<string, unknown> | undefined;
        if (location === 'team') creature = this.playerTeam[creatureIndex];
        else if (location === 'storage') creature = this.storage[creatureIndex];
        else if (location === 'pension') creature = this.pension[creatureIndex];
        if (!creature) return;

        if (!isCtTablesReady()) {
            runWhenCtTablesReady(
                () => this.beginTeachCT(creatureIndex, location, ctItemKey),
                () => {
                    if (typeof toast !== 'undefined') toast.error(this.t('modal.ct.errorTitle'), this.t('modal.ct.unknown'));
                },
            );
            return;
        }

        let moveName: string =
            Object.keys(MOVES_DB || {}).find((m: string) => ('ct_' + m) === ctItemKey) as string
            || ((Object.values(SHOP_ITEMS || {}) as Array<Record<string, unknown>>).find((entry: Record<string, unknown>) => entry && entry.type === 'ct' && entry.item === ctItemKey && entry.moveName) || {}).moveName as string
            || ctItemKey.replace(/^ct_/, '').replace(/_/g, ' ');
        moveName = resolveMoveName(moveName);
        if (!hasMoveDefinition(moveName)) {
            if (typeof toast !== 'undefined') toast.error(this.t('modal.ct.errorTitle'), this.t('modal.ct.unknown'));
            return;
        }
        if (!isDamagingMove(moveName)) {
            if (typeof toast !== 'undefined') toast.error(this.t('modal.ct.incompatibleTitle'), this.t('modal.ct.cannotLearn', { name: creature.name, move: this.getLocalizedMoveNamePlain(moveName) }));
            return;
        }
        if (!canLearnCT(creature.name as string, moveName)) {
            if (typeof toast !== 'undefined') toast.error(this.t('modal.ct.incompatibleTitle'), this.t('modal.ct.cannotLearn', { name: creature.name, move: this.getLocalizedMoveNamePlain(moveName) }));
            return;
        }
        if (!this.items[ctItemKey] || this.items[ctItemKey] <= 0) {
            if (typeof toast !== 'undefined') toast.error(this.t('modal.ct.noLongerHaveTitle'), this.t('modal.ct.noLongerHaveBody'));
            return;
        }

        if (!Array.isArray(creature.currentMoves) || creature.currentMoves.length === 0) {
            creature.currentMoves = ['Charge'];
        }
        if ((creature.currentMoves as string[]).length > 4) {
            creature.currentMoves = (creature.currentMoves as string[]).slice(0, 4);
        }

        if ((creature.currentMoves as string[]).includes(moveName)) {
            if (typeof toast !== 'undefined') toast.error(this.t('modal.ct.errorTitle'), this.t('modal.ct.alreadyKnown', { name: creature.name, move: this.getLocalizedMoveNamePlain(moveName) }));
            return;
        }

        if ((creature.currentMoves as string[]).length < 4) {
            this.teachCTToCreature(creatureIndex, location, ctItemKey, null);
            const m = document.getElementById('teachCTModal');
            if (m) m.remove();
            return;
        }

        if (typeof this.getTmEraserCount === 'function' && this.getTmEraserCount() < 1) {
            if (typeof toast !== 'undefined') {
                toast.info(this.t('modal.forgetMove.noItemTitle'), this.t('modal.forgetMove.noItem'));
            }
            return;
        }

        this.showTeachCTReplaceMoveModal(creatureIndex, location, ctItemKey, moveName);
    };

