import { ELU_TALENT_BOOST, scaleTalentFlat } from './eluTalentBoost.ts';
import { getAntivaxGroupPokerusMultiplier } from './antivaxPokerusMultiplier.ts';

/** Flat ult charge bonus when landing attacks (Adrenaline). */
export const ADRENALINE_ULT_FLAT_BONUS = 12;

/** Flat ult charge bonus when taking damage (Epineux). */
export const EPINEUX_ULT_FLAT_BONUS = 6;

export type TalentEluDisplayOpts = {
    /** Team stack count (required for dynamic Antivax display). */
    stackCount?: number;
    formatUltChargeDelta?: (delta: number) => string;
    formatMultDelta?: (delta: number) => string;
};

/** Base percentage values (in display units, e.g. 20 = 20%) annotated when Élu is active. */
export const TALENT_ELU_PERCENT_SPECS: Record<string, number[]> = {
    mentor: [25],
    robustesse: [25],
    collecteur: [50],
    catalyseur: [2.5],
    vengeance: [50],
    dernier_elan: [30],
    dernier_rempart: [50],
    charmeur: [25],
    aura: [10],
    maitre: [20],
    phoenix: [25, 50],
    catalyseur_supreme: [5],
    sniper: [15, 30],
    opportuniste: [50],
    muraille: [10],
    intouchable: [50],
    vampire: [20],
    berserker: [5, 50],
    sentinelle: [20],
    reflexion: [12],
    instinct_maternel: [13],
    prospecteur: [12],
    vertige: [20],
    ohko: [30, 24],
    mediateur: [20],
    regeneration: [3],
    carapace: [20],
    courant_alternatif: [20],
    acharnement: [10, 30],
    piegeur: [5],
    technicien: [35],
    cran: [40, 25, 25, 40],
    force_brute: [25],
    ecran_poudre: [100],
    derniere_volonte: [10, 10],
    second_souffle: [40],
};

export function computeEluPercentDelta(base: number): number {
    if (!Number.isFinite(base) || base <= 0) return 0;
    return base * (ELU_TALENT_BOOST - 1);
}

export function formatDeltaPercent(delta: number): string {
    const rounded = Math.round(delta * 10) / 10;
    if (Number.isInteger(rounded)) return String(rounded);
    return rounded.toFixed(1);
}

export function formatMultDeltaValue(delta: number): string {
    const rounded = Math.round(delta * 100) / 100;
    if (Number.isInteger(rounded)) return String(rounded);
    return rounded.toFixed(2).replace(/0+$/, '').replace(/\.$/, '');
}

export function formatEluBonusSuffix(delta: number): string {
    if (!Number.isFinite(delta) || delta <= 0) return '';
    return `<span class="talent-elu-bonus">(+${formatDeltaPercent(delta)}%)</span>`;
}

function wrapEluBonus(label: string): string {
    return `<span class="talent-elu-bonus">${label}</span>`;
}

function insertAt(text: string, at: number, insert: string): string {
    return text.slice(0, at) + insert + text.slice(at);
}

function escapeRegex(value: string): string {
    return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function buildNumberPattern(base: number): string {
    if (Number.isInteger(base)) {
        return escapeRegex(String(base));
    }
    const dot = base.toFixed(1);
    const comma = dot.replace('.', ',');
    if (dot === comma) return escapeRegex(dot);
    return `(?:${escapeRegex(dot)}|${escapeRegex(comma)})`;
}

function buildMultiplierNumberPattern(mult: number): string {
    if (Number.isInteger(mult)) {
        return escapeRegex(String(mult));
    }
    let dot = mult.toFixed(2).replace(/0+$/, '').replace(/\.$/, '');
    const comma = dot.replace('.', ',');
    if (dot === comma) return escapeRegex(dot);
    return `(?:${escapeRegex(dot)}|${escapeRegex(comma)})`;
}

function findPercentMatch(
    text: string,
    base: number,
    fromIndex: number,
): { index: number; length: number } | null {
    const numPat = buildNumberPattern(base);
    const re = new RegExp(`(?:~\\s*)?[+\\u2212-]?\\s*(${numPat})\\s*%`, 'g');
    re.lastIndex = fromIndex;
    const match = re.exec(text);
    if (!match) return null;
    return { index: match.index, length: match[0].length };
}

function findMultiplierTokenMatch(text: string, mult: number): { index: number; length: number } | null {
    const numPat = buildMultiplierNumberPattern(mult);
    const re = new RegExp(`[×x]\\s*(${numPat})`, 'i');
    const match = re.exec(text);
    if (!match) return null;
    return { index: match.index, length: match[0].length };
}

function findDoubleSpeedToken(text: string): { index: number; length: number } | null {
    const re = /2\s*[×x]/i;
    const match = re.exec(text);
    if (!match) return null;
    return { index: match.index, length: match[0].length };
}

function annotateUltChargeTalent(
    desc: string,
    flatBase: number,
    opts?: TalentEluDisplayOpts,
): string {
    const boosted = scaleTalentFlat(flatBase, ELU_TALENT_BOOST);
    const delta = boosted - flatBase;
    if (delta <= 0) return desc;
    const match = findDoubleSpeedToken(desc);
    if (!match) return desc;
    const label = opts?.formatUltChargeDelta?.(delta) ?? `(+${delta} charge ult)`;
    return insertAt(desc, match.index + match.length, wrapEluBonus(label));
}

function annotateAntivaxMultiplier(
    desc: string,
    count: number,
    opts?: TalentEluDisplayOpts,
): string {
    if (count <= 0) return desc;
    const base = getAntivaxGroupPokerusMultiplier(count, false);
    const boosted = getAntivaxGroupPokerusMultiplier(count, true);
    const delta = boosted - base;
    if (delta <= 0) return desc;

    const label = opts?.formatMultDelta?.(delta)
        ?? `(+${formatMultDeltaValue(delta)}×)`;
    const suffix = wrapEluBonus(label);

    const tokenMatch = findMultiplierTokenMatch(desc, base);
    if (tokenMatch) {
        return insertAt(desc, tokenMatch.index + tokenMatch.length, suffix);
    }

    const fallback = opts?.formatMultDelta?.(delta)
        ?? `(Élu: +${formatMultDeltaValue(delta)}×)`;
    return desc + wrapEluBonus(fallback);
}

function annotatePercentSpecs(desc: string, talentKey: string): string {
    const specs = TALENT_ELU_PERCENT_SPECS[talentKey];
    if (!specs?.length) return desc;

    const insertions: Array<{ at: number; text: string }> = [];
    let cursor = 0;
    for (const base of specs) {
        const match = findPercentMatch(desc, base, cursor);
        if (!match) continue;
        const delta = computeEluPercentDelta(base);
        if (delta <= 0) continue;
        const at = match.index + match.length;
        insertions.push({ at, text: formatEluBonusSuffix(delta) });
        cursor = at;
    }

    let result = desc;
    for (let i = insertions.length - 1; i >= 0; i--) {
        const { at, text } = insertions[i]!;
        result = result.slice(0, at) + text + result.slice(at);
    }
    return result;
}

export function formatPassiveTalentDescriptionWithElu(
    desc: string,
    talentKey: string,
    eluActive: boolean,
    opts?: TalentEluDisplayOpts,
): string {
    if (!eluActive || !desc || talentKey === 'elu') return desc;

    if (talentKey === 'adrenaline') {
        return annotateUltChargeTalent(desc, ADRENALINE_ULT_FLAT_BONUS, opts);
    }
    if (talentKey === 'epineux') {
        return annotateUltChargeTalent(desc, EPINEUX_ULT_FLAT_BONUS, opts);
    }
    if (talentKey === 'antivax') {
        return annotateAntivaxMultiplier(desc, opts?.stackCount ?? 0, opts);
    }

    return annotatePercentSpecs(desc, talentKey);
}

/** Suffix for stacking talent chips: delta in percentage points (e.g. 0.075 → 7.5). */
export function formatEluStackBonusSuffix(deltaFraction: number): string {
    if (!Number.isFinite(deltaFraction) || deltaFraction <= 0) return '';
    return formatEluBonusSuffix(deltaFraction * 100);
}
