/**

 * Promo code catalogue — hashes only (no plaintext codes in repo).

 * Generate hashes: node scripts/hash-promo-code.mjs YOUR-CODE

 */



import type { UnlockedFeatures } from '../src/types/game/state.ts';



export interface PromoCreatureReward {
  name: string;
  level?: number;
  isShiny?: boolean;
}

export interface PromoCodeReward {
  pokedollars?: number;
  questTokens?: number;
  essenceDust?: number;
  combatTickets?: number;
  triumphMarks?: number;
  eggs?: { common?: number; rare?: number; epic?: number; legendary?: number };
  items?: Record<string, number>;
  /** Offensive TMs rolled at redeem (same pool as mart CT aléatoire). */
  randomOffensiveCt?: number;
  creatures?: PromoCreatureReward[];
  headerSkins?: string[];
  unlockFeatures?: Partial<UnlockedFeatures>;
}



export interface PromoCodeDefinition {

  id: string;

  hash: string;

  rewards: PromoCodeReward;

  expiresAt?: string;

  requiresUnlock?: keyof UnlockedFeatures;

}



