/// <reference types="svelte" />
/**
 * Store: stats — StatsModal tab content
 */

import { facade } from '@bus/facade';
import { GameEventType as Evt } from '../bus/events.js';

class StatsStore {
  activeTab: string = $state('combat');
  tabHtml: string = $state('');
  /** Bumped on STATS_CHANGED so Svelte tab components re-read game state. */
  contentRevision: number = $state(0);
}

export const stats = new StatsStore();

facade.subscribe(Evt.STATS_CHANGED, (evt) => {
  if (!('tab' in evt)) return;
  if (evt.tab !== stats.activeTab) stats.activeTab = evt.tab;
  if (evt.html !== stats.tabHtml) stats.tabHtml = evt.html;
  stats.contentRevision++;
});
