/**
 * @file src/ui/storageDisplay.ts
 * Storage drag delegation + sort button state (cards owned by Svelte StorageGrid).
 */

import type { GameRuntime } from '../types/game.js';
import { updateDragAutoscroll } from '../lib/dragAutoscroll.ts';
import { eventTargetElement, type StorageListElement } from './uiDom.ts';

export function _bindStorageDragDelegation(game: GameRuntime, storageList: StorageListElement): void {
    if (!storageList || storageList._storageDragDelegationBound) return;
    storageList._storageDragDelegationBound = true;

    storageList.addEventListener('dragstart', (evt) => {
        const target = eventTargetElement(evt.target);
        const card = target?.closest('.creature-card[data-storage-index]');
        if (!card || !storageList.contains(card)) return;
        const storageIndex = parseInt(card.getAttribute('data-storage-index') ?? '', 10);
        if (!Number.isFinite(storageIndex) || storageIndex < 0) return;
        game.onStorageDragStart(evt, storageIndex);
    });

    storageList.addEventListener('dragend', (evt) => {
        const target = eventTargetElement(evt.target);
        const card = target?.closest('.creature-card[data-storage-index]');
        if (!card || !storageList.contains(card)) return;
        game.onCreatureDragEnd(evt);
    });
}

function getStorageDropTarget(evt: DragEvent, storageList: HTMLElement): Element | null {
    const target = eventTargetElement(evt.target);
    if (!target) return null;
    const card = target.closest('.creature-card[data-storage-index]');
    if (card && storageList.contains(card)) {
        const idx = card.getAttribute('data-storage-index');
        if (idx !== null && idx !== '') return card;
    }
    if (storageList.contains(target) || target === storageList) return storageList;
    return null;
}

export function _bindStorageDropDelegation(game: GameRuntime, storageList: StorageListElement): void {
    if (!storageList || storageList._storageDropDelegationBound) return;
    storageList._storageDropDelegationBound = true;
    storageList.classList.add('storage-drop-zone');

    function applyDragOverStyle(evt: DragEvent): void {
        evt.preventDefault();
        if (evt.dataTransfer) evt.dataTransfer.dropEffect = 'move';
        updateDragAutoscroll(evt.clientY);
        const target = getStorageDropTarget(evt, storageList);
        storageList.querySelectorAll('.team-drag-over').forEach((el) => {
            el.classList.remove('team-drag-over');
        });
        if (target) target.classList.add('team-drag-over');
    }

    storageList.addEventListener('dragenter', applyDragOverStyle);
    storageList.addEventListener('dragover', applyDragOverStyle);

    storageList.addEventListener('dragleave', (evt: DragEvent) => {
        const target = getStorageDropTarget(evt, storageList);
        if (target) target.classList.remove('team-drag-over');
    });

    storageList.addEventListener('drop', (evt: DragEvent) => {
        evt.preventDefault();
        let target = getStorageDropTarget(evt, storageList);
        if (!target && typeof document.elementsFromPoint === 'function') {
            const stack = document.elementsFromPoint(evt.clientX, evt.clientY);
            for (let i = 0; i < stack.length; i++) {
                const el = stack[i];
                if (!el || !storageList.contains(el)) continue;
                const card = el.closest('.creature-card[data-storage-index]');
                if (card && storageList.contains(card)) {
                    target = card;
                    break;
                }
                if (el === storageList || storageList.contains(el)) {
                    target = storageList;
                    break;
                }
            }
        }
        if (!target) return;
        target.classList.remove('team-drag-over');
        if (target.classList.contains('creature-card')) {
            const storageIndex = parseInt(target.getAttribute('data-storage-index') ?? '', 10);
            if (!Number.isFinite(storageIndex)) return;
            game.onDropOnStorage(evt, storageIndex);
            return;
        }
        game.onDropOnStorage(evt);
    });
}

export function updateStorageDisplayUI(game: GameRuntime): void {
    const storageList = document.getElementById('storageList');
    if (!storageList) return;
    _bindStorageDragDelegation(game, storageList);
    _bindStorageDropDelegation(game, storageList);
}

interface PensionListElement extends HTMLElement {
    _pensionDropDelegationBound?: boolean;
}

function getPensionDropTarget(evt: DragEvent, pensionList: HTMLElement): Element | null {
    const target = eventTargetElement(evt.target);
    if (!target) return null;
    const card = target.closest('.creature-card[data-pension-index]');
    if (card && pensionList.contains(card)) {
        const idx = card.getAttribute('data-pension-index');
        if (idx !== null && idx !== '') return card;
    }
    const emptyZone = target.closest('.pension-drop-zone.team-slot-empty');
    if (emptyZone && pensionList.contains(emptyZone)) return emptyZone;
    if (pensionList.contains(target) || target === pensionList) return pensionList;
    return null;
}

export function _bindPensionDragDelegation(game: GameRuntime, pensionList: PensionListElement): void {
    if (!pensionList || pensionList._pensionDropDelegationBound) return;
    pensionList._pensionDropDelegationBound = true;
    pensionList.classList.add('pension-drop-zone');

    function applyDragOverStyle(evt: DragEvent): void {
        evt.preventDefault();
        if (evt.dataTransfer) evt.dataTransfer.dropEffect = 'move';
        updateDragAutoscroll(evt.clientY);
        const target = getPensionDropTarget(evt, pensionList);
        pensionList.querySelectorAll('.team-drag-over').forEach((el) => {
            el.classList.remove('team-drag-over');
        });
        if (target) target.classList.add('team-drag-over');
    }

    pensionList.addEventListener('dragenter', applyDragOverStyle);
    pensionList.addEventListener('dragover', applyDragOverStyle);

    pensionList.addEventListener('dragleave', (evt: DragEvent) => {
        const target = getPensionDropTarget(evt, pensionList);
        if (target) target.classList.remove('team-drag-over');
    });

    pensionList.addEventListener('drop', (evt: DragEvent) => {
        evt.preventDefault();
        let target = getPensionDropTarget(evt, pensionList);
        if (!target && typeof document.elementsFromPoint === 'function') {
            const stack = document.elementsFromPoint(evt.clientX, evt.clientY);
            for (let i = 0; i < stack.length; i++) {
                const el = stack[i];
                if (!el || !pensionList.contains(el)) continue;
                if (el.classList.contains('pension-drop-zone') && el.classList.contains('team-slot-empty')) {
                    target = el;
                    break;
                }
                const card = el.closest('.creature-card[data-pension-index]');
                if (card && pensionList.contains(card)) {
                    target = card;
                    break;
                }
            }
        }
        if (!target) return;
        target.classList.remove('team-drag-over');
        if (target.classList.contains('creature-card')) {
            const pensionIndex = parseInt(target.getAttribute('data-pension-index') ?? '', 10);
            if (!Number.isFinite(pensionIndex)) return;
            game.onDropOnPension(evt, pensionIndex);
            return;
        }
        game.onDropOnPension(evt);
    });
}
