/**
 * @file src/lib/afkSummarySnapshot.ts
 * Typed snapshot for AfkTeamSummary (mode AFK header bar).
 */

import { formatNumber } from '../../formatters.ts';
import { publishDeferred } from '../bus/pub.js';
import { GameEventType as Evt } from '../bus/events.js';
import type { CreatureData } from '../types/creature.js';
import type { FarmingMetricsSession, GameRuntime } from '../types/game.js';
import { getPokemonSpriteUrl } from '../ui/utils.ts';
import { getPlayerCombatRoster } from './playerCombatRoster.ts';

export type AfkTeamSlot = {
  name: string;
  spriteUrl: string;
  hpPct: number;
  isActive: boolean;
};

export type AfkDpsPill = {
  spriteUrl: string;
  dpsText: string;
  isActive: boolean;
  isEmpty: boolean;
  title: string;
};

export type AfkFarmLine = {
  label: string;
  value: string;
};

export type AfkSummarySnapshot = {
  ariaLabel: string;
  teamLabel: string;
  noTeam: boolean;
  noTeamText: string;
  teamSlots: AfkTeamSlot[];
  dpsLabel: string;
  dpsLocked: boolean;
  dpsLockedText: string;
  dpsPills: AfkDpsPill[];
  dpsHasData: boolean;
  farmLabel: string;
  farmLocked: boolean;
  farmLockedText: string;
  farmRecSuffix: string;
  farmLines: AfkFarmLine[];
};

function tf(game: GameRuntime, key: string, fb: string): string {
  if (typeof game.t !== 'function') return fb;
  // Must call as game.t(key) — extracting t loses `this` (normalizeLanguage).
  return game.t(key);
}

function fm(game: GameRuntime, key: string, fb: string): string {
  return tf(game, `farmingMetrics.${key}`, fb);
}

function isTrainerBattle(game: GameRuntime): boolean {
  return !!(game.arenaState?.active) || !!(game.gymTrainerState && game.gymTrainerState.active);
}

function buildTeamSlots(game: GameRuntime): { noTeam: boolean; slots: AfkTeamSlot[] } {
  const roster = getPlayerCombatRoster(game);
  if (roster.length === 0) return { noTeam: true, slots: [] };

  const trainer = isTrainerBattle(game);
  const slots: AfkTeamSlot[] = [];

  for (const c of roster) {
    if (!c) continue;
    let maxHp: number;
    let curHp: number;
    if (trainer) {
      maxHp = c.maxHp || 1;
      curHp = c.currentHp ?? maxHp;
    } else if (game.currentPlayerCreature === c) {
      maxHp = typeof game.getPlayerMaxHp === 'function' ? game.getPlayerMaxHp() : (c.maxHp || 1);
      const raw = (c as CreatureData & Record<string, unknown>).mainAccountCurrentHp;
      curHp = typeof raw === 'number' ? raw : maxHp;
    } else {
      maxHp = c.maxHp || 1;
      curHp = c.currentHp ?? maxHp;
    }
    const ratio = Math.max(0, Math.min(1, (Number(curHp) || 0) / (Number(maxHp) || 1)));
    slots.push({
      name: c.name,
      spriteUrl: getPokemonSpriteUrl(c.name, !!c.isShiny, false),
      hpPct: Math.round(ratio * 100),
      isActive: game.currentPlayerCreature === c,
    });
  }

  return { noTeam: false, slots };
}

function buildDpsSection(game: GameRuntime): {
  locked: boolean;
  pills: AfkDpsPill[];
  hasData: boolean;
} {
  if (game.unlockedFeatures && !game.unlockedFeatures.dpsMeter) {
    return { locked: true, pills: [], hasData: false };
  }

  const roster = getPlayerCombatRoster(game);
  const meter = game.dpsMeter;
  const now = Date.now();
  const fmt = formatNumber;
  let hasData = false;
  const pills: AfkDpsPill[] = [];

  for (const c of roster) {
    if (!c) continue;
    const id = (c as CreatureData & Record<string, unknown>)._dpsMeterId as number | undefined;
    let dps = 0;
    let total = 0;
    if (meter && id != null && meter.done?.[id]) {
      const entry = meter.done[id];
      const elapsedSec = Math.max(1, (now - (Number(entry.firstHitAt) || now)) / 1000);
      dps = Number(entry.total) / elapsedSec;
      total = Number(entry.total);
      if (total > 0) hasData = true;
    }
    const hasDamage = total > 0;
    pills.push({
      spriteUrl: getPokemonSpriteUrl(c.name, !!c.isShiny, false),
      dpsText: hasDamage ? fmt(Math.round(dps)) : '—',
      isActive: game.currentPlayerCreature === c,
      isEmpty: !hasDamage,
      title: `${c.name} : ${hasDamage ? `${fmt(Math.round(dps))} DPS` : tf(game, 'afkSummary.noDamage', 'pas de dégâts')}`,
    });
  }

  return { locked: false, pills, hasData };
}

function buildFarmSection(
  game: GameRuntime,
): Pick<AfkSummarySnapshot, 'farmLocked' | 'farmLockedText' | 'farmRecSuffix' | 'farmLines'> {
  if (game.unlockedFeatures && !game.unlockedFeatures.farmingMetricsModal) {
    return {
      farmLocked: true,
      farmLockedText: tf(game, 'afkSummary.farmLocked', 'Verrouillé'),
      farmRecSuffix: '',
      farmLines: [],
    };
  }

  const m: FarmingMetricsSession | undefined =
    game.farmingMetrics
    ?? (typeof game.getDefaultFarmingMetrics === 'function' ? game.getDefaultFarmingMetrics() : undefined);
  const fmt = formatNumber;
  const rec = !!(m && m.recording);
  const combats = (m && m.combats) || 0;
  const money = (m && m.pokedollarsTotal) || 0;
  const xp = (m && m.xp) || 0;
  const itemKey = (m && m.selectedItemKey) || 'trade_stone';
  const itemCount = (m?.items && m.items[itemKey]) || 0;

  return {
    farmLocked: false,
    farmLockedText: '',
    farmRecSuffix: rec ? tf(game, 'afkSummary.recOn', 'ON') : tf(game, 'afkSummary.recOff', 'OFF'),
    farmLines: [
      { label: fm(game, 'combats', 'Combats'), value: fmt(combats) },
      { label: fm(game, 'moneyTotal', '$'), value: `${fmt(money)}$` },
      { label: fm(game, 'xp', 'XP'), value: fmt(xp) },
      { label: fm(game, 'selectedItem', 'Objet'), value: fmt(itemCount) },
    ],
  };
}

export function buildAfkSummarySnapshot(game: GameRuntime): AfkSummarySnapshot {
  const team = buildTeamSlots(game);
  const dps = buildDpsSection(game);
  const farm = buildFarmSection(game);

  return {
    ariaLabel: tf(game, 'afkSummary.ariaLabel', 'Résumé équipe, DPS et farm (mode AFK)'),
    teamLabel: tf(game, 'afkSummary.team', 'Équipe'),
    noTeam: team.noTeam,
    noTeamText: tf(game, 'afkSummary.noTeam', 'Aucune'),
    teamSlots: team.slots,
    dpsLabel: tf(game, 'afkSummary.dps', 'DPS'),
    dpsLocked: dps.locked,
    dpsLockedText: tf(game, 'afkSummary.dpsLocked', 'DPS (verrouillé)'),
    dpsPills: dps.pills,
    dpsHasData: dps.hasData,
    farmLabel: tf(game, 'afkSummary.farm', 'Farm'),
    ...farm,
  };
}

export function publishAfkSummaryChanged(): void {
  publishDeferred(Evt.AFK_SUMMARY_CHANGED, () => ({
    type: Evt.AFK_SUMMARY_CHANGED,
  }));
}
