/** Fallback anti-gel page : ignorer les écarts courts sans marqueur d'onglet caché. */
export const VISIBILITY_RESUME_FALLBACK_THRESHOLD_MS = 30_000;

export type VisibilityHiddenMsInput = {
    now: number;
    tabHiddenTime?: number | null;
    lastVisibleAt?: number | null;
    lastSaveTime?: number | null;
    fallbackThresholdMs?: number;
};

function positiveDelta(now: number, then: number | null | undefined): number {
    if (then == null || !Number.isFinite(then) || then <= 0) return 0;
    return Math.max(0, now - then);
}

/**
 * Durée hors-ligne à rattraper au retour d'onglet.
 * Si `tabHiddenTime` est défini (visibilitychange hidden reçu), on ne mélange
 * jamais avec lastSaveTime — évite les faux positifs quand l'autosave n'a pas
 * flush depuis ~60 s mais l'onglet n'était caché que quelques secondes.
 */
export function computeVisibilityHiddenMs(input: VisibilityHiddenMsInput): number {
    const {
        now,
        tabHiddenTime,
        lastVisibleAt,
        lastSaveTime,
        fallbackThresholdMs = VISIBILITY_RESUME_FALLBACK_THRESHOLD_MS,
    } = input;

    if (tabHiddenTime != null && Number.isFinite(tabHiddenTime) && tabHiddenTime > 0) {
        return positiveDelta(now, tabHiddenTime);
    }

    const fallbackAnchor = (
        lastVisibleAt != null && Number.isFinite(lastVisibleAt) && lastVisibleAt > 0
    )
        ? lastVisibleAt
        : lastSaveTime;

    const gap = positiveDelta(now, fallbackAnchor);
    return gap > fallbackThresholdMs ? gap : 0;
}
