import { buildAutoSaveSignature } from './autoSaveSignature.ts';
import {
    AUTOSAVE_CHECK_INTERVAL_MS,
    AUTOSAVE_COMBAT_MIN_FLUSH_MS,
    AUTOSAVE_MIN_FLUSH_MS,
} from './autoSaveConstants.ts';
import type { GameRuntime } from '../types/game.ts';

export type AutoSaveFlushReason = 'pending' | 'dirty' | 'periodic';

export type AutoSaveTickAction =
    | { type: 'noop' }
    | { type: 'clear_pending' }
    | { type: 'defer_combat'; signature: string }
    | { type: 'defer_min_interval'; signature: string }
    | { type: 'flush'; signature: string; reason: AutoSaveFlushReason };

export const VISIBILITY_AUTOSAVE_DEBOUNCE_MS = 2_000;

export function getAutoSaveLastFlushAt(game: Pick<GameRuntime, '_lastAutoSaveAt'>): number | null {
    const value = game._lastAutoSaveAt;
    if (typeof value !== 'number' || !Number.isFinite(value) || value <= 0) return null;
    return value;
}

export function canPerformAutoSaveFlush(
    game: Pick<GameRuntime, '_lastAutoSaveAt'>,
    opts?: { force?: boolean; now?: number; minFlushMs?: number },
): boolean {
    if (opts?.force) return true;
    const lastSave = getAutoSaveLastFlushAt(game);
    if (lastSave == null) return false;
    const now = opts?.now ?? Date.now();
    const minFlushMs = opts?.minFlushMs ?? AUTOSAVE_MIN_FLUSH_MS;
    return now - lastSave >= minFlushMs;
}

export function shouldShowAutoSaveIndicator(
    game: Pick<GameRuntime, '_lastAutoSaveIndicatorAt'>,
    reason: AutoSaveFlushReason,
    opts?: { now?: number; minIntervalMs?: number },
): boolean {
    if (reason === 'periodic') return false;
    const now = opts?.now ?? Date.now();
    const minIntervalMs = opts?.minIntervalMs ?? AUTOSAVE_MIN_FLUSH_MS;
    const lastShown = game._lastAutoSaveIndicatorAt;
    if (typeof lastShown === 'number' && Number.isFinite(lastShown) && lastShown > 0) {
        if (now - lastShown < minIntervalMs) return false;
    }
    return true;
}

export function evaluateAutoSaveTick(params: {
    pendingSignature: string | null | undefined;
    inCombat: boolean;
    now: number;
    lastSaveAt: number;
    lastSignature: string | null;
    currentSignature: string;
    minFlushMs?: number;
    combatMinFlushMs?: number;
}): AutoSaveTickAction {
    const minFlushMs = params.minFlushMs ?? AUTOSAVE_MIN_FLUSH_MS;
    const combatMinFlushMs = params.combatMinFlushMs ?? AUTOSAVE_COMBAT_MIN_FLUSH_MS;
    const pending = params.pendingSignature;
    const lastSave = params.lastSaveAt ?? 0;
    const dirty = pending != null || params.lastSignature !== params.currentSignature;
    const intervalElapsed = params.now - lastSave >= minFlushMs;
    const signature = pending || params.currentSignature;

    if (params.inCombat) {
        if (params.now - lastSave < combatMinFlushMs || !intervalElapsed) {
            if (dirty) return { type: 'defer_combat', signature };
            return { type: 'noop' };
        }
        if (dirty) return { type: 'defer_combat', signature };
        return { type: 'noop' };
    }

    if (intervalElapsed) {
        let reason: AutoSaveFlushReason = 'periodic';
        if (pending) reason = 'pending';
        else if (dirty) reason = 'dirty';
        return { type: 'flush', signature, reason };
    }

    if (!dirty) return { type: 'clear_pending' };

    return { type: 'defer_min_interval', signature };
}

export function shouldFlushVisibilityAutoSave(params: {
    now: number;
    lastSaveAt: number;
    lastSignature: string | null;
    currentSignature: string;
    pendingSignature: string | null | undefined;
    minFlushMs?: number;
    force?: boolean;
}): boolean {
    if (params.force) return true;
    const minFlushMs = params.minFlushMs ?? AUTOSAVE_MIN_FLUSH_MS;
    return params.now - (params.lastSaveAt ?? 0) >= minFlushMs;
}

type IdleCapableWindow = Window & {
    requestIdleCallback?: (cb: () => void, opts?: { timeout?: number }) => number;
    cancelIdleCallback?: (id: number) => void;
};

export function scheduleIdleAutoSaveFlush(
    runFlush: () => void,
    isAlreadyScheduled: () => boolean,
    markScheduled: (scheduled: boolean) => void,
): void {
    if (isAlreadyScheduled()) return;
    markScheduled(true);

    const win = typeof window !== 'undefined' ? (window as IdleCapableWindow) : undefined;
    const done = () => {
        markScheduled(false);
        runFlush();
    };

    if (win && typeof win.requestIdleCallback === 'function') {
        win.requestIdleCallback(done, { timeout: 2000 });
        return;
    }
    setTimeout(done, 0);
}

/** @deprecated Prefer bindAutoSaveInterval — kept for unit tests. */
export function replaceAutoSaveInterval(
    existingId: ReturnType<typeof setInterval> | null | undefined,
    tick: () => void,
    intervalMs: number,
): ReturnType<typeof setInterval> {
    if (existingId != null) {
        clearInterval(existingId);
    }
    return setInterval(tick, intervalMs);
}

// ─── Module-level autosave interval (single timer across HMR / re-bind) ───

let autoSaveIntervalId: ReturnType<typeof setInterval> | null = null;
let autoSaveBoundGame: GameRuntime | null = null;

export function bindAutoSaveInterval(game: GameRuntime, intervalMs: number = AUTOSAVE_CHECK_INTERVAL_MS): void {
    autoSaveBoundGame = game;
    if (autoSaveIntervalId != null) return;

    autoSaveIntervalId = setInterval(() => {
        const bound = autoSaveBoundGame;
        if (!bound || typeof bound.tickAutoSave !== 'function') return;
        if (typeof document !== 'undefined' && document.hidden) return;
        bound.tickAutoSave();
    }, intervalMs);
}

export function resetAutoSaveIntervalForTests(): void {
    if (autoSaveIntervalId != null) {
        clearInterval(autoSaveIntervalId);
        autoSaveIntervalId = null;
    }
    autoSaveBoundGame = null;
    resetAutoSaveLifecycleForTests();
}

export function getAutoSaveIntervalIdForTests(): ReturnType<typeof setInterval> | null {
    return autoSaveIntervalId;
}

// ─── Visibility / page lifecycle (debounced hidden flush, force on unload) ───

let lifecycleBound = false;
let lifecycleGame: GameRuntime | null = null;
let visibilityDebounceId: ReturnType<typeof setTimeout> | null = null;

type FlushableGame = GameRuntime & {
    flushAutoSaveInternal?: (signature: string, immediate: boolean, reason?: AutoSaveFlushReason) => void;
};

function requestVisibilityAutoSaveFlush(game: FlushableGame, force: boolean): void {
    if (typeof game.flushAutoSaveInternal !== 'function') return;

    const now = Date.now();
    const pending = game._pendingAutoSaveSignature;
    const currentSignature = buildAutoSaveSignature(game);
    const signature = pending || currentSignature;

    if (!shouldFlushVisibilityAutoSave({
        now,
        lastSaveAt: getAutoSaveLastFlushAt(game) ?? now,
        lastSignature: game._lastAutoSaveSignature,
        currentSignature,
        pendingSignature: pending,
        force,
    })) {
        return;
    }

    const dirty = pending != null || game._lastAutoSaveSignature !== currentSignature;
    let reason: AutoSaveFlushReason = 'periodic';
    if (pending) reason = 'pending';
    else if (dirty) reason = 'dirty';

    game.flushAutoSaveInternal(signature, force, reason);
}

function cancelVisibilityAutoSaveDebounce(): void {
    if (visibilityDebounceId != null) {
        clearTimeout(visibilityDebounceId);
        visibilityDebounceId = null;
    }
}

function scheduleVisibilityAutoSaveDebounce(): void {
    cancelVisibilityAutoSaveDebounce();
    visibilityDebounceId = setTimeout(() => {
        visibilityDebounceId = null;
        if (!lifecycleGame || typeof document === 'undefined') return;
        if (document.visibilityState !== 'hidden') return;
        requestVisibilityAutoSaveFlush(lifecycleGame as FlushableGame, false);
    }, VISIBILITY_AUTOSAVE_DEBOUNCE_MS);
}

function onPageHideForceSave(): void {
    cancelVisibilityAutoSaveDebounce();
    if (!lifecycleGame) return;
    requestVisibilityAutoSaveFlush(lifecycleGame as FlushableGame, true);
}

export function bindAutoSaveLifecycle(game: GameRuntime): void {
    lifecycleGame = game;
    if (lifecycleBound || typeof document === 'undefined') return;
    lifecycleBound = true;

    document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'hidden') {
            scheduleVisibilityAutoSaveDebounce();
            return;
        }
        cancelVisibilityAutoSaveDebounce();
    });

    if (typeof window !== 'undefined') {
        window.addEventListener('pagehide', onPageHideForceSave);
        window.addEventListener('beforeunload', onPageHideForceSave);
    }
}

export function resetAutoSaveLifecycleForTests(): void {
    cancelVisibilityAutoSaveDebounce();
    lifecycleBound = false;
    lifecycleGame = null;
}
