/**
 * Visibility rules for combat-area Rocket mini-bars (staking vs casino).
 */

import { isMobileViewport } from '../ui/breakpoints.ts';
import type {
  RocketCasinoBackgroundSessionSnapshot,
  RocketRealtimeSnapshot,
  RocketStakingSessionSnapshot,
  RocketStakingSnapshot,
} from '../bus/snapshots.js';

export function resolveMobileExtrasPanelActive(): boolean {
  if (typeof document === 'undefined') return true;
  if (!isMobileViewport()) return true;
  return !!document.querySelector('.secondary-content.mobile-active');
}

export function resolveRocketStakingSessionForUi(
  staking: RocketStakingSnapshot,
  realtime: RocketRealtimeSnapshot,
): RocketStakingSessionSnapshot | null {
  if (!staking.session) return null;
  return realtime.session ?? staking.session;
}

export function resolveTeamRocketUiVisible(
  isTeamRocketTabActive: boolean,
  isMobileExtrasPanelActive = true,
): boolean {
  return isTeamRocketTabActive && isMobileExtrasPanelActive;
}

export interface RocketCombatMiniBarVisibilityInput {
  stakingSession: RocketStakingSessionSnapshot | null;
  casinoBackgroundSession: RocketCasinoBackgroundSessionSnapshot | null;
  isTeamRocketTabActive: boolean;
  /** False on mobile when Combat/Team panel is active; default true (desktop). */
  isMobileExtrasPanelActive?: boolean;
}

export interface RocketCombatMiniBarVisibility {
  showStakingMini: boolean;
  showCasinoMini: boolean;
}

export function resolveRocketCombatMiniBarVisibility(
  input: RocketCombatMiniBarVisibilityInput,
): RocketCombatMiniBarVisibility {
  const hasStakingSession = !!input.stakingSession;
  const extrasActive =
    input.isMobileExtrasPanelActive ?? resolveMobileExtrasPanelActive();
  const teamRocketUiVisible = resolveTeamRocketUiVisible(
    input.isTeamRocketTabActive,
    extrasActive,
  );
  const showStakingMini = hasStakingSession && !teamRocketUiVisible;
  const showCasinoMini =
    !showStakingMini && !!(input.casinoBackgroundSession?.visible);
  return { showStakingMini, showCasinoMini };
}
