/**
 * Escape a string for embedding inside a single-quoted JavaScript literal
 * in an HTML inline handler (ondragstart, onclick, etc.).
 * Backslashes must be escaped before quotes.
 */
export function escapeForInlineJsString(value: string): string {
    return String(value).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
}

/**
 * Build the move-name argument as it appears in creature modal drag handlers.
 */
export function escapeMoveNameForInlineJs(moveName: string): string {
    return escapeForInlineJsString(moveName);
}
