/**
 * Passive growth timing (Temps x2, projections) with wing (passiveGain_*) expiration.
 */

export interface PassiveGrowthWingBoost {
  type?: string;
  value?: number;
  endTime?: number;
}

export interface PassiveGrowthWingState {
  multiplier: number;
  endTime: number;
}

export interface ComputePassiveGrowthMetricsInput {
  currentValue: number;
  baseGainPerSec: number;
  wingMultiplier: number;
  wingEndTimeMs: number | null;
  nowMs: number;
  horizonSec: number;
}

export interface PassiveGrowthMetricsResult {
  doublingSeconds: number;
  projectedAtHorizon: number;
}

/** Active wing (Aile) for a stat — `passiveGain_<statKey>` in activeBoosts. */
export function getPassiveGainWingState(
  activeBoosts: PassiveGrowthWingBoost[],
  statKey: string,
  nowMs: number,
): PassiveGrowthWingState | null {
  const targetType = `passiveGain_${String(statKey || '')}`;
  for (let i = 0; i < activeBoosts.length; i++) {
    const b = activeBoosts[i];
    if (!b || b.type !== targetType) continue;
    const end = Number(b.endTime);
    if (!Number.isFinite(end) || end <= nowMs) continue;
    const m = 1 + (Number(b.value) || 0);
    return { multiplier: m > 1 ? m : 1, endTime: end };
  }
  return null;
}

/**
 * Points needed to double = currentValue. Integrates boosted then base gain until wing expires.
 */
export function computePassiveGrowthMetrics(
  input: ComputePassiveGrowthMetricsInput,
): PassiveGrowthMetricsResult {
  const currentValue = Math.max(0, Number(input.currentValue) || 0);
  const baseGain = Math.max(0, Number(input.baseGainPerSec) || 0);
  const wingMult = Number(input.wingMultiplier) > 1 ? Number(input.wingMultiplier) : 1;
  const wingEnd = input.wingEndTimeMs;
  const now = Number(input.nowMs) || 0;
  const horizon = Math.max(0, Number(input.horizonSec) || 0);

  if (currentValue <= 0 || baseGain <= 0) {
    return { doublingSeconds: Infinity, projectedAtHorizon: currentValue };
  }

  const targetGain = currentValue;

  if (wingMult <= 1 || wingEnd == null || !Number.isFinite(wingEnd) || wingEnd <= now) {
    return {
      doublingSeconds: targetGain / baseGain,
      projectedAtHorizon: currentValue + baseGain * horizon,
    };
  }

  const tWingSec = Math.max(0, (wingEnd - now) / 1000);
  const gBoosted = baseGain * wingMult;
  const gainDuringWing = gBoosted * tWingSec;

  let doublingSeconds: number;
  if (gainDuringWing >= targetGain) {
    doublingSeconds = targetGain / gBoosted;
  } else {
    doublingSeconds = tWingSec + (targetGain - gainDuringWing) / baseGain;
  }

  const boostedHorizon = Math.min(tWingSec, horizon);
  const normalHorizon = Math.max(0, horizon - boostedHorizon);
  const projectedAtHorizon = currentValue + gBoosted * boostedHorizon + baseGain * normalHorizon;

  return { doublingSeconds, projectedAtHorizon };
}
