/// <reference types="svelte" />
import { facade } from '@bus/facade';
import { GameEventType as Evt } from '../bus/events.js';
import type { ExpeditionPanelUiSnapshot, ExpeditionSnapshot } from '../bus/snapshots.js';

const EMPTY_UI: ExpeditionPanelUiSnapshot = {
  language: 'fr',
  masteryLabel: 'Maîtrises',
  slotsPrefix: 'Slots :',
  availableTitle: 'Missions Disponibles',
  runningTitle: 'En cours',
};

const EMPTY: ExpeditionSnapshot = {
  ui: EMPTY_UI,
  slotsLabel: '0/0',
  availableHtml: '',
  activeHtml: '',
};

class ExpeditionStore {
  snapshot: ExpeditionSnapshot = $state(EMPTY);
}

export const expedition = new ExpeditionStore();

facade.subscribe(Evt.EXPEDITION_CHANGED, (evt) => {
  if (!('expedition' in evt)) return;
  expedition.snapshot = evt.expedition;
});
