<script lang="ts">
  import { onMount } from 'svelte';
  import { shop } from '../../stores/shop.svelte.ts';
  import { game } from '../../../gameManager.js';
  import { uiText } from '../../ui/i18n.ts';
  import { facade } from '../../bus/gameFacade.js';
  import { formatNumber } from '../../../formatters.ts';
  import RecyclerShardsPanel from './RecyclerShardsPanel.svelte';
  import RecyclerDustShopPanel from './RecyclerDustShopPanel.svelte';

  let snap = $derived(shop.snapshot);
  let ui = $derived(snap.ui);
  let shardsPanel: RecyclerShardsPanel | undefined = $state();

  let massConfirmRarity = $state<string | null>(null);
  let massConfirmStep = $state(0);

  const RARITIES = ['common', 'rare', 'epic', 'legendary'] as const;

  let massLabels = $derived({
    common: uiText('shop.recyclerRecycleAllCommon', 'Recycler tout Common', {}, game),
    rare: uiText('shop.recyclerRecycleAllRare', 'Recycler tout Rare', {}, game),
    epic: uiText('shop.recyclerRecycleAllEpic', 'Recycler tout Epic', {}, game),
    legendary: uiText('shop.recyclerRecycleAllLegendary', 'Recycler tout Legendary', {}, game),
  });

  let confirmLabel = $derived(uiText('shop.recyclerMassConfirmBtn', 'Confirmer', {}, game));
  let sureLabel = $derived(uiText('shop.recyclerMassConfirmSure', 'Sure ?', {}, game));
  let cancelLabel = $derived(uiText('shop.recyclerMassCancel', 'Annuler', {}, game));

  function computeMassStats(rarity: string): { count: number; dust: number; dustFormatted: string } {
    const protectedSet = new Set<string>([]);
    let count = 0;
    let dust = 0;
    for (const entry of snap.recyclerShards) {
      if (entry.rarity !== rarity) continue;
      if (entry.isProtected) continue;
      count += entry.count;
      dust += entry.dustValue;
    }
    return { count, dust, dustFormatted: formatNumber(dust) };
  }

  let massStats = $derived(
    massConfirmRarity ? computeMassStats(massConfirmRarity) : null
  );

  function confirmMassTitle(stats: { count: number; dustFormatted: string }): string {
    return uiText('shop.recyclerMassConfirm',
      'Confirmer : recycler {count} shards \u2192 {dust} Poussi\u00e8re ?',
      { count: stats.count, dust: stats.dustFormatted },
      game
    );
  }

  let confirmMassTitleDerived = $derived(
    massStats ? confirmMassTitle(massStats) : ''
  );

  function startMassRecycle(rarity: string) {
    const stats = computeMassStats(rarity);
    if (stats.count <= 0) return;
    massConfirmRarity = rarity;
    massConfirmStep = 0;
  }

  function confirmMassRecycle() {
    if (!massConfirmRarity) return;
    if (massConfirmStep === 0) {
      massConfirmStep = 1;
      return;
    }
    facade.dispatch({ type: 'RECYCLE_ALL_BY_RARITY', rarity: massConfirmRarity });
    massConfirmRarity = null;
    massConfirmStep = 0;
  }

  function cancelMassRecycle() {
    massConfirmRarity = null;
    massConfirmStep = 0;
  }

  function handleSearchInput(e: Event) {
    massConfirmRarity = null;
    massConfirmStep = 0;
  }

  onMount(() => {
    const onClosePopover = () => shardsPanel?.closePopover();
    document.addEventListener('poketime:recyclerClosePopover', onClosePopover);
    return () => document.removeEventListener('poketime:recyclerClosePopover', onClosePopover);
  });
</script>

<div class="recycler-content" id="recyclerContent">
  <div class="sub-tabs-container recycler-sub-tabs" role="tablist" aria-label={ui.subTabsAriaLabel}>
    <button
      id="recyclerSubTab-shards"
      type="button"
      class="sub-tab-btn active"
      role="tab"
      aria-selected="true"
      aria-controls="recycler-shards"
      tabindex="0"
      data-action="switchRecyclerSubTab"
      data-arg="shards"
    >
      <span id="recyclerSubShardsLabel">{ui.recyclerShardsTitle}</span>
    </button>
    <button
      id="recyclerSubTab-dust"
      type="button"
      class="sub-tab-btn"
      role="tab"
      aria-selected="false"
      aria-controls="recycler-dust"
      tabindex="-1"
      data-action="switchRecyclerSubTab"
      data-arg="dust"
    >
      <span id="recyclerSubDustLabel">{ui.recyclerDustShopTitle}</span>
    </button>
  </div>

  <div
    class="sub-tab-content recycler-sub-tab-panel active"
    id="recycler-shards"
    role="tabpanel"
    aria-labelledby="recyclerSubTab-shards"
  >
    <div class="recycler-toolbar">
      <input
        id="recyclerSearchInput"
        type="search"
        class="recycler-search-input"
        placeholder={ui.recyclerSearchPlaceholder}
        oninput={handleSearchInput}
      >
      <button
        id="recyclerSort-rarity"
        type="button"
        class="sort-btn"
        class:active={snap.recyclerSortRarityActive}
        data-action="toggleRecyclerSort"
        data-arg="rarity"
      >
        <span id="recyclerSortRarityLabel">{ui.recyclerSortRarity}</span>
      </button>
      <button
        id="recyclerSort-count"
        type="button"
        class="sort-btn"
        class:active={snap.recyclerSortCountActive}
        data-action="toggleRecyclerSort"
        data-arg="count"
      >
        <span id="recyclerSortCountLabel">{ui.recyclerSortCount}</span>
      </button>
      {#each RARITIES as rarity}
        <button
          id="recyclerMass-{rarity}"
          type="button"
          class="sort-btn"
          onclick={() => startMassRecycle(rarity)}
        ><span>{massLabels[rarity]}</span></button>
      {/each}
    </div>

    {#if massConfirmRarity}
      <div class="recycler-mass-confirm-bar">
        <span class="recycler-mass-confirm-text">{confirmMassTitleDerived}</span>
        <button id="recyclerMassConfirm" type="button" class="sort-btn" class:sure={massConfirmStep === 1} onclick={confirmMassRecycle}>
          <span>{massConfirmStep === 1 ? sureLabel : confirmLabel}</span>
        </button>
        <button id="recyclerMassCancel" type="button" class="sort-btn" onclick={cancelMassRecycle}>
          <span>{cancelLabel}</span>
        </button>
      </div>
    {/if}

    <RecyclerShardsPanel bind:this={shardsPanel} />
  </div>

  <div
    class="sub-tab-content recycler-sub-tab-panel"
    id="recycler-dust"
    role="tabpanel"
    aria-labelledby="recyclerSubTab-dust"
    hidden
  >
    <RecyclerDustShopPanel />
  </div>
</div>
