<script lang="ts">
  import type { StorageCardSnapshot } from '../bus/snapshots.js';
  import { game } from '../../gameManager.js';
  import { _bindStorageDragDelegation, _bindStorageDropDelegation } from '../ui/storageDisplay.ts';
  import { uiText } from '../ui/i18n.ts';
  import { team } from '../stores/team.svelte.ts';
  import { isStorageRosterAppendOnly, storageRosterSignature } from '../stores/storeUtils.js';
  import { captureUiScrollPositions, restoreUiScrollPositions } from '../lib/uiScrollPreserve.ts';
  import {
    cancelStorageExpansion,
    requestStorageExpansion,
  } from '../lib/storageGridExpansion.ts';
  import {
    clampStorageWindow,
    DEFAULT_STORAGE_ROW_HEIGHT,
    getStorageVirtualSpacerHeights,
    measureStableGridMetrics,
    syncStorageWindowFromScroll,
    type GridRowMetrics,
  } from '../lib/storageVirtualScroll.ts';
  import { getLazyListScrollRoot } from '../../formatters.ts';
  import { isMobileViewport } from '../ui/breakpoints.ts';
  import { bindVirtualGridResizeSync } from '../lib/virtualGridResizeSync.ts';
  import CreatureCard from './CreatureCard.svelte';
  import type { UltimateSlotStatBlock } from '../lib/ultimateSlotPreview.ts';

  const STORAGE_BATCH_SIZE = 24;
  const STORAGE_BATCH_SIZE_MOBILE = 12;
  const STORAGE_CHUNK_SIZE = 6;
  const STORAGE_CHUNK_SIZE_MOBILE = 4;
  /** Max cards in DOM — sliding window when scrolling large rosters. */
  const STORAGE_MAX_DOM = 120;
  const STORAGE_MAX_DOM_MOBILE = 60;

  function effectiveBatchSize(propBatch: number): number {
    return isMobileViewport() ? STORAGE_BATCH_SIZE_MOBILE : propBatch;
  }

  function effectiveChunkSize(): number {
    return isMobileViewport() ? STORAGE_CHUNK_SIZE_MOBILE : STORAGE_CHUNK_SIZE;
  }

  function effectiveMaxDom(): number {
    return isMobileViewport() ? STORAGE_MAX_DOM_MOBILE : STORAGE_MAX_DOM;
  }

  let {
    creatures = [],
    batchSize = STORAGE_BATCH_SIZE,
    listId = 'storageList',
    pickMode = undefined,
    forceSpriteOnly = false,
    showEmptyFiltered = undefined,
    scrollRootSelector = '.team-area',
    ultimateSlotBonusMaxima = null,
    ultimateSlotBonusTotalMax = 0,
  }: {
    creatures?: StorageCardSnapshot[];
    batchSize?: number;
    listId?: string;
    pickMode?: 'ultimateSlot' | undefined;
    forceSpriteOnly?: boolean;
    showEmptyFiltered?: boolean;
    scrollRootSelector?: string;
    ultimateSlotBonusMaxima?: UltimateSlotStatBlock | null;
    ultimateSlotBonusTotalMax?: number;
  } = $props();

  const isUltimatePick = $derived(pickMode === 'ultimateSlot');
  const spriteOnlyMode = $derived(forceSpriteOnly || team.teamSpritesOnly);
  const emptyFiltered = $derived(
    showEmptyFiltered ?? team.storageShowEmptyFiltered,
  );

  let listEl = $state<HTMLElement | null>(null);
  let visibleCount = $state(isMobileViewport() ? STORAGE_BATCH_SIZE_MOBILE : STORAGE_BATCH_SIZE);
  let windowStart = $state(0);
  let expansionTargetEnd = $state(0);
  let sentinelEl = $state<HTMLDivElement | null>(null);
  let lastRosterSig = $state('');
  let lastRosterCreatures = $state<StorageCardSnapshot[]>([]);
  let sentinelObserveKey = $state(0);
  let cachedMetrics = $state<GridRowMetrics>({ cols: 4, rowHeight: DEFAULT_STORAGE_ROW_HEIGHT });

  let visibleCreatures = $derived(
    creatures.slice(windowStart, Math.min(windowStart + visibleCount, creatures.length)),
  );

  let spacerHeights = $derived.by(() => {
    void visibleCreatures.length;
    void cachedMetrics.rowHeight;
    return getStorageVirtualSpacerHeights(
      listEl,
      windowStart,
      visibleCount,
      creatures.length,
      DEFAULT_STORAGE_ROW_HEIGHT,
      cachedMetrics,
    );
  });

  function refreshCachedMetrics(): void {
    const el = listEl;
    if (!el) return;
    cachedMetrics = measureStableGridMetrics(el, DEFAULT_STORAGE_ROW_HEIGHT, cachedMetrics);
  }

  function applyClampStorageWindow(): void {
    const batch = effectiveBatchSize(batchSize);
    const maxDom = effectiveMaxDom();
    const clamped = clampStorageWindow(creatures.length, windowStart, visibleCount, batch, maxDom);
    windowStart = clamped.windowStart;
    visibleCount = clamped.visibleCount;
  }

  function syncWindowFromScroll(): void {
    const el = listEl;
    if (!el) return;
    const synced = syncStorageWindowFromScroll(
      el,
      creatures.length,
      effectiveMaxDom(),
      effectiveBatchSize(batchSize),
      scrollRootSelector,
      DEFAULT_STORAGE_ROW_HEIGHT,
      cachedMetrics,
    );
    if (!synced) return;
    windowStart = synced.windowStart;
    visibleCount = Math.max(visibleCount, synced.visibleCount);
    applyClampStorageWindow();
    expansionTargetEnd = Math.max(expansionTargetEnd, windowStart + visibleCount);
  }

  function bumpSentinelObserver(): void {
    sentinelObserveKey += 1;
  }

  function queueStorageExpansion(): void {
    requestStorageExpansion({
      getCreaturesLength: () => creatures.length,
      getWindowStart: () => windowStart,
      getVisibleCount: () => visibleCount,
      setVisibleCount: (v) => {
        visibleCount = v;
        applyClampStorageWindow();
      },
      getExpansionTargetEnd: () => expansionTargetEnd,
      setExpansionTargetEnd: (v) => { expansionTargetEnd = v; },
      onBatchComplete: bumpSentinelObserver,
      batch: effectiveBatchSize(batchSize),
      maxDom: effectiveMaxDom(),
      chunk: effectiveChunkSize(),
    });
  }

  $effect(() => {
    const el = listEl;
    const gm = game;
    if (!el || !gm || isUltimatePick) return;
    _bindStorageDragDelegation(gm, el);
    _bindStorageDropDelegation(gm, el);
    el.classList.toggle('sprite-only-mode', team.teamSpritesOnly);
  });

  $effect(() => {
    const el = listEl;
    if (!el || !isUltimatePick) return;
    el.classList.add('sprite-only-mode');
  });

  $effect(() => {
    void visibleCreatures.length;
    const el = listEl;
    if (!el) return;
    const metricsRaf = requestAnimationFrame(() => {
      refreshCachedMetrics();
    });
    return () => cancelAnimationFrame(metricsRaf);
  });

  $effect(() => {
    const el = listEl;
    if (!el) return;
    return bindVirtualGridResizeSync(el, () => {
      refreshCachedMetrics();
      syncWindowFromScroll();
    });
  });

  $effect(() => {
    const el = listEl;
    const root = getLazyListScrollRoot(el, scrollRootSelector);
    if (!el || !(root instanceof HTMLElement)) return;

    let scrollRaf: number | null = null;
    const onScroll = () => {
      if (scrollRaf != null) return;
      scrollRaf = requestAnimationFrame(() => {
        scrollRaf = null;
        syncWindowFromScroll();
      });
    };

    root.addEventListener('scroll', onScroll, { passive: true });
    return () => {
      root.removeEventListener('scroll', onScroll);
      if (scrollRaf != null) cancelAnimationFrame(scrollRaf);
    };
  });

  $effect(() => {
    sentinelObserveKey;
    const el = sentinelEl;
    const root = getLazyListScrollRoot(listEl, scrollRootSelector);
    const len = creatures.length;
    if (!el || typeof IntersectionObserver === 'undefined') return;
    const obs = new IntersectionObserver(
      (entries) => {
        if (!entries.some((e) => e.isIntersecting)) return;
        if (windowStart + visibleCount >= len) return;
        queueStorageExpansion();
      },
      { root, rootMargin: '200px', threshold: 0 },
    );
    obs.observe(el);
    return () => obs.disconnect();
  });

  $effect(() => {
    const sig = storageRosterSignature(creatures);
    if (sig !== lastRosterSig) {
      const scrollSaved = captureUiScrollPositions();
      const isAppend = isStorageRosterAppendOnly(lastRosterCreatures, creatures);
      lastRosterSig = sig;
      lastRosterCreatures = creatures;
      if (isAppend) {
        const wasNearEnd = windowStart + visibleCount >= creatures.length - 1;
        if (wasNearEnd) {
          visibleCount = Math.min(visibleCount + 1, creatures.length - windowStart);
        }
      } else {
        cancelStorageExpansion();
        cachedMetrics = { cols: 4, rowHeight: DEFAULT_STORAGE_ROW_HEIGHT };
        windowStart = 0;
        visibleCount = Math.min(effectiveBatchSize(batchSize), creatures.length);
        expansionTargetEnd = visibleCount;
      }
      applyClampStorageWindow();
      restoreUiScrollPositions(scrollSaved);
    } else {
      applyClampStorageWindow();
    }
  });
</script>

<div
  bind:this={listEl}
  class="team-list"
  id={listId}
  class:sprite-only-mode={spriteOnlyMode}
>
  {#if emptyFiltered}
    <div style="text-align: center; color: #666; padding: 20px; grid-column: 1 / -1;">
      {uiText('storage.emptyFiltered', 'No Pokemon matches your filters.')}
    </div>
  {:else}
    {#if spacerHeights.topPx > 0}
      <div
        class="storage-grid-spacer storage-grid-spacer--top"
        style="height: {spacerHeights.topPx}px"
        aria-hidden="true"
      ></div>
    {/if}
    {#each visibleCreatures as entry (entry.rosterKey)}
      <CreatureCard
        creature={entry}
        index={entry.storageIndex >= 0 ? entry.storageIndex : 0}
        location="storage"
        levelShort={team.labels.levelShort}
        viewDetails={team.labels.viewDetails}
        teamSpritesOnly={spriteOnlyMode}
        storageCompact={!spriteOnlyMode}
        pickForUltimateSlot={isUltimatePick}
        ultimateSlotBonusMaxima={isUltimatePick ? ultimateSlotBonusMaxima : null}
        ultimateSlotBonusTotalMax={isUltimatePick ? ultimateSlotBonusTotalMax : 0}
      />
    {/each}
    {#if windowStart + visibleCount < creatures.length}
      <div class="storage-grid-sentinel" bind:this={sentinelEl} aria-hidden="true"></div>
    {/if}
    {#if spacerHeights.bottomPx > 0}
      <div
        class="storage-grid-spacer storage-grid-spacer--bottom"
        style="height: {spacerHeights.bottomPx}px"
        aria-hidden="true"
      ></div>
    {/if}
  {/if}
</div>
