<script lang="ts">
  import { facade } from '../bus/gameFacade.ts';
  import { game } from '../../gameManager.js';
  import type { GameRuntime } from '../types/game.js';
  import { dailyLogin } from '../stores/dailyLogin.svelte.ts';
  import { fetiche } from '../stores/fetiche.svelte.ts';
  import HeaderStatsRow from './HeaderStatsRow.svelte';
  import HeaderResources from './HeaderResources.svelte';
  import AfkTeamSummary from './AfkTeamSummary.svelte';

  let loginSnap = $derived(dailyLogin.snapshot);
  let feticheSnap = $derived(fetiche.snapshot);
  let dailyLoginBadgeTip = $derived(
    game && typeof game.t === 'function' ? game.t('dailyLogin.headerBadgeTitle') : '',
  );
  let showDailyLoginMenuBadge = $derived(loginSnap.unlocked && loginSnap.canClaimToday);
  let showFeticheHungryBadge = $derived(
    feticheSnap.featureUnlocked && feticheSnap.hasChosen && feticheSnap.headerHungryBadge,
  );
  let showFeticheCravingBadge = $derived(
    feticheSnap.featureUnlocked && feticheSnap.hasChosen && feticheSnap.cravingBerryInBag,
  );
  let showFeticheProfileBadge = $derived(showFeticheHungryBadge || showFeticheCravingBadge);

  let feticheHungryAria = $derived.by((): string => {
    const gm = game as GameRuntime | null;
    if (!gm) return 'Fétiche a faim';
    void gm.language;
    if (showFeticheCravingBadge && !showFeticheHungryBadge) {
      return gm.t?.('fetiche.headerCravingBadge') ?? 'Baie favorite disponible';
    }
    return gm.t?.('fetiche.headerHungryBadge') ?? 'Fétiche a faim';
  });

  let playerProfileLabel = $derived.by((): string => {
    const gm = game as GameRuntime | null;
    if (!gm) return 'Joueur';
    void gm.language;
    return gm.t?.('arenaUi.playerLabel') ?? 'Joueur';
  });

  let playerProfileName = $derived.by((): string => {
    const gm = game as GameRuntime | null;
    if (!gm) return 'Joueur';
    void gm.language;
    return typeof gm.getPlayerProfileName === 'function' ? gm.getPlayerProfileName() : 'Joueur';
  });

  let playerProfileSpriteUrl = $derived.by((): string => {
    const gm = game as GameRuntime | null;
    if (!gm) return 'https://play.pokemonshowdown.com/sprites/trainers/red.png';
    void gm.language;
    return typeof gm.getPlayerProfileSpriteUrl === 'function'
      ? gm.getPlayerProfileSpriteUrl()
      : 'https://play.pokemonshowdown.com/sprites/trainers/red.png';
  });
</script>

<div class="header">
  <div class="header-unified-row">
    <HeaderStatsRow />
    <div class="header-separator"></div>
    <HeaderResources />
    <div class="header-separator"></div>
    <div class="player-profile-group">
      <div class="player-profile-chip" style="cursor:pointer;" role="button" tabindex="0" data-action="openMasteryModal"
        onkeydown={(e) => { if (e.key === 'Enter') (e.currentTarget as HTMLElement).click(); }}>
        <img
          id="headerPlayerSprite"
          src={playerProfileSpriteUrl}
          class="player-profile-sprite"
          alt={playerProfileName}
        >
        <div class="player-profile-meta">
          <div class="player-profile-label">{playerProfileLabel}</div>
          <div id="headerPlayerName" class="player-profile-name">{playerProfileName}</div>
        </div>
        {#if showFeticheProfileBadge}
          <span
            class="player-profile-fetiche-badge"
            class:player-profile-fetiche-badge--craving={showFeticheCravingBadge && !showFeticheHungryBadge}
            role="img"
            aria-label={feticheHungryAria}
          ></span>
        {/if}
        <span id="headerMasteryPointsBadgeWrap" class="header-mastery-points-badge-wrap" hidden>
          <span id="headerMasteryPointsBadge" class="tab-badge tab-badge-accept" role="img"></span>
        </span>
      </div>
    </div>
    <div class="header-separator"></div>
    <div class="header-buttons">
      <span class="header-menu-btn-wrap">
        <button id="openSaveManagerBtn" class="btn" style="background: rgba(48, 52, 62, 0.9); color: #c0c8d4; padding: 0 20px;"
          onclick={() => facade.dispatch({ type: 'OPEN_SAVE_MANAGER' })}>
          &#9776; <span id="openSaveManagerLabel">MENU</span></button>
        {#if showDailyLoginMenuBadge}
          <span class="header-menu-daily-login-badge-wrap">
            <span
              class="tab-badge tab-badge-accept"
              role="img"
              title={dailyLoginBadgeTip}
              aria-label={dailyLoginBadgeTip}
            >1</span>
          </span>
        {/if}
      </span>
    </div>
  </div>
</div>

<AfkTeamSummary />
