/**
 * DPS meter timeline — rolling window for sparkline / peak DPS (120 s).
 */

export const DPS_TIMELINE_WINDOW_SEC = 120;

export type DpsTimelineBucket = { done?: number; taken?: number; heal?: number };
export type DpsTimeline = Record<number, DpsTimelineBucket>;

/** Mutates timeline in place — drop buckets older than the live window. */
export function pruneDpsMeterTimeline(
    timeline: DpsTimeline | null | undefined,
    nowMs: number = Date.now(),
): void {
    if (!timeline) return;
    const cutoff = Math.floor(nowMs / 1000) - DPS_TIMELINE_WINDOW_SEC;
    const keys = Object.keys(timeline);
    for (let i = 0; i < keys.length; i++) {
        const n = Number(keys[i]);
        if (n < cutoff) delete timeline[n];
    }
}

/** Pruned shallow copy for persistence (save payload). */
export function copyPrunedDpsMeterTimeline(
    timeline: DpsTimeline | null | undefined,
    nowMs: number = Date.now(),
): DpsTimeline {
    if (!timeline) return {};
    const cutoff = Math.floor(nowMs / 1000) - DPS_TIMELINE_WINDOW_SEC;
    const out: DpsTimeline = {};
    const keys = Object.keys(timeline);
    for (let i = 0; i < keys.length; i++) {
        const n = Number(keys[i]);
        if (n >= cutoff) out[n] = timeline[n]!;
    }
    return out;
}
