/** Coalesce rapid saveGame calls (autosave idle flush, unlockAchievement chains). */
export const SAVE_DEBOUNCE_MS = 500;

let debounceTimer: ReturnType<typeof setTimeout> | null = null;
let pendingFlush: (() => void) | null = null;

export function scheduleDebouncedSave(runSave: () => void): void {
    pendingFlush = runSave;
    if (debounceTimer != null) {
        clearTimeout(debounceTimer);
    }
    debounceTimer = setTimeout(() => {
        debounceTimer = null;
        const flush = pendingFlush;
        pendingFlush = null;
        if (flush) flush();
    }, SAVE_DEBOUNCE_MS);
}

export function flushPendingDebouncedSave(): void {
    if (debounceTimer != null) {
        clearTimeout(debounceTimer);
        debounceTimer = null;
    }
    const flush = pendingFlush;
    pendingFlush = null;
    if (flush) flush();
}

export function cancelDebouncedSave(): void {
    if (debounceTimer != null) {
        clearTimeout(debounceTimer);
        debounceTimer = null;
    }
    pendingFlush = null;
}

/** Test helper — reset module state between specs. */
export function resetSaveDebounceForTests(): void {
    cancelDebouncedSave();
}
