/**
 * @file gameI18nSystem.js
 * i18n / translation subsystem -- extracted from game.js.
 * Loaded AFTER game.js, extends Game.prototype via mixin.
 */

import { ACCOUNT_TALENTS } from './constants/balance/arenasTrainers.js';
import { PASSIVE_TALENTS, GENERIC_ULTIMATES } from './constants/balance/talentsAndCombat.js';
import { ZONES } from './constants/balance/zonesAndPacing.js';
import { ALL_ITEMS } from './constants/balance/shopAndAggregation.js';
import { HELD_ITEMS } from './constants/balance/towerAndItems.js';
import { escapeHtml } from './formatters.ts';
import {
    UI_I18N,
    ZONE_NAME_I18N,
    ACHIEVEMENT_I18N_FR,
    _toRoman,
    _parseAchievementKey,
} from './gameI18nData.ts';
import { coerceStr, coalesceStr } from './src/lib/coerceStr.ts';
import { RARITY } from './constants/core.ts';
import { MOVES_DB, resolveMoveName } from './constants/movesDb.ts';
import { getLocalizedMoveDescriptionPlain } from './constants/moveDescriptionI18n.ts';
import { ACHIEVEMENTS } from './constants/questsAchievements.js';
import type { GameRuntime } from './src/types/game.js';
import { getExtraZoneNameI18n } from './src/lib/regionsRuntime.ts';
import { localizePokemonName } from './constants/pokemonNameI18n.ts';
import { getLocalizedItemNameUI, uiMaybeLocalizeItemDescription } from './src/ui/i18n.ts';

type GameCtor = { prototype: Record<string, unknown> };
type ThisGame = GameRuntime;

/** Match a generic ultimate fallback string to its rarity key (common/rare/epic/legendary). */
function resolveGenericUltimateRarityKey(fallback: string, field: 'name' | 'description'): string | null {
    const raw = String(fallback || '').trim();
    if (!raw) return null;
    for (const [rarity, ult] of Object.entries(GENERIC_ULTIMATES)) {
        const value = field === 'name' ? ult.name : ult.description;
        if (value === raw) return rarity;
    }
    return null;
}

function localizeUltimateField(
    game: ThisGame,
    creatureName: string,
    fallback: string,
    field: 'name' | 'description',
): string {
    const key = String(creatureName || '').trim();
    const fb = String(fallback || '');
    if (!key) return fb;

    const speciesKey = `ultimates.${key}.${field}`;
    const speciesTranslated = game.t(speciesKey);
    if (speciesTranslated && speciesTranslated !== speciesKey) return speciesTranslated;

    const genericRarity = resolveGenericUltimateRarityKey(fb, field);
    if (genericRarity) {
        const genericKey = `ultimates._generic.${genericRarity}.${field}`;
        const genericTranslated = game.t(genericKey);
        if (genericTranslated && genericTranslated !== genericKey) return genericTranslated;
    }

    return fb;
}

export function applyI18nSystem(GameClass: GameCtor): void {

    GameClass.prototype.normalizeLanguage = function (this: ThisGame, lang: string) {
        return (lang === 'en') ? 'en' : 'fr';
    };

    GameClass.prototype.getLocalizedPokemonName = function (this: ThisGame, name: string, fallbackName: string = '') {
        const raw = String(name || fallbackName || '');
        if (!raw) return raw;
        if (!this || typeof this.normalizeLanguage !== 'function') return raw;
        const lang = this.normalizeLanguage(this.language);
        return escapeHtml(localizePokemonName(raw, lang));
    };

    GameClass.prototype.t = function (this: ThisGame, key: string, vars: Record<string, unknown> = {}) {
        if (!this || typeof this.normalizeLanguage !== 'function') return key;
        const lang = this.normalizeLanguage(this.language);
        const i18nTables = UI_I18N as unknown as Record<string, Record<string, string>>;
        const fallback = i18nTables.fr;
        const source = i18nTables[lang] ?? fallback;
        if (!source || !fallback) return key;
        const parts = String(key || '').split('.');

        const pick = (obj: Record<string, unknown>): string | null => {
            let cur: unknown = obj;
            for (const p of parts) {
                if (!cur || typeof cur !== 'object' || !(p in cur)) return null;
                cur = (cur as Record<string, unknown>)[p];
            }
            return (typeof cur === 'string') ? cur : null;
        };

        let text = pick(source);
        if (text == null) text = pick(fallback);
        if (text == null) return key;

        const inputVars = (vars && typeof vars === 'object') ? vars : {};
        const localizedVars = (typeof (window as unknown as Record<string, unknown>).localizeTemplateSubstitutionVars === 'function')
            ? ((window as unknown as Record<string, unknown>).localizeTemplateSubstitutionVars as (g: unknown, vars: unknown) => unknown)(this, inputVars)
            : (() => {
                const esc = (s: unknown) => escapeHtml(coerceStr(s, ''));
                const out: Record<string, unknown> = {};
                for (const [varKey, varValue] of Object.entries(inputVars)) {
                    if (typeof varValue === 'string') {
                        out[varKey] = esc(localizePokemonName(String(varValue), lang));
                    } else {
                        out[varKey] = varValue;
                    }
                }
                return out;
            })();

        return text.replace(/\{(\w+)\}/g, (_match: string, k: string) => ((localizedVars as Record<string, unknown>)[k] != null ? String((localizedVars as Record<string, unknown>)[k]) : ''));
    };

    GameClass.prototype.getLocalizedAchievementData = function (this: ThisGame, achievementId: string, definition: Record<string, unknown> | null = null) {
        const id = String(achievementId || '');
        const def = definition || (ACHIEVEMENTS as Record<string, Record<string, unknown>>)[id] || {};
        const fallbackTitle = coerceStr(def.title, id);
        const fallbackDesc = coerceStr(def.desc);

        if (this.normalizeLanguage(this.language) !== 'fr') {
            return { title: fallbackTitle, desc: fallbackDesc };
        }

        const parsed = _parseAchievementKey(id);
        const familyCfg = ACHIEVEMENT_I18N_FR[parsed.family];
        if (!familyCfg) return { title: fallbackTitle, desc: fallbackDesc };

        let title = fallbackTitle;
        if (typeof familyCfg.titleFn === 'function') {
            title = familyCfg.titleFn(parsed.rank ?? 0);
        } else if (typeof familyCfg.title === 'string') {
            if (familyCfg.series !== false && parsed.rank != null && Number.isFinite(parsed.rank) && parsed.rank > 0) {
                title = `${familyCfg.title} ${_toRoman(parsed.rank)}`;
            } else {
                title = familyCfg.title;
            }
        }

        let desc = fallbackDesc;
        if (typeof familyCfg.descFn === 'function') {
            const target = def.target as number | string | undefined;
            desc = familyCfg.descFn(target ?? '', parsed.rank ?? undefined);
        } else if (typeof familyCfg.desc === 'string') {
            desc = familyCfg.desc;
        }

        return { title: coerceStr(title, fallbackTitle), desc: coerceStr(desc, fallbackDesc) };
    };

    GameClass.prototype.getLanguageLabel = function (this: ThisGame, lang: string) {
        const normalized = this.normalizeLanguage(lang);
        return normalized === 'en' ? this.t('menu.langEn') : this.t('menu.langFr');
    };

    GameClass.prototype.getRarityLabel = function (this: ThisGame, rarity: string) {
        const key = String(rarity || '').toLowerCase();
        if (key === RARITY.LEGENDARY) return this.t('rarity.legendary');
        if (key === RARITY.EPIC) return this.t('rarity.epic');
        if (key === RARITY.RARE) return this.t('rarity.rare');
        return this.t('rarity.common');
    };

    GameClass.prototype.getStatDisplayLabel = function (this: ThisGame, stat: string) {
        const labels = {
            hp: this.t('storage.sortHp'),
            attack: this.t('storage.sortAttack'),
            spattack: this.t('storage.sortSpAttack'),
            defense: this.t('storage.sortDefense'),
            spdefense: this.t('storage.sortSpDefense'),
            speed: this.t('storage.sortSpeed')
        };
        return (labels as Record<string, string>)[stat] || stat;
    };

    GameClass.prototype.getLocalizedAccountTalentName = function (this: ThisGame, talentKey: string, fallbackName: string = '') {
        const key = String(talentKey || '').trim();
        if (!key) return String(fallbackName || '');
        const accountDef = (ACCOUNT_TALENTS as Record<string, { name?: string }>)[key];
        const fallback = coalesceStr(fallbackName, coalesceStr(accountDef?.name, key));
        const i18nKey = `accountTalents.${key}.name`;
        const translated = this.t(i18nKey);
        return (translated && translated !== i18nKey) ? translated : fallback;
    };

    GameClass.prototype.getLocalizedAccountTalentDescription = function (this: ThisGame, talentKey: string, fallbackDescription: string = '') {
        const key = String(talentKey || '').trim();
        if (!key) return String(fallbackDescription || '');
        const accountDefDesc = (ACCOUNT_TALENTS as Record<string, { description?: string }>)[key];
        const fallback = coerceStr(fallbackDescription, accountDefDesc?.description);
        const i18nKey = `accountTalents.${key}.description`;
        const translated = this.t(i18nKey);
        return (translated && translated !== i18nKey) ? translated : fallback;
    };

    GameClass.prototype.getLocalizedPassiveTalentName = function (this: ThisGame, talentKey: string, fallbackName: string = '') {
        const key = String(talentKey || '').trim();
        if (!key) return escapeHtml(String(fallbackName || ''));
        const passiveDef = (PASSIVE_TALENTS as Record<string, { name?: string }>)[key];
        const fallback = coalesceStr(fallbackName, coalesceStr(passiveDef?.name, key));
        const i18nKey = `passiveTalents.${key}.name`;
        const translated = this.t(i18nKey);
        return escapeHtml((translated && translated !== i18nKey) ? translated : fallback);
    };

    GameClass.prototype.getLocalizedPassiveTalentDescription = function (this: ThisGame, talentKey: string, fallbackDescription: string = '') {
        const key = String(talentKey || '').trim();
        if (!key) return String(fallbackDescription || '');
        const passiveDefDesc = (PASSIVE_TALENTS as Record<string, { description?: string }>)[key];
        const fallback = coerceStr(fallbackDescription, passiveDefDesc?.description);
        const i18nKey = `passiveTalents.${key}.description`;
        const translated = this.t(i18nKey);
        return (translated && translated !== i18nKey) ? translated : fallback;
    };

    GameClass.prototype.getLocalizedUltimateName = function (this: ThisGame, creatureName: string, fallbackName: string = '') {
        return localizeUltimateField(this, creatureName, fallbackName, 'name');
    };

    GameClass.prototype.getLocalizedUltimateDescription = function (this: ThisGame, creatureName: string, fallbackDescription: string = '') {
        return localizeUltimateField(this, creatureName, fallbackDescription, 'description');
    };

    GameClass.prototype.getLocalizedZoneName = function (this: ThisGame, zoneId: number, fallbackName: string = '') {
        const id = Number(zoneId);
        const zoneDef = (typeof ZONES !== 'undefined' && Number.isFinite(id)) ? (ZONES as Record<number, Record<string, unknown>>)[id] : null;
        const base = coalesceStr(fallbackName, coalesceStr(zoneDef?.name, `Zone ${zoneId}`));
        if (this.normalizeLanguage(this.language) !== 'fr') return base;
        const frMap = ZONE_NAME_I18N.fr || {};
        const extraI18n = getExtraZoneNameI18n();
        const extraFrMap = extraI18n.fr ?? {};
        const idKey = String(id);
        return coalesceStr((extraFrMap as Record<string, string>)[idKey], coalesceStr((frMap as Record<string, string>)[idKey], base));
    };

    GameClass.prototype.getBoostTypeLabel = function (this: ThisGame, boostType: string) {
        const isEn = this.normalizeLanguage(this.language) === 'en';
        switch (String(boostType || '')) {
            case 'xp':
                return 'XP';
            case 'money':
                return this.t('offline.moneyLabel');
            case 'eggDrop':
                return isEn ? 'Egg drops' : 'Drop oeufs';
            case 'eggHatchSpeed':
                return isEn ? 'Egg hatch speed' : "Vitesse d'eclosion";
            case 'shiny':
                return 'Shiny';
            default: {
                const raw = String(boostType || '');
                if (raw.startsWith('passiveGain_')) {
                    const statKey = raw.slice('passiveGain_'.length);
                    const statLabel = coerceStr(this['getStatDisplayLabel']?.call(this, statKey) ?? statKey);
                    return isEn ? `${statLabel} passive gain/sec` : `gains ${statLabel}/sec`;
                }
                return raw;
            }
        }
    };

    GameClass.prototype.getLocalizedItemName = function (this: ThisGame, itemKey: string, fallbackName: string = '', itemDef: Record<string, unknown> | null = null) {
        const key = String(itemKey || '').trim();
        const unknownItemLabelRaw = this.t('modal.unknownItem');
        const unknownItemLabel = (unknownItemLabelRaw && unknownItemLabelRaw !== 'modal.unknownItem')
            ? unknownItemLabelRaw
            : 'Unknown item';
        const resolvedDef = itemDef || (
            (typeof ALL_ITEMS !== 'undefined' && key && (ALL_ITEMS as Record<string, Record<string, unknown>>)[key]) ? (ALL_ITEMS as Record<string, Record<string, unknown>>)[key] : null
        ) || (
            (typeof HELD_ITEMS !== 'undefined' && key && (HELD_ITEMS as Record<string, Record<string, unknown>>)[key]) ? (HELD_ITEMS as Record<string, Record<string, unknown>>)[key] : null
        );
        const defaultName = coalesceStr(
            fallbackName,
            coalesceStr(resolvedDef?.name, coalesceStr(key, unknownItemLabel)),
        );

        const localized = getLocalizedItemNameUI(this, key, resolvedDef || {}, defaultName);
        if (typeof localized === 'string' && localized.trim()) return localized;

        return defaultName;
    };

    GameClass.prototype.getLocalizedItemDescription = function (this: ThisGame, itemKey: string, fallbackDescription: string = '', itemDef: Record<string, unknown> | null = null) {
        const key = String(itemKey || '').trim();
        const resolvedDef = itemDef || (
            (typeof ALL_ITEMS !== 'undefined' && key && (ALL_ITEMS as Record<string, Record<string, unknown>>)[key]) ? (ALL_ITEMS as Record<string, Record<string, unknown>>)[key] : null
        ) || (
            (typeof HELD_ITEMS !== 'undefined' && key && (HELD_ITEMS as Record<string, Record<string, unknown>>)[key]) ? (HELD_ITEMS as Record<string, Record<string, unknown>>)[key] : null
        );
        const defaultDescription = coalesceStr(
            fallbackDescription,
            coerceStr(resolvedDef?.description),
        );

        const localized = uiMaybeLocalizeItemDescription(this, resolvedDef || {}, key, defaultDescription);
        if (typeof localized === 'string' && localized.trim()) return localized;

        return defaultDescription;
    };

    GameClass.prototype.getLocalizedItemLogLabel = function (this: ThisGame, itemKey: string, fallbackName: string = '', itemDef: Record<string, unknown> | null = null, withIcon: boolean = false) {
        const key = String(itemKey || '').trim();
        const resolvedDef = itemDef || (
            (typeof ALL_ITEMS !== 'undefined' && key && (ALL_ITEMS as Record<string, Record<string, unknown>>)[key]) ? (ALL_ITEMS as Record<string, Record<string, unknown>>)[key] : null
        ) || (
            (typeof HELD_ITEMS !== 'undefined' && key && (HELD_ITEMS as Record<string, Record<string, unknown>>)[key]) ? (HELD_ITEMS as Record<string, Record<string, unknown>>)[key] : null
        );
        const name = coerceStr(this.getLocalizedItemName(key, fallbackName, resolvedDef));
        if (!withIcon) return name;
        const icon = (resolvedDef && typeof resolvedDef.icon === 'string' && resolvedDef.icon.trim()) ? `${resolvedDef.icon} ` : '';
        return `${icon}${name}`.trim();
    };

    GameClass.prototype.getLocalizedShopEntryName = function (this: ThisGame, category: string, key: string, fallbackName: string) {
        const defaultName = String(fallbackName || key || '');
        if (typeof window !== 'undefined' && typeof (window as unknown as Record<string, unknown>).getLocalizedShopDataTextUI === 'function') {
            const localized = ((window as unknown as Record<string, unknown>).getLocalizedShopDataTextUI as (g: unknown, cat: string, k: string, field: string, d: string) => string)(this, category, key, 'name', defaultName);
            if (typeof localized === 'string' && localized.trim()) return localized;
        }
        return defaultName;
    };

    GameClass.prototype.getLocalizedMoveNamePlain = function (this: ThisGame, source: string, fallbackName: string = '') {
        const raw = String(source || fallbackName || '').trim();
        if (!raw) return '';
        const resolved = resolveMoveName(raw);
        const db = MOVES_DB as Record<string, { name?: string }>;
        const frDisplay = (db && db[resolved] && db[resolved].name) ? String(db[resolved].name) : resolved;
        const lang = this.normalizeLanguage(this.language);
        const localizeFn = (globalThis as unknown as Record<string, unknown>).localizeMoveName;
        return (typeof localizeFn === 'function')
            ? (localizeFn as (name: string, l: string) => string)(frDisplay, lang)
            : frDisplay;
    };

    GameClass.prototype.getLocalizedMoveName = function (this: ThisGame, source: string, fallbackName: string = '') {
        return escapeHtml(this.getLocalizedMoveNamePlain(source, fallbackName));
    };

    GameClass.prototype.getLocalizedMoveDescription = function (this: ThisGame, source: string) {
        const lang = this.normalizeLanguage(this.language);
        return getLocalizedMoveDescriptionPlain(source, lang);
    };

    GameClass.prototype.getEggRarityBadgeLabel = function (this: ThisGame, rarity: string) {
        const label = coerceStr(this.getRarityLabel(rarity)).toUpperCase();
        if (rarity === RARITY.LEGENDARY) return `✦ ${label} ✦`;
        if (rarity === RARITY.EPIC) return `★★★ ${label} ★★★`;
        if (rarity === RARITY.RARE) return `★★ ${label} ★★`;
        return `★ ${label} ★`;
    };
}
