/**
 * @file weeklyChallengeSystem.ts
 * Weekly rotating challenges (4 per ISO week, stratified difficulty).
 */

import {
    WEEKLY_CHALLENGE_POOL,
    buildWeeklyChallengeRewards,
    hashWeekSeed,
    isWeeklyBonusItemKey,
    mulberry32,
    scaleWeeklyDamageTarget,
    scaleWeeklyTarget,
    type WeeklyChallengeDifficulty,
    type WeeklyChallengeRewards,
    type WeeklyChallengeTemplate,
} from './constants/balance/weeklyChallenges.ts';
import { ALL_ITEMS } from './constants/balance/shopAndAggregation.ts';
import type { GameRuntime } from './src/types/game.js';
import { publishQuestsChanged } from './src/bus/publishHooks.ts';
import { callGame, callGameNumber, callGameVoid } from './src/lib/callBound.ts';
import { formatNumber } from './formatters.ts';
import { recordPokedollarsEarned } from './src/lib/pokedollarsEconomyTracking.js';
import {
    bindQuestRewardTooltipEvents,
    questRewardTooltipTitle,
    type QuestRewardTooltipKind,
} from './src/lib/questRewardTooltips.ts';
import { getItemIconHTML, getTimeDustGlowClass } from './src/ui/utils.ts';
import { toast } from './toastManager.ts';

export { bindQuestRewardTooltipEvents };

const CROWN_PASS_IMG =
    'https://raw.githubusercontent.com/msikma/pokesprite/master/items/key-item/crown-pass.png';

const EGG_SPRITE_BY_RARITY: Record<string, string> = {
    common: 'img/common-egg.png',
    rare: 'img/rare-egg.png',
    epic: 'img/epic-egg.png',
    legendary: 'img/legendary-egg.png',
};

function escapeWeeklyHtml(value: string): string {
    return String(value)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;');
}

function weeklyDifficultyBadge(_game: GameRuntime, difficulty: string): { badgeClass: string; badgeText: string } {
    if (difficulty === 'MEDIUM') {
        return { badgeClass: 'badge-medium', badgeText: 'Moyen' };
    }
    if (difficulty === 'HARD') {
        return { badgeClass: 'badge-hard', badgeText: 'Difficile' };
    }
    return { badgeClass: 'badge-easy', badgeText: 'Facile' };
}

function weeklyRewardChipHTML(tooltip: string, innerHtml: string): string {
    return `<span class="quest-reward-item" data-tooltip-title="${escapeWeeklyHtml(tooltip)}">${innerHtml}</span>`;
}

function weeklyRewardItemHTML(
    game: GameRuntime,
    kind: QuestRewardTooltipKind,
    innerHtml: string,
): string {
    return weeklyRewardChipHTML(questRewardTooltipTitle(game, kind), innerHtml);
}

function weeklyItemDisplayName(game: GameRuntime, itemKey: string): string {
    const itemDef = (ALL_ITEMS as Record<string, { name?: string }>)[itemKey];
    const fallback = itemDef?.name || itemKey;
    if (typeof game.getLocalizedItemName === 'function') {
        return game.getLocalizedItemName(itemKey, fallback, itemDef ?? null);
    }
    return fallback;
}

function weeklyItemIconHTML(itemKey: string): string {
    const itemDef = (ALL_ITEMS as Record<string, Record<string, unknown>>)[itemKey];
    if (!itemDef) return '';
    const glow = getTimeDustGlowClass(itemDef);
    const icon = getItemIconHTML(itemDef);
    if (!icon) return '';
    if (glow && icon.includes('class="')) {
        return icon.replace('class="', `class="${glow} `);
    }
    return icon;
}

type WeeklyRewardChipOpts = {
    tooltips: boolean;
    eggLabelsFromRarity?: boolean;
};

function wrapWeeklyRewardChip(
    game: GameRuntime,
    opts: WeeklyRewardChipOpts,
    kind: QuestRewardTooltipKind | null,
    innerHtml: string,
    itemTooltip?: string,
): string {
    if (opts.tooltips) {
        if (kind) return weeklyRewardItemHTML(game, kind, innerHtml);
        return weeklyRewardChipHTML(itemTooltip || '', innerHtml);
    }
    return `<span class="quest-reward-item">${innerHtml}</span>`;
}

function buildWeeklyRewardChips(
    game: GameRuntime,
    rewards: WeeklyChallengeRewards,
    opts: WeeklyRewardChipOpts,
): string[] {
    const parts: string[] = [];
    const pokedollars = Number(rewards.pokedollars) || 0;
    if (pokedollars > 0) {
        parts.push(wrapWeeklyRewardChip(
            game,
            opts,
            'pokedollars',
            `<img src="img/pokedollars.png" class="quest-reward-inline-img" alt="Pokedollars"> ${formatNumber(pokedollars)}`,
        ));
    }
    const tokens = Number(rewards.questTokens) || 0;
    if (tokens > 0) {
        parts.push(wrapWeeklyRewardChip(
            game,
            opts,
            'questTokens',
            `<img src="img/quest-token.png" class="quest-token-inline" alt="Jetons"> ${formatNumber(tokens)}`,
        ));
    }
    const marks = Number(rewards.triumphMarks) || 0;
    if (marks > 0) {
        parts.push(wrapWeeklyRewardChip(
            game,
            opts,
            'triumphMarks',
            `<img src="https://raw.githubusercontent.com/msikma/pokesprite/master/items/valuable-item/relic-crown.png" class="marque-triomphe-inline" alt="Marques"> ${formatNumber(marks)}`,
        ));
    }
    const dust = Number(rewards.essenceDust) || 0;
    if (dust > 0) {
        parts.push(wrapWeeklyRewardChip(
            game,
            opts,
            'essenceDust',
            `<img src="img/essence-dust.png" class="quest-reward-inline-img" alt="Dust"> ${formatNumber(dust)}`,
        ));
    }
    const tickets = Number(rewards.combatTickets) || 0;
    if (tickets > 0) {
        parts.push(wrapWeeklyRewardChip(
            game,
            opts,
            'combatTickets',
            `<img src="${CROWN_PASS_IMG}" class="combat-ticket-inline quest-reward-inline-img" alt="Tickets"> ${formatNumber(tickets)}`,
        ));
    }
    const rerolls = Number(rewards.talentRerolls) || 0;
    if (rerolls > 0) {
        parts.push(wrapWeeklyRewardChip(
            game,
            opts,
            'talentRerolls',
            `<img src="img/talent-reroll.png" class="quest-reward-inline-img" alt="Pilule"> ${formatNumber(rerolls)}`,
        ));
    }
    if (rewards.eggs) {
        for (const [rarity, count] of Object.entries(rewards.eggs)) {
            const qty = Math.max(0, Math.floor(Number(count) || 0));
            if (qty <= 0) continue;
            const sprite = EGG_SPRITE_BY_RARITY[rarity] || EGG_SPRITE_BY_RARITY.common;
            const rarityLabel = opts.eggLabelsFromRarity
                ? (callGame<string>(game, game['getRarityLabel'], rarity) ?? rarity)
                : rarity;
            const label = opts.eggLabelsFromRarity
                ? `${qty}x ${rarityLabel}`
                : `${qty}× ${rarity}`;
            parts.push(wrapWeeklyRewardChip(
                game,
                opts,
                'eggs',
                `<img src="${sprite}" class="quest-reward-inline-img quest-reward-egg" alt="${escapeWeeklyHtml(rarityLabel)}"> ${escapeWeeklyHtml(label)}`,
            ));
        }
    }
    if (rewards.items) {
        for (const [itemKey, count] of Object.entries(rewards.items)) {
            const qty = Math.max(0, Math.floor(Number(count) || 0));
            if (qty <= 0 || !isWeeklyBonusItemKey(itemKey)) continue;
            const name = weeklyItemDisplayName(game, itemKey);
            const icon = weeklyItemIconHTML(itemKey);
            parts.push(wrapWeeklyRewardChip(
                game,
                opts,
                null,
                `${icon} ${qty}× ${escapeWeeklyHtml(name)}`,
                name,
            ));
        }
    }
    return parts;
}

function buildWeeklyRewardsHTML(game: GameRuntime, rewards: WeeklyChallengeRewards): string {
    return buildWeeklyRewardChips(game, rewards, { tooltips: true }).join('');
}

export function buildWeeklyRewardsToastHtml(game: GameRuntime, rewards: WeeklyChallengeRewards): string {
    const chips = buildWeeklyRewardChips(game, rewards, { tooltips: false, eggLabelsFromRarity: true });
    if (chips.length === 0) {
        const note = game.t('quests.weeklyNoReward');
        return `<div class="toast-reward-note">${escapeWeeklyHtml(note)}</div>`;
    }
    return `<div class="toast-reward-summary">${chips.join('')}</div>`;
}

export function buildWeeklyChallengeCardHTML(game: GameRuntime, ch: WeeklyChallengeEntry): string {
    const tpl = WEEKLY_CHALLENGE_POOL.find((t) => t.id === ch.templateId);
    const titleKey = tpl?.titleKey || 'weekly.challenge.generic.title';
    const descKey = tpl?.descKey || 'weekly.challenge.generic.desc';
    const title = escapeWeeklyHtml(game.t(titleKey));
    const description = escapeWeeklyHtml(game.t(descKey, { target: formatNumber(ch.target) }));
    const { badgeClass, badgeText } = weeklyDifficultyBadge(game, ch.difficulty);
    const current = Math.max(0, Math.floor(Number(ch.current) || 0));
    const target = Math.max(1, Math.floor(Number(ch.target) || 1));
    const percent = Math.min(100, (current / target) * 100);
    const rewardsHTML = buildWeeklyRewardsHTML(game, ch.rewards);

    let actionsHTML = '';
    if (ch.completed && !ch.claimed) {
        const claimLabel = escapeWeeklyHtml(game.t('quests.weeklyClaim'));
        actionsHTML = `<button class="quest-btn btn-claim" data-action="claimWeeklyChallenge" data-arg="${escapeWeeklyHtml(ch.id)}">${claimLabel}</button>`;
    } else if (ch.claimed) {
        const claimedLabel = escapeWeeklyHtml(game.t('quests.weeklyClaimed'));
        actionsHTML = `<div class="quest-actions" style="color:#22c55e;font-size:12px;font-weight:bold;">${claimedLabel}</div>`;
    }

    return `
        <div class="quest-header"><div class="quest-title" style="display:flex;align-items:center;flex-wrap:wrap;">${title}</div><div class="quest-badge ${badgeClass}">${escapeWeeklyHtml(badgeText)}</div></div>
        <div class="quest-description">${description}</div>
        <div class="quest-progress-container"><div class="quest-progress-bar"><div class="quest-progress-fill" style="width: ${percent}%"></div></div><div class="quest-progress-text">${formatNumber(current)} / ${formatNumber(target)}</div></div>
        <div class="quest-rewards">${rewardsHTML}</div>${actionsHTML}
    `;
}

export function getWeeklyChallengeCardClass(ch: WeeklyChallengeEntry): string {
    const classes = ['quest-card', 'quest-card-weekly', 'accepted'];
    if (ch.completed || ch.claimed) classes.push('completed');
    return classes.join(' ');
}

export interface WeeklyChallengeEntry {
    id: string;
    templateId: string;
    trackingKey: string;
    target: number;
    current: number;
    difficulty: 'EASY' | 'MEDIUM' | 'HARD';
    completed: boolean;
    claimed: boolean;
    rewards: WeeklyChallengeRewards;
}

export interface WeeklyChallengesState {
    weekKey: string;
    seed: number;
    challenges: WeeklyChallengeEntry[];
}

function rewardsEqual(a: WeeklyChallengeRewards, b: WeeklyChallengeRewards): boolean {
    return JSON.stringify(a) === JSON.stringify(b);
}

function templateEventKeys(tpl: WeeklyChallengeTemplate): string[] {
    return tpl.trackingKeys ?? [tpl.trackingKey];
}

function templateConflictsUsedTypes(tpl: WeeklyChallengeTemplate, usedTypes: Set<string>): boolean {
    return templateEventKeys(tpl).some((key) => usedTypes.has(key));
}

function registerTemplateUsedTypes(tpl: WeeklyChallengeTemplate, usedTypes: Set<string>): void {
    for (const key of templateEventKeys(tpl)) usedTypes.add(key);
}

function weeklyTemplateForEntry(ch: WeeklyChallengeEntry): WeeklyChallengeTemplate | undefined {
    return WEEKLY_CHALLENGE_POOL.find((t) => t.id === ch.templateId);
}

function challengeMatchesEvent(ch: WeeklyChallengeEntry, eventType: string): boolean {
    if (eventType === ch.trackingKey) return true;
    const tpl = weeklyTemplateForEntry(ch);
    if (!tpl?.trackingKeys) return false;
    return tpl.trackingKeys.includes(eventType);
}

const DEPRECATED_WEEKLY_FUSIONS_TEMPLATE_ID = 'weekly_fusions';

function migrateDeprecatedWeeklyChallenges(game: GameRuntime): boolean {
    const state = ensureWeeklyChallengesState(game);
    const evoTpl = WEEKLY_CHALLENGE_POOL.find((t) => t.id === 'weekly_evolutions');
    if (!evoTpl) return false;

    let changed = false;
    const badges = badgeCount(game);
    const prestige = prestigeCount(game);

    for (const ch of state.challenges) {
        if (ch.templateId !== DEPRECATED_WEEKLY_FUSIONS_TEMPLATE_ID) continue;
        ch.templateId = 'weekly_evolutions';
        ch.trackingKey = evoTpl.trackingKey;
        ch.target = resolveWeeklyTarget(evoTpl, badges, prestige);
        if ((ch.current || 0) >= ch.target) ch.completed = true;
        ch.rewards = buildWeeklyChallengeRewards(evoTpl, ch.target);
        changed = true;
    }
    return changed;
}

export function reconcileWeeklyChallengeRewards(game: GameRuntime): boolean {
    const state = ensureWeeklyChallengesState(game);
    let changed = migrateDeprecatedWeeklyChallenges(game);
    for (const ch of state.challenges) {
        if (ch.claimed) continue;
        const tpl = WEEKLY_CHALLENGE_POOL.find((t) => t.id === ch.templateId);
        if (!tpl) continue;
        const next = buildWeeklyChallengeRewards(tpl, ch.target);
        if (!rewardsEqual(ch.rewards || {}, next)) {
            ch.rewards = next;
            changed = true;
        }
    }
    if (changed) publishQuestsChanged();
    return changed;
}

function badgeCount(game: GameRuntime): number {
    return Object.values(game.badges || {}).filter(Boolean).length;
}

function prestigeCount(game: GameRuntime): number {
    return Math.max(0, Math.floor(Number(game.stats?.prestigeCount) || 0));
}

function isTemplateAvailable(game: GameRuntime, tpl: WeeklyChallengeTemplate): boolean {
    const badges = badgeCount(game);
    if ((tpl.minBadges || 0) > badges) return false;
    if (tpl.requiresFeature) {
        if (!game.unlockedFeatures || !game.unlockedFeatures[tpl.requiresFeature]) return false;
    }
    return true;
}

function isChosen(tpl: WeeklyChallengeTemplate, chosen: WeeklyChallengeTemplate[]): boolean {
    return chosen.some((c) => c.id === tpl.id);
}

function candidatesForDifficulty(
    available: WeeklyChallengeTemplate[],
    chosen: WeeklyChallengeTemplate[],
    usedTypes: Set<string>,
    difficulty: WeeklyChallengeDifficulty,
): WeeklyChallengeTemplate[] {
    return available.filter(
        (t) => t.difficulty === difficulty
            && !isChosen(t, chosen)
            && !templateConflictsUsedTypes(t, usedTypes),
    );
}

function pickOneFromPool(
    pool: WeeklyChallengeTemplate[],
    rng: () => number,
    chosen: WeeklyChallengeTemplate[],
    usedTypes: Set<string>,
): boolean {
    if (!pool.length) return false;
    const idx = Math.floor(rng() * pool.length);
    const tpl = pool[idx];
    if (!tpl) return false;
    registerTemplateUsedTypes(tpl, usedTypes);
    chosen.push(tpl);
    return true;
}

function pickForDifficulty(
    available: WeeklyChallengeTemplate[],
    chosen: WeeklyChallengeTemplate[],
    usedTypes: Set<string>,
    rng: () => number,
    difficulty: WeeklyChallengeDifficulty,
    fallbacks: WeeklyChallengeDifficulty[],
): boolean {
    let pool = candidatesForDifficulty(available, chosen, usedTypes, difficulty);
    for (const fb of fallbacks) {
        if (pool.length) break;
        pool = candidatesForDifficulty(available, chosen, usedTypes, fb);
    }
    if (!pool.length) {
        pool = available.filter((t) => !isChosen(t, chosen) && !templateConflictsUsedTypes(t, usedTypes));
    }
    return pickOneFromPool(pool, rng, chosen, usedTypes);
}

export function pickWeeklyTemplates(game: GameRuntime, weekKey: string, count = 4): WeeklyChallengeTemplate[] {
    const available = WEEKLY_CHALLENGE_POOL.filter((t) => isTemplateAvailable(game, t));
    if (available.length === 0) return [];

    const rng = mulberry32(hashWeekSeed(weekKey, weeklySalt(game)));
    const chosen: WeeklyChallengeTemplate[] = [];
    const usedTypes = new Set<string>();

    pickForDifficulty(available, chosen, usedTypes, rng, 'EASY', ['MEDIUM']);
    pickForDifficulty(available, chosen, usedTypes, rng, 'MEDIUM', ['EASY', 'HARD']);
    pickForDifficulty(available, chosen, usedTypes, rng, 'HARD', ['MEDIUM']);

    if (chosen.length < count) {
        const fourthDifficulty: WeeklyChallengeDifficulty = rng() < 0.4 ? 'MEDIUM' : 'HARD';
        pickForDifficulty(available, chosen, usedTypes, rng, fourthDifficulty, ['HARD', 'MEDIUM', 'EASY']);
    }

    while (chosen.length < count) {
        const pool = available.filter((t) => !isChosen(t, chosen) && !templateConflictsUsedTypes(t, usedTypes));
        if (!pickOneFromPool(pool, rng, chosen, usedTypes)) break;
    }

    return chosen;
}

function weeklySalt(game: GameRuntime): number {
    return Math.floor(Number(game.prestige) || 0);
}

function resolveWeeklyTarget(
    tpl: WeeklyChallengeTemplate,
    badges: number,
    prestige: number,
): number {
    if (tpl.trackingKey === 'typedDamageDealt') {
        return scaleWeeklyDamageTarget(tpl.baseTarget, badges, prestige);
    }
    return scaleWeeklyTarget(tpl.baseTarget, badges, prestige);
}

export function ensureWeeklyChallengesState(game: GameRuntime): WeeklyChallengesState {
    if (!game.weeklyChallenges || typeof game.weeklyChallenges !== 'object') {
        game.weeklyChallenges = { weekKey: '', seed: 0, challenges: [] };
    }
    if (!Array.isArray(game.weeklyChallenges.challenges)) {
        game.weeklyChallenges.challenges = [];
    }
    return game.weeklyChallenges as WeeklyChallengesState;
}

export function ensureWeeklyChallengesLogic(game: GameRuntime): boolean {
    if (!game.unlockedFeatures?.classicQuests) return false;

    const weekKey = typeof game._currentWeekKey === 'function'
        ? game._currentWeekKey()
        : '';

    if (!weekKey) return false;

    const state = ensureWeeklyChallengesState(game);
    if (state.weekKey === weekKey && state.challenges.length > 0) {
        reconcileWeeklyChallengeRewards(game);
        return false;
    }

    const seed = hashWeekSeed(weekKey, weeklySalt(game));
    const templates = pickWeeklyTemplates(game, weekKey, 4);
    const badges = badgeCount(game);
    const prestige = prestigeCount(game);

    state.weekKey = weekKey;
    state.seed = seed;
    state.challenges = templates.map((tpl, i) => {
        const target = resolveWeeklyTarget(tpl, badges, prestige);
        return {
            id: `${weekKey}_${tpl.id}_${i}`,
            templateId: tpl.id,
            trackingKey: tpl.trackingKey,
            target,
            current: 0,
            difficulty: tpl.difficulty,
            completed: false,
            claimed: false,
            rewards: buildWeeklyChallengeRewards(tpl, target),
        };
    });

    publishQuestsChanged();
    return true;
}

function bumpChallenge(ch: WeeklyChallengeEntry, amount: number): boolean {
    if (ch.completed || ch.claimed) return false;
    const inc = Math.max(0, Number(amount) || 0);
    if (inc <= 0) return false;
    ch.current = Math.min(ch.target, (ch.current || 0) + inc);
    if (ch.current >= ch.target) {
        ch.completed = true;
    }
    return true;
}

function weeklyIncrementForEvent(
    ch: WeeklyChallengeEntry,
    eventType: string,
    params?: Record<string, unknown>,
): number {
    if (ch.trackingKey === 'typedDamageDealt' && eventType === 'typedDamageDealt') {
        return Number(params?.amount) || 0;
    }
    const tpl = WEEKLY_CHALLENGE_POOL.find((t) => t.id === ch.templateId);
    return tpl?.increment ?? 1;
}

export function checkWeeklyChallengesLogic(
    game: GameRuntime,
    eventType: string,
    params?: Record<string, unknown>,
): boolean {
    if (game.isOfflineSimulating) return false;
    if (!game.unlockedFeatures?.classicQuests) return false;

    ensureWeeklyChallengesLogic(game);
    const state = ensureWeeklyChallengesState(game);
    if (!state.challenges.length) return false;

    let changed = false;
    for (const ch of state.challenges) {
        if (ch.completed) continue;
        if (!challengeMatchesEvent(ch, eventType)) continue;

        const inc = weeklyIncrementForEvent(ch, eventType, params);
        if (bumpChallenge(ch, inc)) changed = true;
    }

    if (changed) {
        callGameVoid(game, game['saveGame']);
        publishQuestsChanged();
    }
    return changed;
}

export function resolveGrantedWeeklyRewards(
    game: GameRuntime,
    rewards: WeeklyChallengeRewards,
): WeeklyChallengeRewards {
    const scaleWeekly = (n: number) => callGameNumber(game, game['scaleMasteryWeeklyRewardAmount'], n);
    const granted: WeeklyChallengeRewards = {};

    if (rewards.pokedollars) {
        const amt = scaleWeekly(Number(rewards.pokedollars) || 0);
        if (amt > 0) granted.pokedollars = amt;
    }
    if (rewards.questTokens) {
        const tokenReward = callGameNumber(game, game['scaleMasteryQuestTokenAmount'], Number(rewards.questTokens) || 0);
        const scaled = scaleWeekly(tokenReward);
        if (scaled > 0) granted.questTokens = scaled;
    }
    if (rewards.triumphMarks) {
        const marks = scaleWeekly(Number(rewards.triumphMarks) || 0);
        if (marks > 0) granted.triumphMarks = marks;
    }
    if (rewards.essenceDust) {
        const dust = scaleWeekly(Number(rewards.essenceDust) || 0);
        if (dust > 0) granted.essenceDust = dust;
    }
    if (rewards.combatTickets) {
        const baseTickets = Math.max(0, Math.floor(Number(rewards.combatTickets) || 0));
        const ticketReward = callGameNumber(game, game['scaleMasteryCombatTicketAmount'], baseTickets);
        const tickets = scaleWeekly(ticketReward);
        if (tickets > 0) granted.combatTickets = tickets;
    }
    if (rewards.eggs) {
        const eggs: NonNullable<WeeklyChallengeRewards['eggs']> = {};
        for (const [rarity, count] of Object.entries(rewards.eggs)) {
            const qty = scaleWeekly(Math.max(0, Math.floor(Number(count) || 0)));
            if (qty > 0) eggs[rarity] = qty;
        }
        if (Object.keys(eggs).length > 0) granted.eggs = eggs;
    }
    if (rewards.talentRerolls) {
        const rerolls = scaleWeekly(Math.max(0, Math.floor(Number(rewards.talentRerolls) || 0)));
        if (rerolls > 0) granted.talentRerolls = rerolls;
    }
    if (rewards.items) {
        const items: NonNullable<WeeklyChallengeRewards['items']> = {};
        for (const [itemKey, count] of Object.entries(rewards.items)) {
            const qty = Math.max(0, Math.floor(Number(count) || 0));
            if (qty <= 0 || !isWeeklyBonusItemKey(itemKey)) continue;
            items[itemKey] = qty;
        }
        if (Object.keys(items).length > 0) granted.items = items;
    }

    return granted;
}

export function grantWeeklyChallengeRewards(
    game: GameRuntime,
    rewards: WeeklyChallengeRewards,
): WeeklyChallengeRewards {
    const granted = resolveGrantedWeeklyRewards(game, rewards);

    if (granted.pokedollars) {
        game.pokedollars = (game.pokedollars || 0) + granted.pokedollars;
        recordPokedollarsEarned(game, granted.pokedollars);
    }
    if (granted.questTokens) {
        game.questTokens = (game.questTokens || 0) + granted.questTokens;
        if (game.stats) game.stats.totalQuestTokensEarned = (game.stats.totalQuestTokensEarned || 0) + granted.questTokens;
    }
    if (granted.triumphMarks) {
        game.triumphMarks = (game.triumphMarks || 0) + granted.triumphMarks;
    }
    if (granted.essenceDust) {
        game.essenceDust = (game.essenceDust || 0) + granted.essenceDust;
    }
    if (granted.combatTickets) {
        game.combatTickets = (game.combatTickets || 0) + granted.combatTickets;
    }
    if (granted.eggs) {
        if (!game.eggs || typeof game.eggs !== 'object') game.eggs = {};
        for (const [rarity, count] of Object.entries(granted.eggs)) {
            if (count > 0) game.eggs[rarity] = (game.eggs[rarity] || 0) + count;
        }
    }
    if (granted.talentRerolls) {
        game.talentRerolls = (game.talentRerolls || 0) + granted.talentRerolls;
    }
    if (granted.items) {
        for (const [itemKey, count] of Object.entries(granted.items)) {
            if (count <= 0) continue;
            if (typeof game.addItem === 'function') {
                game.addItem(itemKey, count);
            } else if (game.items && typeof game.items === 'object') {
                game.items[itemKey] = (Number(game.items[itemKey]) || 0) + count;
            }
        }
    }

    return granted;
}

function refreshWeeklyClaimDisplays(game: GameRuntime, granted: WeeklyChallengeRewards): void {
    if (granted.eggs && Object.keys(granted.eggs).length > 0) {
        callGameVoid(game, game['updateEggsDisplay']);
    }
    if (granted.items && Object.keys(granted.items).length > 0) {
        if (typeof game.syncTalentConsumablesInInventory === 'function') {
            game.syncTalentConsumablesInInventory();
        }
        callGameVoid(game, game['updateItemsDisplay']);
    }
    if (
        granted.pokedollars
        || granted.questTokens
        || granted.triumphMarks
        || granted.essenceDust
        || granted.combatTickets
        || granted.talentRerolls
    ) {
        callGameVoid(game, game['updatePlayerStatsDisplay']);
    }
}

export function claimWeeklyChallengeLogic(game: GameRuntime, challengeId: string): boolean {
    ensureWeeklyChallengesLogic(game);
    const state = ensureWeeklyChallengesState(game);
    const ch = state.challenges.find((c) => c.id === challengeId);
    if (!ch || !ch.completed || ch.claimed) return false;

    const granted = grantWeeklyChallengeRewards(game, ch.rewards || {});

    const tpl = WEEKLY_CHALLENGE_POOL.find((t) => t.id === ch.templateId);
    const title = game.t(tpl?.titleKey ?? 'weekly.challenge.generic.title');
    const toastType = ch.difficulty === 'HARD' ? 'legendary' : 'success';

    toast.show({
        title,
        message: buildWeeklyRewardsToastHtml(game, granted),
        type: toastType,
        duration: 0,
        html: true,
    });

    ch.claimed = true;
    callGameVoid(game, game['saveGame']);
    publishQuestsChanged();
    refreshWeeklyClaimDisplays(game, granted);
    return true;
}

export interface WeeklyChallengeCardSnapshot {
    id: string;
    cardClass: string;
    cardHtml: string;
}

export function getWeeklyChallengesSnapshot(game: GameRuntime): {
    unlocked: boolean;
    weekKey: string;
    sectionTitle: string;
    sectionDesc: string;
    challenges: WeeklyChallengeCardSnapshot[];
} {
    const unlocked = !!(game.unlockedFeatures && game.unlockedFeatures.classicQuests);
    if (!unlocked) {
        return {
            unlocked: false,
            weekKey: '',
            sectionTitle: '',
            sectionDesc: '',
            challenges: [],
        };
    }

    ensureWeeklyChallengesLogic(game);
    const state = ensureWeeklyChallengesState(game);

    const challenges = state.challenges.map((ch) => ({
        id: ch.id,
        cardClass: getWeeklyChallengeCardClass(ch),
        cardHtml: buildWeeklyChallengeCardHTML(game, ch),
    }));

    return {
        unlocked: true,
        weekKey: state.weekKey,
        sectionTitle: game.t('quests.weeklyTitle'),
        sectionDesc: game.t('quests.weeklyWeekLabel', { week: state.weekKey }),
        challenges,
    };
}
