/**
 * @file src/lib/concentratedMilkCombatIndicator.ts
 * Combat zone indicator when Concentrated Milk farm production boost is active.
 */

import { formatBoostTimeLeft } from '../../formatters.ts';
import { getAllItem } from '../ui/uiItems.ts';
import { uiMaybeLocalizeItemName } from '../ui/i18n.ts';
import type { GameRuntime } from '../types/game.js';
import { getFarmWideProductionMult } from './miltankFarmLogic.ts';

export const CONCENTRATED_MILK_ITEM_KEY = 'concentrated_milk';

export interface ConcentratedMilkCombatIndicator {
  visible: boolean;
  spriteUrl: string;
  spriteAlt: string;
  tooltipTitle: string;
  tooltipBody: string;
}

export const EMPTY_CONCENTRATED_MILK_COMBAT_INDICATOR: ConcentratedMilkCombatIndicator = {
  visible: false,
  spriteUrl: '',
  spriteAlt: '',
  tooltipTitle: '',
  tooltipBody: '',
};

const indicatorListeners = new Set<() => void>();

export function subscribeConcentratedMilkIndicatorChanged(listener: () => void): () => void {
  indicatorListeners.add(listener);
  return () => indicatorListeners.delete(listener);
}

export function notifyConcentratedMilkIndicatorChanged(): void {
  indicatorListeners.forEach((listener) => listener());
}

function itemDisplayName(game: GameRuntime, itemKey: string): string {
  const itemDef = getAllItem(itemKey);
  const fallback = itemDef?.name ?? 'Lait concentre';
  if (typeof game.getLocalizedItemName === 'function') {
    return game.getLocalizedItemName(itemKey, fallback, itemDef ?? undefined);
  }
  return uiMaybeLocalizeItemName(game, itemDef, itemKey, fallback);
}

function isFarmUnlocked(game: GameRuntime): boolean {
  return !!(game.unlockedFeatures?.miltankFarm
    || (game.miltankFarmState && game.miltankFarmState.unlocked));
}

function boostTimeLeftLabel(game: GameRuntime, mult: number, remainingMs: number): string {
  const time = formatBoostTimeLeft(remainingMs, {
    minuteShort: game.t?.('offline.minuteShort') ?? 'min',
    secondShort: game.t?.('offline.secondShort') ?? 's',
  });
  const multLabel = Number.isInteger(mult) ? String(mult) : mult.toFixed(1).replace(/\.0$/, '');
  return game.t?.('combatUi.concentratedMilkTimeLeft', { mult: multLabel, time })
    ?? `x${multLabel} production · ${time} restantes`;
}

export function buildConcentratedMilkCombatIndicator(
  game: GameRuntime,
  now = Date.now(),
): ConcentratedMilkCombatIndicator {
  const itemDef = getAllItem(CONCENTRATED_MILK_ITEM_KEY);
  const spriteUrl = itemDef?.img ?? '';
  const spriteAlt = itemDisplayName(game, CONCENTRATED_MILK_ITEM_KEY);

  if (!isFarmUnlocked(game) || !game.miltankFarmState) {
    return { ...EMPTY_CONCENTRATED_MILK_COMBAT_INDICATOR };
  }

  const state = game.miltankFarmState;
  const until = Number(state.farmProductionBoostUntil) || 0;
  const mult = getFarmWideProductionMult(state, now);
  if (until <= now || mult <= 1) {
    return { ...EMPTY_CONCENTRATED_MILK_COMBAT_INDICATOR };
  }

  const remainingMs = Math.max(0, until - now);
  return {
    visible: true,
    spriteUrl,
    spriteAlt,
    tooltipTitle: spriteAlt,
    tooltipBody: boostTimeLeftLabel(game, mult, remainingMs),
  };
}
