import type { GameRuntime } from '../types/game.js';
import { resolveOpenCreatureModalCreature } from './refreshOpenCreatureModal.ts';
import { buildTapTooltipEvent } from '../ui/scheduleTooltipHelpers.ts';

/** Shows the creature base-stats tooltip on touch tap. Returns true when shown. */
export function showCreatureBaseStatsTooltipOnTap(
  game: GameRuntime,
  trigger: Element,
  sourceEvent: MouseEvent,
): boolean {
  const creature = resolveOpenCreatureModalCreature(game);
  if (!creature || typeof game.showCreatureBaseStatsTooltip !== 'function') return false;
  game.showCreatureBaseStatsTooltip(
    buildTapTooltipEvent(sourceEvent, trigger) as MouseEvent,
    creature,
  );
  return true;
}
