/**
 * Grant a fixed species from promo codes (storage + Pokédex).
 */

import { Creature } from '../../Creature.ts';
import { RARITY, POKEMON_SECONDARY_TYPES } from '../../constants/core.ts';
import {
  applyPokedexCaptureEntry,
  createPokedexEntryFromCapture,
} from './pokedexCaptureUpdate.ts';
import type { PromoCreatureReward } from '../../constants/promoCodes.ts';
import type { GameRuntime } from '../types/game.js';
import type { CreatureData } from '../types/creature.ts';
import { callGameVoid } from './callBound.ts';

function sanitizePromoLevel(value: unknown): number {
  const n = Math.floor(Number(value));
  if (!Number.isFinite(n) || n < 1) return 1;
  return Math.min(n, 100);
}

export function grantPromoCreature(game: GameRuntime, spec: PromoCreatureReward): boolean {
  const name = typeof spec.name === 'string' ? spec.name.trim() : '';
  if (!name) return false;

  const level = sanitizePromoLevel(spec.level);
  const isShiny = spec.isShiny !== false;

  const findTypeFn = game['findTypeForPokemon'];
  const type =
    typeof findTypeFn === 'function'
      ? (findTypeFn as (n: string) => string).call(game, name)
      : 'dark';

  const getRarityFn = game['getNaturalRarity'];
  const rarity =
    typeof getRarityFn === 'function'
      ? (getRarityFn as (n: string) => string).call(game, name)
      : RARITY.EPIC;

  const secondaryType =
    (POKEMON_SECONDARY_TYPES as Record<string, string | undefined>)[name] ?? null;

  const creature = new Creature(
    name,
    type,
    level,
    rarity,
    false,
    isShiny,
    secondaryType,
    false,
    false,
    false,
  ) as CreatureData & { recalculateStats?: () => void; heal?: () => void };

  creature.recalculateStats?.();
  creature.heal?.();

  if (!Array.isArray(game.storage)) game.storage = [];

  const findFn = game['findCreatureByName'];
  const existing =
    typeof findFn === 'function'
      ? (findFn as (n: string, shiny: boolean, shadow: boolean) => CreatureData | null).call(
          game,
          name,
          isShiny,
          false,
        )
      : null;

  if (existing && typeof game['processFusion'] === 'function') {
    (game['processFusion'] as (src: CreatureData, tgt: CreatureData) => void).call(
      game,
      creature,
      existing,
    );
  } else {
    game.storage.push(creature);
  }

  if (!game.pokedex || typeof game.pokedex !== 'object') game.pokedex = {};
  const pokedexKey = `${creature.name}_${creature.type}_${creature.rarity}`;
  const existingEntry = game.pokedex[pokedexKey];
  if (!existingEntry) {
    game.pokedex[pokedexKey] = createPokedexEntryFromCapture({
      name: creature.name,
      type: creature.type,
      rarity: creature.rarity,
      isShiny,
      isShadow: false,
    });
    const logFn = game['logMessage'];
    if (typeof logFn === 'function') {
      const msg =
        typeof game.t === 'function'
          ? game.t('log.pokedexNew', { name: creature.name, shiny: isShiny ? ' ✨' : '' })
          : `New discovery: ${creature.name}`;
      callGameVoid(game, logFn, msg);
    }
    if (typeof game['checkSpecialQuests'] === 'function') {
      (game['checkSpecialQuests'] as (k: string) => void).call(game, 'new_discovery');
    }
  } else {
    applyPokedexCaptureEntry(existingEntry, { isShiny, isShadow: false });
  }

  if (typeof game['trackHolyGrailCreature'] === 'function') {
    (game['trackHolyGrailCreature'] as (c: CreatureData) => void).call(game, creature);
  }
  if (typeof game['checkSpecialQuests'] === 'function') {
    (game['checkSpecialQuests'] as (k: string, p?: unknown) => void).call(game, 'creature_obtained', {
      creatureType: creature.type,
      secondaryType: creature.secondaryType,
    });
  }

  return true;
}
