/**
 * Dynamic Team Rocket Shadow reward pool from unlocked zone encounter tables.
 */
import { ZONES } from '../../constants/balance/zonesAndPacing.js';
import { ROCKET_SHADOW_POOL_WEIGHT_MULT } from '../../constants/balance/teamRocket.ts';
import { RARITY } from '../../constants/core.ts';
import type { GameRuntime } from '../types/game.js';
import {
    getWeightedReachableEntriesInZoneLogic,
    isZoneUnlockedLogic,
} from '../../zoneSystem.ts';
import { arrayAt } from './safeAccess.ts';

export type ShadowWeightedEntry = { name: string; weight: number };

const SHADOW_FALLBACK_SPECIES = 'Mew';

function isZoneUnlockedForGame(game: GameRuntime, zoneId: number): boolean {
    if (typeof game.isZoneUnlocked === 'function') {
        return game.isZoneUnlocked(zoneId, true);
    }
    return isZoneUnlockedLogic(game, zoneId, true);
}

function getNaturalRarity(game: GameRuntime, speciesName: string): string {
    if (typeof game.getNaturalRarity === 'function') {
        return game.getNaturalRarity(speciesName);
    }
    return RARITY.COMMON;
}

function getRarityWeightMult(rarity: string): number {
    const table = ROCKET_SHADOW_POOL_WEIGHT_MULT.byRarity as Record<string, number>;
    return table[rarity] ?? 1;
}

function getSpeciesWeightMult(speciesName: string): number {
    const override = ROCKET_SHADOW_POOL_WEIGHT_MULT.bySpecies[speciesName];
    return override != null && override > 0 ? override : 1;
}

/** Aggregate weighted entries from all unlocked zones, with rarity/species multipliers applied. */
export function buildRocketShadowWeightedPool(game: GameRuntime): ShadowWeightedEntry[] {
    const bySpecies = new Map<string, number>();

    for (const zoneKey of Object.keys(ZONES)) {
        const zoneId = Number(zoneKey);
        if (!Number.isFinite(zoneId) || zoneId <= 0) continue;
        if (!isZoneUnlockedForGame(game, zoneId)) continue;

        const entries = getWeightedReachableEntriesInZoneLogic(game, zoneId);
        for (const entry of entries) {
            if (!entry.name || entry.weight <= 0) continue;
            const rarity = getNaturalRarity(game, entry.name);
            const adjusted = entry.weight * getRarityWeightMult(rarity) * getSpeciesWeightMult(entry.name);
            if (adjusted <= 0) continue;
            bySpecies.set(entry.name, (bySpecies.get(entry.name) ?? 0) + adjusted);
        }
    }

    return [...bySpecies.entries()].map(([name, weight]) => ({ name, weight }));
}

export function filterShadowPoolByOwnedFamilies(
    game: GameRuntime,
    pool: ShadowWeightedEntry[],
): ShadowWeightedEntry[] {
    const hasFamily = typeof game.hasShadowOfSpeciesFamily === 'function'
        ? (name: string) => game.hasShadowOfSpeciesFamily(name)
        : () => false;

    return pool.map((entry) => ({
        name: entry.name,
        weight: hasFamily(entry.name) ? 0 : entry.weight,
    }));
}

export function pickWeightedShadowSpecies(pool: ShadowWeightedEntry[]): string | null {
    const eligible = pool.filter((e) => e.weight > 0);
    const total = eligible.reduce((sum, e) => sum + e.weight, 0);
    if (total <= 0) return null;

    let roll = Math.random() * total;
    for (const entry of eligible) {
        roll -= entry.weight;
        if (roll <= 0) return entry.name;
    }
    return arrayAt(eligible, eligible.length - 1)?.name ?? null;
}

export function pickRocketShadowSpeciesName(game: GameRuntime): string {
    const rawPool = buildRocketShadowWeightedPool(game);
    const filtered = filterShadowPoolByOwnedFamilies(game, rawPool);
    return pickWeightedShadowSpecies(filtered) ?? SHADOW_FALLBACK_SPECIES;
}
