<script lang="ts">
  import { team } from '../stores/team.svelte.ts';
  import { facade } from '../bus/gameFacade.js';
  import { game } from '../../gameManager.js';
  import type { GameRuntime } from '../types/game.js';
  import TeamList from './TeamList.svelte';
  import PensionList from './PensionList.svelte';
  import StorageGrid from './StorageGrid.svelte';
  import StorageSortBar from './StorageSortBar.svelte';
  import StorageFiltersBar from './StorageFiltersBar.svelte';
  import ActiveTalentsDisplay from './ActiveTalentsDisplay.svelte';
  import ZRingPicker from './ZRingPicker.svelte';
  import DynamaxBandPanel from './DynamaxBandPanel.svelte';
  import ResonanceAnchorsPreview from './ResonanceAnchorsPreview.svelte';
  import { useGameLanguageTick } from '../lib/useGameLanguageTick.svelte.ts';
  import { showGameTooltip, hideGameTooltip } from '../ui/scheduleTooltipHelpers.ts';
  import { buildSynergyButtonTooltip } from '../lib/synergyListLogic.js';

  const { trackGameLanguage } = useGameLanguageTick();

  function refreshStorageDisplay(): void {
    const gm = game as GameRuntime | null;
    if (gm && typeof gm.updateStorageDisplay === 'function') {
      gm.updateStorageDisplay();
    }
  }

  function t(key: string, fallback: string): string {
    const gm = game as GameRuntime | null;
    if (!gm?.t) return fallback;
    const got = gm.t(key);
    return got && got !== key ? got : fallback;
  }

  let synergyTooltip = $derived.by(() => {
    trackGameLanguage();
    const gm = game as GameRuntime | null;
    void team.playerTeam;
    return buildSynergyButtonTooltip(gm, team.playerTeam);
  });

  let tooltips = $derived.by(() => {
    trackGameLanguage();
    return {
      synergy: {
        title: synergyTooltip.title,
        body: synergyTooltip.body,
        aria: t('team.synergyTitle', 'Synergies'),
      },
      teamLoadout: {
        title: t('team.loadoutsTitle', "Loadouts d'équipe"),
        body: t('modal.loadoutManagerHelp', 'Enregistrez et rechargez rapidement vos compositions.'),
        aria: t('team.loadoutsTitle', "Loadouts d'équipe"),
      },
      pensionLoadout: {
        title: t('pension.loadoutsTitle', 'Loadouts de pension'),
        body: t('modal.loadoutManagerHelp', 'Enregistrez et rechargez rapidement vos compositions.'),
        aria: t('pension.loadoutsTitle', 'Loadouts de pension'),
      },
      pensionMoveAllToStorage: {
        title: t('pension.moveAllToStorageBtn', 'Tout au stockage'),
        body: t('pension.moveAllToStorageBtn', 'Tout au stockage'),
        aria: t('pension.moveAllToStorageBtn', 'Tout au stockage'),
      },
      baseStatsSort: {
        title: t('storage.baseStatsSortToggle', 'Stats de base'),
        body: t('tooltip.baseStatsSortHint', 'Trie par stats de base (espèce) au lieu des stats actuelles.'),
        aria: t('storage.baseStatsSortToggle', 'Stats de base'),
      },
    };
  });

  function toggleBaseStatSort(): void {
    facade.dispatch({ type: 'TOGGLE_STORAGE_BASE_STAT_SORT' });
  }
</script>

<!-- La cible est .team-area — le composant rend le contenu interne SANS wrapper .team-area -->
<div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 15px;">
  <div style="display: flex; align-items: center; gap: 10px;">
    <h2 style="margin: 0;">
      <span id="teamMainTitleLabel">Équipe Principale</span>
      (<span id="teamCount">{team.teamCountLabel}</span>)
      <span id="teamContributionInfoIcon" class="info-icon" data-touch-tooltip="teamContribution"
        style="font-size: 12px; cursor: help; color: #888; background: #2a2a2a; border-radius: 50%; width: 16px; height: 16px; display: inline-flex; justify-content: center; align-items: center; margin-left: 5px; border: 1px solid #444;">?</span>
    </h2>

    <button id="synergyBtn" class="synergy-btn" type="button"
      aria-label={tooltips.synergy.aria}
      onmouseenter={(e) => showGameTooltip(e, tooltips.synergy.title, tooltips.synergy.body)}
      onmouseleave={hideGameTooltip}
      onfocus={(e) => showGameTooltip(e, tooltips.synergy.title, tooltips.synergy.body)}
      onblur={hideGameTooltip}
      data-action="openSynergyListModal">
      <img id="synergyBtnSprite" src="img/synergy-off.png" class="synergy-btn-sprite" alt={tooltips.synergy.aria}>
    </button>
    <button id="teamLoadoutsBtn" type="button" class="sort-btn"
      aria-label={tooltips.teamLoadout.aria}
      onmouseenter={(e) => showGameTooltip(e, tooltips.teamLoadout.title, tooltips.teamLoadout.body)}
      onmouseleave={hideGameTooltip}
      onfocus={(e) => showGameTooltip(e, tooltips.teamLoadout.title, tooltips.teamLoadout.body)}
      onblur={hideGameTooltip}
      data-action="showLoadoutManager" data-arg="team" style="margin-left:6px;">
      <span id="teamLoadoutsLabel">Loadouts</span>
    </button>
    <ResonanceAnchorsPreview preview={team.resonancePreview} />
  </div>
</div>

<TeamList />
<ActiveTalentsDisplay />
<ZRingPicker />
<DynamaxBandPanel />

<h3 style="margin-top: 20px; display: flex; align-items: center; gap: 8px;">
  <span style="cursor: pointer;" data-action="togglePension">
    <span id="pensionTitleLabel">Pension</span>
    (<span id="pensionCount">{team.pensionCountLabel}</span>)
    <span id="pensionToggleIcon">?</span>
  </span>
    <button type="button" id="pensionLoadoutsBtn" class="sort-btn"
    aria-label={tooltips.pensionLoadout.aria}
    onmouseenter={(e) => showGameTooltip(e, tooltips.pensionLoadout.title, tooltips.pensionLoadout.body)}
    onmouseleave={hideGameTooltip}
    onfocus={(e) => showGameTooltip(e, tooltips.pensionLoadout.title, tooltips.pensionLoadout.body)}
    onblur={hideGameTooltip}
    data-action="showLoadoutManager" data-arg="pension" style="margin-left:6px;">
    <span id="pensionLoadoutsLabel">Loadouts</span>
  </button>
  <button
    type="button"
    id="pensionMoveAllToStorageBtn"
    class="sort-btn"
    disabled={team.pension.length === 0}
    aria-label={tooltips.pensionMoveAllToStorage.aria}
    onmouseenter={(e) => showGameTooltip(e, tooltips.pensionMoveAllToStorage.title, tooltips.pensionMoveAllToStorage.body)}
    onmouseleave={hideGameTooltip}
    onfocus={(e) => showGameTooltip(e, tooltips.pensionMoveAllToStorage.title, tooltips.pensionMoveAllToStorage.body)}
    onblur={hideGameTooltip}
    data-action="confirmMoveAllPensionToStorage"
    style="margin-left:6px;"
  >
    <span aria-hidden="true">&#8681;</span>
  </button>
  {#if team.ultimateSlotUnlocked}
    <button
      type="button"
      id="ultimateSlotBtn"
      class="sort-btn"
      aria-label={t('ultimateSlot.open', 'Slot ultime')}
      data-action="openUltimateSlotModal"
      style="margin-left:6px;"
    >
      {#if team.ultimateSlot}
        <img
          src={team.ultimateSlot.spriteUrl}
          alt=""
          width="20"
          height="20"
          class="ultimate-slot-btn-sprite"
        />
      {:else}
        <span id="ultimateSlotBtnLabel">{t('ultimateSlot.short', 'Ultime')}</span>
      {/if}
    </button>
  {/if}
  <span id="pensionContributionInfoIcon" class="info-icon" data-touch-tooltip="pensionContribution"
    style="font-size: 10px; cursor: help; color: #888; background: #2a2a2a; border-radius: 50%; width: 14px; height: 14px; display: inline-flex; justify-content: center; align-items: center; border: 1px solid #444;">?</span>
</h3>

<div id="pensionContainer">
  <div id="pensionContributionTextLabel" style="font-size: 12px; color: #ff69b4; margin-bottom: 10px; font-weight: bold;">
    Les cr&eacute;atures en pension contribuent &agrave; vos stats principales !
  </div>
  <PensionList />
</div>

<div class="storage-header-row">
  <h3>
    <span style="cursor: pointer;" data-action="toggleStorage">
      <span id="storageTitleLabel">Stockage</span>
      (<span id="storageCount">{team.storageFilteredCountLabel}</span>)
      <span id="storageToggleIcon">&#9660;</span>
    </span>
  </h3>
  <div id="storageContainer" class="storage-container">
    <div class="storage-controls-toggle-row">
      <button type="button" id="storageControlsToggleBtn" class="sort-btn" data-action="toggleStorageControls">
        <span id="storageControlsToggleLabel">Filtres</span>
        <span id="storageControlsToggleIcon">&#9660;</span>
      </button>
      <button
        type="button"
        id="storageBaseStatSortToggleBtn"
        class="sort-btn storage-base-stat-sort-toggle"
        class:active={team.storageSortByBaseStats}
        aria-label={tooltips.baseStatsSort.aria}
        aria-pressed={team.storageSortByBaseStats}
        title={tooltips.baseStatsSort.body}
        onmouseenter={(e) => showGameTooltip(e, tooltips.baseStatsSort.title, tooltips.baseStatsSort.body)}
        onmouseleave={hideGameTooltip}
        onfocus={(e) => showGameTooltip(e, tooltips.baseStatsSort.title, tooltips.baseStatsSort.body)}
        onblur={hideGameTooltip}
        onclick={toggleBaseStatSort}
      >
        <span id="storageBaseStatSortToggleLabel">{tooltips.baseStatsSort.title}</span>
      </button>
    </div>
    <div id="storageControlsContent">
      <div class="storage-controls">
        <StorageFiltersBar onFilterChange={refreshStorageDisplay} />

        <StorageSortBar sortStack={team.storageSortStack} />
      </div>
    </div>
    <StorageGrid creatures={team.storageRoster} />
  </div>
</div>
