import { POKEMON_BASE_STATS } from '../../pokemonStats.js';
import { RARITY, TYPES, POKEMON_POOL, POKEMON_PRIMARY_TYPES, POKEMON_SECONDARY_TYPES } from '../core.js';
import { POKEMON_SPRITE_IDS, POKEMON_CATCH_RATES } from './dexAndCapture.js';
import { EVOLUTIONS, EVOLUTION_FAMILIES } from '../evolutions.ts';
import type { EvolutionDefinition } from '../evolutionTypes.ts';

let eggPoolFamilyRarityRebuilt = false;

// Rebuild egg pool rarity for the whole dex using family benchmark rules.
// Zones remain untouched; this only affects Egg generation via POKEMON_POOL.
export function rebuildEggPoolByFamilyRarityAllGens() {
    if (!POKEMON_SPRITE_IDS || !POKEMON_CATCH_RATES) return false;
    if (eggPoolFamilyRarityRebuilt) return true;

    const VERY_LOW_CATCH_RATE = 0.1137; // official catch rate <= 25
    const EPIC_BST_THRESHOLD = 520;
    const RARE_BST_THRESHOLD = 455;

    // Manual "popular Pokemon => Epic" family root overrides.
    // Examples requested: Gengar line, Scizor line.
    const POPULAR_EPIC_FAMILY_ROOT_OVERRIDES = new Set([
        'Gastly',
        'Scyther',
        'Staryu',
        'Trapinch',
        'Ralts',
        'Aerodactyl',
        'Onix',
        'Machop',
        'Shuckle',
        'Abra',
        'Heracross'
    ]);

    const FAMILY_RARITY_OVERRIDES: Record<string, string> = {
        'Pichu': RARITY.RARE,
        'Kangaskhan': RARITY.RARE,
        'Absol': RARITY.EPIC,
        'Zorua': RARITY.EPIC,
    };

    // "Legendary strict" (includes Mythicals, Ultra Beasts and Paradox as requested).
    const HARD_LEGENDARY_ID_RANGES = [
        [144, 146],   // Articuno, Zapdos, Moltres
        [150, 151],   // Mewtwo, Mew
        [243, 245],   // Raikou, Entei, Suicune
        [249, 251],   // Lugia, Ho-Oh, Celebi
        [377, 386],   // Regi trio, Lati duo, weather trio, Jirachi, Deoxys
        [480, 493],   // Sinnoh legends + Arceus
        [638, 649],   // Gen 5 legendaries + mythicals
        [716, 721],   // Gen 6 legendaries + mythicals
        [785, 792],   // Tapus + Cosmog line
        [800, 809],   // Necrozma + mythicals (Marshadow..Melmetal)
        [888, 898],   // Gen 8 legendaries + mythicals
        [1001, 1010], // Gen 9 treasures + box legends + specials
        [1014, 1018], // Teal Mask legends
        [1020, 1025]  // Indigo Disk legends + Pecharunt line
    ];
    const HARD_LEGENDARY_EXTRA_IDS = new Set([
        494, // Victini (mythical Gen 5, hors plages 480–493 / 638–649)
        772, 773, 905, // Type: Null, Silvally, Enamorus
        // Ultra Beasts
        793, 794, 795, 796, 797, 798, 799, 803, 804, 805, 806,
        // Paradox families
        984, 985, 986, 987, 988, 989, 990, 991, 992, 993, 994, 995
    ]);

    const allTypes = Object.values(TYPES || {});
    const emptyTypedBuckets: () => Record<string, string[]> = () => {
        const byType: Record<string, string[]> = {};
        allTypes.forEach((t) => { byType[t] = []; });
        return byType;
    };

    const isHardLegendary = (dexId: number) => {
        if (HARD_LEGENDARY_EXTRA_IDS.has(dexId)) return true;
        return HARD_LEGENDARY_ID_RANGES.some(([start, end]) => {
            if (start == null || end == null) return false;
            return dexId >= start && dexId <= end;
        });
    };

    // Rebuild official BST from pokemonStats.js representation:
    // HP is kept as-is, other stats are stored divided by 2.
    const getOfficialBst = (name: string) => {
        const s = POKEMON_BASE_STATS[name];
        if (!s) return 0;
        const hp = Number(s.hp) || 0;
        const atk = Number(s.attack) || 0;
        const def = Number(s.defense) || 0;
        const spa = Number(s.spattack != null ? s.spattack : s.attack) || 0;
        const spd = Number(s.spdefense != null ? s.spdefense : s.defense) || 0;
        const spe = Number(s.speed) || 0;
        return hp + 2 * (atk + def + spa + spd + spe);
    };

    const getEvolutionChildren = (name: string) => {
        const evo = (EVOLUTIONS as Record<string, EvolutionDefinition>)[name];
        if (!evo || typeof evo !== 'object') return [];
        if (Array.isArray(evo.options)) {
            return evo.options.map((opt) => opt?.evolves_to).filter((to): to is string => Boolean(to));
        }
        return evo.evolves_to ? [evo.evolves_to] : [];
    };

    const getDepthMapFromRoot = (root: string) => {
        const depth: Record<string, number> = {};
        const queue = [{ name: root, d: 0 }];
        while (queue.length) {
            const cur = queue.shift();
            if (!cur || !cur.name) continue;
            const existingDepth = depth[cur.name];
            if (existingDepth != null && existingDepth >= cur.d) continue;
            depth[cur.name] = cur.d;
            getEvolutionChildren(cur.name).forEach((child: string) => queue.push({ name: child, d: cur.d + 1 }));
        }
        return depth;
    };

    // Snapshot type source before rebuilding the pool:
    // 1) POKEMON_PRIMARY_TYPES when available
    // 2) existing POKEMON_POOL fallback
    // 3) default normal type
    const typeBySpecies: Record<string, string> = {};
    const rarityBySpeciesSnapshot: Record<string, string> = {};
    if (typeof POKEMON_PRIMARY_TYPES !== 'undefined' && POKEMON_PRIMARY_TYPES) {
        Object.entries(POKEMON_PRIMARY_TYPES as Record<string, string>).forEach(([name, type]) => {
            if (type) typeBySpecies[name] = type;
        });
    }
    Object.values(POKEMON_POOL as Record<string, Record<string, string[]>>).forEach((byType) => {
        if (!byType || typeof byType !== 'object') return;
        const rarityKey = Object.entries(POKEMON_POOL as Record<string, Record<string, string[]>>).find(([,v]) => v === byType)?.[0] || null;
        Object.entries(byType).forEach(([typeKey, list]) => {
            if (!Array.isArray(list)) return;
            list.forEach((name) => {
                if (!typeBySpecies[name]) typeBySpecies[name] = typeKey;
                if (rarityKey && !rarityBySpeciesSnapshot[name]) rarityBySpeciesSnapshot[name] = rarityKey;
            });
        });
    });

    const allSpecies = Object.keys(POKEMON_SPRITE_IDS as Record<string, number> || {}).filter((name) => {
        const dexId = Number((POKEMON_SPRITE_IDS as Record<string, number>)[name]);
        return Number.isFinite(dexId)
            && dexId >= 1
            && dexId <= 1025
            && !!(POKEMON_CATCH_RATES as Record<string, number>)[name];
    });

    const families: Record<string, string[]> = {};
    const allFamilyMembers: Record<string, string[]> = {};
    const familyRarityHint: Record<string, string> = {};
    const rarityWeight: Record<string, number> = {
        [RARITY.COMMON]: 1,
        [RARITY.RARE]: 2,
        [RARITY.EPIC]: 3,
        [RARITY.LEGENDARY]: 4
    };
    Object.entries(EVOLUTION_FAMILIES as Record<string, string>).forEach(([name, root]) => {
        if (!root) return;
        if (!allFamilyMembers[root]) allFamilyMembers[root] = [];
        allFamilyMembers[root].push(name);
        const snapshotRarity = rarityBySpeciesSnapshot[name];
        if (snapshotRarity) {
            const prev = familyRarityHint[root];
            if (!prev || (rarityWeight[snapshotRarity] || 0) > (rarityWeight[prev] || 0)) {
                familyRarityHint[root] = snapshotRarity;
            }
        }
    });
    allSpecies.forEach((name) => {
        const root = (EVOLUTION_FAMILIES as Record<string, string>)[name] || name;
        if (!families[root]) families[root] = [];
        families[root].push(name);
    });

    const newPool = {
        [RARITY.COMMON]: emptyTypedBuckets(),
        [RARITY.RARE]: emptyTypedBuckets(),
        [RARITY.EPIC]: emptyTypedBuckets(),
        [RARITY.LEGENDARY]: emptyTypedBuckets()
    };

    Object.entries(families).forEach(([root, speciesInFamily]) => {
        const familyMembers = Array.isArray(allFamilyMembers[root]) ? allFamilyMembers[root] : speciesInFamily;
        const depthMap = getDepthMapFromRoot(root);
        const rankedMembers = familyMembers
            .map((name) => {
                const dexId = Number(((POKEMON_SPRITE_IDS as Record<string, number>)[name] || 0));
                const depth = Number(depthMap[name] || 0);
                const bst = getOfficialBst(name);
                const catchRate = Number(((POKEMON_CATCH_RATES as Record<string, number>)[name] || 1));
                return { name, dexId, depth, bst, catchRate };
            })
            .filter((m) => Number.isFinite(m.dexId) && m.dexId > 0)
            .sort((a, b) =>
                (b.depth - a.depth) ||
                (b.bst - a.bst) ||
                (a.catchRate - b.catchRate) ||
                (b.dexId - a.dexId)
            );

        const firstInFamily = speciesInFamily[0];
        const benchmark = rankedMembers[0] || {
            name: firstInFamily ?? root,
            dexId: Number(firstInFamily ? ((POKEMON_SPRITE_IDS as Record<string, number>)[firstInFamily] || 0) : 0),
            bst: 0,
            catchRate: 1
        };

        let familyRarity: string;
        if (isHardLegendary(benchmark.dexId)) {
            familyRarity = RARITY.LEGENDARY;
        } else if (POPULAR_EPIC_FAMILY_ROOT_OVERRIDES.has(root)) {
            familyRarity = RARITY.EPIC;
        } else if (benchmark.bst <= 0 && familyRarityHint[root]) {
            familyRarity = familyRarityHint[root];
        } else if (benchmark.bst >= EPIC_BST_THRESHOLD || benchmark.catchRate <= VERY_LOW_CATCH_RATE) {
            familyRarity = RARITY.EPIC;
        } else if (benchmark.bst >= RARE_BST_THRESHOLD) {
            familyRarity = RARITY.RARE;
        } else {
            familyRarity = RARITY.COMMON;
        }

        if (FAMILY_RARITY_OVERRIDES[root]) {
            familyRarity = FAMILY_RARITY_OVERRIDES[root];
        }

        speciesInFamily.forEach((name) => {
            const typeKey = typeBySpecies[name] ?? TYPES.NORMAL;
            const rarityPool = (newPool as Record<string, Record<string, string[]>>)[familyRarity];
            if (!rarityPool || !typeKey) return;
            if (!rarityPool[typeKey]) rarityPool[typeKey] = [];
            rarityPool[typeKey].push(name);
        });
    });

    // Replace pool in-place (const object).
    Object.keys(POKEMON_POOL).forEach((k) => { delete POKEMON_POOL[k]; });
    POKEMON_POOL[RARITY.COMMON] = newPool[RARITY.COMMON];
    POKEMON_POOL[RARITY.RARE] = newPool[RARITY.RARE];
    POKEMON_POOL[RARITY.EPIC] = newPool[RARITY.EPIC];
    POKEMON_POOL[RARITY.LEGENDARY] = newPool[RARITY.LEGENDARY];

    eggPoolFamilyRarityRebuilt = true;
    return true;
}

// Backward-compatible alias (called from pokemonStats.js).
export function enrichEggPoolGen5To9ByFamilyRarity() {
    return rebuildEggPoolByFamilyRarityAllGens();
}

rebuildEggPoolByFamilyRarityAllGens();


