// Phase 6 fix: lookup globals at CALL TIME, not at module load time.
// At module evaluation, the lazy bridge hasn't loaded yet ? these were all undefined.
const _g = (): Record<string, unknown> => globalThis;

function strArg(v: ActionArg): string {
    return v == null ? '' : String(v);
}

function callGlobalVoid(key: string): void {
    const fn: unknown = _g()[key];
    if (typeof fn === 'function') {
        (fn as () => void)();
    }
}

function callGlobal1(key: string, a0: unknown): void {
    const fn: unknown = _g()[key];
    if (typeof fn === 'function') {
        (fn as (x: unknown) => void)(a0);
    }
}

function inputValue(el: HTMLElement | null | undefined): string {
    const v = (el as HTMLInputElement | HTMLSelectElement | undefined)?.value;
    return typeof v === 'string' ? v : '';
}

type ActionArg = string | null | undefined;
type ActionHandler = (arg1?: ActionArg, arg2?: ActionArg, arg3?: ActionArg, el?: HTMLElement | null, e?: Event) => void;

