// ---------------------------------------------------------------
// Robust click dispatch
// ---------------------------------------------------------------
// Sur desktop, un `click` natif ne se declenche QUE si `mousedown` et
// `mouseup` visent le meme noeud DOM. Or plusieurs composants (liste de
// quetes, onglets dynamiques, etc.) reconstruisent leur HTML de facon
// asynchrone pendant une frame de jeu. Si le rebuild tombe entre le
// mousedown et le mouseup de l'utilisateur, le noeud clique est remplace
// et le `click` n'est jamais emis : il faut "cliquer deux fois" pour que
// l'action passe. Sur tactile le `click` est synthetise depuis le
// touchstart/touchend et survit au remplacement du DOM — d'ou l'absence
// de bug sur smartphone.
//
// On synthetise donc l'action au `pointerup` lorsque :
//   - l'utilisateur a bien presse un `[data-action]` au pointerdown,
//   - il n'a pas "dragge" (mouvement < seuil),
//   - le click natif n'a pas ete emis (DOM remplace entre-temps).
// Un stamp empeche tout double-fire avec le handler de click natif.
// ---------------------------------------------------------------

interface PendingAction {
    target: Element;
    action: string;
    arg1: string | null;
    arg2: string | null;
    arg3: string | null;
    downX: number;
    downY: number;
    ts: number;
}

let _pendingActionDown: PendingAction | null = null;
let _lastNativeActionClickStamp = 0;
const POINTER_DRIFT_TOLERANCE_PX = 12;

export function initEventDelegation() {

document.addEventListener('pointerdown', function (e) {
    if (e.pointerType === 'mouse' && e.button !== 0) { _pendingActionDown = null; return; }
    const target = (e.target as HTMLElement)?.closest('[data-action]') ?? null;
    if (!target) { _pendingActionDown = null; return; }
    if ((target as HTMLElement).tagName === 'SELECT' || (target as HTMLElement).tagName === 'OPTION') { _pendingActionDown = null; return; }
    const actionAttr = target.getAttribute('data-action');
    if (!actionAttr) { _pendingActionDown = null; return; }
    _pendingActionDown = {
        target,
        action: actionAttr,
        arg1: target.getAttribute('data-arg'),
        arg2: target.getAttribute('data-arg2'),
        arg3: target.getAttribute('data-arg3'),
        downX: e.clientX,
        downY: e.clientY,
        ts: performance.now(),
    };
}, true);

document.addEventListener('pointerup', function (e) {
    const pending: PendingAction | null = _pendingActionDown;
    _pendingActionDown = null;
    if (!pending) return;
    if (Math.abs(e.clientX - pending.downX) > POINTER_DRIFT_TOLERANCE_PX) return;
    if (Math.abs(e.clientY - pending.downY) > POINTER_DRIFT_TOLERANCE_PX) return;

    const stampAtUp = pending.ts;
    const { target: downTarget, action, arg1, arg2, arg3 } = pending;
    const upX = e.clientX;
    const upY = e.clientY;
    const srcEvent = e;

    setTimeout(() => {
        if (_lastNativeActionClickStamp >= stampAtUp) return;

        const handler = ACTION_MAP[action];
        if (typeof handler !== 'function') return;

        const upEl = document.elementFromPoint(upX, upY);
        const upAction = upEl && (upEl as HTMLElement).closest ? (upEl as HTMLElement).closest('[data-action]') : null;
        const sameSignature = !!upAction
            && upAction.getAttribute('data-action') === action
            && upAction.getAttribute('data-arg') === arg1
            && upAction.getAttribute('data-arg2') === arg2
            && upAction.getAttribute('data-arg3') === arg3;
        if (upAction === downTarget && downTarget.isConnected) return;

        if (sameSignature && upAction) {
            _lastNativeActionClickStamp = performance.now();
            handler(arg1, arg2, arg3, upAction as HTMLElement, srcEvent);
            return;
        }

        // Moving targets (e.g. farm threat sprites) can drift off the cursor between
        // pointerdown and pointerup so elementFromPoint no longer matches — still honor
        // the press if the original target is connected and drift stayed within tolerance.
        if (downTarget.isConnected) {
            _lastNativeActionClickStamp = performance.now();
            handler(arg1, arg2, arg3, downTarget as HTMLElement, srcEvent);
        }
    }, 0);
}, true);

document.addEventListener('click', function (e) {
    const target = (e.target as HTMLElement)?.closest('[data-action]');
    if (!target) return;
    if ((target as HTMLElement).tagName === 'SELECT' || (target as HTMLElement).tagName === 'OPTION') return;

    const action = target.getAttribute('data-action');
    if (!action) return;
    const handler = ACTION_MAP[action];
    if (!handler) {
        debugWarn('[eventDelegation] unknown action:', action);
        return;
    }

    _lastNativeActionClickStamp = performance.now();

    const arg1 = target.getAttribute('data-arg');
    const arg2 = target.getAttribute('data-arg2');
    const arg3 = target.getAttribute('data-arg3');
    handler(arg1, arg2, arg3, target as HTMLElement, e);
}, true);

document.addEventListener('change', function (e) {
    const target = (e.target as HTMLElement)?.closest('select[data-action], input[data-action-on-change]');
    if (!target) return;
    const action = target.getAttribute('data-action') || target.getAttribute('data-action-on-change');
    if (!action) return;
    const handler = ACTION_MAP[action];
    if (!handler) return;
    const arg1 = target.getAttribute('data-arg');
    const arg2 = target.getAttribute('data-arg2');
    const arg3 = target.getAttribute('data-arg3');
    handler(arg1, arg2, arg3, target as HTMLElement, e);
}, true);

document.addEventListener('keydown', function (e) {
    if (e.key !== 'Enter' && e.key !== ' ') return;
    const target = (e.target as HTMLElement)?.closest('[data-action]');
    if (!target || (target as HTMLElement).tagName === 'BUTTON' || (target as HTMLElement).tagName === 'A') return;
    e.preventDefault();
    (target as HTMLElement).click();
});
}
