﻿/**
 * Apply auto-generated level-up overrides to POKEMON_DEFAULT_MOVES.
 */
import { resolveMoveName, hasMoveDefinition, isDamagingMove } from './movesDb.ts';
import { POKEMON_DEFAULT_MOVES } from './balance/pokemonDefaultsBase.ts';

export function applyLevelupDefaultMovesOverrides(OVERRIDES: Record<string, string[]> | null) {
    if (!OVERRIDES || typeof OVERRIDES !== 'object') return;

    const canResolve = resolveMoveName;
    const canFilterDefinition = hasMoveDefinition;
    const canFilterDamage = isDamagingMove;

    Object.keys(OVERRIDES).forEach((poke) => {
        const raw = OVERRIDES[poke] || [];
        const resolved = canResolve ? raw.map((m: string) => canResolve(m)) : raw;
        const filtered = resolved.filter((m: string) => {
            if (!m) return false;
            if (canFilterDefinition && !canFilterDefinition(m)) return false;
            if (canFilterDamage && !canFilterDamage(m)) return false;
            return true;
        });
        (POKEMON_DEFAULT_MOVES as Record<string, string[]>)[poke] = filtered.length ? filtered : ['Charge'];
    });
}

if (typeof globalThis !== 'undefined') {
    (globalThis as unknown as Record<string, unknown>).applyLevelupDefaultMovesOverrides = applyLevelupDefaultMovesOverrides;
}
if (typeof window !== 'undefined') {
    (window as unknown as Record<string, unknown>).applyLevelupDefaultMovesOverrides = applyLevelupDefaultMovesOverrides;
}
