/**
 * @file dynamaxSystem.ts
 * Dynamax Band mixin (Galar).
 */

import type { GameRuntime } from './src/types/game.js';
import { logMessage } from './src/ui/modals.ts';
import { showFloatingText } from './src/ui/floatingText.ts';
import { toast } from './toastManager.ts';
import { publishCombatStateChanged, publishResourcesChanged } from './src/bus/publishHooks.js';
import {
    getDynamaxHpMult,
    getDynamaxDurationMs,
} from './constants/balance/dynamax.ts';
import {
    canAffordDynamaxUpgrade,
    confirmDynamaxBand,
    depositDynamaxUpgrade,
    getDynamaxState,
    getDynamaxUpgradeLevel,
    getDynamaxUpgradeProgress,
    isDynamaxBandConfigured,
    isDynamaxBandUnlocked,
    onGalarGymBadgeWon,
    syncDynamaxFromGalarBadges,
    tryUpgradeDynamaxBand,
    type DynamaxDepositSelection,
} from './src/lib/dynamaxLogic.ts';
import { tryActivateDynamax, notifyDynamaxCombatHud } from './src/lib/dynamaxCombat.ts';

type GameCtor = { prototype: Record<string, unknown> };
type ThisGame = GameRuntime;

export function applyDynamaxSystem(GameClass: GameCtor): void {
    GameClass.prototype.isDynamaxBandUnlocked = function (this: ThisGame): boolean {
        return isDynamaxBandUnlocked(this);
    };

    GameClass.prototype.isDynamaxBandConfigured = function (this: ThisGame): boolean {
        return isDynamaxBandConfigured(this);
    };

    GameClass.prototype.getDynamaxUpgradeLevel = function (this: ThisGame): number {
        return getDynamaxUpgradeLevel(this);
    };

    GameClass.prototype.confirmDynamaxBand = function (this: ThisGame): boolean {
        if (this.combatState === 'fighting' || this.combatState === 'starting' || this.combatState === 'capture') {
            logMessage(
                typeof this.t === 'function'
                    ? this.t('dynamax.configureBlockedCombat')
                    : 'Configure Dynamax Band outside combat only.',
            );
            return false;
        }
        const ok = confirmDynamaxBand(this);
        if (ok) {
            if (typeof this.checkSpecialQuests === 'function') {
                this.checkSpecialQuests('dynamax_band_configured');
            }
            if (typeof this.saveGame === 'function') this.saveGame();
            logMessage(
                typeof this.t === 'function'
                    ? this.t('dynamax.bandConfigured')
                    : 'Dynamax Band ready for zone battles.',
            );
        }
        return ok;
    };

    GameClass.prototype.depositDynamaxUpgrade = function (
        this: ThisGame,
        selection: DynamaxDepositSelection,
    ): boolean {
        const beforeLevel = getDynamaxUpgradeLevel(this);
        const result = depositDynamaxUpgrade(this, selection);
        if (!result.ok) {
            const body = typeof this.t === 'function'
                ? this.t('dynamax.upgradeFailed')
                : 'Dépôt Dynamax impossible.';
            if (typeof toast !== 'undefined' && typeof toast.warning === 'function') {
                toast.warning(
                    typeof this.t === 'function' ? this.t('dynamax.title') : 'Dynamax',
                    body && body !== 'dynamax.upgradeFailed' ? body : 'Dépôt Dynamax impossible.',
                );
            }
            logMessage(body);
            return false;
        }
        const level = getDynamaxUpgradeLevel(this);
        const leveled = result.leveled || level > beforeLevel;
        if (leveled) {
            const mult = getDynamaxHpMult(level);
            const durSec = Math.round(getDynamaxDurationMs(level) / 1000);
            const title = typeof this.t === 'function' ? this.t('toast.dynamaxUpgradedTitle') : 'Bande Dynamax';
            const bodyRaw = typeof this.t === 'function'
                ? this.t('toast.dynamaxUpgradedBody', { level, mult: mult.toFixed(1), seconds: durSec })
                : '';
            const titleSafe = title && title !== 'toast.dynamaxUpgradedTitle' ? title : 'Bande Dynamax';
            const bodySafe = bodyRaw && bodyRaw !== 'toast.dynamaxUpgradedBody'
                ? bodyRaw
                : `Bande améliorée (niv. ${level}) : PV/dégâts ×${mult.toFixed(1)}, ${durSec} s.`;
            if (typeof toast !== 'undefined' && typeof toast.success === 'function') {
                toast.success(titleSafe, bodySafe);
            }
            logMessage(bodySafe);
        } else {
            const progress = getDynamaxUpgradeProgress(this);
            const title = typeof this.t === 'function' ? this.t('dynamax.title') : 'Bande Dynamax';
            const bodyRaw = typeof this.t === 'function'
                ? this.t('dynamax.depositProgress', {
                    moneyHave: progress.moneyHave,
                    moneyNeed: progress.moneyNeed ?? 0,
                    itemsHave: progress.itemsHave,
                    itemsNeed: progress.itemsNeed ?? 0,
                })
                : '';
            const bodySafe = bodyRaw && bodyRaw !== 'dynamax.depositProgress'
                ? bodyRaw
                : `Dépôt Dynamax : ${progress.moneyHave}/${progress.moneyNeed ?? 0} $ · ${progress.itemsHave}/${progress.itemsNeed ?? 0} items.`;
            if (typeof toast !== 'undefined' && typeof toast.info === 'function') {
                toast.info(title, bodySafe);
            } else if (typeof toast !== 'undefined' && typeof toast.success === 'function') {
                toast.success(title, bodySafe);
            }
            logMessage(bodySafe);
        }
        if (typeof this.saveGame === 'function') this.saveGame();
        if (typeof this.updateTeamDisplay === 'function') this.updateTeamDisplay();
        publishResourcesChanged();
        return true;
    };

    GameClass.prototype.upgradeDynamaxBand = function (this: ThisGame, stoneKey: string): boolean {
        const beforeLevel = getDynamaxUpgradeLevel(this);
        const afford = canAffordDynamaxUpgrade(this, stoneKey);
        const ok = tryUpgradeDynamaxBand(this, stoneKey);
        if (!ok) {
            const reason = afford.ok ? null : afford.reason;
            let body = typeof this.t === 'function'
                ? this.t('dynamax.upgradeFailed')
                : 'Amélioration Dynamax impossible.';
            if (typeof this.t === 'function') {
                if (reason === 'no_money') body = this.t('toast.notEnoughPokedollars');
                else if (reason === 'no_stones') body = this.t('dynamax.upgradeNoStones');
                else if (reason === 'max_level') body = this.t('dynamax.upgradeMax');
            }
            if (typeof toast !== 'undefined' && typeof toast.warning === 'function') {
                toast.warning(
                    typeof this.t === 'function' ? this.t('dynamax.title') : 'Dynamax',
                    body && body !== 'toast.notEnoughPokedollars' && !body.startsWith('dynamax.')
                        ? body
                        : (reason === 'no_money'
                            ? 'Pas assez de Pokédollars !'
                            : reason === 'no_stones'
                                ? 'Pas assez d\'items d\'évolution.'
                                : 'Amélioration Dynamax impossible.'),
                );
            }
            logMessage(body);
            return false;
        }
        const level = getDynamaxUpgradeLevel(this);
        const leveled = level > beforeLevel;
        if (leveled) {
            const mult = getDynamaxHpMult(level);
            const durSec = Math.round(getDynamaxDurationMs(level) / 1000);
            const title = typeof this.t === 'function' ? this.t('toast.dynamaxUpgradedTitle') : 'Bande Dynamax';
            const bodyRaw = typeof this.t === 'function'
                ? this.t('toast.dynamaxUpgradedBody', { level, mult: mult.toFixed(1), seconds: durSec })
                : '';
            const titleSafe = title && title !== 'toast.dynamaxUpgradedTitle' ? title : 'Bande Dynamax';
            const bodySafe = bodyRaw && bodyRaw !== 'toast.dynamaxUpgradedBody'
                ? bodyRaw
                : `Bande améliorée (niv. ${level}) : PV/dégâts ×${mult.toFixed(1)}, ${durSec} s.`;
            if (typeof toast !== 'undefined' && typeof toast.success === 'function') {
                toast.success(titleSafe, bodySafe);
            }
            logMessage(bodySafe);
        } else {
            const progress = getDynamaxUpgradeProgress(this);
            const title = typeof this.t === 'function' ? this.t('dynamax.title') : 'Bande Dynamax';
            const bodyRaw = typeof this.t === 'function'
                ? this.t('dynamax.depositProgress', {
                    moneyHave: progress.moneyHave,
                    moneyNeed: progress.moneyNeed ?? 0,
                    itemsHave: progress.itemsHave,
                    itemsNeed: progress.itemsNeed ?? 0,
                })
                : '';
            const bodySafe = bodyRaw && bodyRaw !== 'dynamax.depositProgress'
                ? bodyRaw
                : `Dépôt Dynamax : ${progress.moneyHave}/${progress.moneyNeed ?? 0} $ · ${progress.itemsHave}/${progress.itemsNeed ?? 0} items.`;
            if (typeof toast !== 'undefined' && typeof toast.info === 'function') {
                toast.info(title, bodySafe);
            } else if (typeof toast !== 'undefined' && typeof toast.success === 'function') {
                toast.success(title, bodySafe);
            }
            logMessage(bodySafe);
        }
        if (typeof this.saveGame === 'function') this.saveGame();
        if (typeof this.updateTeamDisplay === 'function') this.updateTeamDisplay();
        publishResourcesChanged();
        return true;
    };

    GameClass.prototype.activateDynamax = function (this: ThisGame): boolean {
        const ok = tryActivateDynamax(this);
        if (ok) {
            const level = getDynamaxUpgradeLevel(this);
            const mult = getDynamaxHpMult(level);
            const durSec = Math.round(getDynamaxDurationMs(level) / 1000);
            const title = typeof this.t === 'function' ? this.t('toast.dynamaxActivatedTitle') : 'Dynamax';
            const bodyKey = 'toast.dynamaxActivatedBody';
            const body = typeof this.t === 'function'
                ? this.t(bodyKey, { mult: mult.toFixed(1), seconds: durSec })
                : '';
            const titleSafe = title && title !== 'toast.dynamaxActivatedTitle' ? title : 'Dynamax';
            const bodySafe = body && body !== bodyKey
                ? body
                : `Dynamax activé ! PV et dégâts ×${mult.toFixed(1)} pendant ${durSec} s (fenêtre compte).`;
            if (typeof toast !== 'undefined' && typeof toast.success === 'function') {
                toast.success(titleSafe, bodySafe);
            }
            logMessage(bodySafe);

            const playerContainer = document.getElementById('playerSpriteContainer');
            if (playerContainer) {
                playerContainer.classList.add('is-dynamax', 'dynamax-burst');
                showFloatingText('DYNAMAX!', playerContainer, 'ft-dynamax');
                window.setTimeout(() => {
                    playerContainer.classList.remove('dynamax-burst');
                }, 700);
            }

            notifyDynamaxCombatHud(this);
            publishCombatStateChanged();
        }
        return ok;
    };

    GameClass.prototype.syncDynamaxFromBadges = function (this: ThisGame): void {
        syncDynamaxFromGalarBadges(this);
    };
}

export function onGalarGymBadgeWonDynamax(game: GameRuntime, badgeKey: string): void {
    onGalarGymBadgeWon(game, badgeKey);
}

export function ensureDynamaxOnLoad(game: GameRuntime): void {
    getDynamaxState(game);
    syncDynamaxFromGalarBadges(game);
}

export { isDynamaxBandUnlocked, getDynamaxState };
