<script lang="ts">
  import {
    DEFAULT_STORAGE_FILTERS,
    type StorageFilterState,
  } from '../lib/storageRoster.js';
  import { game } from '../../gameManager.js';
  import { uiText } from '../ui/i18n.ts';

  let {
    idPrefix = '',
    filters = $bindable({ ...DEFAULT_STORAGE_FILTERS }),
    onFilterChange = () => {},
  }: {
    idPrefix?: string;
    filters?: StorageFilterState;
    onFilterChange?: () => void;
  } = $props();

  let favoritesLabel = $derived(uiText('storage.favoritesOnly', 'Favoris', {}, game));
  let favoritesAria = $derived(uiText('storage.favoritesOnlyAria', 'Afficher uniquement les favoris', {}, game));

  const TYPE_OPTIONS = [
    { value: 'all', label: 'Tous les types' },
    { value: 'fire', label: 'Feu' },
    { value: 'water', label: 'Eau' },
    { value: 'grass', label: 'Plante' },
    { value: 'electric', label: 'Electrik' },
    { value: 'normal', label: 'Normal' },
    { value: 'flying', label: 'Vol' },
    { value: 'bug', label: 'Insecte' },
    { value: 'poison', label: 'Poison' },
    { value: 'ground', label: 'Sol' },
    { value: 'rock', label: 'Roche' },
    { value: 'fighting', label: 'Combat' },
    { value: 'psychic', label: 'Psy' },
    { value: 'ghost', label: 'Spectre' },
    { value: 'ice', label: 'Glace' },
    { value: 'dragon', label: 'Dragon' },
    { value: 'steel', label: 'Acier' },
    { value: 'dark', label: 'Ténèbres' },
    { value: 'fairy', label: 'Fée' },
  ] as const;

  const GEN_OPTIONS = [
    { value: 'all', label: 'Toutes les générations' },
    { value: '1', label: 'Gen 1' },
    { value: '2', label: 'Gen 2' },
    { value: '3', label: 'Gen 3' },
    { value: '4', label: 'Gen 4' },
    { value: '5', label: 'Gen 5' },
    { value: '6', label: 'Gen 6' },
    { value: '7', label: 'Gen 7' },
    { value: '8', label: 'Gen 8' },
    { value: '9', label: 'Gen 9' },
  ] as const;

  function onSearchInput(e: Event): void {
    const value = (e.currentTarget as HTMLInputElement).value;
    filters = { ...filters, searchText: value };
    onFilterChange();
  }

  function onTypeChange(e: Event, field: 'selectedType' | 'selectedType2'): void {
    const value = (e.currentTarget as HTMLSelectElement).value;
    filters = { ...filters, [field]: value };
    onFilterChange();
  }

  function onGenChange(e: Event): void {
    const value = (e.currentTarget as HTMLSelectElement).value;
    filters = { ...filters, selectedGeneration: value };
    onFilterChange();
  }

  function toggleFavoritesOnly(): void {
    filters = { ...filters, favoritesOnly: !filters.favoritesOnly };
    onFilterChange();
  }
</script>

<div class="storage-filters-row">
  <input
    type="text"
    id="{idPrefix}storageSearchInput"
    placeholder="Rechercher par nom..."
    class="storage-filters-row__search"
    value={filters.searchText}
    oninput={onSearchInput}
  />
  <button
    type="button"
    id="{idPrefix}storageFavoriteFilter"
    class="storage-filters-row__select storage-filters-row__favorite-toggle"
    class:active={filters.favoritesOnly}
    aria-pressed={filters.favoritesOnly}
    aria-label={favoritesAria}
    title={favoritesAria}
    onclick={toggleFavoritesOnly}
  ><span class="storage-filters-row__favorite-icon" aria-hidden="true">{filters.favoritesOnly ? '★' : '☆'}</span> {favoritesLabel}</button>
  <select
    id="{idPrefix}storageTypeFilter"
    class="storage-filters-row__select"
    value={filters.selectedType}
    onchange={(e) => onTypeChange(e, 'selectedType')}
  >
    {#each TYPE_OPTIONS as opt (opt.value)}
      <option value={opt.value}>{opt.label}</option>
    {/each}
  </select>
  <select
    id="{idPrefix}storageTypeFilter2"
    class="storage-filters-row__select"
    value={filters.selectedType2}
    onchange={(e) => onTypeChange(e, 'selectedType2')}
  >
    {#each TYPE_OPTIONS as opt (opt.value)}
      <option value={opt.value}>{opt.label}</option>
    {/each}
  </select>
  <select
    id="{idPrefix}storageGenFilter"
    class="storage-filters-row__select"
    value={filters.selectedGeneration}
    onchange={onGenChange}
  >
    {#each GEN_OPTIONS as opt (opt.value)}
      <option value={opt.value}>{opt.label}</option>
    {/each}
  </select>
</div>
