import { logMessage } from './src/ui/modals.ts';
import { awaitLazyModalReady } from './src/lib/lazyModalMounts.ts';
import { setMasteryProfileTab } from './src/stores/masteryProfileTab.svelte.ts';
import { buildTrainerCardHtml, bindArenaBadgeTooltips } from './src/lib/arenaSnapshot.ts';
import { getRegions } from './src/lib/regionsRuntime.ts';
