function uiGameRef(ref: GameRuntime | null | undefined): GameRuntime | undefined {
    return ref ?? undefined;
}

function uiT(
    gameRef: GameRuntime,
    key: string,
    fallback: string | null = null,
    vars: Record<string, unknown> = {},
): string {
    return uiText(key, fallback, vars, uiGameRef(gameRef));
}

interface RocketCasinoSpinResult {
    matrix?: string[][];
    winningLines?: Array<{ coords?: Array<[number, number]> }>;
}

interface RocketContractSelectOption {
    name: string;
    key?: string;
    have?: number;
    img?: string | null;
    icon?: string;
    storageIndex?: number;
    isShiny?: boolean;
    rarity?: string;
    level?: number;
}

// === Shared state (moved from uiManager.js) ===
let rocketCasinoSpinLock = false;
let rocketCasinoAutoSpinActive = false;
let rocketCasinoAutoSpinCancelRequested = false;
let rocketCasinoAutoSpinRemaining = 0;
let rocketCasinoAutoSpinTotalStarted = 0;
let rocketCasinoBackgroundHideImmediate = false;
let rocketCasinoBackgroundHideTimer: ReturnType<typeof setTimeout> | null = null;
let rocketCasinoBackgroundMinimized = false;
let rocketCasinoWiredGame: GameRuntime | null = null;

export function isRocketCasinoAutoSpinActive(): boolean {
    return rocketCasinoAutoSpinActive;
}

export function isRocketCasinoModalVisible(): boolean {
    return document.getElementById('rocketCasinoOverlay')?.classList.contains('show') ?? false;
}

/** @internal Test hook — seed module session flags. */
export function __setRocketCasinoSessionStateForTest(state: {
    autoSpinActive?: boolean;
    autoSpinRemaining?: number;
    autoSpinTotalStarted?: number;
    backgroundMinimized?: boolean;
    wiredGame?: GameRuntime | null;
}): void {
    if (state.autoSpinActive !== undefined) rocketCasinoAutoSpinActive = state.autoSpinActive;
    if (state.autoSpinRemaining !== undefined) rocketCasinoAutoSpinRemaining = state.autoSpinRemaining;
    if (state.autoSpinTotalStarted !== undefined) rocketCasinoAutoSpinTotalStarted = state.autoSpinTotalStarted;
    if (state.backgroundMinimized !== undefined) rocketCasinoBackgroundMinimized = state.backgroundMinimized;
    if (state.wiredGame !== undefined) rocketCasinoWiredGame = state.wiredGame;
}

/** @internal Test hook — reset module session flags. */
export function __resetRocketCasinoSessionStateForTest(): void {
    rocketCasinoSpinLock = false;
    rocketCasinoAutoSpinActive = false;
    rocketCasinoAutoSpinCancelRequested = false;
    rocketCasinoAutoSpinRemaining = 0;
    rocketCasinoAutoSpinTotalStarted = 0;
    rocketCasinoBackgroundHideImmediate = false;
    rocketCasinoBackgroundMinimized = false;
    rocketCasinoWiredGame = null;
    clearBackgroundHideTimer();
}

function resolveCasinoGame(game?: GameRuntime | null): GameRuntime | null {
    return game ?? rocketCasinoWiredGame ?? (gameManagerRef as GameRuntime | null);
}

function clearBackgroundHideTimer(): void {
    if (rocketCasinoBackgroundHideTimer) {
        clearTimeout(rocketCasinoBackgroundHideTimer);
        rocketCasinoBackgroundHideTimer = null;
    }
}

function scheduleBackgroundSessionHide(immediate = false): void {
    clearBackgroundHideTimer();
    const delayMs = immediate || rocketCasinoBackgroundHideImmediate ? 0 : 2000;
    rocketCasinoBackgroundHideImmediate = false;
    rocketCasinoBackgroundHideTimer = setTimeout(() => {
        rocketCasinoBackgroundHideTimer = null;
        rocketCasinoBackgroundMinimized = false;
        patchRocketCasinoBackgroundSession({ visible: false, running: false, spinning: false });
    }, delayMs);
}

function syncBackgroundSession(game: GameRuntime, overrides: Parameters<typeof syncRocketCasinoBackgroundSession>[1] = {}): void {
    syncRocketCasinoBackgroundSession(game, {
        running: rocketCasinoAutoSpinActive,
        spinning: rocketCasinoSpinLock,
        remaining: rocketCasinoAutoSpinRemaining,
        totalStarted: rocketCasinoAutoSpinTotalStarted,
        ...overrides,
    });
}

export function updateTeamRocketDisplayUI(game: GameRuntime): void {
    if (!document.getElementById('teamRocketPanel') || !game.teamRocketState) return;
    notifyRocketPanelRefresh(game);
}

/** Staking section refresh after recover / contract — snapshot + realtime in sync. */
export function updateRocketStakingSectionUI(game: GameRuntime): void {
    if (!game?.teamRocketState) return;
    if (typeof game.refreshRocketStakeableOffers === 'function') {
        game.refreshRocketStakeableOffers(Date.now(), false);
    }
    notifyRocketPanelRefresh(game);
}

export function closeRocketContractSelectModalUI() {
    closeRocketContractSelectModal();
}

export function minimizeRocketCasinoModalUI(game?: GameRuntime | null): void {
    const gm = resolveCasinoGame(game);
    rocketCasinoBackgroundMinimized = true;
    closeRocketCasinoModal();
    if (gm?.teamRocketState) {
        syncBackgroundSession(gm, { visible: true });
    }
}

export function closeRocketCasinoModalUI(game?: GameRuntime | null): void {
    if (rocketCasinoAutoSpinActive) {
        minimizeRocketCasinoModalUI(game);
        return;
    }
    closeRocketCasinoModal();
    rocketCasinoSpinLock = false;
    rocketCasinoAutoSpinCancelRequested = false;
    rocketCasinoBackgroundMinimized = false;
    clearBackgroundHideTimer();
    patchRocketCasinoBackgroundSession({ visible: false, running: false, spinning: false });
}

export function stopRocketCasinoAutoSpinUI(game?: GameRuntime | null): void {
    const gm = resolveCasinoGame(game);
    if (!rocketCasinoAutoSpinActive) return;
    rocketCasinoAutoSpinCancelRequested = true;
    rocketCasinoBackgroundHideImmediate = true;
    if (gm) {
        patchRocketCasinoAutoSpin({
            statusText: uiT(gm, 'teamRocket.casinoAutoSpinStopping', 'Stopping after current spin...'),
        });
        syncBackgroundSession(gm, {
            statusText: uiT(gm, 'teamRocket.casinoAutoSpinStopping', 'Stopping after current spin...'),
        });
    }
}

export function renderRocketCasinoHistoryUI(game: GameRuntime): void {
    notifyRocketCasinoModalChanged(game);
    if (rocketCasinoAutoSpinActive && !isRocketCasinoModalVisible()) {
        syncBackgroundSession(game);
    }
}

export function getRocketCasinoGridCellEl(col: number, row: number): HTMLElement | null {
    return document.getElementById(`rocketCasinoCell_${col}_${row}`);
}

export function clearRocketCasinoGridHighlights() {
    for (let col = 0; col < 3; col++) {
        for (let row = 0; row < 3; row++) {
            const cell = getRocketCasinoGridCellEl(col, row);
            if (!cell) continue;
            cell.classList.remove('win-highlight');
        }
    }
}

export function animateRocketCasinoCounter(startValue: number, endValue: number, durationMs: number, onUpdate: (value: number) => void, onDone?: () => void): void {
    const start = performance.now();
    const delta = endValue - startValue;
    const tick = (now: number) => {
        const t = Math.min(1, (now - start) / Math.max(1, durationMs));
        const eased = 1 - Math.pow(1 - t, 3);
        const value = Math.floor(startValue + (delta * eased));
        if (typeof onUpdate === 'function') onUpdate(value);
        if (t < 1) {
            requestAnimationFrame(tick);
        } else if (typeof onDone === 'function') {
            onDone();
        }
    };
    requestAnimationFrame(tick);
}

export function animateRocketCasinoGridReveal(result: RocketCasinoSpinResult, onDone?: () => void, speedBonus = 0): void {
    const matrix = result.matrix || [[], [], []];
    const gridEl = document.getElementById('rocketCasinoGrid3x3');
    if (!gridEl) {
        if (typeof onDone === 'function') onDone();
        return;
    }
    clearRocketCasinoGridHighlights();

    const speedMult = 1 + Math.max(0, Math.min(0.9, Number(speedBonus) || 0));
    const REEL_EXTRA_SYMBOLS = 12;
    const REEL_DURATION_MS = Math.round(2200 / speedMult);
    const REEL_STAGGER_MS = Math.round(180 / speedMult);
    const REEL_EASE = 'cubic-bezier(0.25, 0.1, 0.25, 1)';

    function buildReelStripHtml(colIndex: number) {
        const col = matrix[colIndex];
        const finalSymbols = [col?.[0], col?.[1], col?.[2]].filter((s): s is string => typeof s === 'string');
        const keys = [];
        for (let i = 0; i < REEL_EXTRA_SYMBOLS; i++) keys.push(rollRocketCasinoSymbolKey());
        keys.push(...finalSymbols);
        return keys.map(key => {
            const meta = getRocketCasinoSymbolMeta(key || 'unknown');
            return `<div class="rocket-casino-reel-symbol"><img src="${meta.sprite}" alt="${meta.label}" class="rocket-casino-symbol-img"></div>`;
        }).join('');
    }

    gridEl.classList.add('rocket-casino-reels-mode');
    gridEl.innerHTML = [0, 1, 2].map(col => `
        <div class="rocket-casino-reel" id="rocketCasinoReel_${col}" data-col="${col}">
            <div class="rocket-casino-reel-strip">${buildReelStripHtml(col)}</div>
        </div>
    `).join('');

    void gridEl.offsetHeight;

    [0, 1, 2].forEach((col, idx) => {
        const strip = document.querySelector(`#rocketCasinoReel_${col} .rocket-casino-reel-strip`) as HTMLElement | null;
        if (!strip) return;
        strip.style.transform = 'translateY(0)';
        strip.style.transition = `transform ${REEL_DURATION_MS}ms ${REEL_EASE}`;
        setTimeout(() => {
            strip.style.transform = 'translateY(-80%)';
        }, idx * REEL_STAGGER_MS);
    });

    const totalAnimMs = REEL_STAGGER_MS * 2 + REEL_DURATION_MS + Math.round(300 / speedMult);
    setTimeout(() => {
        gridEl.classList.remove('rocket-casino-reels-mode');
        gridEl.innerHTML = [0, 1, 2].map(row => [0, 1, 2].map(col => {
            const key = matrix[col]?.[row];
            const meta = getRocketCasinoSymbolMeta(key ?? 'unknown');
            return `<div class="rocket-casino-cell revealed" id="rocketCasinoCell_${col}_${row}"><img src="${meta.sprite}" alt="${meta.label}" class="rocket-casino-symbol-img"></div>`;
        }).join('')).join('');

        const wins = Array.isArray(result.winningLines) ? result.winningLines : [];
        let delay = 0;
        wins.forEach((win: { coords?: Array<[number, number]> }) => {
            setTimeout(() => {
                (win.coords || []).forEach(([c, r]: [number, number]) => {
                    const cell = getRocketCasinoGridCellEl(c, r);
                    if (cell) cell.classList.add('win-highlight');
                });
            }, delay);
            delay += 260;
        });
        setTimeout(() => {
            if (typeof onDone === 'function') onDone();
        }, Math.max(0, delay));
    }, totalAnimMs);
}

export function showRocketCasinoModalUI(game: GameRuntime): void {
    if (!game.teamRocketState) return;
    clearBackgroundHideTimer();
    rocketCasinoBackgroundMinimized = false;
    patchRocketCasinoBackgroundSession({ visible: false });
    notifyRocketCasinoModalChanged(game);
    openRocketCasinoModal();
}

function finishAutoSpinSession(game: GameRuntime, statusText = ''): void {
    rocketCasinoAutoSpinActive = false;
    rocketCasinoAutoSpinCancelRequested = false;
    patchRocketCasinoAutoSpin({
        showStop: false,
        running: false,
        statusText,
    });
    syncBackgroundSession(game, {
        running: false,
        spinning: rocketCasinoSpinLock,
        remaining: 0,
        statusText,
    });
    if (rocketCasinoBackgroundMinimized) {
        syncBackgroundSession(game, { visible: true });
        scheduleBackgroundSessionHide();
    }
}

/** Wire spin / auto-spin DOM handlers after Svelte modal is visible (buttons may mount late). */
export function wireRocketCasinoModalControls(game: GameRuntime): void {
    if (!game.teamRocketState) return;
    rocketCasinoWiredGame = game;
    const trText = (key: string, fallback: string | null, vars: Record<string, unknown> = {}) => uiT(game, `teamRocket.${key}`, fallback, vars);
    const cfg = ROCKET_CASINO_CONFIG ?? { lineCostRJ: 250, defaultActivePaylines: 8 };
    const lineCost = Math.max(1, Math.floor(Number(cfg.lineCostRJ) || 250));
    const maxPaylines = 8;
    const defaultLines = Math.max(1, Math.min(maxPaylines, Math.floor(Number(cfg.defaultActivePaylines) || maxPaylines)));

    const rjText = document.getElementById('rocketCasinoModalRjText');
    const spinBtn = document.getElementById('rocketCasinoSpinBtn');
    const autoSpinBtn = document.getElementById('rocketCasinoAutoSpinBtn');
    const autoSpinStopBtn = document.getElementById('rocketCasinoAutoSpinStopBtn');

    const refreshRjLabel = () => {
        if (!game?.teamRocketState) return;
        const label = trText('casinoRjLabel', 'Rocket Token: {value}', {
            value: formatNumber(game.teamRocketState.rj || 0),
        });
        patchRocketCasinoRjLabel(label);
        if (rjText) rjText.textContent = label;
        if (rocketCasinoAutoSpinActive && !isRocketCasinoModalVisible()) {
            syncBackgroundSession(game, { rjLabel: label });
        }
    };

    const completeSpinUi = (afterRJ: number, onDone?: (result: RocketCasinoSpinResult | null) => void, result?: RocketCasinoSpinResult | null) => {
        if (rjText) {
            rjText.textContent = trText('casinoRjLabel', 'Rocket Token: {value}', { value: formatNumber(afterRJ) });
        }
        rocketCasinoSpinLock = false;
        if (isHtmlButtonElement(spinBtn)) spinBtn.disabled = rocketCasinoAutoSpinActive;
        refreshRjLabel();
        syncBackgroundSession(game, { spinning: false });
        if (typeof onDone === 'function') onDone(result ?? null);
    };

    const runCasinoSpin = (onDone?: (result: RocketCasinoSpinResult | null) => void) => {
        if (!game || rocketCasinoSpinLock) { if (typeof onDone === 'function') onDone(null); return null; }
        const linesPlayed = defaultLines;
        let stakeCost = lineCost * linesPlayed;

        if (game.upgrades && game.upgrades.casinoRoyal) {
            const reduction = game.upgrades.casinoRoyal.level * 0.05;
            stakeCost = Math.floor(stakeCost * (1 - reduction));
        }

        const beforeRJ = Math.max(0, Math.floor(Number(game.teamRocketState.rj) || 0));
        const result = (typeof game.handleRocketCasinoSpinAmount === 'function')
            ? game.handleRocketCasinoSpinAmount(linesPlayed)
            : null;
        if (!result) { if (typeof onDone === 'function') onDone(null); return null; }
        const afterRJ = Math.max(0, Math.floor(Number(game.teamRocketState.rj) || 0));

        rocketCasinoSpinLock = true;
        syncBackgroundSession(game, { spinning: true });
        if (isHtmlButtonElement(spinBtn)) spinBtn.disabled = true;

        if (rjText && isRocketCasinoModalVisible()) {
            showFloatingText(`-${formatNumber(stakeCost)}`, rjText, 'ft-debt ft-from-rj');
        }

        const currentSpeedBonus = (game && typeof game.getRocketAutoSpinSpeedBonus === 'function')
            ? game.getRocketAutoSpinSpeedBonus()
            : 0;

        const finishSpin = () => {
            renderRocketCasinoHistoryUI(game);
            const counterDuration = Math.max(120, Math.round(550 / (1 + currentSpeedBonus)));
            animateRocketCasinoCounter(beforeRJ, afterRJ, counterDuration, (value: number) => {
                const label = trText('casinoRjLabel', 'Rocket Token: {value}', { value: formatNumber(value) });
                if (rjText && isRocketCasinoModalVisible()) {
                    rjText.textContent = label;
                }
                if (rocketCasinoAutoSpinActive && !isRocketCasinoModalVisible()) {
                    patchRocketCasinoRjLabel(label);
                    syncBackgroundSession(game, { rjLabel: label });
                }
            }, () => {
                completeSpinUi(afterRJ, onDone, result);
            });
        };

        animateRocketCasinoGridReveal(result, finishSpin, currentSpeedBonus);
        return result;
    };

    const setAutoSpinUi = (active: boolean, remaining = 0) => {
        const statusText = active
            ? trText('casinoAutoSpinRunning', 'Auto-spinning: {remaining} left', { remaining })
            : '';
        patchRocketCasinoAutoSpin({
            showStop: active,
            running: active,
            statusText,
        });
        syncBackgroundSession(game, {
            running: active,
            remaining,
            statusText,
            ...(active && rocketCasinoBackgroundMinimized ? { visible: true } : {}),
        });
    };

    const runAutoSpinSession = () => {
        if (rocketCasinoAutoSpinActive) return;
        const totalSpins = (game && typeof game.getRocketAutoSpinCount === 'function') ? game.getRocketAutoSpinCount() : 0;
        if (totalSpins <= 0) return;

        clearBackgroundHideTimer();
        rocketCasinoAutoSpinActive = true;
        rocketCasinoAutoSpinCancelRequested = false;
        rocketCasinoBackgroundHideImmediate = false;
        rocketCasinoAutoSpinTotalStarted = totalSpins;
        rocketCasinoAutoSpinRemaining = totalSpins;
        setAutoSpinUi(true, rocketCasinoAutoSpinRemaining);

        const spinOnce = () => {
            if (!rocketCasinoAutoSpinActive || rocketCasinoAutoSpinCancelRequested || rocketCasinoAutoSpinRemaining <= 0) {
                finishAutoSpinSession(game);
                if (isHtmlButtonElement(spinBtn)) spinBtn.disabled = rocketCasinoSpinLock;
                return;
            }
            const current = Math.max(0, Math.floor(Number(game.teamRocketState && game.teamRocketState.rj) || 0));
            let stakeNeeded = lineCost * defaultLines;
            if (game.upgrades && game.upgrades.casinoRoyal) {
                const reduction = game.upgrades.casinoRoyal.level * 0.05;
                stakeNeeded = Math.floor(stakeNeeded * (1 - reduction));
            }
            if (current < stakeNeeded) {
                const noRjText = trText('casinoAutoSpinNoRj', 'Auto-spin stopped: not enough RJ.');
                finishAutoSpinSession(game, noRjText);
                if (isHtmlButtonElement(spinBtn)) spinBtn.disabled = rocketCasinoSpinLock;
                return;
            }

            const spinResult = runCasinoSpin(() => {
                rocketCasinoAutoSpinRemaining -= 1;
                setAutoSpinUi(true, rocketCasinoAutoSpinRemaining);
                const speedBonus = (game && typeof game.getRocketAutoSpinSpeedBonus === 'function') ? game.getRocketAutoSpinSpeedBonus() : 0;
                const gap = Math.max(80, Math.round(220 / (1 + speedBonus)));
                setTimeout(spinOnce, gap);
            });
            if (!spinResult) {
                finishAutoSpinSession(game);
                if (isHtmlButtonElement(spinBtn)) spinBtn.disabled = rocketCasinoSpinLock;
            }
        };

        spinOnce();
    };

    if (spinBtn) {
        spinBtn.onclick = function () {
            if (rocketCasinoAutoSpinActive) return;
            runCasinoSpin(undefined);
        };
        spinBtn.onmousedown = function () {
            spinBtn.classList.add('spin-pressed-btn');
        };
        const releaseSpin = function () {
            spinBtn.classList.remove('spin-pressed-btn');
        };
        spinBtn.onmouseup = releaseSpin;
        spinBtn.onmouseleave = releaseSpin;
    }
    if (autoSpinBtn) {
        autoSpinBtn.onclick = function () {
            runAutoSpinSession();
        };
    }
    if (autoSpinStopBtn) {
        autoSpinStopBtn.onclick = function () {
            stopRocketCasinoAutoSpinUI(game);
        };
    }
    refreshRjLabel();
}

