/**
 * @file src/lib/shinyCharmCombatIndicator.ts
 * Combat zone indicator when Shiny Charm timed boost is active.
 */

import { formatBoostTimeLeft } from '../../formatters.ts';
import { getAllItem } from '../ui/uiItems.ts';
import { uiMaybeLocalizeItemName } from '../ui/i18n.ts';
import type { GameRuntime } from '../types/game.js';

export const SHINY_CHARM_ITEM_KEY = 'shiny_charm_30m';
const SHINY_BOOST_TYPE = 'shiny';

export interface ShinyCharmCombatIndicator {
  visible: boolean;
  spriteUrl: string;
  spriteAlt: string;
  tooltipTitle: string;
  tooltipBody: string;
}

export const EMPTY_SHINY_CHARM_COMBAT_INDICATOR: ShinyCharmCombatIndicator = {
  visible: false,
  spriteUrl: '',
  spriteAlt: '',
  tooltipTitle: '',
  tooltipBody: '',
};

const indicatorListeners = new Set<() => void>();

export function subscribeShinyCharmIndicatorChanged(listener: () => void): () => void {
  indicatorListeners.add(listener);
  return () => indicatorListeners.delete(listener);
}

export function notifyShinyCharmIndicatorChanged(): void {
  indicatorListeners.forEach((listener) => listener());
}

function itemDisplayName(game: GameRuntime, itemKey: string): string {
  const itemDef = getAllItem(itemKey);
  const fallback = itemDef?.name ?? 'Charme Chroma (30 min)';
  if (typeof game.getLocalizedItemName === 'function') {
    return game.getLocalizedItemName(itemKey, fallback, itemDef ?? undefined);
  }
  return uiMaybeLocalizeItemName(game, itemDef, itemKey, fallback);
}

function boostTimeLeftLabel(game: GameRuntime, remainingMs: number): string {
  const time = formatBoostTimeLeft(remainingMs, {
    minuteShort: game.t?.('offline.minuteShort') ?? 'min',
    secondShort: game.t?.('offline.secondShort') ?? 's',
  });
  return game.t?.('combatUi.shinyCharmTimeLeft', { time })
    ?? `${time} restantes`;
}

export function buildShinyCharmCombatIndicator(
  game: GameRuntime,
  now = Date.now(),
): ShinyCharmCombatIndicator {
  const itemDef = getAllItem(SHINY_CHARM_ITEM_KEY);
  const spriteUrl = itemDef?.img ?? '';
  const spriteAlt = itemDisplayName(game, SHINY_CHARM_ITEM_KEY);

  const boost = (game.activeBoosts || []).find(
    (entry) => entry?.type === SHINY_BOOST_TYPE && Number(entry.endTime) > now,
  );
  if (!boost) {
    return { ...EMPTY_SHINY_CHARM_COMBAT_INDICATOR };
  }

  const remainingMs = Math.max(0, Number(boost.endTime) - now);
  return {
    visible: true,
    spriteUrl,
    spriteAlt,
    tooltipTitle: spriteAlt,
    tooltipBody: boostTimeLeftLabel(game, remainingMs),
  };
}

export function activeShinyBoostExpired(boost: { type?: string }): boolean {
  return boost?.type === SHINY_BOOST_TYPE;
}
