/// <reference types="svelte" />
/**
 * Store: shop — ShopPanel sub-tabs (mart section isolated from upgrades/recycler)
 */

import { facade } from '@bus/facade';
import { GameEventType as Evt } from '../bus/events.js';
import type { ShopMartSnapshot, ShopPanelUiSnapshot, ShopSnapshot } from '../bus/snapshots.js';
import { captureUiScrollPositions, restoreUiScrollPositions } from '../lib/uiScrollPreserve.ts';
import { pickShopMart, shopMartTimerWouldChange, shopMartWouldChange, shopUiWouldChange } from './shopSnapshotDiff.js';

const EMPTY_MART: ShopMartSnapshot = {
  martHtml: '',
  martMoney: '0',
  martOfferTimer: '—',
  martOfferTimerLabel: '',
  autoPurchaseButtonLabel: 'Auto-Purchase',
  offers: [],
  martEmptyMessage: null,
};

const EMPTY_UI: ShopPanelUiSnapshot = {
  language: 'fr',
  subTabsAriaLabel: 'Sous-sections boutique',
  subGrocery: 'Epicerie',
  subUpgrades: 'Améliorations',
  subTokens: 'Boutique Jetons',
  subTower: 'Boutique Tour',
  subSubway: 'Boutique Subway',
  subRecycler: 'Recycleur',
  martTitle: 'PokeMart',
  walletLabel: 'Porte-monnaie :',
  upgradesTitle: 'Améliorations',
  specialTitle: 'Boutique Spéciale',
  tokensUnit: 'Jetons',
  towerTitle: 'Boutique de la Tour',
  towerDesc: 'Utilisez vos Marques du Triomphe pour acheter des améliorations uniques.',
  subwayTitle: 'Boutique Subway',
  subwayDesc: 'Trois objets tenus exclusifs au Battle Subway — introuvables ailleurs.',
  subwayBpLabel: 'Points Subway :',
  recyclerTotal: 'Total :',
  recyclerEssenceLabel: "Poussière d'essence",
  recyclerShardsTitle: 'Vos Shards',
  recyclerDustShopTitle: 'Boutique de Poussière',
  recyclerSearchPlaceholder: 'Rechercher une famille...',
  recyclerSortRarity: 'Rareté',
  recyclerSortCount: 'Quantité',
};

class ShopStore {
  ui: ShopPanelUiSnapshot = $state(EMPTY_UI);
  mart: ShopMartSnapshot = $state(EMPTY_MART);
  upgradesHtml = $state('');
  tokenShopHtml = $state('');
  questTokens = $state('0');
  towerShopHtml = $state('');
  subwayShopVisible = $state(false);
  subwayShopOffers = $state<ShopSnapshot['subwayShopOffers']>([]);
  subwayShopDesc = $state('');
  subwayBP = $state('0');
  recyclerShards = $state<ShopSnapshot['recyclerShards']>([]);
  recyclerDustOffers = $state<ShopSnapshot['recyclerDustOffers']>([]);
  recyclerShardsEmpty = $state<string | null>(null);
  essenceDust = $state('0');
  recyclerSortRarityActive = $state(true);
  recyclerSortCountActive = $state(false);

  get snapshot(): ShopSnapshot {
    return {
      ui: this.ui,
      ...this.mart,
      upgradesHtml: this.upgradesHtml,
      tokenShopHtml: this.tokenShopHtml,
      questTokens: this.questTokens,
      towerShopHtml: this.towerShopHtml,
      subwayShopVisible: this.subwayShopVisible,
      subwayShopOffers: this.subwayShopOffers,
      subwayShopDesc: this.subwayShopDesc,
      subwayBP: this.subwayBP,
      recyclerShards: this.recyclerShards,
      recyclerDustOffers: this.recyclerDustOffers,
      recyclerShardsEmpty: this.recyclerShardsEmpty,
      essenceDust: this.essenceDust,
      recyclerSortRarityActive: this.recyclerSortRarityActive,
      recyclerSortCountActive: this.recyclerSortCountActive,
    };
  }
}

export const shop = new ShopStore();

function applyShopSnapshot(next: ShopSnapshot): void {
  if (shopUiWouldChange(shop.ui, next.ui)) {
    shop.ui = next.ui;
  }
  const nextMart = pickShopMart(next);
  if (shopMartWouldChange(shop.mart, nextMart)) {
    if (
      shopMartTimerWouldChange(shop.mart, nextMart)
      && shop.mart.martHtml === nextMart.martHtml
      && shop.mart.martMoney === nextMart.martMoney
    ) {
      shop.mart.martOfferTimer = nextMart.martOfferTimer;
      shop.mart.martOfferTimerLabel = nextMart.martOfferTimerLabel;
    } else {
      shop.mart = nextMart;
    }
  }
  if (shop.upgradesHtml !== next.upgradesHtml) shop.upgradesHtml = next.upgradesHtml;
  if (shop.tokenShopHtml !== next.tokenShopHtml) shop.tokenShopHtml = next.tokenShopHtml;
  if (shop.questTokens !== next.questTokens) shop.questTokens = next.questTokens;
  if (shop.towerShopHtml !== next.towerShopHtml) shop.towerShopHtml = next.towerShopHtml;
  if (shop.subwayShopVisible !== next.subwayShopVisible) shop.subwayShopVisible = next.subwayShopVisible;
  if (shop.subwayShopOffers !== next.subwayShopOffers) shop.subwayShopOffers = next.subwayShopOffers;
  if (shop.subwayShopDesc !== next.subwayShopDesc) shop.subwayShopDesc = next.subwayShopDesc;
  if (shop.subwayBP !== next.subwayBP) shop.subwayBP = next.subwayBP;
  if (shop.recyclerShards !== next.recyclerShards) shop.recyclerShards = next.recyclerShards;
  if (shop.recyclerDustOffers !== next.recyclerDustOffers) shop.recyclerDustOffers = next.recyclerDustOffers;
  if (shop.recyclerShardsEmpty !== next.recyclerShardsEmpty) {
    shop.recyclerShardsEmpty = next.recyclerShardsEmpty;
  }
  if (shop.essenceDust !== next.essenceDust) shop.essenceDust = next.essenceDust;
  if (shop.recyclerSortRarityActive !== next.recyclerSortRarityActive) {
    shop.recyclerSortRarityActive = next.recyclerSortRarityActive;
  }
  if (shop.recyclerSortCountActive !== next.recyclerSortCountActive) {
    shop.recyclerSortCountActive = next.recyclerSortCountActive;
  }
}

facade.subscribe(Evt.SHOP_CHANGED, (evt) => {
  if (!('shop' in evt)) return;
  const scrollSaved = captureUiScrollPositions();
  applyShopSnapshot(evt.shop);
  restoreUiScrollPositions(scrollSaved);
});
