import { EVOLUTIONS } from '../../constants/evolutions.ts';
import { coerceStr } from './coerceStr.ts';

export interface PokedexEvolutionRow {
    from?: string;
    to?: string;
    detail: string;
}

function summarizeEvolutionBranch(branch: Record<string, unknown> | null | undefined): string {
    if (!branch) return '';
    const lv = branch.level;
    const lvNum = Number(lv);
    if (Number.isFinite(lvNum) && lvNum > 0) return 'Lv.' + lvNum;
    if (branch.conditionItem) return coerceStr(branch.conditionItem, '');
    if (branch.condition) return coerceStr(branch.condition, '');
    return '';
}

function dedupeEvolutionRows<T extends { detail: string }>(
    list: T[],
    keyFn: (row: T) => string,
): T[] {
    const uniq: Record<string, boolean> = {};
    const deduped: T[] = [];
    list.forEach((row) => {
        const k = keyFn(row);
        if (uniq[k]) return;
        uniq[k] = true;
        deduped.push(row);
    });
    return deduped;
}

/** Parents directs dans EVOLUTIONS dont la cible est speciesName. */
export function collectEvolutionParentsForSpecies(speciesName: string): Array<{ from: string; detail: string }> {
    const list: Array<{ from: string; detail: string }> = [];
    if (!speciesName) return list;

    const evoObj = EVOLUTIONS as Record<string, Record<string, unknown>>;
    Object.keys(evoObj).forEach((from) => {
        const def = evoObj[from];
        if (!def) return;

        const pushIfTarget = (
            targetName: string | null | undefined,
            branch: Record<string, unknown> | null | undefined,
        ): void => {
            if (targetName !== speciesName) return;
            const detail = summarizeEvolutionBranch(branch || def);
            list.push({ from: String(from), detail });
        };

        if (def.evolves_to) pushIfTarget(coerceStr(def.evolves_to, ''), def);

        if (Array.isArray(def.options)) {
            for (const opt of def.options as Record<string, unknown>[]) {
                if (opt?.evolves_to) pushIfTarget(coerceStr(opt.evolves_to, ''), opt);
            }
        }
    });

    return dedupeEvolutionRows(list, (row) => row.from + '|' + row.detail);
}

/** Enfants directs dans EVOLUTIONS depuis speciesName. */
export function collectEvolutionChildrenForSpecies(speciesName: string): Array<{ to: string; detail: string }> {
    const list: Array<{ to: string; detail: string }> = [];
    if (!speciesName) return list;

    const def = (EVOLUTIONS as Record<string, Record<string, unknown>>)[speciesName];
    if (!def) return list;

    const pushTarget = (
        targetName: string | null | undefined,
        branch: Record<string, unknown> | null | undefined,
    ): void => {
        const to = coerceStr(targetName, '');
        if (!to) return;
        const detail = summarizeEvolutionBranch(branch || def);
        list.push({ to, detail });
    };

    if (def.evolves_to) pushTarget(coerceStr(def.evolves_to, ''), def);

    if (Array.isArray(def.options)) {
        for (const opt of def.options as Record<string, unknown>[]) {
            if (opt?.evolves_to) pushTarget(coerceStr(opt.evolves_to, ''), opt);
        }
    }

    return dedupeEvolutionRows(list, (row) => row.to + '|' + row.detail);
}
