/** Map generated zone pokemon entries into runtime ZONE_POKEMON rows. */

export type TaggedZonePokemonEntry = {
    name: string;
    weight: number;
    channel?: 'land' | 'water' | 'fishing';
    excludeFromZoneMastery?: boolean;
};

export function mapTaggedZonePoolEntry(entry: TaggedZonePokemonEntry): Record<string, unknown> {
    const row: Record<string, unknown> = {
        name: entry.name,
        weight: Math.max(1, Number(entry.weight) || 1),
    };
    if (entry.channel === 'land' || entry.channel === 'water' || entry.channel === 'fishing') {
        row.channel = entry.channel;
    }
    if (entry.excludeFromZoneMastery === true) {
        row.excludeFromZoneMastery = true;
    }
    return row;
}

export function mapTaggedZonePool(pool: TaggedZonePokemonEntry[]): unknown[] {
    return pool.map(mapTaggedZonePoolEntry);
}
