  periodText: string;
  mainRows: FarmingMetricRow[];
  avgVisible: boolean;
  avgTitle: string;
  avgRows: FarmingMetricRow[];
  dryVisible: boolean;
  dryTitle: string;
  dryRows: FarmingMetricRow[];
  revenueVisible: boolean;
  revenueTitle: string;
  donutSlices: FarmingDonutSlice[];
  topItemsVisible: boolean;
  topItemsTitle: string;
  topItems: FarmingTopItem[];
  timelineVisible: boolean;
  timelineTitle: string;
  timeline: FarmingTimelineSnapshot | null;
  estimationMode: 'forward' | 'goal';
  estimationModeLabel: string;
  estimationModeForwardLabel: string;
  estimationModeGoalLabel: string;
  goalLabel: string;
  sessionNamePlaceholder: string;
  deleteSessionTitle: string;
  estimationLabelHtml: string;
  estimationOptions: Array<{ value: string; label: string }>;
  estimationSelectedMin: number;
  estimationTooltipHtml: string;
  itemOptions: Array<{ value: string; label: string }>;
  selectedItemKey: string;
  goalMetric: string;
  goalAmount: number;
  goalResultHtml: string;
  goalOptions: Array<{ value: string; label: string }>;
  sessionsTitle: string;
  sessionsSaveLabel: string;
  sessionsEmpty: string;
  sessions: FarmingSessionRow[];
