function fmT(
  game: GameRuntime,
  key: string,
  fr: string,
  en: string,
): string {
  const lang = (game && game.normalizeLanguage && game.normalizeLanguage(game.language)) || 'fr';
  if (game.t) {
    const got = game.t('farmingMetrics.' + key);
    if (got && got !== 'farmingMetrics.' + key) return got;
  }
  return lang === 'en' ? en : fr;
}

function fmFormatDuration(sec: number): string {
  sec = Math.max(0, Math.round(sec));
  if (sec < 60) return sec + ' s';
  const min = Math.floor(sec / 60);
  const rem = sec % 60;
  if (min < 60) return min + ' min' + (rem > 0 ? ' ' + rem + ' s' : '');
  const h = Math.floor(min / 60);
  const mRest = min % 60;
  return h + ' h' + (mRest > 0 ? ' ' + mRest + ' min' : '');
}

function getItemMeta(
  game: GameRuntime,
  key: string,
): { name: string; icon: string; img: string } {
  const items = ALL_ITEMS as Record<string, Record<string, unknown>>;
  const def = items[key];
  const name =
    def && def.name
      ? (game.getLocalizedItemName
          ? game.getLocalizedItemName(key, def.name as string, def)
          : def.name)
      : key;
  const icon = def && def.icon ? String(def.icon) : '📦';
  const img = def && def.img ? String(def.img) : '';
  return { name: name as string, icon, img };
}

