/**
 * Phase 6.6 — Bridge for EggHatchModal lifecycle.
 * Replaces globalThis.__showEggHatchModal / __closeEggHatchModal
 * with explicit module-level bindings.
 *
 * Usage:
 *   - EggHatchModal.svelte calls setShow/SetClose at top level.
 *   - gameEggSystem.ts calls showEggHatch() / closeEggHatch().
 */

import { awaitLazyModalReady } from '../lib/lazyModalMounts.ts';

type ShowFn = (html: string, options?: Record<string, unknown>) => void;
type CloseFn = () => void;

let _show: ShowFn | null = null;
let _close: CloseFn | null = null;
let _pendingHtml: string | null = null;
let _pendingOptions: Record<string, unknown> | undefined;

function flushPendingEggHatchShow(): void {
  if (!_show || _pendingHtml === null) return;
  const html = _pendingHtml;
  const options = _pendingOptions;
  _pendingHtml = null;
  _pendingOptions = undefined;
  _show(html, options);
}

export function setShow(fn: ShowFn): void {
  _show = fn;
  flushPendingEggHatchShow();
}
export function setClose(fn: CloseFn): void { _close = fn; }

export async function showEggHatch(html: string, options?: Record<string, unknown>): Promise<void> {
  await awaitLazyModalReady('eggHatchModal');
  if (_show) {
    _show(html, options);
  } else {
    _pendingHtml = html;
    _pendingOptions = options;
  }
}

export function closeEggHatch(): void {
  _close?.();
}

/** @internal Vitest only */
export function _resetEggHatchBridgeForTests(): void {
  _show = null;
  _close = null;
  _pendingHtml = null;
  _pendingOptions = undefined;
}

// Phase 6.6 — keep legacy globalThis aliases for gameEggSystem.ts (which is @ts-nocheck).
// Remove these when gameEggSystem.ts is typed and imports the bridge directly.
if (typeof globalThis !== 'undefined') {
  (globalThis as Record<string, unknown>).__showEggHatchModal = showEggHatch;
  (globalThis as Record<string, unknown>).__closeEggHatchModal = closeEggHatch;
}
