/**
 * @file gameTalentSystem.ts
 * Talent/passive talent subsystem -- extracted from game.js.
 * Loaded AFTER game.js, extends Game.prototype via mixin.
 * Phase 5.4 — @ts-nocheck removed.
 */

import { ALL_ITEMS } from './constants/balance/shopAndAggregation.js';
import { PASSIVE_TALENTS, LEGENDARY_TALENTS, EPIC_TALENTS } from './constants/balance/talentsAndCombat.js';
import type { GameRuntime } from './src/types/game.js';
import { logMessage } from './src/ui/modals.ts';
import { getPokemonSpriteUrl } from './src/ui/utils.ts';
import { RARITY } from './constants/core.ts';
import { debugError } from './formatters.ts';
import { refreshOpenCreatureModalIfVisible } from './src/lib/refreshOpenCreatureModal.ts';

type GameCtor = { prototype: Record<string, unknown> };
type ThisGame = GameRuntime;

export function applyTalentSystem(GameClass: GameCtor): void {

    GameClass.prototype.useTalentReroll = function (this: ThisGame, creatureIndex: number, location: string) {
        if (this.talentRerolls <= 0) {
            logMessage(this.t('log.talentNoPill'));
            return false;
        }

        let creature;
        if (location === 'team') creature = this.playerTeam[creatureIndex];
        else if (location === 'storage') creature = this.storage[creatureIndex];
        else if (location === 'pension') creature = this.pension[creatureIndex];

        if (!creature) {
            debugError("Créature introuvable !");
            return false;
        }

        if (creature.rarity !== RARITY.EPIC && creature.rarity !== RARITY.LEGENDARY) {
            logMessage(this.t('log.talentRarityOnly'));
            return false;
        }

        if (!creature.passiveTalent) return false;

        const oldTalent = creature.passiveTalent;
        const oldTalentInfo = (PASSIVE_TALENTS as Record<string, Record<string, unknown>>)[oldTalent];

        let talentPool = creature.rarity === RARITY.LEGENDARY ? LEGENDARY_TALENTS : EPIC_TALENTS;
        if (creature.isEnemy && Array.isArray(talentPool)) {
            talentPool = talentPool.filter(t => t !== 'robustesse');
            if (talentPool.length === 0) talentPool = creature.rarity === RARITY.LEGENDARY ? LEGENDARY_TALENTS : EPIC_TALENTS;
        }
        if (!Array.isArray(talentPool) || !talentPool.some(t => t !== oldTalent)) {
            logMessage(this.t('log.talentRerollNoAlternative'));
            return false;
        }

        let attempts = 0;
        do {
            creature.assignRandomTalent!();
            attempts++;
        } while (creature.passiveTalent === oldTalent && attempts < 20);

        this.talentRerolls--;
        this.syncTalentConsumablesInInventory();

        const saveChance = this.getMasteryBonus ? (this.getMasteryBonus('talent_reroll_save_chance') || 0) : 0;
        if (saveChance > 0 && Math.random() < saveChance) {
            this.talentRerolls++;
            this.syncTalentConsumablesInInventory();
            logMessage(this.t('log.talentRerollSaved'));
        }

        const oldTalentName = this.getLocalizedPassiveTalentName(oldTalent, oldTalentInfo ? (oldTalentInfo).name as string : oldTalent);
        const newTalentInfo = (PASSIVE_TALENTS as Record<string, Record<string, unknown>>)[creature.passiveTalent];
        const newTalentName = this.getLocalizedPassiveTalentName(creature.passiveTalent, newTalentInfo ? (newTalentInfo).name as string : creature.passiveTalent);
        logMessage(this.t('log.talentChanged', { name: creature.name, old: oldTalentName, next: newTalentName }));

        if (creature.recalculateStats) creature.recalculateStats();
        this.calculateTeamStats();
        this.uiDirty = true;
        this.updateDisplay(['team', 'items', 'statBoosts', 'boosts']);
        refreshOpenCreatureModalIfVisible(this);

        this.showTalentChangeJuice(creature, oldTalent, creature.passiveTalent, creatureIndex, location);
        if (typeof this.checkSpecialQuests === 'function') this.checkSpecialQuests('talent_reset');
        return true;
    };

    GameClass.prototype.handleTalentSpriteClick = function (this: ThisGame, creatureIndex: number, location: string) {
        location = location || 'team';
        const creature = this.getCreatureByLocation(location, creatureIndex);
        if (!creature) {
            logMessage(this.t('log.creatureNotFound'));
            return false;
        }

        if (!creature.passiveTalent) {
            logMessage(this.t('log.talentNoPassive', { name: creature.name }));
            return false;
        }

        if (creature.rarity !== RARITY.EPIC && creature.rarity !== RARITY.LEGENDARY) {
            logMessage(this.t('log.talentRarityOnly'));
            return false;
        }

        const hasReroll = (this.talentRerolls || 0) > 0;
        const hasChoice = (this.talentChoices || 0) > 0;

        if (!hasReroll && !hasChoice) {
            logMessage(this.t('log.talentNoConsumable'));
            return false;
        }

        if (hasReroll && hasChoice) {
            this.openTalentActionPickerModal(creature, creatureIndex, location);
            return true;
        }

        if (hasChoice) {
            return this.useTalentChoice(creatureIndex, location);
        }

        return this.useTalentReroll(creatureIndex, location);
    };

    GameClass.prototype.openTalentActionPickerModal = function (this: ThisGame, creature: Record<string, unknown>, creatureIndex: number, location: string) {
        const modal = document.createElement('div');
        modal.className = 'talent-action-modal';
        modal.setAttribute('data-talent-action-modal', '1');

        const content = document.createElement('div');
        content.className = 'talent-action-modal-content';

        const allItems = (typeof ALL_ITEMS !== 'undefined')
            ? (ALL_ITEMS as Record<string, Record<string, unknown>>)
            : undefined;
        const talentRerollItem = allItems?.talent_reroll;
        const talentChoiceItem = allItems?.talent_choice;

        const piluleImg = talentRerollItem?.img
            ? String(talentRerollItem.img)
            : 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/ability-capsule.png';
        const patchImg = talentChoiceItem?.img
            ? String(talentChoiceItem.img)
            : 'img/ability-patch.png';
        const piluleName = talentRerollItem?.name
            ? String(talentRerollItem.name)
            : this.t('modal.talentPillName');
        const patchName = talentChoiceItem?.name
            ? String(talentChoiceItem.name)
            : this.t('modal.talentPatchName');
        const piluleDesc = talentRerollItem?.description
            ? String(talentRerollItem.description).replace(/\\/g, '\\\\').replace(/'/g, "\\'")
            : this.t('modal.talentPillDesc');
        const patchDesc = talentChoiceItem?.description
            ? String(talentChoiceItem.description).replace(/\\/g, '\\\\').replace(/'/g, "\\'")
            : this.t('modal.talentPatchDesc');
        const safePiluleName = String(piluleName).replace(/'/g, "\\'");
        const safePatchName = String(patchName).replace(/'/g, "\\'");
        const creatureDisplayName = this.getLocalizedPokemonName(creature.name as string);

        const closeModal = () => {
            if (modal.parentNode) modal.parentNode.removeChild(modal);
        };

        content.innerHTML = `
            <div class="talent-action-title">${this.t('modal.talentActionTitle')}</div>
            <div class="talent-action-subtitle">${creatureDisplayName}</div>
            <div class="talent-action-grid">
                <button type="button" class="talent-action-slot" onmouseenter="game.scheduleTooltip(event, '${safePiluleName}', '${piluleDesc}')" onmouseleave="game.hideTooltip()" data-action="useTalentReroll" data-arg="${creatureIndex}" data-arg2="${location}">
                    <div class="talent-action-icon"><img src="${piluleImg}" alt="${piluleName}"></div>
                    <div class="talent-action-count">${this.talentRerolls || 0}</div>
                    <div class="talent-action-name">${piluleName}</div>
                </button>
                <button type="button" class="talent-action-slot" onmouseenter="game.scheduleTooltip(event, '${safePatchName}', '${patchDesc}')" onmouseleave="game.hideTooltip()" data-action="useTalentChoice" data-arg="${creatureIndex}" data-arg2="${location}">
                    <div class="talent-action-icon"><img src="${patchImg}" alt="${patchName}"></div>
                    <div class="talent-action-count">${this.talentChoices || 0}</div>
                    <div class="talent-action-name">${patchName}</div>
                </button>
            </div>
            <button type="button" class="talent-action-cancel" data-action="removeTalentActionModal">${this.t('modal.cancel')}</button>
        `;

        modal.appendChild(content);
        modal.addEventListener('click', (e) => {
            if (e.target === modal) closeModal();
        });
        document.body.appendChild(modal);
    };

    GameClass.prototype.showTalentChangeJuice = function (this: ThisGame, creature: Record<string, unknown>, oldTalentKey: string, newTalentKey: string, creatureIndex: number, location: string) {
        const newTalentInfo = (PASSIVE_TALENTS as Record<string, Record<string, unknown>>)[newTalentKey];
        const newTalentName = this.getLocalizedPassiveTalentName(newTalentKey, newTalentInfo ? (newTalentInfo).name as string : newTalentKey);
        const spriteUrl = getPokemonSpriteUrl(creature.name as string, creature.isShiny as boolean, false);
        const creatureDisplayName = this.getLocalizedPokemonName(creature.name as string);

        const overlay = document.createElement('div');
        overlay.className = 'talent-change-juice';

        const particlesHTML = '<span class="egg-particle"></span><span class="egg-particle"></span><span class="egg-particle"></span><span class="egg-particle"></span>' +
            '<span class="egg-particle"></span><span class="egg-particle"></span><span class="egg-particle"></span><span class="egg-particle"></span>';

        const card = document.createElement('div');
        card.className = 'talent-change-juice-card';
        card.innerHTML = `
            <div class="talent-juice-particles" aria-hidden="true">${particlesHTML}</div>
            <div class="stats-header talent-change-juice-modal-header">
                <h2>${this.t('modal.newTalentLabel')}</h2>
            </div>
            <img src="${spriteUrl}" alt="${creatureDisplayName}" class="talent-juice-sprite">
            <div class="talent-juice-name">${creatureDisplayName}</div>
            <div class="talent-juice-talent-name">${newTalentName}</div>
            <button type="button" class="btn-talent-juice-close">${this.t('modal.confirm')}</button>
        `;

        const closeJuice = () => {
            if (!overlay.parentNode) return;
            overlay.parentNode.removeChild(overlay);
            this.updateDisplay(['team', 'items', 'statBoosts', 'boosts']);
            this.showCreatureModal(creatureIndex, location);
        };

        card.querySelector('.btn-talent-juice-close')!.addEventListener('click', closeJuice);
        overlay.addEventListener('click', (e) => { if (e.target === overlay) closeJuice(); });
        overlay.appendChild(card);
        document.body.appendChild(overlay);

        setTimeout(closeJuice, 4000);
    };

    GameClass.prototype.useTalentChoice = function (this: ThisGame, creatureIndex: number, location: string) {
        location = location || 'team';
        if (this.talentChoices <= 0) {
            logMessage(this.t('log.talentNoOrb'));
            return false;
        }

        const creature = this.getCreatureByLocation(location, creatureIndex);

        if (!creature) {
            logMessage(this.t('log.creatureNotFound'));
            return false;
        }

        if (creature.rarity !== RARITY.EPIC && creature.rarity !== RARITY.LEGENDARY) {
            logMessage(this.t('log.talentRarityOnly'));
            return false;
        }

        if (!creature.passiveTalent) {
            logMessage(this.t('log.talentNoPassive', { name: creature.name }));
            return false;
        }

        this.openTalentChoiceModal(creature, creatureIndex, location);
        return true;
    };

    GameClass.prototype.openTalentChoiceModal = function (this: ThisGame, creature: Record<string, unknown>, creatureIndex: number, location: string) {
        const modal = document.createElement('div');
        modal.className = 'talent-choice-modal';
        modal.setAttribute('data-talent-choice-modal', '1');

        const content = document.createElement('div');
        content.className = 'talent-choice-modal-content';

        const currentTalentInfo = (PASSIVE_TALENTS as Record<string, Record<string, unknown>>)[creature.passiveTalent as string];
        const currentName = this.getLocalizedPassiveTalentName(
            creature.passiveTalent as string,
            currentTalentInfo ? (currentTalentInfo).name as string : creature.passiveTalent as string
        );
        const creatureDisplayName = this.getLocalizedPokemonName(creature.name as string);
        const isEpicCreature = creature.rarity === RARITY.EPIC;
        const safeLoc = (location || 'team').replace(/'/g, "\\'");

        const epicTalents: string[] = [];
        const legendaryTalents: string[] = [];
        for (const talentKey of Object.keys(PASSIVE_TALENTS)) {
            const entry = (PASSIVE_TALENTS as Record<string, Record<string, unknown>>)[talentKey];
            if (!entry) continue;
            if (entry.rarity === RARITY.LEGENDARY) legendaryTalents.push(talentKey);
            else if (entry.rarity === RARITY.EPIC) epicTalents.push(talentKey);
        }

        const renderTalentItem = (talentKey: string, locked: boolean): string => {
            const talent = (PASSIVE_TALENTS as Record<string, Record<string, unknown>>)[talentKey];
            if (!talent) return '';
            const isCurrent = talentKey === creature.passiveTalent;
            const rarityClass = talent.rarity === RARITY.LEGENDARY ? 'rarity-legendary' : 'rarity-epic';
            const talentName = this.getLocalizedPassiveTalentName(talentKey, (talent).name as string);
            const talentDesc = this.getLocalizedPassiveTalentDescription(talentKey, (talent).description as string);
            const safeKey = talentKey.replace(/'/g, "\\'");
            const stateClass = isCurrent ? 'current' : locked ? 'locked' : '';
            const disabled = isCurrent || locked;
            const actionAttrs = disabled
                ? ''
                : `data-action="closeTalentChoiceAndApply" data-arg="${safeKey}" data-arg2="${creatureIndex}" data-arg3="${safeLoc}"`;
            return `
            <button type="button" class="talent-choice-item ${stateClass}" ${disabled ? 'disabled' : ''} ${actionAttrs}>
                <div class="talent-choice-item-name ${rarityClass}">${talentName}</div>
                <div class="talent-choice-item-desc">${talentDesc}</div>
            </button>`;
        };

        const renderSection = (title: string, talentKeys: string[], locked: boolean): string => {
            if (talentKeys.length === 0) return '';
            const items = talentKeys.map(key => renderTalentItem(key, locked)).join('');
            return `
            <div class="talent-choice-section">
                <div class="talent-choice-section-title">${title}</div>
                <div class="talent-choice-list">${items}</div>
            </div>`;
        };

        const listHTML =
            renderSection(this.getRarityLabel(RARITY.EPIC), epicTalents, false)
            + renderSection(this.getRarityLabel(RARITY.LEGENDARY), legendaryTalents, isEpicCreature);

        content.innerHTML = `
            <div class="talent-choice-title">${this.t('modal.talentChoiceTitle')}</div>
            <div class="talent-choice-subtitle">${creatureDisplayName}</div>
            <div class="talent-choice-current">${this.t('modal.talentCurrent', { name: currentName })}</div>
            ${listHTML}
            <button type="button" class="btn-talent-choice-cancel" data-action="closeTalentChoiceModal">${this.t('modal.cancel')}</button>
        `;

        modal.appendChild(content);
        modal.addEventListener('click', (e) => {
            if (e.target === modal) modal.remove();
        });
        document.body.appendChild(modal);
    };

    GameClass.prototype.applyTalentChoice = function (this: ThisGame, talentKey: string, creatureIndex: number, location: string) {
        location = location || 'team';
        const creature = this.getCreatureByLocation(location, creatureIndex);
        if (!creature) {
            logMessage(this.t('log.creatureNotFound'));
            return false;
        }

        const chosenTalentInfo = (PASSIVE_TALENTS as Record<string, Record<string, unknown>>)[talentKey];
        if (creature.rarity === RARITY.EPIC && chosenTalentInfo?.rarity === RARITY.LEGENDARY) {
            logMessage(this.t('log.talentRarityOnly'));
            return false;
        }

        const oldTalent = creature.passiveTalent;
        const oldTalentInfo = (PASSIVE_TALENTS as Record<string, Record<string, unknown>>)[oldTalent as string];

        creature.passiveTalent = talentKey;
        this.talentChoices--;
        this.syncTalentConsumablesInInventory();

        const newTalentInfo = (PASSIVE_TALENTS as Record<string, Record<string, unknown>>)[talentKey];
        const oldTalentName = this.getLocalizedPassiveTalentName(oldTalent as string, oldTalentInfo ? (oldTalentInfo).name as string : oldTalent as string);
        const newTalentName = this.getLocalizedPassiveTalentName(talentKey, newTalentInfo ? (newTalentInfo).name as string : talentKey);
        const newTalentDesc = this.getLocalizedPassiveTalentDescription(talentKey, newTalentInfo ? (newTalentInfo).description as string : '');
        logMessage(this.t('log.talentChanged', { name: creature.name, old: oldTalentName, next: newTalentName }));

        logMessage(this.t('log.raw', { value: newTalentDesc }));
        if (creature.recalculateStats) creature.recalculateStats();
        this.calculateTeamStats();
        this.updateDisplay(['team', 'items', 'statBoosts', 'boosts']);
        refreshOpenCreatureModalIfVisible(this);
        this.showTalentChangeJuice(creature, oldTalent as string, talentKey, creatureIndex, location);
        return true;
    };
}
