<script lang="ts">
  import type { CreatureSnapshot, StorageCardSnapshot } from '../bus/snapshots.js';
  import { game } from '../../gameManager.js';
  import { bindTouchDragToCreatureCard } from '../ui/teamDisplay.ts';
  import { isMobileViewport } from '../ui/breakpoints.ts';
  import { getHeldItem } from '../ui/uiItems.ts';
  import { getLocalizedHeldItemLabel, uiText } from '../ui/i18n.ts';
  import { touchTooltipHandlers, showGameTooltip, hideGameTooltip } from '../ui/scheduleTooltipHelpers.ts';
  import {
    computeUltimateSlotTransferBonus,
    computeStorageUltimateSlotBonusTotalMaximum,
    formatUltimateSlotPickTooltipBody,
    type UltimateSlotStatBlock,
  } from '../lib/ultimateSlotPreview.ts';
  import type { GameRuntime } from '../types/game.js';
  import { GEN5_SUBSTITUTE_SPRITE, getStaticFallbackFromAnimatedUrl } from '../ui/utils.ts';
  import { stableImgSrc } from '../lib/stableImgSrc.js';
  import { PRESTIGE_STAR_IMG_URL } from '../../formatters.ts';
  let {
    creature,
    index = 0,
    location = 'team',
    animationDelaySec = 0,
    isActive = false,
    isFainted = false,
    teamSpritesOnly = false,
    /** Lighter storage card (no shard/prestige row) when grid is not in sprite-only mode. */
    storageCompact = false,
    teamContributionRatePercent = '10',
    pensionContributionLabel = '',
    labels,
    levelShort,
    viewDetails,
    pickForUltimateSlot = false,
    ultimateSlotBonusMaxima = null,
    ultimateSlotBonusTotalMax = 0,
  }: {
    creature: CreatureSnapshot | StorageCardSnapshot;
    index?: number;
    location?: 'team' | 'pension' | 'storage';
    animationDelaySec?: number;
    isActive?: boolean;
    isFainted?: boolean;
    teamSpritesOnly?: boolean;
    storageCompact?: boolean;
    teamContributionRatePercent?: string;
    pensionContributionLabel?: string;
    /** Full labels (pension/storage). Team list should pass levelShort + viewDetails only. */
    labels?: { levelShort: string; viewDetails: string };
    levelShort?: string;
    viewDetails?: string;
    pickForUltimateSlot?: boolean;
    ultimateSlotBonusMaxima?: UltimateSlotStatBlock | null;
    ultimateSlotBonusTotalMax?: number;
  } = $props();

  const levelShortLabel = $derived(levelShort ?? labels?.levelShort ?? 'Lvl');
  const viewDetailsLabel = $derived(viewDetails ?? labels?.viewDetails ?? 'View details');

  let cardEl = $state<HTMLElement | null>(null);
  let storageEntry = $derived(
    location === 'storage' ? (creature as StorageCardSnapshot) : null,
  );

  let expPercent = $derived(
    Math.max(0, Math.min(100, (creature.exp / Math.max(1, creature.expToNext)) * 100)),
  );
  let prestige = $derived(creature.prestige ?? 0);
  let hasPrestige = $derived(prestige > 0);
  let resonanceCapped = $derived(!!creature.resonanceCapped);
  let effectivePrestige = $derived(creature.effectivePrestige);
  let effectiveLevel = $derived(creature.effectiveLevel);
  let anchorCatchUpXpMult = $derived(creature.anchorCatchUpXpMult ?? 1);
  let anchorCatchUp = $derived(anchorCatchUpXpMult > 1);
  let anchorCatchUpXpPct = $derived(Math.round((anchorCatchUpXpMult - 1) * 100));
  let anchorBoostLabel = $derived(
    uiText('resonance.anchorBoostShort', '+XP'),
  );
  let anchorBoostTooltipTitle = $derived(
    uiText('resonance.anchorBoostTooltipTitle', 'Région boost'),
  );
  let anchorBoostTooltipBody = $derived(
    uiText(
      'resonance.anchorBoostTooltipBody',
      "+{pct}% XP gagnée · −1 pierre de prestige au prestige",
      { pct: anchorCatchUpXpPct },
    ),
  );
  let favoriteBadgeTitle = $derived(
    uiText('modal.creature.favoriteBadge', 'Favori', {}, game),
  );
  let resonanceTrueStatsAria = $derived(
    uiText('resonance.trueStatsAria', 'Stats réelles : niveau {level}, prestige {prestige}', {
      level: creature.level,
      prestige,
    }),
  );
  let heldItem = $derived(creature.heldItem ? getHeldItem(creature.heldItem) : undefined);
  let heldItemLabel = $derived(
    creature.heldItem ? getLocalizedHeldItemLabel(game, creature.heldItem) : '',
  );
  let showPokerusBadge = $derived((creature.pokerusBadgeHtml ?? '').length > 0);
  let animDelay = $derived(`-${animationDelaySec.toFixed(3)}s`);

  const spriteIdentity = $derived(
    `${location}|${creature.uid}|${creature.name}|${creature.isShiny ? 1 : 0}`,
  );

  /** Snapshot sprite URL at publish time — avoids 60fps combat context races on live resolve. */
  let spriteSrc = $derived.by(() => {
    spriteIdentity;
    return creature.spriteUrl || GEN5_SUBSTITUTE_SPRITE;
  });

  function onSpriteError(e: Event) {
    const img = e.currentTarget as HTMLImageElement;
    const staticFallback = getStaticFallbackFromAnimatedUrl(img.src);
    if (staticFallback && img.src !== staticFallback) {
      img.src = staticFallback;
      return;
    }
    if (img.src !== GEN5_SUBSTITUTE_SPRITE) img.src = GEN5_SUBSTITUTE_SPRITE;
  }

  let cardClass = $derived(
    [
      'creature-card',
      `rarity-${creature.rarity}`,
      creature.isShiny ? 'shiny' : '',
      creature.isShadow ? 'shadow' : '',
      location === 'team' && isActive ? 'active' : '',
      location === 'team' && isFainted ? 'fainted' : '',
      creature.prestigeReady ? 'prestige-ready' : '',
      resonanceCapped ? 'resonance-capped-card' : '',
    ]
      .filter(Boolean)
      .join(' '),
  );

  $effect(() => {
    const el = cardEl;
    const gm = game;
    if (!el || !gm) return;
    if (pickForUltimateSlot) return;
    if (!isMobileViewport()) return;
    if (location === 'storage' && !storageEntry?.draggable) return;
    const marked = el as HTMLElement & { _touchDragBound?: boolean };
    if (marked._touchDragBound) return;
    marked._touchDragBound = true;
    bindTouchDragToCreatureCard(
      gm,
      el,
      location,
      location === 'storage' && storageEntry ? storageEntry.storageIndex : index,
    );
  });

  function onClick() {
    const gm = game;
    if (!gm || gm._touchDragJustEnded) return;
    if (pickForUltimateSlot && location === 'storage' && storageEntry?.draggable) {
      gm.moveToUltimateSlot(storageEntry.storageIndex, 'storage');
      return;
    }
    if (location === 'team') {
      requestAnimationFrame(() => gm.showCreatureModal(index, 'team'));
    } else if (location === 'pension') {
      gm.showCreatureModal(index, 'pension');
    } else if (location === 'storage' && storageEntry?.draggable) {
      gm.showCreatureModal(storageEntry.storageIndex, 'storage');
    }
  }

  function onContextMenu(e: MouseEvent) {
    if (location !== 'team') return;
    e.preventDefault();
    const gm = game;
    if (gm && creature.isAlive) gm.setActiveCreature(index);
  }

  function onDragStartTeam(e: DragEvent) {
    game?.onTeamDragStart(e, index);
  }

  function onDragStartPension(e: DragEvent) {
    game?.onPensionDragStart(e, index);
  }

  function onDragEnd(e: DragEvent) {
    game?.onCreatureDragEnd(e);
  }

  function onTeamContributionEnter(e: MouseEvent) {
    e.stopPropagation();
    game?.showTeamContributionPopover(index, e.currentTarget as HTMLElement);
  }

  function onPensionContributionEnter(e: MouseEvent) {
    e.stopPropagation();
    game?.showPensionContributionPopover(index, e.currentTarget as HTMLElement);
  }

  function onContributionLeave() {
    game?.scheduleHidePensionContributionPopover(150);
  }

  function onSpriteInfoEnter(e: MouseEvent) {
    e.stopPropagation();
    const gm = game;
    const trigger = e.currentTarget as HTMLElement;
    if (!gm || !trigger) return;
    if (location === 'team') {
      gm.showTeamContributionPopover?.(index, trigger, { dark: true });
    } else if (location === 'pension') {
      gm.showPensionContributionPopover?.(index, trigger, { dark: true });
    }
  }

  function onSpriteInfoLeave() {
    game?.scheduleHidePensionContributionPopover?.(150);
  }

  const showSpriteInfoTrigger = $derived(
    teamSpritesOnly && (location === 'team' || location === 'pension'),
  );

  function expeditionTitle(): string {
    if (!storageEntry?.isExpeditionEntry) return '';
    return uiText('storage.currentlyInExpedition', '{name} is currently on expedition', {
      name: creature.displayName,
    });
  }

  let anchorBoostHandlers = $derived(
    anchorCatchUp
      ? touchTooltipHandlers(() => ({
          title: anchorBoostTooltipTitle,
          body: anchorBoostTooltipBody,
        }))
      : null,
  );

  function onSpriteInfoTap(e: MouseEvent) {
    const gm = game;
    if (!gm?.isTouchUi?.()) return;
    e.stopPropagation();
    onSpriteInfoEnter(e);
  }

  function onUltimatePickEnter(e: MouseEvent | FocusEvent) {
    if (!pickForUltimateSlot) return;
    const gm = game as GameRuntime | null;
    const rate = typeof gm?.getUltimateSlotTransferRate === 'function'
      ? gm.getUltimateSlotTransferRate()
      : 0.01;
    const bonus = computeUltimateSlotTransferBonus(creature, rate);
    const title = uiText('ultimateSlot.bonusPerMember', 'Bonus par membre d\'équipe');
    const totalMax = ultimateSlotBonusTotalMax > 0
      ? ultimateSlotBonusTotalMax
      : (gm ? computeStorageUltimateSlotBonusTotalMaximum(gm, rate) : 0);
    const body = formatUltimateSlotPickTooltipBody(bonus, ultimateSlotBonusMaxima, totalMax);
    showGameTooltip(e, title, body);
  }

  function onUltimatePickLeave() {
    if (!pickForUltimateSlot) return;
    hideGameTooltip();
  }
</script>

<!-- svelte-ignore a11y_click_events_have_key_events -->
<!-- svelte-ignore a11y_no_static_element_interactions -->
<div
  bind:this={cardEl}
  class={cardClass}
  data-team-index={location === 'team' ? String(index) : undefined}
  data-team-slot-index={location === 'team' ? String(index) : undefined}
  data-storage-index={location === 'storage' && storageEntry && storageEntry.storageIndex >= 0
    ? String(storageEntry.storageIndex)
    : undefined}
  data-pension-index={location === 'pension' ? String(index) : undefined}
  draggable={!pickForUltimateSlot &&
    (location === 'team' ||
    location === 'pension' ||
    (location === 'storage' && !!storageEntry?.draggable))}
  style:animation-delay={location === 'team' ? animDelay : undefined}
  style:opacity={location === 'storage' ? String(storageEntry?.cardOpacity ?? 0.8) : undefined}
  style:cursor={pickForUltimateSlot
    ? 'pointer'
    : location === 'storage' && storageEntry?.isExpeditionEntry
    ? 'not-allowed'
    : location === 'pension'
      ? 'grab'
      : undefined}
  style:filter={location === 'storage' && storageEntry?.isExpeditionEntry
    ? 'grayscale(0.55)'
    : undefined}
  style:border={location === 'pension' && !creature.isShadow
    ? '1px solid #ff69b4'
    : undefined}
  style:box-shadow={location === 'pension' && !creature.isShadow
    ? '0 0 5px rgba(255, 105, 180, 0.5)'
    : undefined}
  title={location === 'storage' && storageEntry?.isExpeditionEntry ? expeditionTitle() : undefined}
  aria-label={resonanceCapped ? resonanceTrueStatsAria : undefined}
  onclick={onClick}
  oncontextmenu={onContextMenu}
  onmouseenter={pickForUltimateSlot ? onUltimatePickEnter : undefined}
  onmouseleave={pickForUltimateSlot ? onUltimatePickLeave : undefined}
  ondragstart={location === 'team'
    ? onDragStartTeam
    : location === 'pension'
      ? onDragStartPension
      : undefined}
  ondragend={location === 'team' || location === 'pension' ? onDragEnd : undefined}
>
  {#if showSpriteInfoTrigger}
    <button
      type="button"
      class="team-sprite-info-trigger"
      aria-label={viewDetailsLabel}
      onmouseenter={onSpriteInfoEnter}
      onmouseleave={onSpriteInfoLeave}
      onclick={(e) => {
        e.stopPropagation();
        onSpriteInfoTap(e);
      }}
    >?</button>
  {/if}
  <img
    use:stableImgSrc={spriteSrc}
    alt={creature.displayName}
    class="team-slot-sprite"
    draggable="false"
    style:animation-delay={location === 'team' ? animDelay : undefined}
    onerror={onSpriteError}
  />
  {#if heldItem}
    {#if heldItem.img}
      <img
        src={heldItem.img}
        class="creature-card-held-item"
        alt={heldItemLabel}
        title={heldItemLabel}
      />
    {:else}
      <span
        class="creature-card-held-item creature-card-held-item-icon"
        title={heldItemLabel}
      >{heldItem.icon ?? 'OBJ'}</span>
    {/if}
  {/if}
  {#if showPokerusBadge}
    <img src="img/PKRS.png" class="creature-card-pokerus" alt="PKRS" title="Pokérus" />
  {/if}
  {#if creature.isFavorite && !pickForUltimateSlot && (location === 'team' || location === 'pension' || (location === 'storage' && storageEntry?.draggable))}
    <span
      class="creature-card-favorite-badge"
      title={favoriteBadgeTitle}
      aria-label={favoriteBadgeTitle}
    >★</span>
  {/if}
  <div class="team-slot-level">
    {#if resonanceCapped && effectiveLevel != null}
      <span class="resonance-stat-swap">
        <span class="resonance-stat-swap__face resonance-stat-swap__face--effective">
          {levelShortLabel} {effectiveLevel}
        </span>
        <span class="resonance-stat-swap__face resonance-stat-swap__face--real" aria-hidden="true">
          {levelShortLabel} {creature.level}
        </span>
      </span>
    {:else}
      {levelShortLabel} {creature.level}
    {/if}
    {#if anchorCatchUp && anchorBoostHandlers}
      <span
        class="team-slot-anchor-boost"
        role="button"
        tabindex="0"
        aria-label={anchorBoostTooltipBody}
        onmouseenter={anchorBoostHandlers.onmouseenter}
        onmouseleave={anchorBoostHandlers.onmouseleave}
        onfocus={anchorBoostHandlers.onfocus}
        onblur={anchorBoostHandlers.onblur}
        onclick={(e) => {
          e.stopPropagation();
          anchorBoostHandlers.onclick(e);
        }}
        onkeydown={(e) => {
          e.stopPropagation();
          anchorBoostHandlers.onkeydown(e);
        }}
      >{anchorBoostLabel}</span>
    {/if}
  </div>
  {#if hasPrestige}
    <div class="team-slot-prestige">
      {#if resonanceCapped && effectivePrestige != null}
        <span class="prestige-badge resonance-stat-swap team-slot-prestige-resonance">
          <span class="resonance-stat-swap__face resonance-stat-swap__face--effective"
            >{effectivePrestige}</span
          >
          <span class="resonance-stat-swap__face resonance-stat-swap__face--real" aria-hidden="true"
            >{prestige}</span
          >
          <img
            src={PRESTIGE_STAR_IMG_URL}
            class="prestige-star-icon"
            alt=""
            aria-hidden="true"
          />
        </span>
      {:else}
        <span class="prestige-badge"
          >{prestige}<img
            src={PRESTIGE_STAR_IMG_URL}
            class="prestige-star-icon"
            alt=""
            aria-hidden="true"
          /></span
        >
      {/if}
    </div>
  {/if}

  {#if location === 'team'}
    <div class="exp-bar" style="height: 8px; margin-top: 5px;">
      <div class="exp-fill" style="width: {expPercent}%"></div>
    </div>
  {:else if location === 'storage' || (location === 'pension' && teamSpritesOnly)}
    <div class="exp-bar" style="height: 4px; margin-top: 2px;">
      <div class="exp-fill" style="width: {expPercent}%"></div>
    </div>
  {/if}

  {#if location !== 'team' && (location !== 'pension' || !teamSpritesOnly) && !(location === 'storage' && storageCompact)}
    <div
      class="team-slot-info"
      style:justify-content={location === 'team' ? undefined : 'center'}
    >
      
    </div>
  {/if}

  {#if location === 'team' && !teamSpritesOnly}
    <!-- svelte-ignore a11y_no_static_element_interactions -->
    <div
      class="team-contribution-trigger"
      data-creature-index={String(index)}
      style="background: rgba(34, 197, 94, 0.15); padding: 6px 8px; border-radius: 5px; margin-top: 5px; width: 100%; font-size: 11px;"
      onmouseenter={onTeamContributionEnter}
      onmouseleave={onContributionLeave}
    >
      <span style="font-weight: bold; color: #16a34a;">
        Contribution ({teamContributionRatePercent}%) :
      </span>
      <span class="team-contribution-btn">{viewDetailsLabel}</span>
    </div>
  {/if}

  {#if location === 'pension' && !teamSpritesOnly}
    <!-- svelte-ignore a11y_no_static_element_interactions -->
    <div
      class="pension-contribution-trigger"
      data-creature-index={String(index)}
      style="background: rgba(255,105,180,0.2); padding: 6px 8px; border-radius: 5px; margin-top: 5px; width: 100%; font-size: 11px;"
      onmouseenter={onPensionContributionEnter}
      onmouseleave={onContributionLeave}
    >
      <span style="font-weight: bold; color: #ff1493;">{pensionContributionLabel}:</span>
      <span class="pension-contribution-btn">{viewDetailsLabel}</span>
    </div>
  {/if}

  {#if location === 'storage' && storageEntry?.isExpeditionEntry}
    <div class="team-slot-info" style="justify-content: center; margin-top: 4px;">
      <span style="color: #92400e; font-weight: 700;">
        {uiText('storage.expeditionBadge', '[EXPEDITION] {name}', {
          name: storageEntry.expeditionName ?? '',
        })}
      </span>
    </div>
    <div class="team-slot-info" style="justify-content: center;">
      <span style="color: #b45309; font-size: 11px;">{storageEntry.expeditionStatus ?? ''}</span>
    </div>
  {/if}
</div>

