﻿/**
 * @file src/gameListeners.ts
 * DOM event listeners extraits de la fin de game.js.
 */

import type { GameRuntime } from './types/game.js';
import { refreshCaptureButtonUI } from './ui/combatDisplay.ts';
import { bindMoveTooltipEvents, isMoveTooltipTapBlocked, showMoveTooltipFromElement } from './lib/moveTooltip.ts';
import { showCreatureBaseStatsTooltipOnTap } from './lib/creatureBaseStatsTooltip.ts';
import { showResonanceAnchorsTooltip } from './lib/resonanceTooltip.ts';
import { buildTapTooltipEvent } from './ui/scheduleTooltipHelpers.ts';

/**
 * Enregistre tous les listeners DOM globaux.
 */
export function registerGameListeners(game: GameRuntime | null | undefined): void {
    if (!game) return;

    bindMoveTooltipEvents(document, game);

    const hideAllGameTooltips = (immediate = true): void => {
        if (game && typeof game.hideAllTooltips === 'function') {
            game.hideAllTooltips(immediate);
        }
    };

    document.addEventListener('mouseover', (e) => {
        const target = e.target;
        if (!(target instanceof Element)) return;
        const statChip = target.closest('.header-stat-chip');
        if (statChip && game && typeof game.showBoostTooltip === 'function') {
            const statType = statChip.getAttribute('data-stat');
            game.showBoostTooltip(e, statType);
        }
    });

    document.addEventListener('mouseout', (e) => {
        const target = e.target;
        if (!(target instanceof Element)) return;
        const statChip = target.closest('.header-stat-chip');
        if (statChip && game && typeof game.hideTooltip === 'function') {
            game.hideTooltip();
        }
    });

    const finishTapTooltip = (e: MouseEvent): void => {
        if (typeof game.scheduleTooltipAutoHide === 'function') game.scheduleTooltipAutoHide(1400);
        e.preventDefault();
        e.stopPropagation();
    };

    document.addEventListener('click', (e) => {
        if (!game || typeof game.isTouchUi !== 'function' || !game.isTouchUi()) return;
        if (typeof game.isTooltipSuppressedOnTouch === 'function' && game.isTooltipSuppressedOnTouch()) return;

        const target = e.target;
        if (!(target instanceof Element)) return;

        const statChip = target.closest('.header-stat-chip');
        if (statChip && typeof game.showBoostTooltip === 'function') {
            const statType = statChip.getAttribute('data-stat');
            game.showBoostTooltip(buildTapTooltipEvent(e, statChip), statType);
            finishTapTooltip(e);
            return;
        }

        const touchTip = target.closest('[data-touch-tooltip]');
        if (touchTip) {
            const kind = touchTip.getAttribute('data-touch-tooltip');
            const ev = buildTapTooltipEvent(e, touchTip);
            if (kind === 'teamContribution' && typeof game.showTeamContributionTooltip === 'function') {
                game.showTeamContributionTooltip(ev);
                finishTapTooltip(e);
            } else if (kind === 'pensionContribution' && typeof game.showPensionContributionTooltip === 'function') {
                game.showPensionContributionTooltip(ev);
                finishTapTooltip(e);
            }
            return;
        }

        const resonancePreview = target.closest('.resonance-anchors-preview');
        if (resonancePreview) {
            const ev = buildTapTooltipEvent(e, resonancePreview);
            if (showResonanceAnchorsTooltip(game, ev)) {
                finishTapTooltip(e);
            }
            return;
        }

        const moveNode = target.closest('[data-move-tooltip-name]');
        if (moveNode && !isMoveTooltipTapBlocked(target)) {
            const ev = buildTapTooltipEvent(e, moveNode);
            if (showMoveTooltipFromElement(game, moveNode as HTMLElement, ev)) {
                finishTapTooltip(e);
            }
            return;
        }

        const baseStatTrigger = target.closest('.stat-base-tooltip-trigger');
        if (baseStatTrigger) {
            if (showCreatureBaseStatsTooltipOnTap(game, baseStatTrigger, e)) {
                finishTapTooltip(e);
            }
            return;
        }

        const dataTip = target.closest('[data-tooltip-title]');
        if (dataTip && !dataTip.hasAttribute('data-action') && typeof game.scheduleTooltip === 'function') {
            const el = dataTip as HTMLElement;
            const title = el.dataset.tooltipTitle || '';
            if (title) {
                const desc = el.dataset.tooltipDesc || '';
                game.scheduleTooltip(buildTapTooltipEvent(e, dataTip), title, desc, 50);
                finishTapTooltip(e);
            }
        }
    });

    window.addEventListener('click', (e) => {
        hideAllGameTooltips(true);

        const target = e.target;
        if (!(target instanceof Element)) return;

        const closeBtn = target.closest('.js-close-modal');
        if (closeBtn) {
            const modalToClose = closeBtn.closest('.js-modal-overlay') || closeBtn.closest('.modal') || closeBtn.closest('.compact-popup');
            if (modalToClose) {
                modalToClose.classList.remove('show');
            }
            const targetId = closeBtn.getAttribute('data-target');
            if (targetId) {
                const targetEl = document.getElementById(targetId);
                if (targetEl) {
                    targetEl.classList.remove('show');
                    if (targetEl.style.display === 'block') targetEl.style.display = 'none';
                }
            }
            return;
        }

        if (target.classList.contains('js-modal-overlay')) {
            if (target.id === 'captureModal') {
                return;
            }
            const overlay = target as HTMLElement;
            overlay.classList.remove('show');
            const disp = overlay.style.display;
            if (disp === 'block' || disp === 'flex') overlay.style.display = 'none';
            return;
        }

        const clickInsideMainModal = target.closest(
            '.js-modal-overlay.show, .stats-modal.show, .modal.show, .modal-overlay.show, #saveSlotBootModal.show, .talent-action-modal, .talent-choice-modal',
        ) || (() => {
            const nar = target.closest('#narrativeOverlay');
            return !!(nar && nar.classList.contains('narrative-open'));
        })();

        if (!clickInsideMainModal &&
            !target.closest('.compact-popup') &&
            !target.closest('#autoSelectGroup') &&
            !target.closest('#autoSelectBtn') &&
            !target.closest('#autoSettingsBtn') &&
            !target.closest('#captureSelectGroup') &&
            !target.closest('#captureModeBtn') &&
            !target.closest('#captureSettingsBtn')) {

            const autoModal = document.getElementById('autoSettingsModal');
            if (autoModal && autoModal.classList.contains('show')) {
                game.closeAutoSettings();
            }

            const captureModal = document.querySelector<HTMLElement>('#captureTargetWrapper.show');
            if (captureModal) {
                captureModal.classList.remove('show');
                captureModal.style.removeProperty('display');
                refreshCaptureButtonUI(game);
            }
        }
    });

    document.addEventListener('touchstart', () => {
        hideAllGameTooltips(true);
        if (game && typeof game.startTouchTooltipGuard === 'function') {
            game.startTouchTooltipGuard();
        }
    }, { capture: true, passive: true });

    const cancelTouchTooltipGuard = (): void => {
        if (game && typeof game.cancelTouchTooltipGuard === 'function') {
            game.cancelTouchTooltipGuard();
        }
    };

    document.addEventListener('touchend', cancelTouchTooltipGuard, { capture: true, passive: true });
    document.addEventListener('touchcancel', cancelTouchTooltipGuard, { capture: true, passive: true });
    document.addEventListener('touchmove', cancelTouchTooltipGuard, { capture: true, passive: true });

    window.addEventListener('scroll', () => {
        hideAllGameTooltips(true);
    }, { passive: true });

    window.addEventListener('resize', () => {
        hideAllGameTooltips(true);
    });

    document.addEventListener('visibilitychange', () => {
        if (document.hidden) hideAllGameTooltips(true);
    });

    window.addEventListener('load', () => {
        setTimeout(() => {
            if (game) {
                if (typeof game.updateAutoBadge === 'function') {
                    game.updateAutoBadge();
                }
                if (typeof game.updateCaptureBadge === 'function') {
                    game.updateCaptureBadge();
                }
                if (typeof game.refreshBattleFeatureButtons === 'function') {
                    game.refreshBattleFeatureButtons();
                }
            }
        }, 1000);
    });
}
