// Deep clone rapide : structuredClone (natif, ~2-5x plus rapide que JSON round-trip)
// avec fallback JSON pour les très vieux runtimes.
export const __hasStructuredClone = (typeof structuredClone === 'function');
export function __deepClone<T>(value: T): T {
    if (value === null || value === undefined) return value;
    if (__hasStructuredClone) {
        try { return structuredClone(value); }
        catch (_) { /* fallback ci-dessous (ex: valeur non clonable) */ }
    }
    return JSON.parse(JSON.stringify(value)) as T;
}

