export function saveLang(gameRef: GameRuntime | null = null): string {
    const runtimeGame = gameRef || ((typeof window !== 'undefined' && window.game) ? window.game : null);
    if (runtimeGame && typeof runtimeGame.normalizeLanguage === 'function') {
        return runtimeGame.normalizeLanguage(runtimeGame.language);
    }
    return (runtimeGame && runtimeGame.language === 'en') ? 'en' : 'fr';
}

export function saveText(gameRef: GameRuntime | null, fr: string, en: string, vars: Record<string, unknown> = {}): string {
    const template = saveLang(gameRef) === 'en' ? en : fr;
    return String(template || '').replace(/\{(\w+)\}/g, (_, k: string) => coerceStr(vars[k], ''));
}

export function clampSaveSlotId(rawSlotId: unknown) {
    const n = Number(rawSlotId);
    if (!Number.isFinite(n)) return 1;
    return Math.min(SAVE_SLOT_COUNT, Math.max(1, Math.floor(n)));
}

export function getSaveSlotKey(slotId: number = 1) {
    return `${SAVE_SLOT_PREFIX}${clampSaveSlotId(slotId)}`;
}

export function getSaveBackupSlotKey(slotId: number = 1) {
    return `${getSaveSlotKey(slotId)}${SAVE_SLOT_BACKUP_SUFFIX}`;
}

export function getPlayerSpriteCatalogForSave() {
    const fromConstants = (typeof PLAYER_TRAINER_SPRITES !== 'undefined' && Array.isArray(PLAYER_TRAINER_SPRITES))
        ? PLAYER_TRAINER_SPRITES
        : SAVE_FALLBACK_PLAYER_SPRITES;
    const catalog = fromConstants
        .filter(entry => entry && typeof entry.id === 'string' && entry.id && typeof entry.url === 'string' && entry.url)
        .map(entry => ({ id: entry.id, label: entry.label || entry.id, url: entry.url }));
    return catalog.length > 0 ? catalog : SAVE_FALLBACK_PLAYER_SPRITES;
}

export function getDefaultPlayerSpriteIdForSave() {
    const catalog = getPlayerSpriteCatalogForSave();
    const fromConstant = (typeof PLAYER_TRAINER_DEFAULT_SPRITE_ID === 'string' && PLAYER_TRAINER_DEFAULT_SPRITE_ID)
        ? PLAYER_TRAINER_DEFAULT_SPRITE_ID
        : null;
    if (fromConstant && catalog.some(entry => entry.id === fromConstant)) return fromConstant;
    const firstEntry = catalog[0];
    return firstEntry ? firstEntry.id : SAVE_FALLBACK_PLAYER_SPRITES[0]?.id ?? 'default';
}

export function getPlayerSpriteUrlFromIdForSave(spriteId: string) {
    const catalog = getPlayerSpriteCatalogForSave();
    const match = catalog.find(entry => entry.id === spriteId);
    const fallback = catalog[0];
    return match ? match.url : (fallback ? fallback.url : SAVE_FALLBACK_PLAYER_SPRITES[0]?.url ?? '');
}

export function getDefaultPlayerNameForSave(gameRef: GameRuntime | null = null) {
    return saveLang(gameRef) === 'en' ? SAVE_FALLBACK_PLAYER_NAME_EN : SAVE_FALLBACK_PLAYER_NAME_FR;
}

export function sanitizePlayerNameForSave(rawName: unknown, gameRef: GameRuntime | null = null) {
    const fallbackName = getDefaultPlayerNameForSave(gameRef);
    const candidate = (typeof rawName === 'string' ? rawName : '')
        .replace(/[\u0000-\u001F\u007F]/g, '')
        .trim()
        .slice(0, 20);
    return candidate || fallbackName;
}

export function normalizePlayerProfileForSave(profile: unknown, gameRef: GameRuntime | null = null) {
    if (gameRef && typeof gameRef.normalizePlayerProfile === 'function') {
        try {
            const normalizedByGame = gameRef.normalizePlayerProfile(profile as Record<string, unknown> | null | undefined);
            if (normalizedByGame && typeof normalizedByGame === 'object') {
                return {
                    name: sanitizePlayerNameForSave(normalizedByGame.name, gameRef),
                    spriteId: typeof normalizedByGame.spriteId === 'string' ? normalizedByGame.spriteId : getDefaultPlayerSpriteIdForSave()
                };
            }
        } catch (_) {
            // fallback below
        }
    }

    const prof = profile as { name?: string; spriteId?: string } | null | undefined;
    const safeName = sanitizePlayerNameForSave(prof?.name, gameRef);
    const wantedSpriteId = (prof && typeof prof.spriteId === 'string') ? prof.spriteId : getDefaultPlayerSpriteIdForSave();
    const catalog = getPlayerSpriteCatalogForSave();
    const hasSprite = catalog.some(entry => entry.id === wantedSpriteId);
    return {
        name: safeName,
        spriteId: hasSprite ? wantedSpriteId : getDefaultPlayerSpriteIdForSave()
    };
}

export function createDefaultSaveSlotMeta(slotId: number) {
    return {
        slotId: clampSaveSlotId(slotId),
        hasData: false,
        playerName: '',
        spriteId: getDefaultPlayerSpriteIdForSave(),
        updatedAt: 0,
        createdAt: 0
    };
}

export function normalizeSaveSlotMeta(slotId: number, rawMeta: unknown): SaveSlotMeta {
    const safe = createDefaultSaveSlotMeta(slotId);
    if (!rawMeta || typeof rawMeta !== 'object') return safe;
    const raw = rawMeta as SaveSlotMetaRaw;
    const normalizedProfile = normalizePlayerProfileForSave({
        name: raw.playerName || '',
        spriteId: raw.spriteId
    });
    return {
        slotId: safe.slotId,
        hasData: !!raw.hasData,
        playerName: normalizedProfile.name || '',
        spriteId: normalizedProfile.spriteId,
        updatedAt: Number.isFinite(Number(raw.updatedAt)) ? Math.max(0, Number(raw.updatedAt)) : 0,
        createdAt: Number.isFinite(Number(raw.createdAt)) ? Math.max(0, Number(raw.createdAt)) : 0
    };
}

export function readSaveMetaState(): SaveMetaState {
    const fallbackSlots: Record<number, SaveSlotMeta> = {};
    for (let i = 1; i <= SAVE_SLOT_COUNT; i++) {
        fallbackSlots[i] = createDefaultSaveSlotMeta(i);
    }

    if (typeof localStorage === 'undefined') {
        return { version: 1, slots: fallbackSlots };
    }

    const raw = localStorage.getItem(SAVE_META_KEY);
    if (!raw) return { version: 1, slots: fallbackSlots };

    try {
        const parsed: unknown = JSON.parse(raw);
        const meta = (parsed && typeof parsed === 'object')
            ? parsed as { version?: unknown; slots?: Record<string, unknown> }
            : null;
        const slotsObj = (meta?.slots && typeof meta.slots === 'object') ? meta.slots : {};
        for (let i = 1; i <= SAVE_SLOT_COUNT; i++) {
            fallbackSlots[i] = normalizeSaveSlotMeta(i, slotsObj[i]);
        }
        return {
            version: Number.isFinite(Number(meta?.version)) ? Number(meta?.version) : 1,
            slots: fallbackSlots
        };
    } catch (error) {
        debugWarn('Meta slots invalide, regeneration automatique.', error);
        return { version: 1, slots: fallbackSlots };
    }
}

export function writeSaveMetaState(metaState: SaveMetaState) {
    if (typeof localStorage === 'undefined') return;
    const safeSlots: Record<number, SaveSlotMeta> = {};
    for (let i = 1; i <= SAVE_SLOT_COUNT; i++) {
        safeSlots[i] = normalizeSaveSlotMeta(i, metaState.slots[i]);
    }
    const payload = {
        version: Number.isFinite(Number(metaState && metaState.version)) ? Number(metaState.version) : 1,
        slots: safeSlots
    };
    localStorage.setItem(SAVE_META_KEY, JSON.stringify(payload));
}

export function readSaveDataForSlot(slotId: number) {
    if (typeof localStorage === 'undefined') return { raw: null, data: null, corrupted: false };
    const raw = localStorage.getItem(getSaveSlotKey(slotId));
    if (!raw) return { raw: null, data: null, corrupted: false };
    const parsed = parseSavePayload(raw);
    return { raw, data: parsed, corrupted: !parsed };
}

const PARSE_SAVE_PAYLOAD_CACHE_MAX = 4;
const parseSavePayloadCache = new Map<string, SaveData | null>();

/** Drop cached LZ/JSON parses after any save write or slot clear. */
export function invalidateParseSavePayloadCache(): void {
    parseSavePayloadCache.clear();
}

function rememberParsedSavePayload(raw: string, parsed: SaveData | null): void {
    if (parseSavePayloadCache.has(raw)) {
        parseSavePayloadCache.delete(raw);
    } else if (parseSavePayloadCache.size >= PARSE_SAVE_PAYLOAD_CACHE_MAX) {
        const oldest = parseSavePayloadCache.keys().next().value;
        if (oldest !== undefined) parseSavePayloadCache.delete(oldest);
    }
    parseSavePayloadCache.set(raw, parsed);
}

function cloneParsedSaveData(data: SaveData): SaveData {
    try {
        return structuredClone(data);
    } catch {
        return JSON.parse(JSON.stringify(data)) as SaveData;
    }
}

export function parseSavePayload(raw: unknown): SaveData | null {
    if (typeof raw !== 'string') return null;
    const sanitizedRaw = raw.replace(/^\uFEFF/, '').trim();
    if (sanitizedRaw.length === 0) return null;
    if (parseSavePayloadCache.has(sanitizedRaw)) {
        const cached = parseSavePayloadCache.get(sanitizedRaw);
        if (cached == null) return null;
        // Clone so loadGameLogic migrations cannot poison the cache entry.
        return cloneParsedSaveData(cached);
    }
    try {
        const parsed: unknown = JSON.parse(sanitizedRaw);
        if (!parsed || typeof parsed !== 'object') {
            rememberParsedSavePayload(sanitizedRaw, null);
            return null;
        }
        const envelope = parsed as {
            __saveEnvelope?: unknown;
            encoding?: unknown;
            data?: unknown;
        };
        const looksLikeEnvelope = !!(
            typeof envelope.__saveEnvelope === 'string'
            && typeof envelope.encoding === 'string'
            && typeof envelope.data === 'string'
        );
        if (
            looksLikeEnvelope
            && envelope.encoding === SAVE_ENVELOPE_ENCODING
        ) {
            const decompressed = __lzStringCodec.decompressFromUTF16(envelope.data as string);
            if (typeof decompressed !== 'string' || decompressed.length === 0) {
                rememberParsedSavePayload(sanitizedRaw, null);
                return null;
            }
            const inner: unknown = JSON.parse(decompressed);
            const result = (inner && typeof inner === 'object') ? inner as SaveData : null;
            rememberParsedSavePayload(sanitizedRaw, result);
            return result ? cloneParsedSaveData(result) : null;
        }
        if (looksLikeEnvelope) {
            rememberParsedSavePayload(sanitizedRaw, null);
            return null;
        }
        const result = parsed as SaveData;
        rememberParsedSavePayload(sanitizedRaw, result);
        return cloneParsedSaveData(result);
    } catch (_) {
        rememberParsedSavePayload(sanitizedRaw, null);
        return null;
    }
}

export function isUsableSavePayload(raw: unknown) {
    const parsed = parseSavePayload(raw);
    return !!(parsed && Array.isArray(parsed.playerTeam) && parsed.playerTeam.length > 0);
}

/** True if slot (or legacy slot-1 key) has a parseable save blob in localStorage. */
export function slotHasRecoverableSave(slotId: number = 1): boolean {
    if (typeof localStorage === 'undefined') return false;
    const normalized = clampSaveSlotId(slotId);
    const slotRaw = localStorage.getItem(getSaveSlotKey(normalized));
    if (isUsableSavePayload(slotRaw)) return true;
    const backupRaw = localStorage.getItem(getSaveBackupSlotKey(normalized));
    if (isUsableSavePayload(backupRaw)) return true;
    if (normalized === 1) {
        const legacyRaw = localStorage.getItem(SAVE_KEY);
        if (isUsableSavePayload(legacyRaw)) return true;
    }
    return false;
}

export function isLikelyCreatureGameSaveData(data: unknown): data is SaveData {
    if (!data || typeof data !== 'object') return false;
    const d = data as SaveData;
    if (!Array.isArray(d.playerTeam) || d.playerTeam.length === 0) return false;
    if (!d.playerMainStats || typeof d.playerMainStats !== 'object') return false;
    if (!d.stats || typeof d.stats !== 'object') return false;
    const money = Number(d.pokedollars);
    if (!Number.isFinite(money) || money < 0) return false;
    return true;
}

export function findRecoverableSaveCandidatesFromStorage() {
    if (typeof localStorage === 'undefined') return [];
    const knownKeys = new Set([SAVE_KEY, SAVE_META_KEY, SAVE_ACTIVE_SLOT_KEY, SAVE_MIGRATED_KEY]);
    for (let i = 1; i <= SAVE_SLOT_COUNT; i++) {
        knownKeys.add(getSaveSlotKey(i));
        knownKeys.add(getSaveBackupSlotKey(i));
    }

    const candidates = [];
    for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (!key || knownKeys.has(key)) continue;
        const raw = localStorage.getItem(key);
        const parsed = parseSavePayload(raw);
        if (!isLikelyCreatureGameSaveData(parsed)) continue;
        const ts = Number(parsed.lastSaveTime || parsed.saveTime || parsed.lastQuestUpdate || 0);
        candidates.push({
            key,
            raw,
            ts: Number.isFinite(ts) ? Math.max(0, ts) : 0
        });
    }

    candidates.sort((a, b) => {
        if (b.ts !== a.ts) return b.ts - a.ts;
        return (b.raw ? b.raw.length : 0) - (a.raw ? a.raw.length : 0);
    });
    return candidates;
}

export function buildMetaFromSaveData(slotId: number, gameData: SaveData, baseMeta: SaveSlotMeta | null = null) {
    const previous = normalizeSaveSlotMeta(slotId, baseMeta);
    const normalizedProfile = normalizePlayerProfileForSave(gameData && gameData.playerProfile
        ? gameData.playerProfile
        : { name: previous.playerName, spriteId: previous.spriteId });
    const timestampCandidate = Number(gameData && (gameData.lastSaveTime || gameData.saveTime || gameData.lastQuestUpdate));
    const updatedAt = (Number.isFinite(timestampCandidate) && timestampCandidate > 0) ? timestampCandidate : Date.now();
    return {
        slotId: previous.slotId,
        hasData: true,
        playerName: normalizedProfile.name,
        spriteId: normalizedProfile.spriteId,
        updatedAt,
        createdAt: previous.createdAt > 0 ? previous.createdAt : updatedAt
    };
}

export function getKnownRegionIdsForSave(): string[] {
    const set: Record<string, boolean> = { kanto: true };
    if (typeof REGIONS !== 'undefined' && REGIONS && typeof REGIONS === 'object') {
        Object.keys(REGIONS).forEach((id) => {
            if (id) set[String(id)] = true;
        });
    }
    if (typeof ZONES !== 'undefined' && ZONES && typeof ZONES === 'object') {
        Object.keys(ZONES).forEach((idStr) => {
            const id = Number(idStr);
            if (!Number.isFinite(id)) return;
            const zone = ZONES[id];
            const regionId = (zone && zone.regionId) ? String(zone.regionId) : 'kanto';
            set[regionId] = true;
        });
    }
    const ids = Object.keys(set).filter((id) => isRegionReleased(id));
    ids.sort((a, b) => {
        if (a === b) return 0;
        if (a === 'kanto') return -1;
        if (b === 'kanto') return 1;
        return a.localeCompare(b);
    });
    return ids;
}

export function getFirstZoneIdForRegionSave(regionId: string) {
    if (typeof ZONES === 'undefined' || !ZONES) return null;
    const target = String(regionId || 'kanto');
    const ids = Object.keys(ZONES)
        .map((id) => Number(id))
        .filter((id) => Number.isFinite(id) && String((ZONES[id] && ZONES[id].regionId) || 'kanto') === target)
        .sort((a, b) => {
            const za = ZONES[a];
            const zb = ZONES[b];
            const oa = Number(za?.regionOrder);
            const ob = Number(zb?.regionOrder);
            if (Number.isFinite(oa) && Number.isFinite(ob) && oa !== ob) return oa - ob;
            return a - b;
        });
    return ids.length ? ids[0] : null;
}

export function createDefaultMaxReachedZoneByRegion(baseMaxReached = 1): Record<string, number> {
    const out: Record<string, number> = {};
    const regionIds = getKnownRegionIdsForSave();
    regionIds.forEach((regionId) => {
        const firstZoneId = getFirstZoneIdForRegionSave(regionId);
        if (regionId === 'kanto') {
            const baseline = Number.isFinite(Number(baseMaxReached)) ? Number(baseMaxReached) : 1;
            out[regionId] = Math.max(baseline, Number(firstZoneId) || 1);
        } else {
            out[regionId] = 0;
        }
    });
    return out;
}

export function normalizeMaxReachedZoneByRegionForSave(rawValue: unknown, baseMaxReached = 1) {
    const normalized = createDefaultMaxReachedZoneByRegion(baseMaxReached);
    if (!rawValue || typeof rawValue !== 'object') return normalized;

    const raw = rawValue as Record<string, unknown>;
    Object.keys(raw).forEach((regionId) => {
        const n = Number(raw[regionId]);
        if (!Number.isFinite(n)) return;
        if (String(regionId) === 'kanto') {
            const firstZoneId = Number(getFirstZoneIdForRegionSave('kanto') || 1);
            let kantoMax = Math.max(firstZoneId, Math.floor(n));
            if (kantoMax === 47) kantoMax = 46;
            normalized.kanto = kantoMax;
            return;
        }
        if (String(regionId) === 'hoenn') {
            let hoennMax = Math.max(0, Math.floor(n));
            if (shouldRemapLegacyHoennZoneId(hoennMax)) {
                hoennMax = remapHoennLegacyZoneId(hoennMax);
            }
            normalized.hoenn = hoennMax;
            return;
        }
        normalized[String(regionId)] = Math.max(0, Math.floor(n));
    });

    return normalized;
}

/** Legacy: Kanto zone 47 removed after Jadielle arena map renumber; clamp to Cerulean Cave (46). */
export function applyLegacyKantoZone47ClampOnLoad(game: GameRuntime): void {
    if (currentZone === 47) {
        setActiveZone(46);
        if (typeof document !== 'undefined') {
            const zoneSelect = document.getElementById('zoneSelect') as HTMLSelectElement | null;
            if (zoneSelect) zoneSelect.value = String(currentZone);
            updateZoneInfo(game);
        }
    }
    if (maxReachedZone === 47) setMaxReachedZone(46);
}

/** Legacy: Hoenn zone ids renumbered to sequential 201–264 (Emerald layout). */
export function applyLegacyHoennZoneRemapOnLoad(
    game: GameRuntime,
    options?: { hoennZonesLayoutV2?: boolean },
): void {
    if (options?.hoennZonesLayoutV2 === true) return;

    let changed = false;

    if (game.zoneProgress && typeof game.zoneProgress === 'object') {
        const keysBefore = Object.keys(game.zoneProgress).sort().join(',');
        migrateHoennZoneProgressKeys(game.zoneProgress as Record<string, {
            pokemonTiers?: Record<string, number>;
            bossesDefeated?: number;
            epicsDefeated?: number;
            trainersDefeated?: number;
            combatsWon?: number;
        }>);
        if (Object.keys(game.zoneProgress).sort().join(',') !== keysBefore) changed = true;
    }

    if (shouldRemapLegacyHoennZoneId(currentZone)) {
        setActiveZone(remapHoennLegacyZoneId(currentZone));
        changed = true;
    }
    if (shouldRemapLegacyHoennZoneId(maxReachedZone)) {
        setMaxReachedZone(remapHoennLegacyZoneId(maxReachedZone));
        changed = true;
    }
    if (maxReachedZoneByRegion && maxReachedZoneByRegion.hoenn != null) {
        const hoennMax = Number(maxReachedZoneByRegion.hoenn);
        if (Number.isFinite(hoennMax) && shouldRemapLegacyHoennZoneId(hoennMax)) {
            maxReachedZoneByRegion.hoenn = remapHoennLegacyZoneId(hoennMax);
            changed = true;
        }
    }

    if (changed && typeof document !== 'undefined') {
        const zoneSelect = document.getElementById('zoneSelect') as HTMLSelectElement | null;
        if (zoneSelect) zoneSelect.value = String(currentZone);
        updateZoneInfo(game);
    }
}

export function deriveSlotMetaFromStorage(slotId: number, baseMeta: SaveSlotMeta | null = null) {
    const previous = normalizeSaveSlotMeta(slotId, baseMeta);
    const loaded = readSaveDataForSlot(slotId);
    if (!loaded.raw) {
        return {
            ...previous,
            hasData: false,
            updatedAt: 0,
            createdAt: 0
        };
    }
    if (loaded.data && typeof loaded.data === 'object') {
        return buildMetaFromSaveData(slotId, loaded.data, previous);
    }
    const now = Date.now();
    return {
        ...previous,
        hasData: true,
        updatedAt: previous.updatedAt || now,
        createdAt: previous.createdAt || now
    };
}

export function getActiveSaveSlot() {
    if (typeof localStorage === 'undefined') return 1;
    return clampSaveSlotId(localStorage.getItem(SAVE_ACTIVE_SLOT_KEY));
}

export function setActiveSaveSlot(slotId: number) {
    const normalized = clampSaveSlotId(slotId);
    if (typeof localStorage !== 'undefined') {
        localStorage.setItem(SAVE_ACTIVE_SLOT_KEY, String(normalized));
    }
    return normalized;
}

export function migrateLegacySaveToSlotsIfNeeded() {
    if (typeof localStorage === 'undefined') return false;
    let restoredAnySaveToSlot = false;

    const legacyRaw = localStorage.getItem(SAVE_KEY);
    const slot1Key = getSaveSlotKey(1);
    const slot1Raw = localStorage.getItem(slot1Key);
    const canUseLegacy = isUsableSavePayload(legacyRaw);
    const slot1LooksUsable = isUsableSavePayload(slot1Raw);
    if (canUseLegacy && (!slot1Raw || !slot1LooksUsable)) {
        localStorage.setItem(slot1Key, legacyRaw!);
        restoredAnySaveToSlot = true;
    }

    const slot1BackupRaw = localStorage.getItem(getSaveBackupSlotKey(1));
    if (!isUsableSavePayload(localStorage.getItem(slot1Key)) && isUsableSavePayload(slot1BackupRaw)) {
        localStorage.setItem(slot1Key, slot1BackupRaw!);
        restoredAnySaveToSlot = true;
    }

    if (!isUsableSavePayload(localStorage.getItem(slot1Key))) {
        const candidates = findRecoverableSaveCandidatesFromStorage();
        const topCandidate = candidates[0];
        if (topCandidate) {
            localStorage.setItem(slot1Key, topCandidate.raw!);
            restoredAnySaveToSlot = true;
            debugWarn(`Restauration d'une sauvegarde detectee sous la cle "${topCandidate.key}" vers le slot 1.`);
        }
    }

    if (!localStorage.getItem(SAVE_ACTIVE_SLOT_KEY)) {
        localStorage.setItem(SAVE_ACTIVE_SLOT_KEY, '1');
    }

    const state = readSaveMetaState();
    for (let i = 1; i <= SAVE_SLOT_COUNT; i++) {
        state.slots[i] = deriveSlotMetaFromStorage(i, state.slots[i]);
    }
    writeSaveMetaState(state);

    if (restoredAnySaveToSlot) {
        localStorage.setItem(SAVE_MIGRATED_KEY, '1');
    }
    return restoredAnySaveToSlot;
}

export function listSaveSlotsMeta(options: { skipMigration?: boolean } = {}): SaveSlotMeta[] {
    if (!options.skipMigration) {
        migrateLegacySaveToSlotsIfNeeded();
    }

    const state = readSaveMetaState();
    let changed = false;
    const metas = [];
    for (let i = 1; i <= SAVE_SLOT_COUNT; i++) {
        const prev = normalizeSaveSlotMeta(i, state.slots[i]);
        const next = deriveSlotMetaFromStorage(i, prev);
        metas.push(next);
        if (JSON.stringify(prev) !== JSON.stringify(next)) changed = true;
    }
    if (changed) {
        const nextState: SaveMetaState = { version: state.version || 1, slots: {} };
        metas.forEach(meta => {
            nextState.slots[meta.slotId] = meta;
        });
        writeSaveMetaState(nextState);
    }
    return metas;
}

export function getSaveSlotMetaById(slotId: number): SaveSlotMeta {
    const normalizedSlot = clampSaveSlotId(slotId);
    const metas = listSaveSlotsMeta({ skipMigration: true });
    return metas.find(meta => meta.slotId === normalizedSlot) || createDefaultSaveSlotMeta(normalizedSlot);
}

export function syncSaveSlotMetaFromGameData(slotId: number, gameData: SaveData, gameRef: GameRuntime | null = null) {
    const normalizedSlot = clampSaveSlotId(slotId);
    const state = readSaveMetaState();
    const current = state.slots[normalizedSlot];
    state.slots[normalizedSlot] = buildMetaFromSaveData(normalizedSlot, gameData || {}, current);
    if (gameRef && gameRef.playerProfile) {
        const profile = normalizePlayerProfileForSave(gameRef.playerProfile, gameRef);
        state.slots[normalizedSlot].playerName = profile.name;
        state.slots[normalizedSlot].spriteId = profile.spriteId;
    }
    writeSaveMetaState(state);
}

export function clearPendingNewPlayerProfile() {
    if (typeof window === 'undefined') return;
    delete window.__pendingNewPlayerProfile;
}

export function setPendingNewPlayerProfile(profile: unknown) {
    if (typeof window === 'undefined') return;
    window.__pendingNewPlayerProfile = normalizePlayerProfileForSave(profile);
}

export function consumePendingNewPlayerProfile() {
    if (typeof window === 'undefined') return null;
    const pending = window.__pendingNewPlayerProfile;
    delete window.__pendingNewPlayerProfile;
    if (!pending || typeof pending !== 'object') return null;
    return normalizePlayerProfileForSave(pending);
}

function fileReaderTextResult(result: string | ArrayBuffer | null | undefined): string {
    return typeof result === 'string' ? result : '';
}

export function escapeHtmlForSaveBoot(value: unknown) {
    return escapeHtml(coerceStr(value, ''));
}

export function formatSaveSlotDate(timestamp: unknown) {
    const ts = Number(timestamp);
    if (!Number.isFinite(ts) || ts <= 0) return '-';
    try {
        const locale = (typeof navigator !== 'undefined' && typeof navigator.language === 'string' && navigator.language.toLowerCase().startsWith('en'))
            ? 'en-US'
            : 'fr-FR';
        return new Date(ts).toLocaleString(locale, {
            year: 'numeric',
            month: '2-digit',
            day: '2-digit',
            hour: '2-digit',
            minute: '2-digit'
        });
    } catch (_) {
        return new Date(ts).toLocaleString();
    }
}

export function formatSaveBootDuration(durationMs: unknown) {
    const ms = Number(durationMs);
    if (!Number.isFinite(ms) || ms <= 0) return '0 min';
    const totalMinutes = Math.floor(ms / 60000);
    const days = Math.floor(totalMinutes / (60 * 24));
    const hours = Math.floor((totalMinutes % (60 * 24)) / 60);
    const minutes = totalMinutes % 60;
    if (days > 0) return `${days}j ${hours}h`;
    if (hours > 0) return `${hours}h ${minutes}m`;
    return `${minutes} min`;
}

export function formatSaveBootInteger(value: unknown) {
    const num = Number(value);
    if (!Number.isFinite(num) || num < 0) return '-';
    const rounded = Math.floor(num);
    try {
        const locale = (typeof navigator !== 'undefined' && typeof navigator.language === 'string' && navigator.language.toLowerCase().startsWith('en'))
            ? 'en-US'
            : 'fr-FR';
        return new Intl.NumberFormat(locale).format(rounded);
    } catch (_) {
        return String(rounded);
    }
}

export function getSaveBootZoneLabel(zoneId: unknown) {
    const numericId = Number(zoneId);
    if (!Number.isFinite(numericId) || numericId <= 0) return '-';
    const zoneMap = (typeof ZONES !== 'undefined' && ZONES && typeof ZONES === 'object')
        ? ZONES as Record<number, { regionId: string; name?: string }>
        : null;
    const zoneData = zoneMap ? zoneMap[numericId] : null;
    const zoneName = zoneData && typeof zoneData.name === 'string' ? zoneData.name : '';
    return zoneName ? `#${numericId} ${zoneName}` : `#${numericId}`;
}

export function getSaveSlotProgressSummary(slotId: number) {
    const summary = {
        playTime: '-',
        zone: '-',
        badgeCount: '-',
        gold: '-',
        maxLevel: '-',
        maxPrestige: '-',
        shinyCount: '-',
        corrupted: false
    };
    const normalizedSlot = clampSaveSlotId(slotId);
    if (typeof localStorage === 'undefined') return summary;

    const raw = localStorage.getItem(getSaveSlotKey(normalizedSlot));
    if (!raw) return summary;

    const data = parseSavePayload(raw);
    if (!data) {
        summary.corrupted = true;
        return summary;
    }

    const team = Array.isArray(data.playerTeam) ? data.playerTeam : [];
    const storage = Array.isArray(data.storage) ? data.storage : [];
    const pension = Array.isArray(data.pension) ? data.pension : [];
    const allCreatures = [...team, ...storage, ...pension];

    let maxLevelFromCreatures = 0;
    let maxPrestige = 0;
    let shinyFromRoster = 0;
    for (const creature of allCreatures) {
        const lvl = Number(creature && creature.level);
        if (Number.isFinite(lvl) && lvl > maxLevelFromCreatures) maxLevelFromCreatures = lvl;
        const prestige = Number(creature && creature.prestige);
        if (Number.isFinite(prestige) && prestige > maxPrestige) maxPrestige = prestige;
        if (creature && creature.isShiny === true) shinyFromRoster += 1;
    }

    summary.zone = getSaveBootZoneLabel(data.currentZone);

    const stats = data && typeof data.stats === 'object' ? data.stats : null;

    const maxLevelFromStats = Number(stats && stats.highestLevelReached);
    const effectiveMaxLevel = Number.isFinite(maxLevelFromStats) && maxLevelFromStats > 0
        ? maxLevelFromStats
        : maxLevelFromCreatures;
    summary.maxLevel = effectiveMaxLevel > 0 ? formatSaveBootInteger(effectiveMaxLevel) : '-';

    const totalPlayTime = Number(stats && stats.totalPlayTime);
    const sessionStart = Number(stats && stats.startTime);
    const saveTs = Number(data.saveTime || data.lastSaveTime);
    const extraSession = Number.isFinite(sessionStart) && Number.isFinite(saveTs) && saveTs >= sessionStart
        ? (saveTs - sessionStart)
        : 0;
    const computedPlayTime = Math.max(0, (Number.isFinite(totalPlayTime) ? totalPlayTime : 0) + extraSession);
    summary.playTime = formatSaveBootDuration(computedPlayTime);

    const badges = data && typeof data.badges === 'object' && data.badges ? data.badges : null;
    const badgeCount = badges
        ? Object.values(badges).filter(value => !!value).length
        : Number(stats && stats.badgesEarned);
    summary.badgeCount = Number.isFinite(badgeCount) && badgeCount >= 0 ? formatSaveBootInteger(badgeCount) : '-';

    const gold = Number(data && data.pokedollars);
    summary.gold = Number.isFinite(gold) && gold >= 0 ? formatSaveBootInteger(gold) : '-';

    summary.maxPrestige = maxPrestige > 0 ? formatSaveBootInteger(maxPrestige) : '0';

    const shinyFromStats = Number(stats && stats.shiniesObtained);
    if (Number.isFinite(shinyFromStats) && shinyFromStats >= 0) {
        summary.shinyCount = formatSaveBootInteger(shinyFromStats);
    } else {
        let shinyFromPokedex = 0;
        const pokedex = data && typeof data.pokedex === 'object' ? data.pokedex : null;
        if (pokedex) {
            for (const entry of Object.values(pokedex)) {
                if (!entry || typeof entry !== 'object') continue;
                const e = entry as Record<string, unknown>;
                const shinyCount = Number(e.shinyCount);
                if (Number.isFinite(shinyCount) && shinyCount > 0) {
                    shinyFromPokedex += shinyCount;
                } else if (e.hasShiny) {
                    shinyFromPokedex += 1;
                }
            }
        }
        const fallbackShiny = shinyFromPokedex > 0 ? shinyFromPokedex : shinyFromRoster;
        summary.shinyCount = formatSaveBootInteger(fallbackShiny);
    }

    return summary;
}

export function exportSaveSlotToFile(slotId: number) {
    const normalizedSlot = clampSaveSlotId(slotId);
    if (typeof localStorage === 'undefined') return { ok: false, error: bootText('errStorageUnavailable') };
    const raw = localStorage.getItem(getSaveSlotKey(normalizedSlot));
    if (!raw) return { ok: false, error: bootText('errNoSaveToExport') };

    const blob = new Blob([raw], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    const date = new Date();
    const dateStr = date.toISOString().split('T')[0];
    const timeStr = `${String(date.getHours()).padStart(2, '0')}h${String(date.getMinutes()).padStart(2, '0')}`;
    a.href = url;
    a.download = `pokeweb_save_slot${normalizedSlot}_${dateStr}_${timeStr}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    return { ok: true };
}

export function importSaveFileToSlot(slotId: number, onDone: (result: { ok: boolean; error?: string }) => void) {
    const normalizedSlot = clampSaveSlotId(slotId);
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.json';
    input.onchange = (e) => {
        const file = e?.target && (e.target as HTMLInputElement).files?.[0] ? (e.target as HTMLInputElement).files![0] : null;
        if (!file) {
            if (typeof onDone === 'function') onDone({ ok: false, error: bootText('errImportCancelled') });
            return;
        }

        const reader = new FileReader();
        reader.onload = (event) => {
            const content = fileReaderTextResult(event?.target?.result);
            try {
                const parsedData = parseSavePayload(content);
                if (!parsedData) throw new Error(bootText('errInvalidFile'));
                normalizeSpeciesNamesInSaveData(parsedData);
                repairCtItemsInSaveData(parsedData);
                repairSaveDataBeforeValidation(parsedData);
                const validationError = validateSaveData(null, parsedData);
                if (validationError) throw new Error(validationError);
                const serialized = buildSerializedSavePayload(parsedData);
                localStorage.setItem(getSaveSlotKey(normalizedSlot), serialized);
                localStorage.setItem(getSaveBackupSlotKey(normalizedSlot), serialized);
                syncSaveSlotMetaFromGameData(normalizedSlot, parsedData, null);
                if (typeof onDone === 'function') onDone({ ok: true });
            } catch (err) {
                const message = err instanceof Error ? err.message : bootText('errInvalidFile');
                if (typeof onDone === 'function') onDone({ ok: false, error: message });
            }
        };
        reader.onerror = () => {
            if (typeof onDone === 'function') onDone({ ok: false, error: bootText('errFileUnreadable') });
        };
        reader.readAsText(file);
    };
    input.click();
}

export function clearSaveSlotData(slotId: number, options: { preserveProfile?: boolean } = {}): { ok: boolean; error?: string } {
    const normalizedSlot = clampSaveSlotId(slotId);
    const preserveProfile = options && options.preserveProfile === true;
    if (typeof localStorage === 'undefined') return { ok: false, error: bootText('errStorageUnavailable') };

    const previousMeta = getSaveSlotMetaById(normalizedSlot);
    localStorage.removeItem(getSaveSlotKey(normalizedSlot));
    localStorage.removeItem(getSaveBackupSlotKey(normalizedSlot));
    invalidateParseSavePayloadCache();

    const state = readSaveMetaState();
    if (preserveProfile) {
        const profile = normalizePlayerProfileForSave({
            name: previousMeta.playerName || '',
            spriteId: previousMeta.spriteId
        });
        state.slots[normalizedSlot] = {
            ...createDefaultSaveSlotMeta(normalizedSlot),
            slotId: normalizedSlot,
            playerName: profile.name || '',
            spriteId: profile.spriteId
        };
    } else {
        state.slots[normalizedSlot] = createDefaultSaveSlotMeta(normalizedSlot);
    }
    writeSaveMetaState(state);
    clearPendingNewPlayerProfile();
    return { ok: true };
}

export function initSaveSlotBoot(onReadyToBootstrap: () => void) {
    migrateLegacySaveToSlotsIfNeeded();

    const modal = document.getElementById('saveSlotBootModal');
    const cardsHost = document.getElementById('saveSlotCards');
    const createPanel = document.getElementById('saveSlotCreatePanel');
    const createTitle = document.getElementById('saveSlotCreateTitle');
    const nameInput = document.getElementById('saveSlotNameInput') as HTMLInputElement | null;
    const spriteGrid = document.getElementById('saveSlotSpriteGrid');
    const createConfirm = document.getElementById('saveSlotCreateConfirm');
    const createCancel = document.getElementById('saveSlotCreateCancel');
    const errorBox = document.getElementById('saveSlotBootError');
    const languageHost = document.getElementById('saveSlotBootLanguage');

    if (!modal || !cardsHost || !createPanel || !nameInput || !spriteGrid || !createConfirm || !createCancel) {
        if (typeof onReadyToBootstrap === 'function') onReadyToBootstrap();
        return;
    }

    const state: { creatingSlotId: number | null; selectedSpriteId: string } = {
        creatingSlotId: null,
        selectedSpriteId: getDefaultPlayerSpriteIdForSave()
    };

    finishSaveSlotBootstrapImpl = () => {
        setSaveBootSlotControlsDisabled(false);
        setSaveBootLoadingMessage(false);
        modal.classList.remove('show');
        document.body.classList.remove('save-slot-boot-active');
    };

    const beginBootstrap = () => {
        beginSaveSlotBootstrap();
        const run = onReadyToBootstrap;
        if (typeof run !== 'function') return;
        const schedule =
            typeof requestAnimationFrame === 'function'
                ? (cb: () => void) => requestAnimationFrame(() => requestAnimationFrame(cb))
                : (cb: () => void) => setTimeout(cb, 0);
        schedule(run);
    };

    const setBootMessage = (message = '', isError = true) => {
        if (!errorBox) return;
        errorBox.textContent = message || '';
        errorBox.classList.toggle('success', !!message && !isError);
    };

    const renderSpriteGrid = () => {
        const profileCatalog = getPlayerSpriteCatalogForSave();
        spriteGrid.innerHTML = profileCatalog.map(sprite => {
            const isActive = sprite.id === state.selectedSpriteId;
            return `
                <button type="button" class="save-slot-sprite-choice${isActive ? ' active' : ''}" data-sprite-id="${escapeHtmlForSaveBoot(sprite.id)}" aria-label="${escapeHtmlForSaveBoot(sprite.label)}">
                    <img src="${escapeHtmlForSaveBoot(sprite.url)}" alt="${escapeHtmlForSaveBoot(sprite.label)}" loading="lazy" decoding="async">
                    <span>${escapeHtmlForSaveBoot(sprite.label)}</span>
                </button>
            `;
        }).join('');
    };

    const closeCreatePanel = () => {
        state.creatingSlotId = null;
        createPanel.classList.remove('show');
        cardsHost.classList.remove('hide');
        setBootMessage('');
    };

    const openCreatePanel = (slotMeta: SaveSlotMeta) => {
        state.creatingSlotId = slotMeta.slotId;
        state.selectedSpriteId = slotMeta.spriteId || getDefaultPlayerSpriteIdForSave();
        if (createTitle) createTitle.textContent = bootText('slotCreatePanelTitle', { id: slotMeta.slotId });
        nameInput.value = slotMeta.playerName || '';
        setBootMessage('');
        renderSpriteGrid();
        cardsHost.classList.add('hide');
        createPanel.classList.add('show');
        setTimeout(() => nameInput.focus(), 0);
    };

    const renderSlotCards = () => {
        const metas = listSaveSlotsMeta();
        const activeSlot = getActiveSaveSlot();
        cardsHost.innerHTML = metas.map(meta => {
            const spriteUrl = getPlayerSpriteUrlFromIdForSave(meta.spriteId);
            const isFilled = !!meta.hasData;
            const hasProfile = typeof meta.playerName === 'string' && meta.playerName.trim().length > 0;
            const displayName = meta.playerName || (isFilled ? getDefaultPlayerNameForSave() : bootText('slotEmpty'));
            const summary = isFilled ? getSaveSlotProgressSummary(meta.slotId) : null;
            const emptySlotText = hasProfile ? bootText('slotProfileReady') : bootText('slotNoProfile');
            return `
                <article class="save-slot-card${activeSlot === meta.slotId ? ' active-slot' : ''}" data-slot-id="${meta.slotId}">
                    <div class="save-slot-card-head">
                        <span class="save-slot-title">${escapeHtmlForSaveBoot(bootText('slotTitle', { id: meta.slotId }))}</span>
                        <span class="save-slot-badge ${isFilled ? 'filled' : 'empty'}">${escapeHtmlForSaveBoot(isFilled ? bootText('badgeFilled') : bootText('badgeEmpty'))}</span>
                    </div>
                    <div class="save-slot-player">
                        <img src="${escapeHtmlForSaveBoot(spriteUrl)}" alt="" class="save-slot-avatar" loading="lazy" decoding="async">
                        <div class="save-slot-player-meta">
                            <div class="save-slot-player-name">${escapeHtmlForSaveBoot(displayName)}</div>
                            <div class="save-slot-player-date">${isFilled ? escapeHtmlForSaveBoot(bootText('lastSession', { date: formatSaveSlotDate(meta.updatedAt) })) : escapeHtmlForSaveBoot(emptySlotText)}</div>
                        </div>
                    </div>
                    ${isFilled ? `
                    <div class="save-slot-progress-grid${summary && summary.corrupted ? ' is-corrupted' : ''}">
                        <div class="save-slot-progress-item">
                            <span class="save-slot-progress-key">${escapeHtmlForSaveBoot(bootText('statPlayTime'))}</span>
                            <span class="save-slot-progress-value">${escapeHtmlForSaveBoot(summary!.playTime)}</span>
                        </div>
                        <div class="save-slot-progress-item">
                            <span class="save-slot-progress-key">${escapeHtmlForSaveBoot(bootText('statZone'))}</span>
                            <span class="save-slot-progress-value">${escapeHtmlForSaveBoot(summary!.zone)}</span>
                        </div>
                        <div class="save-slot-progress-item">
                            <span class="save-slot-progress-key">${escapeHtmlForSaveBoot(bootText('statBadge'))}</span>
                            <span class="save-slot-progress-value">${escapeHtmlForSaveBoot(summary!.badgeCount)}</span>
                        </div>
                        <div class="save-slot-progress-item">
                            <span class="save-slot-progress-key">${escapeHtmlForSaveBoot(bootText('statGold'))}</span>
                            <span class="save-slot-progress-value">${escapeHtmlForSaveBoot(summary!.gold)}</span>
                        </div>
                        <div class="save-slot-progress-item">
                            <span class="save-slot-progress-key">${escapeHtmlForSaveBoot(bootText('statMaxLevel'))}</span>
                            <span class="save-slot-progress-value">${escapeHtmlForSaveBoot(summary!.maxLevel)}</span>
                        </div>
                        <div class="save-slot-progress-item">
                            <span class="save-slot-progress-key">${escapeHtmlForSaveBoot(bootText('statMaxPrestige'))}</span>
                            <span class="save-slot-progress-value">${escapeHtmlForSaveBoot(summary!.maxPrestige)}</span>
                        </div>
                        <div class="save-slot-progress-item">
                            <span class="save-slot-progress-key">${escapeHtmlForSaveBoot(bootText('statShinyCount'))}</span>
                            <span class="save-slot-progress-value">${escapeHtmlForSaveBoot(summary!.shinyCount)}</span>
                        </div>
                    </div>
                    ` : ''}
                    <button type="button" class="btn save-slot-action ${isFilled ? 'continue' : 'create'}" data-action="${isFilled ? 'continue' : 'create'}" data-action-stop data-slot-id="${meta.slotId}">
                        ${escapeHtmlForSaveBoot(isFilled ? bootText('actionContinue') : bootText('actionNew'))}
                    </button>
                    <div class="save-slot-tools">
                        <button type="button" class="save-slot-tool-btn" data-action="import" data-action-stop data-slot-id="${meta.slotId}">${escapeHtmlForSaveBoot(bootText('actionImport'))}</button>
                        <button type="button" class="save-slot-tool-btn" data-action="export" data-action-stop data-slot-id="${meta.slotId}" ${isFilled ? '' : 'disabled'}>${escapeHtmlForSaveBoot(bootText('actionExport'))}</button>
                        <button type="button" class="save-slot-tool-btn danger" data-action="delete-save" data-action-stop data-slot-id="${meta.slotId}" ${isFilled ? '' : 'disabled'}>${escapeHtmlForSaveBoot(bootText('actionDeleteSave'))}</button>
                        <button type="button" class="save-slot-tool-btn danger-hard" data-action="delete-profile" data-action-stop data-slot-id="${meta.slotId}" ${(isFilled || hasProfile) ? '' : 'disabled'}>${escapeHtmlForSaveBoot(bootText('actionDeleteProfile'))}</button>
                    </div>
                </article>
            `;
        }).join('');
    };

    const applyBootStaticLabels = () => {
        try {
            const titleSprite = document.querySelector('#saveSlotBootTitle img');
            if (titleSprite) titleSprite.setAttribute('alt', bootText('bootTitleAlt'));
            const subtitleEl = modal.querySelector('.save-slot-boot-subtitle');
            if (subtitleEl) subtitleEl.textContent = bootText('bootSubtitle');
            if (createTitle) {
                createTitle.textContent = state.creatingSlotId
                    ? bootText('slotCreatePanelTitle', { id: state.creatingSlotId })
                    : bootText('createNewTitle');
            }
            const pseudoLabelEl = createPanel.querySelector('.save-slot-input-label > span');
            if (pseudoLabelEl) pseudoLabelEl.textContent = bootText('pseudoLabel');
            nameInput.setAttribute('placeholder', bootText('pseudoPlaceholder'));
            if (createConfirm) createConfirm.textContent = bootText('confirmCreate');
            if (createCancel) createCancel.textContent = bootText('cancel');
            const desktopNoticeEl = document.getElementById('saveSlotBootDesktopNotice');
            if (desktopNoticeEl) desktopNoticeEl.textContent = bootText('desktopNotice');
            const disclaimerEl = document.getElementById('saveSlotBootDisclaimer');
            if (disclaimerEl) disclaimerEl.textContent = bootText('ipDisclaimer');
            const discordLink = document.getElementById('saveSlotDiscordLink');
            if (discordLink) {
                discordLink.textContent = bootText('linkDiscord');
                discordLink.setAttribute('href', SAVE_BOOT_DISCORD_URL);
            }
            const redditLink = document.getElementById('saveSlotRedditLink');
            if (redditLink) {
                redditLink.textContent = bootText('linkReddit');
                redditLink.setAttribute('href', SAVE_BOOT_REDDIT_URL);
            }
            const changelogEl = document.getElementById('saveSlotBootChangelog');
            const changelogTitleEl = document.getElementById('saveSlotBootChangelogTitle');
            if (changelogEl) changelogEl.setAttribute('aria-label', bootText('changelogAria'));
            if (changelogTitleEl) changelogTitleEl.textContent = bootText('changelogBody');
            const changelogDiscordLink = document.getElementById('saveSlotBootChangelogDiscordLink');
            if (changelogDiscordLink) {
                changelogDiscordLink.textContent = bootText('linkDiscord');
                changelogDiscordLink.setAttribute('href', SAVE_BOOT_DISCORD_URL);
            }
            const activeLang = getSaveBootLanguage();
            if (languageHost) {
                languageHost.setAttribute('aria-label', bootText('languageAria'));
                languageHost.querySelectorAll<HTMLButtonElement>('.save-slot-lang-flag[data-lang]').forEach((btn) => {
                    const lang = btn.getAttribute('data-lang') === 'en' ? 'en' : 'fr';
                    const isActive = lang === activeLang;
                    btn.classList.toggle('active', isActive);
                    btn.setAttribute('aria-pressed', isActive ? 'true' : 'false');
                    btn.setAttribute('aria-label', bootText(lang === 'en' ? 'langEnAria' : 'langFrAria'));
                    btn.setAttribute('title', bootText(lang === 'en' ? 'langEnAria' : 'langFrAria'));
                });
            }
            document.documentElement.lang = activeLang;
        } catch (_) { /* noop : DOM optionnel */ }
    };

    const applyBootLanguage = () => {
        applyBootStaticLabels();
        renderSlotCards();
    };

    if (languageHost) {
        languageHost.addEventListener('click', (event) => {
            const btn = (event.target as HTMLElement).closest<HTMLButtonElement>('button.save-slot-lang-flag[data-lang]');
            if (!btn) return;
            const lang = btn.getAttribute('data-lang') === 'en' ? 'en' : 'fr';
            if (getSaveBootLanguage() === lang) return;
            setSaveBootLanguage(lang);
            applyBootLanguage();
        });
    }

    cardsHost.onclick = (event) => {
        const btn = (event.target as HTMLElement).closest('button[data-action][data-slot-id]');
        if (!btn) return;
        const slotId = clampSaveSlotId(btn.getAttribute('data-slot-id'));
        const action = btn.getAttribute('data-action');
        if (action === 'continue') {
            setActiveSaveSlot(slotId);
            clearPendingNewPlayerProfile();
            beginBootstrap();
            return;
        }
        if (action === 'create') {
            const slotMeta = getSaveSlotMetaById(slotId);
            openCreatePanel(slotMeta);
            return;
        }
        if (action === 'export') {
            const result = exportSaveSlotToFile(slotId);
            setBootMessage(result.ok ? bootText('msgExported', { id: slotId }) : result.error, !result.ok);
            return;
        }
        if (action === 'delete-save') {
            const currentMeta = getSaveSlotMetaById(slotId);
            if (!currentMeta.hasData) {
                setBootMessage(bootText('msgSlotEmpty', { id: slotId }), true);
                return;
            }
            const confirmed = window.confirm(bootText('confirmDeleteSave', { id: slotId }));
            if (!confirmed) return;
            const result = clearSaveSlotData(slotId, { preserveProfile: true });
            setBootMessage(result.ok ? bootText('msgSaveDeleted', { id: slotId }) : result.error, !result.ok);
            renderSlotCards();
            return;
        }
        if (action === 'delete-profile') {
            const currentMeta = getSaveSlotMetaById(slotId);
            const hasProfile = typeof currentMeta.playerName === 'string' && currentMeta.playerName.trim().length > 0;
            if (!currentMeta.hasData && !hasProfile) {
                setBootMessage(bootText('msgSlotAlreadyEmpty', { id: slotId }), true);
                return;
            }
            const confirmed = window.confirm(bootText('confirmDeleteProfile', { id: slotId }));
            if (!confirmed) return;
            const result = clearSaveSlotData(slotId, { preserveProfile: false });
            setBootMessage(result.ok ? bootText('msgProfileDeleted', { id: slotId }) : result.error, !result.ok);
            renderSlotCards();
            return;
        }
        if (action === 'import') {
            const currentMeta = getSaveSlotMetaById(slotId);
            if (currentMeta.hasData) {
                const confirmed = window.confirm(bootText('confirmReplaceImport', { id: slotId }));
                if (!confirmed) return;
            }
            importSaveFileToSlot(slotId, (result) => {
                setBootMessage(result.ok ? bootText('msgImported', { id: slotId }) : result.error, !result.ok);
                renderSlotCards();
            });
        }
    };

    spriteGrid.onclick = (event) => {
        const btn = (event.target as HTMLElement).closest('button[data-sprite-id]');
        if (!btn) return;
        state.selectedSpriteId = btn.getAttribute('data-sprite-id') || getDefaultPlayerSpriteIdForSave();
        renderSpriteGrid();
    };

    createConfirm.onclick = () => {
        if (!state.creatingSlotId) return;
        const safeName = sanitizePlayerNameForSave(nameInput.value || '');
        if (!safeName || safeName.trim().length === 0) {
            setBootMessage(bootText('errPseudoRequired'), true);
            return;
        }

        const playerProfile = normalizePlayerProfileForSave({
            name: safeName,
            spriteId: state.selectedSpriteId
        });
        setPendingNewPlayerProfile(playerProfile);
        const slotId = setActiveSaveSlot(state.creatingSlotId);

        const stateMeta = readSaveMetaState();
        const previous = normalizeSaveSlotMeta(slotId, stateMeta.slots[slotId]);
        const now = Date.now();
        stateMeta.slots[slotId] = {
            ...previous,
            slotId,
            hasData: false,
            playerName: playerProfile.name,
            spriteId: playerProfile.spriteId,
            updatedAt: now,
            createdAt: previous.createdAt > 0 ? previous.createdAt : now
        };
        writeSaveMetaState(stateMeta);
        setBootMessage('');

        beginBootstrap();
    };

    createCancel.onclick = closeCreatePanel;
    nameInput.addEventListener('keydown', (event) => {
        if (event.key === 'Enter') {
            event.preventDefault();
            createConfirm.click();
        }
    });

    document.body.classList.add('save-slot-boot-active');
    modal.classList.add('show');
    closeCreatePanel();
    applyBootLanguage();
}

