/**
 * Zone combat: restore team slot 0 after a forced KO relay (or a punctual right-click lead)
 * when all auto-switch toggles are off.
 */

import type { GameRuntime } from '../types/game.js';
import type { CreatureData } from '../types/creature.js';
import { arrayAt } from './safeAccess.ts';
import { resolvePreferredActiveIndex } from './autoFightAdvanced.ts';

export function shouldRestorePreferredActiveAfterRelay(game: GameRuntime): boolean {
    if (game.unlockedFeatures?.autoFightAdvanced
        && game.autoFightAdvancedOptions?.respectPreferredActive) {
        return true;
    }
    return !game.autoSwitchAdvantage
        && !game.autoSwitchDisadvantage
        && !game.autoSwitchStamina
        && !game.autoSwitchAdvanced;
}

function isCreatureAlive(creature: CreatureData | null | undefined): boolean {
    if (!creature) return false;
    if (typeof creature.isAlive === 'function') return creature.isAlive();
    return (creature.currentHp ?? 0) > 0;
}

/**
 * After a zone combat win, switch back to team slot 0.
 * Does not call setActiveCreature (no combat logs / HP transfer outside fighting).
 */
export function restoreCombatPreferredActiveIfNeeded(game: GameRuntime): boolean {
    if (!shouldRestorePreferredActiveAfterRelay(game)) return false;
    if (!Array.isArray(game.playerTeam) || game.playerTeam.length === 0) return false;

    const idx = resolvePreferredActiveIndex(game);
    if (idx >= game.playerTeam.length) return false;

    const preferred = arrayAt(game.playerTeam, idx);
    if (!isCreatureAlive(preferred)) return false;

    if (game.activeCreatureIndex === idx && game.currentPlayerCreature === preferred) {
        return false;
    }

    game.activeCreatureIndex = idx;
    game.currentPlayerCreature = preferred ?? null;
    return true;
}
