/**
 * @file src/lib/pickRoamerSpecies.ts
 * Choix d'espèce roamer avec boost radar œufs (même multiplicateur que les œufs).
 */

import { pickWeightedIndex } from './pickWeightedIndex.ts';

export function pickRoamerSpecies(
    pool: string[],
    radarTargets: string[],
    radarMult: number,
    rng: () => number = Math.random,
): string | null {
    if (!Array.isArray(pool) || pool.length === 0) return null;

    const targets = Array.isArray(radarTargets) ? radarTargets : [];
    const mult = Number.isFinite(radarMult) && radarMult > 0 ? radarMult : 1;
    const useRadar = targets.length > 0 && mult > 1;

    if (!useRadar) {
        const idx = Math.floor(rng() * pool.length);
        return pool[idx] ?? null;
    }

    const weights = pool.map((n) => (targets.includes(n) ? mult : 1));
    const idx = pickWeightedIndex(weights, rng);
    return pool[idx] ?? null;
}
