export function getLocalizedMoveDescriptionPlain(moveName: string, lang?: string): string | null {
  const resolved = resolveMoveName(moveName);
  if (!resolved) return null;
  const normalizedLang = String(lang || 'fr').toLowerCase().startsWith('en') ? 'en' : 'fr';
  const overrides = MANUAL_MOVE_DESCRIPTION_OVERRIDES as Record<string, { fr: string; en: string }>;
  const manual = overrides[resolved];
  if (manual) return normalizedLang === 'en' ? manual.en : manual.fr;
  const map = MOVE_DESCRIPTION_I18N[normalizedLang] as Record<string, string>;
  return map[resolved] || null;
}
