/**
 * Debug-only QA grants: full item / offensive CT pools with structured results.
 * Attached to game.qaGrant when localStorage poketime:debug=1.
 */

import { ALL_ITEMS } from '../../constants/balance/shopAndAggregation.ts';
import { HELD_ITEMS } from '../../constants/balance/towerAndItems.ts';
import { ALLOWED_CT_ITEM_KEYS, isAllowedCtItemKey, isInvalidCtItemKey } from '../../constants/validCtItems.ts';
import type { GameRuntime } from '../types/game.js';

export type QaSetFeticheLevelFailReason = 'no_fetiche' | 'no_species' | 'invalid_level' | 'invalid_xp_pct';

export interface QaSetFeticheLevelResult {
  ok: boolean;
  level?: number;
  xp?: number;
  xpToNext?: number;
  xpPct?: number;
  displaySpeciesKey?: string | null;
  nextEvolutionAtLevel?: number | null;
  reason?: QaSetFeticheLevelFailReason;
}

export type QaGrantFailReason =
  | 'unknown_item'
  | 'invalid_ct'
  | 'non_offensive_ct'
  | 'zero_qty'
  | 'add_item_noop';

export interface QaGrantItemResult {
  ok: boolean;
  key: string;
  qty: number;
  before: number;
  after: number;
  reason?: QaGrantFailReason;
}

export interface QaGrantRandomResult {
  granted: Record<string, number>;
  skipped: number;
  poolSize: number;
}

export type { QaSetFeticheLevelResult } from './feticheLogic.ts';

export interface QaItemPoolOptions {
  excludeCt?: boolean;
  excludeHeld?: boolean;
  excludeKeyItems?: boolean;
}

export interface QaGrantFacade {
  listOffensiveCtPool(): string[];
  listItemPool(opts?: QaItemPoolOptions): string[];
  grantItem(key: string, qty?: number, updateUI?: boolean): QaGrantItemResult;
  grantRandomCt(count?: number, updateUI?: boolean): QaGrantRandomResult;
  grantRandomItems(count?: number, opts?: QaItemPoolOptions & { updateUI?: boolean }): QaGrantRandomResult;
  setFeticheLevel(level?: number, xpPct?: number): QaSetFeticheLevelResult;
}

type QaGame = GameRuntime & {
  items?: Record<string, number>;
  addItem?: (key: string, qty?: number, updateUI?: boolean) => void;
  updateItemsDisplay?: () => void;
  isDamagingCtItemKey?: (key: string) => boolean;
};

function itemCount(game: QaGame, key: string): number {
  return Math.max(0, Math.floor(Number(game.items?.[key]) || 0));
}

function validateGrantKey(game: QaGame, key: string): QaGrantFailReason | null {
  if (typeof key !== 'string' || !key) return 'unknown_item';

  const inCatalog = !!(ALL_ITEMS as Record<string, unknown>)[key];
  const isCt = key.startsWith('ct_');

  if (!inCatalog && !isCt) return 'unknown_item';

  if (isCt) {
    if (!isAllowedCtItemKey(key)) return 'invalid_ct';
    if (typeof game.isDamagingCtItemKey === 'function' && !game.isDamagingCtItemKey(key)) {
      return 'non_offensive_ct';
    }
  }

  return null;
}

/** Full offensive CT pool: allowlist ∩ isDamagingCtItemKey (broader than SHOP_ITEMS-only). */
export function listQaOffensiveCtKeys(game: QaGame): string[] {
  const out: string[] = [];
  for (const key of ALLOWED_CT_ITEM_KEYS) {
    if (typeof game.isDamagingCtItemKey === 'function' && !game.isDamagingCtItemKey(key)) continue;
    out.push(key);
  }
  return out.sort();
}

/** All grantable catalog keys from ALL_ITEMS with optional filters. */
export function listQaItemKeys(opts: QaItemPoolOptions = {}): string[] {
  const heldSet = opts.excludeHeld ? new Set(Object.keys(HELD_ITEMS as Record<string, unknown>)) : null;

  return Object.keys(ALL_ITEMS as Record<string, Record<string, unknown>>)
    .filter((key) => {
      const def = (ALL_ITEMS as Record<string, Record<string, unknown>>)[key];
      if (!def) return false;
      if (opts.excludeCt && key.startsWith('ct_')) return false;
      if (heldSet?.has(key)) return false;
      if (opts.excludeKeyItems && def.type === 'key_item') return false;
      return true;
    })
    .sort();
}

export function grantItemForQa(
  game: QaGame,
  key: string,
  quantity: number = 1,
  updateUI: boolean = false,
): QaGrantItemResult {
  const qty = Math.max(0, Math.floor(Number(quantity) || 0));
  const before = itemCount(game, key);

  if (qty <= 0) {
    return { ok: false, key, qty, before, after: before, reason: 'zero_qty' };
  }

  const validationError = validateGrantKey(game, key);
  if (validationError) {
    return { ok: false, key, qty, before, after: before, reason: validationError };
  }

  if (typeof game.addItem !== 'function') {
    return { ok: false, key, qty, before, after: before, reason: 'add_item_noop' };
  }

  game.addItem(key, qty, updateUI);
  const after = itemCount(game, key);

  if (after <= before && key !== 'talent_reroll' && key !== 'talent_choice') {
    return { ok: false, key, qty, before, after, reason: 'add_item_noop' };
  }

  return { ok: true, key, qty, before, after };
}

function pickRandomFromPool(pool: string[]): string | null {
  if (pool.length === 0) return null;
  return pool[Math.floor(Math.random() * pool.length)] ?? null;
}

function aggregateGrants(results: QaGrantItemResult[]): QaGrantRandomResult {
  const granted: Record<string, number> = {};
  let skipped = 0;
  for (const r of results) {
    if (!r.ok) {
      skipped++;
      continue;
    }
    granted[r.key] = (granted[r.key] || 0) + r.qty;
  }
  return { granted, skipped, poolSize: 0 };
}

export function grantRandomCtForQa(
  game: QaGame,
  count: number = 1,
  updateUI: boolean = false,
): QaGrantRandomResult {
  const pool = listQaOffensiveCtKeys(game);
  const n = Math.min(Math.max(1, Math.floor(Number(count) || 0)), 100);
  const results: QaGrantItemResult[] = [];

  for (let i = 0; i < n; i++) {
    const key = pickRandomFromPool(pool);
    if (!key) break;
    results.push(grantItemForQa(game, key, 1, false));
  }

  if (updateUI && typeof game.updateItemsDisplay === 'function') {
    game.updateItemsDisplay();
  }

  const out = aggregateGrants(results);
  out.poolSize = pool.length;
  return out;
}

export function grantRandomItemsForQa(
  game: QaGame,
  count: number = 1,
  opts: QaItemPoolOptions & { updateUI?: boolean } = {},
): QaGrantRandomResult {
  const { updateUI = false, ...poolOpts } = opts;
  const pool = listQaItemKeys(poolOpts);
  const n = Math.min(Math.max(1, Math.floor(Number(count) || 0)), 100);
  const results: QaGrantItemResult[] = [];

  for (let i = 0; i < n; i++) {
    const key = pickRandomFromPool(pool);
    if (!key) break;
    results.push(grantItemForQa(game, key, 1, false));
  }

  if (updateUI && typeof game.updateItemsDisplay === 'function') {
    game.updateItemsDisplay();
  }

  const out = aggregateGrants(results);
  out.poolSize = pool.length;
  return out;
}

export function createQaGrantFacade(
  game: GameRuntime,
  extensions?: {
    setFeticheLevel?: (level?: number, xpPct?: number) => QaSetFeticheLevelResult;
  },
): QaGrantFacade {
  const g = game as QaGame;
  return {
    listOffensiveCtPool: () => listQaOffensiveCtKeys(g),
    listItemPool: (opts) => listQaItemKeys(opts),
    grantItem: (key, qty, updateUI) => grantItemForQa(g, key, qty, updateUI),
    grantRandomCt: (count, updateUI) => grantRandomCtForQa(g, count, updateUI),
    grantRandomItems: (count, opts) => grantRandomItemsForQa(g, count, opts),
    setFeticheLevel: extensions?.setFeticheLevel ?? (() => ({ ok: false, reason: 'no_fetiche' })),
  };
}

export function attachQaGrantToGame(
  game: GameRuntime,
  extensions?: Parameters<typeof createQaGrantFacade>[1],
): QaGrantFacade {
  const facade = createQaGrantFacade(game, extensions);
  (game as GameRuntime & { qaGrant?: QaGrantFacade }).qaGrant = facade;
  return facade;
}

/** @internal Vitest — invalid CT must never appear in QA offensive pool */
export function isQaOffensiveCtPoolKey(key: string, game: QaGame): boolean {
  if (isInvalidCtItemKey(key)) return false;
  return listQaOffensiveCtKeys(game).includes(key);
}
