/**
 * @file src/lib/miltankFarmClaimFeedback.ts
 * Visual feedback when collecting Moomoo Milk from the farm.
 */

import { getItemIconPath } from '../ui/utils.ts';
import { showFloatingText } from '../ui/floatingText.ts';
import { prefersReducedMotion } from '../ui/prestigeAnimation.ts';

const POP_MS = 450;
const PRESS_MS = 280;
const POP_CLASS = 'milk-claim-pop';
const PRESS_CLASS = 'milk-claim-pressed';

const MILK_ICON_URL = getItemIconPath('moomoo_milk')
    || 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/moomoo-milk.png';

export interface MilkClaimFeedbackOptions {
    qty: number;
    pastureUid?: string;
    sourceEl?: HTMLElement | null;
}

/** @internal Vitest */
export function resolveMilkClaimFeedbackTarget(
    pastureUid?: string,
    sourceEl?: HTMLElement | null,
): HTMLElement | null {
    const fromPasture = sourceEl?.closest('.miltank-pasture-sprite-btn');
    if (fromPasture instanceof HTMLElement) return fromPasture;

    const modalShell = sourceEl?.closest('.miltank-farm-modal-shell');
    const fromModal = modalShell?.querySelector('.miltank-farm-sprite-wrap');
    if (fromModal instanceof HTMLElement) return fromModal;

    const fromHud = sourceEl?.closest('.miltank-farm-hud-bar');
    if (fromHud instanceof HTMLElement) return fromHud;

    if (pastureUid) {
        const sel = `[data-action="openMiltankFarmModalForPasture"][data-arg="${CSS.escape(pastureUid)}"]`;
        const spriteBtn = document.querySelector(sel);
        if (spriteBtn instanceof HTMLElement) return spriteBtn;
    }

    return sourceEl ?? null;
}

function flashClaimButton(sourceEl: HTMLElement | null | undefined): void {
    const btn = sourceEl?.closest('button');
    if (!(btn instanceof HTMLButtonElement) || btn.disabled) return;
    btn.classList.remove(PRESS_CLASS);
    void btn.offsetWidth;
    btn.classList.add(PRESS_CLASS);
    window.setTimeout(() => btn.classList.remove(PRESS_CLASS), PRESS_MS);
}

function popClaimTarget(target: HTMLElement): void {
    target.classList.remove(POP_CLASS);
    void target.offsetWidth;
    target.classList.add(POP_CLASS);
    window.setTimeout(() => target.classList.remove(POP_CLASS), POP_MS);
}

function showMilkFloatingText(target: HTMLElement, qty: number): void {
    const safeQty = Math.max(1, Math.floor(Number(qty) || 0));
    showFloatingText({
        text: `+${safeQty}`,
        html: `<span class="floating-milk-reward">+${safeQty} <img class="floating-milk-reward-icon" src="${MILK_ICON_URL}" alt="" width="20" height="20" /></span>`,
    }, target, 'ft-milk-claim');
}

export function playMilkClaimFeedback(opts: MilkClaimFeedbackOptions): void {
    if (opts.qty <= 0) return;

    const target = resolveMilkClaimFeedbackTarget(opts.pastureUid, opts.sourceEl);
    if (!target) return;

    showMilkFloatingText(target, opts.qty);

    if (!prefersReducedMotion()) {
        popClaimTarget(target);
        flashClaimButton(opts.sourceEl);
    }
}
